// Generates the C header of the ops, the Swift layer over it, the C++ header of the Highway ops
// they are tested against, the tests that compare the two, and the functions that put both of
// them into machine code to be compared, from the op list below.
//
// Run from the repository root:
//
//     swift utils/GenerateVectorizationOps.swift

import Foundation

enum Category: Hashable {
    case unsignedInteger
    case signedInteger
    case float
    case float16
    case bfloat16
}

struct Element {
    let suffix: String
    let cType: String
    let swiftType: String
    let category: Category
    let bits: Int
    var width = 16

    var tag: String { "Tag\(suffix)" }
    var vector: String { "Vector\(suffix)" }
    var mask: String { "Mask\(suffix)" }
    var outVector: String { "OutVector\(suffix)" }
    var namespace: String { "SIMD\(swiftType)" }
    var laneCount: Int { width / (bits / 8) }
    var blockLaneCount: Int { 16 / (bits / 8) }
    var cSuffix: String { suffix.lowercased() }
    var cVector: String { "cvectorization_ops_vector_\(cSuffix)" }
    var cBlock: String { "cvectorization_ops_block_\(cSuffix)" }
    var cMask: String { "cvectorization_ops_mask_\(cSuffix)" }
    var cRawVector: String { "cvectorization_ops_raw_vector_\(cSuffix)" }
    var cRawMask: String { "cvectorization_ops_raw_mask_\(cSuffix)" }
    var cToRawVector: String { "cvectorization_ops_to_raw_vector_\(cSuffix)" }
    var cFromRawVector: String { "cvectorization_ops_from_raw_vector_\(cSuffix)" }
    var cToRawMask: String { "cvectorization_ops_to_raw_mask_\(cSuffix)" }
    var cFromRawMask: String { "cvectorization_ops_from_raw_mask_\(cSuffix)" }
    var hasOpaqueVector: Bool { category != .float && category != .float16 }
    var isHalfPrecision: Bool { category == .float16 || category == .bfloat16 }
    var cScalar: String { isHalfPrecision ? "uint16_t" : cType }
    var cPointee: String { isHalfPrecision ? "void" : cType }
    var hwyType: String {
        switch category {
        case .float16: return "hwy::float16_t"
        case .bfloat16: return "hwy::bfloat16_t"
        default: return cType
        }
    }

    var compilationCondition: String? {
        category == .float16
            ? "!((os(macOS) || targetEnvironment(macCatalyst)) && arch(x86_64))" : nil
    }

    var swiftAvailability: String? {
        category == .float16 ? "@available(SwiftStdlib 5.3, *)" : nil
    }

    func hwyScalar(_ expression: String) -> String {
        isHalfPrecision ? "hwy::BitCastScalar<\(hwyType)>(\(expression))" : expression
    }

    func hwyPointer(_ expression: String, isConst: Bool) -> String {
        isHalfPrecision
            ? "reinterpret_cast<\(isConst ? "const " : "")\(hwyType)*>(\(expression))" : expression
    }

    func swiftLane(fromSimd expression: String) -> String {
        category == .bfloat16 ? "BFloat16(bitPattern: \(expression))" : expression
    }

    var swiftZeroLane: String { isHalfPrecision ? "\(swiftType)(bitPattern: 0)" : "0" }

    func swiftScalarArgument(_ expression: String) -> String {
        isHalfPrecision ? "\(expression).bitPattern" : expression
    }

    func swiftScalarResult(_ expression: String) -> String {
        isHalfPrecision ? "Lane(bitPattern: \(expression))" : expression
    }
    var cUnsignedLane: String { "uint\(bits)_t" }
    var cUnsignedVector: String { "cvectorization_ops_vector_u\(bits)" }
    var cMaskLane: String { "int\(bits)_t" }
    var swiftMaskLane: String { "Int\(bits)" }

    var cTupleVector: String { "cvectorization_ops_tuple_vector_\(cSuffix)" }

    func cTuple(_ count: Int) -> String { "cvectorization_ops_tuple\(count)_\(cSuffix)" }

    func at(width: Int) -> Element {
        var scaled = self
        scaled.width = width
        return scaled
    }

    func supports(_ shape: Shape) -> Bool {
        switch shape {
        case .full, .half, .block: return true
        case .quarter: return bits <= 16
        case .eighth: return bits == 8
        }
    }

    func bytes(of shape: Shape) -> Int {
        guard let fraction = shape.fraction else { return 16 }
        return width / fraction
    }

    func laneCount(of shape: Shape) -> Int { bytes(of: shape) / (bits / 8) }

    func cVector(of shape: Shape) -> String { "cvectorization_ops_\(shape.cName)_\(cSuffix)" }
    func cRawVector(of shape: Shape) -> String {
        "cvectorization_ops_raw_\(shape.cName)_\(cSuffix)"
    }
    func cToRawVector(of shape: Shape) -> String {
        "cvectorization_ops_to_raw_\(shape.cName)_\(cSuffix)"
    }
    func cFromRawVector(of shape: Shape) -> String {
        "cvectorization_ops_from_raw_\(shape.cName)_\(cSuffix)"
    }
    func tag(of shape: Shape) -> String { "\(shape.prefix)\(tag)" }
    func vector(of shape: Shape) -> String { "\(shape.prefix)\(vector)" }

    func cMask(of shape: Shape) -> String { "cvectorization_ops_\(shape.cMaskName)_\(cSuffix)" }
    func cRawMask(of shape: Shape) -> String {
        "cvectorization_ops_raw_\(shape.cMaskName)_\(cSuffix)"
    }
    func cToRawMask(of shape: Shape) -> String {
        "cvectorization_ops_to_raw_\(shape.cMaskName)_\(cSuffix)"
    }
    func cFromRawMask(of shape: Shape) -> String {
        "cvectorization_ops_from_raw_\(shape.cMaskName)_\(cSuffix)"
    }
    func mask(of shape: Shape) -> String { "\(shape.prefix)\(mask)" }
}

enum Shape: CaseIterable {
    case full
    case half
    case quarter
    case eighth
    case block

    var fraction: Int? {
        switch self {
        case .full: return 1
        case .half: return 2
        case .quarter: return 4
        case .eighth: return 8
        case .block: return nil
        }
    }

    var cName: String {
        switch self {
        case .full: return "vector"
        case .half: return "half_vector"
        case .quarter: return "quarter_vector"
        case .eighth: return "eighth_vector"
        case .block: return "block"
        }
    }

    var prefix: String {
        switch self {
        case .full: return ""
        case .half: return "Half"
        case .quarter: return "Quarter"
        case .eighth: return "Eighth"
        case .block: return "Block"
        }
    }

    var swiftVector: String { "\(prefix)Vector" }

    var hasMask: Bool { self != .block }

    var isPartial: Bool { fraction.map { $0 > 1 } ?? false }

    var cMaskName: String {
        switch self {
        case .full: return "mask"
        case .half: return "half_mask"
        case .quarter: return "quarter_mask"
        case .eighth: return "eighth_mask"
        case .block: fatalError("A block has no mask")
        }
    }

    var swiftMask: String { "\(prefix)Mask" }

    var spanExtent: SpanExtent? {
        switch self {
        case .full: return nil
        case .half: return .halfVector
        case .quarter: return .quarterVector
        case .eighth: return .eighthVector
        case .block: return .block
        }
    }

    var applies: Applies {
        switch self {
        case .full, .half, .block: return .all
        case .quarter: return .all(bits: [8, 16])
        case .eighth: return .all(bits: [8])
        }
    }

    func conversion(_ name: String) -> String {
        self == .full ? name : "\(prefix.lowercased())\(uppercasedFirst(name))"
    }
}

let elements: [Element] = [
    Element(
        suffix: "U8",
        cType: "uint8_t",
        swiftType: "UInt8",
        category: .unsignedInteger,
        bits: 8
    ),
    Element(
        suffix: "U16",
        cType: "uint16_t",
        swiftType: "UInt16",
        category: .unsignedInteger,
        bits: 16
    ),
    Element(
        suffix: "U32",
        cType: "uint32_t",
        swiftType: "UInt32",
        category: .unsignedInteger,
        bits: 32
    ),
    Element(
        suffix: "U64",
        cType: "uint64_t",
        swiftType: "UInt64",
        category: .unsignedInteger,
        bits: 64
    ),
    Element(suffix: "I8", cType: "int8_t", swiftType: "Int8", category: .signedInteger, bits: 8),
    Element(
        suffix: "I16",
        cType: "int16_t",
        swiftType: "Int16",
        category: .signedInteger,
        bits: 16
    ),
    Element(
        suffix: "I32",
        cType: "int32_t",
        swiftType: "Int32",
        category: .signedInteger,
        bits: 32
    ),
    Element(
        suffix: "I64",
        cType: "int64_t",
        swiftType: "Int64",
        category: .signedInteger,
        bits: 64
    ),
    Element(suffix: "F32", cType: "float", swiftType: "Float", category: .float, bits: 32),
    Element(suffix: "F64", cType: "double", swiftType: "Double", category: .float, bits: 64),
    Element(suffix: "F16", cType: "__fp16", swiftType: "Float16", category: .float16, bits: 16),
    Element(
        suffix: "BF16",
        cType: "uint16_t",
        swiftType: "BFloat16",
        category: .bfloat16,
        bits: 16
    ),
]

let classicElements = elements.filter { !$0.isHalfPrecision }

struct Applies {
    var categories: Set<Category>
    var bits: Set<Int>?
    var suffixes: Set<String>?
    var additional: Set<String> = []

    func matches(_ element: Element) -> Bool {
        if additional.contains(element.suffix) { return true }
        if let suffixes { return suffixes.contains(element.suffix) }
        guard categories.contains(element.category) else { return false }
        guard let bits else { return true }
        return bits.contains(element.bits)
    }

    static let all = Applies(categories: [.unsignedInteger, .signedInteger, .float], bits: nil)
    static let integer = Applies(categories: [.unsignedInteger, .signedInteger], bits: nil)
    static let unsigned = Applies(categories: [.unsignedInteger], bits: nil)
    static let signed = Applies(categories: [.signedInteger], bits: nil)
    static let float = Applies(categories: [.float], bits: nil)
    static let signedOrFloat = Applies(categories: [.signedInteger, .float], bits: nil)

    static func integer(bits: Set<Int>) -> Applies {
        Applies(categories: [.unsignedInteger, .signedInteger], bits: bits)
    }
    static func signed(bits: Set<Int>) -> Applies {
        Applies(categories: [.signedInteger], bits: bits)
    }
    static func unsigned(bits: Set<Int>) -> Applies {
        Applies(categories: [.unsignedInteger], bits: bits)
    }
    static func all(bits: Set<Int>) -> Applies {
        Applies(categories: [.unsignedInteger, .signedInteger, .float], bits: bits)
    }
    static func allAndFloat16(bits: Set<Int>) -> Applies {
        Applies(
            categories: [.unsignedInteger, .signedInteger, .float, .float16],
            bits: bits
        )
    }
    static func results(_ elements: [Element]) -> Applies {
        Applies(categories: [], bits: nil, suffixes: Set(elements.map(\.suffix)))
    }

    func including(_ elements: [Element]) -> Applies {
        var extended = self
        extended.additional.formUnion(elements.map(\.suffix))
        return extended
    }
}

// A `tag` is not a parameter of the generated functions; it marks where Highway wants the tag
// in its own argument list.
enum Parameter: Equatable {
    case tag
    case vector
    case indices
    case laneIndices
    case lookupIndices
    case indexVector
    case mask
    case lane
    case insertedLane
    case laneIndex
    case tuple(Int)
    case tupleIndex
    case constLanePointer
    case lanePointer
    case constBytePointer
    case bytePointer
    case count
    case shiftAmount
    case shiftCounts
    case laneAmount
    case flag
    case maskBits
    case outVector
    case fillVector
    case fillLane
    case whereMask
    case otherwiseVector
    case roundConstant
    case immediate
    case constBitsPointer
    case constIndexPointer
    case narrowLanePointer
    case pointerIndices
    case pointerOffsets
    case sourceTag
    case sourceVector
    case signedSourceVector
    case sourceMask
    case narrowTag(Shape)
    case narrowVector(Shape)
    case sourceNarrowTag(Shape)
    case sourceNarrowVector(Shape)
    case narrowMask(Shape)
    case sourceNarrowMask(Shape)

    /// The label of a parameter that only some overloads of an op take, and its rank among such
    /// parameters. Highway takes them first, as in `SlideUpLanesOr(lo, d, hi, amt)`, while Swift
    /// declares them after the ordinary ones, the lowest rank first.
    var overloading: (label: String, rank: Int)? {
        switch self {
        case .fillVector, .fillLane: return ("fillingWith", 1)
        case .shiftCounts: return ("by", 0)
        case .whereMask: return ("where", 1)
        case .otherwiseVector: return ("otherwise", 2)
        default: return nil
        }
    }

    var isLaneIndices: Bool {
        self == .laneIndices || self == .lookupIndices || self == .indexVector
    }

    var isSourced: Bool {
        switch self {
        case .sourceTag, .sourceVector, .signedSourceVector, .sourceMask, .sourceNarrowTag,
            .sourceNarrowVector, .sourceNarrowMask:
            return true
        default: return false
        }
    }

    var isTag: Bool {
        switch self {
        case .tag, .sourceTag, .narrowTag, .sourceNarrowTag: return true
        default: return false
        }
    }

    var isMask: Bool {
        switch self {
        case .mask, .sourceMask, .narrowMask, .sourceNarrowMask: return true
        default: return false
        }
    }

    var shape: Shape {
        switch self {
        case .narrowTag(let shape), .narrowVector(let shape), .sourceNarrowTag(let shape),
            .sourceNarrowVector(let shape), .narrowMask(let shape), .sourceNarrowMask(let shape):
            return shape
        default: return .full
        }
    }

    var isConstPointer: Bool {
        self == .constLanePointer || self == .constBytePointer || self == .constBitsPointer
            || self == .constIndexPointer
    }

    var isMutablePointer: Bool {
        self == .lanePointer || self == .bytePointer || self == .narrowLanePointer
    }

    var isPointer: Bool {
        isConstPointer || isMutablePointer
    }

    var isBytePointer: Bool {
        self == .constBytePointer || self == .bytePointer || self == .constBitsPointer
    }

    var isPointerIndices: Bool {
        self == .pointerIndices || self == .pointerOffsets
    }

    /// Where Swift declares a parameter among the others, the lowest rank first. Highway takes a
    /// lookup's table before its indices, while Swift takes the indices first.
    var swiftRank: Int {
        self == .lookupIndices ? -1 : overloading?.rank ?? 0
    }
}

enum UnorderedNaNs {
    case perLane
    case multiplyAdd
    case negatedMultiplicand
    case negatedAddend
    case alternatingAddend
    case alternatingNegatedAddend
    case acrossLanes
    case adjacentLanes
    case alternatingNegation
    case complexLanes
    case widenedPairs
    case widenedEven
    case widenedOdd
    case widenedAccumulating

    var isWidened: Bool {
        [.widenedPairs, .widenedEven, .widenedOdd, .widenedAccumulating].contains(self)
    }
}

enum ReturnType: Equatable {
    case vector
    case laneIndices
    case mask
    case lane
    case count
    case index
    case bits
    case boolean
    case void
    case indices
    case tuple(Int)
    case narrowVector(Shape)
    case narrowMask(Shape)
}

// How much of a span the span form of a pointer op reads or writes, from the span's start.
// `first` is as many lanes as the span has, up to a vector, which a pointer op takes as `count`.
// An `aligned` op also needs the span to start at an address aligned to the vector size.
// A `table` is that many lanes, from an address aligned to their size, however many lanes a vector
// has. `maskBytes` is as many bytes as a mask has bits, rounded up. A `block` is the lanes of a
// 128-bit block and a `halfVector` is half of the lanes of a vector. A `gathered` extent is the
// lanes that the indices of the op select, wherever they are in the span.
enum SpanExtent {
    case vectors(Int, aligned: Bool = false)
    case first
    case table(lanes: Int)
    case maskBytes
    case block
    case halfVector
    case quarterVector
    case eighthVector
    case gathered
}

// How many indices a lookup op accepts, as a number of lanes of a vector or a fixed number.
enum IndexCount {
    case fixed(Int)
    case lanes(Int)

    func expression(laneCount: String) -> String {
        switch self {
        case .fixed(let count): return String(count)
        case .lanes(1): return laneCount
        case .lanes(let multiple): return "\(multiple) * \(laneCount)"
        }
    }
}

// The indices a lookup op accepts: those which, as unsigned lanes, are below `count` once `offset`
// is subtracted from them, wrapping around. So an offset of 128 and a count of 144 accept 128
// through 255 and 0 through 15. A per-byte contract applies to every byte of the indices, however
// wide their lanes are.
struct IndexContract {
    let offset: Int
    let count: IndexCount
    let message: String
    var isDefinedOnEmulation = true
    var isPerByte = false

    static let bytes = IndexContract(
        offset: 0,
        count: .fixed(16),
        message: "Byte index is negative or more than 15",
        isPerByte: true
    )
    static let zeroingBytes = IndexContract(
        offset: 128,
        count: .fixed(144),
        message: "Byte index is 16 through 127",
        isPerByte: true
    )
    static let lanes = IndexContract(
        offset: 0,
        count: .lanes(1),
        message: "Lane index is negative or at least as many as a vector has lanes",
        isDefinedOnEmulation: false
    )
    static func table(lanes: Int) -> IndexContract {
        IndexContract(
            offset: 0,
            count: .fixed(lanes),
            message: "Lane index is negative or at least as many as the table has lanes",
            isDefinedOnEmulation: false
        )
    }
    static let lanesOfTwoTables = IndexContract(
        offset: 0,
        count: .lanes(2),
        message: "Lane index is negative or at least twice as many as a vector has lanes"
    )
}

protocol WidthScaled {
    func at(width: Int) -> Self
}

extension Element: WidthScaled {}

struct WideningElements: WidthScaled {
    let narrow: Element
    let wide: Element

    func at(width: Int) -> WideningElements {
        WideningElements(narrow: narrow, wide: wide.at(width: width))
    }
}

struct TargetBodies<Input> {
    var neon: ((Input) -> String?)?
    var sve2_128: ((Input) -> String?)?
    var sve2_128Splat: ((Input) -> String?)?
    var avx3dl: ((Input) -> String?)?
    var avx3: ((Input) -> String?)?
    var avx2: ((Input) -> String?)?
    var sse4: ((Input) -> String?)?
    var ssse3: ((Input) -> String?)?
    var sse2: ((Input) -> String?)?
    var emu128: ((Input) -> String?)?

    var isEmpty: Bool {
        neon == nil && sve2_128 == nil && sve2_128Splat == nil && avx3dl == nil && avx3 == nil
            && avx2 == nil && sse4 == nil
            && ssse3 == nil && sse2 == nil && emu128 == nil
    }

    func body(at level: X86Level) -> ((Input) -> String?)? {
        switch level {
        case .avx3dl: return avx3dl
        case .avx3: return avx3
        case .avx2: return avx2
        case .sse4: return sse4
        case .ssse3: return ssse3
        case .sse2: return sse2
        }
    }
}

