    case blockwise = "Blockwise"
    case shiftWithinBlocks = "ShiftWithinBlocks"
    case reverse = "Reverse"
    case userSpecifiedPermutationAcrossBlocks = "UserSpecifiedPermutationAcrossBlocks"
    case slideAcrossBlocks = "SlideAcrossBlocks"
    case reductions = "Reductions"
    case crypto = "Crypto"
