}

// How far an immediate reaches, in terms of the lanes a block and a vector have. A vector has more
// lanes on a wider target, so a bound that follows the vector grows with it.
enum ImmediateBound {
    case fixed(Int)
    case lanes(offset: Int)
    case blockLanes(offset: Int)
    case blocks(offset: Int)

    func value(for element: Element) -> Int {
        switch self {
        case .fixed(let value): return value
        case .lanes(let offset): return element.laneCount + offset
        case .blockLanes(let offset): return element.blockLaneCount + offset
        case .blocks(let offset): return element.laneCount / element.blockLaneCount + offset
        }
    }

    func expression(for element: Element, laneCount: String) -> String {
        func offset(_ expression: String, _ offset: Int) -> String {
            offset == 0 ? expression : "\(expression) \(offset < 0 ? "-" : "+") \(abs(offset))"
        }
        switch self {
        case .fixed(let value): return String(value)
        case .lanes(let amount): return offset(laneCount, amount)
        case .blockLanes(let amount): return String(element.blockLaneCount + amount)
        case .blocks(let amount):
            return offset("\(laneCount) / \(element.blockLaneCount)", amount)
        }
    }

    func width(reaching immediate: Int, for element: Element) -> Int {
        let bytes: Int
        switch self {
        case .fixed, .blockLanes: bytes = 16
        case .lanes(let offset): bytes = (immediate - offset) * element.bits / 8
        case .blocks(let offset): bytes = (immediate - offset) * 16
        }
        return max(16, bytes)
    }
}

// Another value of an immediate that the codegen pairs of its op are also made for, which `name`
// tells apart in their names, and which may depend on the element that the op returns.
struct CodegenImmediate {
    let name: String
    let value: (Element) -> Int
}

// A constant that an op takes as a template argument in Highway, and as an `Int` that is checked
// to be within its bounds in Swift. An `…Unchecked` form takes it without the check.
struct ImmediateArgument {
    let name: String
    let label: String
    var uncheckedLabel: String?
    var lowerBound = 0
    let upperBound: ImmediateBound
    var codegenValue = 1
    var codegenAlternatives: [CodegenImmediate] = []
    let message: String

    func values(for element: Element) -> ClosedRange<Int> {
        lowerBound...upperBound.value(for: element)
    }

    func swiftLabel(checked: Bool) -> String {
        checked ? label : uncheckedLabel ?? checkedLabel(label, checked: false)
    }

    func check(for element: Element, laneCount: String = "laneCount") -> Check {
        let upper = upperBound.expression(for: element, laneCount: laneCount)
        return ("\(name) >= \(lowerBound) && \(name) <= \(upper)", message)
    }
}

// The template op of Highway that takes the shift amount of an op as a template argument, which a
// literal amount within `range` takes the code of. The amounts outside of it, and those that are
// not known, are those of the op, and Highway's reference of it is `fallback` over its arguments.
struct ImmediateTemplate {
    let name: String
    var range: (Element) -> ClosedRange<Int>
    var fallback: (([String]) -> String)?
    var paths: TargetBodies<Element>
}

struct ConstantArgument {
    let name: String
    var cast = ""
    var applies: (Element) -> Bool = { _ in true }
    var vector = false
    var holds: ((Element) -> String)?
}

enum DefinedLanes {
    case trueLanes
    case falseLanes
}

enum Growth {
    case unspecified
    case zeroed
}

struct Op {
    let swiftName: String
    let highwayName: String
    let parameters: [Parameter]
    let returns: ReturnType
    var applies: Applies
    let section: Section
    var documentation: String = ""
    let span: SpanExtent?
    let constantArgument: ConstantArgument?
    let immediates: [ImmediateArgument]
    let template: ImmediateTemplate?
    let indexContract: IndexContract?
    let laneCapability: LaneCapability?
    let divides: Bool
    let requiresTrueLane: Bool
    let unorderedNaNs: UnorderedNaNs?
    let filtersUnorderedNaNs: Bool
    let unspecifiedResult: Bool
    let definedLanes: DefinedLanes?
    let growth: Growth?
    let accumulates: Bool
    let vectorLabels: [String]
    let maskLabels: [String]
    let source: Element?
    let explicitIdentifier: String?
    let targets: TargetBodies<Element>
    let spanTargets: TargetBodies<Element>
    let helpers: TargetBodies<Element>
    let outOfLineOnSVE: Applies?
    let narrowElement: Element?
    let swiftOrdering: [Int]?
    let appendsToOutputSpan: Bool
    let clampsSpanCount: Bool
    let leavesLanesUnspecified: Bool
    let acceptsNonCanonicalMasks: Bool
    let referenceCall: ((Element, [String]) -> String)?
    let portable: (Element) -> String

    init(
        _ swiftName: String,
        _ highwayName: String,
        _ parameters: [Parameter],
        _ returns: ReturnType,
        _ applies: Applies,
        section: Section,
        _ documentation: String = "",
        span: SpanExtent? = nil,
        constantArgument: ConstantArgument? = nil,
        immediates: [ImmediateArgument] = [],
        template: ImmediateTemplate? = nil,
        indexContract: IndexContract? = nil,
        laneCapability: LaneCapability? = nil,
        divides: Bool = false,
        requiresTrueLane: Bool = false,
        unorderedNaNs: UnorderedNaNs? = nil,
        filtersUnorderedNaNs: Bool = false,
        unspecifiedResult: Bool = false,
        definedLanes: DefinedLanes? = nil,
        growth: Growth? = nil,
        accumulates: Bool = false,
        vectorLabels: [String] = [],
        maskLabels: [String] = [],
        source: Element? = nil,
        identifier: String? = nil,
        targets: TargetBodies<Element> = TargetBodies(),
        spanTargets: TargetBodies<Element> = TargetBodies(),
        helpers: TargetBodies<Element> = TargetBodies(),
        outOfLineOnSVE: Applies? = nil,
        narrowElement: Element? = nil,
        swiftOrdering: [Int]? = nil,
        appendsToOutputSpan: Bool = true,
        clampsSpanCount: Bool = false,
        leavesLanesUnspecified: Bool = false,
        acceptsNonCanonicalMasks: Bool = false,
        referenceCall: ((Element, [String]) -> String)? = nil,
        portable: @escaping (Element) -> String
    ) {
        if source == nil && parameters.contains(where: \.isSourced) {
            fatalError("\(swiftName) takes a source operand but has no source element")
        }
        self.swiftName = swiftName
        self.highwayName = highwayName
        self.parameters = parameters
        self.returns = returns
        self.applies = applies
        self.section = section
        self.documentation = documentation
        self.span = span
        self.constantArgument = constantArgument
        self.immediates = immediates
        self.template = template
        self.indexContract = indexContract
        self.laneCapability = laneCapability
        self.divides = divides
        self.requiresTrueLane = requiresTrueLane
        self.unorderedNaNs = unorderedNaNs
        self.filtersUnorderedNaNs = filtersUnorderedNaNs
        self.unspecifiedResult = unspecifiedResult
        self.definedLanes = definedLanes
        self.growth = growth
        self.accumulates = accumulates
        self.vectorLabels = vectorLabels
        self.maskLabels = maskLabels
        self.source = source
        self.explicitIdentifier = identifier
        self.targets = targets
        self.spanTargets = spanTargets
        self.helpers = helpers
        self.outOfLineOnSVE = outOfLineOnSVE
        self.narrowElement = narrowElement
        self.swiftOrdering = swiftOrdering
        self.appendsToOutputSpan = appendsToOutputSpan
        self.clampsSpanCount = clampsSpanCount
        self.leavesLanesUnspecified = leavesLanesUnspecified
        self.acceptsNonCanonicalMasks = acceptsNonCanonicalMasks
        self.referenceCall = referenceCall
        self.portable = portable
    }

    var operands: [Parameter] {
        parameters.filter { !$0.isTag }
    }

    /// The positions in `operands` of the parameters in the order Swift declares them.
    var swiftOrder: [Int] {
        if let swiftOrdering { return swiftOrdering }
        let operands = self.operands
        return operands.indices.sorted {
            (operands[$0].swiftRank, $0) < (operands[$1].swiftRank, $1)
        }
    }

    /// `values`, one per operand in Highway's order, in the order Swift declares them.
    func swiftOrdered<Value>(_ values: [Value]) -> [Value] {
        swiftOrder.map { values[$0] }
    }

    /// `values`, one per operand in Swift's order, in the order Highway takes them.
    func highwayOrdered<Value>(_ values: [Value]) -> [Value] {
        var ordered = values
        for (position, index) in swiftOrder.enumerated() {
            ordered[index] = values[position]
        }
        return ordered
    }

    /// What tells this op from the overloads that share its `swiftName`, which the names of its
    /// C, reference and test functions are made of.
    var identifier: String {
        if let explicitIdentifier { return explicitIdentifier }
        var swiftLabels = SwiftLabels(of: self)
        let labels = operands.map { parameter -> String? in
            let label = swiftLabels.next(for: parameter)
            return parameter.overloading != nil || parameter.isSourced ? label : nil
        }
        let overloading = swiftOrdered(labels).compactMap { $0 }.filter { $0 != "_" }
        return swiftName + overloading.map(uppercasedFirst).joined()
    }

    var sourceShape: Shape {
        parameters.first(where: \.isSourced)?.shape ?? .full
    }

    var testIdentifier: String {
        guard let source else { return identifier }
        return "\(identifier)From\(sourceShape.prefix)\(source.swiftType)"
    }
}

struct SwiftLabels {
    private var vectorLabels: IndexingIterator<[String]>
    private var maskLabels: IndexingIterator<[String]>

    init(of op: Op) {
        vectorLabels = op.vectorLabels.makeIterator()
        maskLabels = op.maskLabels.makeIterator()
    }

    mutating func next(for parameter: Parameter) -> String? {
        if let label = parameter.overloading?.label { return label }
        switch parameter {
        case .vector, .shiftCounts, .sourceVector, .signedSourceVector, .narrowVector,
            .sourceNarrowVector:
            return vectorLabels.next()
        case .mask, .whereMask, .sourceMask, .narrowMask, .sourceNarrowMask:
            return maskLabels.next()
        default: return nil
        }
    }
}

func compoundLiteral(_ type: String, _ values: [String]) -> String {
    "(\(type)){\(values.joined(separator: ", "))}"
}

func splat(_ value: String, as type: String, lanes: Int) -> String {
    compoundLiteral(type, Array(repeating: value, count: lanes))
}

func iota(as type: String, lanes: Int) -> String {
    compoundLiteral(type, (0..<lanes).map(String.init))
}

func clampedCount(_ count: String = "count", to lanes: Int) -> String {
    "(\(count) < \(lanes) ? \(count) : \(lanes))"
}

func unsignedElement(bits: Int) -> Element {
    guard
        let unsigned = elements.first(where: { $0.category == .unsignedInteger && $0.bits == bits })
    else {
        fatalError("There is no unsigned element of \(bits) bits")
    }
    return unsigned
}

func unsignedElement(of element: Element) -> Element {
    unsignedElement(bits: element.bits)
}

func signedElement(of element: Element) -> Element {
    guard
        let signed = elements.first(where: {
            $0.category == .signedInteger && $0.bits == element.bits
        })
    else {
        fatalError("There is no signed element of \(element.bits) bits")
    }
    return signed
}

func resizedElement(of element: Element, bits: Int) -> Element {
    guard
        let resized = elements.first(where: {
            $0.category == element.category && $0.bits == bits
        })
    else {
        fatalError("There is no element of \(bits) bits")
    }
    return resized.at(width: element.width)
}

func widenedElement(of element: Element) -> Element {
    resizedElement(of: element, bits: element.bits * 2)
}

func floatElement(bits: Int) -> Element {
    guard let float = elements.first(where: { $0.category == .float && $0.bits == bits }) else {
        fatalError("There is no float element of \(bits) bits")
    }
    return float
}

func laneIndexElement(of element: Element) -> Element {
    element.category == .unsignedInteger || element.category == .signedInteger
        ? element : signedElement(of: element)
}

func operandElement(
    of parameter: Parameter,
    for element: Element,
    source: Element? = nil
) -> Element {
    if parameter == .signedSourceVector, let source { return signedElement(of: source) }
    if parameter.isSourced, let source { return source }
    if parameter.isPointerIndices { return signedElement(of: element) }
    return parameter.isLaneIndices ? laneIndexElement(of: element) : element
}

func signedFirstLanesMask(for element: Element) -> String {
    let lanes = element.laneCount
    let offsets = iota(as: element.cMask, lanes: lanes)
    let unsigned = unsignedElement(of: element)
    let limit = "(\(element.cMask))\(repeatingVector("(\(unsigned.cType))n", of: unsigned))"
    return """
        const \(element.cMaskLane) n = (\(element.cMaskLane))\(clampedCount(to: lanes));
        const \(element.cMask) mask = \(limit) > \(offsets);
        """
}

func signedFirstLanes(for element: Element) -> String {
    "\(signedFirstLanesMask(for: element))\n\(maskResult("mask", for: element))"
}

func x86Avx3FirstLanes(for element: Element) -> String {
    let lanes = element.laneCount
    let bits = (value: x86FirstLanesBits(lanes: lanes), type: x86MaskType(lanes: lanes))
    let letter = x86LaneLetter(bits: element.bits)
    let mask = x86Builtin(
        "cvtmask2\(letter)\(x86Bits(element.width))",
        [bits],
        returning: element.cMask
    )
    return maskResult(mask, for: element)
}

func x86Int64FirstLanes(for element: Element) -> String {
    let lanes = element.laneCount
    let mask = element.cMask
    return """
        const \(element.cMaskLane) n = (\(element.cMaskLane))\(clampedCount(to: lanes));
        const \(mask) offsets = \(iota(as: mask, lanes: lanes));
        const \(mask) limit = \(splat("n", as: mask, lanes: lanes));
        \(x86Int64Comparison("limit", "offsets", for: element))
        """
}

func unsignedBits(_ operand: String, of element: Element) -> String {
    element.category == .unsignedInteger ? operand : "(\(element.cUnsignedVector))\(operand)"
}

func fromUnsignedBits(_ expression: String, of element: Element) -> String {
    element.category == .unsignedInteger ? expression : "(\(element.cVector))(\(expression))"
}

func repeatingVector(_ value: String, of element: Element) -> String {
    "(\(element.cVector))\(cFunctionName("repeating", element))(\(value))"
}

func vectorResult(_ expression: String, for element: Element) -> String {
    "return (\(element.cRawVector))(\(expression));"
}

func maskResult(_ expression: String, for element: Element) -> String {
    "return (\(element.cRawMask))(\(expression));"
}

func withoutContraction(_ statements: String) -> String {
    "{\n#pragma clang fp contract(off)\n\(indented(statements))\n}"
}

func unfusedMultiplyAdding(for element: Element) -> String {
    withoutContraction(vectorResult("a * b + c", for: element))
}

func fusedMultiplyAdding(for element: Element) -> String? {
    guard element.category == .float else { return nil }
    return vectorResult("__builtin_elementwise_fma(a, b, c)", for: element)
}

func multipliedLanes(_ first: String, _ second: String, for element: Element) -> String {
    let raw = element.cRawVector
    let multiplying = cFunctionName("multiplying", element)
    return "(\(element.cVector))\(multiplying)((\(raw))\(first), (\(raw))\(second))"
}

func integerMultiplyAdding(for element: Element) -> String {
    let product = multipliedLanes("a", "b", for: element)
    return vectorResult(arithmetic("+", product, "c", for: element), for: element)
}

func arithmetic(
    _ symbol: String,
    _ first: String,
    _ second: String,
    for element: Element
) -> String {
    guard element.category == .signedInteger else { return "\(first) \(symbol) \(second)" }
    let unsigned = element.cUnsignedVector
    return "(\(element.cVector))((\(unsigned))\(first) \(symbol) (\(unsigned))\(second))"
}

func binaryArithmetic(_ symbol: String, for element: Element) -> String {
    vectorResult(arithmetic(symbol, "a", "b", for: element), for: element)
}

func vectorComparison(_ symbol: String, for element: Element) -> String {
    maskResult("(\(element.cMask))(a \(symbol) b)", for: element)
}

func bitSelect(_ mask: String, _ a: String, _ b: String, of element: Element) -> String {
    let unsignedMask = "(\(element.cUnsignedVector))\(mask)"
    let chosen = "(\(unsignedMask) & \(unsignedBits(a, of: element)))"
    let rest = "(~\(unsignedMask) & \(unsignedBits(b, of: element)))"
    return fromUnsignedBits("\(chosen) | \(rest)", of: element)
}

func infinity(of element: Element) -> String {
    element.bits == 32 ? "__builtin_inff()" : "__builtin_inf()"
}

func elementwiseExtremum(_ name: String, comparing symbol: String, for element: Element) -> String {
    guard element.category == .float else {
        return vectorResult("__builtin_elementwise_\(name)(a, b)", for: element)
    }
    let mask = element.cMask
    let ordered = "(\(mask))(a == a)"
    let unordered = "(\(mask))(a != a)"
    let constant = "__builtin_constant_p(__builtin_reduce_or((\(element.cUnsignedVector))b))"
    let number = "__builtin_elementwise_\(name)(first, b)"
    return """
        \(element.cVector) first = a;
        if (\(constant)) {
          first = \(bitSelect(unordered, "b", "a", of: element));
        }
        const \(mask) take = (\(mask))(first \(symbol) b) | ((\(mask))(b != b) & \(ordered));
        \(element.cVector) result = \(bitSelect("take", "first", "b", of: element));
        if (\(constant)) {
          \(element.cVector) source;
          for (size_t i = 0; i < \(element.laneCount); ++i) {
            source[i] = a[i] != a[i] ? b[i] : b[i] != b[i] ? a[i] : a[i] \(symbol) b[i] ? a[i] : b[i];
          }
          const \(mask) bySelect = ~((\(mask))(b < 0) | (\(mask))(b > 0));
          result = \(bitSelect("bySelect", "source", number, of: element));
        }
        \(vectorResult("result", for: element))
        """
}

func highestValue(of element: Element) -> String {
    switch element.category {
    case .float: return infinity(of: element)
    case .signedInteger: return "INT\(element.bits)_MAX"
    case .unsignedInteger: return "UINT\(element.bits)_MAX"
    case .float16, .bfloat16: fatalError("\(element.swiftType) has no highest value")
    }
}

func lowestValue(of element: Element) -> String {
    switch element.category {
    case .float: return "-\(infinity(of: element))"
    case .signedInteger: return "INT\(element.bits)_MIN"
    case .unsignedInteger: return "0"
    case .float16, .bfloat16: fatalError("\(element.swiftType) has no lowest value")
    }
}

func reducedSum(for element: Element) -> String {
    let isSigned = element.category == .signedInteger
    let accumulator = isSigned ? element.cUnsignedLane : element.cType
    return """
        \(accumulator) sum = 0;
        for (size_t i = 0; i < \(element.laneCount); ++i) {
          sum += a[i];
        }
        return \(isSigned ? "(\(element.cType))sum" : "sum");
        """
}

func reducedExtremum(
    comparing symbol: String,
    from start: String,
    for element: Element
) -> String {
    guard element.category == .float else {
        return """
            \(element.cType) result = \(start);
            for (size_t i = 0; i < \(element.laneCount); ++i) {
              result = result \(symbol) a[i] ? result : a[i];
            }
            return result;
            """
    }
    let lanes = (0..<element.laneCount).map { "const \(element.cType) lane\($0) = a[\($0)];" }
    let steps = (0..<element.laneCount).map {
        "result = result \(symbol) lane\($0) ? result : lane\($0);"
    }
    return """
        \(lanes.joined(separator: "\n"))
        \(element.cType) result = \(start);
        \(steps.joined(separator: "\n"))
        return result;
        """
}

func builtinReduction(_ name: String) -> String {
    "return __builtin_reduce_\(name)(a);"
}

func shiftedWithinWidth(_ symbol: String, for element: Element) -> String {
    let lane = element.cUnsignedLane
    let width = element.bits
    let inRange = splat("inRange", as: element.cUnsignedVector, lanes: element.laneCount)
    let shifted = "\(unsignedBits("a", of: element)) \(symbol) (bits & \(width - 1))"
    return """
        const \(lane) inRange = (\(lane))0 - (\(lane))((unsigned)bits < \(width));
        \(vectorResult(fromUnsignedBits("(\(shifted)) & \(inRange)", of: element), for: element))
        """
}

func shiftedByLanes(_ symbol: String, for element: Element) -> String {
    let unsigned = element.cUnsignedVector
    let width = element.bits
    let amounts = "bits & \(width - 1)"
    let inRange = "(\(unsigned))(bits < \(width))"
    let bits = unsignedBits("a", of: element)
    return """
        const \(unsigned) bits = (\(unsigned))b;
        \(vectorResult(fromUnsignedBits("(\(bits) \(symbol) (\(amounts))) & \(inRange)", of: element), for: element))
        """
}

func portableShiftedRightByLanes(for element: Element) -> String {
    guard element.category == .signedInteger else { return shiftedByLanes(">>", for: element) }
    let unsigned = element.cUnsignedVector
    let limit = splat("\(element.bits - 1)", as: unsigned, lanes: element.laneCount)
    return """
        const \(unsigned) bits = __builtin_elementwise_min((\(unsigned))b, \(limit));
        \(vectorResult("a >> (\(element.cVector))bits", for: element))
        """
}

func rotatedByLanes(left: Bool, for element: Element) -> String {
    let unsigned = unsignedElement(of: element).at(width: element.width)
    let type = unsigned.cVector
    let mask = splat("\(element.bits - 1)", as: type, lanes: element.laneCount)
    let amount = "(\(type))b"
    let direct = "const \(type) \(left ? "shiftLeft" : "shiftRight") = \(amount) & \(mask);"
    let opposite = "const \(type) \(left ? "shiftRight" : "shiftLeft") = -\(amount) & \(mask);"
    let shiftedLeft = operationCall("shiftedLeftBy", ["vector", "shiftLeft"], for: unsigned)
    let shiftedRight = operationCall("shiftedRightBy", ["vector", "shiftRight"], for: unsigned)
    return """
        \(direct)
        \(opposite)
        const \(type) vector = \(unsignedBits("a", of: element));
        \(vectorResult(fromUnsignedBits("\(shiftedLeft) | \(shiftedRight)", of: element), for: element))
        """
}

func rotatedBySame(left: Bool, for element: Element) -> String {
    let unsigned = unsignedElement(of: element).at(width: element.width)
    let direct = "const int \(left ? "shiftLeft" : "shiftRight") = bits & \(element.bits - 1);"
    let opposite =
        "const int \(left ? "shiftRight" : "shiftLeft") = (int)((0u - (unsigned)bits) & \(element.bits - 1)u);"
    let raw = unsigned.cRawVector
    let shiftedLeft = "\(cFunctionName("shiftedLeft", unsigned))((\(raw))vector, shiftLeft)"
    let shiftedRight = "\(cFunctionName("shiftedRight", unsigned))((\(raw))vector, shiftRight)"
    return """
        \(direct)
        \(opposite)
        const \(unsigned.cVector) vector = \(unsignedBits("a", of: element));
        \(vectorResult(fromUnsignedBits("(\(unsigned.cVector))\(shiftedLeft) | (\(unsigned.cVector))\(shiftedRight)", of: element), for: element))
        """
}

func emulatedLaneLoop(_ statements: String, for element: Element) -> String {
    """
    \(element.cVector) result;
    for (size_t i = 0; i < \(element.laneCount); ++i) {
    \(indented(statements))
    }
    \(vectorResult("result", for: element))
    """
}

func emulatedShiftedLane(_ symbol: String, by amount: String, for element: Element) -> String {
    let lane = element.cUnsignedLane
    let limit = element.bits - 1
    switch (element.category, symbol) {
    case (.signedInteger, ">>"):
        return "a[i] >> (\(amount) < \(limit) ? \(amount) : \(limit))"
    case (.signedInteger, _):
        return "(\(element.cType))(\(amount) < \(element.bits) ? (\(lane))a[i] << \(amount) : 0)"
    default:
        return "\(amount) < \(element.bits) ? a[i] \(symbol) \(amount) : 0"
    }
}

func emulatedShiftedByLanes(_ symbol: String, for element: Element) -> String? {
    guard isInteger64(element) else { return nil }
    let lane = element.cUnsignedLane
    return emulatedLaneLoop(
        """
        const \(lane) amount = (\(lane))b[i];
        result[i] = \(emulatedShiftedLane(symbol, by: "amount", for: element));
        """,
        for: element
    )
}

func emulatedRotatedByLanes(left: Bool, for element: Element) -> String? {
    guard isInteger64(element) else { return nil }
    let lane = element.cUnsignedLane
    let (direct, opposite) = left ? ("<<", ">>") : (">>", "<<")
    let mask = element.bits - 1
    return emulatedLaneLoop(
        """
        const \(lane) amount = (\(lane))b[i];
        const \(lane) lane = (\(lane))a[i];
        result[i] = (\(element.cType))((lane \(direct) (amount & \(mask))) | (lane \(opposite) (-amount & \(mask))));
        """,
        for: element
    )
}

func emulatedRotatedBySame(left: Bool, for element: Element) -> String? {
    guard isInteger64(element) else { return nil }
    let lane = element.cUnsignedLane
    let direct = "const int \(left ? "shiftLeft" : "shiftRight") = bits & \(element.bits - 1);"
    let opposite =
        "const int \(left ? "shiftRight" : "shiftLeft") = (int)((0u - (unsigned)bits) & \(element.bits - 1)u);"
    let loop = emulatedLaneLoop(
        """
        const \(lane) lane = (\(lane))a[i];
        result[i] = (\(element.cType))((lane << shiftLeft) | (lane >> shiftRight));
        """,
        for: element
    )
    return """
        \(direct)
        \(opposite)
        \(loop)
        """
}

func emulatedHalvedRounding(_ condition: String, for element: Element) -> String {
    let lane = element.cUnsignedLane
    return "(\(element.cType))((\(lane))scaled - (\(lane))(\(condition) ? 0 : scaled >> 1))"
}

func emulatedRoundingShiftedRightByLanes(for element: Element) -> String? {
    guard isInteger64(element) else { return nil }
    let lane = element.cUnsignedLane
    return emulatedLaneLoop(
        """
        const \(lane) amount = (\(lane))b[i];
        const \(lane) scaleDown = amount == 0 ? 0 : amount - 1;
        const \(element.cType) scaled = \(emulatedShiftedLane(">>", by: "scaleDown", for: element));
        result[i] = \(emulatedHalvedRounding("amount == 0", for: element));
        """,
        for: element
    )
}

func emulatedRoundingShiftedRightBySame(for element: Element) -> String? {
    guard isInteger64(element) else { return nil }
    let lane = element.cUnsignedLane
    let limit = element.bits - 1
    let (range, scaled) =
        element.category == .signedInteger
        ? (
            "const unsigned shift = amount < \(limit) ? amount : \(limit);",
            "a[i] >> shift"
        )
        : (
            "const \(lane) inRange = (\(lane))0 - (\(lane))(amount < \(element.bits));",
            "(a[i] >> (amount & \(limit))) & inRange"
        )
    let loop = emulatedLaneLoop(
        """
        const \(element.cType) scaled = \(scaled);
        result[i] = \(emulatedHalvedRounding("isZero", for: element));
        """,
        for: element
    )
    return """
        const bool isZero = bits == 0;
        const unsigned amount = (unsigned)bits + (unsigned)isZero - 1u;
        \(range)
        \(loop)
        """
}

func emulatedAllBitsReduction(setting: Bool, for element: Element) -> String? {
    guard element.bits == 64, setting || element.category != .float else { return nil }
    let lane = element.cUnsignedLane
    let (initial, symbol) = setting ? ("~(\(lane))0", "&") : ("0", "|")
    return """
        const \(element.cUnsignedVector) bits = \(unsignedBits("a", of: element));
        \(lane) sum = \(initial);
        for (size_t i = 0; i < \(element.laneCount); ++i) {
          sum \(symbol)= bits[i];
        }
        return sum == \(initial);
        """
}

func emulatedHighestSetBitIndex(for element: Element) -> String? {
    guard element.bits == 32 else { return nil }
    return emulatedLaneLoop(
        """
        const uint32_t bits = (uint32_t)a[i];
        const float converted = (float)(bits & ~(bits >> 24));
        result[i] = (\(element.cType))((__builtin_bit_cast(uint32_t, converted) >> 23) - 127u);
        """,
        for: element
    )
}

func roundingShiftedRightByLanesScaled(for element: Element) -> String {
    let unsigned = unsignedElement(of: element).at(width: element.width)
    let ones = splat("1", as: unsigned.cVector, lanes: element.laneCount)
    let scaleDown =
        element.bits < 32
        ? "__builtin_elementwise_sub_sat(amounts, \(ones))"
        : "amounts - \(operationCall("minimum", ["amounts", ones], for: unsigned))"
    return """
        typedef long long quad_lanes __attribute__((vector_size(\(element.width))));
        const \(unsigned.cVector) amounts = (\(unsigned.cVector))b;
        const \(unsigned.cVector) scaleDown = \(scaleDown);
        const \(element.cVector) scaled = \(operationCall("shiftedRightBy", ["a", "scaleDown"], for: element));
        """
}

func portableRoundingShiftedRightByLanes(
    emulatingQuadEquality: Bool = false,
    for element: Element
) -> String {
    let i32 = x86Vector("i32")
    let swapped = laneIndices((0..<(element.width / 4)).map { $0 ^ 1 })
    let zeroLanes =
        emulatingQuadEquality
        ? """
        const \(i32) equalDwords = (\(i32))b == 0;
        const \(i32) isZero = equalDwords & __builtin_shufflevector(equalDwords, equalDwords, \(swapped));
        """
        : "const quad_lanes isZero = (quad_lanes)(b == 0);"
    return """
        \(roundingShiftedRightByLanesScaled(for: element))
        \(zeroLanes)
        const \(element.cVector) unscaled = (\(element.cVector))((quad_lanes)scaled & (quad_lanes)isZero);
        \(vectorResult(operationCall("roundedAverage", ["scaled", "unscaled"], for: element), for: element))
        """
}

func x86Avx2RoundingShiftedRightByLanes(for element: Element) -> String? {
    guard element.category == .signedInteger, element.bits == 16 else { return nil }
    let vector = element.cVector
    let unsigned = unsignedElement(of: element).at(width: element.width).cVector
    return """
        \(roundingShiftedRightByLanesScaled(for: element))
        const quad_lanes isZero = (quad_lanes)(b == 0);
        const \(vector) kept = (\(vector))(~isZero & (quad_lanes)scaled);
        \(vectorResult("(\(vector))((\(unsigned))scaled - (\(unsigned))(kept >> 1))", for: element))
        """
}

func roundingShiftedRightBySame(
    unscaled: (_ scaled: String) -> String,
    prologue: String = "",
    for element: Element
) -> String {
    let shifted = "(\(element.cVector))\(cFunctionName("shiftedRight", element))(rawA, amount)"
    return """
        \(prologue)const bool isZero = bits == 0;
        const int amount = (int)((unsigned)bits + (unsigned)isZero - 1u);
        const \(element.cVector) scaled = \(shifted);
        const \(element.cVector) unscaled = \(unscaled("scaled"));
        \(vectorResult(operationCall("roundedAverage", ["scaled", "unscaled"], for: element), for: element))
        """
}

func portableRoundingShiftedRightBySame(for element: Element) -> String {
    let masks = "typedef int32_t mask_dwords __attribute__((vector_size(\(element.width))));\n"
    let zeroMask = splat("\(setMaskName)(isZero)", as: "mask_dwords", lanes: element.width / 4)
    return roundingShiftedRightBySame(
        unscaled: { scaled in
            "(\(element.cVector))(\(unsignedBits(scaled, of: element)) & (\(element.cUnsignedVector))\(zeroMask))"
        },
        prologue: masks,
        for: element
    )
}

func x86Avx3RoundingShiftedRightBySame(for element: Element) -> String {
    let lanes = element.laneCount
    let all = lanes < 64 ? "((1ull << \(lanes)) - 1ull)" : "~0ull"
    let type = x86MaskType(lanes: lanes)
    let selected = x86Avx3Select(
        "(\(type))(-(int64_t)isZero & \(all))",
        "scaled",
        compoundLiteral(x86Vector(x86LaneSuffix(of: element)), ["0"]),
        for: element
    )
    return roundingShiftedRightBySame(unscaled: { _ in selected }, for: element)
}

func scalarNaN(of element: Element) -> String {
    let bits = (UInt64(1) << UInt64(element.bits - 1)) - 1
    let literal = "(\(element.cUnsignedLane))0x\(String(bits, radix: 16))"
    return "__builtin_bit_cast(\(element.cType), \(literal))"
}

func reducedExtremumOrNaN(_ name: String, isNaN: String, for element: Element) -> String {
    let allFalse = cFunctionName("allFalse", element)
    let extremum = cFunctionName(name, element)
    let hasNoNaN = "\(allFalse)((\(element.cRawMask))\(isNaN))"
    return "return \(hasNoNaN) ? \(extremum)(\(rawName("a"))) : \(scalarNaN(of: element));"
}

func assumedAligned(_ pointer: String, for element: Element) -> String {
    "__builtin_assume_aligned(\(pointer), \(element.width))"
}

func loadedVector(from pointer: String, for element: Element) -> String {
    """
    \(element.cVector) v;
    __builtin_memcpy(&v, \(pointer), sizeof v);
    \(vectorResult("v", for: element))
    """
}

func storedVector(to pointer: String) -> String {
    "__builtin_memcpy(\(pointer), &a, sizeof a);"
}

func zeroedVector(of type: String) -> String {
    """
    \(type) v;
    __builtin_memset(&v, 0, sizeof v);
    """
}

func outVectorStore(_ channel: Int, from source: String? = nil) -> String {
    let name = source ?? "r\(channel)"
    return "__builtin_memcpy(v\(channel), &\(name), sizeof \(name));"
}

func outVectorStore(_ channel: Int, of value: String, for element: Element) -> String {
    """
    const \(element.cVector) out\(channel) = \(value);
    \(outVectorStore(channel, from: "out\(channel)"))
    """
}

func loadInterleaved(channels: Int, for element: Element) -> String {
    let names = (0..<channels).map { "buf\($0)" }
    let declarations = names.map {
        "\(element.cType) \($0)[\(element.laneCount)] __attribute__((aligned(\(element.width))));"
    }
    let loads = names.map { "  \($0)[i] = *from++;" }
    let load = cFunctionName("loadAligned", element)
    let stores = names.enumerated().map { channel, name in
        element.bits >= 32
            ? outVectorStore(channel, from: name)
            : outVectorStore(channel, of: "(\(element.cVector))\(load)(\(name))", for: element)
    }
    return """
        \(declarations.joined(separator: "\n"))
        for (size_t i = 0; i < \(element.laneCount); ++i) {
        \(loads.joined(separator: "\n"))
        }
        \(stores.joined(separator: "\n"))
        """
}

func storeInterleaved(channels: Int, for element: Element) -> String {
    let names = ["a", "b", "c", "d"].prefix(channels)
    if element.bits == 64 {
        let lanes = (0..<element.laneCount).flatMap { lane in
            names.map { "const \(element.cType) \($0)\(lane) = \($0)[\(lane)];" }
        }
        let stores = (0..<element.laneCount).flatMap { lane in
            names.map { "*to++ = \($0)\(lane);" }
        }
        return (lanes + stores).joined(separator: "\n")
    }
    let stores = names.map { name in
        "  *to++ = \(name)[i];"
    }
    return """
        #pragma clang loop unroll(full)
        for (size_t i = 0; i < \(element.laneCount); ++i) {
        \(stores.joined(separator: "\n"))
        }
        """
}

struct RawVector {
    let name: String
    let type: String
    let attribute: String
}

func neonVector(_ suffix: String) -> String {
    "cvectorization_ops_neon_\(suffix)"
}

func sveVector(_ suffix: String) -> String {
    "cvectorization_ops_sve_\(suffix)"
}

func x86Vector(_ suffix: String) -> String {
    "cvectorization_ops_x86_\(suffix)"
}

func x86Block(_ suffix: String) -> String {
    "cvectorization_ops_x86_block_\(suffix)"
}

let x86IfThenElseName = "cvectorization_ops_x86_if_then_else"

func x86GreaterThanName(bits: Int) -> String {
    "cvectorization_ops_x86_greater_than_i\(bits)"
}

func x86AsFloatName(bits: Int) -> String {
    "cvectorization_ops_x86_as_f\(bits)"
}

let neonVectors: [RawVector] = [
    RawVector(name: neonVector("i8x8"), type: "int8_t", attribute: "neon_vector_type(8)"),
    RawVector(name: neonVector("i8"), type: "int8_t", attribute: "neon_vector_type(16)"),
    RawVector(name: neonVector("f32"), type: "float", attribute: "neon_vector_type(4)"),
    RawVector(name: neonVector("f64"), type: "double", attribute: "neon_vector_type(2)"),
]

let sveVectorBits = 128

let sveVectors: [RawVector] = elements.map { element in
    RawVector(
        name: sveVector(element.cSuffix),
        type: sveType(of: element),
        attribute: "arm_sve_vector_bits(\(sveVectorBits))"
    )
}

let x86Lanes: [(suffix: String, lane: String)] = [
    ("i8", "char"),
    ("i16", "short"),
    ("i32", "int"),
    ("i64", "long long"),
    ("f32", "float"),
    ("f64", "double"),
    ("f16", "__fp16"),
]

let x86Vectors: [RawVector] = x86Lanes.flatMap { suffix, lane in
    [
        RawVector(
            name: x86Vector(suffix),
            type: lane,
            attribute: "vector_size(CVECTORIZATION_OPS_VECTOR_BYTES)"
        ),
        RawVector(name: x86Block(suffix), type: lane, attribute: "vector_size(16)"),
    ]
}

func x86RawType(of element: Element) -> String {
    x86Vector(element.hasOpaqueVector ? "i64" : element.cSuffix)
}

func x86RawBlockType(of element: Element) -> String {
    x86Block(element.hasOpaqueVector ? "i64" : element.cSuffix)
}

func neonTypeCode(of element: Element) -> Int {
    let quad = 32
    switch element.category {
    case .unsignedInteger: return quad + 16 + (element.bits / 8).trailingZeroBitCount
    case .signedInteger: return quad + (element.bits / 8).trailingZeroBitCount
    case .float: return quad + (element.bits == 32 ? 9 : 10)
    case .float16: return quad + 8
    case .bfloat16: return quad + 11
    }
}

func neonBuiltin(
    _ name: String,
    _ arguments: [String],
    code: Int,
    for element: Element
) -> String {
    let operands = arguments.map { "(\(neonVector("i8")))\($0)" } + [String(code)]
    return "(\(element.cVector))__builtin_neon_\(name)(\(operands.joined(separator: ", ")))"
}

func neonShift(
    negated: Bool,
    instruction: String = "vshlq_v",
    for element: Element
) -> String {
    let lanes = element.laneCount
    let count = splat("(\(element.cUnsignedLane))bits", as: element.cUnsignedVector, lanes: lanes)
    let amounts = ["a", negated ? "(-count)" : "count"]
    let shifted = neonBuiltin(instruction, amounts, code: neonTypeCode(of: element), for: element)
    return """
        const \(element.cUnsignedVector) count = \(count);
        \(vectorResult(shifted, for: element))
        """
}

func neonShiftByLanes(
    negated: Bool,
    instruction: String = "vshlq_v",
    for element: Element
) -> String {
    let counts = negated ? "(-\(unsignedBits("b", of: element)))" : "b"
    let shifted = neonBuiltin(
        instruction,
        ["a", counts],
        code: neonTypeCode(of: element),
        for: element
    )
    return vectorResult(shifted, for: element)
}

func neonExtremum(
    _ name: String,
    of operands: [String] = ["a", "b"],
    for element: Element
) -> String {
    guard element.bits < 64 || element.category == .float else {
        let chosen = name == "min" ? (first: "b", second: "a") : (first: "a", second: "b")
        let selected = bitSelect("mask", chosen.first, chosen.second, of: element)
        return """
            const \(element.cMask) mask = (\(element.cMask))(b < a);
            \(vectorResult(selected, for: element))
            """
    }
    let instruction = element.category == .float ? "v\(name)nmq_v" : "v\(name)q_v"
    let code = neonTypeCode(of: element)
    return vectorResult(
        neonBuiltin(instruction, operands, code: code, for: element),
        for: element
    )
}

func multiplying64(
    for element: Element,
    widening product: (_ first: String, _ second: String) -> String
) -> String {
    let words = "cvectorization_ops_vector_u32"
    func widened(_ first: String, _ second: String, into result: String) -> String {
        "const \(words) \(result) = (\(words))\(product(first, second));"
    }
    func high(_ operand: String) -> String {
        "(\(words))(\(unsignedBits(operand, of: element)) >> 32)"
    }
    let unsigned = element.cUnsignedVector
    return """
        const \(words) x = (\(words))a;
        const \(words) y = (\(words))b;
        \(widened("x", "y", into: "lolo"))
        const \(words) yHigh = \(high("b"));
        \(widened("x", "yHigh", into: "lohi"))
        const \(words) xHigh = \(high("a"));
        \(widened("xHigh", "y", into: "hilo"))
        const \(words) hi = (\(words))((\(unsigned))(lohi + hilo) << 32);
        \(vectorResult(fromUnsignedBits("(\(unsigned))(lolo + hi)", of: element), for: element))
        """
}

func neonMultiplying64(for element: Element) -> String {
    let halves = neonVector("i8x8")
    func evens(_ operand: String) -> String {
        "(\(halves))__builtin_shufflevector(\(operand), \(operand), 0, 2)"
    }
    return multiplying64(for: element) { first, second in
        let product = "__builtin_neon_vmull_v(\(evens(first)), \(evens(second)), 51)"
        return "(\(element.cUnsignedVector))\(product)"
    }
}

func x86Multiplying64(for element: Element) -> String {
    multiplying64(for: element) { first, second in
        x86Builtin(
            "pmuludq\(x86Bits(element.width))",
            [first, second],
            as: "i32",
            returning: element.cUnsignedVector
        )
    }
}

func x86HalvesMultiplying(for element: Element) -> String {
    let wide = widenedElement(of: element)
    func promoted(_ operand: String, half: Int) -> String {
        convertedPart(operand, part: half, lanes: wide.laneCount, to: "wide_vector")
    }
    func multiplied(_ first: String, _ second: String) -> String {
        guard element.category == .signedInteger else { return "\(first) * \(second)" }
        return "(wide_vector)((wide_unsigned_vector)\(first) * (wide_unsigned_vector)\(second))"
    }
    let size = "__attribute__((vector_size(\(element.width))))"
    let evens = compoundLiteral(x86Vector("i8"), (0..<element.width).map { String(2 * $0) })
    let lookup = x86TwoTableLookup("lowProducts", "evens", "highProducts", for: element)
    let unsignedTypedef =
        element.category == .signedInteger
        ? ["typedef \(wide.cUnsignedLane) wide_unsigned_vector \(size);"] : []
    let statements =
        ["typedef \(wide.cType) wide_vector \(size);"] + unsignedTypedef + [
            "const wide_vector lowA = \(promoted("a", half: 0));",
            "const wide_vector highA = \(promoted("a", half: 1));",
            "const wide_vector lowB = \(promoted("b", half: 0));",
            "const wide_vector highB = \(promoted("b", half: 1));",
            "const wide_vector lowProducts = \(multiplied("lowA", "lowB"));",
            "const wide_vector highProducts = \(multiplied("highA", "highB"));",
            "const \(x86Vector("i8")) evens = \(evens);",
            vectorResult(lookup, for: element),
        ]
    return statements.joined(separator: "\n")
}

func neonRoundedAverage(for element: Element) -> String {
    let code = neonTypeCode(of: element)
    return vectorResult(
        neonBuiltin("vrhaddq_v", ["a", "b"], code: code, for: element),
        for: element
    )
}

func neonSaturatingSubtraction(for element: Element) -> String {
    let code = neonTypeCode(of: element)
    return vectorResult(
        neonBuiltin("vqsubq_v", ["a", "b"], code: code, for: element),
        for: element
    )
}

func neonReduction(_ name: String, for element: Element) -> String? {
    guard element.category == .float else { return nil }
    return "return __builtin_neon_\(name)_\(element.cSuffix)((\(neonVector(element.cSuffix)))a);"
}

func neonReducedExtremumOrNaN(_ name: String, for element: Element) -> String? {
    guard element.category == .float else { return nil }
    let reduced = "__builtin_neon_\(name)_\(element.cSuffix)((\(neonVector(element.cSuffix)))a)"
    return """
        const \(element.cType) reduced = \(reduced);
        return reduced != reduced ? \(scalarNaN(of: element)) : reduced;
        """
}

func neonPairExtremum(comparing symbol: String, for element: Element) -> String? {
    guard element.bits == 64, element.category != .float else { return nil }
    return "return a[0] \(symbol) a[1] ? a[0] : a[1];"
}

func neonTableLookup(_ bytes: String, _ indices: String, for element: Element) -> String {
    neonBuiltin("vqtbl1q_v", [bytes, indices], code: 48, for: element)
}

func neonTwoTablesLookup(
    _ first: String,
    _ second: String,
    _ indices: String,
    for element: Element
) -> String {
    neonBuiltin("vqtbl2q_v", [first, second, indices], code: 48, for: element)
}

func lookupBroadcastBytes(lane bytes: Int, width: Int) -> [UInt8] {
    (0..<width).map { UInt8(($0 % 16) / bytes * bytes) }
}

func lookupByteOffsets(lane bytes: Int, width: Int) -> [UInt8] {
    (0..<width).map { UInt8($0 % bytes) }
}

func neonLaneByteIndices(for element: Element) -> (statements: String, indices: String) {
    guard element.bits > 8 else { return ("", "indices") }
    let bytes = element.bits / 8
    let broadcast = lookupBroadcastBytes(lane: bytes, width: element.width).map(String.init)
    let offsets = lookupByteOffsets(lane: bytes, width: element.width).map(String.init)
    let byte = unsignedElement(bits: 8)
    let type = byte.cVector
    let lanes = neonBuiltin("vqtbl1q_v", ["indices", "broadcast"], code: 48, for: byte)
    return (
        """
        const \(type) broadcast = {\(broadcast.joined(separator: ", "))};
        const \(type) offsets = {\(offsets.joined(separator: ", "))};
        const \(type) laneIndices = \(lanes);
        const \(type) byteIndices = (laneIndices << \(bytes.trailingZeroBitCount)) + offsets;
        """,
        "byteIndices"
    )
}

func neonTableLookupLanes(for element: Element) -> String {
    let lookup = neonLaneByteIndices(for: element)
    let table = vectorResult(neonTableLookup("a", lookup.indices, for: element), for: element)
    return [lookup.statements, table].filter { !$0.isEmpty }.joined(separator: "\n")
}

func neonTwoTablesLookupLanes(for element: Element) -> String {
    let lookup = neonLaneByteIndices(for: element)
    let tables = neonTwoTablesLookup("a", "b", lookup.indices, for: element)
    return [lookup.statements, vectorResult(tables, for: element)]
        .filter { !$0.isEmpty }.joined(separator: "\n")
}

let neonNibbles = """
    typedef uint16_t wide_vector __attribute__((vector_size(16)));
    typedef uint8_t narrow_vector __attribute__((vector_size(8)));
    const narrow_vector narrowed = __builtin_convertvector((wide_vector)mask >> 4, narrow_vector);
    const uint64_t nibbles = __builtin_bit_cast(uint64_t, narrowed);
    """

func neonFirstTrueIndex(for element: Element) -> String {
    """
    \(neonNibbles)
    return nibbles == 0 ? -1 : (intptr_t)(__builtin_ctzll(nibbles) / \(element.bits / 2));
    """
}

let sveAllPattern = 31

func sveType(of element: Element) -> String {
    switch element.category {
    case .unsignedInteger: return "__SVUint\(element.bits)_t"
    case .signedInteger: return "__SVInt\(element.bits)_t"
    case .float: return "__SVFloat\(element.bits)_t"
    case .float16: return "__SVFloat16_t"
    case .bfloat16: return "__SVBfloat16_t"
    }
}

func sveSuffix(of element: Element) -> String {
    element.category == .signedInteger ? "s\(element.bits)" : element.cSuffix
}

func sveBuiltin(
    _ name: String,
    _ arguments: [String],
    for element: Element,
    predication: String? = nil
) -> String {
    let parts = [name, sveSuffix(of: element)] + (predication.map { [$0] } ?? [])
    return "__builtin_sve_sv\(parts.joined(separator: "_"))(\(arguments.joined(separator: ", ")))"
}

func sveFirstLane(_ name: String, for element: Element) -> String {
    element.category == .bfloat16 ? "__builtin_bit_cast(__bf16, \(name)[0])" : "\(name)[0]"
}

func sveSplatOperand(_ name: String, for element: Element) -> String {
    let operand = "(\(sveVector(element.cSuffix)))\(name)"
    let duplicated = sveBuiltin("dup_n", [sveFirstLane(name, for: element)], for: element)
    let condition = sveSplatCondition(name, nil, for: element)
    return "(\(condition) ? \(duplicated) : (\(sveType(of: element)))\(operand))"
}

func sveIndexOperand(_ name: String, for element: Element) -> String {
    let signed = signedElement(of: element)
    guard isInteger64(signed) else { return sveOperand(name, for: signed) }
    let unsigned = unsignedElement(of: element)
    let condition = "\(cFunctionName("sveSplat", unsigned))((\(unsigned.cVector))\(name))"
    let duplicated = sveBuiltin("dup_n", ["\(name)[0]"], for: signed)
    let operand = sveOperand(name, for: signed)
    return "(\(condition) ? \(duplicated) : (\(sveType(of: signed)))\(operand))"
}

func sveOperand(_ name: String, for element: Element, splat: Bool = false) -> String {
    guard splat, isInteger64(element) else { return "(\(sveVector(element.cSuffix)))\(name)" }
    return sveSplatOperand(name, for: element)
}

func sveResult(_ call: String, for element: Element) -> String {
    "(\(element.cVector))(\(sveVector(element.cSuffix)))\(call)"
}

func sveAllLanes(of element: Element) -> String {
    "__builtin_sve_svptrue_pat_b\(element.bits)(\(sveAllPattern))"
}

func sveShift(
    _ instruction: String,
    by amount: String? = nil,
    of operand: String? = nil,
    for element: Element
) -> String {
    let arguments = [
        sveAllLanes(of: element),
        operand ?? sveOperand("a", for: element, splat: true),
        amount ?? "(\(element.cUnsignedLane))bits",
    ]
    let shifted = sveBuiltin("\(instruction)_n", arguments, for: element, predication: "x")
    return vectorResult(sveResult(shifted, for: element), for: element)
}

func sveShiftByLanes(_ instruction: String, for element: Element) -> String {
    let unsigned = unsignedElement(of: element)
    let arguments = [
        sveAllLanes(of: element),
        sveOperand("a", for: element, splat: true),
        sveReinterpreted(sveSplatOperand("b", for: element), from: element, to: unsigned),
    ]
    let shifted = sveBuiltin(instruction, arguments, for: element, predication: "x")
    return vectorResult(sveResult(shifted, for: element), for: element)
}

func sveReinterpreted(_ call: String, from source: Element, to target: Element) -> String {
    guard sveSuffix(of: source) != sveSuffix(of: target) else { return call }
    return "__builtin_sve_reinterpret_\(sveSuffix(of: target))_\(sveSuffix(of: source))(\(call))"
}

func sveReinterpretedSplat(_ name: String, from source: Element, to target: Element) -> String {
    guard differentHalfPrecisions(source, target) else {
        return sveReinterpreted(sveSplatOperand(name, for: source), from: source, to: target)
    }
    let words = unsignedElement(of: source)
    let view = source.category == .float16 ? "((\(words.cVector))\(name))" : name
    return sveReinterpreted(sveSplatOperand(view, for: words), from: words, to: target)
}

func sveNegatedCounts(_ counts: String, for element: Element) -> String {
    let signed = signedElement(of: element)
    return sveBuiltin(
        "neg",
        [sveAllLanes(of: element), counts],
        for: signed,
        predication: "x"
    )
}

func sveRoundingShift(counts: String, for element: Element) -> String {
    let arguments = [sveAllLanes(of: element), sveOperand("a", for: element, splat: true), counts]
    let shifted = sveBuiltin("rshl", arguments, for: element, predication: "x")
    return vectorResult(sveResult(shifted, for: element), for: element)
}

func sveRoundingShiftByLanes(for element: Element) -> String {
    let signed = signedElement(of: element)
    let counts = sveReinterpreted(sveSplatOperand("b", for: element), from: element, to: signed)
    return sveRoundingShift(counts: sveNegatedCounts(counts, for: element), for: element)
}

func sveRoundingShiftBySame(for element: Element) -> String {
    let signed = signedElement(of: element)
    let duplicated = sveBuiltin("dup_n", ["(\(element.cType))bits"], for: element)
    let counts =
        element.category == .signedInteger
        ? duplicated : sveReinterpreted(duplicated, from: element, to: signed)
    return sveRoundingShift(counts: sveNegatedCounts(counts, for: element), for: element)
}

func sveRotatedVector(for element: Element) -> String {
    sveReinterpreted(
        sveOperand("a", for: element, splat: true),
        from: element,
        to: unsignedElement(of: element)
    )
}

func sveRotatedByLanes(left: Bool, for element: Element) -> String {
    let unsigned = unsignedElement(of: element)
    let signed = signedElement(of: element)
    let all = sveAllLanes(of: element)
    let type = sveType(of: unsigned)
    let mask = sveBuiltin("dup_n", ["(\(unsigned.cType))\(element.bits - 1)"], for: unsigned)
    let counts = sveReinterpreted("counts", from: element, to: unsigned)
    let negated = sveReinterpreted(
        sveNegatedCounts(sveReinterpreted("counts", from: element, to: signed), for: element),
        from: signed,
        to: unsigned
    )
    func masked(_ operand: String) -> String {
        sveBuiltin("and", [all, operand, "mask"], for: unsigned, predication: "x")
    }
    let (directName, oppositeName) =
        left ? ("shiftLeft", "shiftRight") : ("shiftRight", "shiftLeft")
    let shiftedLeft = sveBuiltin(
        "lsl",
        [all, "vector", "shiftLeft"],
        for: unsigned,
        predication: "x"
    )
    let shiftedRight = sveBuiltin(
        "lsr",
        [all, "vector", "shiftRight"],
        for: unsigned,
        predication: "x"
    )
    let rotated = sveBuiltin(
        "orr",
        [all, shiftedLeft, shiftedRight],
        for: unsigned,
        predication: "x"
    )
    return """
        const \(type) mask = \(mask);
        const \(sveType(of: element)) counts = \(sveSplatOperand("b", for: element));
        const \(type) \(directName) = \(masked(counts));
        const \(type) \(oppositeName) = \(masked(negated));
        const \(type) vector = \(sveRotatedVector(for: element));
        \(vectorResult(sveResult(rotated, for: unsigned), for: element))
        """
}

func sveRotatedBySame(left: Bool, for element: Element) -> String {
    let unsigned = unsignedElement(of: element)
    let all = sveAllLanes(of: element)
    let direct = "const int \(left ? "shiftLeft" : "shiftRight") = bits & \(element.bits - 1);"
    let opposite =
        "const int \(left ? "shiftRight" : "shiftLeft") = (int)((0u - (unsigned)bits) & \(element.bits - 1)u);"
    let lane = unsigned.cUnsignedLane
    let shiftedLeft = sveBuiltin(
        "lsl_n",
        [all, "vector", "(\(lane))shiftLeft"],
        for: unsigned,
        predication: "x"
    )
    let shiftedRight = sveBuiltin(
        "lsr_n",
        [all, "vector", "(\(lane))shiftRight"],
        for: unsigned,
        predication: "x"
    )
    let rotated = sveBuiltin(
        "orr",
        [all, shiftedLeft, shiftedRight],
        for: unsigned,
        predication: "x"
    )
    return """
        const \(sveType(of: unsigned)) vector = \(sveRotatedVector(for: element));
        \(direct)
        \(opposite)
        \(vectorResult(sveResult(rotated, for: unsigned), for: element))
        """
}

enum SveImmediate {
    case arithmetic
    case signed
    case unsigned
    case comparison
}

func sveImmediateFits(_ lane: String, _ immediate: SveImmediate, for element: Element) -> String? {
    let narrow = element.bits == 16 || element.bits == 32
    switch immediate {
    case .comparison:
        return element.category == .signedInteger
            ? "(\(lane) >= -16 && \(lane) <= 15)" : "(\(lane) <= 127)"
    case .arithmetic where narrow:
        let value = "(\(element.cUnsignedLane))\(lane)"
        return "(\(value) <= 255 || ((\(value) & 255) == 0 && \(value) <= 65280))"
    case .signed where narrow:
        let value = "(\(element.cMaskLane))\(lane)"
        return "(\(value) >= -128 && \(value) <= 127)"
    case .unsigned where narrow:
        return "(\(element.cUnsignedLane))\(lane) <= 255"
    default:
        return nil
    }
}

func sveSplatCondition(
    _ name: String,
    _ immediate: SveImmediate?,
    for element: Element
) -> String {
    let splat = "\(cFunctionName("sveSplat", element))(\(name))"
    guard let immediate, let fits = sveImmediateFits("\(name)[0]", immediate, for: element) else {
        return splat
    }
    return "\(splat) && \(fits)"
}

func sveSplatBranch(
    _ name: String,
    _ immediate: SveImmediate?,
    for element: Element,
    _ body: (String) -> String
) -> String {
    """
    if (\(sveSplatCondition(name, immediate, for: element))) {
      \(body(sveBuiltin("dup_n", [sveFirstLane(name, for: element)], for: element)))
    }
    """
}

func sveSplatBinary(
    _ name: String,
    _ immediate: SveImmediate?,
    operands: (first: String, second: String) = ("a", "b"),
    commutative: Bool = true,
    splattingFirst: Bool = true,
    predicated: Bool = true,
    for element: Element
) -> String? {
    guard element.category != .float else { return nil }
    func combined(_ first: String, _ second: String) -> String {
        let arguments = (predicated ? [sveAllLanes(of: element)] : []) + [first, second]
        let call = sveBuiltin(name, arguments, for: element, predication: predicated ? "x" : nil)
        return vectorResult(sveResult(call, for: element), for: element)
    }
    let first = sveOperand(operands.first, for: element)
    let second = sveOperand(operands.second, for: element)
    let branches = [
        sveSplatBranch(operands.second, immediate, for: element) { combined(first, $0) },
        splattingFirst
            ? sveSplatBranch(operands.first, immediate, for: element) {
                commutative ? combined(second, $0) : combined($0, second)
            } : nil,
    ]
    return branches.compactMap { $0 }.joined(separator: "\n")
}

func sveConstantFunction(for element: Element) -> String {
    let bits = element.hasOpaqueVector ? "v" : "(\(element.cUnsignedVector))v"
    let function = cFunction(
        returns: "bool",
        name: cFunctionName("sveConstant", element),
        parameters: ["\(element.cVector) v"],
        body: "return __builtin_constant_p(__builtin_reduce_or(\(bits)));"
    )
    return "#if \(sve2_128Condition)\n\(function)#endif\n"
}

func sveReduction(_ name: String, for element: Element) -> String? {
    guard isInteger64(element) else { return nil }
    let reduced = sveBuiltin(
        name,
        [sveAllLanes(of: element), sveOperand("a", for: element)],
        for: element
    )
    return "return \(reduced);"
}

func sveReversed(for element: Element) -> String? {
    guard element.bits < 64 else { return nil }
    let reversed = sveBuiltin("rev", [sveOperand("a", for: element)], for: element)
    return vectorResult(sveResult(reversed, for: element), for: element)
}

func sveLaneIndices(for element: Element) -> String {
    sveOperand("indices", for: unsignedElement(of: element))
}

func sveTableLookupLanes(for element: Element) -> String {
    let operands = [sveOperand("a", for: element), sveLaneIndices(for: element)]
    let lookup = sveBuiltin("tbl", operands, for: element)
    return vectorResult(sveResult(lookup, for: element), for: element)
}

func sveTableLookupBytes(for element: Element) -> String {
    guard element.bits > 8 else { return sveTableLookupLanes(for: element) }
    let bytes = unsignedElement(bits: 8)
    let operands = [sveOperand("a", for: bytes), sveOperand("indices", for: bytes)]
    let lookup = sveBuiltin("tbl", operands, for: bytes)
    return vectorResult("(\(element.cVector))\(sveResult(lookup, for: bytes))", for: element)
}

func sveTwoTablesLookupLanes(for element: Element) -> String {
    let operands = [sveOperand("a", for: element), sveOperand("b", for: element)]
    let tables = sveBuiltin("create2", operands, for: element)
    let lookup = sveBuiltin("tbl2", [tables, sveLaneIndices(for: element)], for: element)
    return vectorResult(sveResult(lookup, for: element), for: element)
}

func sveComparisonSplat(_ name: String, mirrored: String, for element: Element) -> String? {
    guard isInteger64(element) else { return nil }
    let unsigned = unsignedElement(of: element)
    func selected(_ comparison: String) -> String {
        let lanes = sveBuiltin(
            "dup_n",
            [comparison, "(\(unsigned.cUnsignedLane))-1"],
            for: unsigned,
            predication: "z"
        )
        return maskResult(
            "(\(element.cMask))(\(sveVector(unsigned.cSuffix)))\(lanes)",
            for: element
        )
    }
    let all = sveAllLanes(of: element)
    return [
        sveSplatBranch("b", .comparison, for: element) {
            selected(sveBuiltin(name, [all, sveOperand("a", for: element), $0], for: element))
        },
        sveSplatBranch("a", .comparison, for: element) {
            selected(sveBuiltin(mirrored, [all, sveOperand("b", for: element), $0], for: element))
        },
    ].joined(separator: "\n")
}

func sveAllFalse(for element: Element) -> String? {
    guard element.bits == 64 else { return nil }
    let all = sveAllLanes(of: element)
    let unsigned = unsignedElement(of: element)
    let nonzero = sveBuiltin(
        "cmpne_n",
        [all, "(\(sveVector(unsigned.cSuffix)))mask", "0"],
        for: unsigned
    )
    return "return !__builtin_sve_svptest_any(\(all), \(nonzero));"
}

func sveAllLanesEqual(
    _ operand: String,
    to scalar: String,
    splat: Bool,
    for element: Element
) -> String {
    let compared = sveBuiltin(
        "cmpeq_n",
        [sveAllLanes(of: element), sveOperand(operand, for: element, splat: splat), scalar],
        for: element
    )
    let pattern = min(element.laneCount, 9)
    let vector = "__builtin_sve_svptrue_pat_b\(element.bits)(\(pattern))"
    let count = "__builtin_sve_svcntp_b\(element.bits)(\(vector), equal)"
    return """
        const __SVBool_t equal = \(compared);
        return \(count) == \(element.laneCount);
        """
}

func sveSplatFunction(for element: Element) -> String {
    let bits = element.category == .float ? "(\(unsignedBits("v", of: element)))" : "v"
    let function = cFunction(
        returns: "bool",
        name: cFunctionName("sveSplat", element),
        parameters: ["\(element.cVector) v"],
        body: """
            const bool splat = __builtin_reduce_and(\(bits) == \(bits)[0]) != 0;
            return __builtin_constant_p(splat) && splat;
            """
    )
    return "#if \(sve2_128Condition)\n\(function)#endif\n"
}

func sveBinary(_ name: String, for element: Element) -> String {
    let operands = [sveOperand("a", for: element), sveOperand("b", for: element)]
    let combined = sveBuiltin(
        name,
        [sveAllLanes(of: element)] + operands,
        for: element,
        predication: "x"
    )
    let plain = vectorResult(sveResult(combined, for: element), for: element)
    let bodies = [sveSplatBinary(name, nil, for: element), plain].compactMap { $0 }
    return bodies.joined(separator: "\n")
}

func sveAndXor(for element: Element) -> String? {
    guard element.bits == 64 else { return nil }
    let exclusive = "\(cFunctionName("bitwiseXor", element))(rawB, rawC)"
    return "return \(cFunctionName("bitwiseAnd", element))(rawA, \(exclusive));"
}

func sveWideBitwise(
    _ name: String,
    _ operands: [String],
    for element: Element
) -> String? {
    guard element.category == .float else { return nil }
    let wide = unsignedElement(bits: 64)
    let arguments = operands.map { "(\(wide.cRawVector))\(rawName($0))" }
    let call = "\(cFunctionName(name, wide))(\(arguments.joined(separator: ", ")))"
    return "return (\(element.cRawVector))\(call);"
}

func sveBitwiseResult(_ call: String, for element: Element) -> String {
    vectorResult(sveResult(call, for: element), for: element)
}

func sveTernaryBitwise(
    _ name: String,
    _ operands: [String] = ["a", "b", "c"],
    for element: Element
) -> String {
    let arguments = operands.map { sveOperand($0, for: element, splat: true) }
    return sveBitwiseResult(sveBuiltin(name, arguments, for: element), for: element)
}

func sveNestedBitwise(
    _ outer: String,
    _ inner: String,
    _ operands: [String] = ["a", "b", "c"],
    for element: Element
) -> String {
    let all = sveAllLanes(of: element)
    let arguments = operands.map { sveOperand($0, for: element, splat: true) }
    let nested = sveBuiltin(inner, [all] + arguments.dropFirst(), for: element, predication: "x")
    let combined = sveBuiltin(
        outer,
        [all, arguments[0], nested],
        for: element,
        predication: "x"
    )
    return sveBitwiseResult(combined, for: element)
}

func sveMaskedBitwiseOtherwise(_ name: String, for element: Element) -> String? {
    guard element.bits == 64 else { return nil }
    let operation = "\(cFunctionName(name, element))(rawA, rawB)"
    return "return \(cFunctionName("selecting", element))(rawMask, \(operation), rawOtherwise);"
}

func sveBitwiseSplat(
    _ name: String,
    operands: (first: String, second: String) = ("a", "b"),
    commutative: Bool = true,
    splattingFirst: Bool = true,
    for element: Element
) -> String? {
    guard element.bits == 8 || element.bits == 64 else { return nil }
    return sveSplatBinary(
        name,
        nil,
        operands: operands,
        commutative: commutative,
        splattingFirst: splattingFirst,
        for: element
    )
}

func sveExtremumImmediate(for element: Element) -> SveImmediate {
    element.category == .signedInteger ? .signed : .unsigned
}

enum SveBlockedLane {
    case notANumber
    case one
    case minusOne
    case zero
    case minusZero
    case infinity
    case minusInfinity
}

func sveBlockedLiteral(_ lane: SveBlockedLane, for element: Element) -> String? {
    let suffix = element.bits == 32 ? "f" : ""
    switch lane {
    case .notANumber: return nil
    case .one: return "1.0\(suffix)"
    case .minusOne: return "-1.0\(suffix)"
    case .zero: return "0.0\(suffix)"
    case .minusZero: return "-0.0\(suffix)"
    case .infinity: return infinity(of: element)
    case .minusInfinity: return "-\(infinity(of: element))"
    }
}

struct SveBlockedLanes {
    let first: [SveBlockedLane]
    let second: [SveBlockedLane]

    static func both(_ lanes: [SveBlockedLane]) -> SveBlockedLanes {
        SveBlockedLanes(first: lanes, second: lanes)
    }

    static let adding = SveBlockedLanes.both([.minusZero])
    static let subtracting = SveBlockedLanes(
        first: [.minusZero, .notANumber],
        second: [.zero, .notANumber]
    )
    static let multiplying = SveBlockedLanes.both([.one, .minusOne])
    static let dividing = SveBlockedLanes(
        first: [.notANumber],
        second: [.notANumber, .one, .minusOne]
    )

    func blockingFirst(_ lanes: [SveBlockedLane]) -> SveBlockedLanes {
        SveBlockedLanes(first: first + lanes, second: second)
    }
}

struct SveMaskedArithmetic {
    let symbol: String
    let merged: SveBlockedLanes
    let zeroed: SveBlockedLanes
}

func sveBlockedCondition(
    _ lanes: [SveBlockedLane],
    of operand: String,
    for element: Element
) -> [String] {
    lanes.map { lane in
        guard let literal = sveBlockedLiteral(lane, for: element) else {
            return "\(cFunctionName("constantNaN", element))(\(operand))"
        }
        return "\(cFunctionName("constantLane", element))(\(operand), \(literal))"
    }
}

func comparableOperand(_ operand: String, for element: Element) -> String {
    element.category == .float16 ? "((native_vector)\(operand))" : operand
}

func comparableDeclarations(for element: Element) -> String {
    element.category == .float16 ? "\(halfPrecisionNativeVector(for: element))\n" : ""
}

func constantNaNFunction(for element: Element) -> String {
    let v = comparableOperand("v", for: element)
    let function = cFunction(
        returns: "bool",
        name: cFunctionName("constantNaN", element),
        parameters: ["\(element.cVector) v"],
        body: """
            \(comparableDeclarations(for: element))const bool found = __builtin_reduce_or(\(v) != \(v)) != 0;
            return __builtin_constant_p(found) && found;
            """
    )
    return element.category == .float16 ? "#if \(sve2_128Condition)\n\(function)#endif\n" : function
}

func sveConstantNumbersFunction(for element: Element) -> String {
    let (a, b) = (comparableOperand("a", for: element), comparableOperand("b", for: element))
    let function = cFunction(
        returns: "bool",
        name: cFunctionName("sveConstantNumbers", element),
        parameters: ["\(element.cVector) a", "\(element.cVector) b"],
        body: """
            \(comparableDeclarations(for: element))const bool found = __builtin_reduce_or((\(a) != \(a)) | (\(b) != \(b))) != 0;
            return __builtin_constant_p(found) && !found;
            """
    )
    return "#if \(sve2_128Condition)\n\(function)#endif\n"
}

func constantLaneFunction(for element: Element) -> String {
    let laneBits = "__builtin_bit_cast(\(element.cUnsignedLane), lane)"
    let function = cFunction(
        returns: "bool",
        name: cFunctionName("constantLane", element),
        parameters: ["\(element.cVector) v", "\(element.cType) lane"],
        body: """
            const bool found = __builtin_reduce_or(\(unsignedBits("v", of: element)) == \(laneBits)) != 0;
            return __builtin_constant_p(found) && found;
            """
    )
    return element.category == .float16 ? "#if \(sve2_128Condition)\n\(function)#endif\n" : function
}

func sveConstantBarrier(
    blocking blocked: SveBlockedLanes,
    for element: Element,
    _ operation: (_ first: String, _ second: String) -> String
) -> String {
    let conditions =
        sveBlockedCondition(blocked.first, of: "a", for: element)
        + sveBlockedCondition(blocked.second, of: "b", for: element)
    guard !conditions.isEmpty else { return operation("a", "b") }
    let numbers = "\(cFunctionName("sveConstantNumbers", element))(a, b)"
    let hidden = [
        (name: "first", source: "a", lanes: blocked.first),
        (name: "second", source: "b", lanes: blocked.second),
    ].filter { !$0.lanes.isEmpty }
    let declarations = hidden.map { "\(element.cVector) \($0.name) = \($0.source);" }
    let registers = hidden.map { "\"+w\"(\($0.name))" }
    let first = blocked.first.isEmpty ? "a" : "first"
    let second = blocked.second.isEmpty ? "b" : "second"
    return """
        if (!\(numbers) && (\(conditions.joined(separator: " || ")))) {
          \(declarations.joined(separator: "\n  "))
          __asm__("" : \(registers.joined(separator: ", ")));
          \(operation(first, second))
        }
        \(operation("a", "b"))
        """
}

func sveConstantExtremum(
    _ name: String,
    blocking lane: SveBlockedLane,
    for element: Element
) -> String {
    sveConstantBarrier(blocking: .both([.notANumber, lane]), for: element) {
        element.category == .float16
            ? float16NativeExtremum(name, of: [$0, $1], for: element)
            : neonExtremum(name, of: [$0, $1], for: element)
    }
}

func sveConstantMagnitudeExtremum(_ name: String, for element: Element) -> String? {
    guard element.category == .float || element.category == .float16 else { return nil }
    return sveConstantBarrier(blocking: .both([.notANumber]), for: element) {
        magnitudeExtremum(name, of: ($0, $1), for: element)
    }
}

func sveFloatArithmetic(
    _ symbol: String,
    _ first: String,
    _ second: String,
    for element: Element
) -> String {
    guard element.category == .float16 else {
        return arithmetic(symbol, first, second, for: element)
    }
    return "(\(element.cVector))((native_vector)\(first) \(symbol) (native_vector)\(second))"
}

func sveConstantArithmetic(
    _ symbol: String,
    blocking blocked: SveBlockedLanes,
    for element: Element
) -> String? {
    guard element.category == .float || element.category == .float16 else { return nil }
    return comparableDeclarations(for: element)
        + sveConstantBarrier(blocking: blocked, for: element) {
            vectorResult(sveFloatArithmetic(symbol, $0, $1, for: element), for: element)
        }
}

func sveMaskedArithmetic(
    _ masked: SveMaskedArithmetic,
    merging: Bool,
    for element: Element
) -> String? {
    guard element.category == .float || element.category == .float16 else { return nil }
    let blocked = merging ? masked.merged : masked.zeroed
    return comparableDeclarations(for: element)
        + sveConstantBarrier(blocking: blocked, for: element) {
            let operation = "(\(sveFloatArithmetic(masked.symbol, $0, $1, for: element)))"
            return maskedSelecting(operation, merging: merging, for: element)
        }
}

func sveExtremum(_ name: String, blocking lane: SveBlockedLane, for element: Element) -> String? {
    guard element.category != .float else {
        return sveConstantExtremum(name, blocking: lane, for: element)
    }
    guard element.bits == 64 else { return nil }
    return sveBinary(name, for: element)
}

func sveMultiplyAdding(
    _ name: String = "mad",
    adding add: String = "c",
    for element: Element
) -> String {
    let (mul, x) = ("a", "b")
    let operands = [x, mul, add].map { sveOperand($0, for: element, splat: true) }
    let arguments = [sveAllLanes(of: element)] + operands
    let fused = sveBuiltin(name, arguments, for: element, predication: "x")
    return vectorResult(sveResult(fused, for: element), for: element)
}

func svePredicated(_ name: String, _ operands: [String], for element: Element) -> String {
    sveBuiltin(name, ["all"] + operands, for: element, predication: "x")
}

func sveMultiplyAddingLow52Bits(for element: Element) -> String {
    func predicated(_ name: String, _ operands: String...) -> String {
        svePredicated(name, operands, for: element)
    }
    let a = sveOperand("a", for: element, splat: true)
    let b = sveOperand("b", for: element, splat: true)
    let c = sveOperand("c", for: element, splat: true)
    let mask = (UInt64(1) << UInt64(multiplyAddedBits)) - 1
    let kept = predicated(
        "and",
        predicated("mul", a, b),
        sveBuiltin("dup_n", ["0x\(String(mask, radix: 16))"], for: element)
    )
    let sum = predicated("add", kept, c)
    return """
        const __SVBool_t all = \(sveAllLanes(of: element));
        \(vectorResult(sveResult(sum, for: element), for: element))
        """
}

func sveMultiplyAddingHigh52Bits(for element: Element) -> String {
    func predicated(_ name: String, _ operands: String...) -> String {
        svePredicated(name, operands, for: element)
    }
    let a = sveOperand("a", for: element, splat: true)
    let b = sveOperand("b", for: element, splat: true)
    let c = sveOperand("c", for: element, splat: true)
    let low = predicated("lsr_n", predicated("mul", a, b), "\(multiplyAddedBits)")
    let high = predicated("lsl_n", predicated("mulh", a, b), "\(element.bits - multiplyAddedBits)")
    let sum = predicated("add", predicated("orr", low, high), c)
    return """
        const __SVBool_t all = \(sveAllLanes(of: element));
        \(vectorResult(sveResult(sum, for: element), for: element))
        """
}

func sveActiveLanes(_ count: String, for element: Element) -> String {
    "__builtin_sve_svwhilelt_b\(element.bits)_u32(0, (uint32_t)(\(count)))"
}

func sveClampedLanes(for element: Element) -> String {
    "__builtin_sve_svwhilelt_b\(element.bits)_u64(0, (uint64_t)count)"
}

func sveFirstLanes(for element: Element) -> String {
    let unsigned = unsignedElement(of: element)
    let selected = sveBuiltin(
        "sel",
        [
            sveActiveLanes("count", for: element),
            sveBuiltin("dup_n", ["(\(unsigned.cType))-1"], for: unsigned),
            sveBuiltin("dup_n", ["0"], for: unsigned),
        ],
        for: unsigned
    )
    return maskResult("(\(element.cMask))(\(sveVector(unsigned.cSuffix)))\(selected)", for: element)
}

func sveSlideUp(filling: Bool, for element: Element) -> String {
    let fill =
        filling
        ? sveOperand("fill", for: element, splat: true) : sveBuiltin("dup_n", ["0"], for: element)
    let slid = sveBuiltin(
        "splice",
        [sveActiveLanes("lanes", for: element), fill, sveOperand("a", for: element, splat: true)],
        for: element
    )
    return vectorResult(sveResult(slid, for: element), for: element)
}

func sveIota(for element: Element) -> String? {
    guard element.category != .float else { return nil }
    return vectorResult(
        sveResult(sveBuiltin("index", ["value", "1"], for: element), for: element),
        for: element
    )
}

func sveExtendingLoad(_ active: String, from narrow: Element, to wide: Element) -> String {
    let signedness = narrow.category == .signedInteger ? "s" : "u"
    let width = ["b", "h", "w"][narrow.bits.trailingZeroBitCount - 3]
    let load = sveBuiltin("ld1\(signedness)\(width)", [active, "from"], for: wide)
    return vectorResult(sveResult(load, for: wide), for: wide)
}

func sveLoadFirstConvertingWidening(from narrow: Element, to wide: Element) -> String {
    let active = sveClampedLanes(for: wide)
    let words = unsignedElement(of: wide)
    let bits = unsignedElement(of: narrow)
    let load = sveBuiltin("ld1uw", [active, "(const \(bits.cType)*)from"], for: words)
    let loaded = "__builtin_sve_reinterpret_\(sveSuffix(of: narrow))_u64(\(load))"
    let name = "svcvt_\(sveSuffix(of: wide))_\(sveSuffix(of: narrow))_x"
    let converted = "__builtin_sve_\(name)(\(sveAllLanes(of: wide)), \(loaded))"
    return """
        if (__builtin_constant_p(count)) {
        \(indented(neonLoadFirstWidening(from: narrow, to: wide)))
        }
        \(vectorResult(sveResult(converted, for: wide), for: wide))
        """
}

func sveLoadFirstWidening(from narrow: Element, to wide: Element) -> String? {
    guard narrow.category == .float || wide.category == .float else {
        return sveExtendingLoad(sveClampedLanes(for: wide), from: narrow, to: wide)
    }
    return sveLoadFirstConvertingWidening(from: narrow, to: wide)
}

func sveLoadFirst(for element: Element, spanned: Bool = false) -> String {
    let active = spanned ? sveClampedLanes(for: element) : sveActiveLanes("count", for: element)
    let loaded = sveBuiltin("ld1", [active, "from"], for: element)
    return vectorResult(sveResult(loaded, for: element), for: element)
}

func sveStoreFirst(for element: Element) -> String {
    let stored = sveBuiltin(
        "st1",
        [sveClampedLanes(for: element), "to", sveOperand("a", for: element)],
        for: element
    )
    return "\(stored);"
}

enum ArmLevel: Int {
    case neon = 1
    case sve2_128
}

enum X86Level: Int, CaseIterable, Comparable {
    case sse2 = 1
    case ssse3
    case sse4
    case avx2
    case avx3
    case avx3dl

    static func < (first: X86Level, second: X86Level) -> Bool {
        first.rawValue < second.rawValue
    }

    var width: Int {
        switch self {
        case .sse2, .ssse3, .sse4: return 16
        case .avx2: return 32
        case .avx3, .avx3dl: return 64
        }
    }

    var inherited: [X86Level] {
        X86Level.allCases.filter { $0 <= self && $0.width == width }.reversed()
    }
}

enum SlideDirection: String {
    case up
    case down
}

enum Reduction {
    case sum
    case minimum
    case maximum

    var combiningOp: String {
        switch self {
        case .sum: return "adding"
        case .minimum: return "minimum"
        case .maximum: return "maximum"
        }
    }
}

func prefixed(_ prefix: String, _ name: String) -> String {
    prefix.isEmpty ? name : "\(prefix)\(uppercasedFirst(name))"
}

func x86Builtin(
    _ name: String,
    _ operands: [(value: String, type: String)],
    returning type: String
) -> String {
    let casts = operands.map { "(\($0.type))\($0.value)" }
    return "(\(type))__builtin_ia32_\(name)(\(casts.joined(separator: ", ")))"
}

func x86Builtin(
    _ name: String,
    _ arguments: [String],
    as suffix: String,
    returning type: String
) -> String {
    x86Builtin(name, arguments.map { (value: $0, type: x86Vector(suffix)) }, returning: type)
}

func x86Bits(_ width: Int) -> String {
    "\(width * 8)"
}

func x86UnsuffixedBits(_ width: Int) -> String {
    width == 16 ? "" : x86Bits(width)
}

let x86CurrentRounding = 4
let x86FloorRounding = 9

func x86LaneLetter(bits: Int) -> String {
    guard let letter = [8: "b", 16: "w", 32: "d", 64: "q"][bits] else {
        fatalError("There is no x86 letter for \(bits)-bit lanes")
    }
    return letter
}

func x86LaneSuffix(of element: Element) -> String {
    element.category == .float ? element.cSuffix : "i\(element.bits)"
}

func x86LaneType(of element: Element) -> String {
    guard let lane = x86Lanes.first(where: { $0.suffix == x86LaneSuffix(of: element) })?.lane else {
        fatalError("There is no x86 lane type of \(element.swiftType)")
    }
    return lane
}

func x86MaskedPointee(of register: String, width: Int, for element: Element) -> String {
    width == 64 && (element.category == .float || element.bits >= 32)
        ? x86LaneType(of: element) : register
}

func x86MaskType(lanes: Int) -> String {
    switch lanes {
    case 64: return "unsigned long long"
    case 32: return "unsigned int"
    case 16: return "unsigned short"
    default: return "unsigned char"
    }
}

func x86FirstLanesBits(lanes: Int, count: String = "count", all: String = "~0ull") -> String {
    "__builtin_ia32_bzhi_di(\(all), \(clampedCount(count, to: lanes)))"
}

func x86MaskedAccessName(_ access: String, width: Int, for element: Element) -> String {
    let bits = x86Bits(width)
    guard element.category != .float else {
        return "\(access)u\(element.bits == 32 ? "ps" : "pd")\(bits)_mask"
    }
    guard let suffix = [8: "qi", 16: "hi", 32: "si", 64: "di"][element.bits] else {
        fatalError("There is no x86 masked access of \(element.bits)-bit lanes")
    }
    return "\(access)dqu\(suffix)\(bits)_mask"
}

func x86ShiftCount(_ amount: String) -> String {
    compoundLiteral(x86Block("i32"), [amount, "0", "0", "0"])
}

func x86ShiftName(_ instruction: String, laneBits: Int) -> String {
    guard let suffix = [16: "w", 32: "d", 64: "q"][laneBits] else {
        fatalError("There is no x86 shift of \(laneBits)-bit lanes")
    }
    return "\(instruction)\(suffix)"
}

func x86RegisterShift(
    _ instruction: String,
    _ operand: String,
    by amount: String,
    laneBits: Int,
    width: Int,
    returning type: String
) -> String {
    let name = "\(x86ShiftName(instruction, laneBits: laneBits))\(x86Bits(width))"
    let operands = [
        (value: operand, type: x86Vector("i\(laneBits)")),
        (value: x86ShiftCount(amount), type: x86Block("i\(laneBits)")),
    ]
    return x86Builtin(name, operands, returning: type)
}

func x86Shift(
    _ instruction: String,
    laneBits: Int,
    width: Int,
    returning type: String
) -> String {
    x86RegisterShift(
        instruction,
        "a",
        by: "bits",
        laneBits: laneBits,
        width: width,
        returning: type
    )
}

func x86ShiftSame(
    _ instruction: String,
    _ operand: String,
    by amount: String,
    into result: String,
    laneBits: Int,
    width: Int,
    returning type: String
) -> String {
    let immediate = x86ImmediateShift(
        instruction,
        operand,
        by: amount,
        laneBits: laneBits,
        width: width,
        returning: type
    )
    let register = x86RegisterShift(
        instruction,
        operand,
        by: amount,
        laneBits: laneBits,
        width: width,
        returning: type
    )
    return """
        \(type) \(result);
        if (__builtin_constant_p(\(amount))) {
          \(result) = \(immediate);
        } else {
          \(result) = \(register);
        }
        """
}

func x86ShiftedLeft(for element: Element) -> String {
    guard element.bits == 8 else {
        let shifted = x86Shift(
            "psll",
            laneBits: element.bits,
            width: element.width,
            returning: element.cVector
        )
        return vectorResult(shifted, for: element)
    }
    let unsigned = element.cUnsignedVector
    let shifted = x86Shift("psll", laneBits: 16, width: element.width, returning: unsigned)
    let mask = splat("mask", as: unsigned, lanes: element.laneCount)
    return """
        const \(unsigned) shifted = \(shifted);
        const uint8_t mask = (uint8_t)(0xFFu << (bits & 31));
        \(vectorResult(fromUnsignedBits("shifted & \(mask)", of: element), for: element))
        """
}

func x86ShiftedRight(level: X86Level, for element: Element) -> String {
    let unsigned = element.cUnsignedVector
    switch (element.category, element.bits) {
    case (.unsignedInteger, 8):
        let shifted = x86Shift("psrl", laneBits: 16, width: element.width, returning: unsigned)
        let mask = splat("mask", as: unsigned, lanes: element.laneCount)
        return """
            const \(unsigned) shifted = \(shifted);
            const uint8_t mask = (uint8_t)(0xFF >> (bits & 31));
            \(vectorResult("shifted & \(mask)", for: element))
            """
    case (.signedInteger, 8):
        let shifted = x86Shift("psrl", laneBits: 16, width: element.width, returning: unsigned)
        let mask = splat("mask", as: unsigned, lanes: element.laneCount)
        let signs = splat("sign", as: unsigned, lanes: element.laneCount)
        return """
            const \(unsigned) shifted = \(shifted);
            const uint8_t mask = (uint8_t)(0xFF >> (bits & 31));
            const \(unsigned) masked = shifted & \(mask);
            const uint8_t sign = (uint8_t)(0x80 >> (bits & 31));
            const \(unsigned) signs = \(signs);
            \(vectorResult("(\(element.cVector))((masked ^ signs) - signs)", for: element))
            """
    case (.signedInteger, 64) where level < .avx3:
        let vector = element.cVector
        let right = x86ShiftSame(
            "psrl",
            "a",
            by: "bits",
            into: "right",
            laneBits: 64,
            width: element.width,
            returning: vector
        )
        let sign: String
        if level >= .sse4 {
            sign = "const \(vector) sign = (\(vector))(\(compoundLiteral(vector, ["0"])) > a);"
        } else {
            let i32 = x86Vector("i32")
            sign = """
                const \(i32) signs = (\(i32))a >> 31;
                const \(vector) sign = (\(vector))__builtin_shufflevector(
                  signs, signs, 1, 1, 3, 3);
                """
        }
        let shifted = x86ShiftSame(
            "psll",
            "sign",
            by: "(int)(64u - (unsigned)bits)",
            into: "shifted",
            laneBits: 64,
            width: element.width,
            returning: vector
        )
        return """
            \(right)
            \(sign)
            \(shifted)
            \(vectorResult("right | shifted", for: element))
            """
    default:
        let instruction = element.category == .unsignedInteger ? "psrl" : "psra"
        let shifted = x86Shift(
            instruction,
            laneBits: element.bits,
            width: element.width,
            returning: element.cVector
        )
        return vectorResult(shifted, for: element)
    }
}

struct X86Statements {
    private(set) var lines: [String] = []

    @discardableResult
    mutating func define(_ type: String, _ name: String, _ value: String) -> String {
        lines.append("const \(type) \(name) = \(value);")
        return name
    }

    var text: String {
        lines.joined(separator: "\n")
    }
}

func x86ShiftBody(_ statements: X86Statements, returning result: String, level: X86Level) -> String
{
    let body = "\(statements.text)\n\(result)"
    let width = level.width
    let types = [
        ("words_vector", "uint16_t", width), ("signed_words_vector", "int16_t", width),
        ("dwords_vector", "uint32_t", width), ("quads_vector", "uint64_t", width),
        ("bytes_vector", "uint8_t", width), ("lower_bytes", "uint8_t", width / 2),
        ("lower_words", "uint16_t", width / 2),
        ("half_words", "uint16_t", 16), ("half_signed_words", "int16_t", 16),
        ("wide_dwords", "uint32_t", 32), ("wide_signed_dwords", "int32_t", 32),
    ]
    let typedefs = types.filter {
        body.range(of: "\\b\($0.0)\\b", options: .regularExpression) != nil
    }
    .map { name, lane, bytes in
        "typedef \(lane) \(name) __attribute__((vector_size(\(bytes))));"
    }
    return (typedefs + [body]).joined(separator: "\n")
}

func x86Pow2Words(
    _ counts: String,
    prefix: String,
    level: X86Level,
    into statements: inout X86Statements
) -> String {
    let words = "words_vector"
    let dwords = "dwords_vector"
    let i32 = x86Vector("i32")
    let upper = statements.define(words, "\(prefix)Upper", "(\(counts) << 7) + 0x3F80")
    let zero = statements.define(words, "\(prefix)Zero", compoundLiteral(words, ["0"]))
    func interleaved(_ name: String, _ indices: [Int]) -> String {
        let interleaved = "__builtin_shufflevector(\(zero), \(upper), \(laneIndices(indices)))"
        return statements.define(dwords, "\(prefix)\(name)", "(\(dwords))\(interleaved)")
    }
    func converted(_ name: String, _ floats: String) -> String {
        let call = x86Builtin("cvtps2dq", [floats], as: "f32", returning: i32)
        return statements.define(i32, "\(prefix)\(name)Bits", call)
    }
    func extended(_ name: String, _ bits: String) -> String {
        let value = "(\(i32))((\(dwords))\(bits) << 16) >> 16"
        return statements.define(i32, "\(prefix)\(name)Extended", value)
    }
    let lowerFloats = interleaved("Lower", [0, 8, 1, 9, 2, 10, 3, 11])
    let higherFloats = interleaved("Higher", [4, 12, 5, 13, 6, 14, 7, 15])
    let lower = converted("Lower", lowerFloats)
    let higher = converted("Higher", higherFloats)
    let packed: String
    switch level {
    case .sse2:
        packed = x86Packing(
            "packssdw",
            extended("Lower", lower),
            extended("Higher", higher),
            from: "i32",
            to: "i16",
            width: 16
        )
    case .ssse3:
        packed =
            "__builtin_shufflevector((\(words))\(lower), (\(words))\(higher), "
            + "\(laneIndices([0, 2, 4, 6, 8, 10, 12, 14])))"
    default:
        packed = x86Packing("packusdw", lower, higher, from: "i32", to: "i16", width: 16)
    }
    return statements.define(words, "\(prefix)Pow2", "(\(words))\(packed)")
}

func x86Pow2Dwords(
    _ counts: String,
    prefix: String,
    into statements: inout X86Statements
) -> String {
    let dwords = "dwords_vector"
    let exponent = statements.define(dwords, "\(prefix)Exponent", "\(counts) << 23")
    let floats = statements.define(dwords, "\(prefix)Float", "\(exponent) + 0x3F800000")
    let call = x86Builtin("cvtps2dq", [floats], as: "f32", returning: x86Vector("i32"))
    return statements.define(dwords, "\(prefix)Pow2", "(\(dwords))\(call)")
}

func x86PairedShift(
    _ instruction: String,
    _ value: String,
    by counts: String,
    prefix: String,
    into statements: inout X86Statements
) -> String {
    let quads = "quads_vector"
    let i64 = x86Vector("i64")
    func shifted(_ name: String, _ amount: String) -> String {
        let call = x86Builtin("\(instruction)q128", [value, amount], as: "i64", returning: i64)
        return statements.define(quads, "\(prefix)\(name)", "(\(quads))\(call)")
    }
    let lower = shifted("Lower", counts)
    let upperCounts = statements.define(
        quads,
        "\(prefix)Counts",
        "__builtin_shufflevector(\(counts), \(counts), 1, 1)"
    )
    let upper = shifted("Upper", upperCounts)
    return statements.define(
        quads,
        "\(prefix)Result",
        "__builtin_shufflevector(\(lower), \(upper), 0, 3)"
    )
}

func x86Avx2WordHalf(
    _ operand: String,
    upper: Bool,
    signed: Bool,
    prefix: String,
    into statements: inout X86Statements
) -> String {
    let (half, wide) =
        signed ? ("half_signed_words", "wide_signed_dwords") : ("half_words", "wide_dwords")
    let indices = Array((upper ? 8 : 0)..<(upper ? 16 : 8))
    let halved = "(\(half))__builtin_shufflevector(\(operand), \(operand), \(laneIndices(indices)))"
    return statements.define(wide, prefix, "__builtin_convertvector(\(halved), \(wide))")
}

func x86ShiftWords(
    left: Bool,
    signed: Bool = false,
    _ value: String,
    by counts: String,
    prefix: String,
    level: X86Level,
    into statements: inout X86Statements
) -> String {
    let width = level.width
    let words = "words_vector"
    let instruction = left ? "psll" : signed ? "psra" : "psrl"
    switch width {
    case 64:
        let call = x86Builtin(
            "\(instruction)v32hi",
            [value, counts],
            as: "i16",
            returning: words
        )
        return statements.define(words, "\(prefix)Words", call)
    case 32:
        func shifted(_ name: String, upper: Bool) -> String {
            let promotedValue = x86Avx2WordHalf(
                value,
                upper: upper,
                signed: signed,
                prefix: "\(prefix)\(name)Value",
                into: &statements
            )
            let promotedCounts = x86Avx2WordHalf(
                counts,
                upper: upper,
                signed: signed,
                prefix: "\(prefix)\(name)Counts",
                into: &statements
            )
            let call = x86Builtin(
                "\(instruction)v8si",
                [promotedValue, promotedCounts],
                as: "i32",
                returning: x86Vector("i32")
            )
            return statements.define(x86Vector("i32"), "\(prefix)\(name)", call)
        }
        let lower = shifted("Lower", upper: false)
        let upper = shifted("Upper", upper: true)
        let narrowed: (String, String)
        if left {
            let zero = statements.define(
                "dwords_vector",
                "\(prefix)Zero",
                compoundLiteral("dwords_vector", ["0"])
            )
            func masked(_ name: String, _ operand: String) -> String {
                let call = x86Builtin(
                    "pblendw256",
                    [
                        (value: operand, type: x86Vector("i16")),
                        (value: zero, type: x86Vector("i16")), (value: "0xAA", type: "int"),
                    ],
                    returning: "dwords_vector"
                )
                return statements.define("dwords_vector", "\(prefix)\(name)", call)
            }
            narrowed = (masked("LowerWords", lower), masked("UpperWords", upper))
        } else {
            narrowed = (lower, upper)
        }
        let packed = x86Packing(
            signed ? "packssdw" : "packusdw",
            narrowed.0,
            narrowed.1,
            from: "i32",
            to: "i16",
            width: 32
        )
        let ordered = statements.define(
            x86Vector("i64"),
            "\(prefix)Packed",
            "(\(x86Vector("i64")))\(packed)"
        )
        return statements.define(
            words,
            "\(prefix)Words",
            "(\(words))__builtin_shufflevector(\(ordered), \(ordered), 0, 2, 1, 3)"
        )
    default:
        return x86ShiftSseWords(
            left: left,
            value,
            by: counts,
            prefix: prefix,
            level: level,
            into: &statements
        )
    }
}

func x86ShiftSseWords(
    left: Bool,
    _ value: String,
    by counts: String,
    prefix: String,
    level: X86Level,
    into statements: inout X86Statements
) -> String {
    let words = "words_vector"
    guard left else {
        let sixteen = statements.define(words, "\(prefix)Sixteen", splat("16", as: words, lanes: 8))
        let amounts = statements.define(words, "\(prefix)Amounts", "\(sixteen) - \(counts)")
        let pow2 = x86Pow2Words(amounts, prefix: "\(prefix)Pow2", level: level, into: &statements)
        let high = x86Builtin("pmulhuw128", [value, pow2], as: "i16", returning: words)
        let product = statements.define(words, "\(prefix)High", high)
        let isZero = statements.define(words, "\(prefix)IsZero", "(\(words))(\(counts) == 0)")
        return statements.define(
            words,
            "\(prefix)Words",
            "(~\(isZero) & \(product)) | (\(isZero) & \(value))"
        )
    }
    let pow2 = x86Pow2Words(counts, prefix: "\(prefix)Pow2", level: level, into: &statements)
    return statements.define(words, "\(prefix)Words", "\(value) * \(pow2)")
}

func x86ShiftBytes(
    left: Bool,
    signed: Bool = false,
    _ value: String,
    by counts: String,
    prefix: String,
    level: X86Level,
    into statements: inout X86Statements
) -> String {
    let width = level.width
    let words = "words_vector"
    let bytes = unsignedElement(bits: 8).cVector
    let vector = statements.define(words, "\(prefix)Value", "(\(words))\(value)")
    let amounts = statements.define(words, "\(prefix)Counts", "(\(words))\(counts)")
    let lanes = width / 2
    let evenMask = splat("0x00FF", as: words, lanes: lanes)
    let oddMask = splat("0xFF00", as: words, lanes: lanes)
    let evens: String
    let odds: String
    if signed {
        let signedWords = "signed_words_vector"
        let low = statements.define(
            signedWords,
            "\(prefix)Low",
            "(\(signedWords))(\(vector) << 8) >> 8"
        )
        let evenCounts = statements.define(words, "\(prefix)EvenCounts", "\(amounts) & \(evenMask)")
        let evenResult = x86ShiftWords(
            left: false,
            signed: true,
            low,
            by: evenCounts,
            prefix: "\(prefix)Even",
            level: level,
            into: &statements
        )
        evens = evenResult
        let oddCounts = statements.define(words, "\(prefix)OddCounts", "\(amounts) >> 8")
        odds = x86ShiftWords(
            left: false,
            signed: true,
            vector,
            by: oddCounts,
            prefix: "\(prefix)Odd",
            level: level,
            into: &statements
        )
    } else {
        let evenValue =
            left
            ? vector : statements.define(words, "\(prefix)EvenValue", "\(vector) & \(evenMask)")
        let evenCounts = statements.define(words, "\(prefix)EvenCounts", "\(amounts) & \(evenMask)")
        evens = x86ShiftWords(
            left: left,
            evenValue,
            by: evenCounts,
            prefix: "\(prefix)Even",
            level: level,
            into: &statements
        )
        let oddValue =
            left ? statements.define(words, "\(prefix)OddValue", "\(vector) & \(oddMask)") : vector
        let oddCounts = statements.define(words, "\(prefix)OddCounts", "\(amounts) >> 8")
        odds = x86ShiftWords(
            left: left,
            oddValue,
            by: oddCounts,
            prefix: "\(prefix)Odd",
            level: level,
            into: &statements
        )
    }
    guard width != 32 else {
        let evenBytes = compoundLiteral(
            bytes,
            Array(repeating: ["0xFF", "0"], count: width / 2).flatMap { $0 }
        )
        let mask = statements.define(bytes, "\(prefix)EvenBytes", evenBytes)
        let blended = x86Builtin("pblendvb256", [odds, evens, mask], as: "i8", returning: bytes)
        return statements.define(bytes, "\(prefix)Bytes", blended)
    }
    let keptEvens = left || signed ? "(\(evens) & ~\(oddMask))" : evens
    let merged = "\(keptEvens) | (\(odds) & \(oddMask))"
    return statements.define(bytes, "\(prefix)Bytes", "(\(bytes))(\(merged))")
}

func x86ShiftDwordsRight(
    _ value: String,
    by counts: String,
    prefix: String,
    into statements: inout X86Statements
) -> String {
    let dwords = "dwords_vector"
    let quads = "quads_vector"
    let i64 = x86Vector("i64")
    let thirtyTwo = statements.define(
        dwords,
        "\(prefix)ThirtyTwo",
        splat("32", as: dwords, lanes: 4)
    )
    let amounts = statements.define(dwords, "\(prefix)Amounts", "\(thirtyTwo) - \(counts)")
    let pow2 = x86Pow2Dwords(amounts, prefix: "\(prefix)Pow2", into: &statements)
    func odds(_ operand: String, _ name: String) -> String {
        statements.define(
            dwords,
            "\(prefix)\(name)",
            "__builtin_shufflevector(\(operand), \(operand), 1, 1, 3, 3)"
        )
    }
    let value31 = odds(value, "Value31")
    let pow231 = odds(pow2, "Pow231")
    let product20 = statements.define(
        quads,
        "\(prefix)Product20",
        "(\(quads))" + x86Builtin("pmuludq128", [value, pow2], as: "i32", returning: i64)
    )
    let product31 = statements.define(
        quads,
        "\(prefix)Product31",
        "(\(quads))" + x86Builtin("pmuludq128", [value31, pow231], as: "i32", returning: i64)
    )
    let even = statements.define(dwords, "\(prefix)Even", "(\(dwords))(\(product20) >> 32)")
    let odd = statements.define(dwords, "\(prefix)Odd", "(\(dwords))\(product31)")
    let merged = statements.define(
        dwords,
        "\(prefix)Merged",
        "__builtin_shufflevector(\(even), \(odd), 0, 5, 2, 7)"
    )
    let isZero = statements.define(dwords, "\(prefix)IsZero", "(\(dwords))(\(counts) == 0)")
    return statements.define(
        dwords,
        "\(prefix)Result",
        "(\(isZero) & \(value)) | (~\(isZero) & \(merged))"
    )
}

func x86UnsignedShiftedByLanes(
    left: Bool,
    _ value: String,
    by counts: String,
    bits: Int,
    prefix: String,
    level: X86Level,
    into statements: inout X86Statements
) -> String {
    let width = level.width
    switch (bits, width) {
    case (8, _):
        return x86ShiftBytes(
            left: left,
            value,
            by: counts,
            prefix: prefix,
            level: level,
            into: &statements
        )
    case (16, _):
        return x86ShiftWords(
            left: left,
            value,
            by: counts,
            prefix: prefix,
            level: level,
            into: &statements
        )
    case (32, 16) where left:
        let pow2 = x86Pow2Dwords(counts, prefix: "\(prefix)Left", into: &statements)
        let dwords = unsignedElement(of: unsignedElement(bits: 32))
        return statements.define(
            dwords.cVector,
            "\(prefix)Result",
            operationCall("multiplying", [value, pow2], for: dwords)
        )
    case (32, 16):
        return x86ShiftDwordsRight(value, by: counts, prefix: prefix, into: &statements)
    case (64, 16):
        return x86PairedShift(
            left ? "psll" : "psrl",
            value,
            by: counts,
            prefix: prefix,
            into: &statements
        )
    default:
        let element = unsignedElement(bits: bits).at(width: width)
        let suffix = bits == 32 ? "si" : "di"
        let name = "ps\(left ? "ll" : "rl")v\(element.laneCount)\(suffix)"
        let call = x86Builtin(name, [value, counts], as: "i\(bits)", returning: element.cVector)
        return statements.define(element.cVector, "\(prefix)Result", call)
    }
}

func x86ShiftedLeftByLanes(level: X86Level, for element: Element) -> String {
    var statements = X86Statements()
    let unsigned = unsignedElement(of: element).at(width: element.width)
    let value = statements.define(unsigned.cVector, "value", unsignedBits("a", of: element))
    let counts = statements.define(unsigned.cVector, "counts", unsignedBits("b", of: element))
    let result = x86UnsignedShiftedByLanes(
        left: true,
        value,
        by: counts,
        bits: element.bits,
        prefix: "shifted",
        level: level,
        into: &statements
    )
    return x86ShiftBody(
        statements,
        returning: vectorResult(fromUnsignedBits(result, of: element), for: element),
        level: level
    )
}

func x86ShiftedRightByLanes(level: X86Level, for element: Element) -> String {
    var statements = X86Statements()
    let unsigned = unsignedElement(of: element).at(width: element.width)
    let type = unsigned.cVector
    guard element.category == .signedInteger else {
        let value = statements.define(type, "value", "a")
        let counts = statements.define(type, "counts", "b")
        let result = x86UnsignedShiftedByLanes(
            left: false,
            value,
            by: counts,
            bits: element.bits,
            prefix: "shifted",
            level: level,
            into: &statements
        )
        return x86ShiftBody(statements, returning: vectorResult(result, for: element), level: level)
    }
    let usesNativeSigned =
        (element.bits == 16 && level.width >= 32) || (element.bits == 32 && level.width >= 32)
        || (element.bits == 64 && level.width == 64) || (element.bits == 8 && level.width >= 32)
    if usesNativeSigned {
        return x86NativeSignedShiftedRight(level: level, for: element)
    }
    let sign = statements.define(
        element.cVector,
        "sign",
        operationCall("broadcastingSignBit", ["a"], for: element)
    )
    let magnitude = statements.define(type, "magnitude", "(\(type))(a ^ \(sign))")
    let counts = statements.define(type, "counts", "(\(type))b")
    let shifted = x86UnsignedShiftedByLanes(
        left: false,
        magnitude,
        by: counts,
        bits: element.bits,
        prefix: "shifted",
        level: level,
        into: &statements
    )
    return x86ShiftBody(
        statements,
        returning: vectorResult("(\(element.cVector))\(shifted) ^ \(sign)", for: element),
        level: level
    )
}

func x86NativeSignedShiftedRight(level: X86Level, for element: Element) -> String {
    var statements = X86Statements()
    let result: String
    switch element.bits {
    case 8:
        let unsigned = unsignedElement(of: element).at(width: element.width)
        let value = statements.define(unsigned.cVector, "value", "(\(unsigned.cVector))a")
        let counts = statements.define(unsigned.cVector, "counts", "(\(unsigned.cVector))b")
        let bytes = x86ShiftBytes(
            left: false,
            signed: true,
            value,
            by: counts,
            prefix: "shifted",
            level: level,
            into: &statements
        )
        result = "(\(element.cVector))\(bytes)"
    case 16:
        let unsigned = unsignedElement(of: element).at(width: element.width)
        let value = statements.define(unsigned.cVector, "value", "(\(unsigned.cVector))a")
        let counts = statements.define(unsigned.cVector, "counts", "(\(unsigned.cVector))b")
        let words = x86ShiftWords(
            left: false,
            signed: true,
            value,
            by: counts,
            prefix: "shifted",
            level: level,
            into: &statements
        )
        result = "(\(element.cVector))\(words)"
    default:
        let name = "psrav\(element.laneCount)\(element.bits == 32 ? "si" : "di")"
        result = x86Builtin(
            name,
            ["a", "b"],
            as: "i\(element.bits)",
            returning: element.cVector
        )
    }
    return x86ShiftBody(statements, returning: vectorResult(result, for: element), level: level)
}

func x86Avx3DlShiftedLeftBytes(for element: Element) -> String {
    let bytes = unsignedElement(bits: 8).at(width: element.width)
    let masks: [UInt8] =
        [0xFF, 0x7F, 0x3F, 0x1F, 0x0F, 0x07, 0x03, 0x01] + Array(repeating: 0, count: 8)
    let multipliers: [UInt8] = [1, 2, 4, 8, 0x10, 0x20, 0x40, 0x80] + Array(repeating: 0, count: 8)
    func table(_ values: [UInt8]) -> String {
        let repeated = Array(repeating: values, count: element.width / 16).flatMap { $0 }
        return compoundLiteral(bytes.cVector, repeated.map { "0x\(String($0, radix: 16))" })
    }
    func lookup(_ values: [UInt8]) -> String {
        x86Builtin(
            "pshufb\(x86Bits(element.width))",
            [table(values), "counts"],
            as: "i8",
            returning: bytes.cVector
        )
    }
    let multiplied = x86Builtin(
        "vgf2p8mulb_v\(element.width)qi",
        ["masked", "multipliers"],
        as: "i8",
        returning: element.cVector
    )
    return """
        const \(bytes.cVector) value = \(unsignedBits("a", of: element));
        const \(bytes.cVector) counts = \(unsignedBits("b", of: element));
        const \(bytes.cVector) masked = value & \(lookup(masks));
        const \(bytes.cVector) multipliers = \(lookup(multipliers));
        \(vectorResult(multiplied, for: element))
        """
}

func x86PartVector(bits: Int, width: Int) -> String {
    let lane = bits == 8 ? "uint8_t" : "uint16_t"
    return "typedef \(lane) part_vector __attribute__((vector_size(\(width / 4 * bits / 8))));"
}

func x86ScanBody(
    _ statements: X86Statements,
    returning result: String,
    bits: Int,
    level: X86Level
) -> String {
    let body = x86ShiftBody(statements, returning: result, level: level)
    guard bits <= 16 else { return body }
    return "\(x86PartVector(bits: bits, width: level.width))\n\(body)"
}

func x86PackedExponents(
    _ name: String,
    _ first: String,
    _ second: String,
    from source: String,
    to result: String,
    prefix: String,
    level: X86Level,
    into statements: inout X86Statements
) -> String {
    let resultVector = result == "i16" ? "signed_words_vector" : "bytes_vector"
    let packed = x86Packing(name, first, second, from: source, to: result, width: level.width)
    guard level.width == 32 else {
        return statements.define(resultVector, prefix, "(\(resultVector))\(packed)")
    }
    let i64 = x86Vector("i64")
    let ordered = statements.define(i64, "\(prefix)Packed", "(\(i64))\(packed)")
    return statements.define(
        resultVector,
        prefix,
        "(\(resultVector))__builtin_shufflevector(\(ordered), \(ordered), 0, 2, 1, 3)"
    )
}

func x86ExponentDwords(
    _ value: String,
    clamped: Bool,
    prefix: String,
    width: Int,
    into statements: inout X86Statements
) -> String {
    let floats = x86Vector("f32")
    let converted = statements.define(
        floats,
        "\(prefix)Float",
        "__builtin_convertvector((\(x86Vector("i32")))\(value), \(floats))"
    )
    let shifted = statements.define(
        "dwords_vector",
        "\(prefix)Shifted",
        "(dwords_vector)\(converted) >> 23"
    )
    guard clamped else { return shifted }
    let limit = statements.define(
        "dwords_vector",
        "\(prefix)Limit",
        splat("158", as: "dwords_vector", lanes: width / 4)
    )
    return statements.define(
        "dwords_vector",
        "\(prefix)Clamped",
        "(dwords_vector)__builtin_elementwise_min((signed_words_vector)\(shifted), (signed_words_vector)\(limit))"
    )
}

func x86ExponentNarrow(
    _ value: String,
    bits: Int,
    prefix: String,
    level: X86Level,
    into statements: inout X86Statements
) -> String {
    let lanes = level.width / (bits / 8)
    let parts = bits == 8 ? 4 : 2
    let partLanes = lanes / parts
    func selected(_ part: Int) -> String {
        guard bits == 8 else {
            let indices = Array((part * partLanes)..<((part + 1) * partLanes))
            return
                "(part_vector)__builtin_shufflevector(\(value), \(value), \(laneIndices(indices)))"
        }
        let half = part / 2
        let halfIndices = Array((half * lanes / 2)..<((half + 1) * lanes / 2))
        let halved = statements.define(
            "lower_bytes",
            "\(prefix)Half\(part)",
            "(lower_bytes)__builtin_shufflevector(\(value), \(value), \(laneIndices(halfIndices)))"
        )
        let quarter = part % 2
        let indices = Array((quarter * partLanes)..<((quarter + 1) * partLanes))
        return "(part_vector)__builtin_shufflevector(\(halved), \(halved), \(laneIndices(indices)))"
    }
    let promoted = (0..<parts).map { part in
        statements.define(
            "dwords_vector",
            "\(prefix)Part\(part)",
            "__builtin_convertvector(\(selected(part)), dwords_vector)"
        )
    }
    let exponents = promoted.enumerated().map { part, operand in
        x86ExponentDwords(
            operand,
            clamped: false,
            prefix: "\(prefix)Part\(part)",
            width: level.width,
            into: &statements
        )
    }
    func packed(
        _ name: String,
        _ first: String,
        _ second: String,
        from source: String,
        to result: String,
        _ label: String
    ) -> String {
        x86PackedExponents(
            name,
            first,
            second,
            from: source,
            to: result,
            prefix: "\(prefix)\(label)",
            level: level,
            into: &statements
        )
    }
    let lower = packed("packssdw", exponents[0], exponents[1], from: "i32", to: "i16", "Lower")
    guard bits == 8 else { return lower }
    let upper = packed("packssdw", exponents[2], exponents[3], from: "i32", to: "i16", "Upper")
    return packed("packuswb", lower, upper, from: "i16", to: "i8", "Bytes")
}

func x86ExponentQuads(
    _ value: String,
    prefix: String,
    level: X86Level,
    into statements: inout X86Statements
) -> String {
    let lanes = level.width / 4
    let exponents = x86ExponentDwords(
        value,
        clamped: true,
        prefix: "\(prefix)Dwords",
        width: level.width,
        into: &statements
    )
    let zeros = statements.define(
        "dwords_vector",
        "\(prefix)Zeros",
        compoundLiteral("dwords_vector", ["0"])
    )
    let offsets = compoundLiteral(
        "dwords_vector",
        (0..<(lanes / 2)).flatMap { _ in ["0", "0x20"] }
    )
    let offset = statements.define("dwords_vector", "\(prefix)Offset", offsets)
    let isZero = statements.define(
        "dwords_vector",
        "\(prefix)IsZero",
        "(dwords_vector)(\(exponents) == \(zeros))"
    )
    let adjusted = statements.define(
        "dwords_vector",
        "\(prefix)Adjusted",
        "\(exponents) + (~\(isZero) & \(offset))"
    )
    let swapped = statements.define(
        "dwords_vector",
        "\(prefix)Swapped",
        "__builtin_shufflevector(\(adjusted), \(adjusted), \(laneIndices((0..<lanes).map { $0 ^ 1 })))"
    )
    let repartitioned = unsignedElement(bits: level <= .ssse3 ? 8 : 32).at(width: level.width)
    let combined = statements.define(
        "dwords_vector",
        "\(prefix)Combined",
        "(dwords_vector)\(operationCall("maximum", [adjusted, swapped], for: repartitioned))"
    )
    return statements.define("quads_vector", "\(prefix)Exponent", "(quads_vector)\(combined) >> 32")
}

func x86Exponent(
    _ value: String,
    bits: Int,
    prefix: String,
    level: X86Level,
    into statements: inout X86Statements
) -> String {
    switch bits {
    case 8, 16:
        return x86ExponentNarrow(value, bits: bits, prefix: prefix, level: level, into: &statements)
    case 32:
        return x86ExponentDwords(
            value,
            clamped: true,
            prefix: prefix,
            width: level.width,
            into: &statements
        )
    default:
        return x86ExponentQuads(value, prefix: prefix, level: level, into: &statements)
    }
}

enum BitScan {
    case leadingZeros
    case trailingZeros
    case highestSetBit
}

func x86BiasedBitScan(_ scan: BitScan, level: X86Level, for element: Element) -> String {
    var statements = X86Statements()
    let unsigned = unsignedElement(of: element).at(width: element.width)
    let type = unsigned.cVector
    let bits = element.bits
    let operand = statements.define(type, "value", unsignedBits("a", of: element))
    let source: String
    switch scan {
    case .trailingZeros:
        source = statements.define(type, "lowest", "\(operand) & -\(operand)")
    case .leadingZeros, .highestSetBit:
        source =
            bits >= 32
            ? statements.define(type, "normalized", "\(operand) & ~(\(operand) >> 24)") : operand
    }
    let exponent = x86Exponent(
        source,
        bits: bits,
        prefix: "exponent",
        level: level,
        into: &statements
    )
    let exponents = statements.define(type, "exponents", "(\(type))\(exponent)")
    func constant(_ value: Int) -> String {
        splat("\(value)", as: type, lanes: element.laneCount)
    }
    let result: String
    switch scan {
    case .highestSetBit:
        result = "\(exponents) - \(constant(127))"
    case .leadingZeros, .trailingZeros:
        let counts =
            scan == .leadingZeros
            ? statements.define(type, "counts", "\(constant(bits + 126)) - \(exponents)")
            : statements.define(type, "counts", "\(exponents) - \(constant(127))")
        let repartitioned = unsignedElement(bits: level <= .ssse3 ? 8 : min(bits, 32)).at(
            width: element.width
        )
        result = operationCall("minimum", [counts, constant(bits)], for: repartitioned)
    }
    return x86ScanBody(
        statements,
        returning: vectorResult(fromUnsignedBits(result, of: element), for: element),
        bits: bits,
        level: level
    )
}

func x86Avx3Lzcnt32(
    _ value: String,
    bits: Int,
    prefix: String,
    level: X86Level,
    into statements: inout X86Statements
) -> String {
    let width = level.width
    let lanes = width / (bits / 8)
    let narrow = bits == 8 ? "lower_bytes" : "lower_words"
    let wide = bits == 8 ? "words_vector" : "dwords_vector"
    let result = bits == 8 ? "bytes_vector" : "words_vector"
    func counted(_ label: String, _ indices: [Int]) -> String {
        let selected =
            "(\(narrow))__builtin_shufflevector(\(value), \(value), \(laneIndices(indices)))"
        let promoted = statements.define(
            wide,
            "\(prefix)\(label)",
            "__builtin_convertvector(\(selected), \(wide))"
        )
        guard bits == 8 else {
            let leading = x86Builtin(
                "vplzcntd_\(x86Bits(width))",
                [promoted],
                as: "i32",
                returning: wide
            )
            return statements.define(wide, "\(prefix)\(label)Counts", leading)
        }
        return x86Avx3Lzcnt32(
            promoted,
            bits: 16,
            prefix: "\(prefix)\(label)",
            level: level,
            into: &statements
        )
    }
    let lower = counted("Lower", Array(0..<(lanes / 2)))
    let upper = counted("Upper", Array((lanes / 2)..<lanes))
    let packed = x86Packing(
        bits == 8 ? "packuswb" : "packusdw",
        lower,
        upper,
        from: bits == 8 ? "i16" : "i32",
        to: bits == 8 ? "i8" : "i16",
        width: width
    )
    let quads = x86Vector("i64")
    let ordered = statements.define(quads, "\(prefix)Packed", "(\(quads))\(packed)")
    return statements.define(
        result,
        "\(prefix)Narrow",
        "(\(result))__builtin_shufflevector(\(ordered), \(ordered), 0, 2, 4, 6, 1, 3, 5, 7)"
    )
}

func x86Avx3BitScan(_ scan: BitScan, level: X86Level, for element: Element) -> String {
    var statements = X86Statements()
    let unsigned = unsignedElement(of: element).at(width: element.width)
    let type = unsigned.cVector
    let bits = element.bits
    func constant(_ value: Int) -> String {
        splat("\(value)", as: type, lanes: element.laneCount)
    }
    func highestSetBit(of operand: String) -> String {
        guard bits <= 16 else {
            let name = "vplzcnt\(bits == 32 ? "d" : "q")_\(x86Bits(element.width))"
            let leading = x86Builtin(name, [operand], as: "i\(bits)", returning: type)
            return "\(constant(bits - 1)) - \(leading)"
        }
        let counts = x86Avx3Lzcnt32(
            operand,
            bits: bits,
            prefix: "lzcnt",
            level: level,
            into: &statements
        )
        return "\(constant(31)) - (\(type))\(counts)"
    }
    let operand = statements.define(type, "value", unsignedBits("a", of: element))
    let result: String
    switch scan {
    case .highestSetBit:
        result = highestSetBit(of: operand)
    case .leadingZeros:
        if bits <= 16 {
            let counts = x86Avx3Lzcnt32(
                operand,
                bits: bits,
                prefix: "lzcnt",
                level: level,
                into: &statements
            )
            let shifted = statements.define(
                type,
                "counts",
                "(\(type))\(counts) - \(constant(32 - bits))"
            )
            result = operationCall("minimum", [shifted, constant(bits)], for: unsigned)
        } else {
            let name = "vplzcnt\(bits == 32 ? "d" : "q")_\(x86Bits(element.width))"
            result = x86Builtin(name, [operand], as: "i\(bits)", returning: type)
        }
    case .trailingZeros:
        let lowest = statements.define(type, "lowest", "\(operand) & -\(operand)")
        let signedType = x86Vector("i\(bits)")
        let index = statements.define(type, "index", highestSetBit(of: lowest))
        let negative = statements.define(type, "negative", "(\(type))((\(signedType))\(index) < 0)")
        result = "(\(negative) & \(constant(bits))) | (~\(negative) & \(index))"
    }
    return x86ShiftBody(
        statements,
        returning: vectorResult(fromUnsignedBits(result, of: element), for: element),
        level: level
    )
}

func x86Extremum(
    _ name: String,
    _ first: String,
    _ second: String,
    for element: Element
) -> String {
    let suffix = element.bits == 32 ? "ps" : "pd"
    let rounding = element.width == 64 ? ", \(x86CurrentRounding)" : ""
    return
        "__builtin_ia32_\(name)\(suffix)\(x86UnsuffixedBits(element.width))(\(first), \(second)\(rounding))"
}

func x86IsNaN(of operand: String = "a", for element: Element) -> String {
    "__builtin_ia32_cmp\(element.bits == 32 ? "ps" : "pd")\(x86UnsuffixedBits(element.width))(\(operand), \(operand), 3)"
}

func x86Avx3MaskVector(_ bits: String, for element: Element) -> String {
    let bitsType = x86MaskType(lanes: element.laneCount)
    let letter = x86LaneLetter(bits: element.bits)
    return x86Builtin(
        "cvtmask2\(letter)\(x86Bits(element.width))",
        [(value: bits, type: bitsType)],
        returning: element.cMask
    )
}

func x86Avx3Classified(
    _ classes: Int,
    inverted: Bool = false,
    of operand: String = "a",
    for element: Element
) -> String {
    let float = x86Vector(element.cSuffix)
    let bitsType = x86MaskType(lanes: element.laneCount)
    let found = x86Builtin(
        "fpclassp\(element.bits == 32 ? "s" : "d")\(x86Bits(element.width))_mask",
        [
            (value: operand, type: float),
            (value: "0x\(String(classes, radix: 16))", type: "int"),
            (value: "-1", type: bitsType),
        ],
        returning: bitsType
    )
    return x86Avx3MaskVector(inverted ? "~\(found)" : found, for: element)
}

func x86Avx3IsNaN(of operand: String = "a", for element: Element) -> String {
    x86Avx3Classified(0x81, of: operand, for: element)
}

func x86CombiningFunctionName(_ reduction: Reduction, _ element: Element) -> String {
    "cvectorization_ops_x86_\(snakeCased(reduction.combiningOp))_\(element.cSuffix)"
}

func x86CombiningFunction(
    _ reduction: Reduction,
    level: X86Level,
    for element: Element
) -> String? {
    guard !x86UsesMinimumPosition(reduction, level: level, for: element) else { return "" }
    guard element.bits > 8 || (reduction != .sum && element.width > 16) else { return nil }
    let function = cFunction(
        returns: element.cRawVector,
        name: x86CombiningFunctionName(reduction, element),
        parameters: ["\(element.cRawVector) a", "\(element.cRawVector) b"],
        body: "return \(cFunctionName(reduction.combiningOp, element))(a, b);",
        specifiers: "CVECTORIZATION_OPS_FUNCTION"
    )
    return function.trimmingCharacters(in: .newlines)
}

func x86CombiningHelpers(_ reduction: Reduction) -> TargetBodies<Element> {
    TargetBodies(
        avx3: { element in x86CombiningFunction(reduction, level: .avx3, for: element) },
        avx2: { element in x86CombiningFunction(reduction, level: .avx2, for: element) },
        sse4: { element in x86CombiningFunction(reduction, level: .sse4, for: element) },
        sse2: { element in x86CombiningFunction(reduction, level: .sse2, for: element) }
    )
}

func x86Reverse(
    _ source: String,
    into result: String,
    lanes group: Int,
    level: X86Level,
    for element: Element
) -> String {
    let vector = element.cVector
    let declaration = "const \(vector) \(result)"
    let indices = (0..<element.laneCount).map { $0 ^ (group - 1) }
    guard element.bits == 16 else {
        return
            "\(declaration) = __builtin_shufflevector(\(source), \(source), \(laneIndices(indices)));"
    }
    if level >= .ssse3 {
        let bytes = indices.map { String(format: "0x%04X", ((2 * $0 + 1) << 8) | (2 * $0)) }
        let table = compoundLiteral(x86Vector("i16"), bytes)
        return "\(declaration) = \(x86TableLookup(source, table, for: element));"
    }
    var lines: [String] = []
    var shuffled = source
    if group == 8 {
        let i32 = x86Vector("i32")
        let dwords = prefixed(result, "dwords")
        let reversed = "__builtin_shufflevector((\(i32))\(source), (\(i32))\(source), 3, 2, 1, 0)"
        lines.append("const \(i32) \(dwords) = \(reversed);")
        shuffled = "(\(vector))\(dwords)"
    }
    let within = group == 4 ? 4 : 2
    let lower = prefixed(result, "lower")
    let lowerIndices = (0..<8).map { $0 < 4 ? $0 ^ (within - 1) : $0 }
    let upperIndices = (0..<8).map { $0 < 4 ? $0 : $0 ^ (within - 1) }
    lines.append(
        "const \(vector) \(lower) = __builtin_shufflevector(\(shuffled), \(shuffled), \(laneIndices(lowerIndices)));"
    )
    lines.append(
        "\(declaration) = __builtin_shufflevector(\(lower), \(lower), \(laneIndices(upperIndices)));"
    )
    return lines.joined(separator: "\n")
}

func x86SaturatedExtremum(_ reduction: Reduction, _ first: String, _ second: String) -> String {
    let subtracting = "__builtin_elementwise_sub_sat"
    return reduction == .minimum
        ? "\(first) - \(subtracting)(\(first), \(second))"
        : "\(first) + \(subtracting)(\(second), \(first))"
}

func x86CombinedExtremum(_ reduction: Reduction, for element: Element) -> String {
    guard element.category == .unsignedInteger, element.bits == 16 || element.bits == 64 else {
        fatalError("There is no combined x86 extremum of \(element.swiftType)")
    }
    let isMinimum = reduction == .minimum
    if element.bits == 16 {
        return vectorResult(x86SaturatedExtremum(reduction, "a", "b"), for: element)
    }
    let (yes, no) = isMinimum ? ("b", "a") : ("a", "b")
    return """
        \(x86UnsignedGreater("a", "b", for: element))
        \(vectorResult(bitSelect("mask", yes, no, of: element), for: element))
        """
}

func x86ComparedExtremum(_ reduction: Reduction, for element: Element) -> String? {
    let isMinimum = reduction == .minimum
    let i64 = x86Vector("i64")
    let greater = x86GreaterThanName(bits: element.bits)
    let (first, second) = ("(\(i64))a", "(\(i64))b")
    switch (element.category, element.bits) {
    case (.signedInteger, 8), (.signedInteger, 32):
        let (yes, no) = isMinimum ? (first, second) : (second, first)
        let selected = "\(x86IfThenElseName)(\(greater)(\(second), \(first)), \(yes), \(no))"
        return vectorResult(selected, for: element)
    case (.unsignedInteger, 32):
        let (yes, no) = isMinimum ? (second, first) : (first, second)
        let sign = splat("0x80000000", as: element.cVector, lanes: element.laneCount)
        return """
            const \(i64) sign = (\(i64))\(sign);
            const \(i64) greater = \(greater)(\(first) ^ sign, \(second) ^ sign);
            \(vectorResult("\(x86IfThenElseName)(greater, \(yes), \(no))", for: element))
            """
    default:
        return nil
    }
}

func x86MinMax(_ reduction: Reduction, level: X86Level, for element: Element) -> String? {
    let isMinimum = reduction == .minimum
    let (name, symbol) = isMinimum ? ("min", "<") : ("max", ">")
    if element.category == .float {
        return vectorResult(x86Extremum(name, "a", "b", for: element), for: element)
    }
    guard level < .avx3 else { return nil }
    if isSignedInteger64(element) {
        let chosen = isMinimum ? (first: "a", second: "b") : (first: "b", second: "a")
        return x86Int64Extremum(chosen, native: level >= .sse4, for: element)
    }
    guard level < .avx2 else { return nil }
    let hasInstruction = element.bits == (element.category == .signedInteger ? 16 : 8)
    guard !hasInstruction else { return nil }
    guard level < .sse4 else { return elementwiseExtremum(name, comparing: symbol, for: element) }
    if let compared = x86ComparedExtremum(reduction, for: element) { return compared }
    return x86CombinedExtremum(reduction, for: element)
}

func portableRoundedAverage(for element: Element) -> String {
    vectorResult(arithmetic("-", "(a | b)", "((a ^ b) >> 1)", for: element), for: element)
}

func x86NarrowRoundedAverage(for element: Element) -> String {
    let name = "\(element.bits == 8 ? "pavgb" : "pavgw")\(x86Bits(element.width))"
    guard element.category == .signedInteger else {
        let average = x86Builtin(
            name,
            ["a", "b"],
            as: "i\(element.bits)",
            returning: element.cVector
        )
        return vectorResult(average, for: element)
    }
    let unsigned = element.cUnsignedVector
    let signBit = "0x\(String(UInt64(1) << UInt64(element.bits - 1), radix: 16))"
    let average = x86Builtin(
        name,
        ["first", "second"],
        as: "i\(element.bits)",
        returning: unsigned
    )
    return """
        const \(unsigned) signs = \(splat(signBit, as: unsigned, lanes: element.laneCount));
        const \(unsigned) first = (\(unsigned))a ^ signs;
        const \(unsigned) second = (\(unsigned))b ^ signs;
        \(vectorResult("\(average) ^ signs", for: element))
        """
}

func x86WideRoundedAverage(for element: Element) -> String {
    let words = x86Vector("i64")
    let vector = element.cVector
    let rounded = arithmetic("-", "(\(vector))combined", "halved", for: element)
    return """
        const \(words) combined = (\(words))a | (\(words))b;
        const \(vector) halved = (\(vector))((\(words))a ^ (\(words))b) >> 1;
        \(vectorResult(rounded, for: element))
        """
}

func x86SignedRoundedAverage64(for element: Element) -> String {
    let unsigned = element.cUnsignedVector
    let signBit = "0x\(String(UInt64(1) << UInt64(element.bits - 1), radix: 16))"
    let signs = splat(signBit, as: unsigned, lanes: element.laneCount)
    return """
        const \(unsigned) combined = (\(unsigned))(a | b);
        const \(unsigned) differing = (\(unsigned))a ^ (\(unsigned))b;
        const \(unsigned) halved = (differing >> 1) | (differing & \(signs));
        \(vectorResult("(\(element.cVector))(combined - halved)", for: element))
        """
}

func x86RoundedAverage(level: X86Level, for element: Element) -> String {
    guard element.bits >= 32 else { return x86NarrowRoundedAverage(for: element) }
    guard isSignedInteger64(element), level < .avx3 else {
        return x86WideRoundedAverage(for: element)
    }
    return x86SignedRoundedAverage64(for: element)
}

func convertedLanes(_ operand: String, at indices: [Int], to type: String) -> String {
    let selected = "__builtin_shufflevector(\(operand), \(operand), \(laneIndices(indices)))"
    return "__builtin_convertvector(\(selected), \(type))"
}

func convertedPart(_ operand: String, part: Int, lanes: Int, to type: String) -> String {
    convertedLanes(operand, at: Array(part * lanes..<(part + 1) * lanes), to: type)
}

func vectorTypedef(_ name: String, lane: String, bits: Int, lanes: Int) -> String {
    "typedef \(lane) \(name) __attribute__((vector_size(\(lanes * bits / 8))));"
}

func vectorTypedef(of element: Element) -> String {
    "typedef \(element.cType) \(element.cVector) __attribute__((vector_size(CVECTORIZATION_OPS_VECTOR_BYTES)));"
}

func vectorTypedef(_ name: String, of element: Element, lanes: Int) -> String {
    vectorTypedef(name, lane: element.cType, bits: element.bits, lanes: lanes)
}

func floatTypedefs(bits: Int, lanes: Int, includingSigned: Bool = true) -> String {
    var typedefs = [
        vectorTypedef("float_vector", of: floatElement(bits: bits), lanes: lanes),
        vectorTypedef("unsigned_vector", of: unsignedElement(bits: bits), lanes: lanes),
    ]
    if includingSigned {
        typedefs.append(
            vectorTypedef(
                "signed_vector",
                of: signedElement(of: unsignedElement(bits: bits)),
                lanes: lanes
            )
        )
    }
    return typedefs.joined(separator: "\n")
}

let neonHasFloat16Condition =
    "defined(__ARM_FEATURE_FP16_VECTOR_ARITHMETIC) || HWY_STATIC_TARGET == HWY_NEON_BF16"

func portableInRangeConversion(
    named name: String,
    of operand: String,
    floatBits: Int,
    to integer: Element,
    as type: String,
    lanes: Int
) -> String {
    let isSigned = integer.category == .signedInteger
    let mantissaBits = floatBits == 32 ? 23 : 52
    let exponentBias = floatBits == 32 ? 127 : 1023
    let outOfRangeExponent = exponentBias + integer.bits - (isSigned ? 1 : 0)
    let magnitudeMask = "0x\(String(UInt64.max >> UInt64(65 - floatBits), radix: 16))"
    let magnitude =
        isSigned
        ? "\(name)Bits & \(splat(magnitudeMask, as: "unsigned_vector", lanes: lanes))"
        : "\(name)Bits"
    let threshold = splat(String(outOfRangeExponent), as: "unsigned_vector", lanes: lanes)
    var statements = [
        "const unsigned_vector \(name)Bits = (unsigned_vector)(\(operand));",
        "const signed_vector \(name)InRange = (signed_vector)((\(magnitude)) >> \(mantissaBits) < \(threshold));",
        "const float_vector \(name)Clean = (float_vector)((unsigned_vector)\(name)InRange & \(name)Bits);",
    ]
    guard isSigned else {
        statements.append("const \(type) \(name) = __builtin_convertvector(\(name)Clean, \(type));")
        return statements.joined(separator: "\n")
    }
    let narrowedMask =
        floatBits == integer.bits
        ? "\(name)InRange" : "__builtin_convertvector(\(name)InRange, \(type))"
    let limit = splat(lowestValue(of: integer), as: type, lanes: lanes)
    statements += [
        "const \(type) \(name)Converted = __builtin_convertvector(\(name)Clean, \(type));",
        "const \(type) \(name) = \(name)Converted | (~(\(type))\(narrowedMask) & \(limit));",
    ]
    return statements.joined(separator: "\n")
}

func selectedLanes(_ mask: String, _ yes: String, _ no: String, as type: String) -> String {
    let chosen = "((unsigned_vector)\(mask) & (unsigned_vector)\(yes))"
    let rest = "(~(unsigned_vector)\(mask) & (unsigned_vector)\(no))"
    return "(\(type))(\(chosen) | \(rest))"
}

func convertingToFloat64(_ operand: String, _ integer: Element) -> String {
    "__builtin_convertvector(\(operand), float_vector)"
}

func longDividing(
    for element: Element,
    declarations: String = "",
    convertingToFloat toFloat: (_ operand: String, _ integer: Element) -> String =
        convertingToFloat64,
    convertingToInteger toInteger: (
        _ name: String, _ operand: String, _ type: String, _ integer: Element
    ) -> String,
    preparing preparation: String? = nil,
    selectingBySign select: (
        (_ sign: String, _ yes: String, _ no: String, _ type: String) -> String
    )? = nil,
    correcting correction: String? = nil
) -> String {
    let isSigned = element.category == .signedInteger
    let lanes = element.laneCount
    let vector = element.cVector
    let signed = signedElement(of: element).at(width: element.width)
    let zero = compoundLiteral("signed_vector", ["0"])
    var statements = [
        floatTypedefs(bits: 64, lanes: lanes),
        declarations,
        "const signed_vector zero = \(zero);",
        "const float_vector floatOnes = \(splat("1.0", as: "float_vector", lanes: lanes));",
    ]
    if isSigned {
        statements += ["const \(vector) dividend = a;", "const \(vector) divisor = b;"]
    } else if let preparation {
        statements.append(preparation)
    } else if let select {
        statements += [
            "const unsigned_vector ones = \(splat("1", as: "unsigned_vector", lanes: lanes));",
            "const unsigned_vector atLeast = (unsigned_vector)((signed_vector)a >= (signed_vector)b) & (a >> 63);",
            "const \(vector) dividend = \(select("b", "atLeast", "a", vector));",
            "const \(vector) divisor = \(select("b", "ones", "b", vector));",
        ]
    } else {
        let highDividend = "((unsigned_vector)(a >= b) & ones)"
        statements += [
            "const unsigned_vector ones = \(splat("1", as: "unsigned_vector", lanes: lanes));",
            "const unsigned_vector highDivisors = (unsigned_vector)((signed_vector)b < zero);",
            "const \(vector) dividend = \(selectedLanes("highDivisors", highDividend, "a", as: vector));",
            "const \(vector) divisor = \(selectedLanes("highDivisors", "ones", "b", as: vector));",
        ]
    }
    let firstProduct = multipliedLanes("firstQuotient", "divisor", for: element)
    let secondProduct = multipliedLanes("secondQuotient", "divisor", for: element)
    statements += [
        "const float_vector reciprocal = floatOnes / \(toFloat("divisor", element));",
        toInteger(
            "firstQuotient",
            "\(toFloat("dividend", element)) * reciprocal",
            vector,
            element
        ),
        "const unsigned_vector firstRemainder = (unsigned_vector)dividend - (unsigned_vector)\(firstProduct);",
        toInteger(
            "secondQuotient",
            "\(toFloat("(signed_vector)firstRemainder", signed)) * reciprocal",
            "signed_vector",
            signed
        ),
        "const unsigned_vector secondRemainder = firstRemainder - (unsigned_vector)\(secondProduct);",
        "const signed_vector remainder = (signed_vector)secondRemainder;",
    ]
    if isSigned {
        let adjusted =
            select?("a", "(zero - remainder)", "remainder", "signed_vector")
            ?? selectedLanes(
                "(a < zero)",
                "(signed_vector)(-secondRemainder)",
                "remainder",
                as: "signed_vector"
            )
        let absolute =
            select?("b", "(zero - b)", "b", "unsigned_vector")
            ?? "(unsigned_vector)__builtin_elementwise_abs(b)"
        statements += [
            "const signed_vector adjustedRemainder = \(adjusted);",
            "const unsigned_vector magnitude = \(absolute);",
            "const signed_vector negation = (signed_vector)(secondRemainder ^ (unsigned_vector)b);",
        ]
    } else {
        statements += [
            "const signed_vector adjustedRemainder = remainder;",
            "const unsigned_vector magnitude = divisor;",
            "const signed_vector negation = remainder;",
        ]
    }
    let signedCorrection: String
    if let select {
        let negated = select("negation", "(zero - correction)", "correction", "signed_vector")
        signedCorrection = "const signed_vector signedCorrection = \(negated);"
    } else {
        signedCorrection = """
            const signed_vector signs = (signed_vector)(negation < zero);
            const signed_vector signedCorrection = (correction ^ signs) - signs;
            """
    }
    statements += [
        correction ?? """
            const signed_vector correction = (signed_vector)((unsigned_vector)adjustedRemainder >= magnitude);
            \(signedCorrection)
            """,
        vectorResult(
            "(unsigned_vector)firstQuotient + (unsigned_vector)secondQuotient - (unsigned_vector)signedCorrection",
            for: element
        ),
    ]
    return statements.filter { !$0.isEmpty }.joined(separator: "\n")
}

func narrowingStatements(
    of quotients: [String],
    from wideBits: Int,
    as type: String,
    combining combine: (_ first: String, _ second: String, _ narrowBits: Int) -> String
) -> (statements: [String], result: String) {
    var names = quotients
    var bits = wideBits
    var statements: [String] = []
    var level = 0
    while true {
        bits /= 2
        let combined = stride(from: 0, to: names.count, by: 2).map {
            combine(names[$0], names[$0 + 1], bits)
        }
        guard combined.count > 1 else { return (statements, combined[0]) }
        names = combined.indices.map { "narrowed\(level)_\($0)" }
        statements += zip(names, combined).map { "const \(type) \($0) = \($1);" }
        level += 1
    }
}

func neonConvertedToInteger(_ operand: String, _ integer: Element) -> String {
    let sign = integer.category == .signedInteger ? "s" : "u"
    let builtin = integer.bits == 16 ? "vcvtq_\(sign)16_f16" : "vcvtq_\(sign)\(integer.bits)_v"
    let code = neonTypeCode(of: integer)
    return "__builtin_neon_\(builtin)((\(neonVector("i8")))(\(operand)), \(code))"
}

func neonConvertingToInteger(
    _ name: String,
    _ operand: String,
    _ type: String,
    _ integer: Element
) -> String {
    "const \(type) \(name) = (\(type))\(neonConvertedToInteger(operand, integer));"
}

func neonSaturatingNarrowing(
    _ first: String,
    _ second: String,
    toBits bits: Int,
    as element: Element
) -> String {
    let halves = neonVector("i8x8")
    let narrow = resizedElement(of: element, bits: bits)
    let code = neonTypeCode(of: narrow) - 32
    func narrowed(_ operand: String) -> String {
        "(\(halves))__builtin_neon_vqmovn_v((\(neonVector("i8")))\(operand), \(code))"
    }
    let combined =
        "__builtin_shufflevector(\(narrowed(first)), \(narrowed(second)), \(laneIndices(0..<16)))"
    return "(\(neonVector("i8")))\(combined)"
}

func neonPartsDividing(for element: Element, floatBits: Int) -> String {
    let wide = resizedElement(of: element, bits: floatBits)
    let parts = floatBits / element.bits
    let lanes = wide.laneCount
    let carrier = neonVector("i8")
    let float = "float_vector"
    let lane = floatBits == 16 ? "_Float16" : floatElement(bits: floatBits).cType
    var statements = [vectorTypedef(float, lane: lane, bits: floatBits, lanes: lanes)]
    let usesHalves = element.bits == 8 && floatBits == 32
    if usesHalves {
        let half = resizedElement(of: element, bits: 16)
        statements.append(vectorTypedef("half_vector", of: half, lanes: 2 * lanes))
        for name in ["a", "b"] {
            for (position, side) in ["low", "high"].enumerated() {
                let converted = convertedPart(
                    name,
                    part: position,
                    lanes: 2 * lanes,
                    to: "half_vector"
                )
                statements.append("const half_vector \(side)\(name.uppercased()) = \(converted);")
            }
        }
    }
    func converted(_ operand: String, part: Int) -> String {
        guard usesHalves else { return convertedPart(operand, part: part, lanes: lanes, to: float) }
        let half = "\(part < 2 ? "low" : "high")\(operand.uppercased())"
        return convertedPart(half, part: part % 2, lanes: lanes, to: float)
    }
    func quotient(_ part: Int) -> String {
        "\(converted("a", part: part)) / \(converted("b", part: part))"
    }
    if floatBits == 64 {
        statements += [1, 0].map { "const \(float) division\($0) = \(quotient($0));" }
        statements += [1, 0].map {
            neonConvertingToInteger("quotient\($0)", "division\($0)", carrier, wide)
        }
    } else {
        statements += (0..<parts).map {
            neonConvertingToInteger("quotient\($0)", quotient($0), carrier, wide)
        }
    }
    let narrowing = narrowingStatements(
        of: (0..<parts).map { "quotient\($0)" },
        from: floatBits,
        as: carrier
    ) { first, second, bits in
        neonSaturatingNarrowing(first, second, toBits: bits, as: element)
    }
    return (statements + narrowing.statements + [vectorResult(narrowing.result, for: element)])
        .joined(separator: "\n")
}

func neonPreparation(for element: Element) -> String {
    let vector = element.cVector
    return """
        const unsigned_vector highDivisors = (unsigned_vector)((signed_vector)b < zero);
        const unsigned_vector atLeast = (unsigned_vector)(a >= b) >> 63;
        const \(vector) dividend = \(selectedLanes("highDivisors", "atLeast", "a", as: vector));
        const \(vector) divisor = (\(vector))(((unsigned_vector)b & ~highDivisors) + (highDivisors >> 63));
        """
}

func neonDividing(for element: Element) -> String {
    switch element.bits {
    case 64:
        return longDividing(
            for: element,
            convertingToInteger: neonConvertingToInteger,
            preparing: neonPreparation(for: element)
        )
    case 32: return neonPartsDividing(for: element, floatBits: 64)
    case 16: return neonPartsDividing(for: element, floatBits: 32)
    default:
        return """
            #if \(neonHasFloat16Condition)
            \(neonPartsDividing(for: element, floatBits: 16))
            #else
            \(neonPartsDividing(for: element, floatBits: 32))
            #endif
            """
    }
}

func portableDividing(for element: Element) -> String {
    let lanes = element.laneCount
    guard element.bits < 64 else {
        return longDividing(for: element) { name, operand, type, integer in
            portableInRangeConversion(
                named: name,
                of: operand,
                floatBits: 64,
                to: integer,
                as: type,
                lanes: lanes
            )
        }
    }
    let floatBits = element.bits == 32 ? 64 : 32
    let declarations = floatTypedefs(bits: floatBits, lanes: lanes)
    let float = "float_vector"
    let quotient =
        "const \(float) quotient = __builtin_convertvector(a, \(float)) / __builtin_convertvector(b, \(float));"
    guard element.bits < 32 else {
        let conversion = portableInRangeConversion(
            named: "result",
            of: "quotient",
            floatBits: floatBits,
            to: element,
            as: element.cVector,
            lanes: lanes
        )
        return [declarations, quotient, conversion, vectorResult("result", for: element)]
            .joined(separator: "\n")
    }
    let wide = resizedElement(of: element, bits: floatBits)
    let conversion = portableInRangeConversion(
        named: "converted",
        of: "quotient",
        floatBits: floatBits,
        to: wide,
        as: "wide_vector",
        lanes: lanes
    )
    let low = splat(lowestValue(of: element), as: "wide_vector", lanes: lanes)
    let high = splat(highestValue(of: element), as: "wide_vector", lanes: lanes)
    let floored =
        element.category == .signedInteger
        ? "__builtin_elementwise_max(converted, \(low))" : "converted"
    let saturated = "__builtin_elementwise_min(\(floored), \(high))"
    let narrowed = "__builtin_convertvector(\(saturated), \(element.cVector))"
    return [
        declarations,
        vectorTypedef("wide_vector", of: wide, lanes: lanes),
        quotient,
        conversion,
        vectorResult(narrowed, for: element),
    ].joined(separator: "\n")
}

func concatenatedParts(_ parts: [String], lanes: Int) -> String {
    guard parts.count > 1 else { return parts[0] }
    let indices = laneIndices(0..<2 * lanes)
    let pairs = stride(from: 0, to: parts.count, by: 2).map {
        "__builtin_shufflevector(\(parts[$0]), \(parts[$0 + 1]), \(indices))"
    }
    return concatenatedParts(pairs, lanes: 2 * lanes)
}

func x86Truncating(_ operand: String, to result: String, using name: String, width: Int) -> String {
    let isSingle = name.hasPrefix("cvttps")
    let source = "(\(x86Vector(isSingle ? "f32" : "f64")))\(operand)"
    guard width == 64 else {
        let call = "__builtin_ia32_\(name)\(x86UnsuffixedBits(width))(\(source))"
        guard width == 16 && !isSingle else { return "(\(result))\(call)" }
        let block = "(\(x86Block("i32")))\(call)"
        return "(\(result))__builtin_shufflevector(\(block), \(block), 0, 1)"
    }
    let zero = compoundLiteral(result, ["0"])
    let mask = isSingle ? "(unsigned short)-1" : "(unsigned char)-1"
    let arguments = [source, zero, mask, "\(x86CurrentRounding)"].joined(separator: ", ")
    return "(\(result))__builtin_ia32_\(name)512_mask(\(arguments))"
}

func x86Packing(
    _ name: String,
    _ first: String,
    _ second: String,
    from source: String,
    to result: String,
    width: Int
) -> String {
    let operands = [first, second].map { "(\(x86Vector(source)))\($0)" }
    let call = "__builtin_ia32_\(name)\(x86Bits(width))(\(operands.joined(separator: ", ")))"
    return "(\(x86Vector(result)))\(call)"
}

func x86PartsDividing(level: X86Level, for element: Element, remainder: Bool = false) -> String {
    let parts = 32 / element.bits
    let blocks = element.width / 16
    let isSigned = element.category == .signedInteger
    let wide = signedElement(of: resizedElement(of: element, bits: 32))
    func blockwise(start: Int, count: Int, perBlock: Int) -> [Int] {
        (0..<blocks).flatMap { block in (0..<count).map { block * perBlock + start + $0 } }
    }
    var statements = [
        vectorTypedef("float_vector", of: floatElement(bits: 32), lanes: blocks * 4),
        vectorTypedef("wide_vector", of: wide, lanes: blocks * 4),
    ]
    let usesHalves = element.bits == 8 && (blocks == 1 || remainder)
    if usesHalves {
        let half = resizedElement(of: element, bits: 16)
        statements.append(vectorTypedef("half_vector", of: half, lanes: blocks * 8))
        for (name, operand) in [("A", "a"), ("B", "b")] {
            for (position, half) in ["low", "high"].enumerated() {
                let lanes = blockwise(start: position * 8, count: 8, perBlock: 16)
                statements.append(
                    "const half_vector \(half)\(name) = \(convertedLanes(operand, at: lanes, to: "half_vector"));"
                )
            }
        }
    }
    let downConverts = !remainder && blocks == 4 && (element.bits == 16 || isSigned)
    let continuous = downConverts || (element.bits == 16 && blocks > 1)
    let extendsByShuffling = !usesHalves && !isSigned && blocks > 1 && !continuous
    if extendsByShuffling {
        statements.append(
            "const \(element.cVector) zero = \(compoundLiteral(element.cVector, ["0"]));"
        )
    }
    func floating(_ operand: String, part: Int) -> String {
        if usesHalves {
            let half = "\(part < 2 ? "low" : "high")\(operand.uppercased())"
            let lanes = blockwise(start: part % 2 * 4, count: 4, perBlock: 8)
            return convertedLanes(half, at: lanes, to: "float_vector")
        }
        let lanes =
            continuous
            ? Array(part * blocks * 4..<(part + 1) * blocks * 4)
            : blockwise(start: part * 4, count: 4, perBlock: element.blockLaneCount)
        guard extendsByShuffling else {
            return convertedLanes(operand, at: lanes, to: "float_vector")
        }
        let zeros = Array(repeating: element.laneCount, count: parts - 1)
        let shuffled =
            "__builtin_shufflevector(\(operand), zero, \(laneIndices(lanes.flatMap { [$0] + zeros })))"
        return "__builtin_convertvector((wide_vector)\(shuffled), float_vector)"
    }
    for part in 0..<parts {
        let truncated = x86Truncating(
            "(\(floating("a", part: part)) / \(floating("b", part: part)))",
            to: "wide_vector",
            using: "cvttps2dq",
            width: element.width
        )
        statements.append("const wide_vector quotient\(part) = \(truncated);")
    }
    func packed(
        _ name: String,
        _ first: String,
        _ second: String,
        from: String,
        to: String
    ) -> String {
        x86Packing(name, first, second, from: from, to: to, width: element.width)
    }
    if downConverts {
        statements.append(vectorTypedef("narrow_vector", of: element, lanes: 16))
        let name = "pmovsd\(x86LaneLetter(bits: element.bits))512_mask"
        for part in 0..<parts {
            let operands = [
                "(\(x86Vector("i32")))quotient\(part)", compoundLiteral("narrow_vector", ["0"]),
                "(unsigned short)-1",
            ]
            let saturated = "__builtin_ia32_\(name)(\(operands.joined(separator: ", ")))"
            let truncated = "__builtin_convertvector(quotient\(part), narrow_vector)"
            statements.append(
                "const narrow_vector narrowed\(part) = \(isSigned ? "(narrow_vector)\(saturated)" : truncated);"
            )
        }
        let concatenated = concatenatedParts((0..<parts).map { "narrowed\($0)" }, lanes: 16)
        return (statements + [vectorResult(concatenated, for: element)]).joined(separator: "\n")
    }
    var quotients = (0..<parts).map { "quotient\($0)" }
    let extendsLowHalves = element.bits == 16 && !isSigned && level < .sse4
    if extendsLowHalves {
        statements.append(
            vectorTypedef(
                "wide_unsigned_vector",
                of: unsignedElement(of: unsignedElement(bits: 32)),
                lanes: blocks * 4
            )
        )
        for part in 0..<parts {
            let clamped = "quotient\(part) & ~(quotient\(part) >> 31)"
            let extended = "(wide_vector)((wide_unsigned_vector)(\(clamped)) << 16) >> 16"
            statements.append("const wide_vector extended\(part) = \(extended);")
        }
        quotients = (0..<parts).map { "extended\($0)" }
    }
    let result: String
    if element.bits == 8 {
        let low = packed("packssdw", quotients[0], quotients[1], from: "i32", to: "i16")
        let high = packed("packssdw", quotients[2], quotients[3], from: "i32", to: "i16")
        if remainder {
            statements += x86PartsRemainder(low: low, high: high, for: element)
        }
        result =
            remainder
            ? packed(
                isSigned ? "packsswb" : "packuswb",
                "lowRemainder",
                "highRemainder",
                from: "i16",
                to: "i8"
            ) : packed(isSigned ? "packsswb" : "packuswb", low, high, from: "i16", to: "i8")
    } else {
        let name = isSigned || extendsLowHalves ? "packssdw" : "packusdw"
        let words = packed(name, quotients[0], quotients[1], from: "i32", to: "i16")
        let ordering = (0..<blocks).map { 2 * $0 } + (0..<blocks).map { 2 * $0 + 1 }
        let quads = x86Vector("i64")
        result =
            continuous
            ? "__builtin_shufflevector((\(quads))\(words), (\(quads))\(words), \(laneIndices(ordering)))"
            : words
    }
    return (statements + [vectorResult(result, for: element)]).joined(separator: "\n")
}

func x86PartsRemainder(low: String, high: String, for element: Element) -> [String] {
    var statements = [
        vectorTypedef(
            "half_unsigned_vector",
            of: unsignedElement(bits: 16),
            lanes: element.width / 2
        )
    ]
    for (side, quotient) in [("low", low), ("high", high)] {
        let product = "(half_unsigned_vector)\(quotient) * (half_unsigned_vector)\(side)B"
        statements.append(
            "const half_vector \(side)Remainder = (half_vector)((half_unsigned_vector)\(side)A - \(product));"
        )
    }
    return statements
}

func x86Remainder(level: X86Level, for element: Element) -> String? {
    if element.bits == 32 && element.width == 16 {
        let product = arithmetic("*", "quotient", "b", for: element)
        return """
            const \(element.cVector) quotient = \(operationCall("dividing", ["a", "b"], for: element));
            \(vectorResult(arithmetic("-", "a", "(\(element.cVector))(\(product))", for: element), for: element))
            """
    }
    guard element.bits == 8 else { return nil }
    guard element.width > 16 else {
        return x86PartsDividing(level: level, for: element, remainder: true)
    }
    return x86OrderedRemainder(for: element)
}

func x86OrderedRemainder(for element: Element) -> String {
    let lanes = element.laneCount
    let width = element.width
    let isSigned = element.category == .signedInteger
    let words = resizedElement(of: element, bits: 16)
    func ordered(_ packed: String, as suffix: String) -> String {
        let quads = x86Vector("i64")
        let reordered =
            width == 32
            ? "__builtin_shufflevector((\(quads))\(packed), (\(quads))\(packed), 0, 2, 1, 3)"
            : "__builtin_ia32_permvardi512((\(quads))\(packed), indices)"
        return "(\(x86Vector(suffix)))\(reordered)"
    }
    var statements = [
        vectorTypedef("half_vector", of: words, lanes: lanes / 2),
        vectorTypedef("half_unsigned_vector", of: unsignedElement(bits: 16), lanes: lanes / 2),
        vectorTypedef("float_vector", of: floatElement(bits: 32), lanes: lanes / 4),
        vectorTypedef(
            "wide_vector",
            of: signedElement(of: resizedElement(of: element, bits: 32)),
            lanes: lanes / 4
        ),
    ]
    if width == 64 {
        let indices = compoundLiteral(x86Vector("i64"), ["0", "2", "4", "6", "1", "3", "5", "7"])
        statements += [
            "\(x86Vector("i64")) indices = \(indices);",
            "__asm__(\"\" : \"+v\"(indices));",
        ]
    }
    for (side, start) in [("low", 0), ("high", lanes / 2)] {
        for (name, operand) in [("A", "a"), ("B", "b")] {
            let halves = convertedLanes(
                operand,
                at: Array(start..<start + lanes / 2),
                to: "half_vector"
            )
            statements.append("const half_vector \(side)\(name) = \(halves);")
        }
        for part in 0..<2 {
            let parts = Array(part * lanes / 4..<(part + 1) * lanes / 4)
            let (first, second) = (
                convertedLanes("\(side)A", at: parts, to: "float_vector"),
                convertedLanes("\(side)B", at: parts, to: "float_vector")
            )
            let quotient = x86Truncating(
                "(\(first) / \(second))",
                to: "wide_vector",
                using: "cvttps2dq",
                width: width
            )
            statements.append("const wide_vector \(side)Quotient\(part) = \(quotient);")
        }
        let packed = x86Packing(
            "packssdw",
            "\(side)Quotient0",
            "\(side)Quotient1",
            from: "i32",
            to: "i16",
            width: width
        )
        let product = "(half_unsigned_vector)\(side)Quotients * (half_unsigned_vector)\(side)B"
        statements += [
            "const half_vector \(side)Quotients = (half_vector)\(ordered(packed, as: "i16"));",
            "const half_vector \(side)Remainder = (half_vector)((half_unsigned_vector)\(side)A - \(product));",
        ]
    }
    let narrowed = x86Packing(
        isSigned ? "packsswb" : "packuswb",
        "lowRemainder",
        "highRemainder",
        from: "i16",
        to: "i8",
        width: width
    )
    return (statements + [vectorResult(ordered(narrowed, as: "i8"), for: element)])
        .joined(separator: "\n")
}

func x86HalvesDividing(level: X86Level, for element: Element) -> String {
    let lanes = element.laneCount / 2
    let isUnsigned = element.category == .unsignedInteger
    let emulates = isUnsigned && level < .avx3
    let name = "cvttpd2\(isUnsigned && !emulates ? "u" : "")dq"
    var statements = [
        vectorTypedef("float_vector", of: floatElement(bits: 64), lanes: lanes),
        vectorTypedef("half_vector", of: element, lanes: lanes),
    ]
    if emulates {
        statements += [
            floatTypedefs(bits: 64, lanes: lanes),
            "const float_vector limit = \(splat("2147483648.0", as: "float_vector", lanes: lanes));",
        ]
    }
    for part in [1, 0] {
        let first = convertedPart("a", part: part, lanes: lanes, to: "float_vector")
        let second = convertedPart("b", part: part, lanes: lanes, to: "float_vector")
        statements.append("const float_vector quotient\(part) = \(first) / \(second);")
    }
    for part in [1, 0] {
        let reduced =
            "quotient\(part) - (float_vector)((unsigned_vector)high\(part) & (unsigned_vector)limit)"
        let truncated = x86Truncating(
            emulates ? "reduced\(part)" : "quotient\(part)",
            to: "half_vector",
            using: name,
            width: element.width
        )
        guard emulates else {
            statements.append("const half_vector converted\(part) = \(truncated);")
            continue
        }
        statements += [
            "const signed_vector high\(part) = (signed_vector)(quotient\(part) >= limit);",
            "const float_vector reduced\(part) = \(reduced);",
            "const half_vector converted\(part) = \(truncated) | ((half_vector)__builtin_convertvector(high\(part), half_vector) << 31);",
        ]
    }
    let concatenated = concatenatedParts(["converted0", "converted1"], lanes: lanes)
    return (statements + [vectorResult(concatenated, for: element)]).joined(separator: "\n")
}

func x86VariableShift(_ operand: String, by counts: String, left: Bool, width: Int) -> String {
    let words = x86Vector("i64")
    let name = "ps\(left ? "ll" : "rl")"
    guard width == 16 else {
        let shifted = "__builtin_ia32_\(name)v4di((\(words))\(operand), (\(words))\(counts))"
        return "(unsigned_vector)\(shifted)"
    }
    func shifted(_ count: String) -> String {
        "(\(words))__builtin_ia32_\(name)q128((\(words))\(operand), (\(words))\(count))"
    }
    let upper = "__builtin_shufflevector(\(counts), \(counts), 1, 1)"
    return "(unsigned_vector)__builtin_shufflevector(\(shifted(counts)), \(shifted(upper)), 0, 3)"
}

func x86EmulatedConversion(
    named name: String,
    of operand: String,
    as type: String,
    to integer: Element,
    width: Int
) -> String {
    let lanes = integer.laneCount
    let isSigned = integer.category == .signedInteger
    let exponentBias = splat("1075", as: "unsigned_vector", lanes: lanes)
    let exponents =
        isSigned
        ? "(\(name)Bits >> 52) & \(splat("0x7FF", as: "unsigned_vector", lanes: lanes))"
        : "\(name)Bits >> 52"
    let mantissa =
        "(\(name)Bits & \(splat("0xFFFFFFFFFFFFFull", as: "unsigned_vector", lanes: lanes))) | \(splat("0x10000000000000ull", as: "unsigned_vector", lanes: lanes))"
    func saturatedDifference(_ first: String, _ second: String) -> String {
        "(unsigned_vector)__builtin_elementwise_sub_sat((narrow_vector)\(first), (narrow_vector)\(second))"
    }
    let right = x86VariableShift(
        "\(name)Mantissa",
        by: "\(name)MantissaShift",
        left: false,
        width: width
    )
    let magnitude = x86VariableShift(
        "\(name)Shifted",
        by: "\(name)IntegerShift",
        left: true,
        width: width
    )
    var statements = [
        "const float_vector \(name)Float = \(operand);",
        "const unsigned_vector \(name)Bits = (unsigned_vector)\(name)Float;",
        "const unsigned_vector \(name)Exponent = \(exponents);",
        "const unsigned_vector \(name)MantissaShift = \(saturatedDifference(exponentBias, "\(name)Exponent"));",
        "const unsigned_vector \(name)IntegerShift = \(saturatedDifference("\(name)Exponent", exponentBias));",
        "const unsigned_vector \(name)Mantissa = \(mantissa);",
        "const unsigned_vector \(name)Shifted = \(right);",
        "const unsigned_vector \(name)Magnitude = \(magnitude);",
    ]
    if isSigned {
        statements += [
            "const unsigned_vector \(name)Signs = (unsigned_vector)((signed_vector)\(name)Bits < zero);",
            "const \(type) \(name) = (\(type))((\(name)Magnitude ^ \(name)Signs) - \(name)Signs);",
        ]
    } else {
        statements.append("const \(type) \(name) = (\(type))\(name)Magnitude;")
    }
    return statements.joined(separator: "\n")
}

func x86ConvertingToInteger64(
    level: X86Level,
    width: Int
) -> (_ name: String, _ operand: String, _ type: String, _ integer: Element) -> String {
    { name, operand, type, integer in
        let isSigned = integer.category == .signedInteger
        if level >= .avx3 {
            let truncated = x86Truncating(
                operand,
                to: type,
                using: "cvttpd2\(isSigned ? "" : "u")qq",
                width: width
            )
            return "const \(type) \(name) = \(truncated);"
        }
        guard isSigned && level < .avx2 else {
            return x86EmulatedConversion(
                named: name,
                of: operand,
                as: type,
                to: integer,
                width: width
            )
        }
        let float = x86Vector("f64")
        let upper = "__builtin_shufflevector(\(name)Float, \(name)Float, 1, 1)"
        let lanes = ["\(name)Float", upper].map {
            "__builtin_ia32_cvttsd2si64((\(float))\($0))"
        }
        return """
            const float_vector \(name)Float = \(operand);
            const \(type) \(name) = \(compoundLiteral(type, lanes));
            """
    }
}

func x86ConvertingToFloat64(_ operand: String, _ integer: Element) -> String {
    let lanes = integer.laneCount
    func constant(_ bits: String) -> String {
        splat("\(bits)ull", as: "unsigned_vector", lanes: lanes)
    }
    let bits = "(unsigned_vector)(\(operand))"
    let exponent = splat("0x43300000", as: "words_vector", lanes: 2 * lanes)
    let evens = (0..<2 * lanes).map { $0 % 2 == 0 ? $0 : 2 * lanes + $0 }
    let blended =
        "__builtin_shufflevector((words_vector)\(bits), \(exponent), \(laneIndices(evens)))"
    let lower = "(float_vector)\(blended)"
    let offset = "(float_vector)\(constant("0x4330000000000000"))"
    guard integer.category == .signedInteger else {
        let high = "(float_vector)((\(bits) >> 32) | \(constant("0x4330000000000000")))"
        let scale = splat("4294967296.0", as: "float_vector", lanes: lanes)
        return "((\(high) - \(offset)) * \(scale) + (\(lower) - \(offset)))"
    }
    let upper = "(float_vector)((\(bits) >> 32) ^ \(constant("0x4530000080000000")))"
    return "((\(upper) - (float_vector)\(constant("0x4530000080100000"))) + \(lower))"
}

func x86Avx3Preparation(for element: Element) -> String {
    let words = x86Vector("i64")
    let vector = element.cVector
    let ones = splat("1", as: "unsigned_vector", lanes: element.laneCount)
    return """
        const unsigned_vector ones = \(ones);
        const unsigned char highDivisors = __builtin_ia32_cvtq2mask512((\(words))b);
        const unsigned char notBelow = __builtin_ia32_ucmpq512_mask((\(words))a, (\(words))b, 5, -1);
        const unsigned_vector atLeast = (unsigned_vector)__builtin_ia32_cvtmask2q512(notBelow) >> 63;
        const \(vector) dividend = (\(vector))__builtin_ia32_selectq_512(highDivisors, (\(words))atLeast, (\(words))a);
        const \(vector) divisor = (\(vector))__builtin_ia32_selectq_512(highDivisors, (\(words))ones, (\(words))b);
        """
}

let x86Avx3Correction = """
    const unsigned char exceeds = __builtin_ia32_ucmpq512_mask((\(x86Vector("i64")))adjustedRemainder, (\(x86Vector("i64")))magnitude, 5, -1);
    const signed_vector correction = (signed_vector)__builtin_ia32_cvtmask2q512(exceeds);
    const unsigned char nonNegative = __builtin_ia32_cmpq512_mask((\(x86Vector("i64")))negation, (\(x86Vector("i64")))zero, 5, -1);
    const signed_vector signedCorrection = (signed_vector)__builtin_ia32_selectq_512(nonNegative, (\(x86Vector("i64")))correction, (\(x86Vector("i64")))(zero - correction));
    """

func x86SelectingBySign(
    _ sign: String,
    _ yes: String,
    _ no: String,
    as type: String,
    for element: Element
) -> String {
    x86Builtin(
        "blendvpd\(x86UnsuffixedBits(element.width))",
        [no, yes, sign],
        as: "f64",
        returning: type
    )
}

func x86LongDividing(level: X86Level, for element: Element) -> String {
    let typedefs = [
        (
            name: "narrow_vector",
            declaration: vectorTypedef(
                "narrow_vector",
                lane: "uint16_t",
                bits: 16,
                lanes: element.laneCount * 4
            )
        ),
        (
            name: "words_vector",
            declaration: vectorTypedef(
                "words_vector",
                lane: "uint32_t",
                bits: 32,
                lanes: element.laneCount * 2
            )
        ),
    ]
    func dividing(declaring declarations: [String]) -> String {
        longDividing(
            for: element,
            declarations: declarations.joined(separator: "\n"),
            convertingToFloat: level == .avx2 ? x86ConvertingToFloat64 : convertingToFloat64,
            convertingToInteger: x86ConvertingToInteger64(level: level, width: element.width),
            preparing: level >= .avx3 ? x86Avx3Preparation(for: element) : nil,
            selectingBySign: level == .avx2
                ? { x86SelectingBySign($0, $1, $2, as: $3, for: element) } : nil,
            correcting: level >= .avx3 ? x86Avx3Correction : nil
        )
    }
    guard level < .avx3 else { return dividing(declaring: []) }
    let used = identifiers(in: dividing(declaring: []))
    return dividing(declaring: typedefs.filter { used.contains($0.name) }.map(\.declaration))
}

func identifiers(in source: String) -> Set<String> {
    Set(source.split { !($0.isLetter || $0.isNumber || $0 == "_") }.map(String.init))
}

func x86Dividing(level: X86Level, for element: Element) -> String {
    switch element.bits {
    case 64: return x86LongDividing(level: level, for: element)
    case 32: return x86HalvesDividing(level: level, for: element)
    default: return x86PartsDividing(level: level, for: element)
    }
}

func sveDividing(for element: Element) -> String {
    guard element.bits < 32 else {
        let operands = [sveAllLanes(of: element)] + ["a", "b"].map { sveOperand($0, for: element) }
        let divided = sveBuiltin("div", operands, for: element, predication: "x")
        let plain = vectorResult(sveResult(divided, for: element), for: element)
        let splat = sveSplatBinary("div", nil, commutative: false, for: element)
        return [splat, plain].compactMap { $0 }.joined(separator: "\n")
    }
    let sixteen = resizedElement(of: element, bits: 16)
    let word = resizedElement(of: element, bits: 32)
    var statements: [String] = []
    func widened(_ name: String, of source: String, through steps: [Element]) -> [String] {
        guard let wide = steps.first else { return [name] }
        return [("Even", "movlb"), ("Odd", "movlt")].flatMap { half, instruction in
            let child = "\(name)\(half)"
            let call = sveBuiltin(instruction, [source], for: wide)
            statements.append("const \(sveType(of: wide)) \(child) = \(call);")
            return widened(child, of: child, through: Array(steps.dropFirst()))
        }
    }
    let steps = element.bits == 8 ? [sixteen, word] : [word]
    let leaves = ["a", "b"].map { widened($0, of: sveOperand($0, for: element), through: steps) }
    var quotients: [String] = []
    for (first, second) in zip(leaves[0], leaves[1]) {
        let operands = [sveAllLanes(of: word), first, second]
        let quotient = "quotient\(first.dropFirst())"
        let divided = sveBuiltin("div", operands, for: word, predication: "x")
        statements.append("const \(sveType(of: word)) \(quotient) = \(divided);")
        quotients.append(quotient)
    }
    func narrowed(_ low: String, _ high: String, from wide: Element) -> String {
        sveBuiltin("qxtnt", [sveBuiltin("qxtnb", [low], for: wide), high], for: wide)
    }
    var result = narrowed(quotients[0], quotients[1], from: word)
    if element.bits == 8 {
        for (name, pair) in [("Even", 0), ("Odd", 2)] {
            let halves = narrowed(quotients[pair], quotients[pair + 1], from: word)
            statements.append("const \(sveType(of: sixteen)) quotients\(name) = \(halves);")
        }
        result = narrowed("quotientsEven", "quotientsOdd", from: sixteen)
    }
    return (statements + [vectorResult(sveResult(result, for: element), for: element)])
        .joined(separator: "\n")
}

func portableFloatDividing(for element: Element) -> String {
    let vector = element.cVector
    let unsigned = element.cUnsignedVector
    let lanes = element.laneCount
    let signBit = "0x\(String(UInt64(1) << UInt64(element.bits - 1), radix: 16))"
    let infinityBits = unsignedBits("infinity", of: element)
    let divisor = bitSelect("zeroDenominator", "ones", "b", of: element)
    let signedInfinity = fromUnsignedBits("\(infinityBits) | signs", of: element)
    let zeroQuotient = bitSelect(
        "zeroOrNaNNumerator",
        "indeterminate",
        "signedInfinity",
        of: element
    )
    let result = bitSelect("zeroDenominator", "zeroQuotient", "quotient", of: element)
    return """
        const \(vector) zero = \(compoundLiteral(vector, ["0"]));
        const \(vector) ones = \(splat("1", as: vector, lanes: lanes));
        const \(vector) infinity = \(splat(infinity(of: element), as: vector, lanes: lanes));
        const \(unsigned) signBits = \(splat(signBit, as: unsigned, lanes: lanes));
        const \(unsigned) zeroDenominator = (\(unsigned))(b == zero);
        const \(unsigned) zeroOrNaNNumerator = (\(unsigned))((a == zero) | (a != a));
        const \(vector) quotient = a / \(divisor);
        const \(vector) indeterminate = a + (infinity * zero);
        const \(unsigned) signs = ((\(unsigned))a ^ (\(unsigned))b) & signBits;
        const \(vector) signedInfinity = \(signedInfinity);
        const \(vector) zeroQuotient = \(zeroQuotient);
        \(vectorResult(result, for: element))
        """
}

func portableMagnitude(for element: Element) -> String {
    vectorResult("__builtin_elementwise_abs(a)", for: element)
}

func x86Magnitude(level: X86Level, for element: Element) -> String? {
    guard element.category == .signedInteger, element.bits >= 32 else { return nil }
    let zero = compoundLiteral(element.cVector, ["0"])
    let negated = "const \(element.cVector) negated = \(arithmetic("-", zero, "a", for: element));"
    switch (element.bits, level) {
    case (32, .sse2):
        let i64 = x86Vector("i64")
        let selected = "\(x86IfThenElseName)(sign, (\(i64))negated, (\(i64))a)"
        return """
            const \(i64) sign = (\(i64))(a >> 31);
            \(negated)
            \(vectorResult(selected, for: element))
            """
    case (64, .sse2), (64, .ssse3):
        let i32 = x86Vector("i32")
        return """
            \(negated)
            const \(i32) signs = (\(i32))a >> 31;
            const \(element.cVector) sign = (\(element.cVector))__builtin_shufflevector(
              signs, signs, 1, 1, 3, 3);
            \(vectorResult(bitSelect("sign", "negated", "a", of: element), for: element))
            """
    default:
        return portableMagnitude(for: element)
    }
}

func x86MinimumPosition(
    _ reduction: Reduction,
    repeating: Bool = false,
    for element: Element
) -> String {
    func minimumPosition(_ operand: String) -> String {
        let position = x86Builtin("phminposuw128", [operand], as: "i16", returning: element.cVector)
        guard repeating else { return position }
        let lanes = laneIndices(Array(repeating: 0, count: element.laneCount))
        return "__builtin_shufflevector(\(position), \(position), \(lanes))"
    }
    guard reduction == .maximum else {
        return repeating
            ? vectorResult(minimumPosition("a"), for: element)
            : "return (\(minimumPosition("a")))[0];"
    }
    let result = "maximum - \(minimumPosition("(maximum - a)"))"
    return """
        const \(element.cVector) maximum = \(repeatingVector("0xFFFF", of: element));
        \(repeating ? vectorResult(result, for: element) : "return (\(result))[0];")
        """
}

func x86UsesMinimumPosition(
    _ reduction: Reduction,
    level: X86Level,
    for element: Element
) -> Bool {
    reduction != .sum && level == .sse4 && element.category == .unsignedInteger
        && element.bits == 16
}

func x86BlockReductionSteps(
    for element: Element
) -> [(shuffled: String, combined: String, blocks: [Int])] {
    switch element.width {
    case 32:
        return [("swappedBlocks", "folded", [1, 0])]
    case 64:
        return [
            ("swappedBlocks", "folded", [1, 0, 3, 2]),
            ("reversedBlocks", "gathered", [3, 2, 1, 0]),
        ]
    default:
        return []
    }
}

func x86Int32Shuffle(
    _ source: String,
    into result: String,
    lanes indices: [Int],
    for element: Element
) -> String {
    let i32 = x86Vector("i32")
    let lanes = indices.flatMap { [2 * $0, 2 * $0 + 1] }
    let shuffle =
        "__builtin_shufflevector((\(i32))\(source), (\(i32))\(source), \(laneIndices(lanes)))"
    return "const \(element.cVector) \(result) = (\(element.cVector))\(shuffle);"
}

func x86LowestLane(of vector: String, for element: Element) -> String {
    let i64 = x86Vector("i64")
    var statements: [String] = []
    var source = "(\(i64))\(vector)"
    if element.width == 64 {
        statements.append("typedef long long half_vector __attribute__((vector_size(32)));")
        statements.append(
            "const half_vector half = __builtin_shufflevector(\(source), \(source), 0, 1, 2, 3);"
        )
        source = "half"
    }
    statements.append(
        "const \(x86Block("i64")) lowest = __builtin_shufflevector(\(source), \(source), 0, 1);"
    )
    statements.append("return (\(element.cType))(((\(x86Block("i\(element.bits)")))lowest)[0]);")
    return statements.joined(separator: "\n")
}

typealias X86Combining = (_ first: String, _ second: String) -> String

func x86CombiningCall(_ reduction: Reduction, for element: Element) -> X86Combining {
    let combining = x86CombiningFunctionName(reduction, element)
    let raw = element.cRawVector
    return { first, second in
        "(\(element.cVector))\(combining)((\(raw))\(first), (\(raw))\(second))"
    }
}

func x86AcrossBlocks(
    from source: String,
    throughInt32: Bool,
    for element: Element,
    combining: X86Combining
) -> (statements: [String], reduced: String) {
    let vector = element.cVector
    var statements: [String] = []
    var reduced = source
    for step in x86BlockReductionSteps(for: element) {
        let lanes = (0..<element.laneCount).map {
            step.blocks[$0 / element.blockLaneCount] * element.blockLaneCount
                + $0 % element.blockLaneCount
        }
        if throughInt32 && element.width == 64 {
            statements.append(
                x86Int32Shuffle(reduced, into: step.shuffled, lanes: lanes, for: element)
            )
        } else {
            statements.append(
                "const \(vector) \(step.shuffled) = __builtin_shufflevector(\(reduced), \(reduced), \(laneIndices(lanes)));"
            )
        }
        statements.append(
            "const \(vector) \(step.combined) = \(combining(reduced, step.shuffled));"
        )
        reduced = step.combined
    }
    return (statements, reduced)
}

func x86WithinBlocks(
    from source: String,
    level: X86Level,
    throughInt32: Bool,
    for element: Element,
    combining: X86Combining
) -> (statements: [String], reduced: String) {
    let names: [(reversed: String, reduced: String)]
    switch element.blockLaneCount {
    case 2: names = [("reversed", "combined")]
    case 4: names = [("reversed", "pairs"), ("swapped", "combined")]
    default: names = [("reversed", "quads"), ("flipped", "pairs"), ("swapped", "combined")]
    }
    let vector = element.cVector
    var statements: [String] = []
    var reduced = source
    for (step, name) in names.enumerated() {
        let group = element.blockLaneCount >> step
        if throughInt32 {
            let lanes = (0..<element.laneCount).map { $0 ^ (group - 1) }
            statements.append(
                x86Int32Shuffle(reduced, into: name.reversed, lanes: lanes, for: element)
            )
        } else {
            statements.append(
                x86Reverse(reduced, into: name.reversed, lanes: group, level: level, for: element)
            )
        }
        statements.append(
            "const \(vector) \(name.reduced) = \(combining(reduced, name.reversed));"
        )
        reduced = name.reduced
    }
    return (statements, reduced)
}

func x86WordExtremum(_ reduction: Reduction, level: X86Level, for word: Element) -> X86Combining {
    let name = reduction == .minimum ? "min" : "max"
    return { first, second in
        guard word.category == .unsignedInteger, level < .sse4 else {
            return "__builtin_elementwise_\(name)(\(first), \(second))"
        }
        return x86SaturatedExtremum(reduction, first, second)
    }
}

func x86LowestByte(
    of vector: String,
    repeating: Bool,
    duplicatingEven: Bool = false,
    level: X86Level? = nil,
    for element: Element
) -> String {
    guard repeating else { return "return ((\(element.cVector))\(vector))[0];" }
    if duplicatingEven && level == .sse2 {
        return x86Duplicated(even: true, of: "(\(element.cVector))\(vector)", for: element)
    }
    let bytes = byteElement(of: element).cVector
    let lanes = laneIndices(
        duplicatingEven
            ? (0..<element.laneCount).map { $0 & ~1 }
            : Array(repeating: 0, count: element.laneCount)
    )
    let shuffle = "__builtin_shufflevector((\(bytes))\(vector), (\(bytes))\(vector), \(lanes))"
    return vectorResult("(\(element.cVector))\(shuffle)", for: element)
}

func x86ByteSum(level: X86Level, repeating: Bool = false, for element: Element) -> String {
    let sums = unsignedElement(bits: 64).at(width: element.width)
    let zero = compoundLiteral(x86Vector("i8"), ["0"])
    let differences = x86Builtin(
        "psadbw\(x86Bits(element.width))",
        ["a", zero],
        as: "i8",
        returning: sums.cVector
    )
    let adding: X86Combining = { first, second in "\(first) + \(second)" }
    let throughInt32 = element.width >= 32
    let across = x86AcrossBlocks(
        from: "sums",
        throughInt32: throughInt32,
        for: sums,
        combining: adding
    )
    let within = x86WithinBlocks(
        from: across.reduced,
        level: level,
        throughInt32: throughInt32,
        for: sums,
        combining: adding
    )
    let statements =
        [vectorTypedef(of: sums), "const \(sums.cVector) sums = \(differences);"]
        + across.statements + within.statements
        + [x86LowestByte(of: within.reduced, repeating: repeating, for: element)]
    return statements.joined(separator: "\n")
}

func x86ByteMinimumPosition(
    _ reduction: Reduction,
    repeating: Bool = false,
    for element: Element
) -> String {
    let word = resizedElement(of: element, bits: 16)
    let bytes = element.cVector
    let isMaximum = reduction == .maximum
    let source = isMaximum ? "inverted" : "a"
    func minimum(of part: Int) -> String {
        let words = convertedPart(source, part: part, lanes: word.laneCount, to: word.cVector)
        return x86Builtin("phminposuw128", [words], as: "i16", returning: word.cVector)
    }
    let broadcast = laneIndices(Array(repeating: 0, count: element.laneCount))
    func broadcastLowest(of name: String) -> String {
        "__builtin_shufflevector((\(bytes))\(name), (\(bytes))\(name), \(broadcast))"
    }
    let statements = [
        vectorTypedef(of: word),
        isMaximum ? "const \(bytes) inverted = ~a;" : nil,
        "const \(word.cVector) lowMinimum = \(minimum(of: 0));",
        "const \(word.cVector) highMinimum = \(minimum(of: 1));",
        "const \(bytes) smallest = __builtin_elementwise_min(\(broadcastLowest(of: "lowMinimum")), \(broadcastLowest(of: "highMinimum")));",
        repeating
            ? vectorResult(isMaximum ? "~smallest" : "smallest", for: element)
            : (isMaximum ? "return (~smallest)[0];" : "return smallest[0];"),
    ]
    return statements.compactMap { $0 }.joined(separator: "\n")
}

func x86ByteExtremum(
    _ reduction: Reduction,
    level: X86Level,
    repeating: Bool = false,
    for element: Element
) -> String {
    if element.category == .unsignedInteger && level == .sse4 {
        return x86ByteMinimumPosition(reduction, repeating: repeating, for: element)
    }
    let word = resizedElement(of: element, bits: 16)
    let unsigned = word.cUnsignedVector
    let combining = x86CombiningCall(reduction, for: element)
    let across = x86AcrossBlocks(from: "a", throughInt32: false, for: element, combining: combining)
    let isSigned = word.category == .signedInteger
    let wordCombining = x86WordExtremum(reduction, level: level, for: word)
    let halves = [
        (
            "evens",
            isSigned
                ? "(\(word.cVector))((\(unsigned))words << 8) >> 8"
                : "words & \(splat("0xFF", as: unsigned, lanes: word.laneCount))"
        ),
        ("odds", "words >> 8"),
    ]
    let widening =
        ["const \(word.cVector) words = (\(word.cVector))\(across.reduced);"]
        + (isSigned ? halves : halves.reversed()).map { "const \(word.cVector) \($0) = \($1);" }
        + ["const \(word.cVector) merged = \(wordCombining("evens", "odds"));"]
    let within = x86WithinBlocks(
        from: "merged",
        level: level,
        throughInt32: false,
        for: word,
        combining: wordCombining
    )
    let typedefs = Set([word, unsignedElement(of: word)].map(vectorTypedef(of:)))
    let statements =
        typedefs.sorted() + across.statements + widening + within.statements
        + [
            x86LowestByte(
                of: within.reduced,
                repeating: repeating,
                duplicatingEven: true,
                level: level,
                for: element
            )
        ]
    return statements.joined(separator: "\n")
}

func x86Reduction(
    _ reduction: Reduction,
    level: X86Level,
    repeating: Bool = false,
    for element: Element
) -> String {
    if element.bits == 8 {
        return reduction == .sum
            ? x86ByteSum(level: level, repeating: repeating, for: element)
            : x86ByteExtremum(reduction, level: level, repeating: repeating, for: element)
    }
    if x86UsesMinimumPosition(reduction, level: level, for: element) {
        return x86MinimumPosition(reduction, repeating: repeating, for: element)
    }
    let isWideSum =
        reduction == .sum && element.category != .float && element.bits >= 32
        && element.width >= 32
    let throughInt32 = isWideSum && element.bits == 64
    let combining = x86CombiningCall(reduction, for: element)
    let across = x86AcrossBlocks(
        from: "a",
        throughInt32: throughInt32,
        for: element,
        combining: combining
    )
    let within = x86WithinBlocks(
        from: across.reduced,
        level: level,
        throughInt32: throughInt32,
        for: element,
        combining: combining
    )
    let result =
        repeating
        ? vectorResult(within.reduced, for: element)
        : isWideSum
            ? x86LowestLane(of: within.reduced, for: element) : "return \(within.reduced)[0];"
    return (across.statements + within.statements + [result]).joined(separator: "\n")
}

func portableReverse(for element: Element) -> String {
    let indices = (0..<element.laneCount).reversed().map(String.init)
    return vectorResult(
        "__builtin_shufflevector(a, a, \(indices.joined(separator: ", ")))",
        for: element
    )
}

func portableTableLookupBytes(for element: Element) -> String {
    let isWide = element.bits > 8
    let bytes = isWide ? byteElement(of: element) : element
    let (table, indices) = isWide ? ("tableBytes", "indexBytes") : ("a", "indices")
    var statements: [String] = []
    if isWide {
        statements.append("const \(bytes.cVector) \(table) = (\(bytes.cVector))a;")
        statements.append("const \(bytes.cVector) \(indices) = (\(bytes.cVector))indices;")
    }
    statements.append("\(bytes.cVector) result;")
    statements += (0..<16).map { lane in
        "{\n  const uint8_t index = (uint8_t)\(indices)[\(lane)];\n  result[\(lane)] = index < 16 ? \(table)[index] : 0;\n}"
    }
    statements.append(vectorResult(isWide ? "(\(element.cVector))result" : "result", for: element))
    return statements.joined(separator: "\n")
}

func portableLookupSource(for element: Element) -> String {
    element.bits == 16 ? element.cUnsignedLane : element.cType
}

func portableLookup(of lane: String, for element: Element) -> String {
    let lanes = element.laneCount
    guard element.bits == 16 else {
        return """
            \(element.cVector) result;
            for (size_t i = 0; i < \(lanes); ++i) {
              result[i] = \(lane);
            }
            \(vectorResult("result", for: element))
            """
    }
    return """
        \(element.cUnsignedLane) lanes[\(lanes)];
        for (size_t i = 0; i < \(lanes); ++i) {
          lanes[i] = \(lane);
        }
        \(element.cVector) result;
        __builtin_memcpy(&result, lanes, sizeof result);
        \(vectorResult("result", for: element))
        """
}

func portableTableLookupLanes(for element: Element) -> String {
    let lanes = element.laneCount
    return """
        \(portableLookupSource(for: element)) source[\(lanes)];
        \(element.cMaskLane) index[\(lanes)];
        __builtin_memcpy(source, &a, sizeof a);
        __builtin_memcpy(index, &indices, sizeof indices);
        \(portableLookup(of: "source[index[i]]", for: element))
        """
}

func portableTwoTablesLookupLanes(for element: Element) -> String {
    let source = portableLookupSource(for: element)
    let lane = element.cMaskLane
    let lanes = element.laneCount
    let masked = "index[i] & (\(lane))\(lanes - 1)"
    let selected = "index[i] < (\(lane))\(lanes) ? first[\(masked)] : second[\(masked)]"
    return """
        \(source) first[\(lanes)];
        \(source) second[\(lanes)];
        \(lane) index[\(lanes)];
        __builtin_memcpy(first, &a, sizeof a);
        __builtin_memcpy(second, &b, sizeof b);
        __builtin_memcpy(index, &indices, sizeof indices);
        \(portableLookup(of: selected, for: element))
        """
}

func x86ReversedBytes(for element: Element) -> String? {
    guard element.bits == 8 else { return nil }
    let i16 = x86Vector("i16")
    let i32 = x86Vector("i32")
    let right = x86ImmediateShift("psrl", "a", by: "8", laneBits: 16, returning: i16)
    let left = x86ImmediateShift("psll", "a", by: "8", laneBits: 16, returning: i16)
    let lower = laneIndices([3, 2, 1, 0, 4, 5, 6, 7])
    let upper = laneIndices([0, 1, 2, 3, 7, 6, 5, 4])
    let words = "__builtin_shufflevector((\(i32))reversed, (\(i32))reversed, 2, 3, 0, 1)"
    return """
        const \(i16) right = \(right);
        const \(i16) left = \(left);
        const \(i16) rotated = right | left;
        const \(i16) lower = __builtin_shufflevector(rotated, rotated, \(lower));
        const \(i16) reversed = __builtin_shufflevector(lower, lower, \(upper));
        \(vectorResult("(\(element.cVector))\(words)", for: element))
        """
}

func x86TableLookup(_ bytes: String, _ indices: String, for element: Element) -> String {
    let name = "pshufb\(x86Bits(element.width))"
    return x86Builtin(name, [bytes, indices], as: "i8", returning: element.cVector)
}

func x86Sse2TableLookupBytes(for element: Element) -> String {
    """
    \(x86EmulatedTableLookupBytes("a", "indices", into: "looked"))
    \(vectorResult("(\(element.cVector))looked", for: element))
    """
}

func x86EmulatedLaneLookup(
    _ table: String,
    _ indices: String,
    into result: String,
    for element: Element
) -> String {
    let type = x86Vector("i64")
    let lanes = element.blockLaneCount
    let indexLane = element.bits == 16 ? "uint16_t" : "int32_t"
    let mask = element.bits == 16 ? "7u" : "3"
    let lookup = """
        \(element.cType) resultLanes[\(lanes)] __attribute__((aligned(16)));
        \(element.cType) tableLanes[\(lanes)] __attribute__((aligned(16)));
        \(indexLane) indexLanes[\(lanes)] __attribute__((aligned(16)));
        const \(type) tableVector = (\(type))\(table);
        const \(type) indexVector = (\(type))\(indices);
        __builtin_memcpy(tableLanes, &tableVector, 16);
        __builtin_memcpy(indexLanes, &indexVector, 16);
        for (int i = 0; i < \(lanes); i++) {
          resultLanes[i] = tableLanes[indexLanes[i] & \(mask)];
        }
        __builtin_memcpy(&\(result), resultLanes, 16);
        """
    return "\(type) \(result);\n{\n\(indented(lookup))\n}"
}

func x86LaneByteIndices(for element: Element) -> String {
    let bytes = element.bits / 8
    let int8 = x86Vector("i8")
    let broadcast = x86ByteTable(
        "broadcast",
        lookupBroadcastBytes(lane: bytes, width: element.width)
    )
    let offsets = x86ByteTable("offsets", lookupByteOffsets(lane: bytes, width: element.width))
    let lanes = x86Builtin(
        "pshufb\(x86Bits(element.width))",
        ["indices", "broadcast"],
        as: "i8",
        returning: int8
    )
    let shifted = "(\(x86Vector("i16")))laneIndices << \(bytes.trailingZeroBitCount)"
    return """
        \(broadcast)
        \(offsets)
        const \(int8) laneIndices = \(lanes);
        const \(int8) byteIndices = (\(int8))(\(shifted)) + offsets;
        """
}

func x86Avx2WordIndices(for element: Element) -> String {
    let int64 = x86Vector("i64")
    let float = x86Vector("f32")
    let indices = "(\(float))indices"
    let duplicated = "__builtin_shufflevector(\(indices), \(indices), 0, 0, 2, 2, 4, 4, 6, 6)"
    let carry = splat("4294967296ll", as: int64, lanes: element.laneCount)
    return """
        const \(int64) duplicated = (\(int64))\(duplicated);
        const \(int64) wordIndices = duplicated + duplicated + \(carry);
        """
}

func x86Int64LaneLookup(level: X86Level, for element: Element) -> String {
    let int64 = x86Vector("i64")
    let asInt32 = "(\(x86Vector("i32")))"
    let selected =
        level >= .sse4
        ? x86Builtin("pblendvb128", ["swapped", "table", "same"], as: "i8", returning: int64)
        : "(same & table) | (~same & swapped)"
    let iota = compoundLiteral(int64, ["0", "1"])
    return """
        const \(int64) table = (\(int64))a;
        const \(int64) same = ((\(int64))indices ^ \(iota)) - \(splat("1", as: int64, lanes: 2));
        const \(int64) swapped = (\(int64))__builtin_shufflevector(\(asInt32)table, \(asInt32)table, 2, 3, 0, 1);
        \(vectorResult(selected, for: element))
        """
}

func x86Permute(_ table: String, _ indices: String, for element: Element) -> String {
    x86Builtin(
        "permvar\(x86PermuteName(of: element))\(x86Bits(element.width))",
        [
            (value: table, type: x86Vector(x86LaneSuffix(of: element))),
            (value: indices, type: x86Vector("i\(element.bits)")),
        ],
        returning: element.cVector
    )
}

func x86Avx2ByteLaneLookup(for element: Element) -> String {
    let int16 = x86Vector("i16")
    let lowerTable = x86Avx2Concat(.lowerLower, hi: "a", lo: "a", for: element)
    let upperTable = x86Avx2Concat(.upperUpper, hi: "a", lo: "a", for: element)
    return """
        const \(int16) selector = (\(int16))indices << 3;
        const \(element.cVector) lower = \(x86TableLookup(lowerTable, "indices", for: element));
        const \(element.cVector) upper = \(x86TableLookup(upperTable, "indices", for: element));
        \(vectorResult(x86Selecting("selector", "upper", "lower", for: element), for: element))
        """
}

func x86Avx3ByteLaneLookup(for element: Element) -> String {
    let int16 = x86Vector("i16")
    let int32 = x86Vector("i32")
    let maskType = x86MaskType(lanes: element.laneCount)
    func table(_ name: String, _ control: Int) -> String {
        let shuffled = x86Builtin(
            "shuf_i32x4",
            [
                (value: "a", type: int32), (value: "a", type: int32),
                (value: x86Immediate(control), type: "int"),
            ],
            returning: int32
        )
        return "const \(int32) \(name) = \(shuffled);"
    }
    let tables = [
        table("tableA", 0x00), table("tableB", 0x55), table("tableC", 0xAA), table("tableD", 0xFF),
    ]
    func lookup(_ table: String) -> String {
        x86TableLookup(table, "indices", for: element)
    }
    return """
        const \(int16) shiftedBy3 = (\(int16))indices << 3;
        const \(maskType) selectsUpperHalves = \(x86Avx3MaskBits("shiftedBy3", for: element));
        const \(int16) shiftedBy2 = (\(int16))indices << 2;
        const \(maskType) selectsUpperQuarters = \(x86Avx3MaskBits("shiftedBy2", for: element));
        \(tables.joined(separator: "\n"))
        const \(element.cVector) lookedA = \(lookup("tableA"));
        const \(element.cVector) lookedC = \(lookup("tableC"));
        const \(element.cVector) lookedAB = \(x86Avx3Select("selectsUpperHalves", lookup("tableB"), "lookedA", for: element));
        const \(element.cVector) lookedCD = \(x86Avx3Select("selectsUpperHalves", lookup("tableD"), "lookedC", for: element));
        \(vectorResult(x86Avx3Select("selectsUpperQuarters", "lookedCD", "lookedAB", for: element), for: element))
        """
}

func x86TableLookupLanes(level: X86Level, for element: Element) -> String {
    switch (level, element.bits) {
    case (.sse2, 8):
        return x86Sse2TableLookupBytes(for: element)
    case (.sse2, 16), (.sse2, 32):
        return """
            \(x86EmulatedLaneLookup("a", "indices", into: "looked", for: element))
            \(vectorResult("(\(element.cVector))looked", for: element))
            """
    case (.sse2, _), (.ssse3, 64), (.sse4, 64):
        return x86Int64LaneLookup(level: level, for: element)
    case (.ssse3, 8), (.sse4, 8):
        return vectorResult(x86TableLookup("a", "indices", for: element), for: element)
    case (.ssse3, _), (.sse4, _):
        return """
            \(x86LaneByteIndices(for: element))
            \(vectorResult(x86TableLookup("a", "byteIndices", for: element), for: element))
            """
    case (.avx2, 8):
        return x86Avx2ByteLaneLookup(for: element)
    case (.avx2, 16):
        let byte = unsignedElement(bits: 8)
        let raw = byte.cRawVector
        let function = cFunctionName("tableLookupLanes", byte)
        return """
            \(x86LaneByteIndices(for: element))
            \(vectorResult("\(function)((\(raw))rawA, (\(raw))byteIndices)", for: element))
            """
    case (.avx2, 32):
        return vectorResult(x86Permute("a", "indices", for: element), for: element)
    case (.avx2, _):
        let words = x86Vector("i32")
        let lookup = x86Builtin(
            "permvarsi256",
            [(value: "a", type: words), (value: "wordIndices", type: words)],
            returning: element.cVector
        )
        return """
            \(x86Avx2WordIndices(for: element))
            \(vectorResult(lookup, for: element))
            """
    case (.avx3, 8):
        return x86Avx3ByteLaneLookup(for: element)
    case (.avx3, _), (.avx3dl, _):
        return vectorResult(x86Permute("a", "indices", for: element), for: element)
    }
}

func x86Sse2TableLookupBytesOrZero(for element: Element) -> String {
    let int8 = x86Vector("i8")
    return """
        const \(int8) signedIndices = (\(int8))indices;
        \(x86TableLookupBytesOr0("a", "signedIndices", into: "zeroed", level: .sse2))
        \(vectorResult("(\(element.cVector))zeroed", for: element))
        """
}

func tableLookupBytesTargets(zeroing: Bool) -> TargetBodies<Element> {
    func lookup(_ element: Element) -> String {
        vectorResult(x86TableLookup("a", "indices", for: element), for: element)
    }
    return TargetBodies(
        neon: { element in
            vectorResult(neonTableLookup("a", "indices", for: element), for: element)
        },
        sve2_128: zeroing ? { element in sveTableLookupBytes(for: element) } : nil,
        avx3: lookup,
        avx2: lookup,
        ssse3: lookup,
        sse2: { element in
            zeroing
                ? x86Sse2TableLookupBytesOrZero(for: element)
                : x86Sse2TableLookupBytes(for: element)
        }
    )
}

func x86TwoTablesLookupLanes(level: X86Level, for element: Element) -> String {
    let vector = element.cVector
    let lookup = cFunctionName("tableLookupLanes", element)
    let indexRaw = laneIndexElement(of: element).cRawVector
    func lookups(_ indices: String = "rawIndices", upperFirst: Bool = false) -> String {
        let lower = "const \(vector) lower = (\(vector))\(lookup)(rawA, \(indices));"
        let upper = "const \(vector) upper = (\(vector))\(lookup)(rawB, \(indices));"
        return upperFirst ? "\(upper)\n\(lower)" : "\(lower)\n\(upper)"
    }
    func compared(_ comparison: String = ">", with limit: Int) -> String {
        let type = x86Vector("i\(element.bits)")
        let limits = splat("\(limit)", as: type, lanes: element.laneCount)
        return "const \(type) selector = (\(type))((\(type))indices \(comparison) \(limits));"
    }
    func routed(through route: Element, indices: String) -> String {
        let function = cFunctionName("twoTablesLookupLanes", route)
        let raw = route.cRawVector
        let call = "\(function)((\(raw))rawA, (\(raw))rawB, (\(raw))\(indices))"
        return vectorResult(call, for: element)
    }
    func shifted(by bits: Int, lanes laneBits: Int) -> String {
        let type = x86Vector("i\(laneBits)")
        return "const \(type) selector = (\(type))indices << \(bits);"
    }
    switch (level, element.bits) {
    case (.sse2, 8):
        return """
            \(compared(with: 15))
            \(lookups())
            \(vectorResult(x86BitSelect("selector", "upper", "lower", for: element), for: element))
            """
    case (.ssse3, 8):
        return """
            \(compared("<", with: 16))
            \(lookups())
            \(vectorResult(x86BitSelect("selector", "lower", "upper", for: element), for: element))
            """
    case (.sse4, 8):
        return """
            \(shifted(by: 3, lanes: 16))
            \(lookups())
            \(vectorResult(x86Selecting("selector", "upper", "lower", for: element), for: element))
            """
    case (.sse2, 16), (.sse2, 32):
        return """
            \(compared(with: element.bits == 16 ? 7 : 3))
            \(lookups())
            \(vectorResult(x86BitSelect("selector", "upper", "lower", for: element), for: element))
            """
    case (.ssse3, 16), (.ssse3, 32), (.sse4, 16), (.sse4, 32):
        return """
            \(x86LaneByteIndices(for: element))
            \(routed(through: unsignedElement(bits: 8), indices: "byteIndices"))
            """
    case (.sse2, _), (.ssse3, _), (.sse4, _):
        let int64 = x86Vector("i64")
        let int32 = x86Vector("i32")
        let ones = splat("1", as: int64, lanes: 2)
        let modulo = "const \(int64) moduloIndices = (\(int64))indices & \(ones);"
        let selector: String
        let selected: String
        if level == .sse4 {
            selector = "const \(int64) selector = (\(int64))indices << 62;"
            selected = x86Builtin(
                "blendvpd",
                ["lower", "upper", "selector"],
                as: "f64",
                returning: x86Vector("f64")
            )
        } else {
            let indices = "(\(int32))indices"
            let duplicated = "__builtin_shufflevector(\(indices), \(indices), 0, 0, 2, 2)"
            selector = """
                const \(int32) duplicated = \(duplicated);
                const \(int64) selector = (\(int64))(duplicated > \(splat("1", as: int32, lanes: 4)));
                """
            selected = x86BitSelect("selector", "upper", "lower", for: element)
        }
        return """
            \(modulo)
            \(selector)
            \(lookups("(\(indexRaw))moduloIndices"))
            \(vectorResult(selected, for: element))
            """
    case (.avx2, 8):
        return """
            \(shifted(by: 2, lanes: 16))
            \(lookups())
            \(vectorResult(x86Selecting("selector", "upper", "lower", for: element), for: element))
            """
    case (.avx2, 16):
        return """
            \(x86LaneByteIndices(for: element))
            \(routed(through: unsignedElement(bits: 8), indices: "byteIndices"))
            """
    case (.avx2, 32):
        let blended = x86Builtin(
            "blendvps256",
            ["lower", "upper", "selector"],
            as: "f32",
            returning: x86Vector("f32")
        )
        return """
            \(shifted(by: 28, lanes: 32))
            \(lookups())
            \(vectorResult(blended, for: element))
            """
    case (.avx2, _):
        return """
            \(x86Avx2WordIndices(for: element))
            \(routed(through: unsignedElement(of: unsignedElement(bits: 32)), indices: "wordIndices"))
            """
    case (.avx3, 8):
        let int16 = x86Vector("i16")
        let maskType = x86MaskType(lanes: element.laneCount)
        return """
            const \(int16) shifted = (\(int16))indices << 1;
            const \(maskType) selectsUpper = \(x86Avx3MaskBits("shifted", for: element));
            \(lookups(upperFirst: true))
            \(vectorResult(x86Avx3Select("selectsUpper", "upper", "lower", for: element), for: element))
            """
    case (.avx3, _), (.avx3dl, _):
        return vectorResult(x86TwoTableLookup("a", "indices", "b", for: element), for: element)
    }
}

func slideShuffle(_ direction: SlideDirection, by amount: Int, for element: Element) -> String {
    let lanes = element.laneCount
    let zero = compoundLiteral(element.cVector, ["0"])
    switch direction {
    case .up:
        let indices = laneIndices(lanes - amount..<2 * lanes - amount)
        return "__builtin_shufflevector(\(zero), a, \(indices))"
    case .down:
        let indices = laneIndices(amount..<lanes + amount)
        return "__builtin_shufflevector(a, \(zero), \(indices))"
    }
}

func constantLanesSwitch(
    _ cases: [(amount: Int, body: String)],
    when condition: String? = nil
) -> String {
    let lines = cases.map { "case \($0.amount): \($0.body)" }
    let guarded = (["__builtin_constant_p(lanes)"] + (condition.map { [$0] } ?? []))
        .joined(separator: " && ")
    return """
        if (\(guarded)) {
          switch (lanes) {
        \(indented(indented(lines.joined(separator: "\n"))))
          }
        }
        """
}

func slideConstants(
    _ direction: SlideDirection,
    byteShifted: Bool = false,
    custom: (Int) -> String? = { _ in nil },
    evenOnly: Bool = false,
    for element: Element
) -> String {
    let cases = (1..<element.laneCount).filter { !evenOnly || $0 % 2 == 0 }.map { amount in
        if let body = custom(amount) {
            return (amount: amount, body: "{\n\(indented(body))\n}")
        }
        let shuffle =
            byteShifted
            ? x86SlideBytes(direction, by: amount, for: element)
            : slideShuffle(direction, by: amount, for: element)
        return (amount: amount, body: vectorResult(shuffle, for: element))
    }
    return constantLanesSwitch([(amount: 0, body: vectorResult("a", for: element))] + cases)
}

let neonSlideTableName = "cvectorization_ops_neon_slide_table"

func neonSlideIndices(_ direction: SlideDirection, for element: Element) -> String {
    let bytes = "cvectorization_ops_vector_u8"
    let offset = direction == .up ? "-" : "+"
    return """
        \(bytes) indices;
        __builtin_memcpy(&indices, \(neonSlideTableName)() + 16 \(offset) lanes * sizeof(\(element.cType)), sizeof indices);
        """
}

func x86SlideIndices(_ direction: SlideDirection, for element: Element) -> String {
    switch direction {
    case .up:
        let bytes = "cvectorization_ops_vector_u8"
        let first = splat("first", as: bytes, lanes: element.width)
        return """
            const uint8_t first = (uint8_t)(0 - lanes * sizeof(\(element.cType)));
            const \(bytes) indices = \(first) + \(iota(as: bytes, lanes: element.width));
            """
    case .down:
        let unsigned = "cvectorization_ops_vector_u8"
        let bytes = x86Vector("i8")
        let first = splat("first", as: unsigned, lanes: element.width)
        let limit = splat("\(element.width - 1)", as: bytes, lanes: element.width)
        return """
            const uint8_t first = (uint8_t)(lanes * sizeof(\(element.cType)));
            const \(bytes) offsets = (\(bytes))(\(first) + \(iota(as: unsigned, lanes: element.width)));
            const \(bytes) indices = offsets | (offsets > \(limit));
            """
    }
}

func x86ByteSlide(_ direction: SlideDirection, for element: Element) -> String {
    let i8 = x86Vector("i8")
    let blockBytes = 16
    let bytes = element.width
    let low = laneIndices(0..<blockBytes, 0..<blockBytes)
    let high = laneIndices(blockBytes..<bytes, blockBytes..<bytes)
    let pshufb = "pshufb\(x86Bits(element.width))"
    let blend = "pblendvb\(x86Bits(element.width))"
    func lookup(_ part: String) -> String {
        let block = "\(part.lowercased())Block"
        let shuffled = x86Builtin(pshufb, [block, "indices"], as: "i8", returning: i8)
        return "const \(i8) from\(part) = \(shuffled);"
    }
    let blended = x86Builtin(
        blend,
        ["fromLow", "fromHigh", "selected"],
        as: "i8",
        returning: element.cVector
    )
    let selected = x86ImmediateShift(
        "psll",
        "indices",
        by: "3",
        laneBits: 16,
        width: element.width,
        returning: i8
    )
    let lowBlock = "const \(i8) lowBlock = __builtin_shufflevector(bytes, bytes, \(low));"
    let highBlock = "const \(i8) highBlock = __builtin_shufflevector(bytes, bytes, \(high));"
    let statements =
        switch direction {
        case .up:
            [
                x86SlideIndices(.up, for: element),
                "const \(i8) bytes = (\(i8))a;",
                lowBlock,
                highBlock,
                lookup("Low"),
                lookup("High"),
            ]
        case .down:
            [
                x86SlideIndices(.down, for: element),
                "const \(i8) bytes = (\(i8))a;",
                lowBlock,
                lookup("Low"),
                highBlock,
                lookup("High"),
            ]
        }
    return """
        \(statements.joined(separator: "\n"))
        const \(i8) selected = \(selected);
        \(vectorResult(blended, for: element))
        """
}

func x86WordSlide(_ direction: SlideDirection, for element: Element) -> String {
    let words = "cvectorization_ops_vector_u32"
    let i32 = x86Vector("i32")
    let lanes = element.width / 4
    let amount = "lanes * \(element.bits / 32)"
    let first = direction == .up ? "(uint32_t)(0 - \(amount))" : "(uint32_t)(\(amount))"
    let limits = (0..<lanes).map { element.bits == 64 ? 6 + $0 % 2 : lanes - 1 }
    let permuted = x86Builtin("permvarsi256", ["a", "masked"], as: "i32", returning: i32)
    return """
        const uint32_t first = \(first);
        const \(words) indices = \(splat("first", as: words, lanes: lanes)) + \(iota(as: words, lanes: lanes));
        const \(words) masked = indices & \(compoundLiteral(words, limits.map(String.init)));
        const \(i32) gathered = \(permuted);
        \(vectorResult("(\(element.cVector))(gathered & (indices == masked))", for: element))
        """
}

func x86WideSlide(_ direction: SlideDirection, for element: Element) -> String {
    element.bits < 32
        ? x86ByteSlide(direction, for: element) : x86WordSlide(direction, for: element)
}

func x86TwoTableLookup(
    _ first: String,
    _ indices: String,
    _ second: String,
    for element: Element
) -> String {
    guard let suffix = [8: "qi", 16: "hi", 32: "d", 64: "q"][element.bits] else {
        fatalError("There is no x86 two table lookup of \(element.bits)-bit lanes")
    }
    let name = element.category == .float ? "p\(element.bits == 32 ? "s" : "d")" : suffix
    let table = x86Vector(x86LaneSuffix(of: element))
    return x86Builtin(
        "vpermi2var\(name)\(x86Bits(element.width))",
        [
            (value: first, type: table),
            (value: indices, type: x86Vector("i\(element.bits)")),
            (value: second, type: table),
        ],
        returning: element.cVector
    )
}

func x86TwoTableSlide(
    _ direction: SlideDirection,
    by amount: String = "lanes",
    for element: Element
) -> String {
    guard direction == .up || element.bits == 8 else {
        fatalError("There is no x86 two table slide down of \(element.bits)-bit lanes")
    }
    let lanes = element.laneCount
    let unsigned = element.cUnsignedVector
    let table = x86Vector(x86LaneSuffix(of: element))
    let isMasked = element.bits > 8
    let lookup = x86TwoTableLookup(
        "a",
        isMasked ? "masked" : "indices",
        compoundLiteral(table, ["0"]),
        for: element
    )
    let first = direction == .up ? "0 - \(amount)" : amount
    var statements = [
        "const \(element.cUnsignedLane) first = (\(element.cUnsignedLane))(\(first));",
        "const \(unsigned) indices = \(splat("first", as: unsigned, lanes: lanes)) + \(iota(as: unsigned, lanes: lanes));",
    ]
    if isMasked {
        let limit = splat("\(2 * lanes - 1)", as: unsigned, lanes: lanes)
        statements.append("const \(unsigned) masked = indices & \(limit);")
    }
    statements.append(vectorResult(lookup, for: element))
    return statements.joined(separator: "\n")
}

func x86PermuteName(of element: Element, viewingAsIntegers: Bool = false) -> String {
    guard element.category != .float || viewingAsIntegers else {
        return element.bits == 32 ? "sf" : "df"
    }
    guard let suffix = [8: "qi", 16: "hi", 32: "si", 64: "di"][element.bits] else {
        fatalError("There is no x86 permute of \(element.bits)-bit lanes")
    }
    return suffix
}

func x86PermuteSlideDown(for element: Element) -> String {
    let lanes = element.laneCount
    let unsigned = element.cUnsignedVector
    let table = x86Vector(x86LaneSuffix(of: element))
    let permuted = x86Builtin(
        "permvar\(x86PermuteName(of: element))\(x86Bits(element.width))",
        [(value: "a", type: table), (value: "masked", type: x86Vector("i\(element.bits)"))],
        returning: table
    )
    let limit = splat("\(lanes - 1)", as: unsigned, lanes: lanes)
    let valid = "(\(unsigned))(indices == masked)"
    return """
        const \(element.cUnsignedLane) first = (\(element.cUnsignedLane))lanes;
        const \(unsigned) indices = \(splat("first", as: unsigned, lanes: lanes)) + \(iota(as: unsigned, lanes: lanes));
        const \(unsigned) masked = indices & \(limit);
        const \(table) gathered = \(permuted);
        \(vectorResult("(\(unsigned))gathered & \(valid)", for: element))
        """
}

func x86Avx3Slide(
    _ direction: SlideDirection,
    level: X86Level,
    for element: Element
) -> String {
    let slid =
        switch (direction, element.bits) {
        case (.up, 8) where level < .avx3dl: x86Avx3ByteSlideUp(for: element)
        case (.down, 8) where level < .avx3dl: x86Avx3ByteSlideDown(for: element)
        case (_, 8), (.up, _): x86TwoTableSlide(direction, for: element)
        case (.down, _): x86PermuteSlideDown(for: element)
        }
    let slide1 = slide1Body(direction, level: level, for: element)
    let slidesBytes = element.bits == 8 && level < .avx3dl
    let constants = slideConstants(
        direction,
        custom: { amount in
            switch amount {
            case 1: slide1
            case element.laneCount / 2 where direction == .up && isFloat32(element):
                x86Avx3ConcatLowerLower(for: element)
            case _ where slidesBytes && amount % 2 == 1:
                x86Avx3ByteSlideBlocks(direction, by: amount, for: element)
            default: nil
            }
        },
        evenOnly: direction == .down && element.bits == 16,
        for: element
    )
    return "\(constants)\n\(slid)"
}

func x86Avx3ConcatLowerLower(for element: Element) -> String {
    let f32 = x86Vector("f32")
    let shuffled = x86Builtin(
        "shuf_f32x4",
        [
            (value: compoundLiteral(f32, ["0"]), type: f32),
            (value: "a", type: f32),
            (value: "0x44", type: "int"),
        ],
        returning: element.cVector
    )
    return vectorResult(shuffled, for: element)
}

func x86Avx3ByteSlideBlocks(
    _ direction: SlideDirection,
    by amount: Int,
    for element: Element
) -> String {
    let i8 = x86Vector("i8")
    let i32 = x86Vector("i32")
    let i64 = x86Vector("i64")
    let zero = compoundLiteral(i64, ["0"])
    let width = x86Bits(element.width)
    func quads(_ count: Int) -> String {
        switch (direction, count) {
        case (_, 0):
            return "whole"
        case (.up, 4):
            return x86Builtin(
                "shuf_i32x4",
                [
                    (value: zero, type: i32), (value: "whole", type: i32),
                    (value: "0x44", type: "int"),
                ],
                returning: i64
            )
        case (.down, 4):
            return "__builtin_shufflevector(whole, \(zero), 4, 5, 6, 7, 8, 9, 10, 11)"
        case (.up, _):
            return x86Builtin(
                "alignq\(width)",
                [
                    (value: "whole", type: i64),
                    (value: zero, type: i64),
                    (value: "\(8 - count)", type: "int"),
                ],
                returning: i64
            )
        case (.down, _):
            return x86Builtin(
                "alignq\(width)",
                [
                    (value: zero, type: i64),
                    (value: "whole", type: i64),
                    (value: "\(count)", type: "int"),
                ],
                returning: i64
            )
        }
    }
    let blocks = (amount >> 4) << 1
    let (nearer, farther) = (quads(blocks), blocks <= 4 ? quads(blocks + 2) : zero)
    let (high, low, bytes) =
        switch direction {
        case .up: (nearer, farther, 16 - amount % 16)
        case .down: (farther, nearer, amount % 16)
        }
    let shifted = x86Builtin(
        "palignr\(width)",
        [(value: "high", type: i8), (value: "low", type: i8), (value: "\(bytes)", type: "int")],
        returning: element.cVector
    )
    let operands = [(name: "high", value: high), (name: "low", value: low)]
    let statements = (direction == .up ? operands : operands.reversed()).map {
        "const \(i64) \($0.name) = \($0.value);"
    }
    return """
        const \(i64) whole = (\(i64))a;
        \(statements.joined(separator: "\n"))
        \(vectorResult(shifted, for: element))
        """
}

func x86Avx3SlideFillingCase(
    _ direction: SlideDirection,
    laneBits: Int,
    by amount: Int,
    for element: Element
) -> String {
    let lanes = element.width * 8 / laneBits
    let letter = x86LaneLetter(bits: laneBits)
    let vector = x86Vector("i\(laneBits)")
    let maskType = x86MaskType(lanes: lanes)
    let allLanes = (UInt64(1) << UInt64(lanes)) - 1
    let (kept, shift) =
        switch direction {
        case .up: (allLanes & ~((UInt64(1) << UInt64(amount)) - 1), lanes - amount)
        case .down: ((UInt64(1) << UInt64(lanes - amount)) - 1, amount)
        }
    let aligned = x86Builtin(
        "align\(letter)\(x86Bits(element.width))",
        [
            (value: rawName("a"), type: vector),
            (value: rawName("a"), type: vector),
            (value: "\(shift)", type: "int"),
        ],
        returning: vector
    )
    let selected = x86Builtin(
        "select\(letter)_\(x86Bits(element.width))",
        [
            (value: "0x\(String(kept, radix: 16))", type: maskType),
            (value: aligned, type: vector),
            (value: rawName("fill"), type: vector),
        ],
        returning: element.cVector
    )
    return vectorResult(selected, for: element)
}

func x86Avx3SlideFillingConstants(
    _ direction: SlideDirection,
    for element: Element
) -> String {
    func wideCase(_ amount: Int, laneBits: Int) -> String {
        x86Avx3SlideFillingCase(direction, laneBits: laneBits, by: amount, for: element)
    }
    func wordCase(_ words: Int) -> String {
        switch words {
        case 0: return vectorResult(rawName("a"), for: element)
        case _ where words % 2 == 1: return wideCase(words, laneBits: 32)
        default: return wideCase(words / 2, laneBits: 64)
        }
    }
    switch element.bits {
    case 64:
        let cases = (0..<element.laneCount).map { amount in
            (
                amount: amount,
                body: amount == 0
                    ? vectorResult(rawName("a"), for: element) : wideCase(amount, laneBits: 64)
            )
        }
        return constantLanesSwitch(cases)
    case 32:
        return constantLanesSwitch(
            (0..<element.laneCount).map { (amount: $0, body: wordCase($0)) }
        )
    default:
        let lanesPerWord = 32 / element.bits
        let cases = (0..<16).map { words in
            (amount: words * lanesPerWord, body: wordCase(words))
        }
        return constantLanesSwitch(cases, when: "(lanes & \(lanesPerWord - 1)) == 0")
    }
}

func x86Avx3SlideFilling(
    _ direction: SlideDirection,
    level: X86Level,
    for element: Element
) -> String {
    let lanes = element.laneCount
    let maskType = x86MaskType(lanes: lanes)
    let count = direction == .up ? "lanes" : "(\(lanes) - lanes)"
    let selected = "(\(maskType))\(x86FirstLanesBits(lanes: lanes, count: count))"
    let permutes =
        switch element.bits {
        case 8: level == .avx3dl
        case 16: direction == .down
        default: true
        }
    guard permutes else {
        let slid = "\(slideLanesName(direction, for: element))(\(rawName("a")), lanes)"
        let (yes, no) = direction == .up ? (rawName("fill"), slid) : (slid, rawName("fill"))
        return """
            \(x86Avx3SlideFillingConstants(direction, for: element))
            const \(maskType) selected = \(selected);
            \(vectorResult(x86Avx3Select("selected", yes, no, for: element), for: element))
            """
    }
    let integers = x86Vector("i\(element.bits)")
    let unsigned = element.cUnsignedVector
    let first = direction == .up ? "0 - lanes" : "lanes"
    let permuted = x86Builtin(
        "permvar\(x86PermuteName(of: element, viewingAsIntegers: true))\(x86Bits(element.width))",
        [(value: rawName("a"), type: integers), (value: "indices", type: integers)],
        returning: integers
    )
    let (yes, no) = direction == .up ? (rawName("fill"), permuted) : (permuted, rawName("fill"))
    return """
        \(x86Avx3SlideFillingConstants(direction, for: element))
        const \(maskType) selected = \(selected);
        const \(element.cUnsignedLane) first = (\(element.cUnsignedLane))(\(first));
        const \(unsigned) indices = \(splat("first", as: unsigned, lanes: lanes)) + \(iota(as: unsigned, lanes: lanes));
        \(vectorResult(x86Avx3Select("selected", yes, no, for: element), for: element))
        """
}

func x86Avx3ByteSlideUp(for element: Element) -> String {
    let indexVector = "cvectorization_ops_vector_u8"
    let blockVector = "block_vector"
    let i8 = x86Vector("i8")
    let i64 = x86Vector("i64")
    let blockLanes = element.width / 8
    let even = laneIndices(0..<16, 0..<16, 32..<48, 32..<48)
    let odd = laneIndices(48..<64, 16..<32, 16..<32, 48..<64)
    let pshufb = "pshufb\(x86Bits(element.width))"
    let fromEven = x86Builtin(pshufb, ["evenBlocks", "indices"], as: "i8", returning: i8)
    let fromOdd = x86Builtin(pshufb, ["oddBlocks", "indices"], as: "i8", returning: i8)
    let selected = x86ImmediateShift(
        "psll",
        "indices",
        by: "3",
        laneBits: 16,
        width: element.width,
        returning: i8
    )
    let bits = x86Builtin(
        "cvtb2mask\(x86Bits(element.width))",
        ["selected"],
        as: "i8",
        returning: x86MaskType(lanes: element.laneCount)
    )
    let blended = x86Builtin(
        "selectb_\(x86Bits(element.width))",
        [
            (value: bits, type: x86MaskType(lanes: element.laneCount)),
            (value: "fromOdd", type: i8),
            (value: "fromEven", type: i8),
        ],
        returning: i8
    )
    let lookup = x86Builtin(
        "vpermi2varq\(x86Bits(element.width))",
        ["blended", "blockIndices", compoundLiteral(i64, ["0"])],
        as: "i64",
        returning: element.cVector
    )
    return """
        typedef uint64_t \(blockVector) __attribute__((vector_size(\(element.width))));
        const uint8_t first = (uint8_t)(0 - (lanes & 15));
        const \(indexVector) indices = \(splat("first", as: indexVector, lanes: element.width)) + \(iota(as: indexVector, lanes: element.width));
        const uint64_t blockFirst = (uint64_t)(0 - ((lanes >> 4) << 1));
        const \(blockVector) blockIndices = \(splat("blockFirst", as: blockVector, lanes: blockLanes)) + \(iota(as: blockVector, lanes: blockLanes));
        const \(i8) bytes = (\(i8))a;
        const \(i8) evenBlocks = __builtin_shufflevector(bytes, bytes, \(even));
        const \(i8) oddBlocks = __builtin_shufflevector(bytes, bytes, \(odd));
        const \(i8) fromEven = \(fromEven);
        const \(i8) fromOdd = \(fromOdd);
        const \(i8) selected = \(selected);
        const \(i8) blended = \(blended);
        \(vectorResult(lookup, for: element))
        """
}

func x86Avx3ByteSlideDown(for element: Element) -> String {
    let indexVector = "cvectorization_ops_vector_u8"
    let blockVector = "block_vector"
    let i8 = x86Vector("i8")
    let i64 = x86Vector("i64")
    let blockLanes = element.width / 8
    let even = laneIndices(0..<16, 32..<48, 32..<48, 0..<16)
    let odd = laneIndices(16..<32, 16..<32, 48..<64, 48..<64)
    let pshufb = "pshufb\(x86Bits(element.width))"
    let maskType = x86MaskType(lanes: element.laneCount)
    let selected = x86ImmediateShift(
        "psll",
        "indices",
        by: "3",
        laneBits: 16,
        width: element.width,
        returning: i8
    )
    let oddSelect = x86Builtin(
        "cvtb2mask\(x86Bits(element.width))",
        [selected],
        as: "i8",
        returning: maskType
    )
    let fromEven = x86Builtin(
        "selectb_\(x86Bits(element.width))",
        [
            (value: "0x0000FFFFFFFFFFFFULL", type: maskType),
            (
                value: x86Builtin(pshufb, ["evenBlocks", "indices"], as: "i8", returning: i8),
                type: i8
            ),
            (value: compoundLiteral(i8, ["0"]), type: i8),
        ],
        returning: i8
    )
    let blended = x86Builtin(
        "selectb_\(x86Bits(element.width))",
        [
            (value: "oddSelect", type: maskType),
            (
                value: x86Builtin(pshufb, ["oddBlocks", "indices"], as: "i8", returning: i8),
                type: i8
            ),
            (value: "fromEven", type: i8),
        ],
        returning: i8
    )
    let lookup = x86Builtin(
        "vpermi2varq\(x86Bits(element.width))",
        ["blended", "blockIndices", compoundLiteral(i64, ["0"])],
        as: "i64",
        returning: element.cVector
    )
    return """
        typedef uint64_t \(blockVector) __attribute__((vector_size(\(element.width))));
        const uint8_t first = (uint8_t)(lanes & 15);
        const \(indexVector) indices = \(splat("first", as: indexVector, lanes: element.width)) + \(iota(as: indexVector, lanes: element.width));
        const \(i8) bytes = (\(i8))a;
        const \(maskType) oddSelect = \(oddSelect);
        const \(i8) oddBlocks = __builtin_shufflevector(bytes, bytes, \(odd));
        const \(i8) evenBlocks = __builtin_shufflevector(bytes, bytes, \(even));
        const \(i8) fromEven = \(fromEven);
        const \(i8) blended = \(blended);
        const uint64_t blockFirst = (uint64_t)((lanes >> 4) << 1);
        const \(blockVector) blockIndices = \(splat("blockFirst", as: blockVector, lanes: blockLanes)) + \(iota(as: blockVector, lanes: blockLanes));
        \(vectorResult(lookup, for: element))
        """
}

func x86ByteShift(_ direction: SlideDirection, _ operand: String, by bytes: Int) -> String {
    let name = direction == .up ? "pslldqi128" : "psrldqi128"
    return "__builtin_ia32_\(name)_byteshift(\(operand), \(bytes))"
}

func x86SlideBytes(_ direction: SlideDirection, by lanes: Int, for element: Element) -> String {
    let shifted = x86ByteShift(direction, "(\(x86Vector("i64")))a", by: lanes * element.bits / 8)
    return "(\(element.cVector))\(shifted)"
}

func x86Slide(_ direction: SlideDirection, for element: Element) -> String {
    let vector = x86Vector("i64")
    let selected = compoundLiteral(x86Vector("i32"), Array(repeating: "selected", count: 4))
    let (own, ownShift, other, otherShift) =
        switch direction {
        case .up: ("high", "psll", "low", "psrl")
        case .down: ("low", "psrl", "high", "psll")
        }
    let shiftedOwn = "shifted\(uppercasedFirst(own))"
    let shiftedOther = "shifted\(uppercasedFirst(other))"
    let ownShifted = x86ShiftSame(
        ownShift,
        own,
        by: "shift",
        into: shiftedOwn,
        laneBits: 64,
        width: element.width,
        returning: vector
    )
    let otherShifted = x86ShiftSame(
        otherShift,
        other,
        by: "64 - shift",
        into: shiftedOther,
        laneBits: 64,
        width: element.width,
        returning: vector
    )
    return """
        const int selected = -(int)(lanes >= \(element.laneCount / 2));
        const \(vector) mask = (\(vector))\(selected);
        const \(vector) whole = (\(vector))a;
        const \(vector) moved = \(x86ByteShift(direction, "whole", by: 8));
        const \(vector) \(own) = (mask & moved) | (~mask & whole);
        const \(vector) \(other) = \(x86ByteShift(direction, own, by: 8));
        const int shift = (int)((lanes * \(element.bits)) & 63);
        \(ownShifted)
        \(otherShifted)
        \(vectorResult("(\(element.cVector))(\(shiftedOwn) | \(shiftedOther))", for: element))
        """
}

func slideTargets(_ direction: SlideDirection) -> TargetBodies<Element> {
    TargetBodies(
        neon: { element in
            """
            \(slideConstants(direction, for: element))
            \(neonSlideIndices(direction, for: element))
            \(vectorResult(neonTableLookup("a", "indices", for: element), for: element))
            """
        },
        sve2_128: direction == .up ? { element in sveSlideUp(filling: false, for: element) } : nil,
        avx3dl: { element in x86Avx3Slide(direction, level: .avx3dl, for: element) },
        avx3: { element in x86Avx3Slide(direction, level: .avx3, for: element) },
        avx2: { element in
            let custom = x86WideSlideAmount(direction, for: element)
            return """
                \(slideConstants(direction, custom: custom, for: element))
                \(x86WideSlide(direction, for: element))
                """
        },
        ssse3: { element in
            """
            \(slideConstants(direction, for: element))
            \(x86SlideIndices(direction, for: element))
            \(vectorResult(x86TableLookup("a", "indices", for: element), for: element))
            """
        },
        sse2: { element in
            """
            \(slideConstants(direction, for: element))
            \(x86Slide(direction, for: element))
            """
        }
    )
}

func portableSlideOperands(
    _ direction: SlideDirection,
    by lanes: String,
    for element: Element
) -> (destination: String, source: String, size: String) {
    let lane = element.cType
    let size = "(\(element.laneCount) - \(lanes)) * sizeof(\(lane))"
    switch direction {
    case .up: return ("(\(lane)*)&result + \(lanes)", "&source", size)
    case .down: return ("&result", "(const \(lane)*)&source + \(lanes)", size)
    }
}

func portableSlideCopy(
    _ direction: SlideDirection,
    by lanes: String,
    for element: Element
) -> String {
    let (destination, source, size) = portableSlideOperands(direction, by: lanes, for: element)
    return "__builtin_memcpy(\(destination), \(source), \(size));"
}

func portableSlide(_ direction: SlideDirection, for element: Element) -> String {
    let lanes = element.laneCount
    let (destination, source, size) = portableSlideOperands(direction, by: "clamped", for: element)
    return """
        \(element.cVector) result;
        const \(element.cVector) source = a;
        const size_t clamped = lanes < \(lanes) ? lanes : \(lanes);
        void *const destination = \(destination);
        const void *const origin = \(source);
        const size_t size = \(size);
        __builtin_memset(&result, 0, sizeof result);
        __builtin_memcpy(destination, origin, size);
        \(vectorResult("result", for: element))
        """
}

func bytewiseSlide1(_ direction: SlideDirection, for element: Element) -> String {
    let bytes = "cvectorization_ops_vector_u8"
    let zero = compoundLiteral(bytes, ["0"])
    let width = element.width
    let amount = element.bits / 8
    switch direction {
    case .up:
        let indices = laneIndices(width - amount..<2 * width - amount)
        return "(\(element.cVector))__builtin_shufflevector(\(zero), (\(bytes))a, \(indices))"
    case .down:
        let indices = laneIndices(amount..<width + amount)
        return "(\(element.cVector))__builtin_shufflevector((\(bytes))a, \(zero), \(indices))"
    }
}

func portableSlide1(_ direction: SlideDirection, for element: Element) -> String {
    if element.bits == 32 && element.width == 16 && element.category != .float {
        return vectorResult(bytewiseSlide1(direction, for: element), for: element)
    }
    return """
        \(element.cVector) result;
        const \(element.cVector) source = a;
        result = (\(element.cVector)){0};
        \(portableSlideCopy(direction, by: "1", for: element))
        \(vectorResult("result", for: element))
        """
}

func shuffledSlide1(_ direction: SlideDirection, for element: Element) -> String {
    vectorResult(slideShuffle(direction, by: 1, for: element), for: element)
}

func slide1Targets(_ direction: SlideDirection) -> TargetBodies<Element> {
    func avx3(_ level: X86Level) -> (Element) -> String? {
        { element in
            direction == .down && element.bits == 16
                ? nil : x86Avx3Slide1(direction, level: level, for: element)
        }
    }
    return TargetBodies(
        neon: { element in shuffledSlide1(direction, for: element) },
        avx3dl: avx3(.avx3dl),
        avx3: avx3(.avx3),
        avx2: { element in x86WideSlideBytes(direction, by: element.bits / 8, for: element) },
        sse2: { element in
            direction == .up && isFloat32(element)
                ? x86Slide1Up(for: element) : shuffledSlide1(direction, for: element)
        }
    )
}

func slide1Body(_ direction: SlideDirection, level: X86Level, for element: Element) -> String {
    let targets = slide1Targets(direction)
    let specific = level.inherited.lazy.compactMap { targets.body(at: $0)?(element) }.first
    return specific ?? portableSlide1(direction, for: element)
}

func neonSlideFillingTableName(_ direction: SlideDirection) -> String {
    "cvectorization_ops_neon_slide_\(direction.rawValue)_or_table"
}

func neonSlideFillingTable(_ direction: SlideDirection) -> [Int] {
    (0...16).flatMap { shift in
        (0..<16).map { byte in
            switch direction {
            case .up: return byte < shift ? byte : 16 + byte - shift
            case .down: return byte + shift < 16 ? 16 + byte + shift : byte
            }
        }
    }
}

func neonSlideFillingIndices(_ direction: SlideDirection, for element: Element) -> String {
    let bytes = "cvectorization_ops_vector_u8"
    return """
        \(bytes) indices;
        __builtin_memcpy(&indices, \(neonSlideFillingTableName(direction))() + 16 * lanes * sizeof(\(element.cType)), sizeof indices);
        """
}

func slideLanesName(_ direction: SlideDirection, for element: Element) -> String {
    cFunctionName("slide\(uppercasedFirst(direction.rawValue))Lanes", element)
}

func slideFilling(
    _ direction: SlideDirection,
    sliding slide: String,
    for element: Element
) -> String {
    let raw = element.cRawVector
    let slid = "\(slide)((\(raw))a, lanes)"
    let filled = "(\(raw))fill"
    let (count, yes, no) =
        switch direction {
        case .up: ("lanes", filled, slid)
        case .down: ("\(element.laneCount) - lanes", slid, filled)
        }
    let mask = "\(cFunctionName("firstLanes", element))(\(count))"
    return "return \(cFunctionName("selecting", element))(\(mask), \(yes), \(no));"
}

func neonSlideFilling(_ direction: SlideDirection, for element: Element) -> String {
    let slide = slideLanesName(direction, for: element)
    let lookup = neonTwoTablesLookup("fill", "a", "indices", for: element)
    return """
        if (__builtin_constant_p(lanes)) {
        \(indented(slideFilling(direction, sliding: slide, for: element)))
        }
        \(neonSlideFillingIndices(direction, for: element))
        \(vectorResult(lookup, for: element))
        """
}

func x86SlideLanesName(_ direction: SlideDirection, for element: Element) -> String {
    "cvectorization_ops_x86_slide_\(direction.rawValue)_lanes_\(element.cSuffix)"
}

func x86SlideLanes(_ direction: SlideDirection, for element: Element) -> String {
    let function = cFunction(
        returns: element.cRawVector,
        name: x86SlideLanesName(direction, for: element),
        parameters: ["\(element.cRawVector) rawA", "size_t lanes"],
        body: """
            const \(element.cVector) a = (\(element.cVector))rawA;
            \(slideConstants(direction, byteShifted: true, for: element))
            return \(slideLanesName(direction, for: element))(rawA, lanes);
            """
    )
    return function.trimmingCharacters(in: .newlines)
}

func slideFillingTargets(_ direction: SlideDirection) -> TargetBodies<Element> {
    TargetBodies(
        neon: { element in neonSlideFilling(direction, for: element) },
        sve2_128: direction == .up ? { element in sveSlideUp(filling: true, for: element) } : nil,
        avx3dl: { element in x86Avx3SlideFilling(direction, level: .avx3dl, for: element) },
        avx3: { element in x86Avx3SlideFilling(direction, level: .avx3, for: element) },
        sse4: { element in
            slideFilling(direction, sliding: slideLanesName(direction, for: element), for: element)
        },
        sse2: { element in
            slideFilling(
                direction,
                sliding: x86SlideLanesName(direction, for: element),
                for: element
            )
        }
    )
}

func slide1FillingLane(_ direction: SlideDirection, for element: Element) -> Int {
    direction == .up ? 0 : element.laneCount - 1
}

func slideFilledLane(_ vector: String, _ lane: Int, for element: Element) -> String {
    """
    \(element.cVector) result = \(vector);
    result[\(lane)] = fill;
    \(vectorResult("result", for: element))
    """
}

func slide1Filling(_ direction: SlideDirection, for element: Element) -> String {
    if element.category == .float && element.laneCount == 2 {
        let filled = repeatingVector("fill", of: element)
        let shuffle =
            direction == .up
            ? "__builtin_shufflevector(\(filled), a, 0, 2)"
            : "__builtin_shufflevector(a, \(filled), 1, 2)"
        return vectorResult(shuffle, for: element)
    }
    let slide = cFunctionName("slide1\(uppercasedFirst(direction.rawValue))", element)
    let slid = "(\(element.cVector))\(slide)((\(element.cRawVector))a)"
    return slideFilledLane(slid, slide1FillingLane(direction, for: element), for: element)
}

func x86Slide1Filling(
    _ direction: SlideDirection,
    level: X86Level,
    for element: Element
) -> String {
    let lane = slide1FillingLane(direction, for: element)
    let shifted = x86SlideBytes(direction, by: 1, for: element)
    guard level < .sse4 else { return slideFilledLane(shifted, lane, for: element) }
    let raw = element.cRawVector
    if element.bits == 8 || isInteger32(element) || isFloat32(element) {
        let mask = "(\(raw))\(laneMask(lane, for: element))"
        let filled = "\(cFunctionName("repeating", element))(fill)"
        let selected = cFunctionName("selecting", element)
        return "return \(selected)(\(mask), \(filled), (\(raw))\(shifted));"
    }
    guard isInteger64(element) else { return slideFilledLane(shifted, lane, for: element) }
    let (f64, i64) = (x86Vector("f64"), x86Vector("i64"))
    let asFloat = x86AsFloatName(bits: 64)
    let operands = lane == 0 ? "inserted, whole, 0, 3" : "whole, inserted, 0, 2"
    return """
        const \(f64) inserted = \(asFloat)((\(i64))\(cFunctionName("repeating", element))(fill));
        const \(f64) whole = \(asFloat)((\(i64))\(shifted));
        \(vectorResult("__builtin_shufflevector(\(operands))", for: element))
        """
}

func x86WideSlide1Filling(_ direction: SlideDirection, for element: Element) -> String? {
    guard element.bits > 8 else { return nil }
    let raw = element.cRawVector
    let lane = slide1FillingLane(direction, for: element)
    let slide = cFunctionName("slide1\(uppercasedFirst(direction.rawValue))", element)
    let mask = "(\(element.cRawMask))\(laneMask(lane, for: element))"
    let filled = "\(cFunctionName("repeating", element))(fill)"
    let selected = cFunctionName("selecting", element)
    return """
        const \(raw) slid = \(slide)((\(raw))a);
        return \(selected)(\(mask), \(filled), slid);
        """
}

func slide1FillingTargets(_ direction: SlideDirection) -> TargetBodies<Element> {
    TargetBodies(
        avx3: { element in x86Avx3Slide1(direction, filling: true, for: element) },
        avx2: { element in x86WideSlide1Filling(direction, for: element) },
        sse4: { element in x86Slide1Filling(direction, level: .sse4, for: element) },
        sse2: { element in x86Slide1Filling(direction, level: .sse2, for: element) }
    )
}

func isInteger32(_ element: Element) -> Bool {
    element.bits == 32 && element.category != .float
}

func isInteger64(_ element: Element) -> Bool {
    element.bits == 64 && element.category != .float
}

func isFloat32(_ element: Element) -> Bool {
    element.bits == 32 && element.category == .float
}

func isSignedInteger64(_ element: Element) -> Bool {
    element.bits == 64 && element.category == .signedInteger
}

func isUnsigned64(_ element: Element) -> Bool {
    element.bits == 64 && element.category == .unsignedInteger
}

func bitwise(for element: Element, _ operation: (_ bits: (String) -> String) -> String) -> String {
    guard element.category == .float else { return vectorResult(operation { $0 }, for: element) }
    let expression = operation { unsignedBits($0, of: element) }
    return vectorResult(fromUnsignedBits(expression, of: element), for: element)
}

func allBitsSetByEquality(of lane: Element) -> String {
    let ones = splat("(\(lane.cUnsignedLane))~0", as: lane.cUnsignedVector, lanes: lane.laneCount)
    let equal =
        "\(cFunctionName("equalTo", lane))((\(lane.cRawVector))rawA, (\(lane.cRawVector))\(ones))"
    return "return \(cFunctionName("allTrue", lane))(\(equal));"
}

func allBitsClearByEquality(for element: Element) -> String {
    let zero = compoundLiteral(element.cVector, ["0"])
    let equal = "\(cFunctionName("equalTo", element))(rawA, (\(element.cRawVector))\(zero))"
    return "return \(cFunctionName("allTrue", element))(\(equal));"
}

func smearedBits(of operand: String, for element: Element) -> String {
    let unsigned = element.cUnsignedVector
    var statements = ["\(unsigned) smeared = \(unsignedBits(operand, of: element));"]
    var distance = 1
    while distance < element.bits {
        statements.append("smeared |= smeared >> \(distance);")
        distance *= 2
    }
    return statements.joined(separator: "\n")
}

func portableLeadingZeroCount(for element: Element) -> String {
    let width = splat("\(element.bits)", as: element.cUnsignedVector, lanes: element.laneCount)
    let counted = "\(width) - __builtin_elementwise_popcount(smeared)"
    return """
        \(smearedBits(of: "a", for: element))
        \(vectorResult(fromUnsignedBits(counted, of: element), for: element))
        """
}

func portableTrailingZeroCount(for element: Element) -> String {
    let bits = unsignedBits("a", of: element)
    let counted = "__builtin_elementwise_popcount(~\(bits) & (\(bits) - 1))"
    return vectorResult(fromUnsignedBits(counted, of: element), for: element)
}

func portableHighestSetBitIndex(for element: Element) -> String {
    let unsigned = element.cUnsignedVector
    let offset = splat("126", as: unsigned, lanes: element.laneCount)
    let index =
        "__builtin_elementwise_popcount(smeared) - 1 - (\(offset) & (\(unsigned))(smeared == 0))"
    return """
        \(smearedBits(of: "a", for: element))
        \(vectorResult(fromUnsignedBits(index, of: element), for: element))
        """
}

func neonLeadingZeroCount(_ operand: String, for element: Element) -> String {
    guard element.bits == 64 else {
        let counted = neonBuiltin(
            "vclzq_v",
            [operand],
            code: neonTypeCode(of: element),
            for: element
        )
        return "const \(element.cVector) counted = \(counted);"
    }
    let words = unsignedElement(of: unsignedElement(bits: 32)).at(width: element.width)
    let type = words.cVector
    let halves = element.laneCount
    let counts = neonBuiltin("vclzq_v", ["words"], code: neonTypeCode(of: words), for: words)
    let offsets = compoundLiteral(type, (0..<halves).flatMap { _ in ["32", "0"] })
    let lowerHalves = compoundLiteral(type, (0..<halves).flatMap { _ in ["0xFFFFFFFF", "0"] })
    return """
        const \(type) words = (\(type))\(operand);
        const \(type) offsets = \(offsets);
        const \(type) counts = \(counts) + offsets;
        const \(type) lower = counts & \(lowerHalves);
        const \(type) upper = (\(type))((\(element.cUnsignedVector))counts >> 32);
        const \(type) takeLower = (\(type))(upper == offsets);
        const \(element.cVector) counted = (\(element.cVector))((takeLower & lower) | (~takeLower & upper));
        """
}

func neonLeadingZeroCountResult(for element: Element) -> String {
    "\(neonLeadingZeroCount("a", for: element))\n\(vectorResult("counted", for: element))"
}

func neonPopulationCount(for element: Element) -> String {
    let bytes = unsignedElement(bits: 8).at(width: element.width)
    var counted = neonBuiltin("vcntq_v", ["a"], code: neonTypeCode(of: bytes), for: bytes)
    var bits = 16
    while bits <= element.bits {
        let lanes = unsignedElement(bits: bits).at(width: element.width)
        counted = neonBuiltin("vpaddlq_v", [counted], code: neonTypeCode(of: lanes), for: lanes)
        bits *= 2
    }
    return vectorResult(counted, for: element)
}

func portablePopulationCount(for element: Element) -> String {
    vectorResult("__builtin_elementwise_popcount(a)", for: element)
}

func x86PopulationCountBytes(level: X86Level, for element: Element) -> String {
    let type = element.cVector
    guard level >= .ssse3 else {
        func lanes(_ value: Int) -> String {
            splat("0x\(String(value, radix: 16))", as: type, lanes: element.laneCount)
        }
        return """
            const \(type) odds = a - ((a >> 1) & \(lanes(0x55)));
            const \(type) pairs = ((odds >> 2) & \(lanes(0x33))) + (odds & \(lanes(0x33)));
            \(vectorResult("(pairs + (pairs >> 4)) & \(lanes(0x0F))", for: element))
            """
    }
    let table = [0, 1, 1, 2, 1, 2, 2, 3, 1, 2, 2, 3, 2, 3, 3, 4]
    let lookup = compoundLiteral(
        type,
        Array(repeating: table, count: element.width / 16).flatMap { $0 }.map(String.init)
    )
    let nibbles = splat("0x0F", as: type, lanes: element.laneCount)
    func counted(_ name: String, _ nibble: String) -> String {
        let call = x86Builtin(
            "pshufb\(x86Bits(element.width))",
            ["lookup", nibble],
            as: "i8",
            returning: type
        )
        return "const \(type) \(name) = \(call);"
    }
    return """
        const \(type) lookup = \(lookup);
        const \(type) lowNibbles = a & \(nibbles);
        const \(type) highNibbles = (a >> 4) & \(nibbles);
        \(counted("highCounts", "highNibbles"))
        \(counted("lowCounts", "lowNibbles"))
        \(vectorResult("highCounts + lowCounts", for: element))
        """
}

func x86PopulationCount(level: X86Level, for element: Element) -> String {
    guard element.bits > 8 else { return x86PopulationCountBytes(level: level, for: element) }
    let narrow = unsignedElement(bits: element.bits / 2).at(width: element.width)
    let unsigned = unsignedElement(of: element).at(width: element.width)
    let counted = operationCall("nonzeroBitCount", ["a"], for: narrow)
    let lane = splat("0xFF", as: unsigned.cVector, lanes: element.laneCount)
    return """
        const \(unsigned.cVector) counts = (\(unsigned.cVector))\(counted);
        \(vectorResult("(counts >> \(element.bits / 2)) + (counts & \(lane))", for: element))
        """
}

func neonTrailingZeroCount(for element: Element) -> String {
    let bytes = unsignedElement(bits: 8).at(width: element.width)
    let size = element.bits / 8
    let indices = (0..<element.width).map { String($0 / size * size + size - 1 - $0 % size) }
    let reversedLanes =
        size == 1
        ? "reversedBytes"
        : "__builtin_shufflevector(reversedBytes, reversedBytes, \(indices.joined(separator: ", ")))"
    return """
        const \(bytes.cVector) reversedBytes = __builtin_elementwise_bitreverse((\(bytes.cVector))a);
        const \(element.cVector) reversed = (\(element.cVector))\(reversedLanes);
        \(neonLeadingZeroCount("reversed", for: element))
        \(vectorResult("counted", for: element))
        """
}

func neonHighestSetBitIndex(for element: Element) -> String {
    let unsigned = element.cUnsignedVector
    let top = splat("\(element.bits - 1)", as: unsigned, lanes: element.laneCount)
    return """
        \(neonLeadingZeroCount("a", for: element))
        \(vectorResult(fromUnsignedBits("\(top) - (\(unsigned))counted", of: element), for: element))
        """
}

func sveLeadingZeroCount(_ operand: String, for element: Element) -> String {
    let counted = sveBuiltin(
        "clz",
        [sveAllLanes(of: element), operand],
        for: element,
        predication: "x"
    )
    guard element.category == .signedInteger else { return counted }
    let target = sveSuffix(of: element)
    return "__builtin_sve_reinterpret_\(target)_\(unsignedElement(of: element).cSuffix)(\(counted))"
}

func sveReversedBits(for element: Element) -> String {
    sveBuiltin(
        "rbit",
        [sveAllLanes(of: element), sveOperand("a", for: element, splat: true)],
        for: element,
        predication: "x"
    )
}

func sveBitCount(_ counted: String, for element: Element) -> String {
    vectorResult(sveResult(counted, for: element), for: element)
}

func sveTrailingZeroCount(for element: Element) -> String {
    let reversed = "reversed"
    return """
        const \(sveType(of: element)) \(reversed) = \(sveReversedBits(for: element));
        \(sveBitCount(sveLeadingZeroCount(reversed, for: element), for: element))
        """
}

func sveHighestSetBitIndex(for element: Element) -> String {
    let top = sveBuiltin("dup_n", ["(\(element.cType))\(element.bits - 1)"], for: element)
    let counted = sveLeadingZeroCount(sveOperand("a", for: element, splat: true), for: element)
    let index = sveBuiltin(
        "sub",
        [sveAllLanes(of: element), top, counted],
        for: element,
        predication: "x"
    )
    return sveBitCount(index, for: element)
}

func x86Avx3RotatedByLanes(left: Bool, level: X86Level, for element: Element) -> String? {
    let width = x86Bits(element.width)
    switch element.bits {
    case 32, 64:
        let name = "pro\(left ? "l" : "r")v\(element.bits == 32 ? "d" : "q")\(width)"
        let rotated = x86Builtin(
            name,
            ["a", "b"],
            as: "i\(element.bits)",
            returning: element.cVector
        )
        return vectorResult(rotated, for: element)
    case 16 where level == .avx3dl:
        let counts = left ? negatedLanes("b", for: element) : "b"
        let rotated = x86Builtin(
            "vpshrdvw\(width)",
            ["a", "a", counts],
            as: "i16",
            returning: element.cVector
        )
        return vectorResult(rotated, for: element)
    default:
        return nil
    }
}

func x86Avx3RotatedBySame(left: Bool, level: X86Level, for element: Element) -> String? {
    let width = x86Bits(element.width)
    let lane = element.cType
    switch element.bits {
    case 32, 64:
        let counts = splat("(\(lane))(unsigned)bits", as: element.cVector, lanes: element.laneCount)
        let name = "pro\(left ? "l" : "r")v\(element.bits == 32 ? "d" : "q")\(width)"
        let rotated = x86Builtin(
            name,
            ["a", counts],
            as: "i\(element.bits)",
            returning: element.cVector
        )
        return vectorResult(rotated, for: element)
    case 16 where level == .avx3dl:
        let amount = left ? "(\(lane))(0u - (unsigned)bits)" : "(\(lane))bits"
        let counts = splat(amount, as: element.cVector, lanes: element.laneCount)
        let rotated = x86Builtin(
            "vpshrdvw\(width)",
            ["a", "a", counts],
            as: "i16",
            returning: element.cVector
        )
        return vectorResult(rotated, for: element)
    default:
        return nil
    }
}

func x86Avx3GaloisSignBit(for element: Element) -> String {
    let i8 = x86Vector("i8")
    let matrix = Array(repeating: "(long long)0x8080808080808080ull", count: element.width / 8)
    let operands = [
        (value: "a", type: i8),
        (value: compoundLiteral(x86Vector("i64"), matrix), type: i8),
        (value: "0", type: "char"),
    ]
    let affine = x86Builtin(
        "vgf2p8affineqb_v\(element.width)qi",
        operands,
        returning: element.cVector
    )
    return vectorResult(affine, for: element)
}

func x86Avx3AllBitsSet(for element: Element) -> String {
    let words = unsignedElement(bits: 64).at(width: element.width)
    let i64 = x86Vector("i64")
    return """
        const \(i64) mask = (\(i64))a == -1;
        \(x86AllTrue(for: words))
        """
}

func x86Avx3AllBitsClear(for element: Element) -> String {
    let i64 = x86Vector("i64")
    let type = x86MaskType(lanes: element.width / 8)
    let operands = [
        (value: "a", type: i64),
        (value: compoundLiteral(i64, ["0"]), type: i64),
        (value: "4", type: "int"),
        (value: "-1", type: type),
    ]
    let notZero = x86Builtin("cmpq\(x86Bits(element.width))_mask", operands, returning: type)
    return "return \(notZero) == 0;"
}

func neonAndNot(for element: Element) -> String? {
    guard element.category == .float else { return nil }
    let bytes = unsignedElement(bits: 8).cVector
    return vectorResult("(\(element.cVector))(~(\(bytes))a & (\(bytes))b)", for: element)
}

func neonTernaryBitwise(
    _ name: String,
    _ operands: [String] = ["a", "b", "c"],
    portable: String,
    for element: Element
) -> String {
    let integer = element.category == .float ? unsignedElement(of: element) : element
    let call = neonBuiltin(
        "\(name)q_\(sveSuffix(of: integer))",
        operands,
        code: neonTypeCode(of: integer),
        for: element
    )
    return """
        #if defined(__ARM_FEATURE_SHA3)
        \(vectorResult(call, for: element))
        #else
        \(portable)
        #endif
        """
}

func portableBitwiseXor3(for element: Element) -> String {
    bitwise(for: element) { bits in "\(bits("a")) ^ (\(bits("b")) ^ \(bits("c")))" }
}

func portableBitwiseXorAndNot(for element: Element) -> String {
    bitwise(for: element) { bits in "\(bits("a")) ^ (~\(bits("b")) & \(bits("c")))" }
}

func unsignedBitwise(_ symbol: String, for element: Element) -> String {
    guard element.category == .float else { return unsignedBits("(a \(symbol) b)", of: element) }
    return "(\(unsignedBits("a", of: element)) \(symbol) \(unsignedBits("b", of: element)))"
}

func maskedBitwise(_ symbol: String, for element: Element) -> String {
    let operation = unsignedBitwise(symbol, for: element)
    let selected = fromUnsignedBits("\(operation) & (\(element.cUnsignedVector))mask", of: element)
    return vectorResult(selected, for: element)
}

func commutedMaskedBitwise(_ symbol: String, for element: Element) -> String {
    let operation = unsignedBitwise(symbol, for: element)
    let selected = fromUnsignedBits("(\(element.cUnsignedVector))mask & \(operation)", of: element)
    return vectorResult(selected, for: element)
}

func maskedBitwiseOtherwise(_ symbol: String, operation: String, for element: Element) -> String {
    let selecting = cFunctionName("selecting", element)
    let raw = element.cRawVector
    let combined =
        element.category == .float
        ? "\(cFunctionName(operation, element))(rawA, rawB)" : "(\(raw))(a \(symbol) b)"
    let operands = ["(\(element.cRawMask))mask", combined, "(\(raw))otherwise"]
    return "return \(selecting)(\(operands.joined(separator: ", ")));"
}

func x86Avx3MaskedBitwise(
    _ symbol: String,
    otherwise: String? = nil,
    for element: Element
) -> String {
    let lanes =
        element.category == .float ? signedElement(of: element).at(width: element.width) : element
    let vector = x86Vector(x86LaneSuffix(of: lanes))
    let operation = "(\(vector))a \(symbol) (\(vector))b"
    let selected = x86Avx3Selecting(
        "mask",
        "(\(vector))(\(operation))",
        otherwise ?? compoundLiteral(vector, ["0"]),
        for: lanes
    )
    return vectorResult(selected, for: element)
}

func x86Avx3AndXor(for element: Element) -> String {
    let i64 = x86Vector("i64")
    let ternary = x86Builtin(
        "pternlogq\(x86Bits(element.width))_mask",
        [
            (value: "a", type: i64),
            (value: "b", type: i64),
            (value: "c", type: i64),
            (value: "0x60", type: "int"),
            (value: "-1", type: x86MaskType(lanes: element.width / 8)),
        ],
        returning: element.cVector
    )
    return vectorResult(ternary, for: element)
}

func maskedBitwiseTargets(
    _ symbol: String,
    neon: ((Element) -> String?)? = nil
) -> TargetBodies<Element> {
    TargetBodies(
        neon: neon,
        avx3: { element in x86Avx3MaskedBitwise(symbol, for: element) }
    )
}

func maskedBitwiseOtherwiseTargets(_ symbol: String, operation: String) -> TargetBodies<Element> {
    TargetBodies(
        sve2_128: { element in sveMaskedBitwiseOtherwise(operation, for: element) },
        avx3: { element in
            x86Avx3MaskedBitwise(symbol, otherwise: rawName("otherwise"), for: element)
        }
    )
}

let multiplyAddedBits = 52

func multiplyAddingLow52Bits(for element: Element) -> String {
    let raw = element.cRawVector
    let multiplying = cFunctionName("multiplying", element)
    let product = "(\(element.cVector))\(multiplying)((\(raw))a, (\(raw))b)"
    let mask = (UInt64(1) << UInt64(multiplyAddedBits)) - 1
    let kept = splat("0x\(String(mask, radix: 16))", as: element.cVector, lanes: element.laneCount)
    return vectorResult("(\(product) & \(kept)) + c", for: element)
}

func multiplyAddingHighResult(low: String, for element: Element) -> String {
    let shifted = "(\(low) >> \(multiplyAddedBits)) | (high << \(element.bits - multiplyAddedBits))"
    return vectorResult("(\(shifted)) + c", for: element)
}

func multiplyAddingHigh52BitsHalves(flippingSigns: Bool, for element: Element) -> String {
    let vector = element.cVector
    let raw = element.cRawVector
    func multiplying(_ first: String, _ second: String) -> String {
        let arguments = [first, second].map { "(\(raw))\($0)" }.joined(separator: ", ")
        return "(\(vector))\(cFunctionName("multiplying", element))(\(arguments))"
    }
    func flipped(_ operand: String) -> String {
        let signBit = "0x\(String(UInt64(1) << UInt64(element.bits - 1), radix: 16))"
        let sign = "\(cFunctionName("repeating", element))(\(signBit))"
        return "\(cFunctionName("bitwiseXor", element))((\(raw))\(operand), \(sign))"
    }
    let carried =
        flippingSigns
        ? "\(x86GreaterThanName(bits: element.bits))(\(flipped("p0")), \(flipped("low")))"
        : "\(cFunctionName("greaterThan", element))((\(raw))p0, (\(raw))low)"
    let ones = "\(cFunctionName("repeating", element))(1)"
    let selected = [carried, ones, "\(cFunctionName("zero", element))()"]
    let carry = "\(cFunctionName("selecting", element))(\(selected.joined(separator: ", ")))"
    let halfBits = element.bits / 2
    let halfMask = splat("0xffffffff", as: vector, lanes: element.laneCount)
    return """
        const \(vector) mask = \(halfMask);
        const \(vector) a0 = a & mask;
        const \(vector) b0 = b & mask;
        const \(vector) a1 = a >> \(halfBits);
        const \(vector) b1 = b >> \(halfBits);
        const \(vector) p0 = \(multiplying("a0", "b0"));
        const \(vector) p1Add = \(multiplying("a0", "b1"));
        const \(vector) p1 = \(multiplying("a1", "b0")) + p1Add;
        const \(vector) low = p0 + ((p1 & mask) << \(halfBits));
        const \(vector) carry = (\(vector))\(carry);
        const \(vector) high = \(multiplying("a1", "b1")) + (p1 >> \(halfBits)) + carry;
        \(multiplyAddingHighResult(low: "low", for: element))
        """
}

func multiplyAddingHigh52BitsWhole(for element: Element) -> String {
    let vector = element.cVector
    let lane = element.cUnsignedLane
    let halfBits = element.bits / 2
    let wide = "unsigned __int128"
    return """
        const \(vector) low = a * b;
        \(vector) high;
        for (size_t i = 0; i < \(element.laneCount); ++i) {
        #if defined(__SIZEOF_INT128__)
          high[i] = (\(lane))(((\(wide))a[i] * (\(wide))b[i]) >> \(element.bits));
        #else
          const \(lane) loLo = (a[i] & 0xffffffff) * (b[i] & 0xffffffff);
          const \(lane) hiLo = (a[i] >> \(halfBits)) * (b[i] & 0xffffffff);
          const \(lane) loHi = (a[i] & 0xffffffff) * (b[i] >> \(halfBits));
          const \(lane) hiHi = (a[i] >> \(halfBits)) * (b[i] >> \(halfBits));
          const \(lane) t = (loLo >> \(halfBits)) + (hiLo & 0xffffffff) + loHi;
          high[i] = (hiLo >> \(halfBits)) + (t >> \(halfBits)) + hiHi;
        #endif
        }
        \(multiplyAddingHighResult(low: "low", for: element))
        """
}

func x86MultiplyAdding52Bits(high: Bool, for element: Element) -> String {
    let name = "vpmadd52\(high ? "h" : "l")uq\(x86Bits(element.width))"
    let fused = x86Builtin(name, ["c", "a", "b"], as: "i64", returning: element.cVector)
    return vectorResult(fused, for: element)
}

func x86Multiplying32(for element: Element) -> String {
    let i32 = x86Vector("i32")
    let i64 = x86Vector("i64")
    let evens = x86Builtin("pmuludq128", ["a", "b"], as: "i32", returning: i64)
    let odds = x86Builtin("pmuludq128", ["a_x3x1", "b_x3x1"], as: "i32", returning: i64)
    let product = "(\(element.cVector))__builtin_shufflevector(mul_20, mul_31, 0, 4, 1, 5)"
    return """
        const \(i32) a_x3x1 = __builtin_shufflevector((\(i32))a, (\(i32))a, 1, 1, 3, 3);
        const \(i64) mullo_x2x0 = \(evens);
        const \(i32) b_x3x1 = __builtin_shufflevector((\(i32))b, (\(i32))b, 1, 1, 3, 3);
        const \(i64) mullo_x3x1 = \(odds);
        const \(i32) mul_20 = __builtin_shufflevector(
          (\(i32))mullo_x2x0, (\(i32))mullo_x2x0, 0, 2, 0, 2);
        const \(i32) mul_31 = __builtin_shufflevector(
          (\(i32))mullo_x3x1, (\(i32))mullo_x3x1, 0, 2, 0, 2);
        \(vectorResult(product, for: element))
        """
}

func x86Int64Greater(
    _ first: String,
    _ second: String,
    native: Bool = false,
    for element: Element
) -> String {
    let mask = element.cMask
    guard !native else { return "const \(mask) mask = (\(mask))(\(first) > \(second));" }
    let i32 = x86Vector("i32")
    let i64 = x86Vector("i64")
    return """
        const \(i32) equal = (\(i32))\(first) == (\(i32))\(second);
        const \(i32) greater = (\(i32))\(first) > (\(i32))\(second);
        const \(i64) difference = (\(i64))\(second) - (\(i64))\(first);
        const \(i64) upper = (\(i64))greater | ((\(i64))equal & difference);
        const \(mask) mask = (\(mask))__builtin_shufflevector(
          (\(i32))upper, (\(i32))upper, 1, 1, 3, 3);
        """
}

func x86SignedGreater(
    _ first: String,
    _ second: String,
    native: Bool,
    for element: Element
) -> String {
    guard element.bits == 64 else {
        let mask = element.cMask
        return "const \(mask) mask = (\(mask))(\(first) > \(second));"
    }
    return x86Int64Greater(first, second, native: native, for: element)
}

func x86UnsignedGreater(
    _ first: String,
    _ second: String,
    native: Bool = false,
    for element: Element
) -> String {
    let signed = x86Vector("i\(element.bits)")
    let signBit = String(UInt64(1) << UInt64(element.bits - 1), radix: 16)
    let i64 = x86Vector("i64")
    return """
        const \(element.cVector) flip = \(repeatingVector("0x\(signBit)", of: element));
        const \(signed) signedFirst = (\(signed))((\(i64))\(first) ^ (\(i64))flip);
        const \(signed) signedSecond = (\(signed))((\(i64))\(second) ^ (\(i64))flip);
        \(x86SignedGreater("signedFirst", "signedSecond", native: native, for: element))
        """
}

func x86Int64Comparison(_ first: String, _ second: String, for element: Element) -> String {
    "\(x86Int64Greater(first, second, for: element))\n\(maskResult("mask", for: element))"
}

func x86UnsignedComparison(
    _ first: String,
    _ second: String,
    native: Bool = false,
    for element: Element
) -> String {
    let greater = x86UnsignedGreater(first, second, native: native, for: element)
    return "\(greater)\n\(maskResult("mask", for: element))"
}

func x86Int64Extremum(
    _ chosen: (first: String, second: String),
    native: Bool = false,
    for element: Element
) -> String {
    """
    \(x86Int64Greater("b", "a", native: native, for: element))
    \(vectorResult(bitSelect("mask", chosen.first, chosen.second, of: element), for: element))
    """
}

func x86Selecting(
    _ mask: String,
    _ yes: String,
    _ no: String,
    for element: Element
) -> String {
    let (name, suffix) =
        element.category == .float
        ? (
            "blendv\(element.bits == 32 ? "ps" : "pd")\(x86UnsuffixedBits(element.width))",
            element.cSuffix
        )
        : ("pblendvb\(x86Bits(element.width))", "i8")
    return x86Builtin(name, [no, yes, mask], as: suffix, returning: element.cVector)
}

func x86Avx3Select(
    _ bits: String,
    _ yes: String,
    _ no: String,
    for element: Element
) -> String {
    let name =
        element.category == .float
        ? "selectp\(element.bits == 32 ? "s" : "d")" : "select\(x86LaneLetter(bits: element.bits))"
    let vector = x86Vector(x86LaneSuffix(of: element))
    return x86Builtin(
        "\(name)_\(x86Bits(element.width))",
        [
            (value: bits, type: x86MaskType(lanes: element.laneCount)),
            (value: yes, type: vector),
            (value: no, type: vector),
        ],
        returning: element.cVector
    )
}

func x86Avx3Selecting(
    _ mask: String,
    _ yes: String,
    _ no: String,
    for element: Element
) -> String {
    x86Avx3Select(x86Avx3MaskBits(mask, for: element), yes, no, for: element)
}

func x86BitSelect(_ mask: String, _ yes: String, _ no: String, for element: Element) -> String {
    guard element.category != .float else { return bitSelect(mask, yes, no, of: element) }
    let i64 = x86Vector("i64")
    let chosen = "(\(i64))\(mask) & (\(i64))\(yes)"
    let rest = "~(\(i64))\(mask) & (\(i64))\(no)"
    return "(\(element.cVector))((\(chosen)) | (\(rest)))"
}

func x86Immediate(_ value: Int) -> String {
    value < 10 ? "\(value)" : "0x\(String(value, radix: 16, uppercase: true))"
}

func x86WideSlideQuads(
    _ direction: SlideDirection,
    by quads: Int,
    for element: Element
) -> String {
    let i32 = x86Vector("i32")
    let i64 = x86Vector("i64")
    let f64 = x86Vector("f64")
    let sources = (0..<4).map { ((direction == .up ? $0 - quads : $0 + quads) % 4 + 4) % 4 }
    let permutation = x86Immediate(
        sources.enumerated().reduce(0) { $0 | $1.element << (2 * $1.offset) }
    )
    let (floatBlend, integerBlend) =
        switch direction {
        case .up: (x86Immediate((1 << quads) - 1), x86Immediate((1 << (quads * 2)) - 1))
        case .down:
            (
                x86Immediate((0x0F << (4 - quads)) & 0x0F),
                x86Immediate((0xFF << ((4 - quads) * 2)) & 0xFF)
            )
        }
    let permutationOperand = (value: permutation, type: "int")
    guard element.category != .float else {
        let permuted = x86Builtin(
            "permdf256",
            [(value: "a", type: f64), permutationOperand],
            returning: f64
        )
        let blended = x86Builtin(
            "blendpd256",
            [
                (value: permuted, type: f64),
                (value: compoundLiteral(f64, ["0"]), type: f64),
                (value: floatBlend, type: "int"),
            ],
            returning: element.cVector
        )
        return vectorResult(blended, for: element)
    }
    let permuted = x86Builtin(
        "permdi256",
        [(value: "a", type: i64), permutationOperand],
        returning: i64
    )
    let blended = x86Builtin(
        "pblendd256",
        [
            (value: permuted, type: i32),
            (value: compoundLiteral(i32, ["0"]), type: i32),
            (value: integerBlend, type: "int"),
        ],
        returning: element.cVector
    )
    return vectorResult(blended, for: element)
}

func x86WideSlideBytes(
    _ direction: SlideDirection,
    by bytes: Int,
    for element: Element
) -> String {
    guard bytes != 8 && bytes != 24 else {
        return x86WideSlideQuads(direction, by: bytes / 8, for: element)
    }
    guard bytes < 16 else { return x86WideSlideHalf(direction, by: bytes, for: element) }
    let i8 = x86Vector("i8")
    let i64 = x86Vector("i64")
    guard direction == .up else {
        let shifted = x86Builtin(
            "palignr256",
            [
                (value: "high", type: i8),
                (value: "whole", type: i8),
                (value: "\(bytes)", type: "int"),
            ],
            returning: element.cVector
        )
        return """
            const \(i64) whole = (\(i64))a;
            const \(i64) high = __builtin_shufflevector(whole, (\(i64)){0}, 2, 3, 4, 5);
            \(vectorResult(shifted, for: element))
            """
    }
    let shifted = x86Builtin(
        "palignr256",
        [
            (value: "whole", type: i8),
            (value: "lower", type: i8),
            (value: "\(16 - bytes)", type: "int"),
        ],
        returning: element.cVector
    )
    guard isFloat32(element) else {
        let lower = x86Builtin(
            "permti256",
            [
                (value: compoundLiteral(i64, ["0"]), type: i64),
                (value: "whole", type: i64),
                (value: "0x20", type: "int"),
            ],
            returning: i64
        )
        return """
            const \(i64) whole = (\(i64))a;
            const \(i64) lower = \(lower);
            \(vectorResult(shifted, for: element))
            """
    }
    let f32 = x86Vector("f32")
    let lower = x86Builtin(
        "vperm2f128_ps256",
        [
            (value: compoundLiteral(f32, ["0"]), type: f32),
            (value: "whole", type: f32),
            (value: "0x20", type: "int"),
        ],
        returning: f32
    )
    return """
        const \(f32) whole = (\(f32))a;
        const \(f32) lower = \(lower);
        \(vectorResult(shifted, for: element))
        """
}

func x86WideSlideHalf(
    _ direction: SlideDirection,
    by bytes: Int,
    for element: Element
) -> String {
    let suffix = element.category == .float ? element.cSuffix : "i64"
    let vector = x86Vector(suffix)
    let block = x86Block(suffix)
    let zero = compoundLiteral(block, ["0"])
    let blockLanes = 16 / (element.category == .float ? element.bits / 8 : 8)
    let wholeLanes = 2 * blockLanes
    let shifted = x86ByteShift(
        direction,
        "(\(x86Block("i64")))half",
        by: bytes - 16
    )
    let (half, result) =
        switch direction {
        case .up:
            (
                laneIndices(0..<blockLanes),
                "__builtin_shufflevector(\(zero), shifted, \(laneIndices(0..<wholeLanes)))"
            )
        case .down:
            (
                laneIndices(blockLanes..<wholeLanes),
                "__builtin_shufflevector(shifted, \(zero), \(laneIndices(0..<wholeLanes)))"
            )
        }
    return """
        const \(vector) whole = (\(vector))a;
        const \(block) half = __builtin_shufflevector(whole, whole, \(half));
        const \(block) shifted = (\(block))\(shifted);
        \(vectorResult(result, for: element))
        """
}

func x86WideSlideAmount(_ direction: SlideDirection, for element: Element) -> (Int) -> String? {
    { amount in
        let bytes = amount * element.bits / 8
        let isShorterAsShuffle =
            bytes == 16
            || (direction == .up && (bytes == 31 || (bytes == 24 && !isFloat32(element))))
        return isShorterAsShuffle ? nil : x86WideSlideBytes(direction, by: bytes, for: element)
    }
}

func x86Avx3Slide1(
    _ direction: SlideDirection,
    level: X86Level = .avx3,
    filling: Bool = false,
    for element: Element
) -> String {
    let isTableLookup = element.bits == 16 || (element.bits == 8 && level == .avx3dl)
    guard direction == .down || filling || !isTableLookup else {
        return x86TwoTableSlide(.up, by: "1", for: element)
    }
    let width = x86Bits(element.width)
    let fill = filling ? "set" : "0"
    func aligned(
        _ name: String,
        laneBits: Int,
        by lanes: Int,
        returning type: String
    ) -> String {
        let vector = x86Vector("i\(laneBits)")
        let filler = filling ? fill : compoundLiteral(vector, [fill])
        let (high, low) = direction == .up ? ("a", filler) : (filler, "a")
        return x86Builtin(
            name,
            [
                (value: high, type: vector),
                (value: low, type: vector),
                (value: "\(lanes)", type: "int"),
            ],
            returning: type
        )
    }
    let set =
        filling ? "const \(element.cVector) set = \(repeatingVector("fill", of: element));\n" : ""
    guard element.bits < 32 else {
        let shifted = aligned(
            "\(element.bits == 32 ? "alignd" : "alignq")\(width)",
            laneBits: element.bits,
            by: direction == .up ? element.laneCount - 1 : 1,
            returning: element.cVector
        )
        return "\(set)\(vectorResult(shifted, for: element))"
    }
    let i8 = x86Vector("i8")
    let i64 = x86Vector("i64")
    let (neighbour, operands) =
        switch direction {
        case .up: ("lower", ("a", "lower"))
        case .down: ("upper", ("upper", "a"))
        }
    let slid = aligned(
        "alignq\(width)",
        laneBits: 64,
        by: direction == .up ? 6 : 2,
        returning: i64
    )
    let shifted = x86Builtin(
        "palignr\(width)",
        [
            (value: operands.0, type: i8),
            (value: operands.1, type: i8),
            (value: "\(direction == .up ? 16 - element.bits / 8 : element.bits / 8)", type: "int"),
        ],
        returning: element.cVector
    )
    return """
        \(set)const \(i64) \(neighbour) = \(slid);
        \(vectorResult(shifted, for: element))
        """
}

func x86Slide1Up(for element: Element) -> String {
    vectorResult(x86SlideBytes(.up, by: 1, for: element), for: element)
}

func x86Avx3MaskBits(_ operand: String, for element: Element) -> String {
    let name = "cvt\(x86LaneLetter(bits: element.bits))2mask\(x86Bits(element.width))"
    let type = x86MaskType(lanes: element.laneCount)
    return x86Builtin(name, [operand], as: "i\(element.bits)", returning: type)
}

func x86MaskBits(of operand: String = "mask", for element: Element) -> String {
    guard element.width < 64 else { return x86Avx3MaskBits(operand, for: element) }
    let moves = "pmovmskb\(x86Bits(element.width))"
    switch element.bits {
    case 8:
        return x86Builtin(moves, [operand], as: "i8", returning: "int")
    case 16 where element.width > 16:
        return x86Builtin(moves, [operand], as: "i8", returning: "int")
    case 16:
        let zero = compoundLiteral(x86Vector("i16"), ["0"])
        let packed = x86Builtin(
            "packsswb128",
            [operand, zero],
            as: "i16",
            returning: x86Vector("i8")
        )
        return x86Builtin(moves, [packed], as: "i8", returning: "int")
    case 32:
        let name = "movmskps\(x86UnsuffixedBits(element.width))"
        return x86Builtin(name, [operand], as: "f32", returning: "int")
    default:
        let name = "movmskpd\(x86UnsuffixedBits(element.width))"
        return x86Builtin(name, [operand], as: "f64", returning: "int")
    }
}

func x86MaskBitsPerLane(for element: Element) -> Int {
    element.bits == 16 && element.width == 32 ? 2 : 1
}

func x86MaskBitCount(for element: Element) -> Int {
    element.laneCount * x86MaskBitsPerLane(for: element)
}

func x86AllTrue(for element: Element) -> String {
    let bits = x86MaskBitCount(for: element)
    let allBits = "0x\(String(UInt64.max >> UInt64(64 - bits), radix: 16))"
    guard bits < 64 else { return "return \(x86MaskBits(for: element)) == \(allBits)ull;" }
    guard bits < 32 else { return "return (unsigned)\(x86MaskBits(for: element)) == \(allBits)u;" }
    return "return \(x86MaskBits(for: element)) == \(allBits);"
}

func x86TrueCount(for element: Element) -> String {
    let converted = x86MaskBitCount(for: element) > 32 ? "" : "(unsigned)"
    let count = "__builtin_popcountll((uint64_t)\(converted)\(x86MaskBits(for: element)))"
    guard x86MaskBitsPerLane(for: element) > 1 else { return "return (size_t)\(count);" }
    return "return (size_t)(\(count) >> 1);"
}

func x86FirstTrueIndex(for element: Element) -> String {
    let argument =
        x86MaskBitCount(for: element) < 32 && element.width < 32 ? "bits | 0x80000000u" : "bits"
    let index = "__builtin_ctz(\(argument))"
    let lane = x86MaskBitsPerLane(for: element) > 1 ? "(\(index) >> 1)" : index
    return """
        const unsigned bits = (unsigned)\(x86MaskBits(for: element));
        return bits ? (intptr_t)\(lane) : -1;
        """
}

func x86UnpackLower(_ low: String, _ high: String, laneBits: Int) -> String {
    let type = x86Vector("i\(laneBits)")
    let indices = laneIndices(unpackIndices(lanes: 128 / laneBits, upper: false))
    return "__builtin_shufflevector((\(type))\(low), (\(type))\(high), \(indices))"
}

func x86ZeroExtension(of register: String, from narrow: Element, to wide: Element) -> String {
    let zero = compoundLiteral(x86Vector("i64"), ["0"])
    var statements: [String] = []
    var source = register
    var bits = narrow.bits
    while bits < wide.bits {
        let name = "unpacked\(2 * bits)"
        let unpacked = x86UnpackLower(source, zero, laneBits: bits)
        statements.append("const \(x86Vector("i\(bits)")) \(name) = \(unpacked);")
        source = name
        bits *= 2
    }
    return (statements + [vectorResult("(\(wide.cVector))\(source)", for: wide)])
        .joined(separator: "\n")
}

func x86ShuffledZeroExtension(
    of register: String,
    from narrow: Element,
    to wide: Element
) -> String {
    let bytes = narrow.bits / 8
    let table = (0..<16).map { index -> String in
        let lane = index / 8
        let byte = index % 8
        return byte < bytes ? String(lane * bytes + byte) : "-1"
    }
    let i8 = x86Vector("i8")
    let lookup = x86Builtin("pshufb128", [register, "shuffle"], as: "i8", returning: wide.cVector)
    return """
        const \(i8) shuffle = \(compoundLiteral(i8, table));
        \(vectorResult(lookup, for: wide))
        """
}

func x86SignExtension(of register: String, from narrow: Element, to wide: Element) -> String {
    let i8 = x86Vector("i8")
    let i16 = x86Vector("i16")
    let i32 = x86Vector("i32")
    let i64 = x86Vector("i64")
    func shifted(_ operand: String, by amount: Int, laneBits: Int) -> String {
        x86ImmediateShift(
            "psra",
            operand,
            by: "\(amount)",
            laneBits: laneBits,
            returning: wide.cVector
        )
    }
    switch (narrow.bits, wide.bits) {
    case (8, 16):
        return """
            const \(i8) pairs = \(x86UnpackLower(register, register, laneBits: 8));
            \(vectorResult(shifted("pairs", by: 8, laneBits: 16), for: wide))
            """
    case (16, 32):
        return """
            const \(i16) pairs = \(x86UnpackLower(register, register, laneBits: 16));
            \(vectorResult(shifted("pairs", by: 16, laneBits: 32), for: wide))
            """
    case (8, 32):
        return """
            const \(i8) pairs = \(x86UnpackLower(register, register, laneBits: 8));
            const \(i16) quads = \(x86UnpackLower("pairs", "pairs", laneBits: 16));
            \(vectorResult(shifted("quads", by: 24, laneBits: 32), for: wide))
            """
    case (32, 64):
        let right = x86ImmediateShift("psrl", "pairs", by: "32", laneBits: 64, returning: i64)
        let signs = x86ImmediateShift("psra", "pairs", by: "31", laneBits: 32, returning: i32)
        let sign = x86ImmediateShift("psll", "broadcast", by: "32", laneBits: 64, returning: i64)
        return """
            const \(i32) pairs = \(x86UnpackLower(register, register, laneBits: 32));
            const \(i64) right = \(right);
            const \(i32) signs = \(signs);
            const \(i32) broadcast = __builtin_shufflevector(signs, signs, 1, 1, 3, 3);
            const \(i64) sign = \(sign);
            \(vectorResult("(\(wide.cVector))(right | sign)", for: wide))
            """
    default:
        let widened: String
        if narrow.bits == 8 {
            widened = """
                const \(i8) pairs = \(x86UnpackLower(register, register, laneBits: 8));
                const \(i16) quads = \(x86UnpackLower("pairs", "pairs", laneBits: 16));
                const \(i32) lanes = (\(i32))quads >> 24;
                """
        } else {
            widened = """
                const \(i16) pairs = \(x86UnpackLower(register, register, laneBits: 16));
                const \(i32) lanes = (\(i32))pairs >> 16;
                """
        }
        let interleaved = "__builtin_shufflevector(lanes, (\(i32))signs, 0, 4, 1, 5)"
        return """
            \(widened)
            const \(i16) signs = __builtin_shufflevector(
              (\(i16))lanes, (\(i16))lanes, \(laneIndices(1..<2, 1..<2, 3..<4, 3..<4, 4..<8)));
            \(vectorResult("(\(wide.cVector))\(interleaved)", for: wide))
            """
    }
}

func x86Promotion(
    of register: String,
    from narrow: Element,
    to wide: Element,
    level: X86Level
) -> String {
    guard narrow.category == .unsignedInteger else {
        return x86SignExtension(of: register, from: narrow, to: wide)
    }
    guard level == .ssse3, wide.bits == 64, narrow.bits < 32 else {
        return x86ZeroExtension(of: register, from: narrow, to: wide)
    }
    return x86ShuffledZeroExtension(of: register, from: narrow, to: wide)
}

func x86PromotionName(from narrow: Element, to wide: Element) -> String {
    "cvectorization_ops_x86_promote_\(narrow.cSuffix)_to_\(wide.cSuffix)"
}

func x86UnsignedToDoublePromotion(level: X86Level, to wide: Element) -> String {
    let lanes = wide.laneCount
    let unsigned = unsignedElement(bits: 64).cVector
    let signedLanes = vectorTypedef("signed_lanes", lane: "int32_t", bits: 32, lanes: lanes)
    let lowest = "__builtin_shufflevector(a, a, \(laneIndices(0..<lanes)))"
    let bias = splat("4294967296.0", as: wide.cVector, lanes: lanes)
    let zero = compoundLiteral(wide.cVector, ["0"])
    let adjustment: String
    if level >= .sse4 {
        let selected = x86Builtin(
            "blendvpd\(x86UnsuffixedBits(wide.width))",
            [zero, bias, "converted"],
            as: "f64",
            returning: wide.cVector
        )
        adjustment = "const \(wide.cVector) adjustment = \(selected);"
    } else {
        let words = vectorTypedef("sign_words", lane: "int32_t", bits: 32, lanes: 2 * lanes)
        adjustment = """
            \(words)
            const sign_words signs = (sign_words)converted >> 31;
            const sign_words broadcast = __builtin_shufflevector(signs, signs, 1, 1, 3, 3);
            const \(wide.cVector) adjustment = (\(wide.cVector))((\(unsigned))broadcast & (\(unsigned))\(bias));
            """
    }
    return """
        \(signedLanes)
        const \(wide.cVector) converted = __builtin_convertvector((signed_lanes)\(lowest), \(wide.cVector));
        \(adjustment)
        \(vectorResult("converted + adjustment", for: wide))
        """
}

func x86SaturatingPromotion(level: X86Level, to integer: Element) -> String {
    let isSigned = integer.category == .signedInteger
    let floats = floatElement(bits: 32).cBlock
    let words = unsignedElement(of: unsignedElement(bits: 32)).cBlock
    let signedWords = signedElement(of: unsignedElement(of: unsignedElement(bits: 32))).cBlock
    let bytes = unsignedElement(bits: 8).cBlock
    let magnitude = isSigned ? "bits" : "nonNegative"
    let unsigned = "unsigned_vector"
    func promoted(_ source: Element, _ operand: String) -> String {
        let raw = x86RawBlockType(of: source)
        return "(\(unsigned))\(x86PromotionName(from: source, to: integer))((\(raw))\(operand))"
    }
    let exponents = "(\(bytes))(\(magnitude) >> 23)"
    let bias = "(\(bytes))\(splat("157", as: words, lanes: 4))"
    let excess = "__builtin_elementwise_sub_sat(\(exponents), \(bias))"
    let limit = "(\(bytes))\(splat(isSigned ? "32" : "33", as: words, lanes: 4))"
    let truncation = x86Builtin(
        "cvttps2dq",
        [(value: "adjusted", type: x86Block("f32"))],
        returning: signedWords
    )
    var statements = [
        vectorTypedef(unsigned, of: unsignedElement(bits: 64), lanes: integer.laneCount),
        "const \(words) bits = (\(words))a;",
    ]
    if !isSigned {
        let zeroed =
            level >= .sse4
            ? x86Builtin(
                "blendvps",
                [
                    (value: "bits", type: x86Block("f32")),
                    (value: compoundLiteral(x86Block("f32"), ["0"]), type: x86Block("f32")),
                    (value: "bits", type: x86Block("f32")),
                ],
                returning: words
            ) : "bits & ~(\(words))((\(signedWords))bits >> 31)"
        statements.append("const \(words) nonNegative = \(zeroed);")
    }
    statements += [
        "const \(words) adjustment = (\(words))__builtin_elementwise_min(\(excess), \(limit));",
        "const \(floats) adjusted = (\(floats))(\(magnitude) - (adjustment << 23));",
    ]
    let truncated = "const \(signedWords) truncated = \(truncation);"
    let unsignedSource = unsignedElement(of: unsignedElement(bits: 32))
    let significand: String
    let carry: String
    if isSigned {
        significand = promoted(signedElement(of: unsignedSource), "clamped")
        carry = promoted(unsignedSource, "saturated")
        let limitWords = splat("INT32_MAX", as: signedWords, lanes: 4)
        statements += [
            "const \(signedWords) overflow = (\(signedWords))(adjusted >= \(splat("2147483648.0f", as: floats, lanes: 4)));",
            truncated,
            "const \(signedWords) clamped = (truncated & ~overflow) | (\(limitWords) & overflow);",
            "const \(signedWords) saturated = (\(signedWords))(clamped == \(limitWords));",
        ]
    } else {
        significand = promoted(unsignedSource, "truncated")
        carry =
            integer.width == 16
            ? "(\(unsigned))__builtin_shufflevector(overflow, overflow, 0, 0, 1, 1)"
            : "(\(unsigned))__builtin_convertvector(overflow, \(signedElement(of: integer).cVector))"
        statements += [truncated, "const \(signedWords) overflow = truncated >> 31;"]
    }
    statements += [
        "const \(unsigned) carry = \(carry);",
        "const \(unsigned) significand = \(significand);",
        "const \(unsigned) counts = \(promoted(unsignedSource, "adjustment"));",
        vectorResult(
            "\(x86VariableShift("significand", by: "counts", left: true, width: integer.width)) | carry",
            for: integer
        ),
    ]
    return statements.joined(separator: "\n")
}

func x86PromotionHelper(from narrow: Element, to wide: Element, level: X86Level) -> String {
    let vector = narrow.cBlock
    let lowest = laneIndices(0..<wide.laneCount)
    let converted = vectorResult(
        "__builtin_convertvector(__builtin_shufflevector(a, a, \(lowest)), \(wide.cVector))",
        for: wide
    )
    let promotion: String
    if convertsFloatToInteger(from: narrow, to: wide) {
        promotion = x86SaturatingPromotion(level: level, to: wide)
    } else if narrow.category == .unsignedInteger && wide.category == .float {
        promotion = x86UnsignedToDoublePromotion(level: level, to: wide)
    } else if narrow.category == .float || wide.category == .float || level >= .sse4 {
        promotion = converted
    } else {
        promotion = x86Promotion(of: "a", from: narrow, to: wide, level: level)
    }
    return cFunction(
        returns: wide.cRawVector,
        name: x86PromotionName(from: narrow, to: wide),
        parameters: ["\(x86RawBlockType(of: narrow)) v"],
        body: "const \(vector) a = (\(vector))v;\n\(promotion)"
    )
    .trimmingCharacters(in: .newlines)
}

func x86PromotionHelpers(from narrow: Element) -> TargetBodies<Element> {
    TargetBodies(
        avx2: { wide in x86PromotionHelper(from: narrow, to: wide, level: .avx2) },
        sse4: { wide in x86PromotionHelper(from: narrow, to: wide, level: .sse4) },
        ssse3: { wide in x86PromotionHelper(from: narrow, to: wide, level: .ssse3) },
        sse2: { wide in x86PromotionHelper(from: narrow, to: wide, level: .sse2) }
    )
}

func x86Widening(takesCount: Bool, from narrow: Element, to wide: Element) -> String {
    let load =
        takesCount
        ? "\(x86LoadFirstName(lanes: wide.laneCount, for: narrow))(from, count)"
        : "\(x86PartialName("load", bytes: wide.laneCount * narrow.bits / 8, for: narrow))(from)"
    return "return \(x86PromotionName(from: narrow, to: wide))(\(load));"
}

struct ShuffleStep {
    let name: String
    let first: String
    let second: String
    let laneBits: Int
    let indices: [Int]
    var isFloating = false
    var byteShift: Int?
    var unpacksUpper: Bool?

    static func lower(
        _ name: String,
        _ first: String,
        _ second: String,
        laneBits: Int,
        isFloating: Bool = false
    ) -> Self {
        let indices = unpackIndices(lanes: 128 / laneBits, upper: false)
        return Self(
            name: name,
            first: first,
            second: second,
            laneBits: laneBits,
            indices: indices,
            isFloating: isFloating,
            unpacksUpper: false
        )
    }

    static func upper(
        _ name: String,
        _ first: String,
        _ second: String,
        laneBits: Int,
        isFloating: Bool = false
    ) -> Self {
        let indices = unpackIndices(lanes: 128 / laneBits, upper: true)
        return Self(
            name: name,
            first: first,
            second: second,
            laneBits: laneBits,
            indices: indices,
            isFloating: isFloating,
            unpacksUpper: true
        )
    }

    static func permuting(
        _ name: String,
        _ source: String,
        indices: [Int],
        laneBits: Int
    ) -> Self {
        Self(name: name, first: source, second: source, laneBits: laneBits, indices: indices)
    }

    static func byteShiftedRight(_ name: String, _ source: String, bytes: Int) -> Self {
        Self(
            name: name,
            first: source,
            second: source,
            laneBits: 64,
            indices: [],
            byteShift: bytes
        )
    }

    static func floating(
        _ name: String,
        _ first: String,
        _ second: String,
        indices: [Int],
        laneBits: Int
    ) -> Self {
        Self(
            name: name,
            first: first,
            second: second,
            laneBits: laneBits,
            indices: indices,
            isFloating: true
        )
    }
}

func x86Shuffles(
    _ steps: [ShuffleStep],
    opaqueCasts: Bool = false,
    for element: Element
) -> [String] {
    steps.map { step in
        if let bytes = step.byteShift {
            let type = x86Vector(element.category == .float ? "f\(element.bits)" : "i64")
            let shifted =
                "__builtin_ia32_psrldqi128_byteshift((\(x86Vector("i64")))\(step.first), \(bytes))"
            return "const \(type) \(step.name) = (\(type))\(shifted);"
        }
        let isNative = element.category == .float && step.laneBits == element.bits
        let type = x86Vector("\(step.isFloating || isNative ? "f" : "i")\(step.laneBits)")
        func operand(_ name: String) -> String {
            guard opaqueCasts && step.isFloating && !isNative else { return "(\(type))\(name)" }
            return "\(x86AsFloatName(bits: step.laneBits))((\(x86Vector("i64")))\(name))"
        }
        let operands = "\(operand(step.first)), \(operand(step.second))"
        let indices = laneIndices(
            step.unpacksUpper.map {
                unpackIndices(lanes: 128 / step.laneBits, upper: $0, blocks: element.width / 16)
            } ?? step.indices
        )
        return "const \(type) \(step.name) = __builtin_shufflevector(\(operands), \(indices));"
    }
}

func x86LoadInterleaved4Steps(for element: Element) -> [ShuffleStep] {
    switch element.bits {
    case 8:
        return [
            .lower("v5140", "vA", "vB", laneBits: 8),
            .lower("vd9c8", "vC", "vD", laneBits: 8),
            .upper("v7362", "vA", "vB", laneBits: 8),
            .upper("vfbea", "vC", "vD", laneBits: 8),
            .lower("v6420", "v5140", "v7362", laneBits: 8),
            .lower("veca8", "vd9c8", "vfbea", laneBits: 8),
            .upper("v7531", "v5140", "v7362", laneBits: 8),
            .upper("vfdb9", "vd9c8", "vfbea", laneBits: 8),
            .lower("v10L", "v6420", "v7531", laneBits: 8),
            .lower("v10U", "veca8", "vfdb9", laneBits: 8),
            .upper("v32L", "v6420", "v7531", laneBits: 8),
            .upper("v32U", "veca8", "vfdb9", laneBits: 8),
            .lower("r0", "v10L", "v10U", laneBits: 64),
            .upper("r1", "v10L", "v10U", laneBits: 64),
            .lower("r2", "v32L", "v32U", laneBits: 64),
            .upper("r3", "v32L", "v32U", laneBits: 64),
        ]
    case 16:
        return [
            .lower("va820", "vA", "vB", laneBits: 16),
            .lower("vec64", "vC", "vD", laneBits: 16),
            .upper("vb931", "vA", "vB", laneBits: 16),
            .upper("vfd75", "vC", "vD", laneBits: 16),
            .lower("v10b830", "va820", "vb931", laneBits: 16),
            .lower("v10fc74", "vec64", "vfd75", laneBits: 16),
            .upper("v32b830", "va820", "vb931", laneBits: 16),
            .upper("v32fc74", "vec64", "vfd75", laneBits: 16),
            .lower("r0", "v10b830", "v10fc74", laneBits: 64),
            .upper("r1", "v10b830", "v10fc74", laneBits: 64),
            .lower("r2", "v32b830", "v32fc74", laneBits: 64),
            .upper("r3", "v32b830", "v32fc74", laneBits: 64),
        ]
    case 32:
        return [
            .lower("v10e", "vA", "vC", laneBits: 32),
            .lower("v10o", "vB", "vD", laneBits: 32),
            .upper("v32e", "vA", "vC", laneBits: 32),
            .upper("v32o", "vB", "vD", laneBits: 32),
            .lower("r0", "v10e", "v10o", laneBits: 32),
            .upper("r1", "v10e", "v10o", laneBits: 32),
            .lower("r2", "v32e", "v32o", laneBits: 32),
            .upper("r3", "v32e", "v32o", laneBits: 32),
        ]
    default:
        return [
            .lower("r0", "vA", "vC", laneBits: 64),
            .upper("r1", "vA", "vC", laneBits: 64),
            .lower("r2", "vB", "vD", laneBits: 64),
            .upper("r3", "vB", "vD", laneBits: 64),
        ]
    }
}

func x86StoreInterleaved4Steps(for element: Element) -> [ShuffleStep] {
    let bits = element.bits
    guard bits < 64 else {
        return [
            .lower("vA", "a", "b", laneBits: 64),
            .lower("vB", "c", "d", laneBits: 64),
            .upper("vC", "a", "b", laneBits: 64),
            .upper("vD", "c", "d", laneBits: 64),
        ]
    }
    return [
        .lower("v10L", "a", "b", laneBits: bits),
        .lower("v32L", "c", "d", laneBits: bits),
        .upper("v10U", "a", "b", laneBits: bits),
        .upper("v32U", "c", "d", laneBits: bits),
        .lower("vA", "v10L", "v32L", laneBits: 2 * bits),
        .upper("vB", "v10L", "v32L", laneBits: 2 * bits),
        .lower("vC", "v10U", "v32U", laneBits: 2 * bits),
        .upper("vD", "v10U", "v32U", laneBits: 2 * bits),
    ]
}

func x86OddEven(
    _ name: String,
    odd: String,
    even: String,
    level: X86Level,
    for element: Element
) -> [ShuffleStep] {
    guard element.bits == 32 else {
        guard level >= .sse4 else {
            return [.floating(name, even, odd, indices: [0, 3], laneBits: 64)]
        }
        return [.floating(name, odd, even, indices: [2, 1], laneBits: 64)]
    }
    guard level >= .sse4 else {
        return [
            .permuting("\(name)Odd", odd, indices: [1, 3, 1, 3], laneBits: 32),
            .permuting("\(name)Even", even, indices: [0, 2, 0, 2], laneBits: 32),
            .lower(name, "\(name)Even", "\(name)Odd", laneBits: 32),
        ]
    }
    return [.floating(name, odd, even, indices: [4, 1, 6, 3], laneBits: 32)]
}

func x86LoadInterleaved3Steps(level: X86Level, for element: Element) -> [ShuffleStep] {
    func oddEven(_ name: String, odd: String, even: String) -> [ShuffleStep] {
        x86OddEven(name, odd: odd, even: even, level: level, for: element)
    }
    guard element.bits == 32 else {
        let indices = Array(8..<24)
        return oddEven("r0", odd: "vB", even: "vA")
            + [ShuffleStep(name: "r1", first: "vA", second: "vC", laneBits: 8, indices: indices)]
            + oddEven("r2", odd: "vC", even: "vB")
    }
    return oddEven("vxx0203xx", odd: "vC", even: "vB")
        + [.floating("r0", "vA", "vxx0203xx", indices: [0, 3, 6, 5], laneBits: 32)]
        + oddEven("vxxxx1011", odd: "vA", even: "vB")
        + oddEven("v1213xxxx", odd: "vB", even: "vC")
        + [.floating("r1", "vxxxx1011", "v1213xxxx", indices: [1, 0, 7, 6], laneBits: 32)]
        + oddEven("vxx2021xx", odd: "vB", even: "vA")
        + [.floating("r2", "vxx2021xx", "vC", indices: [2, 1, 4, 7], laneBits: 32)]
}

func x86StoreInterleaved2Steps(for element: Element) -> [ShuffleStep] {
    [
        .lower("vA", "a", "b", laneBits: element.bits),
        .upper("vB", "a", "b", laneBits: element.bits),
    ]
}

func x86StoreInterleaved3Steps(level: X86Level, for element: Element) -> [ShuffleStep] {
    func oddEven(_ name: String, odd: String, even: String) -> [ShuffleStep] {
        x86OddEven(name, odd: odd, even: even, level: level, for: element)
    }
    let isFloating = element.category == .float
    guard element.bits == 32 else {
        return [.lower("vA", "a", "b", laneBits: 64)]
            + oddEven("vB", odd: "a", even: "c")
            + [.upper("vC", "b", "c", laneBits: 64)]
    }
    return [.lower("v10v00", "a", "b", laneBits: 32)]
        + oddEven("v01v20", odd: "a", even: "c")
        + [
            .lower("vA", "v10v00", "v01v20", laneBits: 64, isFloating: isFloating),
            .byteShiftedRight("v1x321", "b", bytes: 4),
            .byteShiftedRight("v0x32", "a", bytes: 8),
        ]
        + oddEven("v21v11", odd: "c", even: "v1x321")
        + oddEven("v12v02", odd: "v1x321", even: "v0x32")
        + [
            .lower("vB", "v21v11", "v12v02", laneBits: 64, isFloating: isFloating),
            .upper("vC", "v01v20", "v21v11", laneBits: 64, isFloating: isFloating),
        ]
}

func x86LoadInterleaved(
    _ steps: [ShuffleStep],
    channels: Int,
    for element: Element
) -> String {
    let names = ["vA", "vB", "vC", "vD"].prefix(channels)
    let kind = element.category == .float ? "f" : "i"
    let declaration = "\(x86Vector("\(kind)\(element.bits)")) \(names.joined(separator: ", "));"
    let loads = names.enumerated().map { index, name in
        "__builtin_memcpy(&\(name), from + \(index * element.laneCount), sizeof \(name));"
    }
    let shuffles = steps.flatMap { step -> [String] in
        let shuffle = x86Shuffles([step], for: element)
        guard step.name.hasPrefix("r"), let channel = Int(step.name.dropFirst()) else {
            return shuffle
        }
        let value = "(\(element.cVector))\(step.name)"
        return shuffle + [outVectorStore(channel, of: value, for: element)]
    }
    return ([declaration] + loads + shuffles).joined(separator: "\n")
}

func x86StoreInterleaved(
    _ steps: [ShuffleStep],
    channels: Int,
    for element: Element
) -> String {
    let stores = ["vA", "vB", "vC", "vD"].prefix(channels).enumerated().map { index, name in
        "__builtin_memcpy(to + \(index * element.laneCount), &\(name), sizeof \(name));"
    }
    return (x86Shuffles(steps, opaqueCasts: true, for: element) + stores).joined(separator: "\n")
}

enum X86Avx2ConcatKind {
    case lowerLower
    case lowerUpper
    case upperLower
    case upperUpper
}

func x86Avx2NativeSuffix(of element: Element) -> String {
    element.category == .float ? element.cSuffix : "i64"
}

func x86Avx2Concat(
    _ concat: X86Avx2ConcatKind,
    hi: String,
    lo: String,
    for element: Element
) -> String {
    let suffix = x86Avx2NativeSuffix(of: element)
    let vector = x86Vector(suffix)
    let isFloating = element.category == .float
    let precision = element.bits == 32 ? "ps" : "pd"
    let blockLanes = isFloating ? element.blockLaneCount : 2
    let operands = [(value: lo, type: vector), (value: hi, type: vector)]
    func permuted(_ control: Int) -> String {
        x86Builtin(
            isFloating ? "vperm2f128_\(precision)256" : "permti256",
            operands + [(value: x86Immediate(control), type: "int")],
            returning: vector
        )
    }
    switch concat {
    case .lowerLower:
        let lowerHalf = """
            __builtin_shufflevector(\
            (\(vector))\(hi), (\(vector))\(hi), \(laneIndices(0..<blockLanes)))
            """
        return x86Builtin(
            isFloating ? "vinsertf128_\(precision)256" : "insert128i256",
            [
                (value: lo, type: vector), (value: lowerHalf, type: x86Block(suffix)),
                (value: "1", type: "int"),
            ],
            returning: vector
        )
    case .lowerUpper:
        return permuted(0x21)
    case .upperLower:
        let blendType = x86Vector(isFloating ? element.cSuffix : "i32")
        let control = isFloating && element.bits == 64 ? 3 : 0x0F
        return x86Builtin(
            isFloating ? "blend\(precision)256" : "pblendd256",
            [
                (value: hi, type: blendType), (value: lo, type: blendType),
                (value: x86Immediate(control), type: "int"),
            ],
            returning: vector
        )
    case .upperUpper:
        return permuted(0x31)
    }
}

func x86Avx2LoadBlocks(channels: Int, for element: Element) -> [String] {
    let vector = x86Vector(x86Avx2NativeSuffix(of: element))
    let names = ["v10", "v32", "v54", "v76"].prefix(channels)
    let loads = names.enumerated().map { index, name in
        "__builtin_memcpy(&\(name), from + \(index * element.laneCount), sizeof \(name));"
    }
    func block(_ name: String, _ concat: X86Avx2ConcatKind, hi: String, lo: String) -> String {
        "const \(vector) \(name) = \(x86Avx2Concat(concat, hi: hi, lo: lo, for: element));"
    }
    let blocks =
        channels == 3
        ? [
            block("vA", .upperLower, hi: "v32", lo: "v10"),
            block("vB", .lowerUpper, hi: "v54", lo: "v10"),
            block("vC", .upperLower, hi: "v54", lo: "v32"),
        ]
        : [
            block("vA", .lowerLower, hi: "v54", lo: "v10"),
            block("vB", .upperUpper, hi: "v54", lo: "v10"),
            block("vC", .lowerLower, hi: "v76", lo: "v32"),
            block("vD", .upperUpper, hi: "v76", lo: "v32"),
        ]
    return ["\(vector) \(names.joined(separator: ", "));"] + loads + blocks
}

func x86Avx2LoadInterleaved(
    _ shuffles: [String],
    channels: Int,
    for element: Element
) -> String {
    let stores = (0..<channels).map { channel in
        outVectorStore(channel, of: "(\(element.cVector))r\(channel)", for: element)
    }
    let statements = x86Avx2LoadBlocks(channels: channels, for: element) + shuffles + stores
    return statements.joined(separator: "\n")
}

func x86Avx2StoreBlocks(channels: Int, for element: Element) -> [String] {
    let vector = x86Vector(x86Avx2NativeSuffix(of: element))
    func block(_ name: String, _ concat: X86Avx2ConcatKind, hi: String, lo: String) -> String {
        "const \(vector) \(name) = \(x86Avx2Concat(concat, hi: hi, lo: lo, for: element));"
    }
    func store(_ index: Int) -> String {
        "__builtin_memcpy(to + \(index * element.laneCount), &out\(index), sizeof out\(index));"
    }
    switch channels {
    case 2:
        return [
            block("out0", .lowerLower, hi: "vB", lo: "vA"),
            block("out1", .upperUpper, hi: "vB", lo: "vA"),
            store(0), store(1),
        ]
    case 3:
        return [
            block("out0", .lowerLower, hi: "vB", lo: "vA"),
            block("out1", .upperLower, hi: "vA", lo: "vC"),
            block("out2", .upperUpper, hi: "vC", lo: "vB"),
            store(0), store(1), store(2),
        ]
    default:
        return [
            block("out0", .lowerLower, hi: "vB", lo: "vA"),
            block("out1", .lowerLower, hi: "vD", lo: "vC"),
            store(0), store(1),
            block("out2", .upperUpper, hi: "vB", lo: "vA"),
            block("out3", .upperUpper, hi: "vD", lo: "vC"),
            store(2), store(3),
        ]
    }
}

func x86Avx2StoreInterleaved(
    _ shuffles: [String],
    channels: Int,
    for element: Element
) -> String {
    (shuffles + x86Avx2StoreBlocks(channels: channels, for: element)).joined(separator: "\n")
}

func x86Avx2LoadInterleaved2(for element: Element) -> String {
    let native = x86Vector(x86Avx2NativeSuffix(of: element))
    let i64 = x86Vector("i64")
    let loads = """
        \(native) first, second;
        __builtin_memcpy(&first, from, sizeof first);
        __builtin_memcpy(&second, from + \(element.laneCount), sizeof second);
        """
    func permuted(_ operand: String) -> String {
        guard element.category == .float && element.bits == 64 else {
            return x86Builtin(
                "permdi256",
                [(value: operand, type: i64), (value: "0xD8", type: "int")],
                returning: element.cVector
            )
        }
        return x86Builtin(
            "permdf256",
            [(value: operand, type: native), (value: "0xD8", type: "int")],
            returning: element.cVector
        )
    }
    let statements: [String]
    switch element.bits {
    case 8, 16:
        let wide = x86Vector("i\(2 * element.bits)")
        let mask = splat(element.bits == 8 ? "255" : "65535", as: wide, lanes: 128 / element.bits)
        let pack = element.bits == 8 ? "packuswb256" : "packusdw256"
        func packed(_ low: String, _ high: String) -> String {
            permuted(x86Builtin(pack, [low, high], as: "i\(2 * element.bits)", returning: i64))
        }
        func shiftedRight(_ operand: String) -> String {
            x86ImmediateShift(
                "psrl",
                operand,
                by: "\(element.bits)",
                laneBits: 2 * element.bits,
                width: 32,
                returning: wide
            )
        }
        statements = [
            "const \(wide) evenLow = (\(wide))first & \(mask);",
            "const \(wide) evenHigh = (\(wide))second & \(mask);",
            "const \(element.cVector) out0 = \(packed("evenLow", "evenHigh"));",
            "const \(wide) oddHigh = \(shiftedRight("second"));",
            "const \(wide) oddLow = \(shiftedRight("first"));",
            "const \(element.cVector) out1 = \(packed("oddLow", "oddHigh"));",
        ]
    default:
        let shuffle = element.bits == 32 ? "shufps256" : "shufpd256"
        let shuffleType = x86Vector("f\(element.bits)")
        let controls = element.bits == 32 ? ["0x88", "0xDD"] : ["0", "0xF"]
        func gathered(_ control: String) -> String {
            x86Builtin(
                shuffle,
                [
                    (value: "first", type: shuffleType), (value: "second", type: shuffleType),
                    (value: control, type: "int"),
                ],
                returning: shuffleType
            )
        }
        statements = [
            "const \(shuffleType) evens = \(gathered(controls[0]));",
            "const \(element.cVector) out0 = \(permuted("evens"));",
            "const \(shuffleType) odds = \(gathered(controls[1]));",
            "const \(element.cVector) out1 = \(permuted("odds"));",
        ]
    }
    let stores = (0..<2).map { outVectorStore($0, from: "out\($0)") }
    return ([loads] + statements + stores).joined(separator: "\n")
}

func x86Avx2OddEven(
    _ name: String,
    odd: String,
    even: String,
    for element: Element
) -> String {
    let native = x86Vector(x86Avx2NativeSuffix(of: element))
    let isFloating = element.category == .float
    let (builtin, control) =
        switch (isFloating, element.bits) {
        case (true, 64): ("blendpd256", 5)
        case (true, _): ("blendps256", 0x55)
        case (false, 64): ("pblendd256", 0x33)
        default: ("pblendd256", 0x55)
        }
    let blendType = x86Vector(isFloating ? element.cSuffix : "i32")
    let blended = x86Builtin(
        builtin,
        [
            (value: odd, type: blendType), (value: even, type: blendType),
            (value: x86Immediate(control), type: "int"),
        ],
        returning: native
    )
    return "const \(native) \(name) = \(blended);"
}

func x86Avx2ByteShiftedRight(
    _ name: String,
    _ source: String,
    bytes: Int,
    for element: Element
) -> String {
    let native = x86Vector(x86Avx2NativeSuffix(of: element))
    let shifted = "__builtin_ia32_psrldqi256_byteshift((\(x86Vector("i64")))\(source), \(bytes))"
    return "const \(native) \(name) = (\(native))\(shifted);"
}

func x86Avx2TableLookupBytes(_ bytes: String, _ indices: String, into result: String) -> String {
    let type = x86Vector("i64")
    let lookup = x86Builtin("pshufb256", [bytes, indices], as: "i8", returning: type)
    return "const \(type) \(result) = \(lookup);"
}

func x86Avx2LoadInterleaved3Lookups(for element: Element) -> String {
    let blocks = ["vA", "vB", "vC"]
    let channels = x86LoadInterleaved3Tables(for: element)
    let tables = channels.flatMap { $0 }.map {
        x86ByteTable("idx\(uppercasedFirst($0.name))", $0.table + $0.table)
    }
    let lookups = channels.flatMap { channel in
        channel.enumerated().map { block, part in
            x86Avx2TableLookupBytes(
                blocks[block],
                "idx\(uppercasedFirst(part.name))",
                into: part.name
            )
        }
    }
    let combines = channels.indices.map { channel in
        let names = channels[channel].map(\.name)
        let combined = "\(names[0]) ^ (\(names[1]) ^ \(names[2]))"
        return outVectorStore(channel, of: "(\(element.cVector))(\(combined))", for: element)
    }
    return (x86Avx2LoadBlocks(channels: 3, for: element) + tables + lookups + combines)
        .joined(separator: "\n")
}

func x86Avx2LoadInterleaved3Shuffles(for element: Element) -> [String] {
    func oddEven(_ name: String, odd: String, even: String) -> String {
        x86Avx2OddEven(name, odd: odd, even: even, for: element)
    }
    guard element.bits == 32 else {
        let native = x86Vector(x86Avx2NativeSuffix(of: element))
        let i8 = x86Vector("i8")
        let aligned = x86Builtin(
            "palignr256",
            [(value: "vC", type: i8), (value: "vA", type: i8), (value: "8", type: "int")],
            returning: native
        )
        return [
            oddEven("r0", odd: "vB", even: "vA"),
            "const \(native) r1 = \(aligned);",
            oddEven("r2", odd: "vC", even: "vB"),
        ]
    }
    let f32 = x86Vector("f32")
    func shuffled(_ name: String, _ first: String, _ second: String, control: Int) -> String {
        let shuffle = x86Builtin(
            "shufps256",
            [
                (value: first, type: f32), (value: second, type: f32),
                (value: x86Immediate(control), type: "int"),
            ],
            returning: f32
        )
        return "const \(f32) \(name) = \(shuffle);"
    }
    return [
        oddEven("vxx0203xx", odd: "vC", even: "vB"),
        shuffled("r0", "vA", "vxx0203xx", control: 0x6C),
        oddEven("vxxxx1011", odd: "vA", even: "vB"),
        oddEven("v1213xxxx", odd: "vB", even: "vC"),
        shuffled("r1", "vxxxx1011", "v1213xxxx", control: 0xB1),
        oddEven("vxx2021xx", odd: "vB", even: "vA"),
        shuffled("r2", "vxx2021xx", "vC", control: 0xC6),
    ]
}

func x86Avx2StoreInterleaved3Lookups(for element: Element) -> String {
    let tables = x86StoreInterleaved3Tables(for: element)
    let blocks = ["A", "B", "C"]
    let inputs = ["a", "b", "c"]
    let declarations = zip(blocks, tables).flatMap { block, group in
        group.enumerated().map { index, table in
            x86ByteTable("shuf\(block)\(index)", table + table)
        }
    }
    let statements = blocks.flatMap { block in
        let lookups = inputs.indices.map { index in
            x86Avx2TableLookupBytes(
                inputs[index],
                "shuf\(block)\(index)",
                into: "v\(block)\(index)"
            )
        }
        let combined =
            "const \(element.cVector) v\(block) = (\(element.cVector))(v\(block)0 | v\(block)1 | v\(block)2);"
        return lookups + [combined]
    }
    return (declarations + statements + x86Avx2StoreBlocks(channels: 3, for: element))
        .joined(separator: "\n")
}

func x86Avx2StoreInterleaved3Shuffles(for element: Element) -> [String] {
    func oddEven(_ name: String, odd: String, even: String) -> String {
        x86Avx2OddEven(name, odd: odd, even: even, for: element)
    }
    func shuffles(_ steps: [ShuffleStep]) -> [String] {
        x86Shuffles(steps, opaqueCasts: true, for: element)
    }
    guard element.bits == 32 else {
        return shuffles([.lower("vA", "a", "b", laneBits: 64)])
            + [oddEven("vB", odd: "a", even: "c")]
            + shuffles([.upper("vC", "b", "c", laneBits: 64)])
    }
    let isFloating = element.category == .float
    return shuffles([.lower("v10v00", "a", "b", laneBits: 32)])
        + [oddEven("v01v20", odd: "a", even: "c")]
        + shuffles([.lower("vA", "v10v00", "v01v20", laneBits: 64, isFloating: isFloating)])
        + [
            x86Avx2ByteShiftedRight("v1x321", "b", bytes: 4, for: element),
            x86Avx2ByteShiftedRight("v0x32", "a", bytes: 8, for: element),
            oddEven("v21v11", odd: "c", even: "v1x321"),
            oddEven("v12v02", odd: "v1x321", even: "v0x32"),
        ]
        + shuffles([
            .lower("vB", "v21v11", "v12v02", laneBits: 64, isFloating: isFloating),
            .upper("vC", "v01v20", "v21v11", laneBits: 64, isFloating: isFloating),
        ])
}

func x86ConstantOperandDispatch(
    _ operands: [String],
    constant: String,
    otherwise: String,
    for element: Element
) -> String {
    let condition = operands.map {
        "__builtin_constant_p(__builtin_reduce_or(\(unsignedBits($0, of: element))))"
    }.joined(separator: " || ")
    return """
        if (\(condition)) {
        \(indented(constant))
        } else {
        \(indented(otherwise))
        }
        """
}

func x86Avx2LoadInterleaved3(for element: Element) -> String {
    switch element.bits {
    case 8:
        return shuffleLoadInterleaved(channels: 3, for: element)
    case 16:
        return x86Avx2LoadInterleaved3Lookups(for: element)
    default:
        return x86Avx2LoadInterleaved(
            x86Avx2LoadInterleaved3Shuffles(for: element),
            channels: 3,
            for: element
        )
    }
}

func x86Avx2StoreInterleaved2(for element: Element) -> String {
    let blocks = x86Avx2StoreInterleaved(
        x86Shuffles(x86StoreInterleaved2Steps(for: element), opaqueCasts: true, for: element),
        channels: 2,
        for: element
    )
    guard element.bits < 64 else { return blocks }
    return x86ConstantOperandDispatch(
        element.category == .float ? ["b"] : ["a", "b"],
        constant: shuffleStoreInterleaved(channels: 2, for: element),
        otherwise: blocks,
        for: element
    )
}

func x86Avx2StoreInterleaved3(for element: Element) -> String {
    switch element.bits {
    case 8:
        return x86ConstantOperandDispatch(
            ["a", "b", "c"],
            constant: x86Avx2StoreInterleaved3Lookups(for: element),
            otherwise: shuffleStoreInterleaved(channels: 3, for: element),
            for: element
        )
    case 16:
        return x86Avx2StoreInterleaved3Lookups(for: element)
    default:
        return x86Avx2StoreInterleaved(
            x86Avx2StoreInterleaved3Shuffles(for: element),
            channels: 3,
            for: element
        )
    }
}

func x86Avx2StoreInterleaved4(for element: Element) -> String {
    let blocks = x86Avx2StoreInterleaved(
        x86Shuffles(x86StoreInterleaved4Steps(for: element), opaqueCasts: true, for: element),
        channels: 4,
        for: element
    )
    switch element.bits {
    case 8:
        return x86ConstantOperandDispatch(
            ["a", "b", "c", "d"],
            constant: shuffleStoreInterleaved(channels: 4, for: element),
            otherwise: blocks,
            for: element
        )
    case 64:
        return shuffleStoreInterleaved(channels: 4, for: element)
    default:
        return blocks
    }
}

func x86ImmediateShift(
    _ instruction: String,
    _ operand: String,
    by amount: String,
    laneBits: Int,
    width: Int = 16,
    returning type: String
) -> String {
    let name = x86ShiftName(instruction, laneBits: laneBits)
    let vector = x86Vector("i\(laneBits)")
    return "(\(type))__builtin_ia32_\(name)i\(x86Bits(width))((\(vector))\(operand), \(amount))"
}

func x86LoadInterleaved2(level: X86Level, for element: Element) -> String {
    let i8 = x86Vector("i8")
    let i16 = x86Vector("i16")
    let i32 = x86Vector("i32")
    let i64 = x86Vector("i64")
    let vector = element.cVector
    let loads = """
        \(i64) first, second;
        __builtin_memcpy(&first, from, sizeof first);
        __builtin_memcpy(&second, from + \(element.laneCount), sizeof second);
        """
    guard element.bits == 8 else {
        func shiftedRight(_ operand: String) -> String {
            x86ImmediateShift("psra", operand, by: "16", laneBits: 32, returning: i32)
        }
        let evens: String
        if level >= .sse4 {
            let mask = splat("0xFFFF", as: i32, lanes: 4)
            let packed = x86Builtin(
                "packusdw128",
                ["evenLow", "evenHigh"],
                as: "i32",
                returning: vector
            )
            evens = """
                const \(i32) evenLow = (\(i32))first & \(mask);
                const \(i32) evenHigh = (\(i32))second & \(mask);
                \(outVectorStore(0, of: packed, for: element))
                """
        } else if level >= .ssse3 {
            let table =
                [0x00, 0x01, 0x04, 0x05, 0x08, 0x09, 0x0C, 0x0D] + Array(repeating: 0, count: 8)
            let lookup: (String) -> String = {
                x86Builtin("pshufb128", [$0, "shuffle"], as: "i8", returning: i8)
            }
            let gathered = """
                (\(vector))__builtin_shufflevector(
                  (\(i64))evenLow, (\(i64))evenHigh, 0, 2)
                """
            evens = """
                const \(i8) shuffle = \(compoundLiteral(i8, table.map(String.init)));
                const \(i8) evenLow = \(lookup("first"));
                const \(i8) evenHigh = \(lookup("second"));
                \(outVectorStore(0, of: gathered, for: element))
                """
        } else {
            let packed = x86Builtin(
                "packssdw128",
                ["evenLow", "evenHigh"],
                as: "i32",
                returning: vector
            )
            let shiftedLeft: (String) -> String = {
                x86ImmediateShift("psll", $0, by: "16", laneBits: 32, returning: i32)
            }
            evens = """
                const \(i32) shiftedHigh = \(shiftedLeft("second"));
                const \(i32) shiftedLow = \(shiftedLeft("first"));
                const \(i32) evenHigh = \(shiftedRight("shiftedHigh"));
                const \(i32) evenLow = \(shiftedRight("shiftedLow"));
                \(outVectorStore(0, of: packed, for: element))
                """
        }
        let packed = x86Builtin("packssdw128", ["oddLow", "oddHigh"], as: "i32", returning: vector)
        return """
            \(loads)
            \(evens)
            const \(i32) oddHigh = \(shiftedRight("second"));
            const \(i32) oddLow = \(shiftedRight("first"));
            \(outVectorStore(1, of: packed, for: element))
            """
    }
    func shiftedRight(_ operand: String) -> String {
        x86ImmediateShift("psrl", operand, by: "8", laneBits: 16, returning: i16)
    }
    let mask = splat("255", as: i16, lanes: 8)
    let evens = x86Builtin("packuswb128", ["evenLow", "evenHigh"], as: "i16", returning: vector)
    let odds = x86Builtin("packuswb128", ["oddLow", "oddHigh"], as: "i16", returning: vector)
    return """
        \(loads)
        const \(i16) evenLow = (\(i16))first & \(mask);
        const \(i16) evenHigh = (\(i16))second & \(mask);
        \(outVectorStore(0, of: evens, for: element))
        const \(i16) oddHigh = \(shiftedRight("second"));
        const \(i16) oddLow = \(shiftedRight("first"));
        \(outVectorStore(1, of: odds, for: element))
        """
}

func x86LoadInterleaved3Tables(for element: Element) -> [[(name: String, table: [UInt8])]] {
    let laneBytes = element.bits / 8
    let blockLanes = 16 / laneBytes
    let parts = ["L", "M", "U"]
    return (0..<3).map { channel in
        parts.indices.map { block -> (name: String, table: [UInt8]) in
            let table = (0..<16).map { byte -> UInt8 in
                let position = 3 * (byte / laneBytes) + channel
                guard position / blockLanes == block else { return zeroedByte }
                return UInt8((position % blockLanes) * laneBytes + byte % laneBytes)
            }
            return ("v\(channel)\(parts[block])", table)
        }
    }
}

func x86LoadInterleaved3Lookups(level: X86Level, for element: Element) -> String {
    let type = x86Vector("i8")
    let blocks = ["vA", "vB", "vC"]
    let laneBytes = element.bits / 8
    let blockLanes = 16 / laneBytes
    let loads = blocks.enumerated().map { index, name in
        "__builtin_memcpy(&\(name), from + \(blockLanes * index), sizeof \(name));"
    }
    let channels = x86LoadInterleaved3Tables(for: element)
    let tables = channels.flatMap { $0 }.map {
        x86ByteTable("idx\(uppercasedFirst($0.name))", $0.table)
    }
    let lookups = channels.flatMap { channel in
        channel.enumerated().map { block, part in
            x86TableLookupBytesOr0(
                blocks[block],
                "idx\(uppercasedFirst(part.name))",
                into: part.name,
                level: level
            )
        }
    }
    let combines = channels.indices.map { channel in
        let names = channels[channel].map(\.name)
        let combined = "\(names[0]) ^ (\(names[1]) ^ \(names[2]))"
        return outVectorStore(channel, of: "(\(element.cVector))(\(combined))", for: element)
    }
    let blockType = level < .ssse3 ? x86Vector("i64") : type
    let declaration = "\(blockType) \(blocks.joined(separator: ", "));"
    return ([declaration] + loads + tables + lookups + combines).joined(separator: "\n")
}

let zeroedByte: UInt8 = 0x80

func addingToBytes(_ table: [UInt8], _ amount: Int) -> [UInt8] {
    table.map { $0 &+ UInt8(amount) }
}

func combiningShiftRightBytes(_ high: [UInt8], _ low: [UInt8], by count: Int) -> [UInt8] {
    Array((low + high)[count..<count + 16])
}

func x86StoreInterleaved3Tables(for element: Element) -> [[[UInt8]]] {
    let z = zeroedByte
    guard element.bits == 8 else {
        let first: [UInt8] = [z, z, 0, 1, z, z, z, z, 2, 3, z, z, z, z, 4, 5]
        let second: [UInt8] = [z, z, z, z, 0, 1, z, z, z, z, 2, 3, z, z, z, z]
        let third = combiningShiftRightBytes(first, first, by: 2)
        let middle = [addingToBytes(first, 6), addingToBytes(second, 6), addingToBytes(third, 4)]
        let last = [
            addingToBytes(middle[1], 6), addingToBytes(middle[2], 6), addingToBytes(middle[0], 4),
        ]
        return [[third, first, second], middle, last]
    }
    let first: [UInt8] = [0, z, z, 1, z, z, 2, z, z, 3, z, z, 4, z, z, 5]
    let second: [UInt8] = [z, 0, z, z, 1, z, z, 2, z, z, 3, z, z, 4, z, z]
    let third = combiningShiftRightBytes(second, second, by: 15)
    let middle = [addingToBytes(third, 6), addingToBytes(first, 5), addingToBytes(second, 5)]
    let last = [
        addingToBytes(middle[2], 6), addingToBytes(middle[0], 5), addingToBytes(middle[1], 5),
    ]
    return [[first, second, third], middle, last]
}

func x86ByteTable(_ name: String, _ table: [UInt8]) -> String {
    let values = table.map { String(Int8(bitPattern: $0)) }
    return "const \(x86Vector("i8")) \(name) = {\(values.joined(separator: ", "))};"
}

func x86TableLookupBytesOr0(
    _ bytes: String,
    _ indices: String,
    into result: String,
    level: X86Level
) -> String {
    let type = x86Vector("i8")
    guard level < .ssse3 else {
        let lookup = x86Builtin("pshufb128", [bytes, indices], as: "i8", returning: type)
        return "const \(type) \(result) = \(lookup);"
    }
    let zero = compoundLiteral(type, ["0"])
    let wide = x86Vector("i64")
    return """
        const \(type) \(result)Zeroed = \(zero) > \(indices);
        \(x86EmulatedTableLookupBytes(bytes, indices, into: "\(result)Looked"))
        const \(wide) \(result) = ~(\(wide))\(result)Zeroed & \(result)Looked;
        """
}

func x86EmulatedTableLookupBytes(
    _ bytes: String,
    _ indices: String,
    into result: String
) -> String {
    let type = x86Vector("i64")
    let lookup = """
        uint8_t resultBytes[16] __attribute__((aligned(16)));
        uint8_t tableBytes[16] __attribute__((aligned(16)));
        uint8_t indexBytes[16] __attribute__((aligned(16)));
        *(\(type)*)tableBytes = (\(type))\(bytes);
        *(\(type)*)indexBytes = (\(type))\(indices);
        for (int i = 0; i < 16; i++) {
          resultBytes[i] = tableBytes[indexBytes[i] & 15];
        }
        \(result) = *(\(type)*)resultBytes;
        """
    return "\(type) \(result);\n{\n\(indented(lookup))\n}"
}

func x86StoreInterleaved3Lookups(level: X86Level, for element: Element) -> String {
    let tables = x86StoreInterleaved3Tables(for: element)
    let blocks = ["A", "B", "C"]
    let inputs = ["a", "b", "c"]
    let declarations = zip(blocks, tables).flatMap { block, group in
        group.enumerated().map { index, table in x86ByteTable("shuf\(block)\(index)", table) }
    }
    let statements = blocks.flatMap { block in
        let lookups = inputs.indices.map { index in
            x86TableLookupBytesOr0(
                inputs[index],
                "shuf\(block)\(index)",
                into: "v\(block)\(index)",
                level: level
            )
        }
        let combined =
            "const \(element.cVector) v\(block) = (\(element.cVector))(v\(block)0 | v\(block)1 | v\(block)2);"
        return lookups + [combined]
    }
    let stores = ["vA", "vB", "vC"].enumerated().map { index, name in
        "__builtin_memcpy(to + \(index * element.laneCount), &\(name), sizeof \(name));"
    }
    return (declarations + statements + stores).joined(separator: "\n")
}

func laneIndices(_ indices: [Int]) -> String {
    indices.map(String.init).joined(separator: ", ")
}

func laneIndices(_ ranges: Range<Int>...) -> String {
    laneIndices(ranges.flatMap { $0 })
}

func unpackIndices(lanes: Int, upper: Bool, blocks: Int = 1) -> [Int] {
    let start = upper ? lanes / 2 : 0
    let total = lanes * blocks
    return (0..<blocks).flatMap { block in
        (start..<start + lanes / 2).flatMap { [block * lanes + $0, total + block * lanes + $0] }
    }
}

func indented(_ code: String) -> String {
    code.split(separator: "\n", omittingEmptySubsequences: false)
        .map { $0.isEmpty ? "" : "  \($0)" }
        .joined(separator: "\n")
}

func loadFirstCases(
    lanes: Int,
    of element: Element,
    in register: String? = nil,
    full: String = "__builtin_memcpy(&v, from, sizeof v);",
    single: String?,
    partial: String,
    finish: String
) -> String {
    let vector = register ?? element.cVector
    var lines = ["\(vector) v;", "if (count >= \(lanes)) {"]
    lines += [indented(full), "} else if (count == 0) {"]
    lines += [indented("v = (\(vector)){0};")]
    if let single {
        lines += ["} else if (count == 1) {", indented(single)]
    }
    lines += ["} else {", indented(partial), "}", finish]
    return lines.joined(separator: "\n")
}

func neonUnit(bytes: Int) -> (vector: String, scalar: String) {
    switch bytes {
    case 1: return ("byte_vector", "uint8_t")
    case 2: return ("short_vector", "uint16_t")
    default: return ("word_vector", "uint32_t")
    }
}

func neonWithTypedefs(_ code: String, for element: Element) -> String {
    var declarations = [
        (
            name: "half_vector",
            line: "typedef \(element.cType) half_vector __attribute__((vector_size(8)));"
        )
    ]
    for bytes in [1, 2, 4] {
        let unit = neonUnit(bytes: bytes)
        declarations.append(
            (
                name: unit.vector,
                line: "typedef \(unit.scalar) \(unit.vector) __attribute__((vector_size(8)));"
            )
        )
    }
    declarations.append((name: "zero", line: "const half_vector zero = {0};"))
    let used = declarations.filter { code.contains($0.name) }.map(\.line)
    return (used + [code]).joined(separator: "\n")
}

func neonDuplicatedLoad(
    _ scalar: String,
    into vector: String,
    bytes: Int,
    from pointer: String,
    for element: Element
) -> String {
    let isLane = bytes == element.bits / 8
    let unit = neonUnit(bytes: bytes)
    let values = Array(repeating: scalar, count: 8 / bytes).joined(separator: ", ")
    return """
        \(isLane ? element.cType : unit.scalar) \(scalar);
        __builtin_memcpy(&\(scalar), \(pointer), sizeof \(scalar));
        const \(isLane ? "half_vector" : unit.vector) \(vector) = {\(values)};
        """
}

func neonZipLow(_ low: String, _ high: String, unitBytes: Int, groupBytes: Int? = nil) -> String {
    let unit = neonUnit(bytes: unitBytes).vector
    let group = (groupBytes ?? unitBytes) / unitBytes
    let groups = unpackIndices(lanes: 8 / unitBytes / group, upper: false)
    let indices = laneIndices(groups.flatMap { group * $0..<group * $0 + group })
    return "(half_vector)__builtin_shufflevector((\(unit))\(low), (\(unit))\(high), \(indices))"
}

func neonConcatenation(_ low: String, _ high: String, for element: Element) -> String {
    "__builtin_shufflevector(\(low), \(high), \(laneIndices(0..<element.laneCount)))"
}

func neonKeepingFirst(
    _ count: Int,
    of operand: String,
    lanes: Int,
    type: String,
    for element: Element
) -> String {
    let zeros = Array(repeating: "0", count: lanes - count)
    guard element.category == .float else {
        let kept = Array(repeating: "(\(element.cType))-1", count: count)
        return "\(operand) & \(compoundLiteral(type, kept + zeros))"
    }
    let keptBytes = Array(repeating: "-1", count: count * element.bits / 8)
    let byteLanes = keptBytes + Array(repeating: "0", count: 16 - keptBytes.count)
    let bytes = neonVector("i8")
    return "(\(type))((\(bytes))\(operand) & \(compoundLiteral(bytes, byteLanes)))"
}

func neonLoadFirst(for element: Element) -> String {
    let vector = element.cVector
    let lanes = element.laneCount
    let size = element.bits / 8
    let halfLanes = 8 / size
    func load(_ scalar: String, into name: String, bytes: Int, at pointer: String) -> String {
        neonDuplicatedLoad(scalar, into: name, bytes: bytes, from: pointer, for: element)
    }
    func zip(_ low: String, _ high: String, unitBytes: Int, groupBytes: Int? = nil) -> String {
        neonZipLow(low, high, unitBytes: unitBytes, groupBytes: groupBytes)
    }
    func concatenation(_ low: String, _ high: String) -> String {
        neonConcatenation(low, high, for: element)
    }
    func cases(single: String?, partial: String) -> String {
        neonWithTypedefs(
            loadFirstCases(
                lanes: lanes,
                of: element,
                single: single,
                partial: partial,
                finish: vectorResult("v", for: element)
            ),
            for: element
        )
    }
    let first = neonKeepingFirst(1, of: "widened", lanes: lanes, type: vector, for: element)
    let single = """
        \(load("single", into: "duplicated", bytes: size, at: "from"))
        const \(vector) widened = \(concatenation("duplicated", "zero"));
        v = \(first);
        """
    switch lanes {
    case 2:
        let partial = """
            half_vector single;
            __builtin_memcpy(&single, from, sizeof single);
            v = \(concatenation("single", "zero"));
            """
        return cases(single: nil, partial: partial)
    case 4:
        let partial = """
            half_vector pair;
            __builtin_memcpy(&pair, from, sizeof pair);
            v = \(concatenation("pair", "zero"));
            if (count != 2) {
              v[2] = from[2];
            }
            """
        return cases(single: single, partial: partial)
    case 8:
        let pair = load("pair", into: "lower", bytes: 4, at: "from + leading")
        let third = load("third", into: "duplicated", bytes: 2, at: "from + leading + 2")
        let lone = load("single", into: "duplicated", bytes: 2, at: "from + leading")
        let kept = neonKeepingFirst(
            1,
            of: "duplicated",
            lanes: halfLanes,
            type: "half_vector",
            for: element
        )
        let partial = """
            const size_t leading = count & 4;
            half_vector trailing = zero;
            if (count & 2) {
            \(indented(pair))
              if (count & 1) {
            \(indented(indented(third)))
                const half_vector upper = \(zip("duplicated", "zero", unitBytes: 2));
                trailing = \(zip("lower", "upper", unitBytes: 4));
              } else {
                trailing = \(zip("lower", "zero", unitBytes: 4));
              }
            } else if (count & 1) {
            \(indented(lone))
              trailing = \(kept);
            }
            if (leading != 0) {
              half_vector head;
              __builtin_memcpy(&head, from, sizeof head);
              v = \(concatenation("head", "trailing"));
            } else {
              v = \(concatenation("trailing", "zero"));
            }
            """
        return cases(single: single, partial: partial)
    default:
        let pair = load("pair", into: "lower", bytes: 2, at: "from + leading")
        let third = load("third", into: "duplicated", bytes: 1, at: "from + leading + 2")
        let lone = load("single", into: "duplicated", bytes: 1, at: "from + leading")
        let middle = load("bits", into: "lower", bytes: 4, at: "from + 8")
        let head = load("bits", into: "lower", bytes: 4, at: "from")
        let kept = neonKeepingFirst(
            1,
            of: "duplicated",
            lanes: halfLanes,
            type: "half_vector",
            for: element
        )
        let firstFour = neonKeepingFirst(4, of: "widened", lanes: lanes, type: vector, for: element)
        let partial = """
            const size_t leading = count & 12;
            half_vector trailing = zero;
            if (count & 2) {
            \(indented(pair))
              if (count & 1) {
            \(indented(indented(third)))
                const half_vector upper = \(zip("duplicated", "zero", unitBytes: 1));
                trailing = \(zip("lower", "upper", unitBytes: 2));
              } else {
                trailing = \(zip("lower", "zero", unitBytes: 1, groupBytes: 2));
              }
            } else if (count & 1) {
            \(indented(lone))
              trailing = \(kept);
            }
            if (leading != 0) {
              if (leading >= 8) {
                half_vector upper;
                if (leading & 4) {
            \(indented(indented(indented(middle))))
                  upper = \(zip("lower", "trailing", unitBytes: 4));
                } else {
                  upper = \(zip("trailing", "zero", unitBytes: 4));
                }
                half_vector lower;
                __builtin_memcpy(&lower, from, sizeof lower);
                v = \(concatenation("lower", "upper"));
              } else {
            \(indented(indented(head)))
                const half_vector combined = \(zip("lower", "trailing", unitBytes: 4));
                v = \(concatenation("combined", "zero"));
              }
            } else {
              const \(vector) widened = \(concatenation("trailing", "zero"));
              v = \(firstFour);
            }
            """
        return cases(single: single, partial: partial)
    }
}

func neonWideningConversion(_ operand: String, from narrow: Element, to wide: Element) -> String {
    guard convertsFloatToInteger(from: narrow, to: wide) else {
        return "__builtin_convertvector(\(operand), \(wide.cVector))"
    }
    let floats = "__builtin_convertvector(\(operand), \(neonVector("f64")))"
    return "(\(wide.cVector))\(neonConvertedToInteger(floats, wide))"
}

func neonWidening(from narrow: Element, to wide: Element) -> String? {
    guard convertsFloatToInteger(from: narrow, to: wide) else { return nil }
    return """
        \(wideningLoad(takesCount: false, from: narrow, to: wide))
        \(vectorResult(neonWideningConversion("v", from: narrow, to: wide), for: wide))
        """
}

func neonLoadFirstWidening(from narrow: Element, to wide: Element) -> String {
    let lanes = wide.laneCount
    let size = narrow.bits / 8
    let bytes = lanes * size
    func load(_ scalar: String, into name: String, bytes: Int, at pointer: String) -> String {
        neonDuplicatedLoad(scalar, into: name, bytes: bytes, from: pointer, for: narrow)
    }
    func zip(_ low: String, _ high: String, unitBytes: Int, groupBytes: Int? = nil) -> String {
        neonZipLow(low, high, unitBytes: unitBytes, groupBytes: groupBytes)
    }
    let kept = neonKeepingFirst(
        1,
        of: "duplicated",
        lanes: 8 / size,
        type: "half_vector",
        for: narrow
    )
    let full: String
    if bytes == 8 {
        full = "__builtin_memcpy(&v, from, sizeof v);"
    } else {
        full = """
            \(load("bits", into: "duplicated", bytes: bytes, at: "from"))
            v = (half_vector)duplicated;
            """
    }
    let single = """
        \(load("single", into: "duplicated", bytes: size, at: "from"))
        v = \(kept);
        """
    let partial: String
    switch lanes {
    case 2:
        partial = """
            \(load("single", into: "duplicated", bytes: size, at: "from"))
            v = \(zip("duplicated", "zero", unitBytes: size));
            """
    case 4:
        partial = """
            \(load("pair", into: "duplicated", bytes: 2 * size, at: "from"))
            v = \(zip("duplicated", "zero", unitBytes: 2 * size));
            if (count != 2) {
              v[2] = from[2];
            }
            """
    default:
        let pair = load("pair", into: "lower", bytes: 2, at: "from + leading")
        let third = load("third", into: "duplicated", bytes: 1, at: "from + leading + 2")
        let lone = load("single", into: "duplicated", bytes: 1, at: "from + leading")
        let head = load("bits", into: "lower", bytes: 4, at: "from")
        partial = """
            const size_t leading = count & 4;
            half_vector trailing = zero;
            if (count & 2) {
            \(indented(pair))
              if (count & 1) {
            \(indented(indented(third)))
                const half_vector upper = \(zip("duplicated", "zero", unitBytes: 1));
                trailing = \(zip("lower", "upper", unitBytes: 2));
              } else {
                trailing = \(zip("lower", "zero", unitBytes: 1, groupBytes: 2));
              }
            } else if (count & 1) {
            \(indented(lone))
              trailing = \(kept);
            }
            if (leading != 0) {
            \(indented(head))
              v = \(zip("lower", "trailing", unitBytes: 4));
            } else {
              v = \(zip("trailing", "zero", unitBytes: 4));
            }
            """
    }
    let low = bytes == 8 ? "v" : "__builtin_shufflevector(v, v, \(laneIndices(0..<lanes)))"
    let converted = neonWideningConversion(low, from: narrow, to: wide)
    return neonWithTypedefs(
        loadFirstCases(
            lanes: lanes,
            of: narrow,
            in: "half_vector",
            full: full,
            single: lanes == 2 ? nil : single,
            partial: partial,
            finish: vectorResult(converted, for: wide)
        ),
        for: narrow
    )
}

func x86PartialName(_ operation: String, bytes: Int, floatBits: Int? = nil) -> String {
    let suffix = floatBits.map { "_f\($0)" } ?? ""
    return "cvectorization_ops_x86_\(operation)_\(bytes)_bytes\(suffix)"
}

func x86PartialName(_ operation: String, bytes: Int, for element: Element) -> String {
    let floatBits = element.category == .float ? element.bits : nil
    return x86PartialName(operation, bytes: bytes, floatBits: floatBits)
}

func x86InterleaveLowerName(bits: Int) -> String {
    "cvectorization_ops_x86_interleave_lower_i\(bits)"
}

func x86InsertLaneName(_ lane: Int, for element: Element) -> String {
    "cvectorization_ops_x86_insert_lane_\(lane)_\(element.cSuffix)"
}

func x86PartialLoadHelpers() -> [String] {
    let i32 = x86Block("i32")
    let i64 = x86Block("i64")
    let f32 = x86Block("f32")
    let f64 = x86Block("f64")
    let words = [1, 2, 4].map { bytes in
        cFunction(
            returns: i64,
            name: x86PartialName("load", bytes: bytes),
            parameters: ["const void* from"],
            body: """
                int32_t bits = 0;
                __builtin_memcpy(&bits, from, \(bytes));
                return (\(i64))(\(i32)){bits, 0, 0, 0};
                """
        )
    }
    let long = cFunction(
        returns: i64,
        name: x86PartialName("load", bytes: 8),
        parameters: ["const void* from"],
        body: """
            long long bits;
            __builtin_memcpy(&bits, from, 8);
            return (\(i64)){bits, 0};
            """
    )
    let single = cFunction(
        returns: f32,
        name: x86PartialName("load", bytes: 4, floatBits: 32),
        parameters: ["const void* from"],
        body: """
            float value;
            __builtin_memcpy(&value, from, 4);
            return (\(f32)){value, 0, 0, 0};
            """
    )
    let pair = cFunction(
        returns: f32,
        name: x86PartialName("load", bytes: 8, floatBits: 32),
        parameters: ["const void* from"],
        body: """
            typedef float pair_vector __attribute__((vector_size(8)));
            pair_vector value;
            __builtin_memcpy(&value, from, 8);
            return __builtin_shufflevector(value, (pair_vector){0}, 0, 1, 2, 3);
            """
    )
    let lone = cFunction(
        returns: f64,
        name: x86PartialName("load", bytes: 8, floatBits: 64),
        parameters: ["const void* from"],
        body: """
            double value;
            __builtin_memcpy(&value, from, 8);
            return (\(f64)){value, 0};
            """
    )
    let wholes: [(floatBits: Int?, type: String)] = [(nil, i64), (32, f32), (64, f64)]
    let whole = wholes.map { floatBits, type in
        cFunction(
            returns: type,
            name: x86PartialName("load", bytes: 16, floatBits: floatBits),
            parameters: ["const void* from"],
            body: """
                \(type) value;
                __builtin_memcpy(&value, from, 16);
                return value;
                """
        )
    }
    return words + [long, single, pair, lone] + whole
}

func x86InterleaveLowerHelpers() -> [String] {
    let i64 = x86Block("i64")
    return [16, 32, 64].map { bits in
        let unit = x86Block("i\(bits)")
        let indices = laneIndices(unpackIndices(lanes: 128 / bits, upper: false))
        return cFunction(
            returns: i64,
            name: x86InterleaveLowerName(bits: bits),
            parameters: ["\(i64) low", "\(i64) high"],
            body: "return (\(i64))__builtin_shufflevector((\(unit))low, (\(unit))high, \(indices));"
        )
    }
}

func laneMask(_ lane: Int, for element: Element) -> String {
    var lanes = Array(repeating: "0", count: element.laneCount)
    lanes[lane] = "-1"
    return compoundLiteral(element.cMask, lanes)
}

func x86InsertLane(_ lane: Int, for element: Element) -> String {
    let vector = element.cVector
    let block = element.cBlock
    let inserted = """
        \(block) a = (\(block))rawA;
        a[\(lane)] = t;
        return (\(x86RawBlockType(of: element)))a;
        """
    let selected = x86BitSelect("selected", repeatingVector("t", of: element), "a", for: element)
    let blended = """
        const \(vector) a = (\(vector))rawA;
        const \(element.cMask) selected = \(laneMask(lane, for: element));
        \(vectorResult(selected, for: element))
        """
    let levels = TargetBodies<Element>(
        avx2: { _ in inserted },
        sse4: { _ in inserted },
        sse2: { _ in blended }
    )
    return cFunction(
        returns: x86RawBlockType(of: element),
        name: x86InsertLaneName(lane, for: element),
        parameters: ["\(x86RawBlockType(of: element)) rawA", "\(element.cType) t"],
        body: element.bits == 16 ? inserted : cBody(levels, for: element, portable: nil)
    )
}

func x86LoadFirstName(lanes: Int, for element: Element) -> String {
    "cvectorization_ops_x86_load_first_\(lanes)_\(element.cSuffix)"
}

func x86PartialLoadFirstLanes(of element: Element) -> [Int] {
    let wides = classicElements.filter { wide in
        wideningSources(of: wide).contains { $0.cSuffix == element.cSuffix }
    }
    return Set(wides.map { $0.at(width: element.width).laneCount }).sorted()
}

func x86LoadFirstHelperLanes(for element: Element) -> [Int] {
    let partialLanes = x86PartialLoadFirstLanes(of: element)
    guard element.width > 16 else { return partialLanes }
    return Set(partialLanes + [element.blockLaneCount]).sorted()
}

func x86LoadFirstHelpers(for element: Element) -> String? {
    let helperLanes = x86LoadFirstHelperLanes(for: element)
    let loadedLanes = element.width > 16 ? helperLanes : [element.laneCount] + helperLanes
    var helpers: [String] = []
    if loadedLanes.contains(4) {
        helpers.append(x86InsertLane(2, for: element))
    }
    helpers += helperLanes.map { lanes in
        cFunction(
            returns: x86RawBlockType(of: element),
            name: x86LoadFirstName(lanes: lanes, for: element),
            parameters: ["const \(element.cType)* from", "size_t count"],
            body: x86LoadFirst(lanes: lanes, for: element)
        )
    }
    return helpers.isEmpty ? nil : helpers.joined().trimmingCharacters(in: .newlines)
}

/// Highway's `LoadN`, with a call wherever Highway calls an op, so that LLVM simplifies each part
/// before inlining it the way it does Highway's. `StoreN`s follow the same structure.
func x86LoadFirstWide(for element: Element) -> String {
    let lanes = element.laneCount
    let halfLanes = element.blockLaneCount
    let block = element.cBlock
    let raw = x86RawBlockType(of: element)
    let half = x86LoadFirstName(lanes: halfLanes, for: element)
    let whole = x86PartialName("load", bytes: 16, for: element)
    let zero = "(\(block)){0}"
    let indices = laneIndices(0..<lanes)
    let extended = "__builtin_shufflevector((\(block))lower, \(zero), \(indices))"
    let combined = "__builtin_shufflevector((\(block))lower, (\(block))upper, \(indices))"
    return """
        if (count >= \(lanes)) {
          return \(cFunctionName("load", element))(from);
        }
        if (count <= \(halfLanes)) {
          const \(raw) lower = \(half)(from, count);
          \(vectorResult(extended, for: element))
        }
        const \(raw) lower = \(whole)(from);
        const \(raw) upper = \(half)(from + \(halfLanes), count - \(halfLanes));
        \(vectorResult(combined, for: element))
        """
}

func x86LoadFirst(lanes: Int, for element: Element) -> String {
    let size = element.bits / 8
    let raw = x86RawBlockType(of: element)
    let zero = "(\(raw)){0}"
    func load(_ lanes: Int, at pointer: String) -> String {
        "\(x86PartialName("load", bytes: lanes * size, for: element))(\(pointer))"
    }
    func interleaving(_ low: String, _ high: String, halfLanes: Int) -> String {
        "\(x86InterleaveLowerName(bits: 8 * halfLanes * size))(\(low), \(high))"
    }
    let head = """
        if (count >= \(lanes)) {
          return \(load(lanes, at: "from"));
        }
        if (count == 0) {
          return \(zero);
        }
        """
    guard lanes > 2 else {
        return "\(head)\nreturn \(load(1, at: "from"));"
    }
    let single = """
        \(head)
        if (count == 1) {
          return \(load(1, at: "from"));
        }
        """
    guard lanes > 4 else {
        let inserted = "\(x86InsertLaneName(2, for: element))(pair, from[2])"
        return """
            \(single)
            const \(raw) pair = \(load(2, at: "from"));
            return count == 2 ? pair : \(inserted);
            """
    }
    let third = load(1, at: "from + leading + 2")
    let trailing = """
        \(single)
        const size_t leading = count & \(lanes - 4);
        \(raw) trailing = \(zero);
        if (count & 2) {
          const \(raw) pair = \(load(2, at: "from + leading"));
          if (count & 1) {
            trailing = \(interleaving("pair", third, halfLanes: 2));
          } else {
            trailing = pair;
          }
        } else if (count & 1) {
          trailing = \(load(1, at: "from + leading"));
        }
        """
    guard lanes > 8 else {
        return """
            \(trailing)
            if (leading != 0) {
              return \(interleaving(load(4, at: "from"), "trailing", halfLanes: 4));
            }
            return trailing;
            """
    }
    let upper = interleaving(load(4, at: "from + 8"), "trailing", halfLanes: 4)
    return """
        \(trailing)
        if (leading != 0) {
          if (leading >= 8) {
            const \(raw) upper = (leading & 4) != 0 ? \(upper) : trailing;
            return \(interleaving(load(8, at: "from"), "upper", halfLanes: 8));
          }
          return \(interleaving(load(4, at: "from"), "trailing", halfLanes: 4));
        }
        return trailing;
        """
}

func neonHalfVector(of element: Element) -> String {
    "cvectorization_ops_neon_half_\(element.cSuffix)"
}

func neonHelperName(_ operation: String, bytes: Int? = nil, for element: Element) -> String {
    let size = bytes.map { "_\($0)_bytes" } ?? ""
    return "cvectorization_ops_neon_\(operation)\(size)_\(element.cSuffix)"
}

func neonStoreFirstName(lanes: Int, for element: Element) -> String {
    "cvectorization_ops_neon_store_first_\(lanes)_\(element.cSuffix)"
}

func neonPartialStore(bytes: Int, of vector: String = "v", for element: Element) -> String {
    switch bytes {
    case 8:
        return "__builtin_memcpy(to, &\(vector), sizeof \(vector));"
    case element.bits / 8:
        return "to[0] = \(vector)[0];"
    default:
        let unit = neonUnit(bytes: bytes)
        return """
            typedef \(unit.scalar) \(unit.vector) __attribute__((vector_size(8)));
            const \(unit.scalar) bits = ((\(unit.vector))\(vector))[0];
            __builtin_memcpy(to, &bits, sizeof bits);
            """
    }
}

func neonStoreFirstTree(lanes: Int, of vector: String, for element: Element) -> String {
    let size = element.bits / 8
    let isFullVector = lanes == element.laneCount
    let base = element.isHalfPrecision ? "((\(element.cType)*)to)" : "to"
    func half(_ part: String) -> String {
        isFullVector ? "\(neonHelperName("\(part)_half", for: element))(\(vector))" : vector
    }
    func store(_ lanes: Int, of source: String, at offset: Int = 0) -> String {
        let pointer = offset == 0 ? base : "\(base) + \(offset)"
        let function =
            lanes == element.laneCount
            ? cFunctionName("store", element)
            : neonHelperName("store", bytes: lanes * size, for: element)
        return "\(function)(\(source), \(pointer));"
    }
    func upperHalf(_ lanes: Int) -> String {
        guard !isFullVector else { return half("upper") }
        return "\(neonHelperName("upper_half", bytes: lanes * size, for: element))(\(vector))"
    }
    switch lanes {
    case 2:
        return """
            if (count > 1) {
              \(store(2, of: vector))
            } else if (count == 1) {
              \(store(1, of: half("lower")))
            }
            """
    case 4:
        return """
            if (count > 1) {
              if (count >= 4) {
                \(store(4, of: vector))
              } else {
                \(store(2, of: half("lower")))
                if (count == 3) {
                  \(store(1, of: upperHalf(2), at: 2))
                }
              }
            } else if (count == 1) {
              \(store(1, of: half("lower")))
            }
            """
    default:
        let next = neonStoreFirstName(lanes: lanes / 2, for: element)
        return """
            if (count <= 1) {
              if (count == 1) {
                \(store(1, of: half("lower")))
              }
            } else if (count >= \(lanes)) {
              \(store(lanes, of: vector))
            } else if (count >= \(lanes / 2)) {
              \(store(lanes / 2, of: half("lower")))
              \(next)(\(upperHalf(lanes / 2)), \(base) + \(lanes / 2), count - \(lanes / 2));
            } else {
              \(next)(\(half("lower")), \(base), count);
            }
            """
    }
}

func neonStoreFirstHelpers(for element: Element) -> String {
    let vector = element.cVector
    let half = neonHalfVector(of: element)
    let size = element.bits / 8
    let lanes = element.laneCount
    var helpers = ["typedef \(element.cType) \(half) __attribute__((vector_size(8)));\n"]
    var halves = [("lower", 0..<lanes / 2)]
    if lanes > 2 {
        halves.append(("upper", lanes / 2..<lanes))
    }
    helpers += halves.map { part, range in
        cFunction(
            returns: half,
            name: neonHelperName("\(part)_half", for: element),
            parameters: ["\(vector) v"],
            body: "return __builtin_shufflevector(v, v, \(laneIndices(range)));"
        )
    }
    let halfLevels = [4, 8].filter { $0 < lanes }
    helpers += halfLevels.map { level in
        let bytes = level / 2 * size
        return cFunction(
            returns: half,
            name: neonHelperName("upper_half", bytes: bytes, for: element),
            parameters: ["\(half) v"],
            body: """
                typedef uint8_t byte_vector __attribute__((vector_size(8)));
                const byte_vector zero = {0};
                return (\(half))__builtin_shufflevector((byte_vector)v, zero, \(laneIndices(bytes..<bytes + 8)));
                """
        )
    }
    helpers += [1, 2, 4, 8].filter { $0 >= size }.map { bytes in
        cFunction(
            returns: "void",
            name: neonHelperName("store", bytes: bytes, for: element),
            parameters: ["\(half) v", "\(element.cType)* to"],
            body: neonPartialStore(bytes: bytes, for: element)
        )
    }
    helpers += halfLevels.map { level in
        cFunction(
            returns: "void",
            name: neonStoreFirstName(lanes: level, for: element),
            parameters: ["\(half) v", "\(element.cType)* to", "size_t count"],
            body: neonStoreFirstTree(lanes: level, of: "v", for: element)
        )
    }
    return helpers.joined().trimmingCharacters(in: .newlines)
}

func neonStoreFirst(for element: Element) -> String {
    neonStoreFirstTree(lanes: element.laneCount, of: "a", for: element)
}

func x86StoreFirstName(lanes: Int, for element: Element) -> String {
    "cvectorization_ops_x86_store_first_\(lanes)_\(element.cSuffix)"
}

func x86PartialStoreHelpers() -> [String] {
    let i64 = x86Block("i64")
    let f32 = x86Block("f32")
    let f64 = x86Block("f64")
    let words = [1, 2, 4].map { bytes in
        cFunction(
            returns: "void",
            name: x86PartialName("store", bytes: bytes),
            parameters: ["\(i64) v", "void* to"],
            body: "__builtin_memcpy(to, &v, \(bytes));"
        )
    }
    let long = cFunction(
        returns: "void",
        name: x86PartialName("store", bytes: 8),
        parameters: ["\(i64) v", "void* to"],
        body: """
            const long long bits = v[0];
            __builtin_memcpy(to, &bits, sizeof bits);
            """
    )
    let single = cFunction(
        returns: "void",
        name: x86PartialName("store", bytes: 4, floatBits: 32),
        parameters: ["\(f32) v", "float* to"],
        body: "to[0] = v[0];"
    )
    let pair = cFunction(
        returns: "void",
        name: x86PartialName("store", bytes: 8, floatBits: 32),
        parameters: ["\(f32) v", "float* to"],
        body: """
            typedef float pair_vector __attribute__((vector_size(8)));
            const pair_vector bits = __builtin_shufflevector(v, v, 0, 1);
            __builtin_memcpy(to, &bits, sizeof bits);
            """
    )
    let lone = cFunction(
        returns: "void",
        name: x86PartialName("store", bytes: 8, floatBits: 64),
        parameters: ["\(f64) v", "double* to"],
        body: "to[0] = v[0];"
    )
    let wholes: [(floatBits: Int?, type: String)] = [(nil, i64), (32, f32), (64, f64)]
    let whole = wholes.map { floatBits, type in
        cFunction(
            returns: "void",
            name: x86PartialName("store", bytes: 16, floatBits: floatBits),
            parameters: ["\(type) v", "void* to"],
            body: "__builtin_memcpy(to, &v, 16);"
        )
    }
    return words + [long, single, pair, lone] + whole
}

func x86UpperHalfHelpers() -> [String] {
    let i8 = x86Block("i8")
    let i64 = x86Block("i64")
    let f32 = x86Block("f32")
    let shifted = [2, 4].map { bytes in
        let indices = laneIndices(bytes..<bytes + 16)
        return cFunction(
            returns: i64,
            name: x86PartialName("upper_half", bytes: bytes),
            parameters: ["\(i64) v"],
            body: "return (\(i64))__builtin_shufflevector((\(i8))v, (\(i8)){0}, \(indices));"
        )
    }
    let long = cFunction(
        returns: i64,
        name: x86PartialName("upper_half", bytes: 8),
        parameters: ["\(i64) v"],
        body: "return __builtin_shufflevector(v, v, 1, 3);"
    )
    let pair = cFunction(
        returns: f32,
        name: x86PartialName("upper_half", bytes: 8, floatBits: 32),
        parameters: ["\(f32) v"],
        body: "return __builtin_shufflevector(v, v, 6, 7, 2, 3);"
    )
    return shifted + [long, pair]
}

func x86StoreFirstTree(lanes: Int, of vector: String, for element: Element) -> String {
    let size = element.bits / 8
    func store(_ lanes: Int, of source: String, at offset: Int = 0) -> String {
        let pointer = offset == 0 ? "to" : "to + \(offset)"
        let function = x86PartialName("store", bytes: lanes * size, for: element)
        return "\(function)(\(source), \(pointer));"
    }
    func upperHalf(_ lanes: Int) -> String {
        "\(x86PartialName("upper_half", bytes: lanes * size, for: element))(\(vector))"
    }
    switch lanes {
    case 2:
        return """
            if (count > 1) {
              \(store(2, of: vector))
            } else if (count == 1) {
              \(store(1, of: vector))
            }
            """
    case 4:
        return """
            if (count > 1) {
              if (count >= 4) {
                \(store(4, of: vector))
              } else {
                \(store(2, of: vector))
                if (count == 3) {
                  \(store(1, of: upperHalf(2), at: 2))
                }
              }
            } else if (count == 1) {
              \(store(1, of: vector))
            }
            """
    default:
        let half = lanes / 2
        let next = x86StoreFirstName(lanes: half, for: element)
        return """
            if (count <= 1) {
              if (count == 1) {
                \(store(1, of: vector))
              }
            } else if (count >= \(lanes)) {
              \(store(lanes, of: vector))
            } else if (count >= \(half)) {
              \(store(half, of: vector))
              \(next)(\(upperHalf(half)), to + \(half), count - \(half));
            } else {
              \(next)(\(vector), to, count);
            }
            """
    }
}

func x86StoreFirstHelpers(for element: Element) -> String? {
    let raw = x86RawBlockType(of: element)
    let helpers = [4, 8].filter { $0 < element.laneCount }.map { lanes in
        cFunction(
            returns: "void",
            name: x86StoreFirstName(lanes: lanes, for: element),
            parameters: ["\(raw) v", "\(element.cType)* to", "size_t count"],
            body: x86StoreFirstTree(lanes: lanes, of: "v", for: element)
        )
    }
    return helpers.isEmpty ? nil : helpers.joined().trimmingCharacters(in: .newlines)
}

func x86MaskedStoreTypes(for element: Element) -> (name: String, value: String, mask: String) {
    switch (element.category, element.bits) {
    case (.float, 32): return ("maskstoreps256", "f32", "i32")
    case (.float, _): return ("maskstorepd256", "f64", "i64")
    case (_, 64): return ("maskstoreq256", "i64", "i64")
    default: return ("maskstored256", "i32", "i32")
    }
}

func x86StoreFirstTrailing(for element: Element) -> String {
    let size = element.bits / 8
    let words = "words[stored / \(4 / size)]"
    guard size == 1 else {
        return "to[stored - 1] = (\(element.cType))\(words);"
    }
    return """
        const uint32_t word = (uint32_t)\(words);
        if (stored & 2) {
          const uint16_t bits = (uint16_t)word;
          to[stored - 1] = (\(element.cType))(word >> 16);
          __builtin_memcpy(to + (stored & ~(size_t)3), &bits, sizeof bits);
        } else {
          to[stored - 1] = (\(element.cType))word;
        }
        """
}

func x86StoreFirstMasked(for element: Element) -> String {
    let types = x86MaskedStoreTypes(for: element)
    let store = x86Builtin(
        types.name,
        [
            (value: "to", type: "\(x86Vector(types.value))*"),
            (value: "mask", type: x86Vector(types.mask)),
            (value: "a", type: x86Vector(types.value)),
        ],
        returning: "void"
    )
    guard element.bits < 32 else {
        return "\(signedFirstLanesMask(for: element))\n\(store);"
    }
    let words = x86Vector("i32")
    let trailingLanes = 4 / (element.bits / 8) - 1
    return """
        const size_t stored = \(clampedCount(to: element.laneCount));
        const \(words) words = (\(words))a;
        \(signedFirstLanesMask(for: element))
        \(store);
        if ((stored & \(trailingLanes)) != 0) {
        \(indented(x86StoreFirstTrailing(for: element)))
        }
        """
}

func x86StoreFirst(for element: Element) -> String {
    let raw = x86RawType(of: element)
    return """
        const \(raw) v = (\(raw))a;
        \(x86StoreFirstTree(lanes: element.laneCount, of: "v", for: element))
        """
}

func x86Avx3LoadFirst(for element: Element) -> String {
    let lanes = element.laneCount
    let register = x86Vector(x86LaneSuffix(of: element))
    let loaded = x86Builtin(
        x86MaskedAccessName("load", width: element.width, for: element),
        [
            (
                value: "from",
                type: "const \(x86MaskedPointee(of: register, width: element.width, for: element))*"
            ),
            (value: compoundLiteral(register, ["0"]), type: register),
            (value: x86FirstLanesBits(lanes: lanes), type: x86MaskType(lanes: lanes)),
        ],
        returning: element.cVector
    )
    return vectorResult(loaded, for: element)
}

func x86Avx3StoreFirst(for element: Element) -> String {
    let lanes = element.laneCount
    let register = x86Vector(x86LaneSuffix(of: element))
    let store = x86Builtin(
        x86MaskedAccessName("store", width: element.width, for: element),
        [
            (
                value: "to",
                type: "\(x86MaskedPointee(of: register, width: element.width, for: element))*"
            ),
            (value: "a", type: register),
            (value: x86FirstLanesBits(lanes: lanes), type: x86MaskType(lanes: lanes)),
        ],
        returning: "void"
    )
    return "\(store);"
}

func x86Avx3WideningConversion(from narrow: Element, to wide: Element) -> String {
    guard convertsFloatToInteger(from: narrow, to: wide) else {
        return vectorResult("__builtin_convertvector(v, \(wide.cVector))", for: wide)
    }
    let isSigned = wide.category == .signedInteger
    let lanes = wide.laneCount
    let words = x86Vector("i64")
    let integers = vectorTypedef("integer_vector", lane: "int32_t", bits: 32, lanes: lanes)
    let name = "cvttps2\(isSigned ? "" : "u")qq512_mask"
    func truncated(_ operand: String) -> String {
        x86Builtin(
            name,
            [
                (value: operand, type: "narrow_vector"),
                (value: compoundLiteral(words, ["0"]), type: words),
                (value: "-1", type: x86MaskType(lanes: lanes)),
                (value: String(x86CurrentRounding), type: "int"),
            ],
            returning: words
        )
    }
    guard isSigned else {
        return """
            \(integers)
            const \(x86MaskType(lanes: lanes)) negative = __builtin_ia32_cvtd2mask256((integer_vector)v);
            const narrow_vector nonNegative = __builtin_ia32_selectps_256(negative, \(compoundLiteral("narrow_vector", ["0"])), v);
            \(vectorResult(truncated("nonNegative"), for: wide))
            """
    }
    let limit = splat("9.223372e18f", as: "narrow_vector", lanes: lanes)
    let overflow = x86Builtin(
        "cmpps256_mask",
        [
            (value: "v", type: "narrow_vector"),
            (value: limit, type: "narrow_vector"),
            (value: "29", type: "int"),
            (value: "-1", type: x86MaskType(lanes: lanes)),
        ],
        returning: x86MaskType(lanes: lanes)
    )
    let selected = x86Builtin(
        "selectq_512",
        [
            (value: "overflow", type: x86MaskType(lanes: lanes)),
            (value: splat("INT64_MAX", as: words, lanes: lanes), type: words),
            (value: "truncated", type: words),
        ],
        returning: wide.cVector
    )
    return """
        const \(x86MaskType(lanes: lanes)) overflow = \(overflow);
        const \(words) truncated = \(truncated("v"));
        \(vectorResult(selected, for: wide))
        """
}

func x86Avx3Widening(from narrow: Element, to wide: Element) -> String {
    let bytes = wide.laneCount * narrow.bits / 8
    return """
        typedef \(narrow.cType) narrow_vector __attribute__((vector_size(\(bytes))));
        narrow_vector v;
        __builtin_memcpy(&v, from, sizeof v);
        \(x86Avx3WideningConversion(from: narrow, to: wide))
        """
}

func x86Avx3LoadFirstWidening(from narrow: Element, to wide: Element) -> String {
    let lanes = wide.laneCount
    let bytes = lanes * narrow.bits / 8
    let registerBytes = max(bytes, 16)
    let register = "register_vector"
    let loaded = x86Builtin(
        x86MaskedAccessName("load", width: registerBytes, for: narrow),
        [
            (
                value: "from",
                type: "const \(x86MaskedPointee(of: register, width: registerBytes, for: narrow))*"
            ),
            (value: compoundLiteral(register, ["0"]), type: register),
            (
                value: x86FirstLanesBits(
                    lanes: lanes,
                    all: "0x\(String(UInt64.max >> (64 - lanes), radix: 16))ull"
                ),
                type: x86MaskType(lanes: registerBytes / (narrow.bits / 8))
            ),
        ],
        returning: register
    )
    return """
        typedef \(x86LaneType(of: narrow)) \(register) __attribute__((vector_size(\(registerBytes))));
        typedef \(narrow.cType) narrow_vector __attribute__((vector_size(\(bytes))));
        const \(register) loaded = \(loaded);
        narrow_vector v;
        __builtin_memcpy(&v, &loaded, sizeof v);
        \(x86Avx3WideningConversion(from: narrow, to: wide))
        """
}

func shuffleLoadInterleaved(channels: Int, for element: Element) -> String {
    let lanes = element.laneCount
    let splits = (0..<channels).map { channel in
        let indices = laneIndices((0..<lanes).map { channels * $0 + channel })
        let split = "__builtin_shufflevector(all, all, \(indices))"
        return """
            const \(element.cVector) r\(channel) = (\(element.cVector))\(split);
            \(outVectorStore(channel))
            """
    }
    return """
        typedef \(element.cUnsignedLane) wide_vector __attribute__((vector_size(\(element.width * channels))));
        wide_vector all;
        __builtin_memcpy(&all, from, \(element.width * channels));
        \(splits.joined(separator: "\n"))
        """
}

func shuffleStoreInterleaved(channels: Int, for element: Element) -> String {
    let lanes = element.laneCount
    let type = element.cUnsignedLane
    let inputs = ["a", "b", "c", "d"].prefix(channels).map { unsignedBits($0, of: element) }
    let both = laneIndices(0..<2 * lanes)
    let single = laneIndices(Array(0..<lanes) + Array(repeating: -1, count: lanes))
    let interleaved = laneIndices(
        (0..<lanes).flatMap { lane in (0..<channels).map { $0 * lanes + lane } }
    )
    let wideBytes = element.width * channels
    let wide = "typedef \(type) wide_vector __attribute__((vector_size(\(wideBytes))));"
    let pair = "typedef \(type) pair_vector __attribute__((vector_size(\(2 * element.width))));"
    let shuffle = "__builtin_shufflevector"
    var statements: [String]
    let operands: String
    switch channels {
    case 2:
        statements = [wide]
        operands = "\(inputs[0]), \(inputs[1])"
    case 3:
        statements = [
            pair, wide,
            "const pair_vector ab = \(shuffle)(\(inputs[0]), \(inputs[1]), \(both));",
            "const pair_vector cc = \(shuffle)(\(inputs[2]), \(inputs[2]), \(single));",
        ]
        operands = "ab, cc"
    default:
        statements = [
            pair, wide,
            "const pair_vector ab = \(shuffle)(\(inputs[0]), \(inputs[1]), \(both));",
            "const pair_vector cd = \(shuffle)(\(inputs[2]), \(inputs[3]), \(both));",
        ]
        operands = "ab, cd"
    }
    statements.append("const wide_vector all = \(shuffle)(\(operands), \(interleaved));")
    statements.append("__builtin_memcpy(to, &all, \(element.width * channels));")
    return statements.joined(separator: "\n")
}

func x86Avx3Permutation(_ letters: String) -> Int {
    let blocks = Array("ABCD")
    return letters.reduce(0) { $0 * 4 + blocks.firstIndex(of: $1)! }
}

func x86Avx3Shuffle128(
    _ name: String,
    _ first: String,
    _ second: String,
    permutation: String,
    for element: Element
) -> String {
    let (builtin, suffix) =
        switch (element.category, element.bits) {
        case (.float, 32): ("shuf_f32x4", "f32")
        case (.float, _): ("shuf_f64x2", "f64")
        default: ("shuf_i64x2", "i64")
        }
    let type = x86Vector(suffix)
    let shuffled = x86Builtin(
        builtin,
        [
            (value: first, type: type), (value: second, type: type),
            (value: String(x86Avx3Permutation(permutation)), type: "int"),
        ],
        returning: type
    )
    return "const \(type) \(name) = \(shuffled);"
}

func x86Avx3LoadBlocks(_ names: [String], for element: Element) -> [String] {
    let kind = element.category == .float ? "f\(element.bits)" : "i64"
    let declaration = "\(x86Vector(kind)) \(names.joined(separator: ", "));"
    let loads = names.enumerated().map { index, name in
        "__builtin_memcpy(&\(name), from + \(index * element.laneCount), sizeof \(name));"
    }
    return [declaration] + loads
}

func x86Avx3LoadResults(_ channels: Range<Int>) -> [String] {
    channels.map { outVectorStore($0) }
}

func x86Avx3LoadTransposedBlocks3(for element: Element) -> [String] {
    let loads = x86Avx3LoadBlocks(["v3210", "v7654", "vba98"], for: element)
    let blocks: [X86Avx3BlockStep] = [
        ("v5421", "v3210", "v7654", "BACB"),
        ("va976", "v7654", "vba98", "CBDC"),
        ("vA", "v3210", "va976", "CADA"),
        ("vB", "v5421", "va976", "DBCA"),
        ("vC", "v5421", "vba98", "DADB"),
    ]
    return loads + x86Avx3BlockShuffles(blocks, for: element)
}

func x86Avx3LoadTransposedBlocks4(for element: Element) -> [String] {
    let loads = x86Avx3LoadBlocks(["v3210", "v7654", "vba98", "vfedc"], for: element)
    let blocks: [X86Avx3BlockStep] = [
        ("v5410", "v3210", "v7654", "BABA"),
        ("vdc98", "vba98", "vfedc", "BABA"),
        ("v7632", "v3210", "v7654", "DCDC"),
        ("vfeba", "vba98", "vfedc", "DCDC"),
        ("vA", "v5410", "vdc98", "CACA"),
        ("vB", "v5410", "vdc98", "DBDB"),
        ("vC", "v7632", "vfeba", "CACA"),
        ("vD", "v7632", "vfeba", "DBDB"),
    ]
    return loads + x86Avx3BlockShuffles(blocks, for: element)
}

func x86Avx3LoadInterleaved4(for element: Element) -> String {
    let blocks = x86Avx3LoadTransposedBlocks4(for: element)
    let shuffles = x86Shuffles(x86LoadInterleaved4Steps(for: element), for: element)
    return (blocks + shuffles + x86Avx3LoadResults(0..<4)).joined(separator: "\n")
}

func x86Avx3Xor3(
    _ first: String,
    _ second: String,
    _ third: String,
    for element: Element
) -> String {
    let i64 = x86Vector("i64")
    return x86Builtin(
        "pternlogq\(x86Bits(element.width))_mask",
        [
            (value: first, type: i64),
            (value: second, type: i64),
            (value: third, type: i64),
            (value: "0x96", type: "int"),
            (value: "-1", type: x86MaskType(lanes: element.width / 8)),
        ],
        returning: i64
    )
}

func x86Avx3RegisterVector(of element: Element) -> String {
    x86Vector(element.category == .float ? "f\(element.bits)" : "i64")
}

func x86Avx3LaneVector(of element: Element) -> String {
    x86Vector(element.category == .float ? "f\(element.bits)" : "i\(element.bits)")
}

func x86Avx3OddEven(
    _ name: String,
    odd: String,
    even: String,
    for element: Element
) -> String {
    let lane = x86Avx3LaneVector(of: element)
    let register = x86Avx3RegisterVector(of: element)
    let lanes = element.laneCount
    let indices = laneIndices((0..<lanes).map { $0 % 2 == 0 ? lanes + $0 : $0 })
    let blended = "__builtin_shufflevector((\(lane))\(odd), (\(lane))\(even), \(indices))"
    return "const \(register) \(name) = (\(register))\(blended);"
}

func x86Avx3ShuffleTwo(
    _ name: String,
    _ first: String,
    _ second: String,
    permutation: String,
    for element: Element
) -> String {
    let f32 = x86Vector("f32")
    let register = x86Avx3RegisterVector(of: element)
    let shuffled = x86Builtin(
        "shufps512",
        [
            (value: first, type: f32), (value: second, type: f32),
            (value: String(x86Avx3Permutation(permutation)), type: "int"),
        ],
        returning: register
    )
    return "const \(register) \(name) = \(shuffled);"
}

func x86Avx3LoadInterleaved3Lookups(for element: Element) -> [String] {
    let laneBytes = element.bits / 8
    let blockLanes = 16 / laneBytes
    let blocks = ["vA", "vB", "vC"]
    let parts = ["L", "M", "U"]
    let channels = (0..<3).map { channel in
        parts.indices.map { block -> (name: String, table: [UInt8]) in
            let table = (0..<16).map { byte -> UInt8 in
                let position = 3 * (byte / laneBytes) + channel
                guard position / blockLanes == block else { return zeroedByte }
                return UInt8((position % blockLanes) * laneBytes + byte % laneBytes)
            }
            return ("v\(channel)\(parts[block])", table)
        }
    }
    let i8 = x86Vector("i8")
    let tables = channels.flatMap { $0 }.map { part in
        let wide = Array(repeating: part.table, count: element.width / 16).flatMap { $0 }
        return x86ByteTable("idx\(uppercasedFirst(part.name))", wide)
    }
    let lookups = channels.flatMap { channel in
        channel.enumerated().map { block, part in
            let lookup = x86Builtin(
                "pshufb\(x86Bits(element.width))",
                [blocks[block], "idx\(uppercasedFirst(part.name))"],
                as: "i8",
                returning: i8
            )
            return "const \(i8) \(part.name) = \(lookup);"
        }
    }
    let combines = channels.indices.map { channel in
        let names = channels[channel].map(\.name)
        let combined = x86Avx3Xor3(names[0], names[1], names[2], for: element)
        return "const \(x86Vector("i64")) r\(channel) = \(combined);"
    }
    return tables + lookups + combines
}

func x86Avx3LoadInterleaved3(for element: Element) -> String {
    let i8 = x86Vector("i8")
    let register = x86Avx3RegisterVector(of: element)
    let combines: [String]
    switch element.bits {
    case 8, 16:
        combines = x86Avx3LoadInterleaved3Lookups(for: element)
    case 32:
        combines = [
            x86Avx3OddEven("vxx0203xx", odd: "vC", even: "vB", for: element),
            x86Avx3ShuffleTwo("r0", "vA", "vxx0203xx", permutation: "BCDA", for: element),
            x86Avx3OddEven("vxxxx1011", odd: "vA", even: "vB", for: element),
            x86Avx3OddEven("v1213xxxx", odd: "vB", even: "vC", for: element),
            x86Avx3ShuffleTwo("r1", "vxxxx1011", "v1213xxxx", permutation: "CDAB", for: element),
            x86Avx3OddEven("vxx2021xx", odd: "vB", even: "vA", for: element),
            x86Avx3ShuffleTwo("r2", "vxx2021xx", "vC", permutation: "DABC", for: element),
        ]
    default:
        let shifted = x86Builtin(
            "palignr\(x86Bits(element.width))",
            [(value: "vC", type: i8), (value: "vA", type: i8), (value: "8", type: "int")],
            returning: i8
        )
        combines = [
            x86Avx3OddEven("r0", odd: "vB", even: "vA", for: element),
            "const \(register) r1 = (\(register))\(shifted);",
            x86Avx3OddEven("r2", odd: "vC", even: "vB", for: element),
        ]
    }
    let blocks = x86Avx3LoadTransposedBlocks3(for: element)
    return (blocks + combines + x86Avx3LoadResults(0..<3)).joined(separator: "\n")
}

func x86Avx3LoadInterleaved2(level: X86Level, for element: Element) -> String {
    let loads = x86Avx3LoadBlocks(["vA", "vB"], for: element)
    let combines =
        element.bits == 8 && level < .avx3dl
        ? x86Avx3LoadInterleaved2Packs(for: element)
        : x86Avx3LoadInterleaved2Permutes(for: element)
    return (loads + combines + x86Avx3LoadResults(0..<2)).joined(separator: "\n")
}

func x86Avx3LoadInterleaved2Permutes(for element: Element) -> [String] {
    let lane = x86Avx3LaneVector(of: element)
    return (0..<2).map { channel in
        let indices = laneIndices((0..<element.laneCount).map { 2 * $0 + channel })
        let shuffled = "__builtin_shufflevector((\(lane))vA, (\(lane))vB, \(indices))"
        return "const \(lane) r\(channel) = \(shuffled);"
    }
}

func x86Avx3LoadInterleaved2Packs(for element: Element) -> [String] {
    let i16 = x86Vector("i16")
    let i64 = x86Vector("i64")
    let mask = splat("255", as: i16, lanes: element.width / 2)
    let order = compoundLiteral(i64, ["0", "2", "4", "6", "1", "3", "5", "7"])
    func packedBytes(_ high: String, _ low: String) -> String {
        let packed = x86Builtin(
            "packuswb\(x86Bits(element.width))",
            [(value: low, type: i16), (value: high, type: i16)],
            returning: i64
        )
        return x86Builtin(
            "permvardi\(x86Bits(element.width))",
            [(value: packed, type: i64), (value: order, type: i64)],
            returning: i64
        )
    }
    func shiftedRight(_ operand: String) -> String {
        x86ImmediateShift(
            "psrl",
            operand,
            by: "8",
            laneBits: 16,
            width: element.width,
            returning: i16
        )
    }
    return [
        "const \(i16) evenLow = (\(i16))vA & \(mask);",
        "const \(i16) evenHigh = (\(i16))vB & \(mask);",
        "const \(i64) r0 = \(packedBytes("evenHigh", "evenLow"));",
        "const \(i16) oddHigh = \(shiftedRight("vB"));",
        "const \(i16) oddLow = \(shiftedRight("vA"));",
        "const \(i64) r1 = \(packedBytes("oddHigh", "oddLow"));",
    ]
}

typealias X86Avx3BlockStep = (name: String, first: String, second: String, permutation: String)

func x86Avx3BlockShuffles(_ steps: [X86Avx3BlockStep], for element: Element) -> [String] {
    steps.map { name, first, second, permutation in
        x86Avx3Shuffle128(name, first, second, permutation: permutation, for: element)
    }
}

func x86Avx3Shuffles(_ steps: [ShuffleStep], for element: Element) -> [String] {
    let raws = ["a": "rawA", "b": "rawB", "c": "rawC", "d": "rawD"]
    return x86Shuffles(
        steps.map { step in
            ShuffleStep(
                name: step.name,
                first: raws[step.first] ?? step.first,
                second: raws[step.second] ?? step.second,
                laneBits: step.laneBits,
                indices: step.indices,
                isFloating: step.isFloating,
                byteShift: step.byteShift,
                unpacksUpper: step.unpacksUpper
            )
        },
        opaqueCasts: true,
        for: element
    )
}

func x86Avx3StoreInterleaved(
    _ statements: [String],
    blocks: [X86Avx3BlockStep],
    pointer: String = "to",
    for element: Element
) -> String {
    let outputs = blocks.filter { $0.name.hasPrefix("out") }
    let stores = outputs.indices.map { index in
        "__builtin_memcpy(\(pointer) + \(index * element.laneCount), &out\(index), sizeof out\(index));"
    }
    return (statements + x86Avx3BlockShuffles(blocks, for: element) + stores)
        .joined(separator: "\n")
}

func x86Avx3StoreInterleaved2(for element: Element) -> String {
    x86Avx3StoreInterleaved(
        x86Avx3Shuffles(x86StoreInterleaved2Steps(for: element), for: element),
        blocks: [
            ("j1j0i1i0", "vA", "vB", "BABA"),
            ("j3j2i3i2", "vA", "vB", "DCDC"),
            ("out0", "j1j0i1i0", "j1j0i1i0", "DBCA"),
            ("out1", "j3j2i3i2", "j3j2i3i2", "DBCA"),
        ],
        for: element
    )
}

func x86Avx3StoreInterleaved4(pointer: String = "to", for element: Element) -> String {
    x86Avx3StoreInterleaved(
        x86Avx3Shuffles(x86StoreInterleaved4Steps(for: element), for: element),
        blocks: [
            ("j1j0i1i0", "vA", "vB", "BABA"),
            ("l1l0k1k0", "vC", "vD", "BABA"),
            ("j3j2i3i2", "vA", "vB", "DCDC"),
            ("l3l2k3k2", "vC", "vD", "DCDC"),
            ("out0", "j1j0i1i0", "l1l0k1k0", "CACA"),
            ("out1", "j1j0i1i0", "l1l0k1k0", "DBDB"),
            ("out2", "j3j2i3i2", "l3l2k3k2", "CACA"),
            ("out3", "j3j2i3i2", "l3l2k3k2", "DBDB"),
        ],
        pointer: pointer,
        for: element
    )
}

func x86Avx3StoreInterleaved3Lookups(for element: Element) -> [String] {
    let i8 = x86Vector("i8")
    let register = x86Vector("i64")
    let tables = x86StoreInterleaved3Tables(for: element)
    let blocks = ["A", "B", "C"]
    let inputs = ["rawA", "rawB", "rawC"]
    let declarations = zip(blocks, tables).flatMap { block, group in
        group.enumerated().map { index, table in
            let wide = Array(repeating: table, count: element.width / 16).flatMap { $0 }
            return x86ByteTable("shuf\(block)\(index)", wide)
        }
    }
    let statements = blocks.flatMap { block in
        let lookups = inputs.indices.map { index in
            let lookup = x86Builtin(
                "pshufb\(x86Bits(element.width))",
                [(value: inputs[index], type: i8), (value: "shuf\(block)\(index)", type: i8)],
                returning: i8
            )
            return "const \(i8) v\(block)\(index) = \(lookup);"
        }
        let combined =
            "const \(register) v\(block) = (\(register))(v\(block)0 | v\(block)1 | v\(block)2);"
        return lookups + [combined]
    }
    return declarations + statements
}

func x86Avx3ByteShiftedRight(
    _ name: String,
    _ source: String,
    bytes: Int,
    for element: Element
) -> String {
    let register = x86Avx3RegisterVector(of: element)
    let i64 = x86Vector("i64")
    let shifted =
        "__builtin_ia32_psrldqi\(x86Bits(element.width))_byteshift((\(i64))\(source), \(bytes))"
    return "const \(register) \(name) = (\(register))\(shifted);"
}

func x86Avx3OddEvenStep(
    _ name: String,
    odd: String,
    even: String,
    for element: Element
) -> ShuffleStep {
    let lanes = element.laneCount
    return ShuffleStep(
        name: name,
        first: odd,
        second: even,
        laneBits: element.bits,
        indices: (0..<lanes).map { $0 % 2 == 0 ? lanes + $0 : $0 }
    )
}

func x86Avx3StoreInterleaved3Shuffles(for element: Element) -> [String] {
    func oddEven(_ name: String, odd: String, even: String) -> ShuffleStep {
        x86Avx3OddEvenStep(name, odd: odd, even: even, for: element)
    }
    let isFloating = element.category == .float
    guard element.bits == 32 else {
        return x86Avx3Shuffles(
            [
                .lower("vA", "a", "b", laneBits: 64),
                oddEven("vB", odd: "a", even: "c"),
                .upper("vC", "b", "c", laneBits: 64),
            ],
            for: element
        )
    }
    func shuffles(_ steps: [ShuffleStep]) -> [String] {
        x86Avx3Shuffles(steps, for: element)
    }
    return shuffles([
        .lower("v10v00", "a", "b", laneBits: 32),
        oddEven("v01v20", odd: "a", even: "c"),
        .lower("vA", "v10v00", "v01v20", laneBits: 64, isFloating: isFloating),
    ])
        + [
            x86Avx3ByteShiftedRight("v1x321", "rawB", bytes: 4, for: element),
            x86Avx3ByteShiftedRight("v0x32", "rawA", bytes: 8, for: element),
        ]
        + shuffles([
            oddEven("v21v11", odd: "c", even: "v1x321"),
            oddEven("v12v02", odd: "v1x321", even: "v0x32"),
            .lower("vB", "v21v11", "v12v02", laneBits: 64, isFloating: isFloating),
            .upper("vC", "v01v20", "v21v11", laneBits: 64, isFloating: isFloating),
        ])
}

func x86Avx3StoreInterleaved3(for element: Element) -> String {
    x86Avx3StoreInterleaved(
        element.bits <= 16
            ? x86Avx3StoreInterleaved3Lookups(for: element)
            : x86Avx3StoreInterleaved3Shuffles(for: element),
        blocks: [
            ("j2j0i2i0", "vA", "vB", "CACA"),
            ("i3i1k2k0", "vC", "vA", "DBCA"),
            ("j3j1k3k1", "vC", "vB", "DBDB"),
            ("out0", "j2j0i2i0", "i3i1k2k0", "CACA"),
            ("out1", "j3j1k3k1", "j2j0i2i0", "DBAC"),
            ("out2", "i3i1k2k0", "j3j1k3k1", "BDDB"),
        ],
        for: element
    )
}

func x86Avx3StoreInterleaved2Halves(for element: Element) -> String {
    let vector = element.cUnsignedVector
    let lanes = element.laneCount
    let half = lanes / 2
    func halfOf(_ name: String, _ operand: String, _ range: Range<Int>) -> String {
        let source = "(\(vector))\(operand)"
        return
            "const half_vector \(name) = __builtin_shufflevector(\(source), \(source), \(laneIndices(range)));"
    }
    let interleaved = laneIndices((0..<half).flatMap { [$0, half + $0] })
    return """
        typedef \(element.cUnsignedLane) half_vector __attribute__((vector_size(\(element.width / 2))));
        \(halfOf("aLow", "rawA", 0..<half))
        \(halfOf("aHigh", "rawA", half..<lanes))
        \(halfOf("bLow", "rawB", 0..<half))
        \(halfOf("bHigh", "rawB", half..<lanes))
        const \(vector) low = __builtin_shufflevector(aLow, bLow, \(interleaved));
        const \(vector) high = __builtin_shufflevector(aHigh, bHigh, \(interleaved));
        __builtin_memcpy(to, &low, sizeof low);
        __builtin_memcpy(to + \(lanes), &high, sizeof high);
        """
}

func x86Avx3StoreInterleaved2Spread(for element: Element) -> String {
    let bytes = x86Vector("i8")
    let quads = x86Vector("i64")
    let quadLanes = element.width / 8
    let unpacked = laneIndices(unpackIndices(lanes: 16, upper: false, blocks: element.width / 16))
    func spread(_ name: String, _ operand: String, from start: Int) -> String {
        let indices = laneIndices((start..<start + quadLanes / 2).flatMap { [$0, -1] })
        let source = "(\(quads))\(operand)"
        return "const \(quads) \(name) = __builtin_shufflevector(\(source), \(source), \(indices));"
    }
    func interleave(_ name: String, _ first: String, _ second: String) -> String {
        let operands = "(\(bytes))\(first), (\(bytes))\(second)"
        return "const \(bytes) \(name) = __builtin_shufflevector(\(operands), \(unpacked));"
    }
    return """
        \(spread("lowA", "rawA", from: 0))
        \(spread("highA", "rawA", from: quadLanes / 2))
        \(spread("lowB", "rawB", from: 0))
        \(spread("highB", "rawB", from: quadLanes / 2))
        \(interleave("out0", "lowA", "lowB"))
        \(interleave("out1", "highA", "highB"))
        __builtin_memcpy(to, &out0, sizeof out0);
        __builtin_memcpy(to + \(element.laneCount), &out1, sizeof out1);
        """
}

func x86Avx3StoreInterleaved4Permutes(for element: Element) -> String {
    let lane = x86Avx3LaneVector(of: element)
    let wide = x86Vector("i\(2 * element.bits)")
    let lanes = element.laneCount
    let wideLanes = lanes / 2
    func paired(_ name: String, _ first: String, _ second: String, from start: Int) -> String {
        let indices = laneIndices((start..<start + lanes / 2).flatMap { [$0, lanes + $0] })
        let operands = "(\(lane))\(first), (\(lane))\(second)"
        return "const \(lane) \(name) = __builtin_shufflevector(\(operands), \(indices));"
    }
    func merged(_ name: String, _ first: String, _ second: String, from start: Int) -> String {
        let indices = laneIndices((start..<start + wideLanes / 2).flatMap { [$0, wideLanes + $0] })
        let operands = "(\(wide))\(first), (\(wide))\(second)"
        return "const \(wide) \(name) = __builtin_shufflevector(\(operands), \(indices));"
    }
    let shuffles = [
        paired("v10L", "rawA", "rawB", from: 0),
        paired("v32L", "rawC", "rawD", from: 0),
        paired("v10U", "rawA", "rawB", from: lanes / 2),
        paired("v32U", "rawC", "rawD", from: lanes / 2),
        merged("out0", "v10L", "v32L", from: 0),
        merged("out1", "v10L", "v32L", from: wideLanes / 2),
        merged("out2", "v10U", "v32U", from: 0),
        merged("out3", "v10U", "v32U", from: wideLanes / 2),
    ]
    let stores = (0..<4).map { index in
        "__builtin_memcpy(to + \(index * lanes), &out\(index), sizeof out\(index));"
    }
    return (shuffles + stores).joined(separator: "\n")
}

func x86Avx3LoadInterleaved2Body(level: X86Level, for element: Element) -> String {
    if element.bits == 8 && level < .avx3dl {
        return shuffleLoadInterleaved(channels: 2, for: element)
    }
    return x86Avx3LoadInterleaved2(level: level, for: element)
}

func x86Avx3LoadInterleaved3Body(for element: Element) -> String {
    if element.bits == 16 || element.bits == 32 {
        return shuffleLoadInterleaved(channels: 3, for: element)
    }
    return x86Avx3LoadInterleaved3(for: element)
}

func x86Avx3StoreInterleaved2Body(level: X86Level, for element: Element) -> String {
    if element.bits == 64 {
        return shuffleStoreInterleaved(channels: 2, for: element)
    }
    if element.bits == 8 && level < .avx3dl {
        return x86Avx3StoreInterleaved2Spread(for: element)
    }
    return element.category == .float
        ? x86Avx3StoreInterleaved2(for: element)
        : x86Avx3StoreInterleaved2Halves(for: element)
}

func x86Avx3StoreInterleaved3Body(for element: Element) -> String {
    if element.bits == 16 || element.bits == 32 {
        return shuffleStoreInterleaved(channels: 3, for: element)
    }
    return x86Avx3StoreInterleaved3(for: element)
}

func x86Avx3StoreInterleaved4Doubles(for element: Element) -> String {
    let constant = "__builtin_constant_p(__builtin_reduce_or((\(x86Vector("i64")))rawC))"
    return """
        if (\(constant)) {
        \(shuffleStoreInterleaved(channels: 4, for: element))
        } else {
        \(x86Avx3StoreInterleaved4(for: element))
        }
        """
}

func x86Avx3StoreInterleaved4Body(for element: Element) -> String {
    switch (element.category, element.bits) {
    case (.float, 64):
        return x86Avx3StoreInterleaved4Doubles(for: element)
    case (.float, _), (_, 8), (_, 64):
        return x86Avx3StoreInterleaved4(for: element)
    default:
        return x86Avx3StoreInterleaved4Permutes(for: element)
    }
}

func operationCall(_ name: String, _ operands: [String], for element: Element) -> String {
    let arguments = operands.map { "(\(element.cRawVector))\($0)" }
    return
        "(\(element.cVector))\(cFunctionName(name, element))(\(arguments.joined(separator: ", ")))"
}

func negatedLanes(_ operand: String, for element: Element) -> String {
    guard element.category != .float else { return "-\(operand)" }
    return "(\(element.cVector))(-\(unsignedBits(operand, of: element)))"
}

func alternatingLanes(_ evens: String, _ odds: String, for element: Element) -> String {
    let lanes = element.laneCount
    let indices = (0..<lanes).map { $0.isMultiple(of: 2) ? $0 : lanes + $0 }
    return "__builtin_shufflevector(\(evens), \(odds), \(laneIndices(indices)))"
}

func emulatedAddingSubtracting(for element: Element) -> String {
    let signBit = "0x\(String(UInt64(1) << UInt64(element.bits - 1), radix: 16))"
    let (unsigned, lane) = (element.cUnsignedVector, element.cUnsignedLane)
    let signs = Array(repeating: signBit, count: element.laneCount).joined(separator: ", ")
    return """
        #if defined(__APPLE__)
        \(lane) signs[\(element.laneCount)] = {\(signs)};
        #endif
        const \(unsigned) bits = (\(unsigned))b;
        \(element.cVector) result;
        for (size_t i = 0; i < \(element.laneCount); ++i) {
        #if defined(__APPLE__)
          __asm__("" : "+r"(signs[i]));
          const \(lane) negatedBits = bits[i] ^ signs[i];
        #else
          const \(lane) negatedBits = bits[i] ^ \(signBit);
        #endif
          const \(element.cType) negated = __builtin_bit_cast(\(element.cType), negatedBits);
          result[i] = i % 2 == 0 ? a[i] + negated : a[i] + b[i];
        }
        \(vectorResult("result", for: element))
        """
}

func vectorAddingSubtracting(for element: Element) -> String {
    """
    const \(element.cVector) negated = \(negatedLanes("b", for: element));
    const \(element.cVector) addend = \(alternatingLanes("negated", "b", for: element));
    \(vectorResult(arithmetic("+", "a", "addend", for: element), for: element))
    """
}

func portableAddingSubtracting(for element: Element) -> String {
    element.category == .float
        ? emulatedAddingSubtracting(for: element) : vectorAddingSubtracting(for: element)
}

func floatAddingSubtracting(for element: Element) -> String? {
    element.category == .float ? vectorAddingSubtracting(for: element) : nil
}

func x86AddingSubtracting(for element: Element) -> String? {
    guard element.category == .float else { return nil }
    let name = "addsub\(element.bits == 32 ? "ps" : "pd")\(x86UnsuffixedBits(element.width))"
    let alternating = x86Builtin(
        name,
        ["a", "b"],
        as: element.cSuffix,
        returning: element.cVector
    )
    return vectorResult(alternating, for: element)
}

func subtractedSaturating(_ operand: String, for element: Element) -> String {
    let zero = compoundLiteral(element.cVector, ["0"])
    return "__builtin_elementwise_sub_sat(\(zero), \(operand))"
}

func portableSaturatingNegated(for element: Element) -> String {
    let lanes = element.laneCount
    switch element.bits {
    case 32:
        let lowest = splat("INT32_MIN", as: element.cVector, lanes: lanes)
        return """
            const \(element.cMask) greater = (\(element.cMask))(a > \(lowest));
            \(vectorResult(arithmetic("-", "~a", "greater", for: element), for: element))
            """
    case 64:
        let sign = "((a & negated) >> 63)"
        return """
            const \(element.cVector) negated = \(negatedLanes("a", for: element));
            \(vectorResult(arithmetic("+", "negated", sign, for: element), for: element))
            """
    default:
        return vectorResult(subtractedSaturating("a", for: element), for: element)
    }
}

func neonSaturatingNegated(for element: Element) -> String {
    vectorResult(
        neonBuiltin("vqnegq_v", ["a"], code: neonTypeCode(of: element), for: element),
        for: element
    )
}

func x86SaturatingNegated(level: X86Level, for element: Element) -> String? {
    if element.bits == 64 && level >= .sse4 && level <= .avx2 {
        let zero = compoundLiteral(element.cVector, ["0"])
        return """
            const \(element.cVector) negated = \(negatedLanes("a", for: element));
            const \(element.cVector) signs = (\(element.cVector))(\(zero) > (a & negated));
            \(vectorResult(arithmetic("+", "negated", "signs", for: element), for: element))
            """
    }
    guard element.bits == 32 ? level >= .sse4 : element.bits == 64 && level >= .avx3 else {
        return nil
    }
    let zero = compoundLiteral(element.cVector, ["0"])
    let limit = splat("-INT\(element.bits)_MAX", as: element.cVector, lanes: element.laneCount)
    let negated = arithmetic("-", zero, "__builtin_elementwise_max(a, \(limit))", for: element)
    return vectorResult(negated, for: element)
}

func portableSaturatingMagnitude(for element: Element) -> String {
    let negated = operationCall("saturatingNegated", ["a"], for: element)
    return vectorResult("__builtin_elementwise_max(a, \(negated))", for: element)
}

func neonSaturatingMagnitude(for element: Element) -> String {
    vectorResult(
        neonBuiltin("vqabsq_v", ["a"], code: neonTypeCode(of: element), for: element),
        for: element
    )
}

func sveSaturatingUnary(_ name: String, for element: Element) -> String {
    let arguments = [sveAllLanes(of: element), sveOperand("a", for: element, splat: true)]
    let result = sveBuiltin(name, arguments, for: element, predication: "x")
    return vectorResult(sveResult(result, for: element), for: element)
}

func x86SaturatingMagnitude(level: X86Level, for element: Element) -> String? {
    let unsigned = element.cUnsignedVector
    let absolute = operationCall("magnitude", ["a"], for: element)
    switch element.bits {
    case 8:
        let negated = subtractedSaturating("a", for: element)
        let lowest = "__builtin_elementwise_min((\(unsigned))a, (\(unsigned))\(negated))"
        return vectorResult(lowest, for: element)
    case 32 where level >= .sse4, 64 where level >= .avx3:
        let limit = splat(
            "(\(element.cUnsignedLane))INT\(element.bits)_MAX",
            as: unsigned,
            lanes: element.laneCount
        )
        let lowest = "__builtin_elementwise_min((\(unsigned))absolute, \(limit))"
        return """
            const \(element.cVector) absolute = \(absolute);
            \(vectorResult(lowest, for: element))
            """
    case 32, 64:
        let sign = "(absolute >> \(element.bits - 1))"
        return """
            const \(element.cVector) absolute = \(absolute);
            \(vectorResult(arithmetic("+", "absolute", sign, for: element), for: element))
            """
    default:
        return nil
    }
}

func portableAbsoluteDifference(for element: Element) -> String {
    guard element.category != .float else {
        return vectorResult("__builtin_elementwise_abs(a - b)", for: element)
    }
    let highest = operationCall("maximum", ["a", "b"], for: element)
    let lowest = operationCall("minimum", ["a", "b"], for: element)
    return vectorResult(arithmetic("-", highest, lowest, for: element), for: element)
}

func neonAbsoluteDifference(for element: Element) -> String? {
    guard isInteger64(element) else {
        return vectorResult(
            neonBuiltin("vabdq_v", ["a", "b"], code: neonTypeCode(of: element), for: element),
            for: element
        )
    }
    guard element.category == .unsignedInteger else { return nil }
    let (forward, backward) = ("a, b", "b, a")
    let differences = [forward, backward].map { "__builtin_elementwise_sub_sat(\($0))" }
    return vectorResult(differences.joined(separator: " | "), for: element)
}

func pairedLanes(parity: Int, for element: Element) -> String {
    let lanes = element.laneCount
    let indices = stride(from: parity, to: lanes, by: 2).flatMap { [$0, lanes + $0] }
    return "__builtin_shufflevector(a, b, \(laneIndices(indices)))"
}

func portablePairwise(subtracting: Bool, for element: Element) -> String {
    let (evens, odds) = (pairedLanes(parity: 0, for: element), pairedLanes(parity: 1, for: element))
    let (first, second) = subtracting ? ("odds", "evens") : ("evens", "odds")
    return """
        const \(element.cVector) evens = \(evens);
        const \(element.cVector) odds = \(odds);
        \(vectorResult(arithmetic(subtracting ? "-" : "+", first, second, for: element), for: element))
        """
}

func emulatedPairwise(subtracting: Bool, for element: Element) -> String {
    let lane = element.cType
    let unsigned = element.cUnsignedLane
    let count = element.laneCount
    let (target, other, symbol) = subtracting ? ("odds", "evens", "-") : ("evens", "odds", "+")
    let combination =
        element.category == .float
        ? "\(target)[i] \(symbol)= \(other)[i];"
        : "\(target)[i] = (\(lane))((\(unsigned))\(target)[i] \(symbol) (\(unsigned))\(other)[i]);"
    return """
        \(lane) lanesA[\(count)];
        __builtin_memcpy(lanesA, &a, sizeof lanesA);
        \(lane) lanesB[\(count)];
        __builtin_memcpy(lanesB, &b, sizeof lanesB);
        \(lane) evens[\(count)];
        __builtin_memcpy(evens, lanesA, sizeof evens);
        for (size_t i = 1; i < \(count); i += 2) {
          evens[i] = lanesB[i - 1];
        }
        \(lane) odds[\(count)];
        __builtin_memcpy(odds, lanesB, sizeof odds);
        for (size_t i = 1; i < \(count); i += 2) {
          odds[i - 1] = lanesA[i];
        }
        for (size_t i = 0; i < \(count); ++i) {
          \(combination)
        }
        \(element.cVector) lanes;
        __builtin_memcpy(&lanes, \(target), sizeof lanes);
        \(vectorResult("lanes", for: element))
        """
}

func portableClamped(for element: Element) -> String {
    let raised = operationCall("maximum", ["b", "a"], for: element)
    return """
        const \(element.cVector) raised = \(raised);
        \(vectorResult(operationCall("minimum", ["raised", "c"], for: element), for: element))
        """
}

func x86MinimumNumber(
    _ name: String,
    isNaN: String,
    for element: Element
) -> String? {
    guard element.category == .float else { return nil }
    let selecting = cFunctionName("selecting", element)
    let (rawVector, rawMask) = (element.cRawVector, element.cRawMask)
    let operands = ["(\(rawMask))\(isNaN)", "(\(rawVector))a", "(\(rawVector))b"]
    let replaced = "(\(element.cVector))\(selecting)(\(operands.joined(separator: ", ")))"
    return """
        const \(element.cVector) replaced = \(replaced);
        \(vectorResult(operationCall(name, ["a", "replaced"], for: element), for: element))
        """
}

func emulatedMagnitudeExtremum(_ name: String, for element: Element) -> String {
    let isMinimum = name == "minimum"
    let (yes, no) = isMinimum ? ("a[i]", "b[i]") : ("b[i]", "a[i]")
    let absolute = element.bits == 32 ? "__builtin_fabsf" : "__builtin_fabs"
    let symbol = isMinimum ? "<" : ">"
    let selected =
        "candidate != candidate ? \(no) : \(no) != \(no) ? candidate : candidate \(symbol) \(no) ? candidate : \(no)"
    let constantZero = "__builtin_constant_p(a[i]) && a[i] == 0"
    let limited =
        isMinimum || element.bits == 64
        ? selected : "\(constantZero) ? __builtin_elementwise_max(candidate, a[i]) : \(selected)"
    return """
        \(element.cVector) result;
        for (size_t i = 0; i < \(element.laneCount); ++i) {
          const \(element.cType) magnitudeA = \(absolute)(a[i]);
          const \(element.cType) magnitudeB = \(absolute)(b[i]);
          const \(element.cType) candidate = magnitudeA == magnitudeB ? \(yes) : \(no);
          const \(element.cType) limited = \(limited);
          result[i] = magnitudeA < magnitudeB ? \(yes) : limited;
        }
        \(vectorResult("result", for: element))
        """
}

func emulatedSignedMagnitudeExtremum(_ name: String, for element: Element) -> String {
    let isMinimum = name == "minimum"
    let (yes, no) = isMinimum ? ("a[i]", "b[i]") : ("b[i]", "a[i]")
    let lane = element.cUnsignedLane
    let symbol = isMinimum ? "<" : ">"
    return """
        \(element.cVector) result;
        for (size_t i = 0; i < \(element.laneCount); ++i) {
          const \(lane) magnitudeA = a[i] < 0 ? 0 - (\(lane))a[i] : (\(lane))a[i];
          const \(lane) magnitudeB = b[i] < 0 ? 0 - (\(lane))b[i] : (\(lane))b[i];
          const \(element.cType) candidate = magnitudeA == magnitudeB ? \(yes) : \(no);
          const \(element.cType) limited = candidate \(symbol) \(no) ? candidate : \(no);
          result[i] = magnitudeA < magnitudeB ? \(yes) : limited;
        }
        \(vectorResult("result", for: element))
        """
}

func floatMagnitudeExtremum(_ name: String, for element: Element) -> String? {
    element.category == .float ? magnitudeExtremum(name, for: element) : nil
}

func neonMagnitudeExtremum(_ name: String, for element: Element) -> String? {
    guard element.category == .signedInteger else { return nil }
    return magnitudeExtremum(name, absolute: neonAbsolute, for: element)
}

func neonAbsolute(_ operand: String, for element: Element) -> String {
    neonBuiltin("vabsq_v", [operand], code: neonTypeCode(of: element), for: element)
}

func magnitudeExtremum(
    _ name: String,
    absolute: ((_ operand: String, _ element: Element) -> String)? = nil,
    of operands: (first: String, second: String) = ("a", "b"),
    for element: Element
) -> String {
    let (a, b) = operands
    guard element.category != .unsignedInteger else {
        return vectorResult(operationCall(name, [a, b], for: element), for: element)
    }
    let comparing =
        element.category == .float || element.category == .float16
        ? element : unsignedElement(of: element)
    let (first, second) = name == "minimum" ? (a, b) : (b, a)
    let vector = element.cVector
    let (rawVector, rawMask) = (element.cRawVector, element.cRawMask)
    let selecting = cFunctionName("selecting", element)
    func selected(_ mask: String, _ yes: String, _ no: String) -> String {
        "\(selecting)(\(mask), (\(rawVector))\(yes), (\(rawVector))\(no))"
    }
    func compared(_ name: String) -> String {
        "(\(rawMask))\(cFunctionName(name, comparing))(magnitudeA, magnitudeB)"
    }
    func magnitude(_ operand: String) -> String {
        let value =
            absolute?(operand, element) ?? operationCall("magnitude", [operand], for: element)
        return "(\(comparing.cRawVector))\(value)"
    }
    return """
        const \(comparing.cRawVector) magnitudeA = \(magnitude(a));
        const \(comparing.cRawVector) magnitudeB = \(magnitude(b));
        const \(rawMask) less = \(compared("lessThan"));
        const \(vector) candidate = (\(vector))\(selected(compared("equalTo"), first, second));
        const \(vector) limited = \(operationCall(name, ["candidate", second], for: element));
        return \(selected("less", first, "limited"));
        """
}

struct FusedMultiplication {
    let unfused: String
    let fused: String
    let neon: String
    let sve: String
    let sveInteger: (Element) -> String
    let integer: (Element) -> String
}

let negatedMultiplyAddingForm = FusedMultiplication(
    unfused: "c - a * b",
    fused: "__builtin_elementwise_fma(-a, b, c)",
    neon: "__builtin_elementwise_fma(-a, b, c)",
    sve: "msb",
    sveInteger: { sveMultiplyAdding("msb", for: $0) },
    integer: integerNegatedMultiplyAdding
)

let multiplySubtractingForm = FusedMultiplication(
    unfused: "a * b - c",
    fused: "__builtin_elementwise_fma(a, b, -c)",
    neon: "__builtin_elementwise_fma(a, b, -c)",
    sve: "nmsb",
    sveInteger: sveIntegerMultiplySubtracting,
    integer: integerMultiplySubtracting
)

let negatedMultiplySubtractingForm = FusedMultiplication(
    unfused: "-a * b - c",
    fused: "__builtin_elementwise_fma(-a, b, -c)",
    neon: "-__builtin_elementwise_fma(a, b, c)",
    sve: "nmad",
    sveInteger: sveIntegerNegatedMultiplySubtracting,
    integer: integerNegatedMultiplySubtracting
)

func sveIntegerMultiplySubtracting(for element: Element) -> String {
    let operands = ["a", "b", "c"].map { sveSplatOperand($0, for: element) }
    let all = sveAllLanes(of: element)
    let (a, b, c) = (operands[0], operands[1], operands[2])
    let product = sveBuiltin("mul", [all, a, b], for: element, predication: "x")
    let difference = sveBuiltin("sub", [all, product, c], for: element, predication: "x")
    return vectorResult(sveResult(difference, for: element), for: element)
}

func sveIntegerNegatedMultiplySubtracting(for element: Element) -> String {
    let operands = ["a", "b", "c"].map { sveSplatOperand($0, for: element) }
    let all = sveAllLanes(of: element)
    let signed = signedElement(of: element)
    let (a, b, c) = (operands[0], operands[1], operands[2])
    let sum = sveBuiltin("mad", [all, b, a, c], for: element, predication: "x")
    let negated = sveBuiltin(
        "neg",
        [all, sveReinterpreted(sum, from: element, to: signed)],
        for: signed,
        predication: "x"
    )
    return vectorResult(
        sveResult(sveReinterpreted(negated, from: signed, to: element), for: element),
        for: element
    )
}

func integerNegatedMultiplyAdding(for element: Element) -> String {
    let product = multipliedLanes("a", "b", for: element)
    return vectorResult(arithmetic("-", "c", product, for: element), for: element)
}

func integerMultiplySubtracting(for element: Element) -> String {
    let product = multipliedLanes("a", "b", for: element)
    return vectorResult(arithmetic("-", product, "c", for: element), for: element)
}

func integerNegatedMultiplySubtracting(for element: Element) -> String {
    let product = multipliedLanes("a", "b", for: element)
    let sum = arithmetic("+", product, "c", for: element)
    return vectorResult(negatedLanes("(\(sum))", for: element), for: element)
}

let x86DisablesFmaCondition = "defined(HWY_DISABLE_BMI2_FMA)"

func fusedMultiplicationTargets(_ form: FusedMultiplication) -> TargetBodies<Element> {
    TargetBodies(
        neon: { element in
            element.category == .float ? vectorResult(form.neon, for: element) : nil
        },
        sve2_128: { element in
            element.category == .float
                ? sveMultiplyAdding(form.sve, for: element) : form.sveInteger(element)
        },
        avx3: { element in
            element.category == .float ? vectorResult(form.fused, for: element) : nil
        },
        avx2: { element in
            guard element.category == .float else { return nil }
            return """
                #if \(x86DisablesFmaCondition)
                \(withoutContraction(vectorResult(form.unfused, for: element)))
                #else
                \(vectorResult(form.fused, for: element))
                #endif
                """
        }
    )
}

func portableFusedMultiplication(_ form: FusedMultiplication, for element: Element) -> String {
    element.category == .float
        ? withoutContraction(vectorResult(form.unfused, for: element))
        : form.integer(element)
}

func alternatingAddend(negatingAll: Bool, for element: Element) -> String {
    var statements: [String] = []
    var odd = "c"
    if negatingAll {
        statements.append("const \(element.cVector) flipped = \(negatedLanes("c", for: element));")
        odd = "flipped"
    }
    statements += [
        "const \(element.cVector) negated = \(negatedLanes(odd, for: element));",
        "const \(element.cVector) addend = \(alternatingLanes("negated", odd, for: element));",
    ]
    return statements.joined(separator: "\n")
}

func emulatedMultiplyAlternating(negatingAll: Bool, for element: Element) -> String? {
    guard element.category != .float && element.bits >= 32 else { return nil }
    let lane = element.cUnsignedLane
    let (evens, odds) = negatingAll ? ("+", "-") : ("-", "+")
    return """
        \(element.cVector) result;
        for (size_t i = 0; i < \(element.laneCount); ++i) {
          const \(lane) product = (\(lane))a[i] * (\(lane))b[i];
          result[i] = (\(element.cType))(i % 2 == 0 ? product \(evens) (\(lane))c[i] : product \(odds) (\(lane))c[i]);
        }
        \(vectorResult("result", for: element))
        """
}

func portableMultiplyAlternating(
    negatingAll: Bool,
    fused: Bool,
    for element: Element
) -> String {
    let addend = alternatingAddend(negatingAll: negatingAll, for: element)
    guard element.category == .float else {
        let product = multipliedLanes("a", "b", for: element)
        let sum = arithmetic("+", product, "addend", for: element)
        return "\(addend)\n\(vectorResult(sum, for: element))"
    }
    guard fused else {
        return "\(addend)\n\(withoutContraction(vectorResult("a * b + addend", for: element)))"
    }
    return "\(addend)\n\(vectorResult("__builtin_elementwise_fma(a, b, addend)", for: element))"
}

func x86MultiplyAlternating(
    level: X86Level,
    negatingAll: Bool,
    for element: Element
) -> String? {
    guard element.category == .float else { return nil }
    let suffix = element.bits == 32 ? "ps" : "pd"
    let third = negatingAll ? "-c" : "c"
    let floating = element.cSuffix
    let unfused = x86Builtin(
        "addsub\(suffix)\(x86UnsuffixedBits(element.width))",
        ["product", third],
        as: floating,
        returning: element.cVector
    )
    let separate = """
        const \(element.cVector) product = a * b;
        \(vectorResult(unfused, for: element))
        """
    guard level >= .avx2 else { return separate }
    let name = "vfmaddsub\(suffix)\(x86UnsuffixedBits(element.width))"
    guard level == .avx2 else {
        let mask = x86MaskType(lanes: element.laneCount)
        let arguments = [
            (value: "a", type: x86Vector(floating)), (value: "b", type: x86Vector(floating)),
            (value: third, type: x86Vector(floating)), (value: "-1", type: mask),
            (value: "\(x86CurrentRounding)", type: "int"),
        ]
        return vectorResult(
            x86Builtin("\(name)_mask", arguments, returning: element.cVector),
            for: element
        )
    }
    let fused = x86Builtin(name, ["a", "b", third], as: floating, returning: element.cVector)
    return """
        #if \(x86DisablesFmaCondition)
        \(withoutContraction(separate))
        #else
        \(vectorResult(fused, for: element))
        #endif
        """
}

func multiplyAlternatingTargets(negatingAll: Bool) -> TargetBodies<Element> {
    TargetBodies(
        neon: { element in
            element.category == .float
                ? portableMultiplyAlternating(negatingAll: negatingAll, fused: true, for: element)
                : nil
        },
        sve2_128Splat: { element in
            sveConstantMultiplyAlternating(negatingAll: negatingAll, for: element)
        },
        avx3: { element in
            x86MultiplyAlternating(level: .avx3, negatingAll: negatingAll, for: element)
        },
        avx2: { element in
            x86MultiplyAlternating(level: .avx2, negatingAll: negatingAll, for: element)
        },
        ssse3: { element in
            x86MultiplyAlternating(level: .ssse3, negatingAll: negatingAll, for: element)
        },
        emu128: { element in emulatedMultiplyAlternating(negatingAll: negatingAll, for: element) }
    )
}

func portableRemainder(for element: Element) -> String {
    let quotient = operationCall("dividing", ["a", "b"], for: element)
    let remainder = operationCall("negatedMultiplyAdding", ["quotient", "b", "a"], for: element)
    return """
        const \(element.cVector) quotient = \(quotient);
        \(vectorResult(remainder, for: element))
        """
}

func emulatedMultiplyingHigh(for element: Element) -> String? {
    guard !isInteger64(element) else { return nil }
    let wide = widenedElement(of: element)
    let highs = laneIndices(Array(stride(from: 1, to: 2 * element.laneCount, by: 2)))
    let halves = "(half_vector)product"
    let narrowed = "__builtin_shufflevector(\(halves), \(halves), \(highs))"
    return """
        \(vectorTypedef("wide_vector", of: wide, lanes: element.laneCount))
        \(vectorTypedef("half_vector", of: element, lanes: 2 * element.laneCount))
        const wide_vector product = __builtin_convertvector(a, wide_vector) * __builtin_convertvector(b, wide_vector);
        \(vectorResult(narrowed, for: element))
        """
}

func portableMultiplyingHigh(for element: Element) -> String {
    guard isInteger64(element) else {
        let wide = widenedElement(of: element)
        let narrowed = "__builtin_convertvector(product >> \(element.bits), \(element.cVector))"
        return """
            \(vectorTypedef("wide_vector", of: wide, lanes: element.laneCount))
            const wide_vector product = __builtin_convertvector(a, wide_vector) * __builtin_convertvector(b, wide_vector);
            \(vectorResult(narrowed, for: element))
            """
    }
    let lane = element.cUnsignedLane
    let halfBits = element.bits / 2
    let isSigned = element.category == .signedInteger
    let wide = isSigned ? "__int128" : "unsigned __int128"
    let corrections =
        isSigned
        ? " - ((\(lane))(a[i] >> \(element.bits - 1)) & second) - ((\(lane))(b[i] >> \(element.bits - 1)) & first)"
        : ""
    return """
        \(element.cVector) high;
        for (size_t i = 0; i < \(element.laneCount); ++i) {
        #if defined(__SIZEOF_INT128__)
          high[i] = (\(element.cType))(((\(wide))a[i] * (\(wide))b[i]) >> \(element.bits));
        #else
          const \(lane) first = (\(lane))a[i];
          const \(lane) second = (\(lane))b[i];
          const \(lane) loLo = (first & 0xffffffff) * (second & 0xffffffff);
          const \(lane) hiLo = (first >> \(halfBits)) * (second & 0xffffffff);
          const \(lane) loHi = (first & 0xffffffff) * (second >> \(halfBits));
          const \(lane) hiHi = (first >> \(halfBits)) * (second >> \(halfBits));
          const \(lane) t = (loLo >> \(halfBits)) + (hiLo & 0xffffffff) + loHi;
          high[i] = (\(element.cType))((hiLo >> \(halfBits)) + (t >> \(halfBits)) + hiHi\(corrections));
        #endif
        }
        \(vectorResult("high", for: element))
        """
}

func multiplyingFixedPoint15Product(for element: Element) -> String {
    let wide = widenedElement(of: element)
    return """
        \(vectorTypedef("wide_vector", of: wide, lanes: element.laneCount))
        const wide_vector product = __builtin_convertvector(a, wide_vector) * __builtin_convertvector(b, wide_vector);
        const wide_vector rounded = (product + 16384) >> 15;
        """
}

func portableMultiplyingFixedPoint15(saturating: Bool, for element: Element) -> String {
    let limit = splat("32767", as: "wide_vector", lanes: element.laneCount)
    let narrowed =
        saturating
        ? "__builtin_convertvector(__builtin_elementwise_min(rounded, \(limit)), \(element.cVector))"
        : "__builtin_convertvector(rounded, \(element.cVector))"
    return """
        \(multiplyingFixedPoint15Product(for: element))
        \(vectorResult(narrowed, for: element))
        """
}

func neonMultiplyingFixedPoint15(for element: Element) -> String {
    vectorResult(
        neonBuiltin("vqrdmulhq_v", ["a", "b"], code: neonTypeCode(of: element), for: element),
        for: element
    )
}

func sveMultiplyingFixedPoint15(for element: Element) -> String {
    let operands = [sveOperand("a", for: element), sveOperand("b", for: element)]
    let product = sveBuiltin("qrdmulh", operands, for: element)
    return vectorResult(sveResult(product, for: element), for: element)
}

func x86MultiplyingFixedPoint15(level: X86Level, for element: Element) -> String? {
    guard level >= .ssse3 else { return x86Sse2MultiplyingFixedPoint15(for: element) }
    let rounded = x86Builtin(
        "pmulhrsw\(x86Bits(element.width))",
        ["a", "b"],
        as: "i16",
        returning: element.cVector
    )
    return vectorResult(rounded, for: element)
}

enum FloatRounding {
    case nearestEven
    case towardZero
    case up
    case down

    var builtin: String {
        switch self {
        case .nearestEven: return "roundeven"
        case .towardZero: return "trunc"
        case .up: return "ceil"
        case .down: return "floor"
        }
    }
}

func mantissaEnd(of element: Element) -> String {
    element.bits == 32 ? "8388608.0f" : "4503599627370496.0"
}

func scalarAbsolute(of element: Element) -> String {
    element.bits == 32 ? "__builtin_fabsf" : "__builtin_fabs"
}

func signBitMask(for element: Element) -> String {
    splat(
        "0x\(String(UInt64(1) << UInt64(element.bits - 1), radix: 16))",
        as: element.cUnsignedVector,
        lanes: element.laneCount
    )
}

func vectorRounded(
    _ rounding: FloatRounding,
    of operand: String = "a",
    for element: Element
) -> String {
    vectorResult("__builtin_elementwise_\(rounding.builtin)(\(operand))", for: element)
}

func emulatedLanes(
    from expression: String,
    for element: Element,
    _ statements: (_ lanes: String) -> String
) -> String {
    """
    \(element.cType) lanes[\(element.laneCount)];
    for (size_t i = 0; i < \(element.laneCount); ++i) {
      lanes[i] = \(expression);
    }
    \(statements("lanes"))
    \(element.cVector) result;
    for (size_t i = 0; i < \(element.laneCount); ++i) {
      result[i] = lanes[i];
    }
    \(vectorResult("result", for: element))
    """
}

func absoluteLanes(for element: Element) -> String {
    """
    \(element.cType) absolute[\(element.laneCount)];
    for (size_t i = 0; i < \(element.laneCount); ++i) {
      absolute[i] = \(scalarAbsolute(of: element))(lanes[i]);
    }
    """
}

func portableNearestRounded(from expression: String, for element: Element) -> String {
    let integer = signedElement(of: element).cType
    let absolute = scalarAbsolute(of: element)
    return emulatedLanes(from: expression, for: element) { _ in
        """
        \(absoluteLanes(for: element))
        for (size_t i = 0; i < \(element.laneCount); ++i) {
          if (!(absolute[i] < \(mantissaEnd(of: element)))) {
            continue;
          }
          const \(element.cType) bias = lanes[i] < 0 ? -0.5 : 0.5;
          const \(integer) rounded = (\(integer))(lanes[i] + bias);
          if (rounded == 0) {
            lanes[i] = __builtin_signbit(lanes[i]) ? -0.0 : 0.0;
            continue;
          }
          const \(element.cType) roundedLane = (\(element.cType))rounded;
          if ((rounded & 1) && \(absolute)(roundedLane - lanes[i]) == 0.5) {
            const \(element.cType) even = (\(element.cType))(rounded - (lanes[i] < 0 ? -1 : 1));
            lanes[i] = even == 0 && __builtin_signbit(lanes[i]) ? -0.0 : even;
            continue;
          }
          lanes[i] = roundedLane;
        }
        """
    }
}

func portableMultiplyingRounded(for element: Element) -> String {
    withoutContraction(portableNearestRounded(from: "a[i] * b[i]", for: element))
}

func x86NearestRounded(of operand: String, for element: Element) -> String {
    let limit = splat(mantissaEnd(of: element), as: element.cVector, lanes: element.laneCount)
    let signMask = signBitMask(for: element)
    return """
        const \(element.cVector) limit = \(limit);
        const \(element.cUnsignedVector) signs = \(unsignedBits(operand, of: element)) & \(signMask);
        const \(element.cVector) large = \(fromUnsignedBits("\(unsignedBits("limit", of: element)) | signs", of: element));
        const \(element.cVector) rounded = (\(operand) + large) - large;
        const \(element.cVector) signed_rounded = \(fromUnsignedBits("(\(unsignedBits("rounded", of: element)) & ~\(signMask)) | signs", of: element));
        const \(element.cMask) exact = (\(element.cMask))(__builtin_elementwise_abs(\(operand)) < limit);
        \(vectorResult(bitSelect("exact", "signed_rounded", operand, of: element), for: element))
        """
}

func x86MultiplyingRounded(for element: Element) -> String {
    """
    const \(element.cVector) product = a * b;
    \(x86NearestRounded(of: "product", for: element))
    """
}

enum FloorExponent {
    case emulated
    case vector
    case neon
    case magic
    case sve
}

enum ExponentIsolation {
    case operand
    case raised
}

func multiplyingByFloorPowerOf2(
    _ conversion: FloorExponent,
    isolating: ExponentIsolation? = nil,
    for element: Element
) -> String {
    let lanes = element.laneCount
    let exponents = signedElement(of: element).at(width: element.width)
    let (integer, mask) = (exponents.cVector, element.cMask)
    let bias = maxExponentField(of: element) >> 1
    let mantissaWidth = mantissaBits(of: element)
    let isHalf = element.category == .float16
    let arithmetic = isHalf ? "native_vector" : element.cVector
    let (first, second) = isHalf ? ("nativeA", "nativeB") : ("a", "b")
    func floating(_ value: Int) -> String {
        splat("\(value).0", as: element.cVector, lanes: lanes)
    }
    func integers(_ value: Int) -> String {
        splat("\(value)", as: integer, lanes: lanes)
    }
    func clamped(_ operand: String, _ lowest: Int, _ highest: Int) -> String {
        "__builtin_elementwise_min(__builtin_elementwise_max(\(operand), \(integers(lowest))), \(integers(highest)))"
    }
    func clampedWords(_ operand: String, _ lowest: Int, _ highest: Int) -> String {
        let words = x86Vector("i16")
        let (low, high) = (integers(lowest), integers(highest))
        let raised = "__builtin_elementwise_max((\(words))\(operand), (\(words))\(low))"
        return "(\(integer))__builtin_elementwise_min(\(raised), (\(words))\(high))"
    }
    func factor(_ exponent: String) -> String {
        "(\(arithmetic))((\(exponent) + \(integers(bias))) << \(mantissaWidth))"
    }
    func narrowClamp(_ operand: String, _ lowest: Int, _ highest: Int) -> String {
        conversion == .magic
            ? clampedWords(operand, lowest, highest) : clamped(operand, lowest, highest)
    }
    let scaling: String
    switch conversion {
    case .sve:
        let all = sveAllLanes(of: element)
        let rounded = sveBuiltin(
            "rintm",
            [all, sveOperand("b", for: element)],
            for: element,
            predication: "x"
        )
        let integerType = signedElement(of: element)
        let converted = sveBuiltin(
            "cvt_\(sveSuffix(of: integerType))",
            [all, rounded],
            for: element,
            predication: "x"
        )
        let scaledLanes = sveBuiltin(
            "scale",
            [all, sveOperand("a", for: element), converted],
            for: element,
            predication: "x"
        )
        scaling = "const \(element.cVector) scaled = \(sveResult(scaledLanes, for: element));"
    default:
        let exponent: String
        switch conversion {
        case .neon:
            let builtin =
                isHalf
                ? "__builtin_neon_vcvtmq_s16_f16" : "__builtin_neon_vcvtmq_s\(element.bits)_v"
            let operand = "(\(neonVector("i8")))b"
            exponent = """
                const \(integer) converted = (\(integer))\(builtin)(\(operand), \(neonTypeCode(of: exponents)));
                const \(integer) exponent = \(clamped("converted", 3 - 3 * bias, 3 * bias));
                """
        case .magic:
            let magic = element.bits == 32 ? "12582912.0f" : "6755399441055744.0"
            let magnitudes = splat(magic, as: element.cVector, lanes: lanes)
            let (lowest, highest) = (floating(3 - 3 * bias), floating(3 * bias))
            func isolation(_ stage: ExponentIsolation, _ name: String, _ source: String) -> String {
                guard isolating == stage else { return "" }
                return """
                    \(element.cVector) \(name) = \(source);
                    __asm__("" : "+x"(\(name)));

                    """
            }
            let operand = isolating == .operand ? "isolated" : "b"
            let raised = isolating == .raised ? "floored" : "raised"
            exponent = """
                \(isolation(.operand, "isolated", "b"))const \(element.cVector) \(raised) = \(bitSelect("(\(mask))(\(operand) > \(lowest))", operand, lowest, of: element));
                \(isolation(.raised, "raised", "floored"))const \(element.cVector) limited = \(bitSelect("(\(mask))(raised < \(highest))", "raised", highest, of: element));
                const \(element.cVector) magic = \(magnitudes);
                const \(element.cVector) shifted = limited + magic;
                const \(integer) rounded = (\(integer))shifted - (\(integer))magic;
                const \(integer) exponent = rounded + (\(integer))(shifted - magic > limited);
                """
        default:
            let floor =
                conversion == .vector
                ? x86Floored(of: "b", for: element) : "__builtin_elementwise_floor(b)"
            let raised = "__builtin_elementwise_max(\(floor), \(floating(3 - 3 * bias)))"
            let bounded = "__builtin_elementwise_min(\(raised), \(floating(3 * bias)))"
            let direct =
                "const \(integer) exponent = __builtin_convertvector(\(bounded), \(integer));"
            if conversion == .emulated {
                exponent = """
                    #if defined(__APPLE__)
                    \(integer) floored = __builtin_convertvector(\(bounded), \(integer));
                    if (__builtin_constant_p(__builtin_reduce_or(\(unsignedBits("b", of: element))))) {
                      volatile \(integer) spilled = floored;
                      floored = spilled;
                    }
                    const \(integer) exponent = floored;
                    #else
                    \(direct)
                    #endif
                    """
            } else {
                exponent = direct
            }
        }
        let product =
            "((\(first) * \(factor("exponent1"))) * \(factor("exponent2"))) * \(factor("exponent3"))"
        scaling = """
            \(exponent)
            const \(integer) exponent3 = \(narrowClamp("exponent", 1 - bias, bias));
            const \(integer) remaining = exponent - exponent3;
            const \(integer) exponent2 = \(narrowClamp("remaining", 1 - bias, bias));
            const \(integer) exponent1 = remaining - exponent2;
            const \(element.cVector) scaled = \(isHalf ? "(\(element.cVector))(\(product))" : product);
            """
    }
    let infinities = splat(infinity(of: element), as: arithmetic, lanes: lanes)
    let unsigned = element.cUnsignedVector
    let natives =
        isHalf
        ? [
            halfPrecisionNativeVector(for: element),
            "const native_vector nativeA = (native_vector)a;",
            "const native_vector nativeB = (native_vector)b;",
        ].map { "\($0)\n" }.joined() : ""
    return """
        \(natives)\(scaling)
        const \(mask) negative = (\(mask))\(unsignedBits("b", of: element)) < 0;
        const \(arithmetic) target = (\(arithmetic))((\(unsignedBits(infinities, of: element)) & (\(unsigned))negative));
        const \(mask) infinite = (\(mask))(__builtin_elementwise_abs(\(second)) == \(infinities));
        const \(mask) special = (\(mask))(\(second) != \(second)) | (infinite & (\(mask))(__builtin_elementwise_abs(\(first)) == target));
        \(vectorResult(bitSelect("special", splat(scalarNaN(of: element), as: element.cVector, lanes: lanes), "scaled", of: element), for: element))
        """
}

func x86MultiplyingByFloorPowerOf2(for element: Element) -> String {
    let suffix = element.bits == 32 ? "ps" : "pd"
    let floating = x86Vector(element.cSuffix)
    let arguments = [
        (value: "a", type: floating), (value: "b", type: floating),
        (value: compoundLiteral(floating, ["0"]), type: floating),
        (value: "-1", type: x86MaskType(lanes: element.laneCount)),
        (value: "\(x86CurrentRounding)", type: "int"),
    ]
    let scaled = x86Builtin(
        "scalef\(suffix)\(x86Bits(element.width))_mask",
        arguments,
        returning: element.cVector
    )
    return vectorResult(scaled, for: element)
}

func mantissaBits(of element: Element) -> Int {
    switch element.bits {
    case 16: return 10
    case 32: return 23
    default: return 52
    }
}

func maxExponentField(of element: Element) -> Int {
    switch element.bits {
    case 16: return 31
    case 32: return 255
    default: return 2047
    }
}

func portableTruncated(for element: Element) -> String {
    let integer = signedElement(of: element).cType
    return emulatedLanes(from: "a[i]", for: element) { _ in
        """
        \(absoluteLanes(for: element))
        for (size_t i = 0; i < \(element.laneCount); ++i) {
          if (!(absolute[i] <= \(mantissaEnd(of: element)))) {
            continue;
          }
          const \(integer) truncated = (\(integer))lanes[i];
          if (truncated == 0) {
            lanes[i] = __builtin_signbit(lanes[i]) ? -0.0 : 0.0;
            continue;
          }
          lanes[i] = (\(element.cType))truncated;
        }
        """
    }
}

func portableDirectedRounded(towardPositive: Bool, for element: Element) -> String {
    let bits = element.cUnsignedLane
    let (mantissaBits, exponentMask) = (mantissaBits(of: element), maxExponentField(of: element))
    let suffix = element.bits == 32 ? "u" : "ull"
    let fraction = "0x\(String((UInt64(1) << UInt64(mantissaBits)) - 1, radix: 16))\(suffix)"
    let (direction, comparison) = towardPositive ? ("positive", ">") : ("negative", "<")
    let (unit, other) = towardPositive ? ("1.0", "-0.0") : ("-1.0", "0.0")
    return """
        \(element.cVector) result = a;
        for (size_t i = 0; i < \(element.laneCount); ++i) {
          const \(element.cType) value = a[i];
          const bool \(direction) = value \(comparison) 0.0;
          \(bits) bits = __builtin_bit_cast(\(bits), value);
          const int exponent = (int)((bits >> \(mantissaBits)) & \(exponentMask)) - \(exponentMask / 2);
          if (exponent >= \(mantissaBits)) {
            continue;
          }
          if (exponent < 0) {
            if (\(direction)) {
              result[i] = \(unit);
            } else if (value != 0.0) {
              result[i] = \(other);
            }
            continue;
          }
          const \(bits) mantissaMask = \(fraction) >> exponent;
          if ((bits & mantissaMask) == 0) {
            continue;
          }
          if (\(direction)) {
            bits += (\(fraction) + 1) >> exponent;
          }
          bits &= ~mantissaMask;
          result[i] = __builtin_bit_cast(\(element.cType), bits);
        }
        \(vectorResult("result", for: element))
        """
}

func portableRounded(_ rounding: FloatRounding, for element: Element) -> String {
    switch rounding {
    case .nearestEven: return portableNearestRounded(from: "a[i]", for: element)
    case .towardZero: return portableTruncated(for: element)
    case .up: return portableDirectedRounded(towardPositive: true, for: element)
    case .down: return portableDirectedRounded(towardPositive: false, for: element)
    }
}

func x86Rounded(_ rounding: FloatRounding, for element: Element) -> String {
    guard rounding != .nearestEven else { return x86NearestRounded(of: "a", for: element) }
    let vector = element.cVector
    let integers = signedElement(of: element).at(width: element.width).cVector
    let signMask = signBitMask(for: element)
    let float = x86Vector(element.cSuffix)
    let limit = splat(mantissaEnd(of: element), as: vector, lanes: element.laneCount)
    let conversion: String
    if element.bits == 32 {
        let converted = x86Builtin("cvttps2dq", ["a"], as: element.cSuffix, returning: integers)
        conversion = "const \(integers) integer = \(converted);"
    } else {
        let second = "__builtin_shufflevector((\(float))a, (\(float))a, 1, 1)"
        conversion = """
            const long long first = __builtin_ia32_cvttsd2si64((\(float))a);
            const long long second = __builtin_ia32_cvttsd2si64(\(second));
            const \(integers) integer = \(compoundLiteral(integers, ["first", "second"]));
            """
    }
    let adjustment: String
    switch rounding {
    case .up:
        adjustment = """
            const \(element.cMask) below = (\(element.cMask))(truncated < a);
            const \(vector) adjusted = truncated - __builtin_convertvector(below, \(vector));
            """
    case .down:
        adjustment = """
            const \(element.cMask) above = (\(element.cMask))(truncated > a);
            const \(vector) adjusted = truncated + __builtin_convertvector(above, \(vector));
            """
    default:
        adjustment = "const \(vector) adjusted = truncated;"
    }
    let signed = fromUnsignedBits(
        "(\(unsignedBits("adjusted", of: element)) & ~\(signMask)) | signs",
        of: element
    )
    return """
        const \(vector) limit = \(limit);
        \(conversion)
        const \(vector) truncated = __builtin_convertvector(integer, \(vector));
        \(adjustment)
        const \(element.cUnsignedVector) signs = \(unsignedBits("a", of: element)) & \(signMask);
        const \(vector) signed_adjusted = \(signed);
        const \(element.cMask) exact = (\(element.cMask))(__builtin_elementwise_abs(a) < limit);
        \(vectorResult(bitSelect("exact", "signed_adjusted", "a", of: element), for: element))
        """
}

func roundingTargets(_ rounding: FloatRounding) -> TargetBodies<Element> {
    TargetBodies(
        neon: { element in vectorRounded(rounding, for: element) },
        avx3: { element in vectorRounded(rounding, for: element) },
        avx2: { element in vectorRounded(rounding, for: element) },
        sse4: { element in vectorRounded(rounding, for: element) },
        sse2: { element in x86Rounded(rounding, for: element) }
    )
}

func portableApproximateReciprocal(for element: Element) -> String {
    guard element.bits == 32 else {
        let ones = splat("1.0", as: element.cVector, lanes: element.laneCount)
        return vectorResult("\(ones) / a", for: element)
    }
    return """
        \(element.cVector) result;
        for (size_t i = 0; i < \(element.laneCount); ++i) {
          result[i] = \(scalarAbsolute(of: element))(a[i]) == 0.0f ? 0.0f : 1.0f / a[i];
        }
        \(vectorResult("result", for: element))
        """
}

func portableApproximateReciprocalSquareRoot(
    fused: Bool = false,
    outlining: Bool = false,
    for element: Element
) -> String {
    guard element.bits == 64 else {
        return """
            \(element.cVector) result;
            for (size_t i = 0; i < \(element.laneCount); ++i) {
              const float value = a[i];
              const float half = value * 0.5f;
              const uint32_t bits = 0x5F3759DFu - (__builtin_bit_cast(uint32_t, value) >> 1);
              const float guess = __builtin_bit_cast(float, bits);
              result[i] = guess * (1.5f - (half * guess * guess));
            }
            \(vectorResult("result", for: element))
            """
    }
    let (vector, unsigned) = (element.cVector, element.cUnsignedVector)
    let magic = splat("0x5FE6EB50C7B537A9", as: unsigned, lanes: element.laneCount)
    let halves = splat("0.5", as: vector, lanes: element.laneCount)
    let threeHalves = splat("1.5", as: vector, lanes: element.laneCount)
    let fusedCorrection =
        outlining
        ? "\(x86NegatedMultiplyAddingName(for: element))(half * guess, guess, \(threeHalves))"
        : "__builtin_elementwise_fma(-(half * guess), guess, \(threeHalves))"
    let correction = fused ? fusedCorrection : "\(threeHalves) - half * guess * guess"
    let statements = """
        const \(vector) half = a * \(halves);
        const \(vector) guess = (\(vector))(\(magic) - ((\(unsigned))a >> 1));
        \(vectorResult("guess * (\(correction))", for: element))
        """
    return fused ? statements : withoutContraction(statements)
}

func x86Floored(of operand: String, for element: Element) -> String {
    let name = "roundp\(element.bits == 32 ? "s" : "d")\(x86UnsuffixedBits(element.width))"
    let operands = [
        (value: operand, type: x86Vector(element.cSuffix)),
        (value: "\(x86FloorRounding)", type: "int"),
    ]
    return x86Builtin(name, operands, returning: element.cVector)
}

func x86NegatedMultiplyAddingName(for element: Element) -> String {
    "cvectorization_ops_x86_negated_multiply_adding_\(element.cSuffix)"
}

func x86NegatedMultiplyAddingHelper(for element: Element) -> String? {
    guard element.bits == 64 else { return nil }
    let function = cFunction(
        returns: element.cRawVector,
        name: x86NegatedMultiplyAddingName(for: element),
        parameters: ["a", "b", "c"].map { "\(element.cRawVector) \($0)" },
        body:
            "return (\(element.cRawVector))__builtin_elementwise_fma(-(\(element.cVector))a, (\(element.cVector))b, (\(element.cVector))c);",
        specifiers: "CVECTORIZATION_OPS_FUNCTION"
    )
    return "#if !\(x86DisablesFmaCondition)\n\(function)#endif"
}

func neonApproximate(_ name: String, for element: Element) -> String {
    vectorResult(
        neonBuiltin(name, ["a"], code: neonTypeCode(of: element), for: element),
        for: element
    )
}

func x86Approximate(_ name: String, for element: Element) -> String? {
    let suffix = element.bits == 32 ? "ps" : "pd"
    guard element.width == 64 else {
        guard element.bits == 32 else { return nil }
        let estimate = x86Builtin(
            "\(name)ps\(x86UnsuffixedBits(element.width))",
            ["a"],
            as: element.cSuffix,
            returning: element.cVector
        )
        return vectorResult(estimate, for: element)
    }
    let float = x86Vector(element.cSuffix)
    let arguments = [
        (value: "a", type: float), (value: compoundLiteral(float, ["0"]), type: float),
        (value: "-1", type: x86MaskType(lanes: element.laneCount)),
    ]
    let estimate = x86Builtin(
        "\(name)14\(suffix)512_mask",
        arguments,
        returning: element.cVector
    )
    return vectorResult(estimate, for: element)
}

func portableExponent(for element: Element) -> String {
    let (vector, unsigned) = (element.cVector, element.cUnsignedVector)
    let integers = signedElement(of: element).at(width: element.width).cVector
    let signMask = signBitMask(for: element)
    let bias = splat(
        String(maxExponentField(of: element) / 2),
        as: integers,
        lanes: element.laneCount
    )
    let magnitude = "((\(unsigned))a & ~\(signMask)) >> \(mantissaBits(of: element))"
    return """
        const \(integers) exponent = (\(integers))(\(magnitude)) - \(bias);
        \(vectorResult("__builtin_convertvector(exponent, \(vector))", for: element))
        """
}

func sveExponent(for element: Element) -> String {
    let all = sveAllLanes(of: element)
    let integer = signedElement(of: element)
    let exponent = sveBuiltin(
        "logb",
        [all, sveOperand("a", for: element)],
        for: element,
        predication: "x"
    )
    let converted = sveBuiltin(
        "cvt_\(sveSuffix(of: element))",
        [all, exponent],
        for: integer,
        predication: "x"
    )
    return vectorResult(sveResult(converted, for: element), for: element)
}

func x86Exponent(for element: Element) -> String {
    let float = x86Vector(element.cSuffix)
    let arguments = [
        (value: "a", type: float), (value: compoundLiteral(float, ["0"]), type: float),
        (value: "-1", type: x86MaskType(lanes: element.laneCount)),
        (value: "\(x86CurrentRounding)", type: "int"),
    ]
    let exponent = x86Builtin(
        "getexp\(element.bits == 32 ? "ps" : "pd")512_mask",
        arguments,
        returning: element.cVector
    )
    return vectorResult(exponent, for: element)
}

func doubledInfinity(for element: Element) -> String {
    let mask =
        (UInt64.max << UInt64(mantissaBits(of: element) + 1))
        & (UInt64.max >> UInt64(64 - element.bits))
    return splat(
        "0x\(String(mask, radix: 16))",
        as: element.cUnsignedVector,
        lanes: element.laneCount
    )
}

func portableIsInfinite(for element: Element) -> String {
    let unsigned = element.cUnsignedVector
    return """
        const \(unsigned) doubled = (\(unsigned))a + (\(unsigned))a;
        \(maskResult("(\(element.cMask))(doubled == \(doubledInfinity(for: element)))", for: element))
        """
}

func portableIsFinite(for element: Element) -> String {
    let unsigned = element.cUnsignedVector
    let integers = signedElement(of: element).at(width: element.width).cVector
    let limit = splat(String(maxExponentField(of: element)), as: integers, lanes: element.laneCount)
    return """
        const \(unsigned) doubled = (\(unsigned))a + (\(unsigned))a;
        const \(integers) exponent = (\(integers))(doubled >> \(mantissaBits(of: element) + 1));
        \(maskResult("(\(element.cMask))(exponent < \(limit))", for: element))
        """
}

func x86Avx3IsEitherNaN(for element: Element) -> String {
    let float = x86Vector(element.cSuffix)
    let bitsType = x86MaskType(lanes: element.laneCount)
    let arguments = [
        (value: "a", type: float), (value: "b", type: float), (value: "3", type: "int"),
        (value: "-1", type: bitsType), (value: "\(x86CurrentRounding)", type: "int"),
    ]
    let compared = x86Builtin(
        "cmp\(element.bits == 32 ? "ps" : "pd")\(x86Bits(element.width))_mask",
        arguments,
        returning: bitsType
    )
    return x86Avx3MaskVector(compared, for: element)
}

func portableCopyingSign(toMagnitude: Bool, for element: Element) -> String {
    let signMask = signBitMask(for: element)
    guard toMagnitude else {
        return vectorResult(bitSelect(signMask, "b", "a", of: element), for: element)
    }
    let signs = "\(unsignedBits("b", of: element)) & \(signMask)"
    return vectorResult(
        fromUnsignedBits("\(unsignedBits("a", of: element)) | (\(signs))", of: element),
        for: element
    )
}

func sveApproximate(_ name: String, for element: Element) -> String {
    let estimate = sveBuiltin(name, [sveOperand("a", for: element)], for: element)
    return vectorResult(sveResult(estimate, for: element), for: element)
}

func sveCopyingSign(for element: Element) -> String {
    let unsigned = unsignedElement(of: element)
    let signMask = "0x\(String(UInt64(1) << UInt64(element.bits - 1), radix: 16))"
    let selected = sveBuiltin(
        "bsl",
        [
            sveOperand("b", for: unsigned), sveOperand("a", for: unsigned),
            sveBuiltin("dup_n", [signMask], for: unsigned),
        ],
        for: unsigned
    )
    return vectorResult("(\(element.cVector))\(sveResult(selected, for: unsigned))", for: element)
}

func sveIsFinite(for element: Element) -> String {
    let all = sveAllLanes(of: element)
    let (unsigned, signed) = (unsignedElement(of: element), signedElement(of: element))
    let operand = sveOperand("a", for: unsigned)
    let doubled = sveBuiltin("add", [all, operand, operand], for: unsigned, predication: "x")
    let shifted = sveBuiltin(
        "lsr_n",
        [all, doubled, String(mantissaBits(of: element) + 1)],
        for: unsigned,
        predication: "x"
    )
    let reinterpret =
        "__builtin_sve_reinterpret_\(sveSuffix(of: signed))_\(sveSuffix(of: unsigned))"
    let finite = sveBuiltin(
        "cmplt_n",
        [all, "\(reinterpret)(\(shifted))", String(maxExponentField(of: element))],
        for: signed
    )
    let lanes = sveBuiltin(
        "dup_n",
        [finite, "(\(unsigned.cUnsignedLane))-1"],
        for: unsigned,
        predication: "z"
    )
    let constant = "__builtin_constant_p(__builtin_reduce_or(\(unsignedBits("a", of: element))))"
    return """
        if (\(constant)) {
        \(indented(portableIsFinite(for: element)))
        }
        \(maskResult("(\(element.cMask))(\(sveVector(unsigned.cSuffix)))\(lanes)", for: element))
        """
}

func x86Avx3TernaryLogic(_ immediate: Int, _ operands: [String], for element: Element) -> String {
    let i64 = x86Vector("i64")
    let arguments =
        operands.map { (value: $0, type: i64) } + [
            (value: "0x\(String(immediate, radix: 16))", type: "int"),
            (value: "-1", type: x86MaskType(lanes: element.width / 8)),
        ]
    return x86Builtin(
        "pternlogq\(x86Bits(element.width))_mask",
        arguments,
        returning: element.cVector
    )
}

func x86Avx3Ternary(_ immediate: Int, for element: Element) -> String {
    vectorResult(x86Avx3TernaryLogic(immediate, ["a", "b", "c"], for: element), for: element)
}

func x86Avx3CopyingSign(toMagnitude: Bool, for element: Element) -> String {
    let signMask = signBitMask(for: element)
    let ternary =
        toMagnitude
        ? x86Avx3TernaryLogic(0xF8, ["a", signMask, "b"], for: element)
        : x86Avx3TernaryLogic(0xCA, [signMask, "b", "a"], for: element)
    return vectorResult(ternary, for: element)
}

func x86WordwiseInfinite(for element: Element) -> String? {
    guard element.bits == 64 else { return nil }
    let unsigned = element.cUnsignedVector
    let words = unsignedElement(of: unsignedElement(bits: 32)).at(width: element.width)
    let swapped = (0..<words.laneCount).map { $0 ^ 1 }
    let equal = "(\(words.cMask))((\(words.cVector))doubled == (\(words.cVector))limit)"
    let both = "equal & __builtin_shufflevector(equal, equal, \(laneIndices(swapped)))"
    return """
        const \(unsigned) doubled = (\(unsigned))a + (\(unsigned))a;
        const \(unsigned) limit = \(doubledInfinity(for: element));
        const \(words.cMask) equal = \(equal);
        \(maskResult("(\(element.cMask))(\(both))", for: element))
        """
}

func complexLanes(_ operand: String, odd: Bool, for element: Element) -> String {
    let indices = (0..<element.laneCount).map { $0 - $0 % 2 + (odd ? 1 : 0) }
    return "__builtin_shufflevector(\(operand), \(operand), \(laneIndices(indices)))"
}

func wordwiseEvenLanes(_ evens: String, _ odds: String, for element: Element) -> String {
    let wordLanes = 64 / element.bits
    let ones = (UInt64.max >> UInt64(64 - element.bits))
    let word = (0..<wordLanes).filter { $0.isMultiple(of: 2) }.reduce(UInt64(0)) {
        $0 | (ones << UInt64($1 * element.bits))
    }
    let words = x86Vector("i64")
    let mask = splat("0x\(String(word, radix: 16))", as: words, lanes: element.width / 8)
    let (first, second) = ("(\(words))\(evens)", "(\(words))\(odds)")
    return "(\(element.cVector))((\(mask) & \(first)) | (~\(mask) & \(second)))"
}

func complexDuplicates(for element: Element) -> String {
    let vector = element.cVector
    return """
        const \(vector) u = \(complexLanes("a", odd: false, for: element));
        const \(vector) v = \(complexLanes("a", odd: true, for: element));
        const \(vector) x = \(complexLanes("b", odd: false, for: element));
        const \(vector) y = \(complexLanes("b", odd: true, for: element));
        """
}

func twoProductComplexMultiplyingBody(
    conjugating: Bool,
    adding: Bool,
    for element: Element
) -> String {
    let vector = element.cVector
    let swappedIndices = (0..<element.laneCount).map { $0 ^ 1 }
    let (first, second) =
        conjugating
        ? (alternatingLanes("b", negatedLanes("b", for: element), for: element), "swapped")
        : ("b", alternatingLanes(negatedLanes("swapped", for: element), "swapped", for: element))
    let sum = arithmetic(
        "+",
        multipliedLanes("u", "first", for: element),
        multipliedLanes("v", "second", for: element),
        for: element
    )
    return """
        const \(vector) u = \(complexLanes("a", odd: false, for: element));
        const \(vector) v = \(complexLanes("a", odd: true, for: element));
        const \(vector) swapped = __builtin_shufflevector(b, b, \(laneIndices(swappedIndices)));
        const \(vector) first = \(first);
        const \(vector) second = \(second);
        \(vectorResult(adding ? arithmetic("+", sum, "c", for: element) : sum, for: element))
        """
}

func complexMultiplyingBody(
    conjugating: Bool,
    adding: Bool,
    fused: Bool,
    selectingByMask: Bool = false,
    highwayOrder: Bool = false,
    finishing: ((String) -> String)? = nil,
    for element: Element
) -> String {
    let vector = element.cVector
    let isFloat = element.category == .float
    func product(_ first: String, _ second: String) -> String {
        isFloat ? "\(first) * \(second)" : multipliedLanes(first, second, for: element)
    }
    func combined(_ symbol: String, _ first: String, _ second: String) -> String {
        isFloat ? "\(first) \(symbol) \(second)" : arithmetic(symbol, first, second, for: element)
    }
    var accumulations: [String] = []
    func accumulated(_ first: String, _ second: String, _ addend: String) -> String {
        guard isFloat && fused else {
            guard highwayOrder else { return combined("+", addend, product(first, second)) }
            accumulations.append("const \(vector) addend = \(addend);")
            return combined("+", product(first, second), "addend")
        }
        return "__builtin_elementwise_fma(\(first), \(second), \(addend))"
    }
    let (evens, odds) =
        conjugating
        ? (
            accumulated("u", "x", product("v", "y")),
            combined("-", product("v", "x"), product("u", "y"))
        )
        : (
            combined("-", product("u", "x"), product("v", "y")),
            accumulated("u", "y", product("v", "x"))
        )
    let alternated =
        selectingByMask
        ? wordwiseEvenLanes("evens", "odds", for: element)
        : alternatingLanes("evens", "odds", for: element)
    let lanes =
        ([complexDuplicates(for: element)] + accumulations + [
            "const \(vector) odds = \(odds);",
            "const \(vector) evens = \(evens);",
            "const \(vector) multiplied = \(alternated);",
        ]).joined(separator: "\n")
    let result = adding ? combined("+", "multiplied", "c") : "multiplied"
    let finished = finishing?(result) ?? vectorResult(result, for: element)
    let body = "\(lanes)\n\(finished)"
    return isFloat ? withoutContraction(body) : body
}

func emulatedComplexMultiplying(conjugating: Bool, adding: Bool, for element: Element) -> String {
    let isFloat = element.category == .float
    let lane = isFloat ? element.cType : element.cUnsignedLane
    let (evens, odds) =
        conjugating
        ? ("u[i] * x[i] + v[i] * y[i]", "v[i] * x[i] - u[i] * y[i]")
        : ("u[i] * x[i] - v[i] * y[i]", "u[i] * y[i] + v[i] * x[i]")
    let addend = adding ? " + (\(lane))c[i]" : ""
    let body = """
        \(element.cVector) u, v, x, y;
        for (size_t i = 0; i < \(element.laneCount); ++i) {
          u[i] = a[i - i % 2];
          v[i] = a[i | 1];
          x[i] = b[i - i % 2];
          y[i] = b[i | 1];
        }
        \(element.cVector) result;
        for (size_t i = 0; i < \(element.laneCount); ++i) {
          const \(lane) odds = \(odds);
          const \(lane) evens = \(evens);
          result[i] = (\(element.cType))((i % 2 == 0 ? evens : odds)\(addend));
        }
        \(vectorResult("result", for: element))
        """
    return isFloat ? withoutContraction(body) : body
}

func sveComplexMultiplying(conjugating: Bool, adding: Bool, for element: Element) -> String {
    let all = sveAllLanes(of: element)
    let addend =
        adding ? sveOperand("c", for: element) : sveBuiltin("dup_n", ["0.0"], for: element)
    func multiplyAdd(_ accumulator: String, _ rotation: Int) -> String {
        let (first, second) = (sveOperand("a", for: element), sveOperand("b", for: element))
        let operands = conjugating ? [second, first] : [first, second]
        return sveBuiltin(
            "cmla",
            [all, accumulator] + operands + [String(rotation)],
            for: element,
            predication: "x"
        )
    }
    let rotated = multiplyAdd(multiplyAdd(addend, 0), conjugating ? 270 : 90)
    return vectorResult(sveResult(rotated, for: element), for: element)
}

func isSelectedByMask(_ element: Element) -> Bool {
    element.category != .float && element.bits == 16
}

func complexMultiplyingTargets(conjugating: Bool, adding: Bool) -> TargetBodies<Element> {
    func fused(_ element: Element) -> String? {
        element.category == .float
            ? complexMultiplyingBody(
                conjugating: conjugating,
                adding: adding,
                fused: true,
                for: element
            ) : nil
    }
    return TargetBodies(
        neon: fused,
        sve2_128: { element in
            element.category == .float
                ? sveComplexMultiplying(conjugating: conjugating, adding: adding, for: element)
                : twoProductComplexMultiplyingBody(
                    conjugating: conjugating,
                    adding: adding,
                    for: element
                )
        },
        avx3dl: { element in
            element.bits == 8
                ? twoProductComplexMultiplyingBody(
                    conjugating: conjugating,
                    adding: adding,
                    for: element
                ) : nil
        },
        avx3: fused,
        avx2: { element in
            guard element.category == .float else { return nil }
            let unfused = complexMultiplyingBody(
                conjugating: conjugating,
                adding: adding,
                fused: false,
                for: element
            )
            return """
                #if \(x86DisablesFmaCondition)
                \(unfused)
                #else
                \(fused(element) ?? "")
                #endif
                """
        },
        sse4: { element in
            isSelectedByMask(element)
                ? complexMultiplyingBody(
                    conjugating: conjugating,
                    adding: adding,
                    fused: false,
                    for: element
                ) : nil
        },
        sse2: { element in
            isSelectedByMask(element)
                ? complexMultiplyingBody(
                    conjugating: conjugating,
                    adding: adding,
                    fused: false,
                    selectingByMask: true,
                    for: element
                ) : nil
        },
        emu128: { element in
            element.bits >= 32
                ? emulatedComplexMultiplying(
                    conjugating: conjugating,
                    adding: adding,
                    for: element
                ) : nil
        }
    )
}

func sveReversedPairs(of operand: String, for element: Element) -> String {
    let lanes = unsignedElement(bits: element.bits)
    guard element.bits < 64 else {
        let view = sveSplatOperand("((\(lanes.cVector))\(operand))", for: lanes)
        return sveBuiltin("ext", [view, view, "1"], for: lanes)
    }
    let (name, wide) = [8: ("revb", 16), 16: ("revh", 32), 32: ("revw", 64)][element.bits]!
    let wider = unsignedElement(bits: wide)
    return sveBuiltin(
        name,
        [sveAllLanes(of: element), sveOperand(operand, for: wider)],
        for: wider,
        predication: "x"
    )
}

func sveAlternatingSum(
    of first: String,
    reversing second: String,
    for element: Element
) -> (reversed: String, sum: String) {
    let wider = unsignedElement(bits: min(2 * element.bits, 64))
    let (target, source) = (sveSuffix(of: element), sveSuffix(of: wider))
    let reversed = sveReversedPairs(of: second, for: element)
    let reinterpreted =
        target == source ? reversed : "__builtin_sve_reinterpret_\(target)_\(source)(\(reversed))"
    let operands = [first, "reversed", "90"]
    let sum =
        element.category == .float || element.category == .float16
        ? sveBuiltin("cadd", [sveAllLanes(of: element)] + operands, for: element, predication: "x")
        : sveBuiltin("cadd", operands, for: element)
    return ("const \(sveType(of: element)) reversed = \(reinterpreted);", sum)
}

func sveAddingSubtracting(for element: Element) -> String {
    let first = sveOperand("a", for: element, splat: true)
    let (reversed, sum) = sveAlternatingSum(of: first, reversing: "b", for: element)
    return """
        \(reversed)
        \(vectorResult(sveResult(sum, for: element), for: element))
        """
}

func sveConstantMultiplyAlternating(negatingAll: Bool, for element: Element) -> String? {
    guard element.category == .float, let minusZero = sveBlockedLiteral(.minusZero, for: element)
    else { return nil }
    let constant = cFunctionName("sveConstant", element)
    let negation = sveBuiltin(
        "neg",
        [sveAllLanes(of: element), sveOperand("c", for: element)],
        for: element,
        predication: "x"
    )
    let zero = sveBuiltin("dup_n", [minusZero], for: element)
    let (reversed, sum) = sveAlternatingSum(
        of: zero,
        reversing: negatingAll ? "negated" : "c",
        for: element
    )
    let negated = "const \(element.cVector) negated = \(sveResult(negation, for: element));"
    let statements =
        (negatingAll ? [negated] : []) + [
            reversed, "const \(element.cVector) addend = \(sveResult(sum, for: element));",
            sveMultiplyAdding(adding: "addend", for: element),
        ]
    return """
        if (\(constant)(a) || \(constant)(b)) {
          \(statements.joined(separator: "\n  "))
        }
        """
}

func svePairwiseSubtracting(for element: Element) -> String? {
    guard element.bits == 64 else { return nil }
    let operands = [
        sveOperand("a", for: element, splat: true), sveOperand("b", for: element, splat: true),
    ]
    let (evens, odds) = (
        sveBuiltin("trn1", operands, for: element), sveBuiltin("trn2", operands, for: element)
    )
    let difference = sveBuiltin(
        "sub",
        [sveAllLanes(of: element), odds, evens],
        for: element,
        predication: "x"
    )
    return vectorResult(sveResult(difference, for: element), for: element)
}

func svePredicatedBinary(
    _ name: String,
    predication: String = "x",
    for element: Element
) -> String {
    let operands = [
        sveOperand("a", for: element, splat: true), sveOperand("b", for: element, splat: true),
    ]
    let combined = sveBuiltin(
        name,
        [sveAllLanes(of: element)] + operands,
        for: element,
        predication: predication
    )
    return vectorResult(sveResult(combined, for: element), for: element)
}

func sveAbsoluteDifference(for element: Element) -> String? {
    isInteger64(element) ? svePredicatedBinary("abd", for: element) : nil
}

func sveConstantNaNAbsoluteDifference(for element: Element) -> String? {
    guard element.category == .float || element.category == .float16 else { return nil }
    let constantNaN = cFunctionName("constantNaN", element)
    return """
        if (\(constantNaN)(a) || \(constantNaN)(b)) {
          \(svePredicatedBinary("abd", for: element))
        }
        """
}

func x86Pairwise(subtracting: Bool, for element: Element) -> String? {
    let combination =
        subtracting
        ? arithmetic("-", "odds", "evens", for: element)
        : arithmetic("+", "evens", "odds", for: element)
    let combined = vectorResult(combination, for: element)
    switch element.bits {
    case 8, 16:
        let wide = unsignedElement(bits: 2 * element.bits)
        let ones = (UInt64(1) << UInt64(2 * element.bits)) - 1
        let upper = ones & ~((UInt64(1) << UInt64(element.bits)) - 1)
        let mask = splat(
            "0x\(String(upper, radix: 16))",
            as: "wide_vector",
            lanes: element.laneCount / 2
        )
        let selecting = cFunctionName("selecting", element)
        func selected(_ yes: String, _ no: String) -> String {
            let operands = [
                "(\(element.cRawMask))oddMask", "(\(element.cRawVector))\(yes)",
                "(\(element.cRawVector))\(no)",
            ]
            return "(\(element.cVector))\(selecting)(\(operands.joined(separator: ", ")))"
        }
        return """
            \(vectorTypedef("wide_vector", of: wide, lanes: element.laneCount / 2))
            const wide_vector wideA = (wide_vector)a;
            const wide_vector wideB = (wide_vector)b;
            const \(element.cVector) shiftedA = (\(element.cVector))(wideA >> \(element.bits));
            const \(element.cVector) shiftedB = (\(element.cVector))(wideB << \(element.bits));
            const wide_vector oddMask = \(mask);
            const \(element.cVector) evens = \(selected("shiftedB", "a"));
            const \(element.cVector) odds = \(selected("b", "shiftedA"));
            \(combined)
            """
    case 32 where element.width == 16:
        let floats = x86Vector("f32")
        func shuffled(_ first: String, _ second: String, _ immediate: Int) -> String {
            "__builtin_ia32_shufps((\(floats))\(first), (\(floats))\(second), \(immediate))"
        }
        return """
            const \(floats) evenParts = \(shuffled("a", "b", 0x88));
            const \(floats) oddParts = \(shuffled("a", "b", 0xdd));
            const \(element.cVector) evens = (\(element.cVector))\(shuffled("evenParts", "evenParts", 0xd8));
            const \(element.cVector) odds = (\(element.cVector))\(shuffled("oddParts", "oddParts", 0xd8));
            \(combined)
            """
    default:
        return nil
    }
}

func x86MultiplyingHigh(level: X86Level, for element: Element) -> String? {
    let isSigned = element.category == .signedInteger
    let portable = portableMultiplyingHigh(for: element)
    switch element.bits {
    case 8 where level < .avx3:
        let wide = widenedElement(of: element)
        let lanes = element.laneCount / 2
        func halves(_ operand: String) -> (even: String, odd: String) {
            let odd = "\(operand) >> 8"
            guard isSigned else { return ("\(operand) & 0xff", odd) }
            return ("(wide_vector)((unsigned_wide_vector)\(operand) << 8) >> 8", odd)
        }
        let (a, b) = (halves("wideA"), halves("wideB"))
        let mask = splat("0xff00", as: "unsigned_wide_vector", lanes: lanes)
        let operands = [
            "(\(element.cRawMask))oddMask", "(\(element.cRawVector))odds",
            "(\(element.cRawVector))evens",
        ]
        let selected = "\(cFunctionName("selecting", element))(\(operands.joined(separator: ", ")))"
        return """
            \(vectorTypedef("wide_vector", of: wide, lanes: lanes))
            \(vectorTypedef("unsigned_wide_vector", of: unsignedElement(bits: 16), lanes: lanes))
            const wide_vector wideA = (wide_vector)a;
            const wide_vector wideB = (wide_vector)b;
            const wide_vector evenProducts = (\(a.even)) * (\(b.even));
            const wide_vector oddProducts = (\(a.odd)) * (\(b.odd));
            const \(element.cVector) odds = (\(element.cVector))oddProducts;
            const \(element.cVector) evens = (\(element.cVector))((unsigned_wide_vector)evenProducts >> 8);
            const unsigned_wide_vector oddMask = \(mask);
            \(vectorResult(selected, for: element))
            """
    case 32 where !isSigned && level < .sse4:
        let (integers, floats) = (x86Vector("i32"), x86Vector("f32"))
        let evens = x86Builtin("pmuludq128", ["a", "b"], as: "i32", returning: floats)
        let odds = x86Builtin("pmuludq128", ["oddA", "oddB"], as: "i32", returning: floats)
        return """
            const \(integers) oddA = __builtin_shufflevector((\(integers))a, (\(integers))a, 1, 1, 3, 3);
            const \(integers) oddB = __builtin_shufflevector((\(integers))b, (\(integers))b, 1, 1, 3, 3);
            const \(floats) evens = \(evens);
            const \(floats) odds = \(odds);
            const \(floats) halves = __builtin_ia32_shufps(evens, odds, 0xdd);
            \(vectorResult("__builtin_ia32_shufps(halves, halves, 0xd8)", for: element))
            """
    case 32 where level < .avx3:
        return portable
    case 64:
        return x86MultiplyingHigh64(for: element)
    default:
        return nil
    }
}

func x86MultiplyingHigh64(for element: Element) -> String {
    let integers = x86Vector("i32")
    let unsigned = element.cUnsignedVector
    let lanes = element.laneCount * 2
    let swapped = laneIndices((0..<lanes).map { $0 ^ 1 })
    func product(_ first: String, _ second: String) -> String {
        x86Builtin(
            "pmuludq\(x86Bits(element.width))",
            [first, second],
            as: "i32",
            returning: unsigned
        )
    }
    let lowMask = splat("0xffffffff", as: unsigned, lanes: element.laneCount)
    let isSigned = element.category == .signedInteger
    let corrections =
        isSigned
        ? [
            "const \(element.cVector) aSigns = a >> 63;",
            "const \(element.cVector) bSigns = b >> 63;",
        ] : []
    let signed =
        "(\(unsigned))unsignedHigh - (\(unsigned))(aSigns & b) - (\(unsigned))(a & bSigns)"
    let result = vectorResult(isSigned ? signed : "unsignedHigh", for: element)
    return
        ([
            "const \(integers) a32 = (\(integers))a;",
            "const \(integers) b32 = (\(integers))b;",
            "const \(integers) aSwapped = __builtin_shufflevector(a32, a32, \(swapped));",
            "const \(integers) bSwapped = __builtin_shufflevector(b32, b32, \(swapped));",
            "const \(unsigned) lowProducts = \(product("a32", "b32"));",
            "const \(unsigned) lowMask = \(lowMask);",
            "const \(unsigned) middle = \(product("aSwapped", "b32")) + (lowProducts >> 32);",
            "const \(unsigned) carried = \(product("a32", "bSwapped")) + (middle & lowMask);",
            "const \(unsigned) unsignedHigh = \(product("aSwapped", "bSwapped")) + (middle >> 32) + (carried >> 32);",
        ] + corrections + [result]).joined(separator: "\n")
}

func x86Sse2MultiplyingFixedPoint15(for element: Element) -> String {
    let words = x86Vector("i16")
    let (integers, unsignedWords) = (x86Vector("i32"), element.cUnsignedVector)
    let high = x86Builtin("pmulhw128", ["a", "b"], as: "i16", returning: words)
    let increment = splat("0x4000", as: integers, lanes: element.laneCount / 2)
    func rounded(_ parts: String) -> String {
        "((\(integers))\(parts) + \(increment)) >> 15"
    }
    let low = (0..<4).flatMap { [$0, $0 + 8] }
    let upper = (4..<8).flatMap { [$0, $0 + 8] }
    let packed = x86Packing("packssdw", "lowParts", "highParts", from: "i32", to: "i16", width: 16)
    return """
        const \(unsignedWords) products = (\(unsignedWords))a * (\(unsignedWords))b;
        const \(words) highProducts = \(high);
        const \(words) lowSums = __builtin_shufflevector((\(words))products, highProducts, \(laneIndices(low)));
        const \(words) highSums = __builtin_shufflevector((\(words))products, highProducts, \(laneIndices(upper)));
        const \(integers) lowParts = \(rounded("lowSums"));
        const \(integers) highParts = \(rounded("highSums"));
        \(vectorResult(packed, for: element))
        """
}

struct LookupSize {
    let lanes: Int
    let applies: Applies
}

let lookupSizes = [
    LookupSize(lanes: 8, applies: .allAndFloat16(bits: [16, 32, 64])),
    LookupSize(lanes: 16, applies: .allAndFloat16(bits: [16, 32, 64])),
    LookupSize(lanes: 32, applies: .integer(bits: [8])),
    LookupSize(lanes: 64, applies: .integer(bits: [8])),
]

enum LaneCapability {
    case lookup(LookupSize)
    case reversal(lanes: Int)

    var name: String {
        switch self {
        case .lookup(let size): return "canLookup\(size.lanes)"
        case .reversal(let lanes): return "canReverse\(lanes)"
        }
    }

    var opName: String {
        switch self {
        case .lookup(let size): return "lookup\(size.lanes)"
        case .reversal(let lanes): return "reversed\(lanes)"
        }
    }

    var operation: String {
        switch self {
        case .lookup: return "lookup"
        case .reversal: return "reversal"
        }
    }

    var applies: Applies {
        switch self {
        case .lookup(let size): return size.applies
        case .reversal: return Applies.all.including(halfPrecisionElements)
        }
    }

    var check: Check {
        (name, "Vector has too few lanes for this \(operation)")
    }

    var disabling: Disabling {
        ("!H.\(name)", "Highway's \(operation) needs more lanes than this target has")
    }

    func isChecked(for element: Element) -> Bool {
        switch self {
        case .lookup: return true
        case .reversal(let lanes): return element.at(width: 16).laneCount < lanes
        }
    }

    func body(for element: Element) -> String {
        let lanes = "sizeof(\(element.cVector)) / sizeof(\(element.cType))"
        switch self {
        case .lookup(let size):
            let enough = "return \(lanes) >= \(size.lanes / 2);"
            guard size.lanes == 64 else { return enough }
            return """
                #if \(neonCondition) == \(ArmLevel.neon.rawValue)
                return true;
                #else
                \(enough)
                #endif
                """
        case .reversal(let count):
            return "return \(lanes) >= \(count);"
        }
    }

    func reference(for element: Element) -> String {
        switch self {
        case .lookup(let size): return "hn::CanLookup\(size.lanes)(\(element.tag)())"
        case .reversal(let lanes): return "hn::Lanes(\(element.tag)()) >= \(lanes)"
        }
    }
}

let laneCapabilities =
    lookupSizes.map(LaneCapability.lookup) + [4, 8].map { LaneCapability.reversal(lanes: $0) }

func laneCapabilityChecks(of op: Op, for element: Element) -> [Check] {
    guard let capability = op.laneCapability, capability.isChecked(for: element) else { return [] }
    return indexChecks(of: op, for: element) + [capability.check]
}

func takesPointerIndices(_ op: Op) -> Bool {
    op.parameters.contains(where: \.isPointerIndices)
}

/// The ops whose types depend on more than the element type of their protocol's conformer.
func isOutsideProtocols(_ op: Op) -> Bool {
    takesPointerIndices(op) || op.parameters.contains(.constIndexPointer) || usesNarrowTypes(op)
}

func usesNarrowTypes(_ op: Op) -> Bool {
    switch op.returns {
    case .narrowVector, .narrowMask: return true
    default: break
    }
    return op.parameters.contains { parameter in
        switch parameter {
        case .narrowVector, .sourceNarrowVector, .narrowMask, .sourceNarrowMask: return true
        default: return false
        }
    }
}

/// What a span form of a gather or a scatter checks: that the indices, or the byte offsets, of the
/// lanes it uses select lanes of the span, as a Swift condition and the message for when it fails.
func gatherChecks(of op: Op, for element: Element) -> [Check] {
    guard let parameter = op.parameters.first(where: \.isPointerIndices) else { return [] }
    let indexElement = signedElement(of: element)
    let isOffsets = parameter == .pointerOffsets
    let operand = isOffsets ? "byteOffsets" : "indices"
    let stride = isOffsets ? "MemoryLayout<Lane>.stride" : "1"
    let limit = "\(indexElement.namespace).indexLimit(count: span.count, stride: \(stride))"
    let message =
        isOffsets
        ? "Byte offset is negative or leaves no room for a lane in the span"
        : "Index is negative or past the end of the span"
    let used =
        op.parameters.contains(.whereMask)
        ? "mask.raw" : op.parameters.contains(.count) ? "firstLanes(count: count).raw" : nil
    guard let used else {
        let within = cFunctionName(
            indicesWithinName(perByte: false, for: indexElement),
            indexElement
        )
        return [("\(within)(\(operand).raw, 0, \(limit))", message)]
    }
    let gathering = op.parameters.contains(.constLanePointer)
    let within = cFunctionName(indicesWithinWhereName(gathering: gathering), element)
    return [("\(within)(\(operand).raw, \(limit), \(used))", "\(message), for a lane in use")]
}

/// What a span form of `loadIndices` checks of the indices it loads: that they select lanes of two
/// vectors, as `indices(from:)` checks them.
func loadedIndexChecks(of op: Op, for element: Element) -> [Check] {
    guard op.parameters.contains(.constIndexPointer) else { return [] }
    let indexElement = laneIndexElement(of: element)
    let within = cFunctionName(indicesWithinName(perByte: false, for: indexElement), indexElement)
    let load = cFunctionName(op.identifier, element)
    let contract = IndexContract.lanesOfTwoTables
    let count = contract.count.expression(laneCount: "laneCount")
    let indices = "unsafe \(load)($0.baseAddress.unsafelyUnwrapped)"
    return [
        (
            "span.withUnsafeBufferPointer { \(within)(\(indices), \(contract.offset), \(count)) }",
            contract.message
        )
    ]
}

/// The members of an element that indexes gathers and scatters: the limit their span forms check
/// the indices, or the byte offsets, against, as the `size_t` the check takes. It counts those that
/// select a whole lane, up to `1 << (bits - 1)` so that negative ones fail, without overflowing for
/// any count, also where `Int` has 32 bits.
func indexLimitMembers(for element: Element) -> String {
    let gathered = elements.filter { indexed in
        ops.contains { op in
            op.parameters.contains(where: \.isPointerIndices) && op.applies.matches(indexed)
        }
    }
    guard gathered.contains(where: { signedElement(of: $0).suffix == element.suffix }) else {
        return ""
    }
    let maximum = "1 << \(element.bits - 1)"
    return """
            @export(implementation) @inline(always)
            package static func indexLimit(count: Int, stride: Int) -> Int {
                guard count > 0 else { return 0 }
                let lanes = Swift.min(UInt64(count), (\(maximum)) / UInt64(stride) + 1)
                return Int(truncatingIfNeeded: Swift.min((lanes - 1) * UInt64(stride) + 1, \(maximum)))
            }


        """
}

func spanOpChecks(of op: Op, for element: Element) -> [Check] {
    laneCapabilityChecks(of: op, for: element) + gatherChecks(of: op, for: element)
        + loadedIndexChecks(of: op, for: element)
}

func laneCapabilityStatements(of op: Op, for element: Element) -> String {
    let function = isUnsafe(op) ? "assert" : "precondition"
    return laneCapabilityChecks(of: op, for: element)
        .map { "        \(function)(\($0.condition), \"\($0.message)\")\n" }.joined()
}

func laneCapabilityMembers(for element: Element) -> String {
    var output = ""
    for capability in laneCapabilities where capability.applies.matches(element) {
        let name = capability.name
        output += "    @export(implementation) @inline(always)\n"
        output += "    public static var \(name): Bool { \(cFunctionName(name, element))() }\n\n"
    }
    return output
}

func laneCapabilityRequirements(indent: String) -> String {
    laneCapabilities.filter { classicElements.allSatisfy($0.applies.matches) }.map {
        """
        \(indent)/// Whether a `Vector` holds enough lanes for `\($0.opName)` on the target this was compiled for.
        \(indent)static var \($0.name): Bool { get }


        """
    }.joined()
}

func x86Sse2LookupTables(for element: Element) -> Element {
    element.bits == 64 ? laneIndexElement(of: element) : element
}

func lookupBody(lanes: Int, aligned: Bool, tables: Element? = nil, for element: Element) -> String {
    let vector = element.cVector
    let raw = element.cRawVector
    func pointer(_ expression: String, alignment: Int) -> String {
        aligned ? "__builtin_assume_aligned(\(expression), \(alignment))" : expression
    }
    guard element.laneCount >= lanes else {
        let tables = tables ?? element
        let tableVector = tables.cVector
        let tableRaw = tables.cRawVector
        let function = cFunctionName("twoTablesLookupLanes", tables)
        let call = "\(function)((\(tableRaw))first, (\(tableRaw))second, rawIndices)"
        return """
            \(tableVector) first;
            \(tableVector) second;
            __builtin_memcpy(&first, \(pointer("from", alignment: element.width)), sizeof first);
            __builtin_memcpy(&second, \(pointer("from + \(lanes / 2)", alignment: element.width)), sizeof second);
            \(tableVector == vector ? "return \(call);" : vectorResult(call, for: element))
            """
    }
    let bytes = lanes * element.bits / 8
    let function = cFunctionName("tableLookupLanes", element)
    let table = pointer("from", alignment: bytes)
    let load =
        bytes < element.width
        ? zeroExtendedLoad(from: table, bytes: bytes, for: element)
        : "\(vector) table;\n__builtin_memcpy(&table, \(table), \(bytes));"
    return """
        \(load)
        return \(function)((\(raw))table, rawIndices);
        """
}

func zeroExtendedLoad(from pointer: String, bytes: Int, for element: Element) -> String {
    let words = bytes / 8
    let part = bytes == 16 ? x86Block("i64") : "half_vector"
    let size = "vector_size(\(bytes))"
    let typedef = bytes == 16 ? "" : "typedef long long half_vector __attribute__((\(size)));\n"
    let zeros = compoundLiteral(part, Array(repeating: "0", count: words))
    let indices = (0..<element.width / 8).map { $0 < words ? $0 : words + ($0 - words) % words }
    let extended = "__builtin_shufflevector(loaded, \(zeros), \(laneIndices(indices)))"
    return """
        \(typedef)\(part) loaded;
        __builtin_memcpy(&loaded, \(pointer), \(bytes));
        const \(element.cVector) table = (\(element.cVector))\(extended);
        """
}

func neonLookup64(for element: Element) -> String {
    let tables = (0..<4).map { block in
        "\(element.cVector) table\(block);\n"
            + "__builtin_memcpy(&table\(block), from + \(16 * block), 16);"
    }
    let names = (0..<4).map { "table\($0)" } + ["indices"]
    let lookup = neonBuiltin("vqtbl4q_v", names, code: 48, for: element)
    return "\(tables.joined(separator: "\n"))\n\(vectorResult(lookup, for: element))"
}

func lookupOp(_ size: LookupSize) -> Op {
    let lanes = size.lanes
    func aligned(_ element: Element) -> String {
        lookupBody(lanes: lanes, aligned: true, for: element)
    }
    return Op(
        "lookup\(lanes)",
        "Lookup\(lanes)",
        [.tag, .constLanePointer, .lookupIndices],
        .vector,
        size.applies,
        section: .userSpecifiedPermutationAcrossBlocks,
        span: .table(lanes: lanes),
        indexContract: .table(lanes: lanes),
        laneCapability: .lookup(size),
        targets: TargetBodies(
            neon: { element in lanes == 64 ? neonLookup64(for: element) : nil },
            sve2_128: { element in
                lanes == 64 ? lookupBody(lanes: lanes, aligned: false, for: element) : nil
            },
            avx3: aligned,
            avx2: aligned,
            sse2: { element in
                lookupBody(
                    lanes: lanes,
                    aligned: true,
                    tables: x86Sse2LookupTables(for: element),
                    for: element
                )
            }
        )
    ) { element in
        lookupBody(lanes: lanes, aligned: false, for: element)
    }
}

