func negativeLanes(of operand: String = "a", for element: Element) -> String {
    let signed = signedElement(of: element)
    return "(\(element.cUnsignedVector))((\(signed.cVector))\(operand) >> \(element.bits - 1))"
}

struct MaskedFamily {
    let swiftName: String
    let operation: String
    let operands: [Parameter]
    let applies: Applies
    var returns = ReturnType.vector
    var zeroed: String?
    var merged: String?
    var zeroedSection = Section.zeroMaskedArithmetic
    var mergedSection = Section.mergeMaskedArithmetic
    var divides = false
    var unorderedNaNs: UnorderedNaNs?
    var filtersUnorderedNaNs = false
    var outOfLineOnSVE: Applies?
    var expression: ((Element) -> String)?
    var comparison: (integer: Int, float: Int)?
    var masksOperandFirst = false
    var followsHighwayOrderOnSSE2 = false
    var isolatesDivisorOnAVX2 = false
    var isolatesConstantDivisor = false
    var sveArithmetic: SveMaskedArithmetic?
    var sveZeroedBuiltin: String?
    var selectsByPredicateOnSVE = false
}

func maskedExpression(
    of family: MaskedFamily,
    for element: Element,
    isolatingDivisor: Bool = false
) -> String {
    if let expression = family.expression { return expression(element) }
    let names = Array(["a", "b", "c"].prefix(family.operands.count))
    var arguments = names.map { "(\(element.cRawVector))\($0)" }
    if isolatingDivisor {
        let selecting = cFunctionName("selecting", element)
        let ones = "(\(element.cRawVector))\(repeatingVector("1", of: element))"
        arguments[1] = "\(selecting)((\(element.cRawMask))mask, \(arguments[1]), \(ones))"
    }
    let type = family.returns == .mask ? element.cMask : element.cVector
    let call = cFunctionName(family.operation, element)
    return "(\(type))\(call)(\(arguments.joined(separator: ", ")))"
}

func maskedSelecting(_ operation: String, merging: Bool, for element: Element) -> String {
    let raw = element.cRawVector
    let selecting = cFunctionName(merging ? "selecting" : "selectingOrZero", element)
    let operands =
        ["(\(element.cRawMask))mask", "(\(raw))\(operation)"]
        + (merging ? ["(\(raw))otherwise"] : [])
    return "return \(selecting)(\(operands.joined(separator: ", ")));"
}

func sveMergingSelecting(_ operation: String, for element: Element) -> String {
    let unsigned = unsignedElement(of: element)
    let active = sveBuiltin(
        "cmpne_n",
        [sveAllLanes(of: element), "(\(sveVector(unsigned.cSuffix)))mask", "0"],
        for: unsigned
    )
    let selected = sveBuiltin(
        "sel",
        [
            "active", "(\(sveVector(element.cSuffix)))\(operation)",
            sveSplatOperand("otherwise", for: element),
        ],
        for: element
    )
    return """
        const __SVBool_t active = \(active);
        \(vectorResult(sveResult(selected, for: element), for: element))
        """
}

func x86Avx3ZeroMasked(_ operation: String, for element: Element) -> String {
    let zeros = compoundLiteral(x86Vector(x86LaneSuffix(of: element)), ["0"])
    return vectorResult(x86Avx3Selecting("mask", operation, zeros, for: element), for: element)
}

func x86Avx3MaskedComparison(
    _ predicates: (integer: Int, float: Int),
    for element: Element
) -> String {
    let vector = x86Vector(x86LaneSuffix(of: element))
    let bitsType = x86MaskType(lanes: element.laneCount)
    let width = x86Bits(element.width)
    var arguments = [(value: "a", type: vector), (value: "b", type: vector)]
    let name: String
    switch element.category {
    case .float:
        name = "cmp\(element.bits == 32 ? "ps" : "pd")\(width)_mask"
        arguments += [(value: String(predicates.float), type: "int")]
    case .float16, .bfloat16:
        fatalError("\(element.swiftType) has no AVX-512 comparison")
    case .signedInteger, .unsignedInteger:
        let isOrdered = ![0, 4].contains(predicates.integer)
        let unsigned = isOrdered && element.category == .unsignedInteger ? "u" : ""
        name = "\(unsigned)cmp\(x86LaneLetter(bits: element.bits))\(width)_mask"
        arguments += [(value: String(predicates.integer), type: "int")]
    }
    arguments += [(value: x86Avx3MaskBits("mask", for: element), type: bitsType)]
    if element.category == .float {
        arguments += [(value: "\(x86CurrentRounding)", type: "int")]
    }
    let compared = x86Builtin(name, arguments, returning: bitsType)
    return maskResult(x86Avx3MaskVector(compared, for: element), for: element)
}

func maskedTargets(
    _ operation: @escaping (Element) -> String,
    merging: Bool
) -> TargetBodies<Element> {
    TargetBodies(
        avx3: merging ? nil : { element in x86Avx3ZeroMasked(operation(element), for: element) }
    )
}

func emu128TypeName(_ kind: String, for element: Element) -> String {
    "cvectorization_ops_emu128_\(kind)_\(element.cSuffix)"
}

func emu128FunctionName(_ name: String, for element: Element) -> String {
    cFunctionName("emu128\(uppercasedFirst(name))", element)
}

func emu128Call(_ name: String, _ arguments: [String], for element: Element) -> String {
    "\(emu128FunctionName(name, for: element))(\(arguments.joined(separator: ", ")))"
}

func emu128MaskedDividingHelpers(for element: Element) -> String? {
    guard element.category == .float else { return nil }
    let lanes = element.laneCount
    let (lane, unsignedLane) = (element.cType, element.cUnsignedLane)
    let vector = emu128TypeName("vector", for: element)
    let unsigned = emu128TypeName("unsigned_vector", for: element)
    let mask = emu128TypeName("mask", for: element)
    let signBit = "0x\(String(UInt64(1) << UInt64(element.bits - 1), radix: 16))"
    let call = { (name: String, arguments: [String]) in
        emu128Call(name, arguments, for: element)
    }
    let bits = { (value: String) in "__builtin_bit_cast(\(unsignedLane), \(value))" }
    let function = { (name: String, returns: String, parameters: [String], body: String) in
        cFunction(
            returns: returns,
            name: emu128FunctionName(name, for: element),
            parameters: parameters,
            body: body
        )
    }
    let copying = { (type: String, source: String, field: String) in
        """
        \(type) copy;
        __builtin_memcpy(copy.\(field), \(source), sizeof copy.\(field));
        return copy;
        """
    }
    let lanewise = { (symbol: String) in
        """
        \(unsigned) au = \(call("bitCastToUnsigned", ["a"]));
        \(unsigned) bu = \(call("bitCastToUnsigned", ["b"]));
        for (size_t i = 0; i < \(lanes); ++i) {
          au.raw[i] \(symbol)= bu.raw[i];
        }
        return \(call("bitCast", ["au"]));
        """
    }
    let signs = ["a.raw[i]", "den"].map { call("scalarSignBit", [$0]) }
    let selected = call("or", [call("and", ["mask", "yes"]), call("andNot", ["mask", "no"])])
    let divisor = call("ifThenElse", ["m", "b", "nonzero"])
    let quotient = call("dividing", ["a", divisor])
    return [
        """
        typedef struct { \(lane) raw[\(lanes)]; } \(vector);
        typedef struct { \(unsignedLane) raw[\(lanes)]; } \(unsigned);
        typedef struct { \(unsignedLane) bits[\(lanes)]; } \(mask);

        """,
        function(
            "scalarAbs",
            lane,
            ["\(lane) val"],
            "return __builtin_bit_cast(\(lane), (\(unsignedLane))(\(bits("val")) & ~\(signBit)));"
        ),
        function(
            "scalarIsNaN",
            "bool",
            ["\(lane) val"],
            "return \(bits(call("scalarAbs", ["val"]))) > \(bits(infinity(of: element)));"
        ),
        function(
            "scalarSignBit",
            "bool",
            ["\(lane) val"],
            "return (\(bits("val")) & \(signBit)) != 0;"
        ),
        function("load", vector, ["\(element.cVector) v"], copying(vector, "&v", "raw")),
        function("loadMask", unsigned, ["\(element.cMask) m"], copying(unsigned, "&m", "raw")),
        function(
            "store",
            element.cVector,
            ["\(vector) v"],
            """
            \(element.cVector) copy;
            __builtin_memcpy(&copy, v.raw, sizeof copy);
            return copy;
            """
        ),
        function("bitCast", vector, ["\(unsigned) v"], copying(vector, "v.raw", "raw")),
        function("bitCastToUnsigned", unsigned, ["\(vector) v"], copying(unsigned, "v.raw", "raw")),
        function("maskFromVec", mask, ["\(vector) v"], copying(mask, "v.raw", "bits")),
        function("vecFromMask", vector, ["\(mask) m"], copying(vector, "m.bits", "raw")),
        function(
            "not",
            vector,
            ["\(vector) v"],
            """
            \(unsigned) vu = \(call("bitCastToUnsigned", ["v"]));
            for (size_t i = 0; i < \(lanes); ++i) {
              vu.raw[i] = (\(unsignedLane))~vu.raw[i];
            }
            return \(call("bitCast", ["vu"]));
            """
        ),
        function("and", vector, ["\(vector) a", "\(vector) b"], lanewise("&")),
        function("or", vector, ["\(vector) a", "\(vector) b"], lanewise("|")),
        function(
            "andNot",
            vector,
            ["\(vector) a", "\(vector) b"],
            "return \(call("and", [call("not", ["a"]), "b"]));"
        ),
        function(
            "ifVecThenElse",
            vector,
            ["\(vector) mask", "\(vector) yes", "\(vector) no"],
            "return \(selected);"
        ),
        function(
            "ifThenElse",
            vector,
            ["\(mask) m", "\(vector) yes", "\(vector) no"],
            "return \(call("ifVecThenElse", [call("vecFromMask", ["m"]), "yes", "no"]));"
        ),
        function(
            "set",
            vector,
            ["\(lane) t"],
            """
            \(vector) v = {{0}};
            for (size_t i = 0; i < \(lanes); ++i) {
              v.raw[i] = t;
            }
            return v;
            """
        ),
        function(
            "dividing",
            vector,
            ["\(vector) a", "\(vector) b"],
            """
            const \(lane) inf = \(infinity(of: element));
            for (size_t i = 0; i < \(lanes); ++i) {
              const \(lane) den = b.raw[i];
              if (den == 0) {
                if (\(call("scalarIsNaN", ["a.raw[i]"])) || a.raw[i] == 0) {
                  a.raw[i] = a.raw[i] + (inf * 0);
                } else {
                  const bool sign = \(signs.joined(separator: " ^ "));
                  a.raw[i] = sign ? -inf : inf;
                }
              } else {
                a.raw[i] = a.raw[i] / den;
              }
            }
            return a;
            """
        ),
        function(
            "maskedDividingOr",
            vector,
            ["\(vector) no", "\(mask) m", "\(vector) a", "\(vector) b"],
            """
            const \(vector) nonzero = \(call("set", ["1"]));
            return \(call("ifThenElse", ["m", quotient, "no"]));
            """
        ),
    ].joined(separator: "\n")
}

func emu128MaskedDividing(for element: Element) -> String? {
    guard element.category == .float else { return nil }
    let load = { (name: String) in emu128Call("load", [name], for: element) }
    let loadedMask = emu128Call("loadMask", ["mask"], for: element)
    let mask = emu128Call(
        "maskFromVec",
        [emu128Call("bitCast", [loadedMask], for: element)],
        for: element
    )
    let quotient = emu128Call(
        "maskedDividingOr",
        [load("otherwise"), mask, load("a"), load("b")],
        for: element
    )
    return vectorResult(emu128Call("store", [quotient], for: element), for: element)
}

func maskedConstantDivisor(of family: MaskedFamily, for element: Element) -> String {
    let blocked = sveBlockedCondition([.notANumber, .minusOne], of: "b", for: element)
    let isolated = maskedExpression(of: family, for: element, isolatingDivisor: true)
    let plain = maskedExpression(of: family, for: element)
    return """
        if (\(blocked.joined(separator: " || "))) {
          \(maskedSelecting(isolated, merging: true, for: element))
        }
        \(maskedSelecting(plain, merging: true, for: element))
        """
}

func maskedFamilyTargets(_ family: MaskedFamily, merging: Bool) -> TargetBodies<Element> {
    if let comparison = family.comparison {
        return TargetBodies(avx3: { element in x86Avx3MaskedComparison(comparison, for: element) })
    }
    guard family.returns == .vector else { return TargetBodies() }
    var targets = maskedTargets(
        { element in maskedExpression(of: family, for: element) },
        merging: merging
    )
    if family.masksOperandFirst {
        let operation = { (element: Element) in
            let unsigned = element.cUnsignedVector
            let masked = "(\(element.cVector))((\(unsigned))a & (\(unsigned))mask)"
            return operationCall(family.operation, [masked], for: element)
        }
        if merging {
            targets.sve2_128 = { element in
                maskedSelecting(operation(element), merging: true, for: element)
            }
        } else {
            targets.neon = { element in vectorResult(operation(element), for: element) }
        }
    }
    if let arithmetic = family.sveArithmetic {
        targets.sve2_128 = { element in
            sveMaskedArithmetic(arithmetic, merging: merging, for: element)
        }
    }
    if let builtin = family.sveZeroedBuiltin, !merging {
        targets.sve2_128 = { element in
            guard element.category == .float else { return nil }
            let code = neonTypeCode(of: element)
            let blocked = SveBlockedLanes.both([.notANumber, .minusInfinity])
            return sveConstantBarrier(blocking: blocked, for: element) {
                let operation = neonBuiltin(builtin, [$0, $1], code: code, for: element)
                return maskedSelecting(operation, merging: false, for: element)
            }
        }
    }
    guard merging else { return targets }
    if family.selectsByPredicateOnSVE {
        targets.sve2_128 = { element in
            guard isInteger64(element) else { return nil }
            return sveMergingSelecting(maskedExpression(of: family, for: element), for: element)
        }
    }
    if family.isolatesConstantDivisor {
        targets.avx3 = { element in
            guard element.category == .float else { return nil }
            let operation = maskedExpression(of: family, for: element)
            return maskedSelecting(operation, merging: true, for: element)
        }
        targets.emu128 = { element in emu128MaskedDividing(for: element) }
    }
    if family.followsHighwayOrderOnSSE2 {
        targets.sse2 = { element in
            guard isSelectedByMask(element) else { return nil }
            return complexMultiplyingBody(
                conjugating: false,
                adding: false,
                fused: false,
                selectingByMask: true,
                highwayOrder: true,
                finishing: { maskedSelecting($0, merging: true, for: element) },
                for: element
            )
        }
        targets.ssse3 = { element in
            guard isSelectedByMask(element) else { return nil }
            let operation = maskedExpression(of: family, for: element)
            return maskedSelecting(operation, merging: true, for: element)
        }
    }
    if family.isolatesDivisorOnAVX2 {
        targets.avx2 = { element in
            guard isInteger64(element) else { return nil }
            let operation = maskedExpression(of: family, for: element, isolatingDivisor: true)
            return maskedSelecting(operation, merging: true, for: element)
        }
    }
    return targets
}

func maskedFamilyHelpers(_ family: MaskedFamily, merging: Bool) -> TargetBodies<Element> {
    guard merging, family.isolatesConstantDivisor else { return TargetBodies() }
    return TargetBodies(emu128: { element in emu128MaskedDividingHelpers(for: element) })
}

func maskedOp(
    _ family: MaskedFamily,
    _ highwayName: String,
    merging: Bool,
    template: ImmediateTemplate? = nil,
    targets: TargetBodies<Element>? = nil
) -> Op {
    let parameters: [Parameter] =
        (merging ? [.otherwiseVector, .whereMask] : [.whereMask]) + family.operands
    let operation = { (element: Element) in maskedExpression(of: family, for: element) }
    return Op(
        family.swiftName,
        highwayName,
        parameters,
        family.returns,
        family.applies,
        section: merging ? family.mergedSection : family.zeroedSection,
        template: template,
        divides: family.divides,
        unorderedNaNs: family.unorderedNaNs,
        filtersUnorderedNaNs: family.filtersUnorderedNaNs,
        targets: targets ?? maskedFamilyTargets(family, merging: merging),
        helpers: maskedFamilyHelpers(family, merging: merging),
        outOfLineOnSVE: family.outOfLineOnSVE
    ) { element in
        if family.returns == .mask {
            return maskResult("mask & \(operation(element))", for: element)
        }
        if merging && family.isolatesConstantDivisor && element.category == .float {
            return maskedConstantDivisor(of: family, for: element)
        }
        return maskedSelecting(operation(element), merging: merging, for: element)
    }
}

func maskedFamilyOps(_ family: MaskedFamily) -> [Op] {
    [
        family.zeroed.map { maskedOp(family, $0, merging: false) },
        family.merged.map { maskedOp(family, $0, merging: true) },
    ].compactMap { $0 }
}

func maskedReduction(_ operation: String, identity: String?, for element: Element) -> String {
    let raw = element.cRawVector
    let mask = "(\(element.cRawMask))mask"
    let selected =
        identity.map {
            let identity = "(\(raw))\(repeatingVector($0, of: element))"
            return "\(cFunctionName("selecting", element))(\(mask), (\(raw))a, \(identity))"
        } ?? "\(cFunctionName("selectingOrZero", element))(\(mask), (\(raw))a)"
    return "return \(cFunctionName(operation, element))(\(selected));"
}

func maskedInequality(
    _ symbol: String,
    negating opposite: String,
    for element: Element
) -> String {
    guard element.category != .float else { return "(\(element.cMask))(a \(symbol) b)" }
    let arguments = ["a", "b"].map { "(\(element.cRawVector))\($0)" }
    let call = "\(cFunctionName(opposite, element))(\(arguments.joined(separator: ", ")))"
    return "~(\(element.cMask))\(call)"
}

func maskedRepeatingOp(merging: Bool) -> Op {
    let operation = { (element: Element) in repeatingVector("value", of: element) }
    return Op(
        "repeating",
        merging ? "MaskedSetOr" : "MaskedSet",
        merging ? [.otherwiseVector, .whereMask, .lane] : [.tag, .whereMask, .lane],
        .vector,
        .all,
        section: .initialization,
        targets: maskedTargets(operation, merging: merging)
    ) { element in
        maskedSelecting(operation(element), merging: merging, for: element)
    }
}

func sveMaskedReduction(_ name: String, for element: Element) -> String {
    let unsigned = unsignedElement(of: element)
    let active = sveBuiltin(
        "cmpne_n",
        [sveAllLanes(of: element), "(\(sveVector(unsigned.cSuffix)))mask", "0"],
        for: unsigned
    )
    let reduced = sveBuiltin(
        element.category == .float || element.category == .float16 ? "\(name)nmv" : "\(name)v",
        [active, sveOperand("a", for: element, splat: true)],
        for: element
    )
    guard element.category == .float16 else { return "return \(reduced);" }
    return "return __builtin_bit_cast(uint16_t, \(reduced));"
}

func maskedReductionOp(
    _ swiftName: String,
    _ highwayName: String,
    identity: ((Element) -> String)?,
    sve: String? = nil,
    unorderedNaNs: UnorderedNaNs? = nil,
    filtersUnorderedNaNs: Bool = false
) -> Op {
    Op(
        swiftName,
        highwayName,
        [.tag, .whereMask, .vector],
        .lane,
        .all,
        section: .maskedReductions,
        unorderedNaNs: unorderedNaNs,
        filtersUnorderedNaNs: filtersUnorderedNaNs,
        targets: TargetBodies(sve2_128: { element in
            sve.map { sveMaskedReduction($0, for: element) }
        })
    ) { element in
        maskedReduction(swiftName, identity: identity?(element), for: element)
    }
}

