        maskedReductionOp("largest", "MaskedReduceMax", identity: lowestValue, sve: "max"),
    ]

func negativeLanesDeclaration(for element: Element) -> String {
    "const \(element.cUnsignedVector) negative = \(negativeLanes(for: element));"
}

func portableSignSelect(_ expression: String, for element: Element) -> String {
    """
    \(negativeLanesDeclaration(for: element))
    \(vectorResult(fromUnsignedBits(expression, of: element), for: element))
    """
}

func portableNegatingIfNegative(for element: Element) -> String {
    guard element.category != .float && !element.isHalfPrecision else {
        let signs = "\(unsignedBits("a", of: element)) & \(signBitMask(for: element))"
        return vectorResult(
            fromUnsignedBits("\(unsignedBits("b", of: element)) ^ (\(signs))", of: element),
            for: element
        )
    }
    let negated = negatedLanes("b", for: element)
    return """
        \(negativeLanesDeclaration(for: element))
        \(vectorResult(bitSelect("negative", negated, "b", of: element), for: element))
        """
}

func sveNegativeLanes(for element: Element) -> String {
    sveBuiltin(
        "cmplt_n",
        [sveAllLanes(of: element), sveOperand("a", for: element), "0"],
        for: element
    )
}

func sveNegatingSplat(for element: Element) -> String? {
    guard element.category == .signedInteger else { return nil }
    return sveSplatBranch("b", nil, for: element) { splat in
        let negated = sveBuiltin(
            "neg",
            [splat, sveNegativeLanes(for: element), splat],
            for: element,
            predication: "m"
        )
        return vectorResult(sveResult(negated, for: element), for: element)
    }
}

func sveSelectingNegativeOrZeroSplat(for element: Element) -> String? {
    guard isInteger64(element) else { return nil }
    return sveSplatBranch("b", nil, for: element) { splat in
        let zero = sveBuiltin("dup_n", ["0"], for: element)
        let selected = sveBuiltin(
            "sel",
            [sveNegativeLanes(for: element), splat, zero],
            for: element
        )
        return vectorResult(sveResult(selected, for: element), for: element)
    }
}

func sveUndefinedName(for element: Element) -> String {
    cFunctionName("sveUndefined", element)
}

func sveUndefinedDeclaration(for element: Element) -> String {
    let alias = "__builtin_sve_svundef_\(sveSuffix(of: element))"
    return
        "__attribute__((__clang_arm_builtin_alias(\(alias)))) \(sveType(of: element)) \(sveUndefinedName(for: element))(void);"
}

func sveUndefined(for element: Element) -> String {
    vectorResult(sveResult("\(sveUndefinedName(for: element))()", for: element), for: element)
}

func x86NegativeLanesType(for element: Element) -> String {
    element.category == .float ? element.cUnsignedVector : x86Vector("i64")
}

func x86NegativeLanesName(for element: Element) -> String {
    cFunctionName("x86NegativeLanes", element)
}

func x86NegativeLanesHelpers() -> [String] {
    let i64 = x86Vector("i64")
    return classicElements.filter { $0.category != .unsignedInteger }.map { element in
        cFunction(
            returns: i64,
            name: x86NegativeLanesName(for: element),
            parameters: ["\(x86Vector(x86LaneSuffix(of: element))) a"],
            body: "return \(x86NegativeLanes(of: element, operand: "a", lanes: i64));"
        )
    }
}

func x86NegativeLanes(level: X86Level, for element: Element) -> String {
    let lanes = x86NegativeLanesType(for: element)
    guard level <= .ssse3 else { return x86NegativeLanes(of: element, operand: "a", lanes: lanes) }
    let operand = "(\(x86Vector(x86LaneSuffix(of: element))))a"
    return "(\(lanes))\(x86NegativeLanesName(for: element))(\(operand))"
}

func x86NegativeLanes(of element: Element, operand: String, lanes: String) -> String {
    switch element.bits {
    case 8:
        return "(\(lanes))((\(x86Vector("i8")))\(operand) < 0)"
    case 16:
        return "(\(lanes))((\(x86Vector("i16")))\(operand) >> 15)"
    case 32:
        return "(\(lanes))((\(x86Vector("i32")))\(operand) >> 31)"
    default:
        let i32 = x86Vector("i32")
        let signs = "(\(i32))\(operand) >> 31"
        return "(\(lanes))__builtin_shufflevector(\(signs), \(signs), 1, 1, 3, 3)"
    }
}

func x86BlendBySign(_ yes: String, _ no: String, for element: Element) -> String {
    let (name, suffix) =
        element.bits <= 16
        ? ("pblendvb\(x86Bits(element.width))", "i8")
        : (
            "blendv\(element.bits == 32 ? "ps" : "pd")\(x86UnsuffixedBits(element.width))",
            "f\(element.bits)"
        )
    return x86Builtin(name, [no, yes, "a"], as: suffix, returning: element.cVector)
}

func x86NegativeSelect(
    _ yes: String?,
    _ no: String?,
    declarations: [String] = [],
    level: X86Level,
    for element: Element
) -> String {
    let zero = compoundLiteral(element.cVector, ["0"])
    let lanes = x86NegativeLanesType(for: element)
    let lines: [String]
    if level >= .avx3 {
        let bits = x86Avx3MaskBits("a", for: element)
        lines = [
            vectorResult(x86Avx3Select(bits, yes ?? zero, no ?? zero, for: element), for: element)
        ]
    } else if level >= .sse4 && element.bits != 16 {
        lines = [vectorResult(x86BlendBySign(yes ?? zero, no ?? zero, for: element), for: element)]
    } else {
        let combined =
            switch (yes, no) {
            case (let yes?, let no?) where level >= .sse4:
                x86Selecting("negative", yes, no, for: element)
            case (let yes?, let no?):
                x86BitSelect("negative", yes, no, for: element)
            case (let yes?, nil):
                "(\(element.cVector))(negative & (\(lanes))\(yes))"
            case (nil, let no?):
                "(\(element.cVector))(~negative & (\(lanes))\(no))"
            case (nil, nil):
                fatalError("A selection by sign needs a vector to select")
            }
        lines = [
            "const \(lanes) negative = \(x86NegativeLanes(level: level, for: element));",
            vectorResult(combined, for: element),
        ]
    }
    return (declarations + lines).joined(separator: "\n")
}

func x86NegatingIfNegative(level: X86Level, for element: Element) -> String? {
    guard element.category == .signedInteger else { return nil }
    if level >= .ssse3 && level < .avx3 && element.bits < 64 {
        let name = "psign\(x86LaneLetter(bits: element.bits))\(x86Bits(element.width))"
        let signed = x86Builtin(
            name,
            ["b", "a"],
            as: "i\(element.bits)",
            returning: element.cVector
        )
        return vectorResult(signed, for: element)
    }
    let negated = "const \(element.cVector) negated = \(negatedLanes("b", for: element));"
    return x86NegativeSelect("negated", "b", declarations: [negated], level: level, for: element)
}

func bitTest(allBits: Bool, for element: Element) -> String {
    let comparison = allBits ? "== b" : "!= 0"
    return maskResult("(\(element.cMask))((a & b) \(comparison))", for: element)
}

func x86NotGreater(
    _ first: String,
    _ second: String,
    level: X86Level,
    for element: Element
) -> String? {
    guard element.category != .float else { return nil }
    let negated = maskResult("~mask", for: element)
    if level < .sse4 && isSignedInteger64(element) {
        return "\(x86Int64Greater(first, second, for: element))\n\(negated)"
    }
    if level < .sse4 && element.category == .unsignedInteger {
        return "\(x86UnsignedGreater(first, second, for: element))\n\(negated)"
    }
    if level == .avx2 && element.category == .unsignedInteger {
        return "\(x86UnsignedGreater(first, second, native: true, for: element))\n\(negated)"
    }
    return maskResult("~(\(element.cMask))(\(first) > \(second))", for: element)
}

func x86Avx3Comparison(
    _ first: String,
    _ second: String,
    predicate: Int,
    for element: Element
) -> String {
    let bitsType = x86MaskType(lanes: element.laneCount)
    let unsigned = element.category == .unsignedInteger ? "u" : ""
    let operandType = x86Vector("i\(element.bits)")
    let compared = x86Builtin(
        "\(unsigned)cmp\(x86LaneLetter(bits: element.bits))\(x86Bits(element.width))_mask",
        [
            (value: first, type: operandType), (value: second, type: operandType),
            (value: String(predicate), type: "int"), (value: "-1", type: bitsType),
        ],
        returning: bitsType
    )
    return maskResult(x86Avx3MaskVector(compared, for: element), for: element)
}

func x86Avx3NotLess(_ first: String, _ second: String, for element: Element) -> String? {
    guard element.category != .float else { return nil }
    return x86Avx3Comparison(first, second, predicate: 5, for: element)
}

func pairLanes(_ operand: String, picking offset: Int, for element: Element) -> String {
    let indices = (0..<element.laneCount).map { $0 - $0 % 2 + offset }
    return "__builtin_shufflevector(\(operand), \(operand), \(laneIndices(indices)))"
}

func reversedPairLanes(_ operand: String, for element: Element) -> String {
    let indices = (0..<element.laneCount).map { $0 ^ 1 }
    return "__builtin_shufflevector(\(operand), \(operand), \(laneIndices(indices)))"
}

func pairComparison(
    _ symbol: String,
    combining combination: String? = nil,
    for element: Element
) -> String {
    let mask = element.cMask
    let compared = "(\(mask))(a \(symbol) b)"
    guard let combination else {
        return maskResult(pairLanes(compared, picking: 1, for: element), for: element)
    }
    return """
        const \(mask) compared = \(compared);
        \(maskResult("compared \(combination) \(reversedPairLanes("compared", for: element))", for: element))
        """
}

func lessThan128Statements(
    _ first: String,
    _ second: String,
    upper: Bool,
    for element: Element
) -> String {
    let mask = element.cMask
    let less = "(\(mask))(\(first) < \(second))"
    guard !upper else {
        return "const \(mask) less = \(pairLanes(less, picking: 1, for: element));"
    }
    return """
        const \(mask) equal = (\(mask))(\(first) == \(second));
        const \(mask) lessLanes = \(less);
        const \(mask) lowLess = \(pairLanes("lessLanes", picking: 0, for: element));
        const \(mask) high = (equal & lowLess) | (~equal & lessLanes);
        const \(mask) less = \(pairLanes("high", picking: 1, for: element));
        """
}

func lessThan128(upper: Bool, for element: Element) -> String {
    let statements = lessThan128Statements("a", "b", upper: upper, for: element)
    return "\(statements)\n\(maskResult("less", for: element))"
}

func extremum128(minimum: Bool, upper: Bool, for element: Element) -> String {
    let (first, second) = minimum ? ("a", "b") : ("b", "a")
    let statements = lessThan128Statements(first, second, upper: upper, for: element)
    let selected = "b ^ ((\(element.cUnsignedVector))less & (a ^ b))"
    return "\(statements)\n\(vectorResult(selected, for: element))"
}

func emulatedPairMask(_ condition: String, for element: Element) -> String {
    let lane = element.cMaskLane
    return """
        const bool result = \(condition);
        const \(lane) lane = -(\(lane))result;
        const \(element.cMask) pair = \(compoundLiteral(element.cMask, ["lane", "lane"]));
        """
}

func emulatedLessCondition(_ first: String, _ second: String, upper: Bool) -> String {
    let upperLess = "(\(first)[1] < \(second)[1])"
    guard !upper else { return upperLess }
    return "\(upperLess) | ((\(first)[1] == \(second)[1]) & (\(first)[0] < \(second)[0]))"
}

func emulatedLessThan128(upper: Bool, for element: Element) -> String {
    let condition = emulatedLessCondition("a", "b", upper: upper)
    return "\(emulatedPairMask(condition, for: element))\n\(maskResult("pair", for: element))"
}

func emulatedNotEqualTo128Upper(for element: Element) -> String {
    "\(emulatedPairMask("a[1] != b[1]", for: element))\n\(maskResult("pair", for: element))"
}

func emulatedExtremum128(minimum: Bool, upper: Bool, for element: Element) -> String {
    let (first, second) = minimum ? ("a", "b") : ("b", "a")
    let condition = emulatedLessCondition(first, second, upper: upper)
    let lanes = (0..<element.laneCount).map { "(mask & a[\($0)]) | (~mask & b[\($0)])" }
    return """
        const bool less = \(condition);
        const \(element.cType) mask = -(\(element.cType))less;
        \(vectorResult(compoundLiteral(element.cVector, lanes), for: element))
        """
}

func sveExtremum128(minimum: Bool, upper: Bool, for element: Element) -> String {
    let all = sveAllLanes(of: element)
    let (first, second) = minimum ? ("a", "b") : ("b", "a")
    let operands = [first, second].map { sveOperand($0, for: element, splat: true) }
    let less = sveBuiltin("cmplt", [all] + operands, for: element)
    let selected = { (pair: String) in
        let chosen = ["a", "b"].map { sveOperand($0, for: element, splat: true) }
        return sveBuiltin("sel", [pair] + chosen, for: element)
    }
    guard !upper else {
        return """
            const __SVBool_t less = \(less);
            \(vectorResult(sveResult(selected("__builtin_sve_svtrn2_b64(less, less)"), for: element), for: element))
            """
    }
    let equal = sveBuiltin("cmpeq", [all] + operands, for: element)
    return """
        const __SVBool_t equal = \(equal);
        const __SVBool_t less = \(less);
        const __SVBool_t high = __builtin_sve_svsel_b(equal, __builtin_sve_svtrn1_b64(less, less), less);
        \(vectorResult(sveResult(selected("__builtin_sve_svtrn2_b64(high, high)"), for: element), for: element))
        """
}

func x86PairShifted(_ operand: String, for element: Element) -> String {
    x86Builtin(
        "pslldqi\(x86Bits(element.width))_byteshift",
        [(value: operand, type: x86Vector("i64")), (value: "8", type: "int")],
        returning: element.cMask
    )
}

func x86Avx3LessLanes(
    _ first: String,
    _ second: String,
    upper: Bool,
    for element: Element
) -> String {
    let mask = element.cMask
    let bitsType = x86MaskType(lanes: element.laneCount)
    let i64 = x86Vector("i64")
    func compared(_ name: String, _ first: String, _ second: String, _ predicate: Int) -> String {
        x86Builtin(
            "\(name)q\(x86Bits(element.width))_mask",
            [
                (value: first, type: i64), (value: second, type: i64),
                (value: String(predicate), type: "int"), (value: "-1", type: bitsType),
            ],
            returning: bitsType
        )
    }
    let lessLanes = [
        "const \(bitsType) lessBits = \(compared("ucmp", second, first, 6));",
        "const \(mask) lessLanes = \(x86Avx3MaskVector("lessBits", for: element));",
    ]
    guard !upper else {
        let less = "const \(mask) less = \(pairLanes("lessLanes", picking: 1, for: element));"
        return (lessLanes + [less]).joined(separator: "\n")
    }
    let equalLanes = "const \(bitsType) equalBits = \(compared("cmp", first, second, 0));"
    let high = x86Avx3Select("equalBits", "lowLess", "lessLanes", for: element)
    let blended = [
        "const \(mask) lowLess = \(x86PairShifted("lessLanes", for: element));",
        "const \(mask) high = (\(mask))\(high);",
        "const \(mask) less = \(pairLanes("high", picking: 1, for: element));",
    ]
    return ([equalLanes] + lessLanes + blended).joined(separator: "\n")
}

func x86EqualLanes(
    _ first: String,
    _ second: String,
    level: X86Level,
    for element: Element
) -> String {
    let mask = element.cMask
    guard level < .sse4 else {
        return "const \(mask) equalLanes = (\(mask))(\(first) == \(second));"
    }
    let i32 = x86Vector("i32")
    return """
        const \(i32) equalWords = (\(i32))\(first) == (\(i32))\(second);
        const \(mask) equalLanes = (\(mask))(equalWords & __builtin_shufflevector(equalWords, equalWords, 1, 0, 3, 2));
        """
}

func x86LessLanes(
    _ first: String,
    _ second: String,
    upper: Bool,
    level: X86Level,
    for element: Element
) -> String {
    guard level < .avx3 else {
        return x86Avx3LessLanes(first, second, upper: upper, for: element)
    }
    let mask = element.cMask
    let lessLanes =
        level < .sse4
        ? "\(x86UnsignedGreater(second, first, for: element))\nconst \(mask) lessLanes = mask;"
        : "const \(mask) lessLanes = (\(mask))(\(first) < \(second));"
    let upperLess = "const \(mask) less = \(pairLanes("lessLanes", picking: 1, for: element));"
    guard !upper else { return "\(lessLanes)\n\(upperLess)" }
    let blended =
        level >= .sse4
        ? x86Selecting("equalLanes", "lowLess", "lessLanes", for: element)
        : x86BitSelect("equalLanes", "lowLess", "lessLanes", for: element)
    return """
        \(x86EqualLanes(first, second, level: level, for: element))
        \(lessLanes)
        const \(mask) lowLess = \(x86PairShifted("lessLanes", for: element));
        const \(mask) high = (\(mask))\(blended);
        const \(mask) less = \(pairLanes("high", picking: 1, for: element));
        """
}

func x86LessThan128(upper: Bool, level: X86Level, for element: Element) -> String {
    let lanes = x86LessLanes("a", "b", upper: upper, level: level, for: element)
    return "\(lanes)\n\(maskResult("less", for: element))"
}

func x86Extremum128(minimum: Bool, upper: Bool, level: X86Level, for element: Element) -> String {
    let (first, second) = minimum ? ("a", "b") : ("b", "a")
    let lanes = x86LessLanes(first, second, upper: upper, level: level, for: element)
    let selected =
        switch level {
        case .avx3, .avx3dl: x86Avx3TernaryLogic(0xCA, ["less", "a", "b"], for: element)
        case .sse2, .ssse3: x86BitSelect("less", "a", "b", for: element)
        case .sse4, .avx2: x86Selecting("less", "a", "b", for: element)
        }
    return "\(lanes)\n\(vectorResult(selected, for: element))"
}

func negativeSelectTargets(
    _ yes: String?,
    _ no: String?,
    sveSplat: ((Element) -> String?)? = nil
) -> TargetBodies<Element> {
    TargetBodies(
        sve2_128Splat: sveSplat,
        avx3: { element in x86NegativeSelect(yes, no, level: .avx3, for: element) },
        avx2: { element in x86NegativeSelect(yes, no, level: .avx2, for: element) },
        sse4: { element in x86NegativeSelect(yes, no, level: .sse4, for: element) },
        sse2: { element in x86NegativeSelect(yes, no, level: .sse2, for: element) }
    )
}

func notGreaterTargets(_ first: String, _ second: String) -> TargetBodies<Element> {
    TargetBodies(
        avx3: { element in x86Avx3NotLess(first, second, for: element) },
        avx2: { element in x86NotGreater(second, first, level: .avx2, for: element) },
        sse4: { element in x86NotGreater(second, first, level: .sse4, for: element) },
        sse2: { element in x86NotGreater(second, first, level: .sse2, for: element) }
    )
}

func lessThan128Targets(upper: Bool) -> TargetBodies<Element> {
    TargetBodies(
        avx3: { element in x86LessThan128(upper: upper, level: .avx3, for: element) },
        avx2: { element in x86LessThan128(upper: upper, level: .avx2, for: element) },
        sse4: { element in x86LessThan128(upper: upper, level: .sse4, for: element) },
        sse2: { element in x86LessThan128(upper: upper, level: .sse2, for: element) },
        emu128: { element in emulatedLessThan128(upper: upper, for: element) }
    )
}

func extremum128Targets(minimum: Bool, upper: Bool) -> TargetBodies<Element> {
    TargetBodies(
        sve2_128: { element in sveExtremum128(minimum: minimum, upper: upper, for: element) },
        avx3: { element in
            x86Extremum128(minimum: minimum, upper: upper, level: .avx3, for: element)
        },
        avx2: { element in
            x86Extremum128(minimum: minimum, upper: upper, level: .avx2, for: element)
        },
        sse4: { element in
            x86Extremum128(minimum: minimum, upper: upper, level: .sse4, for: element)
        },
        sse2: { element in
            x86Extremum128(minimum: minimum, upper: upper, level: .sse2, for: element)
        },
        emu128: { element in
            emulatedExtremum128(minimum: minimum, upper: upper, for: element)
        }
    )
}

let signAndComparisonOps: [Op] = [
    Op("signBit", "SignBit", [.tag], .vector, .all, section: .initialization) { element in
        vectorResult(fromUnsignedBits(signBitMask(for: element), of: element), for: element)
    },
    Op(
        "unspecified",
        "Undefined",
        [.tag],
        .vector,
        .all,
        section: .initialization,
        unspecifiedResult: true,
        targets: TargetBodies(sve2_128: { element in sveUndefined(for: element) }),
        helpers: TargetBodies(sve2_128: { element in sveUndefinedDeclaration(for: element) })
    ) { element in
        let zero = compoundLiteral(element.cVector, ["0"])
        return vectorResult("__builtin_nondeterministic_value(\(zero))", for: element)
    },

    Op(
        "zeroingNegative",
        "ZeroIfNegative",
        [.vector],
        .vector,
        .signedOrFloat,
        section: .logical,
        targets: negativeSelectTargets(nil, "a")
    ) { element in
        portableSignSelect("~negative & \(unsignedBits("a", of: element))", for: element)
    },
    Op(
        "selectingIfNegative",
        "IfNegativeThenElse",
        [.vector, .vector, .vector],
        .vector,
        .signedOrFloat,
        section: .logical,
        targets: negativeSelectTargets("b", "c")
    ) { element in
        portableSignSelect(bitSelect("negative", "b", "c", of: element), for: element)
    },
    Op(
        "selectingIfNegativeOrZero",
        "IfNegativeThenElseZero",
        [.vector, .vector],
        .vector,
        .signedOrFloat,
        section: .logical,
        targets: negativeSelectTargets("b", nil, sveSplat: sveSelectingNegativeOrZeroSplat)
    ) { element in
        portableSignSelect("negative & \(unsignedBits("b", of: element))", for: element)
    },
    Op(
        "zeroingIfNegative",
        "IfNegativeThenZeroElse",
        [.vector, .vector],
        .vector,
        .signedOrFloat,
        section: .logical,
        targets: negativeSelectTargets(nil, "b")
    ) { element in
        portableSignSelect("~negative & \(unsignedBits("b", of: element))", for: element)
    },
    Op(
        "negatingIfNegative",
        "IfNegativeThenNegOrUndefIfZero",
        [.vector, .vector],
        .vector,
        .signedOrFloat,
        section: .logical,
        targets: TargetBodies(
            sve2_128Splat: { element in sveNegatingSplat(for: element) },
            avx3: { element in x86NegatingIfNegative(level: .avx3, for: element) },
            avx2: { element in x86NegatingIfNegative(level: .avx2, for: element) },
            sse4: { element in x86NegatingIfNegative(level: .sse4, for: element) },
            ssse3: { element in x86NegatingIfNegative(level: .ssse3, for: element) },
            sse2: { element in x86NegatingIfNegative(level: .sse2, for: element) }
        )
    ) { element in
        portableNegatingIfNegative(for: element)
    },

    Op(
        "lessThanOrEqualTo",
        "Le",
        [.vector, .vector],
        .mask,
        .all,
        section: .comparisons,
        targets: notGreaterTargets("b", "a")
    ) { element in
        vectorComparison("<=", for: element)
    },
    Op(
        "greaterThanOrEqualTo",
        "Ge",
        [.vector, .vector],
        .mask,
        .all,
        section: .comparisons,
        targets: notGreaterTargets("a", "b")
    ) { element in
        vectorComparison(">=", for: element)
    },
    Op(
        "isNegative",
        "IsNegative",
        [.vector],
        .mask,
        .signedOrFloat,
        section: .comparisons
    ) { element in
        maskResult("(\(element.cMask))\(negativeLanes(for: element))", for: element)
    },
    Op(
        "testingBit",
        "TestBit",
        [.vector, .vector],
        .mask,
        .integer,
        section: .comparisons,
        targets: TargetBodies(
            neon: { element in bitTest(allBits: false, for: element) },
            avx3: { element in bitTest(allBits: false, for: element) }
        )
    ) { element in
        bitTest(allBits: true, for: element)
    },
    Op(
        "lessThan128",
        "Lt128",
        [.tag, .vector, .vector],
        .mask,
        .unsigned(bits: [64]),
        section: .comparisons,
        targets: lessThan128Targets(upper: false)
    ) { element in
        lessThan128(upper: false, for: element)
    },
    Op(
        "lessThan128Upper",
        "Lt128Upper",
        [.tag, .vector, .vector],
        .mask,
        .unsigned(bits: [64]),
        section: .comparisons,
        targets: lessThan128Targets(upper: true)
    ) { element in
        lessThan128(upper: true, for: element)
    },
    Op(
        "equalTo128",
        "Eq128",
        [.tag, .vector, .vector],
        .mask,
        .unsigned(bits: [64]),
        section: .comparisons
    ) { element in
        pairComparison("==", combining: "&", for: element)
    },
    Op(
        "notEqualTo128",
        "Ne128",
        [.tag, .vector, .vector],
        .mask,
        .unsigned(bits: [64]),
        section: .comparisons
    ) { element in
        pairComparison("!=", combining: "|", for: element)
    },
    Op(
        "equalTo128Upper",
        "Eq128Upper",
        [.tag, .vector, .vector],
        .mask,
        .unsigned(bits: [64]),
        section: .comparisons
    ) { element in
        pairComparison("==", for: element)
    },
    Op(
        "notEqualTo128Upper",
        "Ne128Upper",
        [.tag, .vector, .vector],
        .mask,
        .unsigned(bits: [64]),
        section: .comparisons,
        targets: TargetBodies(emu128: { element in emulatedNotEqualTo128Upper(for: element) })
    ) { element in
        pairComparison("!=", for: element)
    },

    Op(
        "minimum128",
        "Min128",
        [.tag, .vector, .vector],
        .vector,
        .unsigned(bits: [64]),
        section: .minMax,
        targets: extremum128Targets(minimum: true, upper: false)
    ) { element in
        extremum128(minimum: true, upper: false, for: element)
    },
    Op(
        "maximum128",
        "Max128",
        [.tag, .vector, .vector],
        .vector,
        .unsigned(bits: [64]),
        section: .minMax,
        targets: extremum128Targets(minimum: false, upper: false)
    ) { element in
        extremum128(minimum: false, upper: false, for: element)
    },
    Op(
        "minimum128Upper",
        "Min128Upper",
        [.tag, .vector, .vector],
        .vector,
        .unsigned(bits: [64]),
        section: .minMax,
        targets: extremum128Targets(minimum: true, upper: true)
    ) { element in
        extremum128(minimum: true, upper: true, for: element)
    },
    Op(
        "maximum128Upper",
        "Max128Upper",
        [.tag, .vector, .vector],
        .vector,
        .unsigned(bits: [64]),
        section: .minMax,
        targets: extremum128Targets(minimum: false, upper: true)
    ) { element in
        extremum128(minimum: false, upper: true, for: element)
    },
]

