struct AesRound {
    let swiftName: String
    let highwayName: String
    let inverse: Bool
    let mixesColumns: Bool

    var emulatedName: String { "\(swiftName)Emulated" }
    var x86Name: String { "aes\(inverse ? "dec" : "enc")\(mixesColumns ? "" : "last")" }
    var armSubstitution: String { inverse ? "aesd" : "aese" }
    var armMixing: String { inverse ? "aesimc" : "aesmc" }
}

let aesRounds = [
    AesRound(
        swiftName: "aesRound",
        highwayName: "AESRound",
        inverse: false,
        mixesColumns: true
    ),
    AesRound(
        swiftName: "aesLastRound",
        highwayName: "AESLastRound",
        inverse: false,
        mixesColumns: false
    ),
    AesRound(
        swiftName: "aesRoundInverse",
        highwayName: "AESRoundInv",
        inverse: true,
        mixesColumns: true
    ),
    AesRound(
        swiftName: "aesLastRoundInverse",
        highwayName: "AESLastRoundInv",
        inverse: true,
        mixesColumns: false
    ),
]

let aesInverseMixColumnsEmulatedName = "aesInverseMixColumnsEmulated"
let aesKeyGenerationAssistEmulatedName = "aesKeyGenerationAssistEmulated"
let carrylessMultiplyingEmulatedName = "carrylessMultiplyingEmulated"
let carrylessWideProductName = "carrylessWideProduct"
let carrylessBlockProductName = "carrylessBlockProduct"
let carrylessLanesName = "carrylessLanes"

func aesBlocks(_ block: [String], for element: Element) -> String {
    compoundLiteral(element.cVector, (0..<element.width / 16).flatMap { _ in block })
}

func aesTable(_ bytes: [UInt8], for element: Element) -> String {
    aesBlocks(bytes.map { String(format: "0x%02X", $0) }, for: element)
}

func aesRoundConstants(at bytes: [Int], for element: Element) -> String {
    aesBlocks((0..<16).map { bytes.contains($0) ? "roundConstant" : "0" }, for: element)
}

func aesConstants(_ tables: [(name: String, bytes: [UInt8])], for element: Element) -> String {
    tables.map { "const \(element.cVector) \($0.name) = \(aesTable($0.bytes, for: element));" }
        .joined(separator: "\n")
}

func aesLookup(
    _ bytes: String,
    _ indices: String,
    zeroing: Bool = false,
    for element: Element
) -> String {
    let function = cFunctionName(zeroing ? "tableLookupBytesOrZero" : "tableLookupBytes", element)
    let raw = element.cRawVector
    return "(\(element.cVector))\(function)((\(raw))(\(bytes)), (\(raw))(\(indices)))"
}

func aesBitwise(_ symbol: String, _ operands: [String], for element: Element) -> String {
    let raw = element.cRawVector
    let combined = operands.map { "(\(raw))(\($0))" }.joined(separator: " \(symbol) ")
    return "(\(element.cVector))(\(combined))"
}

func aesXor(_ operands: String..., for element: Element) -> String {
    aesBitwise("^", operands, for: element)
}

func aesOr(_ operands: String..., for element: Element) -> String {
    aesBitwise("|", operands, for: element)
}

func aesUpperNibbles(of state: String, into result: String, for element: Element) -> String {
    let vector = element.cVector
    return """
        #if CVECTORIZATION_OPS_X86
        const \(vector) \(result) = (\(vector))((halves)\(state) >> 4) & 0xF;
        #else
        const \(vector) \(result) = \(state) >> 4;
        #endif
        """
}

func aesSubBytesMulInverse(
    of state: String,
    affineLower: [UInt8],
    affineUpper: [UInt8],
    into result: String,
    for element: Element
) -> String {
    let vector = element.cVector
    func lookup(_ bytes: String, _ indices: String, zeroing: Bool = false) -> String {
        aesLookup(bytes, indices, zeroing: zeroing, for: element)
    }
    let constants = aesConstants(
        [
            ("basisLower", aesBasisLower),
            ("basisUpper", aesBasisUpper),
            ("zetaInverse", aesZetaInverse),
            ("inverseTable", aesInverseTable),
            ("affineLower", affineLower),
            ("affineUpper", affineUpper),
        ],
        for: element
    )
    return """
        #if CVECTORIZATION_OPS_X86
        \(vectorTypedef("halves", of: unsignedElement(bits: 16), lanes: element.width / 2))
        #endif
        \(constants)
        const \(vector) lowers = \(state) & 0xF;
        \(aesUpperNibbles(of: state, into: "uppers", for: element))
        const \(vector) basisChanged = \(aesXor(lookup("basisLower", "lowers"), lookup("basisUpper", "uppers"), for: element));
        const \(vector) inverseLowers = basisChanged & 0xF;
        \(aesUpperNibbles(of: "basisChanged", into: "inverseUppers", for: element))
        const \(vector) sums = \(aesXor("inverseUppers", "inverseLowers", for: element));
        const \(vector) lowerInverses = \(lookup("zetaInverse", "inverseLowers"));
        const \(vector) upperInverses = \(lookup("inverseTable", "inverseUppers"));
        const \(vector) sumInverses = \(lookup("inverseTable", "sums"));
        const \(vector) outLowers = \(aesXor("sums", lookup("inverseTable", aesXor("lowerInverses", "upperInverses", for: element), zeroing: true), for: element));
        const \(vector) outUppers = \(aesXor("inverseUppers", lookup("inverseTable", aesXor("lowerInverses", "sumInverses", for: element), zeroing: true), for: element));
        const \(vector) \(result) = \(aesXor(lookup("affineLower", "outLowers", zeroing: true), lookup("affineUpper", "outUppers", zeroing: true), for: element));
        """
}

func aesSubBytes(of state: String, into result: String, for element: Element) -> String {
    let substituted = aesSubBytesMulInverse(
        of: state,
        affineLower: aesAffineLower,
        affineUpper: aesAffineUpper,
        into: "affined",
        for: element
    )
    return """
        \(substituted)
        const \(element.cVector) \(result) = affined ^ 0x63;
        """
}

func aesInverseSubBytes(of state: String, into result: String, for element: Element) -> String {
    let vector = element.cVector
    let substituted = aesSubBytesMulInverse(
        of: "inverseAffined",
        affineLower: aesInverseAffineLower,
        affineUpper: aesInverseAffineUpper,
        into: result,
        for: element
    )
    return """
        const \(vector) rotated1 = \(aesOr("\(state) << 1", "\(state) >> 7", for: element));
        const \(vector) rotated3 = \(aesOr("\(state) << 3", "\(state) >> 5", for: element));
        const \(vector) rotated6 = \(aesOr("\(state) << 6", "\(state) >> 2", for: element));
        const \(vector) inverseAffined = \(aesXor("rotated1", aesXor("rotated3", "rotated6", for: element), for: element)) ^ 0x05;
        \(substituted)
        """
}

func aesShiftedRows(
    of state: String,
    inverse: Bool,
    into result: String,
    for element: Element
) -> String {
    let rows = aesConstants([("rows", inverse ? aesInverseShiftRows : aesShiftRows)], for: element)
    return """
        \(rows)
        const \(element.cVector) \(result) = \(aesLookup(state, "rows", for: element));
        """
}

func aesDoubled(_ operand: String, into result: String, for element: Element) -> String {
    let vector = element.cVector
    return """
        const signed_vector \(result)Negatives = (signed_vector)((signed_vector)\(operand) < 0);
        const \(vector) \(result)Overflow = \(aesBitwise("&", ["\(result)Negatives", splat("0x1B", as: vector, lanes: element.laneCount)], for: element));
        const \(vector) \(result) = \(aesXor("\(operand) + \(operand)", "\(result)Overflow", for: element));
        """
}

func aesRotatedColumns(for element: Element) -> String {
    aesConstants(
        [("rotated2301", aesRotatedColumns2301), ("rotated1230", aesRotatedColumns1230)],
        for: element
    )
}

func aesMixedColumns(of state: String, into result: String, for element: Element) -> String {
    let vector = element.cVector
    return """
        \(aesRotatedColumns(for: element))
        \(aesDoubled(state, into: "doubled", for: element))
        const \(vector) rotated = \(aesLookup(state, "rotated2301", for: element));
        const \(vector) doubledAndRotated = \(aesXor("doubled", "rotated", for: element));
        const \(vector) tripledAndRotated = \(aesXor(state, "doubledAndRotated", for: element));
        const \(vector) tripledRotated = \(aesLookup("tripledAndRotated", "rotated1230", for: element));
        const \(vector) \(result) = \(aesXor("doubledAndRotated", "tripledRotated", for: element));
        """
}

func aesInverseMixedColumns(of state: String, into result: String, for element: Element) -> String {
    let vector = element.cVector
    return """
        \(aesRotatedColumns(for: element))
        \(aesDoubled(state, into: "times2", for: element))
        \(aesDoubled("times2", into: "times4", for: element))
        \(aesDoubled("times4", into: "times8", for: element))
        const \(vector) times9 = \(aesXor("times8", state, for: element));
        const \(vector) times11 = \(aesXor("times9", "times2", for: element));
        const \(vector) times13 = \(aesXor("times9", "times4", for: element));
        const \(vector) times14 = \(aesXor("times8", aesXor("times4", "times2", for: element), for: element));
        const \(vector) times13And9 = \(aesXor("times13", aesLookup("times9", "rotated1230", for: element), for: element));
        const \(vector) times14And11 = \(aesXor("times14", aesLookup("times11", "rotated1230", for: element), for: element));
        const \(vector) times13And9Rotated = \(aesLookup("times13And9", "rotated2301", for: element));
        const \(vector) \(result) = \(aesXor("times14And11", "times13And9Rotated", for: element));
        """
}

func aesSignedVectorTypedef(for element: Element) -> String {
    vectorTypedef("signed_vector", of: signedElement(of: element), lanes: element.laneCount)
}

func aesEmulatedRound(_ round: AesRound, for element: Element) -> String {
    let substituted =
        round.inverse
        ? aesInverseSubBytes(of: "a", into: "substituted", for: element)
        : aesSubBytes(of: "a", into: "substituted", for: element)
    var statements = [
        substituted,
        aesShiftedRows(of: "substituted", inverse: round.inverse, into: "shifted", for: element),
    ]
    if round.mixesColumns {
        statements.insert(aesSignedVectorTypedef(for: element), at: 0)
        statements.append(
            round.inverse
                ? aesInverseMixedColumns(of: "shifted", into: "mixed", for: element)
                : aesMixedColumns(of: "shifted", into: "mixed", for: element)
        )
    }
    let keyed = aesXor(round.mixesColumns ? "mixed" : "shifted", "b", for: element)
    statements.append(vectorResult(keyed, for: element))
    return statements.joined(separator: "\n")
}

func aesEmulatedInverseMixColumns(for element: Element) -> String {
    [
        aesSignedVectorTypedef(for: element),
        aesInverseMixedColumns(of: "a", into: "mixed", for: element),
        vectorResult("mixed", for: element),
    ].joined(separator: "\n")
}

func aesEmulatedKeyGenerationAssist(for element: Element) -> String {
    let rotation = aesLookup("substituted", "rotatedWord", for: element)
    return """
        \(aesSubBytes(of: "a", into: "substituted", for: element))
        \(aesConstants([("rotatedWord", aesRotatedWord)], for: element))
        const \(element.cVector) mask = \(aesRoundConstants(at: aesRoundConstantBytes, for: element));
        \(vectorResult(aesXor(rotation, "mask", for: element), for: element))
        """
}

func emulatedFunction(
    _ name: String,
    vectors: Int,
    parameters: [String] = [],
    body: @escaping (Element) -> String
) -> (Element) -> String {
    { element in
        let operands = ["a", "b"].prefix(vectors)
        return cOpFunction(
            returns: .vector,
            name: cFunctionName(name, element),
            parameters: operands.map { "\(element.cRawVector) \(rawName($0))" } + parameters,
            prologue: operands.map {
                "const \(element.cVector) \($0) = (\(element.cVector))\(rawName($0));"
            },
            body: body(element),
            for: element
        )
    }
}

func emulatedCall(_ name: String, _ arguments: [String], for element: Element) -> String {
    "return \(cFunctionName(name, element))(\(arguments.joined(separator: ", ")));"
}

func aesRoundEmulatedCall(_ round: AesRound, for element: Element) -> String {
    emulatedCall(round.emulatedName, ["rawA", "rawB"], for: element)
}

func aesInverseMixColumnsEmulatedCall(for element: Element) -> String {
    emulatedCall(aesInverseMixColumnsEmulatedName, ["rawA"], for: element)
}

func aesKeyGenerationAssistEmulatedCall(for element: Element) -> String {
    emulatedCall(aesKeyGenerationAssistEmulatedName, ["rawA", "roundConstant"], for: element)
}

func carrylessMultiplyingEmulatedCall(upper: Bool, for element: Element) -> String {
    let arguments = ["rawA", "rawB", upper ? "1" : "0"]
    return emulatedCall(carrylessMultiplyingEmulatedName, arguments, for: element)
}

func neonAesRound(_ round: AesRound, for element: Element) -> String {
    let zero = compoundLiteral(element.cVector, ["0"])
    let code = neonTypeCode(of: element)
    var state = neonBuiltin("v\(round.armSubstitution)q_u8", ["a", zero], code: code, for: element)
    if round.mixesColumns {
        state = neonBuiltin("v\(round.armMixing)q_u8", [state], code: code, for: element)
    }
    return """
        #if \(neonHasAesCondition)
        \(vectorResult("\(state) ^ b", for: element))
        #else
        \(aesRoundEmulatedCall(round, for: element))
        #endif
        """
}

func neonAesInverseMixColumns(for element: Element) -> String {
    let mixed = neonBuiltin("vaesimcq_u8", ["a"], code: neonTypeCode(of: element), for: element)
    return """
        #if \(neonHasAesCondition)
        \(vectorResult(mixed, for: element))
        #else
        \(aesInverseMixColumnsEmulatedCall(for: element))
        #endif
        """
}

func aesNativeKeyGenerationAssist(
    lastRound: (_ state: String, _ key: String) -> String,
    for element: Element
) -> String {
    let vector = element.cVector
    let words = element.width / 4
    let duplicates = laneIndices((0..<words).map { $0 | 1 })
    let rotation = aesLookup("substituted", "rotatedWord", for: element)
    return """
        \(vectorTypedef("words", of: unsignedElement(of: unsignedElement(bits: 32)), lanes: words))
        \(aesConstants([("rotatedWord", aesNativeRotatedWord)], for: element))
        const \(vector) mask = \(aesRoundConstants(at: aesNativeRoundConstantBytes, for: element));
        const \(vector) duplicated = (\(vector))__builtin_shufflevector((words)a, (words)a, \(duplicates));
        const \(vector) substituted = \(lastRound("duplicated", "mask"));
        \(vectorResult(rotation, for: element))
        """
}

func neonAesKeyGenerationAssist(for element: Element) -> String {
    let zero = compoundLiteral(element.cVector, ["0"])
    let code = neonTypeCode(of: element)
    let native = aesNativeKeyGenerationAssist(
        lastRound: { state, key in
            "\(neonBuiltin("vaeseq_u8", [state, zero], code: code, for: element)) ^ \(key)"
        },
        for: element
    )
    return """
        #if \(neonHasAesCondition)
        \(native)
        #else
        \(aesKeyGenerationAssistEmulatedCall(for: element))
        #endif
        """
}

func neonCarrylessMultiplying(upper: Bool, for element: Element) -> String {
    let lane = upper ? 1 : 0
    return """
        #if \(neonHasAesCondition)
        \(vectorResult("__builtin_neon_vmull_p64(a[\(lane)], b[\(lane)])", for: element))
        #else
        \(carrylessMultiplyingEmulatedCall(upper: upper, for: element))
        #endif
        """
}

func sveAesZero(for element: Element) -> String {
    sveBuiltin("dup_n", ["0"], for: element)
}

func sveAesRound(_ round: AesRound, for element: Element) -> String {
    var state = sveBuiltin(
        round.armSubstitution,
        [sveOperand("a", for: element), sveAesZero(for: element)],
        for: element
    )
    if round.mixesColumns {
        state = sveBuiltin(round.armMixing, [state], for: element)
    }
    return """
        #if \(sveHasAesCondition)
        \(vectorResult("\(sveResult(state, for: element)) ^ b", for: element))
        #else
        \(aesRoundEmulatedCall(round, for: element))
        #endif
        """
}

func sveAesInverseMixColumns(for element: Element) -> String {
    let mixed = sveBuiltin("aesimc", [sveOperand("a", for: element)], for: element)
    return """
        #if \(sveHasAesCondition)
        \(vectorResult(sveResult(mixed, for: element), for: element))
        #else
        \(aesInverseMixColumnsEmulatedCall(for: element))
        #endif
        """
}

func sveAesKeyGenerationAssist(for element: Element) -> String {
    let native = aesNativeKeyGenerationAssist(
        lastRound: { state, key in
            let substituted = sveBuiltin(
                "aese",
                [sveOperand(state, for: element), sveAesZero(for: element)],
                for: element
            )
            return "\(sveResult(substituted, for: element)) ^ \(key)"
        },
        for: element
    )
    return """
        #if \(sveHasAesCondition)
        \(native)
        #else
        \(aesKeyGenerationAssistEmulatedCall(for: element))
        #endif
        """
}

func sveCarrylessMultiplying(upper: Bool, for element: Element) -> String {
    let operands = [sveOperand("a", for: element), sveOperand("b", for: element)]
    let product = sveBuiltin(upper ? "pmullt_pair" : "pmullb_pair", operands, for: element)
    return """
        #if \(sveHasAesCondition)
        \(vectorResult(sveResult(product, for: element), for: element))
        #else
        \(carrylessMultiplyingEmulatedCall(upper: upper, for: element))
        #endif
        """
}

func x86Blocks(of operand: String, width: Int) -> [String] {
    let words = x86Vector("i64")
    guard width > 16 else { return ["(\(x86Block("i64")))\(operand)"] }
    return (0..<width / 16).map {
        "__builtin_shufflevector((\(words))\(operand), (\(words))\(operand), \(2 * $0), \(2 * $0 + 1))"
    }
}

func x86Blockwise(
    _ operands: [String],
    for element: Element,
    call: ([String]) -> String
) -> (statements: [String], combined: String) {
    let blocks = operands.map { x86Blocks(of: $0, width: element.width) }
    let parts = blocks[0].indices.map { part in
        "const \(x86Block("i64")) part\(part) = \(call(blocks.map { $0[part] }));"
    }
    return (parts, concatenatedParts(parts.indices.map { "part\($0)" }, lanes: 2))
}

func x86BlockwiseResult(
    _ operands: [String],
    for element: Element,
    call: ([String]) -> String
) -> String {
    let (statements, combined) = x86Blockwise(operands, for: element, call: call)
    return (statements + [vectorResult(combined, for: element)]).joined(separator: "\n")
}

func x86Crypto(native: String, emulated: String) -> String {
    """
    #if \(x86HasAesCondition)
    \(native)
    #else
    \(emulated)
    #endif
    """
}

func x86AesRound(_ round: AesRound, for element: Element) -> String {
    let name = "\(round.x86Name)128"
    return x86Crypto(
        native: x86BlockwiseResult(["a", "b"], for: element) { blocks in
            "__builtin_ia32_\(name)(\(blocks.joined(separator: ", ")))"
        },
        emulated: aesRoundEmulatedCall(round, for: element)
    )
}

func x86Avx3DlAesRound(_ round: AesRound, for element: Element) -> String {
    let name = "\(round.x86Name)\(x86Bits(element.width))"
    return x86Crypto(
        native: vectorResult(
            x86Builtin(name, ["a", "b"], as: "i64", returning: element.cVector),
            for: element
        ),
        emulated: aesRoundEmulatedCall(round, for: element)
    )
}

func x86AesInverseMixColumns(for element: Element) -> String {
    x86Crypto(
        native: x86BlockwiseResult(["a"], for: element) { blocks in
            "__builtin_ia32_aesimc128(\(blocks[0]))"
        },
        emulated: aesInverseMixColumnsEmulatedCall(for: element)
    )
}

func x86Avx3DlAesInverseMixColumns(for element: Element) -> String {
    let bits = x86Bits(element.width)
    let words = x86Vector("i64")
    let zero = compoundLiteral(words, ["0"])
    func round(_ name: String, _ state: String) -> String {
        let operands = [(value: state, type: words), (value: zero, type: words)]
        return x86Builtin("\(name)\(bits)", operands, returning: element.cVector)
    }
    let mixed = round("aesdec", round("aesenclast", "a"))
    return x86Crypto(
        native: vectorResult(mixed, for: element),
        emulated: aesInverseMixColumnsEmulatedCall(for: element)
    )
}

func x86AesKeyGenerationAssistName(for element: Element) -> String {
    cFunctionName("x86AesKeyGenerationAssist", element)
}

func x86AesKeyGenerationAssistHelper(for element: Element) -> String {
    let block = x86Block("i64")
    func assist(_ constant: Int) -> String {
        let immediate = constant < 128 ? constant : constant - 256
        return "return __builtin_ia32_aeskeygenassist128(v, \(immediate));"
    }
    let cases = (0..<255).map { "case \($0): \(assist($0))" } + ["default: \(assist(255))"]
    let function = cFunction(
        returns: block,
        name: x86AesKeyGenerationAssistName(for: element),
        parameters: ["\(block) v", "uint8_t roundConstant"],
        body: "switch (roundConstant) {\n\(cases.joined(separator: "\n"))\n}"
    )
    return "#if \(x86HasAesCondition)\n\(function)#endif"
}

func x86AesKeyGenerationAssist(for element: Element) -> String {
    let helper = x86AesKeyGenerationAssistName(for: element)
    let constant = x86Blockwise(["a"], for: element) { blocks in
        "\(helper)(\(blocks[0]), roundConstant)"
    }
    let runtime = x86Blockwise(["a"], for: element) { blocks in
        "__builtin_ia32_aeskeygenassist128(\(blocks[0]), 0)"
    }
    let mask = aesRoundConstants(at: aesRoundConstantBytes, for: element)
    let native = """
        if (__builtin_constant_p(roundConstant)) {
        \(indented((constant.statements + [vectorResult(constant.combined, for: element)]).joined(separator: "\n")))
        }
        \(runtime.statements.joined(separator: "\n"))
        \(vectorResult("(\(element.cVector))(\(runtime.combined)) ^ \(mask)", for: element))
        """
    return x86Crypto(
        native: native,
        emulated: aesKeyGenerationAssistEmulatedCall(for: element)
    )
}

func x86Avx3DlAesKeyGenerationAssist(for element: Element) -> String {
    let native = aesNativeKeyGenerationAssist(
        lastRound: { state, key in
            x86Builtin(
                "aesenclast\(x86Bits(element.width))",
                [state, key],
                as: "i64",
                returning: element.cVector
            )
        },
        for: element
    )
    return x86Crypto(
        native: native,
        emulated: aesKeyGenerationAssistEmulatedCall(for: element)
    )
}

func x86CarrylessMultiplying(upper: Bool, for element: Element) -> String {
    let selector = upper ? "0x11" : "0x00"
    return x86Crypto(
        native: x86BlockwiseResult(["a", "b"], for: element) { blocks in
            "__builtin_ia32_pclmulqdq128(\(blocks.joined(separator: ", ")), \(selector))"
        },
        emulated: carrylessMultiplyingEmulatedCall(upper: upper, for: element)
    )
}

func x86Avx3DlCarrylessMultiplying(upper: Bool, for element: Element) -> String {
    let words = x86Vector("i64")
    let selector = upper ? "0x11" : "0x00"
    let product =
        "(\(element.cVector))__builtin_ia32_pclmulqdq\(x86Bits(element.width))((\(words))a, (\(words))b, \(selector))"
    return x86Crypto(
        native: vectorResult(product, for: element),
        emulated: carrylessMultiplyingEmulatedCall(upper: upper, for: element)
    )
}

func carrylessWideProduct(for element: Element) -> String {
    let lane = element.cType
    return cFunction(
        returns: lane,
        name: cFunctionName(carrylessWideProductName, element),
        parameters: ["\(lane) a", "\(lane) b", "\(lane)* high"],
        body: """
            #if defined(__SIZEOF_INT128__)
            const unsigned __int128 product = (unsigned __int128)a * (unsigned __int128)b;
            *high = (\(lane))(product >> 64);
            return (\(lane))product;
            #else
            const \(lane) loLo = (a & 0xffffffff) * (b & 0xffffffff);
            const \(lane) hiLo = (a >> 32) * (b & 0xffffffff);
            const \(lane) loHi = (a & 0xffffffff) * (b >> 32);
            const \(lane) hiHi = (a >> 32) * (b >> 32);
            const \(lane) carry = (loLo >> 32) + (hiLo & 0xffffffff) + loHi;
            *high = (hiLo >> 32) + (carry >> 32) + hiHi;
            return a * b;
            #endif
            """
    )
}

func carrylessBlockProduct(for element: Element) -> String {
    let multiply = cFunctionName(carrylessWideProductName, element)
    let blocks = (0..<element.laneCount / 2).map { block in
        let low = 2 * block
        return """
            product[\(low)] = \(multiply)(a[\(low) + lane], b[\(low) + lane], &high);
            product[\(low + 1)] = high;
            """
    }
    return """
        \(element.cVector) product;
        \(element.cType) high;
        \(blocks.joined(separator: "\n"))
        \(vectorResult("product", for: element))
        """
}

func sveCarrylessBlockProduct(for element: Element) -> String {
    let all = sveAllLanes(of: element)
    let operands = [all, sveOperand("a", for: element), sveOperand("b", for: element)]
    let type = sveVector(element.cSuffix)
    func interleaved(_ name: String) -> String {
        "(\(type))\(sveBuiltin(name, ["low", "high"], for: element))"
    }
    return """
        const \(type) low = (\(type))\(sveBuiltin("mul", operands, for: element, predication: "x"));
        const \(type) high = (\(type))\(sveBuiltin("mulh", operands, for: element, predication: "x"));
        \(vectorResult("lane ? \(interleaved("trn2")) : \(interleaved("trn1"))", for: element))
        """
}

func carrylessMultiplyingEmulated(for element: Element) -> String {
    let vector = element.cVector
    let raw = element.cRawVector
    let product = cFunctionName(carrylessBlockProductName, element)
    func multiplied(_ first: Int, _ second: Int) -> String {
        "(\(vector))\(product)((\(raw))a\(first), (\(raw))b\(second), lane)"
    }
    func combined(_ products: [(Int, Int)]) -> String {
        products.map { multiplied($0.0, $0.1) }.joined(separator: " ^ ")
    }
    let pieces = (0..<4).flatMap { index in
        ["a", "b"].map { "const \(vector) \($0)\(index) = \($0) & \(carrylessMasks[index]);" }
    }
    let sums = (0..<4).map { "\(vector) m\($0) = \(combined(carrylessFirstProducts[$0]));" }
    let adds = (0..<4).map { "m\($0) = m\($0) ^ (\(combined(carrylessSecondProducts[$0])));" }
    func masked(_ index: Int) -> String {
        "(m\(index) & \(carrylessMasks[index]))"
    }
    let result = "(\(masked(0)) | \(masked(1))) | (\(masked(2)) | \(masked(3)))"
    return (pieces + sums + adds + [vectorResult(result, for: element)]).joined(separator: "\n")
}

func carrylessLanesHelpers(for element: Element) -> String {
    let lanes = cFunctionName(carrylessLanesName, element)
    let combinations = [
        ("Masked", "&", "\(element.cType) mask", "mask"),
        ("Xor", "^", "\(lanes) b", "b.raw[i]"),
        ("Or", "|", "\(lanes) b", "b.raw[i]"),
    ]
    let combining = combinations.map { name, symbol, parameter, operand in
        cFunction(
            returns: lanes,
            name: cFunctionName(carrylessLanesName + name, element),
            parameters: ["\(lanes) a", parameter],
            body: """
                for (size_t i = 0; i < \(element.laneCount); ++i) {
                  a.raw[i] \(symbol)= \(operand);
                }
                return a;
                """
        )
    }
    let multiplying = cFunction(
        returns: lanes,
        name: cFunctionName(carrylessLanesName + "Product", element),
        parameters: ["\(lanes) a", "\(lanes) b", "size_t lane"],
        body: """
            \(lanes) product;
            product.raw[0] = \(cFunctionName(carrylessWideProductName, element))(a.raw[lane], b.raw[lane], &product.raw[1]);
            return product;
            """
    )
    let typedef = "typedef struct { \(element.cType) raw[\(element.laneCount)]; } \(lanes);\n"
    return ([typedef] + combining + [multiplying]).joined(separator: "\n")
}

func carrylessMultiplyingEmulatedLanes(for element: Element) -> String {
    let lanes = cFunctionName(carrylessLanesName, element)
    func call(_ name: String, _ arguments: [String]) -> String {
        "\(cFunctionName(carrylessLanesName + name, element))(\(arguments.joined(separator: ", ")))"
    }
    func combined(_ products: [(Int, Int)]) -> String {
        call("Xor", products.map { call("Product", ["a\($0.0)", "b\($0.1)", "lane"]) })
    }
    let copies = ["a", "b"].flatMap {
        ["\(lanes) \($0)Lanes;", "__builtin_memcpy(&\($0)Lanes, &\($0), sizeof \($0)Lanes);"]
    }
    let pieces = (0..<4).flatMap { index in
        ["a", "b"].map {
            "const \(lanes) \($0)\(index) = \(call("Masked", ["\($0)Lanes", carrylessMasks[index]]));"
        }
    }
    let sums = (0..<4).map { "\(lanes) m\($0) = \(combined(carrylessFirstProducts[$0]));" }
    let adds = (0..<4).map {
        "m\($0) = \(call("Xor", ["m\($0)", combined(carrylessSecondProducts[$0])]));"
    }
    func masked(_ index: Int) -> String {
        call("Masked", ["m\(index)", carrylessMasks[index]])
    }
    let result = call(
        "Or",
        [call("Or", [masked(0), masked(1)]), call("Or", [masked(2), masked(3)])]
    )
    let combinedLanes = [
        "const \(lanes) result = \(result);",
        "\(element.cVector) vector;",
        "__builtin_memcpy(&vector, &result, sizeof vector);",
        vectorResult("vector", for: element),
    ]
    return (copies + pieces + sums + adds + combinedLanes).joined(separator: "\n")
}

func aesRoundOp(_ round: AesRound) -> Op {
    let blockwise: (Element) -> String = { x86AesRound(round, for: $0) }
    return Op(
        round.swiftName,
        round.highwayName,
        [.vector, .vector],
        .vector,
        .unsigned(bits: [8]),
        section: .crypto,
        vectorLabels: ["_", "roundKey"],
        targets: TargetBodies(
            neon: { neonAesRound(round, for: $0) },
            sve2_128: { sveAesRound(round, for: $0) },
            avx3dl: { x86Avx3DlAesRound(round, for: $0) },
            avx3: blockwise,
            avx2: blockwise,
            sse4: blockwise
        ),
        helpers: .everywhere(
            emulatedFunction(round.emulatedName, vectors: 2) {
                aesEmulatedRound(round, for: $0)
            }
        )
    ) { element in
        aesRoundEmulatedCall(round, for: element)
    }
}

func carrylessMultiplyingOp(
    _ swiftName: String,
    _ highwayName: String,
    upper: Bool,
    helpers: TargetBodies<Element> = TargetBodies()
) -> Op {
    let blockwise: (Element) -> String = { x86CarrylessMultiplying(upper: upper, for: $0) }
    return Op(
        swiftName,
        highwayName,
        [.vector, .vector],
        .vector,
        .unsigned(bits: [64]),
        section: .crypto,
        targets: TargetBodies(
            neon: { neonCarrylessMultiplying(upper: upper, for: $0) },
            sve2_128: { sveCarrylessMultiplying(upper: upper, for: $0) },
            avx3dl: { x86Avx3DlCarrylessMultiplying(upper: upper, for: $0) },
            avx3: blockwise,
            avx2: blockwise,
            sse4: blockwise
        ),
        helpers: helpers
    ) { element in
        carrylessMultiplyingEmulatedCall(upper: upper, for: element)
    }
}

let aesKeyGenerationAssistHelpers: TargetBodies<Element> = {
    let emulated = emulatedFunction(
        aesKeyGenerationAssistEmulatedName,
        vectors: 1,
        parameters: ["uint8_t roundConstant"]
    ) {
        aesEmulatedKeyGenerationAssist(for: $0)
    }
    let assisted: (Element) -> String = { element in
        "\(emulated(element))\n\(x86AesKeyGenerationAssistHelper(for: element))"
    }
    return TargetBodies(
        neon: emulated,
        avx3dl: emulated,
        avx3: assisted,
        avx2: assisted,
        sse4: assisted,
        sse2: emulated,
        emu128: emulated
    )
}()

let carrylessMultiplyingHelpers: TargetBodies<Element> = {
    let lane = ["size_t lane"]
    let blockProduct = emulatedFunction(carrylessBlockProductName, vectors: 2, parameters: lane) {
        carrylessBlockProduct(for: $0)
    }
    let sveBlockProduct = emulatedFunction(
        carrylessBlockProductName,
        vectors: 2,
        parameters: lane
    ) {
        sveCarrylessBlockProduct(for: $0)
    }
    let emulated = emulatedFunction(
        carrylessMultiplyingEmulatedName,
        vectors: 2,
        parameters: lane
    ) {
        carrylessMultiplyingEmulated(for: $0)
    }
    var helpers = TargetBodies<Element>.everywhere { element in
        [carrylessWideProduct(for: element), blockProduct(element), emulated(element)]
            .joined(separator: "\n")
    }
    helpers.sve2_128 = { element in
        [sveBlockProduct(element), emulated(element)].joined(separator: "\n")
    }
    let emulatedLanes = emulatedFunction(
        carrylessMultiplyingEmulatedName,
        vectors: 2,
        parameters: lane
    ) {
        carrylessMultiplyingEmulatedLanes(for: $0)
    }
    helpers.emu128 = { element in
        [
            carrylessWideProduct(for: element), carrylessLanesHelpers(for: element),
            emulatedLanes(element),
        ]
        .joined(separator: "\n")
    }
    return helpers
}()

let cryptoOps: [Op] =
    aesRounds.map(aesRoundOp) + [
