enum TrueLane {
    case first
    case last
}

enum ByteBroadcast {
    case quadwords
    case words
}

enum FirstTrueSet {
    case onlyFirst
    case beforeFirst
    case atOrBeforeFirst
    case atOrAfterFirst
}

func maskBitsType(for element: Element) -> String {
    x86MaskType(lanes: element.laneCount)
}

func maskByteCount(for element: Element) -> Int {
    (element.laneCount + 7) / 8
}

func laneBit(_ lane: Int, for element: Element) -> String {
    String(1 << (element.bits == 8 ? lane % 8 : lane))
}

func expandedMask(
    from bits: String,
    lanes: Int,
    broadcasting: ByteBroadcast,
    for element: Element
) -> String {
    let width = lanes * element.bits / 8
    let unsigned = element.cUnsignedLane
    let replicated: String
    if element.bits == 8 {
        let indices = laneIndices((0..<lanes).map { $0 / 8 })
        let (word, count) =
            broadcasting == .quadwords ? ("uint64_t", width / 8) : ("uint32_t", width / 4)
        let words = width == 16 && broadcasting == .words ? 1 : count
        let values = Array(repeating: "(\(word))\(bits)", count: words)
        replicated = """
            typedef \(word) expanded_words __attribute__((vector_size(\(width))));
            const expanded_vector bytes = (expanded_vector)(expanded_words){\(values.joined(separator: ", "))};
            const expanded_vector replicated = __builtin_shufflevector(bytes, bytes, \(indices));
            """
    } else {
        let repeated = splat("(\(unsigned))\(bits)", as: "expanded_vector", lanes: lanes)
        replicated = "const expanded_vector replicated = \(repeated);"
    }
    let bit = compoundLiteral("expanded_vector", (0..<lanes).map { laneBit($0, for: element) })
    return """
        typedef \(unsigned) expanded_vector __attribute__((vector_size(\(width))));
        typedef \(element.cMaskLane) expanded_mask __attribute__((vector_size(\(width))));
        \(replicated)
        const expanded_vector bit = \(bit);
        const expanded_mask expanded = (expanded_mask)((replicated & bit) == bit);
        """
}

func vectorRepeatingBlockMask(
    broadcasting: ByteBroadcast = .words,
    for element: Element
) -> String {
    let lanes = element.blockLaneCount
    let expanded = expandedMask(
        from: "maskBits",
        lanes: lanes,
        broadcasting: broadcasting,
        for: element
    )
    let blocks = Array(repeating: Array(0..<lanes), count: element.width / 16).flatMap { $0 }
    let replicated =
        blocks.count == lanes
        ? "expanded" : "__builtin_shufflevector(expanded, expanded, \(laneIndices(blocks)))"
    return """
        const unsigned maskBits = (unsigned)bits;
        \(expanded)
        \(maskResult(replicated, for: element))
        """
}

func x86Avx3RepeatingBlockMask(for element: Element) -> String {
    let lanes = element.blockLaneCount
    let block = x86Avx3MaskVector(
        "((unsigned)bits & 0x\(String((1 << lanes) - 1, radix: 16)))",
        for: element
    )
    let indices = Array(repeating: Array(0..<lanes), count: element.width / 16).flatMap { $0 }
    return """
        const \(element.cMask) block = \(block);
        \(maskResult("__builtin_shufflevector(block, block, \(laneIndices(indices)))", for: element))
        """
}

func vectorLoadMask(broadcasting: ByteBroadcast = .words, for element: Element) -> String {
    let expanded = expandedMask(
        from: "maskBits",
        lanes: element.laneCount,
        broadcasting: broadcasting,
        for: element
    )
    return """
        uint64_t maskBits = 0;
        __builtin_memcpy(&maskBits, from, \(maskByteCount(for: element)));
        \(expanded)
        \(maskResult("expanded", for: element))
        """
}

func portableRepeatingBlockMask(for element: Element) -> String {
    """
    const unsigned maskBits = (unsigned)bits;
    \(element.cMask) result;
    for (size_t i = 0; i < \(element.laneCount); ++i) {
      result[i] = ((maskBits >> i) & 1u) != 0 ? -1 : 0;
    }
    \(maskResult("result", for: element))
    """
}

func portableLoadMask(for element: Element) -> String {
    """
    \(signedElement(of: element).cType) lanes[\(element.laneCount)];
    for (size_t i = 0; i < \(element.laneCount); ++i) {
      lanes[i] = (from[i >> 3] & (1 << (i & 7))) != 0 ? -1 : 0;
    }
    \(element.cMask) result;
    __builtin_memcpy(&result, lanes, sizeof result);
    \(maskResult("result", for: element))
    """
}

func portableStoreMask(for element: Element) -> String {
    let bytes = maskByteCount(for: element)
    let clearing = (0..<bytes).map { "to[\($0)] = 0;" }
    return """
        \(signedElement(of: element).cType) lanes[\(element.laneCount)];
        __builtin_memcpy(lanes, &mask, sizeof lanes);
        \(clearing.joined(separator: "\n"))
        for (size_t i = 0; i < \(element.laneCount); ++i) {
          if (lanes[i] != 0) {
            to[i >> 3] = (uint8_t)(to[i >> 3] | (1 << (i & 7)));
          }
        }
        return \(bytes);
        """
}

func x86Avx3LoadMask(for element: Element) -> String {
    """
    \(maskBitsType(for: element)) maskBits = 0;
    __builtin_memcpy(&maskBits, from, sizeof maskBits);
    \(maskResult(x86Avx3MaskVector("maskBits", for: element), for: element))
    """
}

func portableBitsOfMask(for element: Element) -> String {
    """
    uint64_t bits = 0;
    for (size_t i = 0; i < \(element.laneCount); ++i) {
      bits |= mask[i] ? 1ull << i : 0;
    }
    return bits;
    """
}

func neonBitsOfMask(for element: Element) -> String {
    let slice = compoundLiteral(
        element.cUnsignedVector,
        (0..<element.laneCount).map { laneBit($0, for: element) }
    )
    let values =
        "const \(element.cUnsignedVector) values = (\(element.cUnsignedVector))mask & \(slice);"
    let active = "0x\(String(UInt64.max >> UInt64(64 - element.laneCount), radix: 16))"
    guard element.bits == 8 else {
        return """
            \(values)
            return (uint64_t)__builtin_reduce_add(values) & \(active);
            """
    }
    let quad = neonVector("i8")
    let half = neonVector("i8x8")
    func pairwise(_ operand: String) -> String {
        "(\(half))__builtin_neon_vpadd_v((\(half))\(operand), (\(half))\(operand), 16)"
    }
    return """
        \(values)
        const \(quad) paired = (\(quad))__builtin_neon_vpaddq_v((\(quad))values, (\(quad))values, 48);
        const \(half) x2 = __builtin_shufflevector(paired, paired, \(laneIndices(0..<8)));
        const \(half) x4 = \(pairwise("x2"));
        const \(half) x8 = \(pairwise("x4"));
        return __builtin_bit_cast(uint64_t, x8) & \(active);
        """
}

func x86MaskBitsValue(for element: Element) -> String {
    guard element.width < 64 else { return x86Avx3MaskBits("mask", for: element) }
    let bits = "(unsigned)\(x86MaskBits(for: element))"
    guard element.width == 32 && element.bits == 16 else { return bits }
    return "__builtin_ia32_pext_si(\(bits), 0xAAAAAAAAu)"
}

func x86BitsOfMask(for element: Element) -> String {
    "return (uint64_t)\(x86MaskBitsValue(for: element));"
}

func storedMaskBits(for element: Element) -> String {
    let bytes = maskByteCount(for: element)
    return """
        const uint64_t bits = \(cFunctionName("bitsOfMask", element))(rawMask);
        __builtin_memcpy(to, &bits, \(bytes));
        return \(bytes);
        """
}

func slidMask(
    _ direction: SlideDirection,
    by lanes: String? = nil,
    for element: Element
) -> String {
    let name = "slide\(lanes == nil ? "1" : "")\(uppercasedFirst(direction.rawValue))"
    let function = cFunctionName(lanes == nil ? name : "\(name)Lanes", element)
    let arguments = ["(\(element.cRawVector))rawMask"] + (lanes.map { [$0] } ?? [])
    return maskResult(
        "(\(element.cMask))\(function)(\(arguments.joined(separator: ", ")))",
        for: element
    )
}

func x86Avx3SlidMask(
    _ direction: SlideDirection,
    by lanes: String? = nil,
    for element: Element
) -> String {
    let count = element.laneCount
    let valid = count < 64 ? "0x\(String((1 << count) - 1, radix: 16))ull" : "~0ull"
    let shifted: String
    switch (direction, lanes) {
    case (.up, let lanes?): shifted = "((unsigned long long)bits << (\(lanes) & 63)) & \(valid)"
    case (.down, let lanes?): shifted = "((unsigned long long)bits & \(valid)) >> (\(lanes) & 63)"
    case (.up, nil): shifted = "__builtin_ia32_kshiftli\(x86MaskSuffix(lanes: count))(bits, 1)"
    case (.down, nil): shifted = "__builtin_ia32_kshiftri\(x86MaskSuffix(lanes: count))(bits, 1)"
    }
    return """
        const \(maskBitsType(for: element)) bits = \(x86Avx3MaskBits("mask", for: element));
        \(maskResult(x86Avx3MaskVector("(\(shifted))", for: element), for: element))
        """
}

func x86MaskSuffix(lanes: Int) -> String {
    switch lanes {
    case 64: return "di"
    case 32: return "si"
    case 16: return "hi"
    default: return "qi"
    }
}

func portableTrueLane(_ search: TrueLane, known: Bool, for element: Element) -> String {
    let lanes = Array(0..<element.laneCount)
    let order = search == .first ? lanes : lanes.reversed()
    let checks = order.map { "if (mask[\($0)]) {\n  return \($0);\n}" }
    return "\(checks.joined(separator: "\n"))\nreturn \(known ? "0" : "-1");"
}

func neonTrueLane(_ search: TrueLane, known: Bool, for element: Element) -> String {
    let divisor = element.bits / 2
    let index =
        search == .first
        ? "(size_t)__builtin_ctzll(nibbles) / \(divisor)"
        : "((size_t)63 - (size_t)__builtin_clzll(nibbles)) / \(divisor)"
    let result = known ? "return \(index);" : "return nibbles == 0 ? -1 : (intptr_t)(\(index));"
    return "\(neonNibbles)\n\(result)"
}

func x86TrueLaneIndex(_ search: TrueLane, of bits: String, for element: Element) -> String {
    let isWide = element.width == 64 && element.bits == 8
    let width = isWide ? 64 : 32
    switch search {
    case .first where element.width >= 32:
        return "__builtin_ia32_tzcnt_u\(width)(\(bits))"
    case .first:
        return "__builtin_ctz(\(bits) | 0x80000000u)"
    case .last:
        return "(size_t)\(width - 1) - (size_t)__builtin_clz\(isWide ? "ll" : "")(\(bits))"
    }
}

func x86TrueLane(_ search: TrueLane, known: Bool, for element: Element) -> String {
    let type = element.width == 64 && element.bits == 8 ? "unsigned long long" : "unsigned"
    let bits = "(\(type))\(x86MaskBitsValue(for: element))"
    if known { return "return (size_t)\(x86TrueLaneIndex(search, of: bits, for: element));" }
    return """
        const \(type) bits = \(bits);
        return bits ? (intptr_t)(\(x86TrueLaneIndex(search, of: "bits", for: element))) : -1;
        """
}

func portableFirstTrueSet(_ kind: FirstTrueSet, for element: Element) -> String {
    let unsigned = element.cUnsignedLane
    let signed = element.cMaskLane
    let declaration = "\(element.cMask) result;"
    let remaining = "\(unsigned) remaining = (\(unsigned))~(\(unsigned))0;"
    let none = "(\(unsigned))-(\(signed))(mask[i] == 0)"
    switch kind {
    case .atOrAfterFirst:
        return """
            \(declaration)
            \(unsigned) found = 0;
            for (size_t i = 0; i < \(element.laneCount); ++i) {
              found = (\(unsigned))(found | (\(unsigned))mask[i]);
              result[i] = (\(signed))found;
            }
            \(maskResult("result", for: element))
            """
    case .beforeFirst:
        return """
            \(declaration)
            \(unsigned) found = 0;
            for (size_t i = 0; i < \(element.laneCount); ++i) {
              found = (\(unsigned))(found | (\(unsigned))mask[i]);
              result[i] = (\(signed))(\(unsigned))~found;
            }
            \(maskResult("result", for: element))
            """
    case .onlyFirst:
        return """
            \(declaration)
            \(remaining)
            for (size_t i = 0; i < \(element.laneCount); ++i) {
              result[i] = (\(signed))((\(unsigned))mask[i] & remaining);
              remaining = (\(unsigned))(remaining & \(none));
            }
            \(maskResult("result", for: element))
            """
    case .atOrBeforeFirst:
        return """
            \(declaration)
            \(remaining)
            for (size_t i = 0; i < \(element.laneCount); ++i) {
              result[i] = (\(signed))remaining;
              remaining = (\(unsigned))(remaining & \(none));
            }
            \(maskResult("result", for: element))
            """
    }
}

func vectorAtOrAfterFirst(of operand: String, isX86: Bool, for element: Element) -> String {
    let width = element.width
    let isWide = width > 16
    let pairs = isWide ? "wide_pairs" : "pair_vector"
    let typedefs = """
        typedef uint64_t \(pairs) __attribute__((vector_size(\(width))));
        """
    if element.bits == 64 && !isWide {
        return
            "const \(element.cMask) after = \(operand) | __builtin_shufflevector(\(operand), \(operand), 0, 0);"
    }
    let words = isWide ? "wide_words" : "half_words"
    let wordTypedef = "typedef int32_t \(words) __attribute__((vector_size(\(width))));"
    guard isWide else {
        guard isX86 else {
            return """
                \(typedefs)
                typedef int64_t signed_pairs __attribute__((vector_size(16)));
                const \(pairs) whole = (\(pairs))\(operand);
                const \(pairs) spread = whole | -whole;
                const signed_pairs carried = (signed_pairs)__builtin_shufflevector((\(pairs)){0}, spread, 0, 2) >> 63;
                const \(element.cMask) after = (\(element.cMask))(spread | (\(pairs))carried);
                """
        }
        return """
            \(typedefs)
            \(wordTypedef)
            const \(pairs) whole = (\(pairs))\(operand);
            const \(pairs) spread = whole | -whole;
            const \(words) carried = __builtin_shufflevector((\(words)){0}, (\(words))spread, 0, 0, 5, 5) >> 31;
            const \(element.cMask) after = (\(element.cMask))(spread | (\(pairs))carried);
            """
    }
    return """
        \(typedefs)
        \(wordTypedef)
        typedef int32_t half_words __attribute__((vector_size(16)));
        const \(pairs) whole = (\(pairs))\(operand);
        const \(pairs) spread = whole | -whole;
        const \(words) carried = __builtin_shufflevector((\(words)){0}, (\(words))spread, 0, 0, 9, 9, 4, 4, 13, 13) >> 31;
        const \(pairs) spreadAcross = (\(pairs))carried | spread;
        const half_words low = __builtin_shufflevector((\(words))spreadAcross, (\(words))spreadAcross, 0, 1, 2, 3);
        const half_words top = __builtin_shufflevector(low, low, 3, 3, 3, 3) >> 31;
        const \(words) upper = __builtin_shufflevector((half_words){0}, top, 0, 1, 2, 3, 4, 5, 6, 7);
        const \(element.cMask) after = (\(element.cMask))((\(pairs))upper | spreadAcross);
        """
}

func vectorOnlyFirst(for element: Element) -> String {
    let width = element.width
    let unsigned = element.cUnsignedVector
    guard width > 16 else {
        return """
            typedef uint64_t pair_vector __attribute__((vector_size(16)));
            const pair_vector whole = (pair_vector)mask;
            const pair_vector zero = {0};
            const pair_vector later = (pair_vector)(__builtin_shufflevector(zero, whole, 0, 2) == zero);
            \(element.bits == 64
                ? maskResult("(\(element.cMask))(whole & later)", for: element)
                : """
                const \(unsigned) lowest = (\(unsigned))(whole & -whole);
                \(maskResult("(\(element.cMask))(-lowest & (\(unsigned))later)", for: element))
                """)
            """
    }
    return """
        typedef uint64_t wide_pairs __attribute__((vector_size(32)));
        typedef uint64_t half_pairs __attribute__((vector_size(16)));
        const wide_pairs whole = (wide_pairs)mask;
        const wide_pairs zeroes = (wide_pairs)(whole == (wide_pairs){0});
        const half_pairs lower = __builtin_shufflevector(zeroes, zeroes, 0, 1);
        const half_pairs lowerPrefix = lower & __builtin_shufflevector(lower, lower, 0, 0);
        const half_pairs upper = __builtin_shufflevector(zeroes, zeroes, 2, 3);
        const half_pairs upperPrefix = __builtin_shufflevector(lowerPrefix, upper, 1, 2) & __builtin_shufflevector(lowerPrefix, lowerPrefix, 1, 1);
        const half_pairs lowerStart = __builtin_shufflevector((half_pairs){~0ull, ~0ull}, lowerPrefix, 0, 2);
        const wide_pairs later = __builtin_shufflevector(lowerStart, upperPrefix, 0, 1, 2, 3);
        const \(unsigned) lowest = (\(unsigned))(whole & -whole);
        \(maskResult("(\(element.cMask))(-lowest & (\(unsigned))later)", for: element))
        """
}

func vectorSlide1Up(of operand: String, into result: String, for element: Element) -> String {
    guard element.width > 16 else {
        let slide = cFunctionName("slide1Up", element)
        return
            "const \(element.cMask) \(result) = (\(element.cMask))\(slide)((\(element.cRawVector))rawMask);"
    }
    let i8 = x86Vector("i8")
    let bytes = 16 - element.bits / 8
    let shifted = x86Builtin(
        "palignr256",
        [(value: operand, type: i8), (value: "lower", type: i8), (value: "\(bytes)", type: "int")],
        returning: element.cMask
    )
    return """
        typedef uint64_t wide_pairs __attribute__((vector_size(32)));
        const wide_pairs lower = __builtin_shufflevector((wide_pairs){0}, (wide_pairs)\(operand), 0, 1, 4, 5);
        const \(element.cMask) \(result) = \(shifted);
        """
}

func vectorFirstTrueSet(_ kind: FirstTrueSet, isX86: Bool, for element: Element) -> String {
    switch kind {
    case .onlyFirst:
        return vectorOnlyFirst(for: element)
    case .atOrAfterFirst:
        return """
            \(vectorAtOrAfterFirst(of: "mask", isX86: isX86, for: element))
            \(maskResult("after", for: element))
            """
    case .beforeFirst:
        return """
            \(vectorAtOrAfterFirst(of: "mask", isX86: isX86, for: element))
            \(maskResult("~after", for: element))
            """
    case .atOrBeforeFirst:
        return """
            \(vectorSlide1Up(of: "mask", into: "shifted", for: element))
            \(vectorAtOrAfterFirst(of: "shifted", isX86: isX86, for: element))
            \(maskResult("~after", for: element))
            """
    }
}

func x86Avx3FirstTrueSet(_ kind: FirstTrueSet, for element: Element) -> String {
    let wide = element.laneCount > 32 ? "unsigned long long" : "unsigned"
    let lowest = "(bits & ((\(wide))0 - bits))"
    let result: String
    switch kind {
    case .onlyFirst: result = lowest
    case .atOrAfterFirst: result = "((\(wide))0 - \(lowest))"
    case .beforeFirst: result = "(\(lowest) - 1)"
    case .atOrBeforeFirst: result = "(bits ^ (bits - 1))"
    }
    return """
        const \(wide) bits = (\(wide))\(x86Avx3MaskBits("mask", for: element));
        \(maskResult(x86Avx3MaskVector(result, for: element), for: element))
        """
}

func svePredicate(of operand: String, for element: Element) -> String {
    let compared = element.category == .float ? element : unsignedElement(of: element)
    let lanes = "(\(sveVector(compared.cSuffix)))\(operand)"
    return sveBuiltin("cmpne_n", [sveAllLanes(of: element), lanes, "0"], for: compared)
}

func sveMaskVector(_ predicate: String, for element: Element) -> String {
    let unsigned = unsignedElement(of: element)
    let selected = sveBuiltin(
        "sel",
        [
            predicate,
            sveBuiltin("dup_n", ["(\(unsigned.cType))-1"], for: unsigned),
            sveBuiltin("dup_n", ["0"], for: unsigned),
        ],
        for: unsigned
    )
    return maskResult("(\(element.cMask))(\(sveVector(unsigned.cSuffix)))\(selected)", for: element)
}

func sveVectorLanes(for element: Element) -> String {
    "__builtin_sve_svptrue_pat_b\(element.bits)(\(min(element.laneCount, 9)))"
}

func sveFirstTrueSet(_ kind: FirstTrueSet, for element: Element) -> String? {
    guard kind == .onlyFirst || element.bits < 64 else { return nil }
    let all = sveAllLanes(of: unsignedElement(bits: 8))
    let selected: String
    switch kind {
    case .onlyFirst: selected = "__builtin_sve_svbrka_b_z(active, active)"
    case .beforeFirst: selected = "__builtin_sve_svbrkb_b_z(\(all), active)"
    case .atOrBeforeFirst: selected = "__builtin_sve_svbrka_b_z(\(all), active)"
    case .atOrAfterFirst:
        selected = "__builtin_sve_svnot_b_z(\(all), __builtin_sve_svbrkb_b_z(\(all), active))"
    }
    return """
        const __SVBool_t active = \(svePredicate(of: "mask", for: element));
        \(sveMaskVector(selected, for: element))
        """
}

func sveKnownFirstTrue(for element: Element) -> String {
    """
    const __SVBool_t active = \(svePredicate(of: "mask", for: element));
    const __SVBool_t lanes = \(sveVectorLanes(for: element));
    return __builtin_sve_svcntp_b\(element.bits)(lanes, __builtin_sve_svbrkb_b_z(lanes, active));
    """
}

func sveKnownLastTrue(for element: Element) -> String {
    let unsigned = unsignedElement(of: element)
    let indices = sveBuiltin("index", ["0", "1"], for: unsigned)
    let present = "__builtin_sve_svand_b_z(lanes, lanes, active)"
    return """
        const __SVBool_t active = \(svePredicate(of: "mask", for: element));
        const \(sveVector(unsigned.cSuffix)) indices = \(indices);
        const __SVBool_t lanes = \(sveVectorLanes(for: element));
        return (size_t)\(sveBuiltin("lastb", [present, "indices"], for: unsigned));
        """
}

func sveSelectingByVector(for element: Element) -> String {
    let unsigned = unsignedElement(of: element)
    let operands = ["b", "c", "a"].map {
        sveSplatOperand("((\(unsigned.cVector))\($0))", for: unsigned)
    }
    let selected = sveBuiltin("bsl", operands, for: unsigned)
    return vectorResult(
        "(\(element.cVector))(\(sveVector(unsigned.cSuffix)))\(selected)",
        for: element
    )
}

