        "ExclusiveNeither",
        [.mask, .mask],
        .mask,
        .all,
        section: .logicalMask,
        targets: TargetBodies(avx3: { element in maskResult("~(a ^ b)", for: element) })
    ) { element in
        maskResult("~a & ~b", for: element)
    },
    Op(
        "onlyFirstTrue",
        "SetOnlyFirst",
        [.mask],
        .mask,
        .all,
        section: .logicalMask,
        targets: TargetBodies(
            neon: { element in vectorFirstTrueSet(.onlyFirst, isX86: false, for: element) },
            sve2_128: { element in sveFirstTrueSet(.onlyFirst, for: element) },
            avx3: { element in x86Avx3FirstTrueSet(.onlyFirst, for: element) },
            avx2: { element in vectorFirstTrueSet(.onlyFirst, isX86: true, for: element) },
            sse2: { element in vectorFirstTrueSet(.onlyFirst, isX86: true, for: element) }
        )
    ) { element in
        portableFirstTrueSet(.onlyFirst, for: element)
    },
    Op(
        "beforeFirstTrue",
        "SetBeforeFirst",
        [.mask],
        .mask,
        .all,
        section: .logicalMask,
        targets: TargetBodies(
            neon: { element in vectorFirstTrueSet(.beforeFirst, isX86: false, for: element) },
            sve2_128: { element in sveFirstTrueSet(.beforeFirst, for: element) },
            avx3: { element in x86Avx3FirstTrueSet(.beforeFirst, for: element) },
            avx2: { element in vectorFirstTrueSet(.beforeFirst, isX86: true, for: element) },
            sse2: { element in vectorFirstTrueSet(.beforeFirst, isX86: true, for: element) }
        )
    ) { element in
        portableFirstTrueSet(.beforeFirst, for: element)
    },
    Op(
        "atOrBeforeFirstTrue",
        "SetAtOrBeforeFirst",
        [.mask],
        .mask,
        .all,
        section: .logicalMask,
        targets: TargetBodies(
            neon: { element in vectorFirstTrueSet(.atOrBeforeFirst, isX86: false, for: element) },
            sve2_128: { element in sveFirstTrueSet(.atOrBeforeFirst, for: element) },
            avx3: { element in x86Avx3FirstTrueSet(.atOrBeforeFirst, for: element) },
            avx2: { element in vectorFirstTrueSet(.atOrBeforeFirst, isX86: true, for: element) },
            sse2: { element in vectorFirstTrueSet(.atOrBeforeFirst, isX86: true, for: element) }
        )
    ) { element in
        portableFirstTrueSet(.atOrBeforeFirst, for: element)
    },
    Op(
        "atOrAfterFirstTrue",
        "SetAtOrAfterFirst",
        [.mask],
        .mask,
        .all,
        section: .logicalMask,
        targets: TargetBodies(
            neon: { element in vectorFirstTrueSet(.atOrAfterFirst, isX86: false, for: element) },
            sve2_128: { element in sveFirstTrueSet(.atOrAfterFirst, for: element) },
            avx3: { element in x86Avx3FirstTrueSet(.atOrAfterFirst, for: element) },
            avx2: { element in vectorFirstTrueSet(.atOrAfterFirst, isX86: true, for: element) },
            sse2: { element in vectorFirstTrueSet(.atOrAfterFirst, isX86: true, for: element) }
        )
    ) { element in
        portableFirstTrueSet(.atOrAfterFirst, for: element)
    },
]

struct MaskComposition {
    let outer: Op
    let inner: Op

    var name: String { "\(outer.identifier)Of\(uppercasedFirst(inner.identifier))" }
}

let firstTrueSettingOps = [
    "onlyFirstTrue", "beforeFirstTrue", "atOrBeforeFirstTrue", "atOrAfterFirstTrue",
]
let firstTrueSettingSources = ["bitwiseNotMask", "neitherTrue"]

func firstTrueCompositions(for element: Element) -> [MaskComposition] {
    let applying = ops.filter { $0.applies.matches(element) }
    return firstTrueSettingOps.flatMap { outerName in
        firstTrueSettingSources.compactMap { innerName in
            guard let outer = applying.first(where: { $0.identifier == outerName }),
                let inner = applying.first(where: { $0.identifier == innerName })
            else { return nil }
            return MaskComposition(outer: outer, inner: inner)
        }
    }
}

func maskCompositionReferenceFunction(
    _ composition: MaskComposition,
    for element: Element
) -> String {
    let parameterBindings = bindings(of: composition.inner, for: element)
    let declarations = parameterBindings.map(\.declaration).filter { !$0.isEmpty }
    let arguments = parameterBindings.map(\.argument).filter { !$0.isEmpty }
    let inner = "hn::\(composition.inner.highwayName)(\(arguments.joined(separator: ", ")))"
    let body = referenceBody(
        calling: "hn::\(composition.outer.highwayName)(\(inner))",
        returning: composition.outer.returns,
        for: element
    )
    let name = referenceFunctionName(composition.name, element)
    return "HWY_INLINE \(cReturnType(composition.outer.returns, element)) "
        + "\(name)(\(declarations.joined(separator: ", "))) { \(body) }\n"
}

func maskCompositionTest(_ composition: MaskComposition, for element: Element) -> String {
    let test = composition.name
    let innerBindings = bindings(of: composition.inner, for: element)
    let operands = zip(innerBindings, composition.inner.parameters).filter { !$0.1.isTag }
    let inputs = operands.enumerated().map { index, operand in
        let seed = "seed: \(referenceTestSeed(element, test, String(index)))"
        return ReferenceInput(
            parameter: operand.1,
            name: operand.0.swiftName,
            values: "Inputs.masksAndComplements(H.Mask.self, \(seed))"
        )
    }
    let calls = referenceCalls(
        of: composition.inner,
        for: element,
        pointer: "",
        referenceName: referenceFunctionName(composition.name, element)
    )
    let outerBindings = bindings(of: composition.outer, for: element)
    let outerOperands = zip(outerBindings, composition.outer.parameters).filter { !$0.1.isTag }
    let port = portCall(
        composition.outer.swiftName,
        outerOperands.map { swiftCallArgument($0.0, passing: calls.port) }
    )
    return referenceTestFunction(
        test,
        label: "\(composition.outer.testIdentifier) of \(composition.inner.testIdentifier)",
        for: element,
        inputs: inputs,
        statements:
            "mismatches.check(\(port), \(calls.reference), \(referenceDescription(of: inputs)))"
    )
}

func firstTrueCompositionMembers(of element: Element, by keys: Set<String>?) -> [SectionMember] {
    firstTrueCompositions(for: element).filter { composition in
        isTested(
            codegenKeys(of: composition.outer, for: element)
                + codegenKeys(of: composition.inner, for: element),
            by: keys
        )
    }.map { composition in
        SectionMember(
            section: composition.outer.section,
            inside: markingKnownGaps(
                [maskCompositionTest(composition, for: element)],
                suite: "\(element.namespace)Reference"
            )
        )
    }
}

func shuffled(
    _ first: String,
    _ second: String,
    _ indices: [Int],
    for element: Element
) -> String {
    vectorResult(
        "__builtin_shufflevector(\(first), \(second), \(laneIndices(indices)))",
        for: element
    )
}

func blockwiseIndices(_ pattern: [Int], for element: Element) -> [Int] {
    let blockLanes = element.blockLaneCount
    return (0..<element.width / 16).flatMap { block in
        pattern.map {
            $0 < blockLanes
                ? block * blockLanes + $0
                : element.laneCount + block * blockLanes + $0 - blockLanes
        }
    }
}

func blockIndices(_ blocks: [(block: Int, second: Bool)], for element: Element) -> [Int] {
    let blockLanes = element.blockLaneCount
    return blocks.flatMap { block, second in
        (0..<blockLanes).map { (second ? element.laneCount : 0) + block * blockLanes + $0 }
    }
}

func interleavedBlocks(
    _ source: @escaping (_ pair: Int, _ blocks: Int) -> Int
) -> (Element) -> [Int] {
    { element in
        let blocks = element.width / 16
        return blockIndices(
            (0..<blocks).map { (source($0 / 2, blocks), $0 % 2 == 1) },
            for: element
        )
    }
}

struct FixedPermutation {
    let swiftName: String
    let highwayName: String
    let parameters: [Parameter]
    let applies: Applies
    let section: Section
    var targets = TargetBodies<Element>()
    var helpers = TargetBodies<Element>()
    var sse2Only: ((Element) -> String?)?
    var lowerFirst = false
    var laneCapability: LaneCapability?
    let indices: (Element) -> [Int]
}

func x86SelectedOddEven(
    odd: String,
    even: String,
    level: X86Level,
    for element: Element
) -> String {
    if element.bits == 16 && level >= .sse4 {
        let words = x86Vector("i16")
        let blend = "pblendw\(x86Bits(element.width))"
        return
            "(\(element.cVector))__builtin_ia32_\(blend)((\(words))\(odd), (\(words))\(even), 0x55)"
    }
    let lanes = (0..<element.laneCount).map { $0 % 2 == 0 ? "-1" : "0" }
    let mask = compoundLiteral(element.cMask, lanes)
    let arguments = [
        "(\(element.cRawMask))\(mask)", "(\(element.cRawVector))\(even)",
        "(\(element.cRawVector))\(odd)",
    ]
    return
        "(\(element.cVector))\(cFunctionName("selecting", element))(\(arguments.joined(separator: ", ")))"
}

func x86OpaqueFloat(_ operand: String, bits: Int) -> String {
    "\(x86AsFloatName(bits: bits))((\(x86Vector("i64")))\(operand))"
}

func x86OddEvenLanes(level: X86Level, for element: Element) -> String? {
    guard element.width == 16 else { return nil }
    if element.bits == 64 && element.category != .float {
        return x86ConcatenatedUpperLower(level: level, for: element)
    }
    guard element.bits <= 16 else { return nil }
    return vectorResult(
        x86SelectedOddEven(odd: "a", even: "b", level: level, for: element),
        for: element
    )
}

func x86InterleavedParity(
    even isEven: Bool,
    level: X86Level,
    for element: Element
) -> String? {
    guard element.width <= 32 else { return nil }
    if element.width == 16 && element.bits == 32 && element.category != .float {
        let lanes = isEven ? "0, 2, 4, 6" : "1, 3, 5, 7"
        let pairs =
            "__builtin_shufflevector(\(x86OpaqueFloat("a", bits: 32)), \(x86OpaqueFloat("b", bits: 32)), \(lanes))"
        return """
            const \(x86Vector("f32")) pairs = \(pairs);
            \(vectorResult("__builtin_shufflevector(pairs, pairs, 0, 2, 1, 3)", for: element))
            """
    }
    guard element.bits <= 16 else { return nil }
    let word = unsignedElement(bits: 2 * element.bits)
    let typedef = vectorTypedef("wide_vector", of: word, lanes: element.laneCount / 2)
    let shifted =
        isEven
        ? "(\(element.cVector))((wide_vector)b << \(element.bits))"
        : "(\(element.cVector))((wide_vector)a >> \(element.bits))"
    let (odd, even) = isEven ? (shifted, "a") : ("b", shifted)
    let selected = x86SelectedOddEven(odd: odd, even: even, level: level, for: element)
    return "\(typedef)\n\(vectorResult(selected, for: element))"
}

func x86ConcatenatedUpperLower(level: X86Level, for element: Element) -> String? {
    guard element.width == 16 else { return nil }
    if element.bits == 32 && element.category == .float && level < .sse4 {
        return vectorResult("__builtin_shufflevector(b, a, 0, 1, 6, 7)", for: element)
    }
    let doubles = x86Vector("f64")
    let operands =
        element.category == .float
        ? ["b", "a"].map { "(\(doubles))\($0)" } : ["b", "a"].map { x86OpaqueFloat($0, bits: 64) }
    let shuffle = "__builtin_shufflevector(\(operands[0]), \(operands[1]), 0, 3)"
    return vectorResult("(\(element.cVector))\(shuffle)", for: element)
}

func sveCompressed(not: Bool, for element: Element) -> String? {
    if element.bits <= 16 { return sveCompressedNarrow(not: not, for: element) }
    guard element.bits == 32 else { return nil }
    let unsigned = unsignedElement(of: element)
    let all = sveAllLanes(of: element)
    let nonzero = sveBuiltin(
        "cmpne_n",
        [all, "(\(sveVector(unsigned.cSuffix)))mask", "0"],
        for: unsigned
    )
    let selected = not ? "__builtin_sve_svnot_b_z(\(all), \(nonzero))" : nonzero
    let compact = sveBuiltin("compact", [selected, sveOperand("a", for: element)], for: element)
    return vectorResult(sveResult(compact, for: element), for: element)
}

func sveCompressedLanes(
    of source: String,
    active: String,
    prefix: String,
    splat: (condition: String, lane: String),
    for element: Element
) -> (statements: [String], result: String) {
    let wide = widenedElement(of: element)
    let narrowVector = sveVector(element.cSuffix)
    let wideVector = sveVector(wide.cSuffix)
    var statements: [String] = []
    let duplicated = sveBuiltin("dup_n", [splat.lane], for: wide)
    for (half, part) in [("Low", "lo"), ("High", "hi")] {
        let name = "\(prefix)\(half)"
        let unpacked = sveBuiltin("unpk\(part)", [source], for: wide)
        let widened = "(\(splat.condition) ? \(duplicated) : \(unpacked))"
        statements.append(
            "const __SVBool_t \(name)Active = __builtin_sve_svunpk\(part)_b(\(active));"
        )
        if wide.bits == 32 {
            let compact = sveBuiltin("compact", ["\(name)Active", widened], for: wide)
            statements.append("const \(wideVector) \(name)Wide = \(compact);")
        } else {
            statements.append("const \(wideVector) \(name)Source = \(widened);")
            let inner = sveCompressedLanes(
                of: "\(name)Source",
                active: "\(name)Active",
                prefix: name,
                splat: splat,
                for: wide
            )
            statements += inner.statements
            statements.append("const \(wideVector) \(name)Wide = \(inner.result);")
        }
        let narrowed = "(\(narrowVector))\(name)Wide"
        statements.append(
            "const \(narrowVector) \(name)Narrow = \(sveBuiltin("uzp1", [narrowed, narrowed], for: element));"
        )
    }
    let count = "__builtin_sve_svcntp_b\(wide.bits)(all, \(prefix)LowActive)"
    let spliced = sveBuiltin(
        "splice",
        [sveActiveLanes(count, for: element), "\(prefix)LowNarrow", "\(prefix)HighNarrow"],
        for: element
    )
    return (statements, spliced)
}

func sveSourceSplat(for element: Element) -> (condition: String, lane: String) {
    (
        "\(cFunctionName("sveSplat", element))((\(element.cVector))source)",
        "source[0]"
    )
}

func sveCompressedNarrow(not: Bool, for element: Element) -> String {
    let unsigned = unsignedElement(of: element)
    let selected = sveBuiltin(
        not ? "cmpeq_n" : "cmpne_n",
        ["all", "(\(sveVector(unsigned.cSuffix)))mask", "0"],
        for: unsigned
    )
    let compressed = sveCompressedLanes(
        of: "source",
        active: "active",
        prefix: "compressed",
        splat: sveSourceSplat(for: element),
        for: element
    )
    return """
        const \(sveVector(element.cSuffix)) source = \(sveOperand("a", for: element));
        const __SVBool_t all = \(sveAllLanes(of: element));
        const __SVBool_t active = \(selected);
        \(compressed.statements.joined(separator: "\n"))
        \(vectorResult(sveResult(compressed.result, for: element), for: element))
        """
}

func sveShuffled(
    _ name: String,
    _ first: String,
    _ second: String,
    viewing view: Element? = nil,
    for element: Element
) -> String {
    let lanes = view ?? element
    let operands = [first, second].map { sveOperand($0, for: lanes, splat: view == nil) }
    let call = sveBuiltin(name, operands, for: lanes)
    let result = vectorResult("(\(element.cVector))\(sveResult(call, for: lanes))", for: element)
    return view == nil ? result : "\(vectorTypedef(of: lanes))\n\(result)"
}

func sveSplatCondition(of operands: [String], for element: Element) -> String {
    operands.map { sveSplatCondition($0, nil, for: element) }.joined(separator: " || ")
}

func sveSplatExtended(for element: Element) -> String? {
    guard isInteger64(element) else { return nil }
    let operands = ["b", "a"].map { sveOperand($0, for: element, splat: true) }
    let extended = sveBuiltin("ext", operands + ["\(element.laneCount / 2)"], for: element)
    return """
        if (\(sveSplatCondition(of: ["a", "b"], for: element))) {
          \(vectorResult(sveResult(extended, for: element), for: element))
        }
        """
}

func sveSplatSelectedLower(for element: Element) -> String {
    let lower = "__builtin_sve_svptrue_pat_b\(element.bits)(\(element.laneCount / 2))"
    let selected = sveBuiltin(
        "sel",
        [lower, sveBuiltin("dup_n", ["b[0]"], for: element), sveOperand("a", for: element)],
        for: element
    )
    return """
        if (\(sveSplatCondition("b", nil, for: element))) {
          \(vectorResult(sveResult(selected, for: element), for: element))
        }
        """
}

func sveSplatMember(_ name: String, for element: Element) -> String {
    let duplicated = sveResult(sveBuiltin("dup_n", ["\(name)[0]"], for: element), for: element)
    let condition = sveSplatCondition(name, nil, for: element)
    return "(\(condition) ? (\(element.cRawVector))\(duplicated) : \(rawName(name)))"
}

func sveLane(for element: Element) -> String {
    let lane = sveBuiltin(
        "lasta",
        [sveActiveLanes("index", for: element), sveSplatOperand("a", for: element)],
        for: element
    )
    return """
        if (__builtin_constant_p(index)) {
          \(laneStorage(for: element))
          return storage.lanes[index];
        }
        return \(lane);
        """
}

func sveSplatPairwise(subtracting: Bool, for element: Element) -> String? {
    guard element.bits == 64 else { return nil }
    let name = cFunctionName(subtracting ? "pairwiseSubtracting" : "pairwiseAdding", element)
    return """
        if (\(sveSplatCondition(of: ["a", "b"], for: element))) {
          return \(name)(\(rawName("a")), \(rawName("b")));
        }
        """
}

func x86ConcatenatedLowerUpper(for element: Element) -> String? {
    guard element.width == 16 else { return nil }
    let longs = x86Vector("i64")
    let lower = x86ByteShift(.down, "(\(longs))b", by: 8)
    let upper = x86ByteShift(.up, "(\(longs))a", by: 8)
    return vectorResult("(\(element.cVector))(\(lower) | \(upper))", for: element)
}

func portableConcatenatedParity(parity: Int, for element: Element) -> String {
    shuffled("b", "a", concatenatedParityLanes(parity: parity, for: element), for: element)
}

func x86Avx3ConcatenatedOdd(for element: Element) -> String? {
    guard element.width == 64, element.bits == 8 else { return nil }
    let wide = unsignedElement(bits: 16)
    let typedef = vectorTypedef("wide_vector", of: wide, lanes: element.laneCount / 2)
    let words = x86Vector("i16")
    let packed = x86Builtin(
        "packuswb512",
        [
            (value: "((wide_vector)b >> 8)", type: words),
            (value: "((wide_vector)a >> 8)", type: words),
        ],
        returning: x86Vector("i64")
    )
    let indices = compoundLiteral(x86Vector("i64"), ["0", "2", "4", "6", "1", "3", "5", "7"])
    let permuted = x86Builtin(
        "permvardi512",
        [(value: packed, type: x86Vector("i64")), (value: indices, type: x86Vector("i64"))],
        returning: element.cVector
    )
    return x86ConstantOperandDispatch(
        ["a", "b"],
        constant: "\(typedef)\n\(vectorResult(permuted, for: element))",
        otherwise: portableConcatenatedParity(parity: 1, for: element),
        for: element
    )
}

func x86ConcatenatedParity(parity: Int, level: X86Level, for element: Element) -> String? {
    guard element.width == 16, element.bits <= 16 else { return nil }
    let isNative = element.bits == 8 ? parity == 1 : level == .sse2
    guard isNative else { return portableConcatenatedParity(parity: parity, for: element) }
    let wide = unsignedElement(bits: 2 * element.bits)
    let typedef =
        element.bits == 16 && parity == 1
        ? "" : "\(vectorTypedef("wide_vector", of: wide, lanes: element.laneCount / 2))\n"
    let operand = { (name: String) -> String in
        switch (element.bits, parity) {
        case (8, _): return "((wide_vector)\(name) >> 8)"
        case (_, 1): return "((\(x86Vector("i32")))\(name) >> 16)"
        default: return "((\(x86Vector("i32")))((wide_vector)\(name) << 16) >> 16)"
        }
    }
    let (builtin, lane) = element.bits == 8 ? ("packuswb128", "i16") : ("packssdw128", "i32")
    let packed = x86Builtin(
        builtin,
        [
            (value: operand("b"), type: x86Vector(lane)),
            (value: operand("a"), type: x86Vector(lane)),
        ],
        returning: element.cVector
    )
    return "\(typedef)\(vectorResult(packed, for: element))"
}

func x86Duplicated(even isEven: Bool, of operand: String, for element: Element) -> String {
    let words = vectorTypedef("wide_vector", of: unsignedElement(bits: 16), lanes: 8)
    let mask = splat(isEven ? "0xFF00" : "0x00FF", as: "wide_vector", lanes: 8)
    let shifted = "(wide_vector)\(operand) \(isEven ? "<<" : ">>") 8"
    let selected = "(mask & (\(shifted))) | (~mask & (wide_vector)\(operand))"
    return """
        \(words)
        const wide_vector mask = \(mask);
        \(vectorResult("(\(element.cVector))(\(selected))", for: element))
        """
}

func x86DuplicatedBytes(even isEven: Bool, for element: Element) -> String? {
    guard element.width == 16, element.bits == 8 else { return nil }
    return x86Duplicated(even: isEven, of: "a", for: element)
}

func x86ReversedBytes(_ source: String, group: Int, for element: Element) -> String {
    let dwords = vectorTypedef(
        "dword_vector",
        of: unsignedElement(of: unsignedElement(bits: 32)),
        lanes: 4
    )
    let shuffle = { (name: String, indices: String) in
        "__builtin_shufflevector(\(name), \(name), \(indices))"
    }
    var lines = [
        vectorTypedef("word_vector", of: unsignedElement(bits: 16), lanes: 8),
        "const word_vector words = (word_vector)\(source);",
        "const word_vector rotated = (words >> 8) | (words << 8);",
    ]
    switch group {
    case 2:
        lines.append(vectorResult("(\(element.cVector))rotated", for: element))
    case 4:
        lines.append("const word_vector swapped = \(shuffle("rotated", "1, 0, 3, 2, 5, 4, 7, 6"));")
        lines.append(vectorResult("(\(element.cVector))swapped", for: element))
    default:
        lines.append("const word_vector swapped = \(shuffle("rotated", "1, 0, 3, 2, 5, 4, 7, 6"));")
        lines.append(dwords)
        lines.append("const dword_vector dwords = (dword_vector)swapped;")
        lines.append(
            vectorResult("(\(element.cVector))\(shuffle("dwords", "1, 0, 3, 2"))", for: element)
        )
    }
    return lines.joined(separator: "\n")
}

func x86Avx3ReversedGroups(_ group: Int, for element: Element) -> String? {
    guard element.width == 64, element.bits == 16 else { return nil }
    guard group > 2 else {
        let dwords = unsignedElement(of: unsignedElement(bits: 32))
        let typedef = vectorTypedef("dword_vector", of: dwords, lanes: element.laneCount / 2)
        return """
            \(typedef)
            const dword_vector dwords = (dword_vector)a;
            \(vectorResult("(\(element.cVector))((dwords >> 16) | (dwords << 16))", for: element))
            """
    }
    let words = x86Vector("i16")
    let permuted = x86Builtin(
        "permvarhi512",
        [(value: "a", type: words), (value: "indices", type: words)],
        returning: element.cVector
    )
    return """
        \(words) indices;
        __builtin_memcpy(&indices, \(x86Avx3ReverseTableName(group, for: element))(), sizeof indices);
        \(vectorResult(permuted, for: element))
        """
}

func x86Avx3ReverseTableName(_ group: Int, for element: Element) -> String {
    "cvectorization_ops_x86_reverse\(group)_table_\(element.cSuffix)"
}

func x86Avx3ReverseHelpers(_ group: Int, for element: Element) -> String? {
    guard element.width == 64, element.bits == 16, group > 2 else { return nil }
    let bytes = reversedGroups(group, for: element).flatMap { [$0 & 0xFF, $0 >> 8] }
    return neonTable(
        named: x86Avx3ReverseTableName(group, for: element),
        bytes,
        alignment: 64,
        isHidden: true
    )
}

func x86ReversedGroups(_ group: Int, for element: Element) -> String? {
    guard element.width == 16, element.bits == 8 else { return nil }
    return x86ReversedBytes("a", group: group, for: element)
}

func x86ByteSwapped(for element: Element) -> String? {
    guard element.width == 16 else { return nil }
    return x86ReversedBytes("a", group: element.bits / 8, for: element)
}

func x86BitReversed(for element: Element) -> String? {
    guard element.width == 16 || element.width == 64 else { return nil }
    let bytes = unsignedElement(bits: 8)
    let steps = [(1, 0x55), (2, 0x33), (4, 0x0F)].map { amount, mask in
        """
        {
          const wide_vector shifting = (wide_vector)reversed;
          const \(bytes.cVector) mask = \(splat("\(mask)", as: bytes.cVector, lanes: element.width));
          const \(bytes.cVector) shiftedRight = (\(bytes.cVector))(shifting >> \(amount));
          const \(bytes.cVector) shiftedLeft = (\(bytes.cVector))(shifting << \(amount));
          reversed = (shiftedRight & mask) | (~mask & shiftedLeft);
        }
        """
    }
    let result =
        element.bits == 8
        ? vectorResult("(\(element.cVector))reversed", for: element)
        : element.width == 16
            ? x86ReversedBytes("reversed", group: element.bits / 8, for: element)
            : vectorResult(byteSwapped("reversed", for: element), for: element)
    return """
        \(vectorTypedef("wide_vector", of: unsignedElement(bits: 16), lanes: element.width / 2))
        \(bytes.cVector) reversed = (\(bytes.cVector))a;
        \(steps.joined(separator: "\n"))
        \(result)
        """
}

func portableReplacingLane(for element: Element) -> String {
    """
    \(laneStorage(for: element))
    storage.lanes[index] = value;
    \(vectorResult("storage.vector", for: element))
    """
}

func x86ReplacingLaneBytes(level: X86Level, for element: Element) -> String? {
    guard element.width == 16, element.bits == 8 else { return nil }
    let positions = iota(as: element.cVector, lanes: element.laneCount)
    let target = splat("(\(element.cType))index", as: element.cVector, lanes: element.laneCount)
    let others = level == .sse2 ? "(positions != target)" : "~selected"
    return """
        if (__builtin_constant_p(index)) {
          const \(element.cVector) positions = \(positions);
          const \(element.cVector) target = \(target);
          const \(element.cVector) selected = (\(element.cVector))(positions == target);
          const \(element.cVector) others = (\(element.cVector))\(others);
          \(vectorResult("(selected & \(repeatingVector("value", of: element))) | (others & a)", for: element))
        }
        \(portableReplacingLane(for: element))
        """
}

func x86Avx2ConcatenatedParity(parity: Int, for element: Element) -> String? {
    guard element.width == 32, element.bits <= 16 else { return nil }
    let wide = unsignedElement(bits: 2 * element.bits)
    let typedef = vectorTypedef("wide_vector", of: wide, lanes: element.laneCount / 2)
    let mask = splat(
        element.bits == 8 ? "0x00FF" : "0x0000FFFF",
        as: "wide_vector",
        lanes: element.laneCount / 2
    )
    let operand = { (name: String) in
        parity == 1
            ? "((wide_vector)\(name) >> \(element.bits))" : "((wide_vector)\(name) & \(mask))"
    }
    let (builtin, lane) = element.bits == 8 ? ("packuswb256", "i16") : ("packusdw256", "i32")
    let i64 = x86Vector("i64")
    let packed = x86Builtin(
        builtin,
        [
            (value: operand("b"), type: x86Vector(lane)),
            (value: operand("a"), type: x86Vector(lane)),
        ],
        returning: i64
    )
    let permuted = x86Builtin(
        "permdi256",
        [(value: packed, type: i64), (value: "0xD8", type: "int")],
        returning: element.cVector
    )
    let native = "\(typedef)\n\(vectorResult(permuted, for: element))"
    guard parity == 0 else { return native }
    return x86ConstantOperandDispatch(
        ["a", "b"],
        constant: native,
        otherwise: portableConcatenatedParity(parity: 0, for: element),
        for: element
    )
}

func x86Avx3WholeTableName(upper: Bool, for element: Element) -> String {
    "cvectorization_ops_x86_interleave_whole_\(upper ? "upper" : "lower")_table_\(element.cSuffix)"
}

func x86Avx3WholeIndices(upper: Bool) -> [Int] {
    (0..<4).flatMap { [$0 + (upper ? 4 : 0), $0 + (upper ? 12 : 8)] }
}

func x86Avx3InterleavedWholeHelpers(upper: Bool, for element: Element) -> String? {
    guard element.width == 64, element.bits == 64 else { return nil }
    let bytes = x86Avx3WholeIndices(upper: upper).flatMap { [$0] + Array(repeating: 0, count: 7) }
    return neonTable(
        named: x86Avx3WholeTableName(upper: upper, for: element),
        bytes,
        alignment: 64,
        isHidden: true
    )
}

func x86Avx3InterleavedWhole(upper: Bool, for element: Element) -> String? {
    guard element.width == 64, element.bits == 64 else { return nil }
    let isFloat = element.category == .float
    let type = x86Vector(isFloat ? "f64" : "i64")
    let permuted = x86Builtin(
        "vpermi2var\(isFloat ? "pd" : "q")512",
        [
            (value: "a", type: type), (value: "indices", type: x86Vector("i64")),
            (value: "b", type: type),
        ],
        returning: element.cVector
    )
    let native = """
        \(x86Vector("i64")) indices;
        __builtin_memcpy(&indices, \(x86Avx3WholeTableName(upper: upper, for: element))(), sizeof indices);
        \(vectorResult(permuted, for: element))
        """
    return x86ConstantOperandDispatch(
        ["a", "b"],
        constant: native,
        otherwise: shuffled(
            "a",
            "b",
            wholeInterleavedLanes(upper: upper, for: element),
            for: element
        ),
        for: element
    )
}

func x86Avx2InterleavedWhole(upper: Bool, for element: Element) -> String? {
    guard element.width == 32 else { return nil }
    let single = shuffled(
        "a",
        "b",
        wholeInterleavedLanes(upper: upper, for: element),
        for: element
    )
    let shuffle = { (upper: Bool) in
        let indices = unpackIndices(lanes: element.blockLaneCount, upper: upper, blocks: 2)
        return "__builtin_shufflevector(a, b, \(laneIndices(indices)))"
    }
    let concat: String
    if element.bits == 64 {
        let half = element.laneCount / 2
        let first = upper ? half : 0
        let second = element.laneCount + first
        concat =
            "__builtin_shufflevector(interleavedLower, interleavedUpper, \(laneIndices(first..<first + half, second..<second + half)))"
    } else {
        concat = x86Avx2Concat(
            upper ? .upperUpper : .lowerLower,
            hi: "interleavedUpper",
            lo: "interleavedLower",
            for: element
        )
    }
    let blocks = """
        const \(element.cVector) interleavedUpper = \(shuffle(true));
        const \(element.cVector) interleavedLower = \(shuffle(false));
        \(vectorResult("(\(element.cVector))\(concat)", for: element))
        """
    return x86ConstantOperandDispatch(
        ["a", "b"],
        constant: blocks,
        otherwise: single,
        for: element
    )
}

func x86Avx2ReplacingLane(for element: Element) -> String? {
    guard element.width == 32 else { return nil }
    let unsigned = unsignedElement(of: element)
    let positions = iota(as: unsigned.cVector, lanes: element.laneCount)
    let target = splat("(\(unsigned.cType))index", as: unsigned.cVector, lanes: element.laneCount)
    let selected = x86Selecting(
        "(positions == target)",
        repeatingVector("value", of: element),
        "a",
        for: element
    )
    return """
        const \(unsigned.cVector) positions = \(positions);
        const \(unsigned.cVector) target = \(target);
        \(vectorResult(selected, for: element))
        """
}

func fixedPermutationOp(_ permutation: FixedPermutation) -> Op {
    let isBinary = permutation.parameters.filter { $0 == .vector }.count > 1
    let operands = isBinary ? (permutation.lowerFirst ? ("b", "a") : ("a", "b")) : ("a", "a")
    let portable = { (element: Element) in
        if case .reversal(let lanes)? = permutation.laneCapability, element.laneCount < lanes {
            return "__builtin_trap();"
        }
        return shuffled(operands.0, operands.1, permutation.indices(element), for: element)
    }
    var targets = permutation.targets
    if let sse2 = permutation.sse2Only {
        targets.sse2 = sse2
        targets.ssse3 = { element in sse2(element) == nil ? nil : portable(element) }
    }
    return Op(
        permutation.swiftName,
        permutation.highwayName,
        permutation.parameters,
        .vector,
        permutation.applies,
        section: permutation.section,
        laneCapability: permutation.laneCapability,
        targets: targets,
        helpers: permutation.helpers,
        portable: portable
    )
}

func interleavedLanes(parity: Int, for element: Element) -> [Int] {
    let lanes = element.laneCount
    return (0..<lanes / 2).flatMap { [2 * $0 + parity, lanes + 2 * $0 + parity] }
}

func wholeInterleavedLanes(upper: Bool, for element: Element) -> [Int] {
    let lanes = element.laneCount
    let start = upper ? lanes / 2 : 0
    return (start..<start + lanes / 2).flatMap { [$0, lanes + $0] }
}

func concatenatedLanes(
    lowFromUpper: Bool,
    highFromUpper: Bool,
    for element: Element
) -> [Int] {
    let lanes = element.laneCount
    let half = lanes / 2
    let low = lowFromUpper ? half : 0
    let high = lanes + (highFromUpper ? half : 0)
    return Array(low..<low + half) + Array(high..<high + half)
}

func concatenatedParityLanes(parity: Int, for element: Element) -> [Int] {
    let lanes = element.laneCount
    return (0..<lanes / 2).map { 2 * $0 + parity } + (0..<lanes / 2).map { lanes + 2 * $0 + parity }
}

func reversedGroups(_ size: Int, for element: Element) -> [Int] {
    (0..<element.laneCount).map { $0 ^ (size - 1) }
}

func byteSwapped(_ source: String, for element: Element) -> String {
    let bytes = byteElement(of: element)
    let width = element.bits / 8
    let indices = (0..<bytes.laneCount).map { $0 / width * width + width - 1 - $0 % width }
    let operand = "(\(bytes.cVector))\(source)"
    let shuffle = "__builtin_shufflevector(\(operand), \(operand), \(laneIndices(indices)))"
    return "(\(element.cVector))\(shuffle)"
}

func portableBitReversed(for element: Element) -> String {
    guard element.bits > 8 else {
        return vectorResult("__builtin_elementwise_bitreverse(a)", for: element)
    }
    let bytes = byteElement(of: element).cVector
    return """
        const \(element.cVector) reversed = (\(element.cVector))__builtin_elementwise_bitreverse((\(bytes))a);
        \(vectorResult(byteSwapped("reversed", for: element), for: element))
        """
}

func neonConcatenatedHalves(upper: Bool, for element: Element) -> String {
    let halves = unsignedElement(bits: 64).at(width: element.width)
    let sources = ["b", "a"].map { "(\(halves.cVector))\($0)" }
    let part = upper ? 1 : 0
    let shuffle = "__builtin_shufflevector(\(sources[0]), \(sources[1]), \(part), \(2 + part))"
    return """
        \(vectorTypedef(of: halves))
        \(vectorResult("(\(element.cVector))\(shuffle)", for: element))
        """
}

func wordSelectedOddEven(for element: Element) -> String? {
    guard element.bits <= 16 else { return nil }
    let word = unsignedElement(bits: 2 * element.bits).at(width: element.width)
    let mask = splat("\((1 << element.bits) - 1)", as: word.cVector, lanes: word.laneCount)
    return """
        \(vectorTypedef(of: word))
        const \(word.cVector) mask = \(mask);
        \(vectorResult("((\(word.cVector))b & mask) | ((\(word.cVector))a & ~mask)", for: element))
        """
}

func laneStorage(for element: Element) -> String {
    "union { \(element.cVector) vector; \(element.cType) lanes[\(element.laneCount)]; } storage = {a};"
}

func x86RepeatingReductionTargets(_ reduction: Reduction) -> TargetBodies<Element> {
    TargetBodies(
        avx3: { x86Reduction(reduction, level: .avx3, repeating: true, for: $0) },
        avx2: { x86Reduction(reduction, level: .avx2, repeating: true, for: $0) },
        sse4: { x86Reduction(reduction, level: .sse4, repeating: true, for: $0) },
        ssse3: { x86Reduction(reduction, level: .ssse3, repeating: true, for: $0) },
        sse2: { x86Reduction(reduction, level: .sse2, repeating: true, for: $0) }
    )
}

func repeatedReduction(_ reduction: String, for element: Element) -> String {
    let reduced = "\(cFunctionName(reduction, element))(\(rawName("a")))"
    return "return \(cFunctionName("repeating", element))(\(reduced));"
}

func pairedBlockLanes(parity: Int, for element: Element) -> String {
    let blockLanes = element.blockLaneCount
    let pattern = [0, blockLanes].flatMap { stride(from: $0 + parity, to: $0 + blockLanes, by: 2) }
    let indices = blockwiseIndices(pattern, for: element)
    return "__builtin_shufflevector(a, b, \(laneIndices(indices)))"
}

func x86HorizontalPairwise(subtracting: Bool, for element: Element) -> String? {
    let operation = subtracting ? "sub" : "add"
    let bits = x86Bits(element.width)
    let horizontal: String
    switch (element.category, element.bits) {
    case (_, 16):
        horizontal = x86Builtin(
            "ph\(operation)w\(bits)",
            ["a", "b"],
            as: "i16",
            returning: element.cVector
        )
    case (.float, 32):
        let name = "h\(operation)ps\(x86UnsuffixedBits(element.width))"
        horizontal = x86Builtin(name, ["a", "b"], as: "f32", returning: element.cVector)
    case (.float, 64):
        let name = "h\(operation)pd\(x86UnsuffixedBits(element.width))"
        horizontal = x86Builtin(name, ["a", "b"], as: "f64", returning: element.cVector)
    case (_, 32):
        horizontal = x86Builtin(
            "ph\(operation)d\(bits)",
            ["a", "b"],
            as: "i32",
            returning: element.cVector
        )
    default:
        return nil
    }
    guard subtracting else { return vectorResult(horizontal, for: element) }
    guard element.category != .float else { return vectorResult("-\(horizontal)", for: element) }
    let unsigned = element.cUnsignedVector
    return vectorResult("(\(element.cVector))(-(\(unsigned))\(horizontal))", for: element)
}

func x86PairwiseBlocks(subtracting: Bool, level: X86Level, for element: Element) -> String {
    if level >= .ssse3, element.width <= 32, !element.isHalfPrecision,
        let horizontal = x86HorizontalPairwise(subtracting: subtracting, for: element)
    {
        return horizontal
    }
    let name = subtracting ? "pairwiseSubtracting" : "pairwiseAdding"
    let arguments = "\(rawName("a")), \(rawName("b"))"
    let pairwise =
        "const \(element.cVector) pairwise = (\(element.cVector))\(cFunctionName(name, element))(\(arguments));"
    let blockLanes = element.blockLaneCount
    let shuffled = { (indices: [Int]) in
        let lanes = laneIndices(blockwiseIndices(indices, for: element))
        return vectorResult("__builtin_shufflevector(pairwise, pairwise, \(lanes))", for: element)
    }
    switch element.bits {
    case 64:
        return "\(pairwise)\n\(vectorResult("pairwise", for: element))"
    case 32:
        return "\(pairwise)\n\(shuffled([0, 2, 1, 3]))"
    default:
        let evens = Array(stride(from: 0, to: blockLanes, by: 2))
        let odds = Array(stride(from: 1, to: blockLanes, by: 2))
        guard level == .sse2 else { return "\(pairwise)\n\(shuffled(evens + odds))" }
        let word = unsignedElement(bits: 2 * element.bits)
        let typedef = vectorTypedef("wide_vector", of: word, lanes: element.laneCount / 2)
        let words = "const wide_vector words = (wide_vector)pairwise;"
        if element.bits == 8 {
            let mask = splat("0x00FF", as: "wide_vector", lanes: element.laneCount / 2)
            let packed = x86Builtin(
                "packuswb\(x86Bits(element.width))",
                [
                    (value: "(words & \(mask))", type: x86Vector("i16")),
                    (value: "(words >> 8)", type: x86Vector("i16")),
                ],
                returning: element.cVector
            )
            return "\(typedef)\n\(pairwise)\n\(words)\n\(vectorResult(packed, for: element))"
        }
        let signed = x86Vector("i32")
        let packed = x86Builtin(
            "packssdw\(x86Bits(element.width))",
            [
                (value: "(wide_vector)(((\(signed))(words << 16)) >> 16)", type: signed),
                (value: "(wide_vector)(((\(signed))words) >> 16)", type: signed),
            ],
            returning: element.cVector
        )
        return "\(typedef)\n\(pairwise)\n\(words)\n\(vectorResult(packed, for: element))"
    }
}

func emulatedPairwiseSubtractingBlocks(for element: Element) -> String? {
    guard element.category == .float else { return nil }
    let count = element.laneCount
    let evens = (0..<count).map { $0 % 2 == 0 ? "a[\($0)]" : "b[\($0 - 1)]" }
    let odds = (0..<count).map { $0 % 2 == 0 ? "a[\($0 + 1)]" : "b[\($0)]" }
    let order = element.bits == 32 ? [0, 2, 1, 3] : Array(0..<count)
    return """
        const \(element.cType) evens[\(count)] = {\(evens.joined(separator: ", "))};
        const \(element.cType) odds[\(count)] = {\(odds.joined(separator: ", "))};
        \(element.cType) lanes[\(count)];
        for (size_t i = 0; i < \(count); ++i) {
          lanes[i] = odds[i] - evens[i];
        }
        \(vectorResult(compoundLiteral(element.cVector, order.map { "lanes[\($0)]" }), for: element))
        """
}

func emulatedPairwiseBlocks(subtracting: Bool, for element: Element) -> String? {
    guard element.bits == 64 else { return nil }
    let signed = element.category == .signedInteger
    func pair(_ operand: String) -> String {
        let lanes = (subtracting ? [1, 0] : [0, 1]).map {
            signed ? "(\(element.cUnsignedLane))\(operand)[\($0)]" : "\(operand)[\($0)]"
        }
        return "\(lanes[0]) \(subtracting ? "-" : "+") \(lanes[1])"
    }
    let pairs = compoundLiteral(
        signed ? element.cUnsignedVector : element.cVector,
        [pair("a"), pair("b")]
    )
    return vectorResult(signed ? "(\(element.cVector))\(pairs)" : pairs, for: element)
}

func pairwiseBlocksTargets(subtracting: Bool) -> TargetBodies<Element> {
    TargetBodies(
        sve2_128Splat: { sveSplatPairwise(subtracting: subtracting, for: $0) },
        avx3: { x86PairwiseBlocks(subtracting: subtracting, level: .avx3, for: $0) },
        avx2: { x86PairwiseBlocks(subtracting: subtracting, level: .avx2, for: $0) },
        sse4: { x86PairwiseBlocks(subtracting: subtracting, level: .sse4, for: $0) },
        ssse3: { x86PairwiseBlocks(subtracting: subtracting, level: .ssse3, for: $0) },
        sse2: { x86PairwiseBlocks(subtracting: subtracting, level: .sse2, for: $0) },
        emu128: { element in
            (subtracting ? emulatedPairwiseSubtractingBlocks(for: element) : nil)
                ?? emulatedPairwiseBlocks(subtracting: subtracting, for: element)
        }
    )
}

func portablePairwiseBlocks(subtracting: Bool, for element: Element) -> String {
    let (evens, odds) = (
        pairedBlockLanes(parity: 0, for: element), pairedBlockLanes(parity: 1, for: element)
    )
    let (first, second) = subtracting ? ("odds", "evens") : ("evens", "odds")
    let declarations = [("evens", evens), ("odds", odds)].sorted { $0.0 == first && $1.0 == second }
    return """
        \(declarations.map { "const \(element.cVector) \($0) = \($1);" }.joined(separator: "\n"))
        \(vectorResult(arithmetic(subtracting ? "-" : "+", first, second, for: element), for: element))
        """
}

func tupleCreation(
    _ count: Int,
    for element: Element,
    member: (String) -> String = rawName
) -> String {
    let members = (0..<count).map { member(["a", "b", "c", "d"][$0]) }
    return "return (\(element.cTuple(count))){\(members.joined(separator: ", "))};"
}

func tupleSwitch(_ count: Int, result: (Int) -> String) -> String {
    let cases = (0..<count).map { member in
        "\(member == count - 1 ? "default" : "case \(member)"): return \(result(member));"
    }
    return "switch (index) {\n\(cases.joined(separator: "\n"))\n}"
}

func concatenatedBlocks(_ blocks: [String], lanes: Int) -> String {
    guard blocks.count > 1 else { return blocks[0] }
    let pairs = stride(from: 0, to: blocks.count, by: 2).map {
        "__builtin_shufflevector(\(blocks[$0]), \(blocks[$0 + 1]), \(laneIndices(0..<2 * lanes)))"
    }
    return concatenatedBlocks(pairs, lanes: 2 * lanes)
}

func tupleMember(_ count: Int, for element: Element) -> String {
    guard element.width > 16 else { return tupleSwitch(count) { "tuple.v\($0)" } }
    let blockLanes = element.category == .float ? element.blockLaneCount : 2
    let names = (0..<element.width / 16).map { "block\($0)" }
    let first = laneIndices(0..<blockLanes)
    let cases = (0..<count).map { member in
        let assignments = names.enumerated().map { block, name in
            let lanes = laneIndices(block * blockLanes..<(block + 1) * blockLanes)
            return
                "\(name) = __builtin_shufflevector(tuple.v\(member), tuple.v\(member), \(lanes));"
        }
        let label = member == count - 1 ? "default" : "case \(member)"
        return "\(label): \(assignments.joined(separator: " ")) break;"
    }
    return """
        __typeof__(__builtin_shufflevector(tuple.v0, tuple.v0, \(first))) \(names.joined(separator: ", "));
        switch (index) {
        \(cases.joined(separator: "\n"))
        }
        return \(concatenatedBlocks(names, lanes: blockLanes));
        """
}

func tupleReplacement(_ count: Int, for element: Element) -> String {
    guard element.width == 32, count == 2 else {
        return tupleSwitch(count) { replaced in
            let members = (0..<count).map { $0 == replaced ? rawName("a") : "tuple.v\($0)" }
            return "(\(element.cTuple(count))){\(members.joined(separator: ", "))}"
        }
    }
    let blockLanes = element.category == .float ? element.blockLaneCount : 2
    let blocks = element.width / 16
    let type =
        "__typeof__(__builtin_shufflevector(tuple.v0, tuple.v0, \(laneIndices(0..<blockLanes))))"
    let declarations = (0..<count).reversed().flatMap { member in
        (0..<blocks).reversed().map { block -> String in
            let lanes = laneIndices(block * blockLanes..<(block + 1) * blockLanes)
            let kept = "__builtin_shufflevector(tuple.v\(member), tuple.v\(member), \(lanes))"
            let replaced = "__builtin_shufflevector(\(rawName("a")), \(rawName("a")), \(lanes))"
            let selected = member == 0 ? "\(replaced) : \(kept)" : "\(kept) : \(replaced)"
            return "const \(type) member\(member)_\(block) = index == 0 ? \(selected);"
        }
    }
    let members = (0..<count).map { member in
        concatenatedBlocks((0..<blocks).map { "member\(member)_\($0)" }, lanes: blockLanes)
    }
    return """
        \(declarations.joined(separator: "\n"))
        return (\(element.cTuple(count))){\(members.joined(separator: ", "))};
        """
}

let fixedPermutations: [FixedPermutation] = [
    FixedPermutation(
        swiftName: "interleavingLower",
        highwayName: "InterleaveLower",
        parameters: [.tag, .vector, .vector],
        applies: .all,
        section: .interleave,
        targets: TargetBodies(sve2_128: { element in sveShuffled("zip1", "a", "b", for: element) })
    ) { element in
        unpackIndices(lanes: element.blockLaneCount, upper: false, blocks: element.width / 16)
    },
    FixedPermutation(
        swiftName: "interleavingUpper",
        highwayName: "InterleaveUpper",
        parameters: [.tag, .vector, .vector],
        applies: .all,
        section: .interleave,
        targets: TargetBodies(sve2_128: { element in sveShuffled("zip2", "a", "b", for: element) })
    ) { element in
        unpackIndices(lanes: element.blockLaneCount, upper: true, blocks: element.width / 16)
    },
    FixedPermutation(
