func tupleOps(count: Int) -> [Op] {
    let vectors = Array(repeating: Parameter.vector, count: count)
    return [
        Op(
            "create\(count)",
            "Create\(count)",
            [.tag] + vectors,
            .tuple(count),
            .all,
            section: .tuples,
            targets: TargetBodies(sve2_128: { element in
                tupleCreation(count, for: element) { sveSplatMember($0, for: element) }
            })
        ) { element in
            tupleCreation(count, for: element)
        },
        Op(
            "get\(count)",
            "Get\(count)",
            [.tuple(count), .tupleIndex],
            .vector,
            .all,
            section: .tuples
        ) { element in
            tupleMember(count, for: element)
        },
        Op(
            "set\(count)",
            "Set\(count)",
            [.tuple(count), .tupleIndex, .vector],
            .tuple(count),
            .all,
            section: .tuples,
            vectorLabels: ["to"]
        ) { element in
            tupleReplacement(count, for: element)
        },
    ]
}

enum ImmediateShift {
    case left
    case right
    case rounding
    case rotateLeft
    case rotateRight

    var name: String {
        switch self {
        case .left: return "ShiftLeft"
        case .right: return "ShiftRight"
        case .rounding: return "RoundingShiftRight"
        case .rotateLeft: return "RotateLeft"
        case .rotateRight: return "RotateRight"
        }
    }
}

let galoisIdentity: UInt64 = 0x0102_0408_1020_4080

func galoisLeftMatrix(_ bits: Int) -> UInt64 {
    (galoisIdentity >> UInt64(bits)) & (0x0101_0101_0101_0101 &* (0xFF >> UInt64(bits)))
}

func galoisRightMatrix(_ bits: Int, arithmetic: Bool) -> UInt64 {
    let shifted =
        (galoisIdentity << UInt64(bits))
        & (0x0101_0101_0101_0101 &* ((0xFF << UInt64(bits)) & 0xFF))
    guard arithmetic, bits != 0 else { return shifted }
    return shifted | (0x8080_8080_8080_8080 >> UInt64(64 - 8 * bits))
}

func galoisRotateMatrix(_ bits: Int) -> UInt64 {
    galoisRightMatrix(bits, arithmetic: false) | galoisLeftMatrix((-bits) & 7)
}

func x86GaloisAffine(_ operand: String, matrix: UInt64, for element: Element) -> String {
    let constant = "(long long)0x\(String(matrix, radix: 16))ull"
    let matrices = compoundLiteral(
        x86Vector("i64"),
        Array(repeating: constant, count: element.width / 8)
    )
    let operands = [
        (value: operand, type: x86Vector("i8")),
        (value: matrices, type: x86Vector("i8")),
        (value: "0", type: "char"),
    ]
    return x86Builtin("vgf2p8affineqb_v\(element.width)qi", operands, returning: element.cVector)
}

func x86ByteShiftedLeft(
    _ operand: String,
    by bits: Int,
    level: X86Level,
    for element: Element
) -> String {
    switch (bits, level) {
    case (0, _):
        return operand
    case (1, _):
        let bytes = unsignedBits(operand, of: element)
        return "(\(element.cVector))(\(bytes) + \(bytes))"
    case (_, .avx3dl):
        return x86GaloisAffine(operand, matrix: galoisLeftMatrix(bits), for: element)
    default:
        let unsigned = element.cUnsignedVector
        let shifted = x86ImmediateShift(
            "psll",
            operand,
            by: String(bits),
            laneBits: 16,
            width: element.width,
            returning: unsigned
        )
        let mask = splat("\((0xFF << bits) & 0xFF)", as: unsigned, lanes: element.laneCount)
        return "(\(element.cVector))(\(shifted) & \(mask))"
    }
}

func x86ByteShiftedRight(
    _ operand: String,
    by bits: Int,
    level: X86Level,
    for element: Element
) -> String {
    let arithmetic = element.category == .signedInteger
    guard level != .avx3dl else {
        let matrix = galoisRightMatrix(bits, arithmetic: arithmetic)
        return bits == 0 ? operand : x86GaloisAffine(operand, matrix: matrix, for: element)
    }
    let unsigned = element.cUnsignedVector
    let shifted = x86ImmediateShift(
        "psrl",
        unsignedBits(operand, of: element),
        by: String(bits),
        laneBits: 16,
        width: element.width,
        returning: unsigned
    )
    let mask = splat("\(0xFF >> bits)", as: unsigned, lanes: element.laneCount)
    let masked = "(\(shifted) & \(mask))"
    guard arithmetic else { return masked }
    let sign = splat("\(0x80 >> bits)", as: unsigned, lanes: element.laneCount)
    return "(\(element.cVector))((\(masked) ^ \(sign)) - \(sign))"
}

func x86ByteRotatedRight(
    _ operand: String,
    by bits: Int,
    level: X86Level,
    for element: Element
) -> String {
    guard bits != 0 else { return operand }
    guard level != .avx3dl else {
        return x86GaloisAffine(operand, matrix: galoisRotateMatrix(bits), for: element)
    }
    let unsigned = unsignedElement(of: element).at(width: element.width)
    let bytes = unsignedBits(operand, of: element)
    let right = x86ByteShiftedRight(bytes, by: bits, level: level, for: unsigned)
    let left = x86ByteShiftedLeft(bytes, by: min(7, 8 - bits), level: level, for: unsigned)
    return "(\(element.cVector))(\(right) | \(left))"
}

func x86ShiftPath(_ shift: ImmediateShift, level: X86Level, for element: Element) -> String? {
    var cases: [(amount: Int, body: String)] = []
    func add(_ amounts: [Int], _ expression: (Int) -> String) {
        cases += amounts.map { (amount: $0, body: vectorResult(expression($0), for: element)) }
    }
    let galois = level == .avx3dl
    switch shift {
    case .left where element.bits == 8:
        add(galois ? Array(0..<8) : [1]) {
            x86ByteShiftedLeft("a", by: $0, level: level, for: element)
        }
    case .right where element.bits == 8 && galois:
        add(Array(0..<8)) { x86ByteShiftedRight("a", by: $0, level: level, for: element) }
    case .rotateRight where element.bits == 8:
        add(galois ? Array(1..<8) : [7]) {
            x86ByteRotatedRight("a", by: $0, level: level, for: element)
        }
    case .rotateLeft where element.bits == 8:
        add(galois ? Array(1..<8) : [1]) {
            x86ByteRotatedRight("a", by: 8 - $0, level: level, for: element)
        }
    case .rounding:
        let signed = element.category == .signedInteger
        add(signed && element.bits <= 16 || galois && element.bits == 8 ? [0] : []) { _ in "a" }
        guard galois && element.bits == 8 else { break }
        let unscaled = compoundLiteral(element.cVector, ["0"])
        for bits in 1..<8 {
            let shifted = x86ByteShiftedRight("a", by: bits - 1, level: level, for: element)
            let average = operationCall("roundedAverage", ["scaled", "unscaled"], for: element)
            cases.append(
                (
                    amount: bits,
                    body: """
                    {
                      const \(element.cVector) scaled = \(shifted);
                      const \(element.cVector) unscaled = \(unscaled);
                      \(vectorResult(average, for: element))
                    }
                    """
                )
            )
        }
    default:
        break
    }
    return cases.isEmpty ? nil : constantSwitch(on: "bits", cases)
}

func sveRoundingPath(for element: Element) -> String {
    let cases = (0..<element.bits).map { bits in
        let rounded = sveBuiltin(
            "rshr_n",
            [sveAllLanes(of: element), sveOperand("a", for: element, splat: true), String(bits)],
            for: element,
            predication: "x"
        )
        let body = bits == 0 ? "a" : sveResult(rounded, for: element)
        return (amount: bits, body: vectorResult(body, for: element))
    }
    return constantSwitch(on: "bits", cases)
}

func shiftPaths(_ shift: ImmediateShift) -> TargetBodies<Element> {
    TargetBodies(
        sve2_128: shift == .rounding ? { sveRoundingPath(for: $0) } : nil,
        avx3dl: { x86ShiftPath(shift, level: .avx3dl, for: $0) },
        avx3: { x86ShiftPath(shift, level: .avx3, for: $0) },
        avx2: { x86ShiftPath(shift, level: .avx2, for: $0) },
        sse4: { x86ShiftPath(shift, level: .sse4, for: $0) },
        ssse3: { x86ShiftPath(shift, level: .ssse3, for: $0) },
        sse2: { x86ShiftPath(shift, level: .sse2, for: $0) }
    )
}

func shiftTemplate(_ shift: ImmediateShift) -> ImmediateTemplate {
    ImmediateTemplate(
        name: shift.name,
        range: { 0...$0.bits - 1 },
        fallback: nil,
        paths: shiftPaths(shift)
    )
}

enum BlockShift {
    case left
    case right
}

func constantSwitch(on amount: String, _ cases: [(amount: Int, body: String)]) -> String {
    let lines = cases.map { "case \($0.amount): \($0.body)" }
    return """
        if (__builtin_constant_p(\(amount))) {
          switch (\(amount)) {
        \(indented(indented(lines.joined(separator: "\n"))))
          }
        }
        """
}

func blockByteCount(_ amount: String, unit: Int) -> String {
    unit == 1 ? amount : "(\(amount) * \(unit))"
}

let blockByteVector = "cvectorization_ops_vector_u8"

func blockUnit(bytewise: Bool, for element: Element) -> Int {
    bytewise ? 1 : element.bits / 8
}

func blockIota(as type: String, width: Int) -> String {
    compoundLiteral(type, (0..<width).map { String($0 % 16) })
}

func portableBlockShiftRuntime(
    _ direction: BlockShift,
    byteCount: String,
    for element: Element
) -> String {
    let (placed, copied) =
        switch direction {
        case .left: ("scratch + 16", "scratch + 16 - \(byteCount)")
        case .right: ("scratch", "scratch + \(byteCount)")
        }
    return """
        const uint8_t* const source = (const uint8_t*)&a;
        \(element.cVector) result;
        #pragma clang loop unroll(full)
        for (size_t block = 0; block < \(element.width / 16); ++block) {
          uint8_t scratch[32] __attribute__((aligned(16))) = {0};
          __builtin_memcpy(\(placed), source + block * 16, 16);
          __builtin_memcpy((uint8_t*)&result + block * 16, \(copied), 16);
        }
        \(vectorResult("result", for: element))
        """
}

func blockShiftIndices(_ direction: BlockShift, bytes: Int, width: Int) -> [Int] {
    (0..<width).map { index in direction == .left ? width - bytes + index : bytes + index }
}

func blockCombineIndices(bytes: Int, width: Int) -> [Int] {
    (0..<width).map { index in
        let block = index / 16 * 16
        let source = index % 16 + bytes
        return source < 16 ? block + source : width + block + source - 16
    }
}

func portableBlockShift(
    _ direction: BlockShift,
    amount: String,
    unit: Int,
    for element: Element
) -> String {
    let zero = compoundLiteral(blockByteVector, ["0"])
    let operand = "(\(blockByteVector))a"
    let operands = direction == .left ? [zero, operand] : [operand, zero]
    let cases = (0...16 / unit).map { count in
        let indices = blockShiftIndices(direction, bytes: count * unit, width: element.width)
        let shuffle =
            "__builtin_shufflevector(\(operands[0]), \(operands[1]), \(laneIndices(indices)))"
        return (amount: count, body: vectorResult("(\(element.cVector))\(shuffle)", for: element))
    }
    let byteCount = blockByteCount(amount, unit: unit)
    return """
        \(constantSwitch(on: amount, cases))
        \(portableBlockShiftRuntime(direction, byteCount: byteCount, for: element))
        """
}

func portableBlockCombine(amount: String, unit: Int, for element: Element) -> String {
    let cases = combineCases(unit: unit) { bytes in
        let indices = blockCombineIndices(bytes: bytes, width: element.width)
        let shuffle =
            "__builtin_shufflevector((\(blockByteVector))b, (\(blockByteVector))a, \(laneIndices(indices)))"
        return vectorResult("(\(element.cVector))\(shuffle)", for: element)
    }
    let byteCount = blockByteCount(amount, unit: unit)
    return """
        \(constantSwitch(on: amount, cases))
        \(portableBlockCombineRuntime(byteCount: byteCount, for: element))
        """
}

func neonExtract(_ low: String, _ high: String, from bytes: Int, for element: Element) -> String {
    let vector = neonVector("i8")
    return
        "(\(element.cVector))__builtin_neon_vextq_v((\(vector))\(low), (\(vector))\(high), \(bytes), 48)"
}

func neonBlockShift(
    _ direction: BlockShift,
    amount: String,
    unit: Int,
    for element: Element
) -> String {
    let zero = compoundLiteral(element.cVector, ["0"])
    let cases = (0...16 / unit).map { count in
        let bytes = count * unit
        let shifted =
            switch (bytes, direction) {
            case (0, _): "a"
            case (16, _): zero
            case (_, .left): neonExtract(zero, "a", from: 16 - bytes, for: element)
            case (_, .right): neonExtract("a", zero, from: bytes, for: element)
            }
        return (amount: count, body: vectorResult(shifted, for: element))
    }
    let offset = direction == .left ? "16 - " : "16 + "
    return """
        \(constantSwitch(on: amount, cases))
        \(blockByteVector) indices;
        __builtin_memcpy(&indices, \(neonSlideTableName)() + \(offset)\(blockByteCount(amount, unit: unit)), sizeof indices);
        \(vectorResult(neonTableLookup("a", "indices", for: element), for: element))
        """
}

func sveBlockShiftView(unit: Int, for element: Element) -> Element {
    unit == 1 ? unsignedElement(bits: 8) : element
}

func sveBlockOperand(_ name: String, unit: Int, for element: Element) -> String {
    let view = sveBlockShiftView(unit: unit, for: element)
    return sveReinterpreted(sveOperand(name, for: element, splat: true), from: element, to: view)
}

func sveBlockResult(_ call: String, unit: Int, for element: Element) -> String {
    let view = sveBlockShiftView(unit: unit, for: element)
    return vectorResult(
        sveResult(sveReinterpreted(call, from: view, to: element), for: element),
        for: element
    )
}

func sveBlockShift(
    _ direction: BlockShift,
    amount: String,
    unit: Int,
    for element: Element
) -> String {
    let view = sveBlockShiftView(unit: unit, for: element)
    let zero = sveBuiltin("dup_n", ["0"], for: view)
    let operand = sveBlockOperand("a", unit: unit, for: element)
    switch direction {
    case .left:
        let active = sveActiveLanes(amount, for: view)
        let slid = sveBuiltin("splice", [active, zero, operand], for: view)
        return sveBlockResult(slid, unit: unit, for: element)
    case .right:
        let limit = 16 / (view.bits / 8)
        let cases = (0...limit).map { count in
            let shifted =
                switch count {
                case 0, limit: operand
                default: sveBuiltin("ext", [operand, zero, String(count)], for: view)
                }
            return (amount: count, body: sveBlockResult(shifted, unit: unit, for: element))
        }
        let active = sveActiveLanes("\(amount) & \(limit - 1)", for: view)
        let inactive = "__builtin_sve_svnot_b_z(\(sveAllLanes(of: view)), \(active))"
        let slid = sveBuiltin("splice", [inactive, operand, zero], for: view)
        return """
            \(constantSwitch(on: amount, cases))
            \(sveBlockResult(slid, unit: unit, for: element))
            """
    }
}

func x86BlockByteShift(
    _ direction: BlockShift,
    _ operand: String,
    by bytes: Int,
    width: Int
) -> String {
    let name = direction == .left ? "pslldqi" : "psrldqi"
    return "__builtin_ia32_\(name)\(x86Bits(width))_byteshift(\(operand), \(bytes))"
}

func x86BlockShiftIndices(_ direction: BlockShift, byteCount: String, width: Int) -> String {
    let unsigned = blockByteVector
    let iota = blockIota(as: unsigned, width: width)
    let count = splat("(uint8_t)\(byteCount)", as: unsigned, lanes: width)
    switch direction {
    case .left:
        return "const \(unsigned) indices = \(iota) - \(count);"
    case .right:
        let bytes = x86Vector("i8")
        let limit = splat("15", as: bytes, lanes: width)
        return """
            const \(bytes) offsets = (\(bytes))(\(iota) + \(count));
            const \(bytes) indices = offsets | (offsets > \(limit));
            """
    }
}

func x86BlockShift(
    _ direction: BlockShift,
    amount: String,
    unit: Int,
    level: X86Level,
    for element: Element
) -> String {
    let words = x86Vector("i64")
    let cases = (0...16 / unit).map { count in
        let shifted = x86BlockByteShift(
            direction,
            "(\(words))a",
            by: count * unit,
            width: element.width
        )
        return (amount: count, body: vectorResult("(\(element.cVector))\(shifted)", for: element))
    }
    let byteCount = blockByteCount(amount, unit: unit)
    let runtime =
        level >= .ssse3
        ? """
        \(x86BlockShiftIndices(direction, byteCount: byteCount, width: element.width))
        \(vectorResult(x86TableLookup("a", "indices", for: element), for: element))
        """
        : portableBlockShiftRuntime(direction, byteCount: byteCount, for: element)
    return "\(constantSwitch(on: amount, cases))\n\(runtime)"
}

func blockShiftTargets(
    _ direction: BlockShift,
    amount: String,
    bytewise: Bool
) -> TargetBodies<Element> {
    func unit(_ element: Element) -> Int { blockUnit(bytewise: bytewise, for: element) }
    return TargetBodies(
        neon: { neonBlockShift(direction, amount: amount, unit: unit($0), for: $0) },
        sve2_128: { sveBlockShift(direction, amount: amount, unit: unit($0), for: $0) },
        avx3dl: {
            x86BlockShift(direction, amount: amount, unit: unit($0), level: .avx3dl, for: $0)
        },
        avx3: { x86BlockShift(direction, amount: amount, unit: unit($0), level: .avx3, for: $0) },
        avx2: { x86BlockShift(direction, amount: amount, unit: unit($0), level: .avx2, for: $0) },
        sse4: { x86BlockShift(direction, amount: amount, unit: unit($0), level: .sse4, for: $0) },
        ssse3: { x86BlockShift(direction, amount: amount, unit: unit($0), level: .ssse3, for: $0) },
        sse2: { x86BlockShift(direction, amount: amount, unit: unit($0), level: .sse2, for: $0) }
    )
}

func portableBlockCombineRuntime(byteCount: String, for element: Element) -> String {
    """
    const uint8_t* const lower = (const uint8_t*)&b;
    const uint8_t* const upper = (const uint8_t*)&a;
    \(element.cVector) result;
    #pragma clang loop unroll(full)
    for (size_t block = 0; block < \(element.width / 16); ++block) {
      uint8_t scratch[32] __attribute__((aligned(16)));
      __builtin_memcpy(scratch, lower + block * 16, 16);
      __builtin_memcpy(scratch + 16, upper + block * 16, 16);
      __builtin_memcpy((uint8_t*)&result + block * 16, scratch + \(byteCount), 16);
    }
    \(vectorResult("result", for: element))
    """
}

func combineCases(
    unit: Int,
    _ body: (Int) -> String
) -> [(amount: Int, body: String)] {
    (1..<16 / unit).map { (amount: $0, body: body($0 * unit)) }
}

func neonBlockCombine(amount: String, unit: Int, for element: Element) -> String {
    let cases = combineCases(unit: unit) { bytes in
        vectorResult(neonExtract("b", "a", from: bytes, for: element), for: element)
    }
    let count = splat(
        "(uint8_t)\(blockByteCount(amount, unit: unit))",
        as: blockByteVector,
        lanes: 16
    )
    let lookup = neonTwoTablesLookup("b", "a", "indices", for: element)
    return """
        \(constantSwitch(on: amount, cases))
        const \(blockByteVector) indices = \(iota(as: blockByteVector, lanes: 16)) + \(count);
        \(vectorResult(lookup, for: element))
        """
}

func sveBlockCombine(amount: String, unit: Int, for element: Element) -> String {
    let view = sveBlockShiftView(unit: unit, for: element)
    let low = sveBlockOperand("b", unit: unit, for: element)
    let high = sveBlockOperand("a", unit: unit, for: element)
    let cases = (1..<16 / (view.bits / 8)).map { count in
        let combined = sveBuiltin("ext", [low, high, String(count)], for: view)
        return (amount: count, body: sveBlockResult(combined, unit: unit, for: element))
    }
    let inactive =
        "__builtin_sve_svnot_b_z(\(sveAllLanes(of: view)), \(sveActiveLanes(amount, for: view)))"
    let slid = sveBuiltin("splice", [inactive, low, high], for: view)
    return """
        \(constantSwitch(on: amount, cases))
        \(sveBlockResult(slid, unit: unit, for: element))
        """
}

func x86BlockCombine(
    amount: String,
    unit: Int,
    level: X86Level,
    for element: Element
) -> String {
    let words = x86Vector("i64")
    let bytes = x86Vector("i8")
    let width = element.width
    let cases = combineCases(unit: unit) { count in
        let combined =
            level >= .ssse3
            ? "(\(element.cVector))__builtin_ia32_palignr\(x86Bits(width))((\(bytes))a, (\(bytes))b, \(count))"
            : "(\(element.cVector))(\(x86BlockByteShift(.right, "(\(words))b", by: count, width: width)) | \(x86BlockByteShift(.left, "(\(words))a", by: 16 - count, width: width)))"
        return vectorResult(combined, for: element)
    }
    let byteCount = blockByteCount(amount, unit: unit)
    let runtime: String
    if level >= .ssse3 {
        let iota = blockIota(as: blockByteVector, width: width)
        let count = splat("(uint8_t)\(byteCount)", as: blockByteVector, lanes: width)
        let limit = splat("15", as: bytes, lanes: width)
        let sixteen = splat("16", as: blockByteVector, lanes: width)
        runtime = """
            const \(blockByteVector) offsets = \(iota) + \(count);
            const \(bytes) lowIndices = (\(bytes))offsets | ((\(bytes))offsets > \(limit));
            const \(blockByteVector) highIndices = offsets - \(sixteen);
            const \(words) fromLow = (\(words))\(x86TableLookup("b", "lowIndices", for: element));
            const \(words) fromHigh = (\(words))\(x86TableLookup("a", "highIndices", for: element));
            \(vectorResult("(\(element.cVector))(fromLow | fromHigh)", for: element))
            """
    } else {
        runtime = portableBlockCombineRuntime(byteCount: byteCount, for: element)
    }
    return "\(constantSwitch(on: amount, cases))\n\(runtime)"
}

func blockCombineTargets(amount: String, bytewise: Bool) -> TargetBodies<Element> {
    func unit(_ element: Element) -> Int { blockUnit(bytewise: bytewise, for: element) }
    return TargetBodies(
        neon: { neonBlockCombine(amount: amount, unit: unit($0), for: $0) },
        sve2_128: { sveBlockCombine(amount: amount, unit: unit($0), for: $0) },
        avx3dl: { x86BlockCombine(amount: amount, unit: unit($0), level: .avx3dl, for: $0) },
        avx3: { x86BlockCombine(amount: amount, unit: unit($0), level: .avx3, for: $0) },
        avx2: { x86BlockCombine(amount: amount, unit: unit($0), level: .avx2, for: $0) },
        sse4: { x86BlockCombine(amount: amount, unit: unit($0), level: .sse4, for: $0) },
        ssse3: { x86BlockCombine(amount: amount, unit: unit($0), level: .ssse3, for: $0) },
        sse2: { x86BlockCombine(amount: amount, unit: unit($0), level: .sse2, for: $0) }
    )
}

let shiftedBytesCount = ImmediateArgument(
    name: "bytes",
    label: "by",
    upperBound: .fixed(16),
    message: "Byte count is negative or more than a block has bytes"
)

let shiftedLanesCount = ImmediateArgument(
    name: "lanes",
    label: "by",
    upperBound: .blockLanes(offset: 0),
    message: "Lane count is negative or more than a block has lanes"
)

let combinedBytesCount = ImmediateArgument(
    name: "bytes",
    label: "by",
    lowerBound: 1,
    upperBound: .fixed(15),
    message: "Byte count is not between 1 and 15"
)

let combinedLanesCount = ImmediateArgument(
    name: "lanes",
    label: "by",
    lowerBound: 1,
    upperBound: .blockLanes(offset: -1),
    message: "Lane count is not between 1 and one less than a block has lanes"
)

func blockShiftOp(
    _ swiftName: String,
    _ highwayName: String,
    _ direction: BlockShift,
    bytewise: Bool
) -> Op {
    let amount = bytewise ? shiftedBytesCount : shiftedLanesCount
    return Op(
        swiftName,
        highwayName,
        [.tag, .vector, .immediate],
        .vector,
        bytewise ? .integer : .all,
        section: .shiftWithinBlocks,
        immediates: [amount],
        targets: blockShiftTargets(direction, amount: amount.name, bytewise: bytewise)
    ) { element in
        let unit = blockUnit(bytewise: bytewise, for: element)
        return portableBlockShift(direction, amount: amount.name, unit: unit, for: element)
    }
}

func blockCombineOp(_ swiftName: String, _ highwayName: String, bytewise: Bool) -> Op {
    let amount = bytewise ? combinedBytesCount : combinedLanesCount
    return Op(
        swiftName,
        highwayName,
        [.tag, .vector, .vector, .immediate],
        .vector,
        bytewise ? .integer : .all,
        section: .shiftWithinBlocks,
        immediates: [amount],
        targets: blockCombineTargets(amount: amount.name, bytewise: bytewise)
    ) { element in
        let unit = blockUnit(bytewise: bytewise, for: element)
        return portableBlockCombine(amount: amount.name, unit: unit, for: element)
    }
}

func constantSwitch(
    on key: String,
    knowing names: [String],
    _ cases: [(amount: Int, body: String)]
) -> String {
    let lines = cases.map { "case \($0.amount): \($0.body)" }
    let known = names.map { "__builtin_constant_p(\($0))" }.joined(separator: " && ")
    return """
        if (\(known)) {
          switch (\(key)) {
        \(indented(indented(lines.joined(separator: "\n"))))
          }
        }
        """
}

func shuffleResult(
    _ first: String,
    _ second: String,
    _ indices: [Int],
    for element: Element
) -> String {
    vectorResult(
        "__builtin_shufflevector(\(first), \(second), \(laneIndices(indices)))",
        for: element
    )
}

func laneLoop(
    _ lane: String = "i",
    _ statement: String,
    for element: Element
) -> String {
    """
    \(element.cVector) result;
    #pragma clang loop unroll(full)
    for (size_t \(lane) = 0; \(lane) < \(element.laneCount); ++\(lane)) {
      \(statement)
    }
    \(vectorResult("result", for: element))
    """
}

func broadcastIndices(lane: Int, for element: Element) -> [Int] {
    let block = element.blockLaneCount
    return (0..<element.laneCount).map { $0 / block * block + lane }
}

func blockLaneBytes(_ lane: String, for element: Element) -> String {
    let size = element.bits / 8
    let pattern = (0..<16).map { String($0 % size) }
    return
        "\(splat("(uint8_t)(\(lane) * \(size))", as: blockByteVector, lanes: 16)) + \(compoundLiteral(blockByteVector, pattern))"
}

func broadcastCases(count: Int, for element: Element) -> [(amount: Int, body: String)] {
    (0..<count).map { lane in
        (
            amount: lane,
            body: shuffleResult("a", "a", broadcastIndices(lane: lane, for: element), for: element)
        )
    }
}

func neonBroadcast(for element: Element) -> String {
    let cases = broadcastCases(count: element.blockLaneCount, for: element)
    return """
        \(constantSwitch(on: "lane", cases))
        \(vectorResult(neonTableLookup("a", blockLaneBytes("lane", for: element), for: element), for: element))
        """
}

func sveBroadcast(for element: Element) -> String {
    let cases = broadcastCases(count: element.blockLaneCount, for: element)
    let index = "(\(unsignedElement(of: element).cType))lane"
    let broadcast = sveBuiltin(
        "dup_lane",
        [sveOperand("a", for: element, splat: true), index],
        for: element
    )
    return """
        \(constantSwitch(on: "lane", cases))
        \(vectorResult(sveResult(broadcast, for: element), for: element))
        """
}

func x86Broadcast(for element: Element) -> String {
    let cases = broadcastCases(count: element.blockLaneCount, for: element)
    let size = element.bits / 8
    let pattern = compoundLiteral(blockByteVector, (0..<element.width).map { String($0 % size) })
    let base = splat("(uint8_t)(lane * \(size))", as: blockByteVector, lanes: element.width)
    return """
        \(constantSwitch(on: "lane", cases))
        const \(blockByteVector) indices = \(pattern) + \(base);
        \(vectorResult(x86TableLookup("a", "indices", for: element), for: element))
        """
}

func portableBroadcast(for element: Element) -> String {
    let cases = broadcastCases(count: element.blockLaneCount, for: element)
    let block = element.blockLaneCount
    return """
        \(constantSwitch(on: "lane", cases))
        \(laneLoop("i", "result[i] = a[i / \(block) * \(block) + lane];", for: element))
        """
}

func broadcastLaneCases(for element: Element) -> [(amount: Int, body: String)] {
    (0..<element.laneCount).map { lane in
        (
            amount: lane,
            body: shuffleResult(
                "a",
                "a",
                Array(repeating: lane, count: element.laneCount),
                for: element
            )
        )
    }
}

func portableBroadcastLane(for element: Element) -> String {
    """
    \(constantSwitch(on: "lane", broadcastLaneCases(for: element)))
    \(repeatingResult("a[lane]", for: element))
    """
}

func repeatingResult(_ lane: String, for element: Element) -> String {
    vectorResult(repeatingVector(lane, of: element), for: element)
}

func broadcastBlockCases(for element: Element) -> [(amount: Int, body: String)] {
    let block = element.blockLaneCount
    return (0..<element.laneCount / block).map { index in
        let indices = (0..<element.laneCount).map { index * block + $0 % block }
        return (amount: index, body: shuffleResult("a", "a", indices, for: element))
    }
}

func portableBroadcastBlock(for element: Element) -> String {
    let block = element.blockLaneCount
    return """
        \(constantSwitch(on: "block", broadcastBlockCases(for: element)))
        \(laneLoop("i", "result[i] = a[block * \(block) + i % \(block)];", for: element))
        """
}

func slideBlocksCases(
    _ direction: SlideDirection,
    for element: Element
) -> [(amount: Int, body: String)] {
    let block = element.blockLaneCount
    return (0..<element.laneCount / block).map { blocks in
        guard blocks > 0 else { return (amount: 0, body: vectorResult("a", for: element)) }
        let shuffle = slideShuffle(direction, by: blocks * block, for: element)
        return (amount: blocks, body: vectorResult(shuffle, for: element))
    }
}

func portableSlideBlocks(_ direction: SlideDirection, for element: Element) -> String {
    let lanes = cFunctionName(direction == .up ? "slideUpLanes" : "slideDownLanes", element)
    return """
        \(constantSwitch(on: "blocks", slideBlocksCases(direction, for: element)))
        return \(lanes)(rawA, (size_t)blocks * \(element.blockLaneCount));
        """
}

func combineSlideDownCases(for element: Element) -> [(amount: Int, body: String)] {
    let lanes = element.laneCount
    return (1..<lanes).map { amount in
        (
            amount: amount,
            body: shuffleResult("b", "a", Array(amount..<lanes + amount), for: element)
        )
    }
}

func portableCombineSlideDownRuntime(for element: Element) -> String {
    let lanes = element.laneCount
    let statement = "result[i] = i + lanes < \(lanes) ? b[i + lanes] : a[i + lanes - \(lanes)];"
    return laneLoop("i", statement, for: element)
}

func portableCombineSlideDown(for element: Element) -> String {
    """
    \(constantSwitch(on: "lanes", combineSlideDownCases(for: element)))
    \(portableCombineSlideDownRuntime(for: element))
    """
}

func per4Indices(_ shuffle: [Int], for element: Element) -> [Int] {
    let lanes = element.laneCount
    guard lanes > 2 else {
        let reversed = (shuffle[0] == 1 || shuffle[1] == 0) && shuffle[0] != shuffle[1]
        let first = shuffle[0] <= 1 ? shuffle[0] : (reversed ? 1 : 0)
        let second = shuffle[1] <= 1 ? shuffle[1] : (reversed ? 0 : 1)
        return [first, second]
    }
    return (0..<lanes).map { $0 / 4 * 4 + shuffle[$0 % 4] }
}

func per4Tuples() -> [[Int]] {
    (0..<256).map { [$0 >> 6, ($0 >> 4) & 3, ($0 >> 2) & 3, $0 & 3] }
}

func per4Key(_ tuple: [Int]) -> Int {
    tuple[0] * 64 + tuple[1] * 16 + tuple[2] * 4 + tuple[3]
}

func per4Tuple(_ key: Int) -> [Int] {
    [key >> 6, (key >> 4) & 3, (key >> 2) & 3, key & 3]
}

func per4Shuffle(
    for element: Element,
    overriding override: (_ key: Int, _ element: Element) -> String? = { _, _ in nil }
) -> String {
    let cases = per4Tuples().map { tuple in
        let indices = per4Indices(Array(tuple.reversed()), for: element)
        let key = per4Key(tuple)
        return (
            amount: key,
            body: override(key, element) ?? shuffleResult("a", "a", indices, for: element)
        )
    }
    let known = constantSwitch(
        on: "((i3 * 4u + i2) * 4u + i1) * 4u + i0",
        knowing: ["i3", "i2", "i1", "i0"],
        cases
    )
    let lookup: String
    let preparation: String
    if element.laneCount > 2 {
        lookup = "result[i] = a[i / 4 * 4 + (shuffle[i % 4] & 3)];"
        preparation = "const int shuffle[4] = {i0, i1, i2, i3};"
    } else {
        lookup = "result[i] = a[perTwo[i]];"
        preparation = """
            const bool reversed = (i0 == 1 || i1 == 0) && i0 != i1;
            const int perTwo[2] = {i0 <= 1 ? i0 : (reversed ? 1 : 0), i1 <= 1 ? i1 : (reversed ? 0 : 1)};
            """
    }
    return """
        \(known)
        \(preparation)
        \(laneLoop("i", lookup, for: element))
        """
}

func portablePer4Shuffle(for element: Element) -> String {
    per4Shuffle(for: element)
}

let per4NativeShuffles: Set<Int> = [
    0x1B, 0x44, 0x4E, 0x50, 0x88, 0xA0, 0xB1, 0xDD, 0xE4, 0xEE, 0xF5, 0xFA,
]

func per4WidenedLanes(of element: Element) -> Element {
    unsignedElement(bits: element.bits * 2).at(width: element.width)
}

func per4ConcatenatedPairs(odd: Bool, for element: Element) -> String {
    let lanes = element.laneCount
    let wide = per4WidenedLanes(of: element)
    let parts = (0..<lanes).map { 2 * ($0 % (lanes / 2)) + (odd ? 1 : 0) }
    let concatenated = "__builtin_shufflevector(a, a, \(laneIndices(parts)))"
    let half = wide.laneCount
    let interleaved = (0..<half).map { $0 % 2 == 0 ? $0 / 2 : half + $0 / 2 }
    let pairs = vectorTypedef("pairs_vector", of: wide, lanes: half)
    return """
        {
          \(pairs)
          const pairs_vector pairs = (pairs_vector)\(concatenated);
          \(vectorResult("(\(element.cVector))__builtin_shufflevector(pairs, pairs, \(laneIndices(interleaved)))", for: element))
        }
        """
}

func neonPer4Override(key: Int, element: Element) -> String? {
    if element.bits == 32 && !per4NativeShuffles.contains(key) {
        let size = element.bits / 8
        let indices = per4Indices(Array(per4Tuple(key).reversed()), for: element)
        let lanes = indices.flatMap { index in (0..<size).map { String(index * size + $0) } }
        let table = compoundLiteral(blockByteVector, lanes)
        return vectorResult(neonTableLookup("a", table, for: element), for: element)
    }
    if element.bits <= 16 && (key == 0x88 || key == 0xDD) {
        return per4ConcatenatedPairs(odd: key == 0xDD, for: element)
    }
    return nil
}

func svePer4Override(key: Int, element: Element) -> String? {
    let operand = sveOperand("a", for: element, splat: true)
    if element.bits == 32 && key == 0x1B {
        let reversed = sveBuiltin("rev", [operand], for: element)
        return vectorResult(sveResult(reversed, for: element), for: element)
    }
    if element.bits == 64 {
        let shuffle = per4Indices(Array(per4Tuple(key).reversed()), for: element)
        guard shuffle[0] == shuffle[1] else { return nil }
        let duplicated = sveBuiltin(
            shuffle[0] == 0 ? "trn1" : "trn2",
            [operand, operand],
            for: element
        )
        return vectorResult(sveResult(duplicated, for: element), for: element)
    }
    guard element.bits <= 16 && (key == 0x88 || key == 0xDD) else { return nil }
    let wide = per4WidenedLanes(of: element)
    let concatenated = sveBuiltin(key == 0x88 ? "uzp1" : "uzp2", [operand, operand], for: element)
    let pairs = sveReinterpreted(concatenated, from: element, to: wide)
    let interleaved = sveBuiltin("zip1", [pairs, pairs], for: wide)
    let result = sveReinterpreted(interleaved, from: wide, to: element)
    return vectorResult(sveResult(result, for: element), for: element)
}

func x86Sse2Per4Override(key: Int, element: Element) -> String? {
    guard element.bits == 8 else { return nil }
    let words = unsignedElement(bits: 16).at(width: element.width)
    let lanes = words.laneCount
    let typedef = vectorTypedef("words_vector", of: words, lanes: lanes)
    let word = "(words_vector)a"
    let expression: String
    switch key {
    case 0x1B:
        let swapped = "((\(word) >> 8) | (\(word) << 8))"
        let order = laneIndices((0..<lanes).map { $0 ^ 1 })
        expression = "__builtin_shufflevector(\(swapped), \(swapped), \(order))"
    case 0xA0:
        let mask = splat("0x00FF", as: "words_vector", lanes: lanes)
        expression = "((\(word) & \(mask)) | (\(word) << 8))"
    case 0xF5:
        let mask = splat("0xFF00", as: "words_vector", lanes: lanes)
        expression = "((\(word) >> 8) | (\(word) & \(mask)))"
    default:
        return nil
    }
    return """
        {
          \(typedef)
          \(vectorResult("(\(element.cVector))\(expression)", for: element))
        }
        """
}

func per4Targets() -> TargetBodies<Element> {
    TargetBodies(
        neon: { per4Shuffle(for: $0, overriding: neonPer4Override) },
        sve2_128: { per4Shuffle(for: $0, overriding: svePer4Override) },
        ssse3: { per4Shuffle(for: $0) },
        sse2: { per4Shuffle(for: $0, overriding: x86Sse2Per4Override) }
    )
}

func x86SlideDownCombine(level: X86Level, for element: Element) -> String {
    x86BlockCombine(amount: "lanes", unit: element.bits / 8, level: level, for: element)
}

func x86Avx2SlideDownCombine(for element: Element) -> String {
    let bytes = x86Vector("i8")
    let words = x86Vector("i64")
    let size = element.bits / 8
    let swapped: String
    switch (element.category, element.bits) {
    case (.float, let bits):
        let suffix = bits == 32 ? "ps" : "pd"
        let lane = x86Vector(bits == 32 ? "f32" : "f64")
        swapped = x86Builtin(
            "vperm2f128_\(suffix)256",
            [(value: "b", type: lane), (value: "a", type: lane), (value: "33", type: "int")],
            returning: bytes
        )
    default:
        swapped = x86Builtin(
            "permti256",
            [(value: "b", type: words), (value: "a", type: words), (value: "33", type: "int")],
            returning: bytes
        )
    }
    let cases = (1..<element.laneCount).map { lanes in
        let count = lanes * size
        func aligned(_ high: String, _ low: String, _ amount: Int) -> String {
            let alignment = x86Builtin(
                "palignr256",
                [
                    (value: high, type: bytes), (value: low, type: bytes),
                    (value: "\(amount)", type: "int"),
                ],
                returning: element.cVector
            )
            return vectorResult(alignment, for: element)
        }
        let body: String
        switch count {
        case ..<16: body = aligned("inner", "b", count)
        case 16: body = vectorResult("inner", for: element)
        default: body = aligned("a", "inner", count - 16)
        }
        return (amount: lanes, body: "{\n  const \(bytes) inner = \(swapped);\n  \(body)\n}")
    }
    return """
        \(constantSwitch(on: "lanes", cases))
        \(portableCombineSlideDownRuntime(for: element))
        """
}

func combinedSlideDownTargets() -> TargetBodies<Element> {
    TargetBodies(
        sve2_128: { sveBlockCombine(amount: "lanes", unit: $0.bits / 8, for: $0) },
        avx2: { x86Avx2SlideDownCombine(for: $0) },
        ssse3: { x86SlideDownCombine(level: .ssse3, for: $0) },
        sse2: { x86SlideDownCombine(level: .sse2, for: $0) }
    )
}

