func immediateMaskedShiftOps(
    _ swiftName: String,
    zeroed: String,
    merged: String,
    same: String
) -> [Op] {
    let family = MaskedFamily(
        swiftName: swiftName,
        operation: swiftName,
        operands: [.vector, .shiftAmount],
        applies: .integer,
        zeroed: zeroed,
        merged: merged,
        zeroedSection: .maskedShifts,
        mergedSection: .maskedShifts,
        expression: { element in
            let shift = cFunctionName(swiftName, element)
            return "(\(element.cVector))\(shift)((\(element.cRawVector))a, bits)"
        }
    )
    func template(_ name: String, merging: Bool) -> ImmediateTemplate {
        ImmediateTemplate(
            name: name,
            range: { 0...$0.bits - 1 },
            fallback: { arguments in
                merging
                    ? "hn::IfThenElse(\(arguments[1]), hn::\(same)(\(arguments[2]), \(arguments[3])), \(arguments[0]))"
                    : "hn::IfThenElseZero(\(arguments[0]), hn::\(same)(\(arguments[1]), \(arguments[2])))"
            },
            paths: TargetBodies()
        )
    }
    var mergedTargets = maskedFamilyTargets(family, merging: true)
    mergedTargets.avx3 = { element in
        let shifted = maskedExpression(of: family, for: element)
        let selected = x86Avx3Selecting("mask", shifted, "otherwise", for: element)
        return vectorResult(selected, for: element)
    }
    return [
        maskedOp(family, zeroed, merging: false, template: template(zeroed, merging: false)),
        maskedOp(
            family,
            merged,
            merging: true,
            template: template(merged, merging: true),
            targets: mergedTargets
        ),
    ]
}

let immediateMaskedOps: [Op] =
    immediateMaskedShiftOps(
        "shiftedLeft",
        zeroed: "MaskedShiftLeft",
        merged: "MaskedShiftLeftOr",
