        blockShiftOp("shiftedRightBytes", "ShiftRightBytes", .right, bytewise: true),
        blockShiftOp("shiftedLeftLanes", "ShiftLeftLanes", .left, bytewise: false),
        blockShiftOp("shiftedRightLanes", "ShiftRightLanes", .right, bytewise: false),
        blockCombineOp("combinedShiftedRightBytes", "CombineShiftRightBytes", bytewise: true),
        blockCombineOp("combinedShiftedRightLanes", "CombineShiftRightLanes", bytewise: false),
    ] + shuffleOps + immediateMaskedOps

func loadedDeclaration(from pointer: String = "from", for element: Element) -> String {
    """
    \(element.cVector) v;
    __builtin_memcpy(&v, \(pointer), sizeof v);
    """
}

func repeatedBlockLoad(for element: Element) -> String {
    guard element.width > 16 else { return loadedVector(from: "from", for: element) }
    let blockLanes = Array(0..<element.blockLaneCount)
    let indices = Array(repeating: blockLanes, count: element.width / 16).flatMap { $0 }
    let repeated = "__builtin_shufflevector(block, block, \(laneIndices(indices)))"
    return """
        \(element.cBlock) block;
        __builtin_memcpy(&block, from, sizeof block);
        \(vectorResult(repeated, for: element))
        """
}

func maskedLoad(otherwise: Bool, for element: Element) -> String {
    let selected =
        otherwise
        ? bitSelect("mask", "v", "otherwise", of: element)
        : fromUnsignedBits(
            "(\(element.cUnsignedVector))mask & \(unsignedBits("v", of: element))",
            of: element
        )
    return """
        \(loadedDeclaration(for: element))
        \(vectorResult(selected, for: element))
        """
}

func portableLoadFirstOtherwise(for element: Element) -> String {
    let size = "\(clampedCount(to: element.laneCount)) * sizeof(\(element.cType))"
    return """
        const size_t size = \(size);
        \(element.cVector) v = otherwise;
        __builtin_memcpy(&v, from, size);
        \(vectorResult("v", for: element))
        """
}

func loadedUpperHalf(for element: Element) -> String {
    let lanes = element.laneCount
    let half = element.width / 2
    guard element.width > 16 else {
        guard element.category != .float || element.bits != 64 else {
            return """
                \(element.cVector) v = a;
                v[1] = from[0];
                \(vectorResult("v", for: element))
                """
        }
        return """
            typedef long long wide_lane_vector __attribute__((vector_size(\(element.width))));
            wide_lane_vector v = (wide_lane_vector)a;
            long long upper;
            __builtin_memcpy(&upper, from, sizeof upper);
            v[1] = upper;
            \(vectorResult("v", for: element))
            """
    }
    let lower = "__builtin_shufflevector(a, a, \(laneIndices(0..<lanes / 2)))"
    let joined = "__builtin_shufflevector(lower, upper, \(laneIndices(0..<lanes)))"
    return """
        typedef \(element.cType) half_vector __attribute__((vector_size(\(half))));
        const half_vector lower = \(lower);
        half_vector upper;
        __builtin_memcpy(&upper, from, sizeof upper);
        \(vectorResult(joined, for: element))
        """
}

func maskedLaneStore(for element: Element) -> String {
    """
    for (size_t i = 0; i < \(element.laneCount); ++i) {
      if (mask[i]) {
        to[i] = a[i];
      }
    }
    """
}

func gatheredLoad(_ lane: String, for element: Element) -> String {
    """
    \(element.cType) lanes[\(element.laneCount)];
    for (size_t i = 0; i < \(element.laneCount); ++i) {
      \(lane)
    }
    \(element.cVector) v;
    __builtin_memcpy(&v, lanes, sizeof v);
    \(vectorResult("v", for: element))
    """
}

func copiedMaskGatheredIndices(for element: Element) -> String {
    let lane = "lanes[i] = maskLanes[i] ? from[indices[i]] : 0;"
    return """
        \(signedElement(of: element).cType) maskLanes[\(element.laneCount)];
        for (size_t i = 0; i < \(element.laneCount); ++i) {
          maskLanes[i] = mask[i];
        }
        \(gatheredLoad(lane, for: element))
        """
}

func gatheredIndices(selected: String? = nil, for element: Element) -> String {
    let load = "from[indices[i]]"
    let lane = selected.map { "lanes[i] = mask[i] ? \(load) : \($0);" } ?? "lanes[i] = \(load);"
    return gatheredLoad(lane, for: element)
}

func gatheredOffsets(for element: Element) -> String {
    gatheredLoad(
        "__builtin_memcpy(&lanes[i], (const char*)from + byteOffsets[i], sizeof lanes[i]);",
        for: element
    )
}

func extractedIndices(for element: Element) -> String {
    let index = signedElement(of: element).cType
    return (0..<element.laneCount)
        .map { "const \(index) index\($0) = indices[\($0)];" }.joined(separator: "\n")
}

func gatheredFirst(for element: Element) -> String {
    """
    \(zeroedVector(of: element.cVector))
    for (size_t i = 0; i < \(element.laneCount); ++i) {
      if (i < count) {
        v[i] = from[indices[i]];
      }
    }
    \(vectorResult("v", for: element))
    """
}

func x86BlendedGatheredFirst(for element: Element) -> String? {
    guard element.category != .float, element.bits == 32 else { return nil }
    let unsigned = element.cUnsignedVector
    let masks = (0..<element.laneCount).map { lane in
        let values = (0..<element.laneCount).map { $0 == lane ? "~0u" : "0" }
        return "(wide_lane_vector)\(compoundLiteral(unsigned, values))"
    }
    let lane = splat("lane", as: element.cVector, lanes: element.laneCount)
    return """
        typedef long long wide_lane_vector __attribute__((vector_size(16)));
        const wide_lane_vector masks[\(element.laneCount)] = {\(masks.joined(separator: ", "))};
        wide_lane_vector v = {0, 0};
        for (size_t i = 0; i < \(element.laneCount); ++i) {
          if (i < count) {
            const \(element.cType) lane = from[indices[i]];
            v = ((wide_lane_vector)\(lane) & masks[i]) | (v & ~masks[i]);
          }
        }
        \(vectorResult("(\(element.cVector))v", for: element))
        """
}

func hoistedGatheredFirst(for element: Element) -> String {
    let lanes = (0..<element.laneCount).map { lane in
        "if (\(lane) < count) {\n  v[\(lane)] = from[index\(lane)];\n}"
    }
    return """
        \(extractedIndices(for: element))
        \(zeroedVector(of: element.cVector))
        \(lanes.joined(separator: "\n"))
        \(vectorResult("v", for: element))
        """
}

func scatteredLanes(
    _ store: String,
    condition: String? = nil,
    for element: Element
) -> String {
    let body = condition.map { "if (\($0)) {\n    \(store)\n  }" } ?? store
    return """
        for (size_t i = 0; i < \(element.laneCount); ++i) {
          \(body)
        }
        """
}

func x86Avx2ScatteredLanes(selecting: Bool, for element: Element) -> String? {
    guard element.width == 32 else { return nil }
    guard selecting else {
        let half = element.laneCount / 2
        let index = signedElement(of: element)
        let halves = [
            (name: "a", lane: "value", type: element.cType),
            (name: "indices", lane: "index", type: index.cType),
        ]
        .flatMap { operand in
            [
                "typedef \(operand.type) half_\(operand.lane) __attribute__((vector_size(16)));",
                "const half_\(operand.lane) lower\(uppercasedFirst(operand.lane)) = (half_\(operand.lane))((wide_lanes)\(operand.name))[0];",
                "const half_\(operand.lane) upper\(uppercasedFirst(operand.lane)) = (half_\(operand.lane))((wide_lanes)\(operand.name))[1];",
            ]
        }
        let stores = (0..<element.laneCount).map { lane -> String in
            let part = lane < half ? "lower" : "upper"
            return
                "if (\(lane) < count) {\n  to[\(part)Index[\(lane % half)]] = \(part)Value[\(lane % half)];\n}"
        }
        return (["typedef __int128 wide_lanes __attribute__((vector_size(32)));"] + halves + stores)
            .joined(separator: "\n")
    }
    let hoisted = (0..<element.laneCount).map { lane in
        "const \(element.cMaskLane) selected\(lane) = mask[\(lane)];"
    }
    let stores = (0..<element.laneCount).map { lane in
        "if (selected\(lane)) {\n  to[indices[\(lane)]] = a[\(lane)];\n}"
    }
    return (hoisted + stores).joined(separator: "\n")
}

func hoistedScatteredFirst(for element: Element) -> String {
    let values = (0..<element.laneCount)
        .map { "const \(element.cType) value\($0) = a[\($0)];" }.joined(separator: "\n")
    let lanes = (0..<element.laneCount).map { lane in
        "if (\(lane) < count) {\n  to[index\(lane)] = value\(lane);\n}"
    }
    return """
        \(extractedIndices(for: element))
        \(values)
        \(lanes.joined(separator: "\n"))
        """
}

func scatteredOffsets(for element: Element) -> String {
    """
    \(element.cType) lanes[\(element.laneCount)];
    __builtin_memcpy(lanes, &a, sizeof a);
    \(scatteredLanes("__builtin_memcpy((char*)to + byteOffsets[i], &lanes[i], sizeof lanes[i]);", for: element))
    """
}

func truncatedStore(to narrow: Element, for element: Element) -> String {
    let bytes = element.laneCount * narrow.bits / 8
    return """
        typedef \(narrow.cType) narrow_vector __attribute__((vector_size(\(bytes))));
        const narrow_vector truncated = __builtin_convertvector(a, narrow_vector);
        __builtin_memcpy(to, &truncated, sizeof truncated);
        """
}

func lowestLanesTruncatedStore(to narrow: Element, for element: Element) -> String? {
    guard element.bits == 64, narrow.bits < 32 else { return nil }
    let narrowBytes = narrow.bits / 8
    let elementBytes = element.bits / 8
    let kept = (0..<element.laneCount).flatMap { lane in
        (0..<narrowBytes).map { lane * elementBytes + $0 }
    }
    let indices = laneIndices(kept + Array(repeating: -1, count: element.width - kept.count))
    let chunk = "uint\(8 * kept.count)_t"
    return """
        typedef uint8_t byte_view __attribute__((vector_size(\(element.width))));
        typedef \(chunk) chunk_view __attribute__((vector_size(\(element.width))));
        const byte_view packed = __builtin_shufflevector((byte_view)a, (byte_view)a, \(indices));
        const \(chunk) truncated = ((chunk_view)packed)[0];
        __builtin_memcpy(to, &truncated, sizeof truncated);
        """
}

func x86Sse2TruncatedStore(to narrow: Element, for element: Element) -> String? {
    guard element.bits == 64, narrow.bits == 8 else { return nil }
    let bytes = x86Vector("i8")
    let interleaved = laneIndices((0..<8).flatMap { [$0, $0 + 16] })
    return """
        const \(bytes) high = (\(bytes))__builtin_ia32_pshufd((\(x86Vector("i32")))a, 0xEE);
        const \(bytes) packed = __builtin_shufflevector((\(bytes))a, high, \(interleaved));
        const uint16_t truncated = (uint16_t)((\(x86Vector("i16")))packed)[0];
        __builtin_memcpy(to, &truncated, sizeof truncated);
        """
}

func truncatingStoreOp(to narrow: Element) -> Op {
    Op(
        "storeTruncating",
        "TruncateStore",
        [.vector, .tag, .narrowLanePointer],
        .void,
        .unsigned(bits: Set([16, 32, 64].filter { $0 > narrow.bits })),
        section: .store,
        span: .vectors(1),
        identifier: "storeTruncating\(narrow.suffix)",
        targets: TargetBodies(
            neon: { element in lowestLanesTruncatedStore(to: narrow, for: element) },
            sve2_128: { element in sveTruncatedStore(to: narrow, for: element) },
            ssse3: { element in truncatedStore(to: narrow, for: element) },
            sse2: { element in x86Sse2TruncatedStore(to: narrow, for: element) }
        ),
        narrowElement: narrow,
        appendsToOutputSpan: false
    ) { element in
        truncatedStore(to: narrow, for: element)
    }
}

func compressedLanes(selecting selected: String, for element: Element) -> String {
    """
    \(element.cType) source[\(element.laneCount)];
    \(element.cType) result[\(element.laneCount)];
    __builtin_memcpy(source, &a, sizeof source);
    size_t count = 0;
    for (size_t i = 0; i < \(element.laneCount); ++i) {
      if (\(selected)) {
        result[count++] = source[i];
      }
    }
    for (size_t i = 0; i < \(element.laneCount); ++i) {
      if (!(\(selected))) {
        result[count++] = source[i];
      }
    }
    \(element.cVector) v;
    __builtin_memcpy(&v, result, sizeof v);
    """
}

func compressedStore(for element: Element) -> String {
    """
    size_t count = 0;
    for (size_t i = 0; i < \(element.laneCount); ++i) {
      if (mask[i]) {
        to[count++] = a[i];
      }
    }
    return count;
    """
}

let compressBitSelected = "(bits[i / 8] >> (i % 8)) & 1"

func compressedBits(for element: Element) -> String {
    """
    \(compressedLanes(selecting: compressBitSelected, for: element))
    \(vectorResult("v", for: element))
    """
}

func compressedBitsStore(for element: Element) -> String {
    """
    \(compressedLanes(selecting: compressBitSelected, for: element))
    size_t selected = 0;
    for (size_t i = 0; i < \(element.laneCount); ++i) {
      selected += (bits[i / 8] >> (i % 8)) & 1;
    }
    __builtin_memcpy(to, &v, sizeof v);
    return selected;
    """
}

func expandedLoad(otherwise: Bool, for element: Element) -> String {
    let initial =
        otherwise ? "\(element.cVector) v = otherwise;" : zeroedVector(of: element.cVector)
    return """
        \(initial)
        size_t position = 0;
        for (size_t i = 0; i < \(element.laneCount); ++i) {
          if (mask[i]) {
            v[i] = from[position++];
          }
        }
        \(vectorResult("v", for: element))
        """
}

func loadedIndices(for element: Element) -> String {
    let indices = laneIndexElement(of: element)
    return """
        \(indices.cVector) v;
        __builtin_memcpy(&v, from, sizeof v);
        return (\(indices.cRawVector))v;
        """
}

// A cache control op acts on the CPU, or on memory through a pointer to anything, rather than on
// the lanes of a vector, so it is generated once, on `SIMDTarget`, and not for each element type.
// Highway chooses its code by the architecture of the host rather than by the static target.
struct CacheControlOp {
    let swiftName: String
    let highwayName: String
    let pointerLabel: String?
    let body: String

    var takesPointer: Bool { pointerLabel != nil }
    var cName: String { "cvectorization_ops_\(snakeCased(swiftName))" }
    var cParameters: [String] { takesPointer ? ["const void* p"] : [] }
    var referenceParameters: String { takesPointer ? "const void* p" : "" }
    var referenceArguments: String { takesPointer ? "p" : "" }
}

let cacheControlOps = [
    CacheControlOp(
        swiftName: "flushStreams",
        highwayName: "FlushStream",
        pointerLabel: nil,
        body: """
            #if defined(__x86_64__) || defined(__i386__)
            __builtin_ia32_sfence();
            #endif
            """
    ),
    CacheControlOp(
        swiftName: "flushCacheLine",
        highwayName: "FlushCacheline",
        pointerLabel: "containing",
        body: """
            #if defined(__x86_64__) || defined(__i386__)
            __builtin_ia32_clflush(p);
            #else
            (void)p;
            #endif
            """
    ),
    CacheControlOp(
        swiftName: "prefetch",
        highwayName: "Prefetch",
        pointerLabel: "_",
        body: "__builtin_prefetch(p, 0, 3);"
    ),
    CacheControlOp(
        swiftName: "pause",
        highwayName: "Pause",
        pointerLabel: nil,
        body: """
            #if defined(__x86_64__) || defined(__i386__)
            __builtin_ia32_pause();
            #elif defined(__aarch64__)
            __builtin_arm_yield();
            #endif
            """
    ),
]

func cacheControlFunctions() -> String {
    cacheControlOps.map {
        cFunction(returns: "void", name: $0.cName, parameters: $0.cParameters, body: $0.body)
    }.joined()
}

func cacheControlReferenceFunctions() -> String {
    cacheControlOps.map {
        "HWY_INLINE void \($0.swiftName)(\($0.referenceParameters)) "
            + "{ hwy::\($0.highwayName)(\($0.referenceArguments)); }\n"
    }.joined()
}

func cacheControlNothrowFunctions() -> String {
    cacheControlOps.map {
        "HWY_INLINE void \($0.swiftName)(\($0.referenceParameters)) noexcept "
            + "{ ::HighwayReference::\($0.swiftName)(\($0.referenceArguments)); }\n"
    }.joined()
}

func cacheControlMembers() -> String {
    cacheControlOps.map { op in
        let parameter = op.pointerLabel.map { label in
            "\(label == "_" ? "_ pointer" : "\(label) pointer"): UnsafeRawPointer"
        }
        let call =
            "\(op.takesPointer ? "unsafe " : "")\(op.cName)(\(op.takesPointer ? "pointer" : ""))"
        return """
            @export(implementation) @inline(always)
            public static func \(op.swiftName)(\(parameter ?? "")) {
                \(call)
            }
            """
    }.joined(separator: "\n\n")
}

func generateCacheControl() -> String {
    """
    \(generationNotice)

    \(elementImports)

    extension SIMDTarget {
    \(cacheControlMembers())
    }

    """
}

func cacheControlRunTests() -> [String] {
    cacheControlOps.map { op in
        let arguments =
            op.pointerLabel.map { label in
                "\(label == "_" ? "" : "\(label): ")buffer.baseAddress!"
            } ?? ""
        let call = "\(op.takesPointer ? "unsafe " : "")SIMDTarget.\(op.swiftName)(\(arguments))"
        let reference =
            "\(op.takesPointer ? "unsafe " : "")HighwayReference.\(op.swiftName)(\(op.takesPointer ? "buffer.baseAddress!" : ""))"
        guard op.takesPointer else {
            return "@Test func \(op.swiftName)() {\n\(call)\n\(reference)\n}"
        }
        return """
            @Test func \(op.swiftName)() {
            let lanes = [UInt8](repeating: 0, count: 64)
            lanes.withUnsafeBytes { buffer in
            \(call)
            \(reference)
            }
            }
            """
    }
}

func cacheControlCodegenFunctions() -> String {
    cacheControlOps.map { op in
        let parameter = op.takesPointer ? "_ pointer: UnsafeRawPointer" : ""
        let keyword = op.takesPointer ? "unsafe " : ""
        let arguments = op.takesPointer ? "pointer" : ""
        let reference = "\(referenceNothrowNamespace).\(op.swiftName)(\(arguments))"
        let label = op.pointerLabel.map { $0 == "_" ? "" : "\($0): " } ?? ""
        return [
            codegenFunction(
                codegenFunctionName("port", op.swiftName),
                parameters: [parameter].filter { !$0.isEmpty },
                returnClause: "",
                call: "\(keyword)SIMDTarget.\(op.swiftName)(\(label)\(arguments))"
            ),
            codegenFunction(
                codegenFunctionName("highway", op.swiftName),
                parameters: [parameter].filter { !$0.isEmpty },
                returnClause: "",
                call: "\(keyword)\(reference)"
            ),
        ].joined(separator: "\n\n")
    }.joined(separator: "\n\n")
}

func unboundedLaneLoop(_ statement: String) -> String {
    """
    #pragma clang loop vectorize(assume_safety)
    for (size_t i = 0; i < count; ++i) {
      \(statement)
    }
    """
}

func sveMaskedLoad(otherwise: Bool, for element: Element) -> String {
    let predicate = svePredicate(of: "mask", for: element)
    let loaded = sveBuiltin("ld1", [predicate, "from"], for: element)
    let selected = sveBuiltin(
        "sel",
        [predicate, loaded, sveOperand("otherwise", for: element, splat: true)],
        for: element
    )
    return vectorResult(sveResult(otherwise ? selected : loaded, for: element), for: element)
}

func sveBlendedStore(for element: Element) -> String {
    let stored = sveBuiltin(
        "st1",
        [svePredicate(of: "mask", for: element), "to", sveOperand("a", for: element, splat: true)],
        for: element
    )
    return "\(stored);"
}

func sveLoadFirstOtherwise(for element: Element) -> String {
    let active = sveActiveLanes("count", for: element)
    let loaded = sveBuiltin("ld1", [active, "from"], for: element)
    let selected = sveBuiltin(
        "sel",
        [active, loaded, sveOperand("otherwise", for: element, splat: true)],
        for: element
    )
    return vectorResult(sveResult(selected, for: element), for: element)
}

func sveSafeFill(for element: Element) -> String {
    let filled = sveBuiltin("dup_n", ["value"], for: element)
    let stored = sveBuiltin(
        "st1",
        [sveActiveLanes("count", for: element), "to", filled],
        for: element
    )
    return "\(stored);"
}

func sveSafeCopy(for element: Element) -> String {
    let active = sveActiveLanes("count", for: element)
    let loaded = sveBuiltin("ld1", [active, "from"], for: element)
    return "\(sveBuiltin("st1", [active, "to", loaded], for: element));"
}

func x86Avx3MaskedLoad(otherwise: Bool, for element: Element) -> String {
    let lanes = element.laneCount
    let register = x86Vector(x86LaneSuffix(of: element))
    let loaded = x86Builtin(
        x86MaskedAccessName("load", width: element.width, for: element),
        [
            (
                value: "from",
                type: "const \(x86MaskedPointee(of: register, width: element.width, for: element))*"
            ),
            (value: otherwise ? "otherwise" : compoundLiteral(register, ["0"]), type: register),
            (value: x86Avx3MaskBits("mask", for: element), type: x86MaskType(lanes: lanes)),
        ],
        returning: element.cVector
    )
    return vectorResult(loaded, for: element)
}

func x86Avx3BlendedStore(for element: Element) -> String {
    let lanes = element.laneCount
    let register = x86Vector(x86LaneSuffix(of: element))
    let store = x86Builtin(
        x86MaskedAccessName("store", width: element.width, for: element),
        [
            (
                value: "to",
                type: "\(x86MaskedPointee(of: register, width: element.width, for: element))*"
            ),
            (value: "a", type: register),
            (value: x86Avx3MaskBits("mask", for: element), type: x86MaskType(lanes: lanes)),
        ],
        returning: "void"
    )
    return "\(store);"
}

func x86Avx3SafeFill(for element: Element) -> String {
    let lanes = element.laneCount
    let register = x86Vector(x86LaneSuffix(of: element))
    let store = x86Builtin(
        x86MaskedAccessName("store", width: element.width, for: element),
        [
            (
                value: "to",
                type: "\(x86MaskedPointee(of: register, width: element.width, for: element))*"
            ),
            (value: splat("value", as: element.cVector, lanes: lanes), type: register),
            (value: x86FirstLanesBits(lanes: lanes), type: x86MaskType(lanes: lanes)),
        ],
        returning: "void"
    )
    return "\(store);"
}

func x86Avx3SafeCopy(for element: Element) -> String {
    let lanes = element.laneCount
    let register = x86Vector(x86LaneSuffix(of: element))
    let pointee = x86MaskedPointee(of: register, width: element.width, for: element)
    let bits = (value: "bits", type: x86MaskType(lanes: lanes))
    let loaded = x86Builtin(
        x86MaskedAccessName("load", width: element.width, for: element),
        [
            (value: "from", type: "const \(pointee)*"),
            (value: compoundLiteral(register, ["0"]), type: register), bits,
        ],
        returning: register
    )
    let store = x86Builtin(
        x86MaskedAccessName("store", width: element.width, for: element),
        [(value: "to", type: "\(pointee)*"), (value: "loaded", type: register), bits],
        returning: "void"
    )
    return """
        const \(bits.type) bits = \(x86FirstLanesBits(lanes: lanes));
        const \(register) loaded = \(loaded);
        \(store);
        """
}

func x86Avx2HoistedMaskedStore(
    for element: Element,
    declaring declarations: [String] = [],
    storing store: (Int) -> String = { "to[\($0)] = a[\($0)];" }
) -> String {
    let lanes = (0..<element.laneCount).map { lane in
        "const \(element.cMaskLane) selected\(lane) = mask[\(lane)];"
    }
    let stores = (0..<element.laneCount).map { lane in
        "if (selected\(lane)) {\n  \(store(lane))\n}"
    }
    return (declarations + lanes + stores).joined(separator: "\n")
}

func x86Avx2MaskedAccess(store: Bool, for element: Element) -> String? {
    guard element.bits >= 32 else { return store ? x86Avx2HoistedMaskedStore(for: element) : nil }
    let letter =
        element.category == .float
        ? (element.bits == 32 ? "ps" : "pd") : (element.bits == 32 ? "d" : "q")
    let register = x86Vector(x86LaneSuffix(of: element))
    let mask = (value: "mask", type: x86Vector("i\(element.bits)"))
    guard store else {
        let loaded = x86Builtin(
            "maskload\(letter)256",
            [(value: "from", type: "const \(register)*"), mask],
            returning: element.cVector
        )
        return vectorResult(loaded, for: element)
    }
    let stored = x86Builtin(
        "maskstore\(letter)256",
        [(value: "to", type: "\(register)*"), mask, (value: "a", type: register)],
        returning: "void"
    )
    return "\(stored);"
}

func vectorBlendedStore(for element: Element) -> String {
    let selecting = cFunctionName("selecting", element)
    return """
        \(element.cVector) loaded;
        __builtin_memcpy(&loaded, to, sizeof loaded);
        const \(element.cVector) blended = (\(element.cVector))\(selecting)(rawMask, rawA, (\(element.cRawVector))loaded);
        __builtin_memcpy(to, &blended, sizeof blended);
        """
}

enum LoadFirstStyle {
    case lanes
    case masked
    case wide
    case adaptive
}

/// With `wrapping`, a count above the signed maximum of a lane selects no lanes, like Highway's
/// NEON `FirstN`.
func vectorLoadFirstOtherwise(
    wrapping: Bool = false,
    style: LoadFirstStyle = .lanes,
    for element: Element
) -> String? {
    let vector = element.cVector
    let load = "__builtin_memcpy(&v, from, sizeof v);"
    switch element.laneCount {
    case 2:
        return """
            \(vector) v;
            if (count >= 2) {
              \(load)
            } else {
              v = otherwise;
              if (count != 0) {
                v[0] = from[0];
              }
            }
            \(vectorResult("v", for: element))
            """
    case 4:
        func quartet(_ style: LoadFirstStyle) -> String {
            let pair = "typedef \(element.cType) pair_vector __attribute__((vector_size(8)));"
            let unsigned = element.cUnsignedVector
            let first =
                style == .masked
                ? """
                return (\(element.cRawVector))(\(vector))(((\(unsigned))otherwise & (\(unsigned)){0, ~0u, ~0u, ~0u}) | (\(unsigned))(\(vector)){from[0], 0, 0, 0});
                """
                : """
                v = otherwise;
                v[0] = from[0];
                return (\(element.cRawVector))v;
                """
            let pairLoaded =
                style == .wide
                ? """
                typedef long long wide_lane_vector __attribute__((vector_size(16)));
                wide_lane_vector wide = (wide_lane_vector)otherwise;
                long long pair;
                __builtin_memcpy(&pair, from, sizeof pair);
                wide[0] = pair;
                v = (\(vector))wide;
                """
                : """
                \(pair)
                pair_vector pair;
                __builtin_memcpy(&pair, from, sizeof pair);
                v = (\(vector)){pair[0], pair[1], otherwise[2], otherwise[3]};
                """
            return """
                \(vector) v;
                if (count >= 4) {
                  \(load)
                  return (\(element.cRawVector))v;
                }
                if (count == 0) {
                  return rawOtherwise;
                }
                if (count == 1) {
                  \(first)
                }
                \(pairLoaded)
                if (count != 2) {
                  v[2] = from[2];
                }
                \(vectorResult("v", for: element))
                """
        }
        guard style == .adaptive else { return quartet(style) }
        return """
            if (__builtin_constant_p(count)) {
            \(indented(quartet(.lanes)))
            }
            \(quartet(.masked))
            """
    default:
        let loaded = "\(cFunctionName("loadFirst", element))(from, count)"
        let mask =
            wrapping
            ? "(\(element.cRawMask))active" : "\(cFunctionName("firstLanes", element))(count)"
        let selected = "\(cFunctionName("selecting", element))(\(mask), \(loaded), rawOtherwise)"
        let lanes = element.laneCount
        let wrapped = """
            const \(element.cMaskLane) n = (\(element.cMaskLane))count;
            const \(element.cMask) active = \(iota(as: element.cMask, lanes: lanes)) < \(splat("n", as: element.cMask, lanes: lanes));
            """
        return "\(wrapping ? wrapped : "")\nreturn \(selected);"
    }
}

func x86Avx2LoadFirstOtherwise(for element: Element) -> String? {
    guard element.width == 32, element.bits >= 32 else { return nil }
    let lanes = element.laneCount / 2
    let fallback = portableLoadFirstOtherwise(for: element)
    let half = { (result: String, no: String, pointer: String, count: String) -> String in
        let loaded = "__builtin_memcpy(&\(result), \(pointer), sizeof \(result));"
        guard lanes == 4 else {
            return """
                if (\(count) >= 2) {
                  \(loaded)
                } else {
                  \(result) = \(no);
                  if (\(count) != 0) {
                    \(result)[0] = \(pointer)[0];
                  }
                }
                """
        }
        return """
            if (\(count) >= 4) {
              \(loaded)
            } else if (\(count) == 0) {
              \(result) = \(no);
            } else if (\(count) == 1) {
              \(result) = \(no);
              \(result)[0] = \(pointer)[0];
            } else {
              pair_vector pair;
              __builtin_memcpy(&pair, \(pointer), sizeof pair);
              \(result) = (half_vector){pair[0], pair[1], \(no)[2], \(no)[3]};
              if (\(count) != 2) {
                \(result)[2] = \(pointer)[2];
              }
            }
            """
    }
    let joined = "__builtin_shufflevector(lower, upper, \(laneIndices(0..<2 * lanes)))"
    return """
        if (__builtin_constant_p(count) && count < \(2 * lanes)) {
          typedef \(element.cType) half_vector __attribute__((vector_size(16)));
          \(lanes == 4 ? "typedef \(element.cType) pair_vector __attribute__((vector_size(8)));" : "")
        const half_vector lowerOtherwise = __builtin_shufflevector(otherwise, otherwise, \(laneIndices(0..<lanes)));
        const half_vector upperOtherwise = __builtin_shufflevector(otherwise, otherwise, \(laneIndices(lanes..<2 * lanes)));
        half_vector lower;
        half_vector upper = upperOtherwise;
        if (count <= \(lanes)) {
        \(indented(half("lower", "lowerOtherwise", "from", "count")))
        } else {
          __builtin_memcpy(&lower, from, sizeof lower);
        \(indented(half("upper", "upperOtherwise", "(from + \(lanes))", "(count - \(lanes))")))
        }
        \(vectorResult(joined, for: element))
        }
        \(fallback)
        """
}

func x86Avx3LoadFirstOtherwise(for element: Element) -> String {
    let lanes = element.laneCount
    let register = x86Vector(x86LaneSuffix(of: element))
    let loaded = x86Builtin(
        x86MaskedAccessName("load", width: element.width, for: element),
        [
            (
                value: "from",
                type: "const \(x86MaskedPointee(of: register, width: element.width, for: element))*"
            ),
            (value: "otherwise", type: register),
            (value: x86FirstLanesBits(lanes: lanes), type: x86MaskType(lanes: lanes)),
        ],
        returning: element.cVector
    )
    return vectorResult(loaded, for: element)
}

func x86GatherBaseType(for element: Element) -> String {
    switch (element.category, element.bits) {
    case (.float, 32): return "float"
    case (.float, _): return "double"
    case (_, 32): return "int"
    default: return "long long"
    }
}

func x86GatheringName(avx3: Bool, store: Bool, for element: Element) -> String {
    let isWide = element.bits == 64
    let letter = element.category == .float ? "f" : "i"
    if avx3 {
        return "\(store ? "scatter" : "gather")\(isWide ? "div8d" : "siv16s")\(letter)"
    }
    let kind = element.category == .float ? (isWide ? "pd" : "ps") : (isWide ? "q" : "d")
    return "gather\(isWide ? "q" : "d")_\(kind)256"
}

/// A gather through `index`, of the lanes selected by `active` if given and otherwise all of them,
/// which take their other lanes from `source`.
func x86Gathered(
    avx3: Bool,
    index: String,
    scale: Int,
    source: String? = nil,
    active: String? = nil,
    for element: Element
) -> String {
    let lanes = element.laneCount
    let register = x86Vector(x86LaneSuffix(of: element))
    let indices = x86Vector("i\(element.bits)")
    let base = avx3 ? "const void*" : "const \(x86GatherBaseType(for: element))*"
    let undefined = x86Builtin("undef\(avx3 ? 512 : 256)", [], returning: register)
    let mask =
        avx3
        ? (value: active ?? "~0ull", type: x86MaskType(lanes: lanes))
        : (value: active ?? splat("-1", as: indices, lanes: lanes), type: indices)
    let gathered = x86Builtin(
        x86GatheringName(avx3: avx3, store: false, for: element),
        [
            (value: source ?? undefined, type: register), (value: "from", type: base),
            (value: index, type: indices), mask, (value: String(scale), type: "int"),
        ],
        returning: element.cVector
    )
    return vectorResult(gathered, for: element)
}

func x86Avx3Scattered(
    index: String,
    scale: Int,
    active: String? = nil,
    for element: Element
) -> String {
    let lanes = element.laneCount
    let register = x86Vector(x86LaneSuffix(of: element))
    let indices = x86Vector("i\(element.bits)")
    let scattered = x86Builtin(
        x86GatheringName(avx3: true, store: true, for: element),
        [
            (value: "to", type: "void*"),
            (value: active ?? "~0ull", type: x86MaskType(lanes: lanes)),
            (value: index, type: indices), (value: "a", type: register),
            (value: String(scale), type: "int"),
        ],
        returning: "void"
    )
    return "\(scattered);"
}

func x86GatherTargets(
    index: String = "indices",
    offsets: Bool = false,
    selecting: Bool = false,
    otherwise: Bool = false,
    firstLanes: Bool = false
) -> TargetBodies<Element> {
    func body(avx3: Bool) -> (Element) -> String? {
        { element in
            let scale = offsets ? 1 : element.bits / 8
            var active: String?
            if selecting {
                active = avx3 ? x86Avx3MaskBits("mask", for: element) : "mask"
            } else if firstLanes {
                active =
                    avx3
                    ? x86FirstLanesBits(lanes: element.laneCount)
                    : "(\(x86Vector("i\(element.bits)")))\(cFunctionName("firstLanes", element))(count)"
            }
            let zero = compoundLiteral(x86Vector(x86LaneSuffix(of: element)), ["0"])
            let source = otherwise ? "otherwise" : (active == nil ? nil : zero)
            return x86Gathered(
                avx3: avx3,
                index: index,
                scale: scale,
                source: source,
                active: active,
                for: element
            )
        }
    }
    return TargetBodies(
        neon: { element in firstLanes ? hoistedGatheredFirst(for: element) : nil },
        sve2_128: { element in
            sveGathering(
                index: index,
                offsets: offsets,
                selecting: selecting,
                otherwise: otherwise,
                firstLanes: firstLanes,
                for: element
            )
        },
        avx3: body(avx3: true),
        avx2: body(avx3: false),
        sse4: { element in firstLanes ? gatheredFirst(for: element) : nil },
        sse2: { element in firstLanes ? x86BlendedGatheredFirst(for: element) : nil },
        emu128: { element in
            selecting && !otherwise && element.category == .float
                ? copiedMaskGatheredIndices(for: element) : nil
        }
    )
}

func x86Avx3ScatterTargets(
    offsets: Bool = false,
    selecting: Bool = false,
    firstLanes: Bool = false
) -> TargetBodies<Element> {
    TargetBodies(
        neon: { element in firstLanes ? hoistedScatteredFirst(for: element) : nil },
        sve2_128: { element in
            sveScattering(
                index: offsets ? "byteOffsets" : "indices",
                offsets: offsets,
                selecting: selecting,
                firstLanes: firstLanes,
                for: element
            )
        },
        avx3: { element in
            let index = offsets ? "byteOffsets" : "indices"
            var active: String?
            if selecting {
                active = x86Avx3MaskBits("mask", for: element)
            } else if firstLanes {
                active = x86FirstLanesBits(lanes: element.laneCount)
            }
            return x86Avx3Scattered(
                index: index,
                scale: offsets ? 1 : element.bits / 8,
                active: active,
                for: element
            )
        },
        avx2: { element in
            offsets || !(selecting || firstLanes)
                ? nil : x86Avx2ScatteredLanes(selecting: selecting, for: element)
        },
        sse2: { element in firstLanes ? hoistedScatteredFirst(for: element) : nil }
    )
}

func x86Avx3CompressSuffix(for element: Element) -> String {
    switch (element.category, element.bits) {
    case (.float, 32): return "sf"
    case (.float, _): return "df"
    case (_, 8): return "qi"
    case (_, 16): return "hi"
    case (_, 32): return "si"
    default: return "di"
    }
}

func x86Avx3IsNative(_ level: X86Level, for element: Element) -> Bool {
    element.bits >= 32 || level >= .avx3dl
}

func x86Avx3CompressStore(for element: Element) -> String {
    let lanes = element.laneCount
    let register = x86Vector(x86LaneSuffix(of: element))
    let stored = x86Builtin(
        "compressstore\(x86Avx3CompressSuffix(for: element))512_mask",
        [
            (value: "to", type: "\(register)*"), (value: "a", type: register),
            (value: "active", type: x86MaskType(lanes: lanes)),
        ],
        returning: "void"
    )
    return """
        const \(x86MaskType(lanes: lanes)) active = \(x86Avx3MaskBits("mask", for: element));
        \(stored);
        return __builtin_popcountll(active);
        """
}

func x86Avx3ExpandLoad(otherwise: Bool, for element: Element) -> String {
    let lanes = element.laneCount
    let register = x86Vector(x86LaneSuffix(of: element))
    let expanded = x86Builtin(
        "expandload\(x86Avx3CompressSuffix(for: element))512_mask",
        [
            (value: "from", type: "const \(register)*"),
            (value: otherwise ? "otherwise" : compoundLiteral(register, ["0"]), type: register),
            (value: x86Avx3MaskBits("mask", for: element), type: x86MaskType(lanes: lanes)),
        ],
        returning: element.cVector
    )
    return vectorResult(expanded, for: element)
}

func x86Avx3CompressStoreUnlessSlow(for element: Element) -> String {
    """
    #if \(staticTargetCondition(of: ["AVX3_ZEN4", "AVX3_SPR"]))
    \(registeredCompressedStore(blended: false, for: element))
    #else
    \(x86Avx3CompressStore(for: element))
    #endif
    """
}

func compressedStoreTargets(blended: Bool) -> TargetBodies<Element> {
    let registered = { (element: Element) in
        registeredCompressedStore(blended: blended, for: element)
    }
    let bytes = { (level: X86Level, element: Element) in
        element.bits == 8
            ? x86CompressedBytesStore(blended: blended, level: level, for: element)
            : registeredCompressedStore(blended: blended, countingBits: true, for: element)
    }
    return TargetBodies(
        neon: { element in neonCompressedStore(blended: blended, for: element) },
        sve2_128: { element in sveCompressedStore(blended: blended, for: element) },
        avx3dl: { element in
            blended
                ? x86Avx3CompressStore(for: element)
                : x86Avx3CompressStoreUnlessSlow(for: element)
        },
        avx3: { element in
            guard x86Avx3IsNative(.avx3, for: element) else {
                return blended ? registered(element) : x86Avx3EmulatedCompressedStore(for: element)
            }
            return x86Avx3CompressStore(for: element)
        },
        avx2: { element in bytes(.avx2, element) },
        ssse3: { element in bytes(.ssse3, element) },
        sse2: { element in bytes(.sse2, element) }
    )
}

func compressedBitsTargets() -> TargetBodies<Element> {
    TargetBodies(
        neon: { element in neonCompressedBits(for: element) },
        sve2_128: { element in
            element.bits == 64
                ? neonCompressedBits(for: element) : registeredCompressedBits(for: element)
        },
        avx3dl: { element in registeredCompressedBits(for: element) },
        avx3: { element in registeredCompressedBits(for: element) },
        avx2: { element in x86Avx2CompressedBits(for: element) },
        ssse3: { element in x86CompressedBits(level: .ssse3, for: element) },
        sse2: { element in x86CompressedBits(level: .sse2, for: element) }
    )
}

func compressedBitsStoreTargets() -> TargetBodies<Element> {
    TargetBodies(
        neon: { element in neonCompressedBitsStore(for: element) },
        sve2_128: { element in registeredCompressedBitsStore(for: element) },
        avx3dl: { element in registeredCompressedBitsStore(for: element) },
        avx3: { element in registeredCompressedBitsStore(for: element) },
        avx2: { element in x86Avx2CompressedBitsStore(for: element) },
        ssse3: { element in x86CompressedBitsStore(level: .ssse3, for: element) },
        sse2: { element in x86CompressedBitsStore(level: .sse2, for: element) }
    )
}

func expandedLoadTargets(otherwise: Bool) -> TargetBodies<Element> {
    TargetBodies(
        neon: { element in registeredExpandedLoad(otherwise: otherwise, for: element) },
        avx3dl: { element in x86Avx3ExpandLoad(otherwise: otherwise, for: element) },
        avx3: { element in
            x86Avx3IsNative(.avx3, for: element)
                ? x86Avx3ExpandLoad(otherwise: otherwise, for: element)
                : registeredExpandedLoad(otherwise: otherwise, for: element)
        },
        avx2: { element in registeredExpandedLoad(otherwise: otherwise, for: element) },
        sse2: { element in registeredExpandedLoad(otherwise: otherwise, for: element) }
    )
}

func vectorLoadedMaskBits(for element: Element) -> String {
    let lanes = element.laneCount
    return """
        uint64_t maskBits = bits[0];
        \(lanes > 8 ? "maskBits |= (uint64_t)bits[1] << 8;" : "")
        \(lanes < 8 ? "maskBits &= (1ull << \(lanes)) - 1;" : "")
        """
}

func swapCompressed(maskBits: String, for element: Element) -> String {
    """
    const \(element.cVector) swapped = __builtin_shufflevector(a, a, 1, 0);
    const \(element.cVector) compressed = \(maskBits) == 2 ? swapped : a;
    """
}

func x86BlendedMaskedLoad(for element: Element) -> String {
    """
    \(loadedDeclaration(for: element))
    \(vectorResult(x86Selecting("mask", "v", "otherwise", for: element), for: element))
    """
}

func sveActiveGatherLanes(selecting: Bool, firstLanes: Bool, for element: Element) -> String {
    if selecting { return svePredicate(of: "mask", for: element) }
    return firstLanes ? sveActiveLanes("count", for: element) : sveAllLanes(of: element)
}

func sveGathering(
    index: String,
    offsets: Bool,
    selecting: Bool,
    otherwise: Bool,
    firstLanes: Bool,
    for element: Element
) -> String {
    let active = sveActiveGatherLanes(selecting: selecting, firstLanes: firstLanes, for: element)
    let name = "ld1_gather_s\(element.bits)\(offsets ? "offset" : "index")"
    let gathered = sveBuiltin(
        name,
        [active, "from", sveIndexOperand(index, for: element)],
        for: element
    )
    let result =
        otherwise
        ? sveBuiltin(
            "sel",
            [active, gathered, sveOperand("otherwise", for: element, splat: true)],
            for: element
        )
        : gathered
    return vectorResult(sveResult(result, for: element), for: element)
}

func sveScattering(
    index: String,
    offsets: Bool,
    selecting: Bool,
    firstLanes: Bool,
    for element: Element
) -> String {
    let active = sveActiveGatherLanes(selecting: selecting, firstLanes: firstLanes, for: element)
    let name = "st1_scatter_s\(element.bits)\(offsets ? "offset" : "index")"
    let scattered = sveBuiltin(
        name,
        [
            active, "to", sveIndexOperand(index, for: element),
            sveOperand("a", for: element, splat: true),
        ],
        for: element
    )
    return "\(scattered);"
}

func scalarMaskedStore(for element: Element) -> String {
    let signed = signedElement(of: element)
    return """
        \(signed.cType) lanes[\(element.laneCount)] __attribute__((aligned(\(element.width))));
        \(signed.cType) selected[\(element.laneCount)] __attribute__((aligned(\(element.width))));
        __builtin_memcpy(lanes, &a, sizeof a);
        __builtin_memcpy(selected, &mask, sizeof mask);
        \(signed.cType)* destination = (\(signed.cType)*)to;
        for (size_t i = 0; i < \(element.laneCount); ++i) {
          if (selected[i]) {
            destination[i] = lanes[i];
          }
        }
        """
}

func x86Streamed(for element: Element) -> String {
    let register = x86Vector(x86LaneSuffix(of: element))
    let aligned = assumedAligned("to", for: element)
    return "__builtin_nontemporal_store((\(register))a, (\(register)*)\(aligned));"
}

func sveStreamed(for element: Element) -> String {
    let stored = sveBuiltin(
        "stnt1",
        [sveAllLanes(of: element), "to", sveOperand("a", for: element)],
        for: element
    )
    return "\(stored);"
}

func sveCompressedPartitionStore(for element: Element) -> String {
    let spliced = sveBuiltin("splice", ["swapped", "source", "source"], for: element)
    let stored = sveBuiltin("st1", [sveAllLanes(of: element), "to", "partitioned"], for: element)
    let count = "__builtin_sve_svcntp_b\(element.bits)(active, active)"
    return """
        const __SVBool_t active = \(svePredicate(of: "mask", for: element));
        const __SVBool_t lower = __builtin_sve_svzip1_b\(element.bits)(active, active);
        const __SVBool_t swapped = __builtin_sve_svbic_b_z(active, active, lower);
        const \(sveType(of: element)) source = \(sveOperand("a", for: element, splat: true));
        const \(sveType(of: element)) partitioned = \(spliced);
        \(stored);
        return \(count);
        """
}

func sveCompressedStore(blended: Bool, for element: Element) -> String {
    if !blended && element.bits == 64 { return sveCompressedPartitionStore(for: element) }
    let active = svePredicate(of: "mask", for: element)
    let compacted =
        if element.bits >= 32 {
            """
            const \(sveType(of: element)) compacted = \(sveBuiltin("compact", ["active", sveOperand("a", for: element)], for: element));
            """
        } else if blended && element.bits == 8 {
            neonCompressedScoped(not: false, into: "compacted", for: element)
        } else {
            """
            const \(element.cVector) compacted = (\(element.cVector))\(cFunctionName("compressed", element))(rawA, rawMask);
            """
        }
    let stored = sveBuiltin(
        "st1",
        [
            blended ? sveActiveLanes("count", for: element) : sveAllLanes(of: element), "to",
            element.bits >= 32 ? "compacted" : sveOperand("compacted", for: element),
        ],
        for: element
    )
    let count = "__builtin_sve_svcntp_b\(element.bits)(active, active)"
    let isCountedFirst = blended || element.bits >= 32
    return """
        const __SVBool_t active = \(active);
        \(compacted)
        \(isCountedFirst ? "const size_t count = \(count);" : "")
        \(stored);
        return \(isCountedFirst ? "count" : count);
        """
}

func sveTruncatedStore(to narrow: Element, for element: Element) -> String {
    let letter = ["b", "h", "w"][narrow.bits.trailingZeroBitCount - 3]
    let stored = sveBuiltin(
        "st1\(letter)",
        [sveAllLanes(of: element), "to", sveOperand("a", for: element, splat: true)],
        for: element
    )
    return "\(stored);"
}

