            .count,
            .all,
            section: .compress,
            span: .vectors(1),
            identifier: "storeCompressedBits",
            targets: compressedBitsStoreTargets(),
            appendsToOutputSpan: false
        ) { element in
            compressedBitsStore(for: element)
        },
        Op(
            "loadExpanded",
            "LoadExpand",
            [.whereMask, .tag, .constLanePointer],
            .vector,
            .all,
            section: .expand,
            span: .vectors(1),
            targets: expandedLoadTargets(otherwise: false)
        ) { element in
            expandedLoad(otherwise: false, for: element)
        },
        Op(
            "loadExpanded",
            "MaskedLoadExpandOr",
            [.otherwiseVector, .whereMask, .tag, .constLanePointer],
            .vector,
            .all,
            section: .expand,
            span: .vectors(1),
            targets: expandedLoadTargets(otherwise: true)
        ) { element in
            expandedLoad(otherwise: true, for: element)
        },
        Op(
            "loadIndices",
            "SetTableIndices",
            [.tag, .constIndexPointer],
            .laneIndices,
            .all,
            section: .userSpecifiedPermutationAcrossBlocks,
            span: .vectors(1)
        ) { element in
            loadedIndices(for: element)
        },
        Op(
            "storeStreaming",
            "Stream",
            [.vector, .tag, .lanePointer],
            .void,
            .all,
            section: .cacheControl,
            span: .vectors(1, aligned: true),
            targets: TargetBodies(
                neon: { _ in "__builtin_prefetch(to, 1, 0);\n\(storedVector(to: "to"))" },
                sve2_128: { element in sveStreamed(for: element) },
                avx3: { element in x86Streamed(for: element) },
                avx2: { element in x86Streamed(for: element) },
                sse2: { element in x86Streamed(for: element) }
            ),
            appendsToOutputSpan: false
        ) { _ in
            storedVector(to: "to")
        },
    ]
    + elements.filter { $0.category == .unsignedInteger && $0.bits < 64 }
    .map(truncatingStoreOp(to:))

func sourcedOps(
    accepting accepts: (_ source: Element, _ result: Element) -> Bool,
    includingHalfPrecision: Bool = false,
    _ makeOp: (_ source: Element, _ results: Applies) -> Op
) -> [Op] {
    let candidates = includingHalfPrecision ? elements : classicElements
    return candidates.compactMap { source in
        let results = candidates.filter { accepts(source, $0) }
        return results.isEmpty ? nil : makeOp(source, .results(results))
    }
}

func sourced<Output>(
    _ source: Element,
    _ body: @escaping (_ source: Element, _ result: Element) -> Output
) -> (Element) -> Output {
    { result in body(source.at(width: result.width), result) }
}

func includingFloat16(
    _ accepts: @escaping (Element, Element) -> Bool
) -> (Element, Element) -> Bool {
    { source, result in
        source.category != .bfloat16 && result.category != .bfloat16 && accepts(source, result)
    }
}

func differentElements(_ source: Element, _ result: Element) -> Bool {
    source.suffix != result.suffix
}

func differentHalfPrecisions(_ source: Element, _ result: Element) -> Bool {
    source.isHalfPrecision && result.isHalfPrecision && source.category != result.category
}

let bitCastOps = sourcedOps(accepting: differentElements, includingHalfPrecision: true) {
    source,
    results in
    Op(
        "vector",
        "BitCast",
        [.tag, .sourceVector],
        .vector,
        results,
        section: .typeConversion,
        vectorLabels: ["bitPattern"],
        source: source,
        targets: TargetBodies(
            sve2_128: sourced(source) { source, result in
                let reinterpreted = sveReinterpretedSplat("a", from: source, to: result)
                return vectorResult(sveResult(reinterpreted, for: result), for: result)
            }
        ),
        portable: sourced(source) { _, result in vectorResult("a", for: result) }
    )
}

func intToFloatConvertible(_ source: Element, _ result: Element) -> Bool {
    source.category != .float && result.category == .float && source.bits == result.bits
}

func intToFloatConverted(for result: Element) -> String {
    "__builtin_convertvector(a, \(result.cVector))"
}

func intToFloatEmulated(
    from source: Element,
    to result: Element,
    unfused: Bool = false
) -> (declarations: String, expression: String)? {
    if source.bits == 64 {
        let declarations = [
            floatTypedefs(bits: 64, lanes: source.laneCount, includingSigned: false),
            vectorTypedef("words_vector", lane: "uint32_t", bits: 32, lanes: source.laneCount * 2),
        ].joined(separator: "\n")
        return (declarations, x86ConvertingToFloat64("a", source))
    }
    guard source.category == .unsignedInteger else { return nil }
    let signed = signedElement(of: source).at(width: source.width).cVector
    let lanes = source.laneCount
    let low = splat("0xFFFF", as: source.cVector, lanes: lanes)
    let scale = splat("65536.0f", as: result.cVector, lanes: lanes)
    let converted = { (operand: String) in
        "__builtin_convertvector((\(signed))(\(operand)), \(result.cVector))"
    }
    guard unfused else {
        return ("", "(\(converted("a >> 16")) * \(scale) + \(converted("a & \(low)")))")
    }
    let declarations = """
        const \(result.cVector) lowest = \(converted("a & \(low)"));
        const \(result.cVector) highest = \(converted("a >> 16"));
        """
    return (declarations, "highest * \(scale) + lowest")
}

func intToFloatEmulatedBody(
    from source: Element,
    masked: Bool,
    unfused: Bool = false
) -> (Element) -> String? {
    { result in
        let source = source.at(width: result.width)
        guard let emulated = intToFloatEmulated(from: source, to: result, unfused: unfused) else {
            return nil
        }
        let finished =
            masked
            ? maskedSelecting(emulated.expression, merging: false, for: result)
            : vectorResult(emulated.expression, for: result)
        return [emulated.declarations, unfused ? withoutContraction(finished) : finished]
            .filter { !$0.isEmpty }.joined(separator: "\n")
    }
}

let intToFloatConvertOps = sourcedOps(accepting: intToFloatConvertible) { source, results in
    Op(
        "vector",
        "ConvertTo",
        [.tag, .sourceVector],
        .vector,
        results,
        section: .typeConversion,
        vectorLabels: ["converting"],
        source: source,
        targets: TargetBodies(
            avx2: intToFloatEmulatedBody(from: source, masked: false),
            sse4: intToFloatEmulatedBody(from: source, masked: false),
            sse2: intToFloatEmulatedBody(from: source, masked: false, unfused: source.bits == 32)
        ),
        portable: sourced(source) { _, result in
            vectorResult(intToFloatConverted(for: result), for: result)
        }
    )
}

let intToFloatMaskedConvertOps = sourcedOps(accepting: intToFloatConvertible) { source, results in
    var targets = maskedTargets({ intToFloatConverted(for: $0) }, merging: false)
    targets.avx2 = intToFloatEmulatedBody(from: source, masked: true)
    targets.sse4 = intToFloatEmulatedBody(from: source, masked: true)
    targets.sse2 = intToFloatEmulatedBody(from: source, masked: true, unfused: source.bits == 32)
    return Op(
        "vector",
        "MaskedConvertTo",
        [.whereMask, .tag, .sourceVector],
        .vector,
        results,
        section: .typeConversion,
        vectorLabels: ["converting"],
        source: source,
        targets: targets,
        portable: sourced(source) { _, result in
            maskedSelecting(intToFloatConverted(for: result), merging: false, for: result)
        }
    )
}

let convertFromIntegerOps: [Op] = intToFloatConvertOps + intToFloatMaskedConvertOps

enum FloatToIntConversion {
    case saturating
    case inRange
    case nearestEven
    case up
    case down

    var neonRounding: String {
        switch self {
        case .saturating, .inRange: return ""
        case .nearestEven: return "n"
        case .up: return "p"
        case .down: return "m"
        }
    }
}

func floatToIntPairs(_ source: Element, _ result: Element) -> Bool {
    source.category == .float && result.category != .float && source.bits == result.bits
}

func floatToSignedIntPairs(_ source: Element, _ result: Element) -> Bool {
    floatToIntPairs(source, result) && result.category == .signedInteger
}

func floatToIntOutOfRangeExponent(from source: Element, to result: Element) -> Int {
    let bias = source.bits == 32 ? 127 : 1023
    return bias + result.bits - (result.category == .signedInteger ? 1 : 0)
}

func floatToIntOverflowLimit(of source: Element) -> String {
    source.bits == 32 ? "2147483648.0f" : "9223372036854775808.0"
}

func floatToIntTruncatedLane(
    inRangeOnly: Bool,
    from source: Element,
    to result: Element
) -> String {
    let compared =
        result.category == .signedInteger ? "\(scalarAbsolute(of: source))(value)" : "value"
    let bits = "__builtin_bit_cast(\(source.cUnsignedLane), \(compared))"
    let threshold = floatToIntOutOfRangeExponent(from: source, to: result)
    let lowest = lowestValue(of: result)
    let saturated = "(__builtin_signbit(value) ? \(lowest) : \(highestValue(of: result)))"
    let outOfRange = inRangeOnly ? lowest : saturated
    return
        "(\(bits) >> \(mantissaBits(of: source))) < \(threshold) ? (\(result.cType))value : \(outOfRange)"
}

func floatToIntNearestLane(from source: Element, to result: Element) -> String {
    let suffix = source.bits == 32 ? "f" : ""
    let half = "0.5\(suffix)"
    let absolute = scalarAbsolute(of: source)
    let (lowest, highest) = (lowestValue(of: result), highestValue(of: result))
    return """
        const \(source.cType) magnitude = \(absolute)(value);
        const bool negative = __builtin_signbit(value);
        if (!(magnitude < \(mantissaEnd(of: source)))) {
          converted[i] = !(magnitude < \(floatToIntOverflowLimit(of: source))) ? (negative ? \(lowest) : \(highest)) : (\(result.cType))value;
          continue;
        }
        const \(source.cType) bias = value < 0.0\(suffix) ? -\(half) : \(half);
        const \(result.cType) rounded = (\(result.cType))(value + bias);
        const \(source.cType) distance = \(absolute)((\(source.cType))rounded - value);
        converted[i] = (rounded & 1) && distance == \(half) ? rounded - (negative ? -1 : 1) : rounded;
        """
}

func floatToIntDirectedLane(
    towardPositive: Bool,
    from source: Element,
    to result: Element
) -> String {
    let (comparison, step) = towardPositive ? ("<", "+ 1") : (">", "- 1")
    let truncated = floatToIntTruncatedLane(inRangeOnly: false, from: source, to: result)
    let magnitude = "\(scalarAbsolute(of: source))(value) < \(mantissaEnd(of: source))"
    return """
        const \(result.cType) truncated = \(truncated);
        const bool inexact = \(magnitude) && (\(source.cType))truncated \(comparison) value;
        converted[i] = inexact ? truncated \(step) : truncated;
        """
}

func floatToIntPortable(
    _ conversion: FloatToIntConversion,
    from source: Element,
    to result: Element,
    maskingLanes: Bool = false
) -> String {
    let lane: String
    switch conversion {
    case .saturating, .inRange:
        let truncated = floatToIntTruncatedLane(
            inRangeOnly: conversion == .inRange,
            from: source,
            to: result
        )
        lane = "converted[i] = \(maskingLanes ? "(\(truncated)) & mask[i]" : truncated);"
    case .nearestEven:
        lane = floatToIntNearestLane(from: source, to: result)
    case .up, .down:
        lane = floatToIntDirectedLane(towardPositive: conversion == .up, from: source, to: result)
    }
    return """
        \(result.cVector) converted;
        for (size_t i = 0; i < \(result.laneCount); ++i) {
          const \(source.cType) value = a[i];
        \(indented(lane))
        }
        """
}

func floatToIntNeon(_ conversion: FloatToIntConversion, to result: Element) -> String {
    let sign = result.category == .signedInteger ? "s" : "u"
    let builtin = "__builtin_neon_vcvt\(conversion.neonRounding)q_\(sign)\(result.bits)_v"
    let operand = "(\(neonVector("i8")))a"
    let code = neonTypeCode(of: result)
    return "const \(result.cVector) converted = (\(result.cVector))\(builtin)(\(operand), \(code));"
}

func floatToIntReturning(masked: Bool, avx3: Bool = false, for result: Element) -> String {
    guard masked else { return vectorResult("converted", for: result) }
    guard avx3 else { return maskedSelecting("converted", merging: false, for: result) }
    return x86Avx3ZeroMasked("converted", for: result)
}

func floatToIntX86Converting(
    _ name: String,
    _ operand: String,
    to result: Element
) -> String {
    let source = "(\(x86Vector(name.contains("ps") ? "f32" : "f64")))\(operand)"
    guard result.width == 64 else {
        let call = "__builtin_ia32_\(name)\(x86UnsuffixedBits(result.width))(\(source))"
        return "(\(result.cVector))\(call)"
    }
    let mask = name.contains("ps") ? "(unsigned short)-1" : "(unsigned char)-1"
    let zero = compoundLiteral(result.cVector, ["0"])
    let arguments = [source, zero, mask, "\(x86CurrentRounding)"].joined(separator: ", ")
    return "(\(result.cVector))__builtin_ia32_\(name)512_mask(\(arguments))"
}

func floatToIntX86Scalars(
    _ name: String,
    of operand: String,
    named converted: String,
    to result: Element
) -> String {
    let float = x86Vector("f64")
    let upper = "__builtin_shufflevector(\(operand), \(operand), 1, 1)"
    let lanes = [operand, upper].map { "__builtin_ia32_\(name)((\(float))\($0))" }
    return "const \(result.cVector) \(converted) = \(compoundLiteral(result.cVector, lanes));"
}

func floatToIntX86NearestEmulation(
    named name: String,
    of operand: String,
    from source: Element,
    to result: Element
) -> [String] {
    let lanes = source.laneCount
    func constant(_ value: String) -> String { splat(value, as: "unsigned_vector", lanes: lanes) }
    let end = splat(mantissaEnd(of: source), as: "float_vector", lanes: lanes)
    let lowest = splat("-9223372036854775808.0", as: "float_vector", lanes: lanes)
    let raised = x86Builtin(
        "maxpd256",
        ["\(name)Float", lowest],
        as: "f64",
        returning: "float_vector"
    )
    let magnitude = x86VariableShift(
        "\(name)Mantissa",
        by: "\(name)Shift",
        left: true,
        width: result.width
    )
    return [
        "const float_vector \(name)Float = \(operand);",
        "const signed_vector \(name)Small = (signed_vector)(__builtin_elementwise_abs(\(name)Float) < \(end));",
        "const float_vector \(name)Raised = \(raised);",
        "const unsigned_vector \(name)Signs = (unsigned_vector)\(name)Float & \(constant("0x8000000000000000ull"));",
        "const float_vector \(name)Offset = (float_vector)((unsigned_vector)\(name)Small & ((unsigned_vector)\(end) | \(name)Signs));",
        "const float_vector \(name)Adjusted = \(name)Raised + \(name)Offset;",
        "const unsigned_vector \(name)Bits = (unsigned_vector)\(name)Adjusted;",
        "const unsigned_vector \(name)Exponent = (\(name)Bits >> 52) & \(constant("0x7FF"));",
        "const unsigned_vector \(name)Shift = \(name)Exponent - \(constant("1075"));",
        "const unsigned_vector \(name)Mantissa = (\(name)Bits & \(constant("0xFFFFFFFFFFFFFull"))) | (~(unsigned_vector)\(name)Small & \(constant("0x10000000000000ull")));",
        "const unsigned_vector \(name)Magnitude = \(magnitude);",
        "const unsigned_vector \(name)Negative = (unsigned_vector)((signed_vector)\(name)Float < zero);",
        "const \(result.cVector) \(name) = (\(result.cVector))((\(name)Magnitude ^ \(name)Negative) - \(name)Negative);",
    ]
}

func floatToIntX86InRange(
    named name: String,
    rounding: Bool,
    of operand: String,
    level: X86Level,
    from source: Element,
    to result: Element
) -> [String] {
    let cvt = rounding ? "cvt" : "cvtt"
    if source.bits == 32 || level >= .avx3 {
        let builtin = floatToIntX86Converting(
            source.bits == 32 ? "\(cvt)ps2dq" : "\(cvt)pd2qq",
            operand,
            to: result
        )
        return ["const \(result.cVector) \(name) = \(builtin);"]
    }
    guard level == .avx2 else {
        return [floatToIntX86Scalars("\(cvt)sd2si64", of: operand, named: name, to: result)]
    }
    guard !rounding else {
        return floatToIntX86NearestEmulation(
            named: name,
            of: operand,
            from: source,
            to: result
        )
    }
    return [
        x86EmulatedConversion(
            named: name,
            of: operand,
            as: result.cVector,
            to: result,
            width: result.width
        )
    ]
}

func floatToIntX86Signed(
    _ conversion: FloatToIntConversion,
    named name: String = "converted",
    of operand: String = "a",
    level: X86Level,
    from source: Element,
    to result: Element
) -> [String] {
    let lanes = source.laneCount
    if conversion == .saturating && source.bits == 64 && level == .avx2 {
        let inRange = x86EmulatedConversion(
            named: "inRange",
            of: operand,
            as: result.cVector,
            to: result,
            width: result.width
        )
        let limit = splat(highestValue(of: result), as: "unsigned_vector", lanes: lanes)
        let threshold = splat("1086", as: "signed_vector", lanes: lanes)
        let selected = selectedLanes("inRangeLanes", "inRange", "saturated", as: result.cVector)
        return [
            inRange,
            "const signed_vector inRangeLanes = (signed_vector)((signed_vector)inRangeExponent < \(threshold));",
            "const unsigned_vector saturated = \(limit) - inRangeSigns;",
            "const \(result.cVector) \(name) = \(selected);",
        ]
    }
    guard conversion != .inRange else {
        return floatToIntX86InRange(
            named: name,
            rounding: false,
            of: operand,
            level: level,
            from: source,
            to: result
        )
    }
    let converting = floatToIntX86InRange(
        named: "truncated",
        rounding: conversion == .nearestEven,
        of: operand,
        level: level,
        from: source,
        to: result
    )
    let limit = splat(floatToIntOverflowLimit(of: source), as: "float_vector", lanes: lanes)
    guard level >= .avx3 else {
        let maximum = splat(highestValue(of: result), as: result.cVector, lanes: lanes)
        let isEmulated = source.bits == 64 && level == .avx2
        let selected =
            isEmulated
            ? x86Builtin(
                "pblendvb256",
                ["truncated", maximum, "overflow"],
                as: "i8",
                returning: result.cVector
            ) : "(\(result.cVector))(truncated ^ overflow)"
        let overflow = "const signed_vector overflow = (signed_vector)(\(operand) >= \(limit));"
        let selection = "const \(result.cVector) \(name) = \(selected);"
        return isEmulated
            ? [overflow] + converting + [selection] : converting + [overflow, selection]
    }
    let float = x86Vector(source.cSuffix)
    let bitsType = x86MaskType(lanes: lanes)
    let overflow = x86Builtin(
        "cmp\(source.bits == 32 ? "ps" : "pd")512_mask",
        [
            (value: operand, type: float), (value: limit, type: float),
            (value: "29", type: "int"), (value: "-1", type: bitsType),
            (value: "\(x86CurrentRounding)", type: "int"),
        ],
        returning: bitsType
    )
    let maximum = splat(highestValue(of: result), as: result.cVector, lanes: lanes)
    let selected = x86Avx3Select("overflow", maximum, "truncated", for: result)
    return ["const \(bitsType) overflow = \(overflow);"] + converting
        + ["const \(result.cVector) \(name) = \(selected);"]
}

func floatToIntX86NonNegative(
    of operand: String = "a",
    level: X86Level,
    from source: Element
) -> [String] {
    if source.bits == 64 && level == .sse4 {
        let zeroed = x86Builtin(
            "blendvpd",
            [operand, compoundLiteral("float_vector", ["0"]), operand],
            as: "f64",
            returning: "float_vector"
        )
        return ["const float_vector nonNegative = \(zeroed);"]
    }
    let signs: [String]
    if source.bits == 64 && level < .sse4 {
        let duplicated = (0..<source.laneCount).flatMap { [2 * $0 + 1, 2 * $0 + 1] }
        signs = [
            "const words_vector signWords = (words_vector)\(operand) >> 31;",
            "const unsigned_vector negative = (unsigned_vector)__builtin_shufflevector(signWords, signWords, \(duplicated.map(String.init).joined(separator: ", ")));",
        ]
    } else {
        signs = [
            "const unsigned_vector negative = (unsigned_vector)((signed_vector)\(operand) >> \(source.bits - 1));"
        ]
    }
    return signs + [
        "const float_vector nonNegative = (float_vector)((unsigned_vector)\(operand) & ~negative);"
    ]
}

func floatToIntX86Unsigned32(
    _ conversion: FloatToIntConversion,
    level: X86Level,
    from source: Element,
    to result: Element
) -> [String] {
    let lanes = source.laneCount
    let saturating = conversion == .saturating
    let operand = saturating ? "nonNegative" : "a"
    let clamping = saturating ? floatToIntX86NonNegative(level: level, from: source) : []
    guard level < .avx3 else {
        let builtin = floatToIntX86Converting("cvttps2udq", operand, to: result)
        return clamping + ["const \(result.cVector) converted = \(builtin);"]
    }
    func constant(_ value: String) -> String { splat(value, as: "unsigned_vector", lanes: lanes) }
    let truncated = floatToIntX86Converting("cvttps2dq", "scaled", to: result)
    let combined =
        saturating ? "doubled | (unsigned_vector)((signed_vector)difference >> 31)" : "doubled"
    return clamping + [
        "const unsigned_vector bits = (unsigned_vector)\(operand);",
        "const unsigned_vector difference = \(constant("158")) - (bits >> 23);",
        "const unsigned_vector halved = (unsigned_vector)(difference == \(constant("0")));",
        "const float_vector scaled = (float_vector)(bits + (halved << 23));",
        "const unsigned_vector truncated = (unsigned_vector)\(truncated);",
        "const unsigned_vector doubled = truncated + (truncated & halved);",
        "const \(result.cVector) converted = (\(result.cVector))(\(combined));",
    ]
}

func floatToIntX86Unsigned64(
    _ conversion: FloatToIntConversion,
    level: X86Level,
    from source: Element,
    to result: Element
) -> [String] {
    let lanes = source.laneCount
    let saturating = conversion == .saturating
    let operand = saturating ? "nonNegative" : "a"
    let clamping = saturating ? floatToIntX86NonNegative(level: level, from: source) : []
    guard level < .avx3 else {
        let builtin = floatToIntX86Converting("cvttpd2uqq", operand, to: result)
        return clamping + ["const \(result.cVector) converted = \(builtin);"]
    }
    let name = saturating ? "inRange" : "converted"
    let emulated = x86EmulatedConversion(
        named: name,
        of: operand,
        as: result.cVector,
        to: result,
        width: result.width
    )
    guard saturating else { return [emulated] }
    let outOfRange: [String]
    if level >= .sse4 {
        let threshold = splat("1086", as: "signed_vector", lanes: lanes)
        outOfRange = [
            "const unsigned_vector outOfRange = (unsigned_vector)((signed_vector)inRangeExponent > \(threshold));"
        ]
    } else {
        let duplicated = (0..<lanes).flatMap { [2 * $0, 2 * $0] }
        let threshold = splat("1086", as: "words_vector", lanes: 2 * lanes)
        outOfRange = [
            "const words_vector exponentWords = (words_vector)inRangeExponent;",
            "const words_vector duplicatedWords = __builtin_shufflevector(exponentWords, exponentWords, \(duplicated.map(String.init).joined(separator: ", ")));",
            "const unsigned_vector outOfRange = (unsigned_vector)(duplicatedWords > \(threshold));",
        ]
    }
    return clamping + [emulated] + outOfRange + [
        "const \(result.cVector) converted = (\(result.cVector))((unsigned_vector)inRange | outOfRange);"
    ]
}

func floatToIntX86Directed(
    towardPositive: Bool,
    level: X86Level,
    from source: Element,
    to result: Element
) -> [String] {
    guard level < .sse4 else {
        let rounded = "__builtin_elementwise_\(towardPositive ? "ceil" : "floor")(a)"
        return ["const float_vector rounded = \(rounded);"]
            + floatToIntX86Signed(
                .saturating,
                of: "rounded",
                level: level,
                from: source,
                to: result
            )
    }
    let lanes = source.laneCount
    let (comparison, operation) = towardPositive ? ("<", "-") : (">", "+")
    let end = splat(mantissaEnd(of: source), as: "float_vector", lanes: lanes)
    return floatToIntX86Signed(
        .saturating,
        named: "integer",
        level: level,
        from: source,
        to: result
    ) + [
        "const float_vector integerFloat = __builtin_convertvector(integer, float_vector);",
        "const signed_vector adjustment = (signed_vector)((__builtin_elementwise_abs(a) < \(end)) & (integerFloat \(comparison) a));",
        "const \(result.cVector) converted = (\(result.cVector))((unsigned_vector)integer \(operation) (unsigned_vector)adjustment);",
    ]
}

func floatToIntX86Statements(
    _ conversion: FloatToIntConversion,
    level: X86Level,
    from source: Element,
    to result: Element
) -> [String] {
    guard result.category == .signedInteger else {
        return source.bits == 32
            ? floatToIntX86Unsigned32(conversion, level: level, from: source, to: result)
            : floatToIntX86Unsigned64(conversion, level: level, from: source, to: result)
    }
    switch conversion {
    case .up, .down:
        return floatToIntX86Directed(
            towardPositive: conversion == .up,
            level: level,
            from: source,
            to: result
        )
    default:
        return floatToIntX86Signed(conversion, level: level, from: source, to: result)
    }
}

func floatToIntX86(
    _ conversion: FloatToIntConversion,
    level: X86Level,
    masked: Bool,
    from source: Element,
    to result: Element
) -> String {
    let lanes = source.laneCount
    let statements = floatToIntX86Statements(conversion, level: level, from: source, to: result)
    let body =
        (statements + [floatToIntReturning(masked: masked, avx3: level >= .avx3, for: result)])
        .joined(separator: "\n")
    let types = [
        ("float_vector", source.cType, source.bits, lanes),
        ("unsigned_vector", source.cUnsignedLane, source.bits, lanes),
        ("signed_vector", signedElement(of: source).cType, source.bits, lanes),
        ("words_vector", "int32_t", 32, 2 * lanes),
        ("narrow_vector", "uint16_t", 16, 4 * lanes),
    ]
    let declarations = types.filter {
        body.range(of: "\\b\($0.0)\\b", options: .regularExpression) != nil
    }
    .map { vectorTypedef($0.0, lane: $0.1, bits: $0.2, lanes: $0.3) }
    let zero = "const signed_vector zero = \(compoundLiteral("signed_vector", ["0"]));"
    let needsZero = body.range(of: "\\bzero\\b", options: .regularExpression) != nil
    return (declarations + (needsZero ? [zero] : []) + [body]).joined(separator: "\n")
}

func floatToIntOps(
    _ conversion: FloatToIntConversion,
    _ highwayName: String,
    label: String,
    masked: Bool = false,
    tagged: Bool = true,
    accepting: @escaping (Element, Element) -> Bool
) -> [Op] {
    sourcedOps(accepting: accepting) { source, results in
        func x86(_ level: X86Level) -> (Element) -> String {
            sourced(source) { source, result in
                floatToIntX86(conversion, level: level, masked: masked, from: source, to: result)
            }
        }
        return Op(
            "vector",
            highwayName,
            (masked ? [.whereMask] : []) + (tagged ? [.tag] : []) + [.sourceVector],
            .vector,
            results,
            section: .typeConversion,
            vectorLabels: [label],
            source: source,
            targets: TargetBodies(
                neon: sourced(source) { source, result in
                    let converted = floatToIntNeon(conversion, to: result)
                    return "\(converted)\n\(floatToIntReturning(masked: masked, for: result))"
                },
                avx3: x86(.avx3),
                avx2: x86(.avx2),
                sse4: x86(.sse4),
                sse2: x86(.sse2)
            )
        ) { result in
            let maskingLanes = masked && result.category == .signedInteger
            let converted = floatToIntPortable(
                conversion,
                from: source.at(width: result.width),
                to: result,
                maskingLanes: maskingLanes
            )
            let returning = floatToIntReturning(masked: masked && !maskingLanes, for: result)
            return "\(converted)\n\(returning)"
        }
    }
}

let convertToIntegerOps: [Op] =
    floatToIntOps(
        .saturating,
        "ConvertTo",
        label: "converting",
        accepting: floatToIntPairs
    )
    + floatToIntOps(
        .inRange,
        "ConvertInRangeTo",
        label: "convertingInRange",
        accepting: floatToIntPairs
    )
    + floatToIntOps(
        .saturating,
        "MaskedConvertTo",
        label: "converting",
        masked: true,
        accepting: floatToIntPairs
    )
    + floatToIntOps(
        .nearestEven,
        "NearestInt",
        label: "roundingToNearestOrEven",
        tagged: false,
        accepting: floatToSignedIntPairs
    )
    + floatToIntOps(
        .up,
        "CeilInt",
        label: "roundingUp",
        tagged: false,
        accepting: floatToSignedIntPairs
    )
    + floatToIntOps(
        .down,
        "FloorInt",
        label: "roundingDown",
        tagged: false,
        accepting: floatToSignedIntPairs
    )

enum PromoteLowerUpperHalf: String {
    case lower
    case upper
}

func promoteLowerUpperAccepts(_ source: Element, _ result: Element) -> Bool {
    promotes(source, to: result) && result.bits == 2 * source.bits
}

func promoteLowerUpperAcceptsInRange(_ source: Element, _ result: Element) -> Bool {
    promoteLowerUpperAccepts(source, result) && convertsFloatToInteger(from: source, to: result)
}

func promoteLowerUpperIndices(_ half: PromoteLowerUpperHalf, of source: Element) -> [Int] {
    let lanes = source.laneCount / 2
    let first = half == .lower ? 0 : lanes
    return Array(first..<first + lanes)
}

func promoteNarrowing(of lanes: [Int], from source: Element, to result: Element) -> String {
    """
    \(vectorTypedef("narrow_vector", of: source, lanes: result.laneCount))
    const narrow_vector v = __builtin_shufflevector(a, a, \(laneIndices(lanes)));
    """
}

func promotePortable(
    of lanes: [Int],
    inRange: Bool,
    from source: Element,
    to result: Element
) -> String {
    let narrowing = promoteNarrowing(of: lanes, from: source, to: result)
    guard convertsFloatToInteger(from: source, to: result) else {
        return """
            \(narrowing)
            \(vectorResult("__builtin_convertvector(v, \(result.cVector))", for: result))
            """
    }
    guard inRange else {
        return "\(narrowing)\n\(portableSaturatingConversion(from: source, to: result))"
    }
    let conversion = portableInRangeConversion(
        named: "result",
        of: "v",
        floatBits: source.bits,
        to: result,
        as: result.cVector,
        lanes: result.laneCount
    )
    return """
        \(narrowing)
        \(floatTypedefs(bits: source.bits, lanes: result.laneCount))
        \(conversion)
        \(vectorResult("result", for: result))
        """
}

func promoteNeon(of lanes: [Int], from source: Element, to result: Element) -> String {
    let narrowing = promoteNarrowing(of: lanes, from: source, to: result)
    return """
        \(narrowing)
        \(vectorResult(neonWideningConversion("v", from: source, to: result), for: result))
        """
}

func promoteLowerUpperSve(
    _ half: PromoteLowerUpperHalf,
    from source: Element,
    to result: Element
) -> String? {
    guard source.category != .float, result.category != .float else { return nil }
    let unpacked = source.category == .signedInteger ? result : unsignedElement(of: result)
    let name = half == .lower ? "unpklo" : "unpkhi"
    let call = sveBuiltin(name, [sveSplatOperand("a", for: source)], for: unpacked)
    return vectorResult(
        sveResult(sveReinterpreted(call, from: unpacked, to: result), for: result),
        for: result
    )
}

func promoteLowerUpperX86Block(_ half: PromoteLowerUpperHalf, from source: Element) -> String {
    let indices = promoteLowerUpperIndices(half, of: source)
    guard source.width == 16 else {
        return "__builtin_shufflevector(a, a, \(laneIndices(indices)))"
    }
    return half == .lower
        ? "a" : "__builtin_shufflevector(a, a, \(laneIndices(indices + indices)))"
}

func promoteX86InRange(of block: String, to integer: Element) -> String {
    let isSigned = integer.category == .signedInteger
    let floats = floatElement(bits: 32).cBlock
    let words = unsignedElement(bits: 32).cBlock
    let signedWords = signedElement(of: unsignedElement(bits: 32)).cBlock
    let bytes = unsignedElement(bits: 8).cBlock
    let unsigned = "unsigned_vector"
    func promoted(_ source: Element, _ operand: String) -> String {
        let raw = x86RawBlockType(of: source)
        return "(\(unsigned))\(x86PromotionName(from: source, to: integer))((\(raw))\(operand))"
    }
    let exponents = "(\(bytes))(bits >> 23)"
    let bias = "(\(bytes))\(splat("0xFFFFFF9Du", as: words, lanes: 4))"
    let truncation = x86Builtin(
        "cvttps2dq",
        [(value: "adjusted", type: x86Block("f32"))],
        returning: signedWords
    )
    let unsignedSource = unsignedElement(bits: 32)
    let significand = promoted(
        isSigned ? signedElement(of: unsignedSource) : unsignedSource,
        "truncated"
    )
    let shifted = x86VariableShift("significand", by: "counts", left: true, width: integer.width)
    return """
        \(vectorTypedef(unsigned, of: unsignedElement(bits: 64), lanes: integer.laneCount))
        const \(words) bits = (\(words))\(block);
        const \(words) adjustment = (\(words))__builtin_elementwise_sub_sat(\(exponents), \(bias));
        const \(floats) adjusted = (\(floats))(bits - (adjustment << 23));
        const \(signedWords) truncated = \(truncation);
        const \(unsigned) significand = \(significand);
        const \(unsigned) counts = \(promoted(unsignedSource, "adjustment"));
        \(vectorResult(shifted, for: integer))
        """
}

func promoteX86(
    of block: String,
    inRange: Bool,
    from source: Element,
    to result: Element
) -> String {
    guard inRange else {
        let raw = x86RawBlockType(of: source)
        return "return \(x86PromotionName(from: source, to: result))((\(raw))\(block));"
    }
    return promoteX86InRange(of: block, to: result)
}

func promoteAvx3Truncation(of operand: String, to integer: Element) -> String {
    let words = x86Vector("i64")
    let name = "cvttps2\(integer.category == .signedInteger ? "" : "u")qq512_mask"
    return x86Builtin(
        name,
        [
            (value: operand, type: "narrow_vector"),
            (value: compoundLiteral(words, ["0"]), type: words),
            (value: "-1", type: x86MaskType(lanes: integer.laneCount)),
            (value: String(x86CurrentRounding), type: "int"),
        ],
        returning: words
    )
}

func promoteAvx3(
    of lanes: [Int],
    inRange: Bool,
    from source: Element,
    to result: Element
) -> String {
    let narrowing = promoteNarrowing(of: lanes, from: source, to: result)
    guard inRange else {
        return "\(narrowing)\n\(x86Avx3WideningConversion(from: source, to: result))"
    }
    return """
        \(narrowing)
        \(vectorResult(promoteAvx3Truncation(of: "v", to: result), for: result))
        """
}

func promoteLowerUpperFamily(_ half: PromoteLowerUpperHalf, inRange: Bool) -> [Op] {
    let name = uppercasedFirst(half.rawValue)
    let range = inRange ? "InRange" : ""
    return sourcedOps(
        accepting: inRange ? promoteLowerUpperAcceptsInRange : promoteLowerUpperAccepts
    ) { source, results in
        let x86 = sourced(source) { source, result in
            promoteX86(
                of: promoteLowerUpperX86Block(half, from: source),
                inRange: inRange,
                from: source,
                to: result
            )
        }
        return Op(
            "vector",
            "Promote\(range)\(name)To",
            [.tag, .sourceVector],
            .vector,
            results,
            section: .singleVectorPromotion,
            vectorLabels: ["widening\(name)\(range)"],
            source: source,
            targets: TargetBodies(
                neon: sourced(source) { source, result in
                    promoteNeon(
                        of: promoteLowerUpperIndices(half, of: source),
                        from: source,
                        to: result
                    )
                },
                sve2_128: { result in
                    promoteLowerUpperSve(half, from: source.at(width: result.width), to: result)
                },
                avx3: sourced(source) { source, result in
                    promoteAvx3(
                        of: promoteLowerUpperIndices(half, of: source),
                        inRange: inRange,
                        from: source,
                        to: result
                    )
                },
                avx2: x86,
                sse2: x86
            ),
            portable: sourced(source) { source, result in
                promotePortable(
                    of: promoteLowerUpperIndices(half, of: source),
                    inRange: inRange,
                    from: source,
                    to: result
                )
            }
        )
    }
}

let promoteLowerUpperOps: [Op] =
    promoteLowerUpperFamily(.lower, inRange: false)
    + promoteLowerUpperFamily(.upper, inRange: false)
    + promoteLowerUpperFamily(.lower, inRange: true)
    + promoteLowerUpperFamily(.upper, inRange: true)

func promoteEvenOddAccepts(_ source: Element, _ result: Element) -> Bool {
    promotes(source, to: result) && result.bits == 2 * source.bits
}

func promoteEvenOddInRangeAccepts(_ source: Element, _ result: Element) -> Bool {
    convertsFloatToInteger(from: source, to: result) && result.bits == 2 * source.bits
}

func promoteEvenOddKeptLanes(parity: Int, count: Int) -> String {
    let kept = laneIndices((0..<count).map { 2 * $0 + parity })
    return "__builtin_shufflevector(a, a, \(kept))"
}

func promoteEvenOddIntegerLanes(parity: Int, from source: Element, to result: Element) -> String {
    let unsigned = unsignedElement(of: result).at(width: result.width)
    let shift = source.bits
    guard source.category != .signedInteger else {
        let lanes =
            parity == 0
            ? "(\(result.cVector))((\(unsigned.cVector))a << \(shift))" : "(\(result.cVector))a"
        return "\(lanes) >> \(shift)"
    }
    let lanes =
        parity == 0
        ? "(\(unsigned.cVector))a & \(splat(highestValue(of: source), as: unsigned.cVector, lanes: result.laneCount))"
        : "(\(unsigned.cVector))a >> \(shift)"
    return "(\(result.cVector))(\(lanes))"
}

func promoteEvenOddPortable(
    parity: Int,
    inRange: Bool,
    from source: Element,
    to result: Element
)
    -> String
{
    let kept = promoteEvenOddKeptLanes(parity: parity, count: result.laneCount)
    guard source.category == .float || result.category == .float else {
        return vectorResult(
            promoteEvenOddIntegerLanes(parity: parity, from: source, to: result),
            for: result
        )
    }
    guard convertsFloatToInteger(from: source, to: result) else {
        return vectorResult("__builtin_convertvector(\(kept), \(result.cVector))", for: result)
    }
    guard inRange else {
        return """
            \(vectorTypedef("narrow_vector", of: source, lanes: result.laneCount))
            const narrow_vector v = \(kept);
            \(portableSaturatingConversion(from: source, to: result))
            """
    }
    return """
        \(floatTypedefs(bits: source.bits, lanes: result.laneCount))
        const float_vector v = \(kept);
        \(portableInRangeConversion(named: "result", of: "v", floatBits: source.bits, to: result, as: result.cVector, lanes: result.laneCount))
        \(vectorResult("result", for: result))
        """
}

func promoteEvenOddNeon(parity: Int, from source: Element, to result: Element) -> String? {
    guard convertsFloatToInteger(from: source, to: result) else { return nil }
    let kept = promoteEvenOddKeptLanes(parity: parity, count: result.laneCount)
    return vectorResult(neonWideningConversion(kept, from: source, to: result), for: result)
}

func promoteEvenOddX86Promoting(parity: Int, from source: Element, to result: Element) -> String {
    let count = max(result.laneCount, source.blockLaneCount)
    let kept = promoteEvenOddKeptLanes(parity: parity, count: count)
    let block = x86RawBlockType(of: source)
    return "return \(x86PromotionName(from: source, to: result))((\(block))\(kept));"
}

func promoteEvenOddX86InRange(parity: Int, from source: Element, to result: Element) -> String {
    let kept = promoteEvenOddKeptLanes(parity: parity, count: source.blockLaneCount)
    let words = unsignedElement(bits: 32)
    let integers = result.category == .signedInteger ? signedElement(of: words) : words
    let floats = x86Block("f32")
    let block = x86RawBlockType(of: words)
    let bytes = vectorTypedef("byte_lanes", of: unsignedElement(bits: 8), lanes: 16)
    let unsigned = vectorTypedef(
        "unsigned_vector",
        of: unsignedElement(bits: 64),
        lanes: result.laneCount
    )
    let truncated = x86Builtin(
        "cvttps2dq",
        [(value: "adjusted", type: floats)],
        returning: x86Block("i32")
    )
    let decrement = splat("0xFFFFFF9Du", as: words.cBlock, lanes: 4)
    let counts = "\(x86PromotionName(from: words, to: result))((\(block))adjustment)"
    let promoted = "\(x86PromotionName(from: integers, to: result))((\(block))converted)"
    let shifted = x86VariableShift("promoted", by: "counts", left: true, width: result.width)
    return """
        \(bytes)
        \(unsigned)
        const \(floats) v = \(kept);
        const \(words.cBlock) bits = (\(words.cBlock))v;
        const \(words.cBlock) adjustment = (\(words.cBlock))__builtin_elementwise_sub_sat((byte_lanes)(bits >> 23), (byte_lanes)\(decrement));
        const \(floats) adjusted = (\(floats))(bits - (adjustment << 23));
        const \(x86Block("i32")) converted = \(truncated);
        const \(result.cRawVector) promoted = \(promoted);
        const \(result.cRawVector) counts = \(counts);
        \(vectorResult(shifted, for: result))
        """
}

func promoteEvenOddX86Avx3Converts(from source: Element, to result: Element) -> Bool {
    (source.category == .float || result.category == .float) && source.bits == 32
}

func promoteEvenOddX86OddTableName(
    inRange: Bool,
    from source: Element,
    to result: Element
) -> String {
    let range = inRange ? "in_range_" : ""
    return "cvectorization_ops_x86_promote_\(range)odd_table_\(source.cSuffix)_to_\(result.cSuffix)"
}

func promoteEvenOddX86OddTable(
    inRange: Bool,
    from source: Element,
    to result: Element
) -> String {
    let indices = (0..<16).map { String(2 * $0 + 1) }.joined(separator: ", ")
    return cFunction(
        returns: "const int*",
        name: promoteEvenOddX86OddTableName(inRange: inRange, from: source, to: result),
        parameters: [],
        body: """
            static const int table[16] __attribute__((aligned(64))) = {\(indices)};
            return table;
            """,
        specifiers: "__attribute__((visibility(\"hidden\"))) CVECTORIZATION_OPS_INLINE"
    )
}

func promoteEvenOddX86Avx3OddLanes(
    inRange: Bool,
    from source: Element,
    to result: Element
) -> String {
    let indices = x86Vector("i32")
    let table = promoteEvenOddX86OddTableName(inRange: inRange, from: source, to: result)
    let odd = x86TwoTableLookup("a", "indices", "a", for: source)
    return """
        \(vectorTypedef("narrow_vector", of: source, lanes: result.laneCount))
        const \(indices) indices = *(const \(indices)*)\(table)();
        const \(source.cVector) odd = \(odd);
        const narrow_vector v = __builtin_shufflevector(odd, odd, \(laneIndices(0..<result.laneCount)));
        """
}

func promoteEvenOddX86Avx3Lanes(
    parity: Int,
    inRange: Bool,
    from source: Element,
    to result: Element
) -> String {
    guard parity == 0 else {
        return promoteEvenOddX86Avx3OddLanes(inRange: inRange, from: source, to: result)
    }
    let words = unsignedElement(bits: 64).at(width: result.width)
    let narrow = unsignedElement(bits: 32)
    return """
        \(vectorTypedef("narrow_vector", of: source, lanes: result.laneCount))
        \(vectorTypedef("narrow_lanes", of: narrow, lanes: result.laneCount))
        const narrow_vector v = (narrow_vector)__builtin_convertvector((\(words.cVector))a, narrow_lanes);
        """
}

func promoteEvenOddX86Avx3(
    parity: Int,
    inRange: Bool,
    from source: Element,
    to result: Element
)
    -> String
{
    let gathered = promoteEvenOddX86Avx3Lanes(
        parity: parity,
        inRange: inRange,
        from: source,
        to: result
    )
    guard inRange else {
        return "\(gathered)\n\(x86Avx3WideningConversion(from: source, to: result))"
    }
    let name = "cvttps2\(result.category == .signedInteger ? "" : "u")qq512_mask"
    let words = x86Vector("i64")
    let truncated = x86Builtin(
        name,
        [
            (value: "v", type: "narrow_vector"),
            (value: compoundLiteral(words, ["0"]), type: words),
            (value: "-1", type: x86MaskType(lanes: result.laneCount)),
            (value: String(x86CurrentRounding), type: "int"),
        ],
        returning: words
    )
    return "\(gathered)\n\(vectorResult(truncated, for: result))"
}

func promoteEvenOddSveIntegers(parity: Int, from source: Element, to result: Element) -> String {
    let extended =
        source.category == .signedInteger
        ? result : unsignedElement(of: result).at(width: result.width)
    let operand = sveReinterpreted(
        sveSplatOperand("a", for: source),
        from: source,
        to: extended
    )
    let call: String
    if parity == 0 {
        let letter = ["b", "h", "w"][source.bits.trailingZeroBitCount - 3]
        call = sveBuiltin(
            "ext\(letter)",
            [sveAllLanes(of: extended), operand],
            for: extended,
            predication: "x"
        )
    } else {
        let shift = source.category == .signedInteger ? "asr" : "lsr"
        call = sveBuiltin(
            "\(shift)_n",
            [sveAllLanes(of: extended), operand, "\(source.bits)"],
            for: extended,
            predication: "x"
        )
    }
    return vectorResult("(\(result.cVector))\(sveResult(call, for: extended))", for: result)
}

func promoteEvenOddSveConverting(parity: Int, from source: Element, to result: Element) -> String {
    let converted = sveBuiltin(
        "cvt_\(sveSuffix(of: result))",
        [
            sveAllLanes(of: source),
            parity == 0 ? "v" : sveBuiltin("trn2", ["v", "v"], for: source),
        ],
        for: source,
        predication: "x"
    )
    return """
        const \(sveType(of: source)) v = \(sveSplatOperand("a", for: source));
        \(vectorResult(sveResult(converted, for: result), for: result))
        """
}

func promoteEvenOddSve(parity: Int, from source: Element, to result: Element) -> String? {
    switch (source.category, result.category) {
    case (.float, .float): return nil
    case (.float, _), (_, .float):
        return promoteEvenOddSveConverting(parity: parity, from: source, to: result)
    default:
        return promoteEvenOddSveIntegers(parity: parity, from: source, to: result)
    }
}

func promoteEvenOddX86Avx2SignedOdd(from source: Element, to result: Element) -> String {
    let unsigned = unsignedElement(of: result).at(width: result.width).cVector
    let signs = splat("0xFFFFFFFF00000000ull", as: unsigned, lanes: result.laneCount)
    let widened = "((\(unsigned))wide >> 32) | ((\(unsigned))(wide >> 31) & \(signs))"
    return """
        const \(result.cVector) wide = (\(result.cVector))a;
        \(vectorResult(widened, for: result))
        """
}

func promoteEvenOddX86(
    parity: Int,
    inRange: Bool,
    level: X86Level,
    from source: Element,
    to result: Element
) -> String? {
    if level >= .avx3 {
        guard promoteEvenOddX86Avx3Converts(from: source, to: result) else { return nil }
        return promoteEvenOddX86Avx3(parity: parity, inRange: inRange, from: source, to: result)
    }
    if convertsFloatToInteger(from: source, to: result) {
        return inRange
            ? promoteEvenOddX86InRange(parity: parity, from: source, to: result)
            : promoteEvenOddX86Promoting(parity: parity, from: source, to: result)
    }
    if level == .avx2, parity == 1, source.category == .signedInteger, source.bits == 32,
        result.category == .signedInteger
    {
        return promoteEvenOddX86Avx2SignedOdd(from: source, to: result)
    }
    guard level < .avx2, source.category == .signedInteger, source.bits == 32,
        result.category != .float
    else { return nil }
    return promoteEvenOddX86Promoting(parity: parity, from: source, to: result)
}

func promoteEvenOddFamily(
    _ highwayName: String,
    label: String,
    parity: Int,
    inRange: Bool
) -> [Op] {
    let accepts = inRange ? promoteEvenOddInRangeAccepts : promoteEvenOddAccepts
    return sourcedOps(accepting: accepts) { source, results in
        func x86(_ level: X86Level) -> (Element) -> String? {
            sourced(source) { source, result -> String? in
                promoteEvenOddX86(
                    parity: parity,
                    inRange: inRange,
                    level: level,
                    from: source,
                    to: result
                )
            }
        }
        return Op(
            "vector",
            highwayName,
            [.tag, .sourceVector],
            .vector,
            results,
            section: .singleVectorPromotion,
            vectorLabels: [label],
            source: source,
            targets: TargetBodies(
                neon: sourced(source) { source, result -> String? in
                    promoteEvenOddNeon(parity: parity, from: source, to: result)
                },
                sve2_128: sourced(source) { source, result -> String? in
                    promoteEvenOddSve(parity: parity, from: source, to: result)
                },
                avx3: x86(.avx3),
                avx2: x86(.avx2),
                sse2: x86(.sse2)
            ),
            helpers: TargetBodies(
                avx3: { result in
                    parity == 1 && promoteEvenOddX86Avx3Converts(from: source, to: result)
                        ? promoteEvenOddX86OddTable(inRange: inRange, from: source, to: result)
                        : nil
                }
            ),
            portable: sourced(source) { source, result in
                promoteEvenOddPortable(
                    parity: parity,
                    inRange: inRange,
                    from: source,
                    to: result
                )
            }
        )
    }
}

let promoteEvenOddOps: [Op] =
    promoteEvenOddFamily(
        "PromoteEvenTo",
        label: "wideningEven",
        parity: 0,
        inRange: false
    )
    + promoteEvenOddFamily(
        "PromoteOddTo",
        label: "wideningOdd",
        parity: 1,
        inRange: false
    )
    + promoteEvenOddFamily(
        "PromoteInRangeEvenTo",
        label: "wideningEvenInRange",
        parity: 0,
        inRange: true
    )
    + promoteEvenOddFamily(
        "PromoteInRangeOddTo",
        label: "wideningOddInRange",
        parity: 1,
        inRange: true
    )

func zipWidens(_ source: Element, _ result: Element) -> Bool {
    source.category == result.category && result.bits == 2 * source.bits
}

func zipInterleaved(upper: Bool, from source: Element, to result: Element) -> String {
    let indices = unpackIndices(
        lanes: source.blockLaneCount,
        upper: upper,
        blocks: source.width / 16
    )
    return vectorResult(
        "__builtin_shufflevector(a, b, \(laneIndices(indices)))",
        for: result
    )
}

func zipSveInterleaved(_ name: String, from source: Element, to result: Element) -> String {
    let operands = ["a", "b"].map { sveSplatOperand($0, for: source) }
    return vectorResult(
        sveResult(sveBuiltin(name, operands, for: source), for: source),
        for: result
    )
}

func zipOp(
    _ swiftName: String,
    _ highwayName: String,
    upper: Bool
) -> [Op] {
    sourcedOps(accepting: zipWidens) { source, results in
        Op(
            swiftName,
            highwayName,
            [.tag, .sourceVector, .sourceVector],
            .vector,
            results,
            section: .zip,
            source: source,
            targets: TargetBodies(
                sve2_128: sourced(source) { source, result in
                    zipSveInterleaved(upper ? "zip2" : "zip1", from: source, to: result)
                }
            ),
            portable: sourced(source) { source, result in
                zipInterleaved(upper: upper, from: source, to: result)
            }
        )
    }
}

let zipOps: [Op] =
    zipOp("zippingLower", "ZipLower", upper: false)
    + zipOp("zippingUpper", "ZipUpper", upper: true)

func halvesOfWidth(_ source: Element, _ result: Element) -> Bool {
    source.bits == 2 * result.bits
}

func demoteIntegers(_ source: Element, _ result: Element) -> Bool {
    source.category != .float && result.category != .float && halvesOfWidth(source, result)
}

func demoteUnsignedIntegers(_ source: Element, _ result: Element) -> Bool {
    source.category == .unsignedInteger && result.category == .unsignedInteger
        && halvesOfWidth(source, result)
}

func demoteSignedToUnsigned(from source: Element, to result: Element) -> Bool {
    source.category == .signedInteger && result.category == .unsignedInteger
}

func demoteUnsignedToUnsigned(from source: Element, to result: Element) -> Bool {
    source.category == .unsignedInteger && result.category == .unsignedInteger
}

func demoteUnsignedToSigned(from source: Element, to result: Element) -> Bool {
    source.category == .unsignedInteger && result.category == .signedInteger
}

enum DemoteShift {
    case plain
    case rounding

    var operation: String {
        switch self {
        case .plain: return "shiftedRight"
        case .rounding: return "roundingShiftedRight"
        }
    }

    var label: String {
        switch self {
        case .plain: return "shiftedRightBy"
        case .rounding: return "roundingShiftedRightBy"
        }
    }
}

struct DemoteKernel {
    var statements: [String] = []
    let value: String

    func body(for result: Element, isMask: Bool = false) -> String {
        let returned = isMask ? maskResult(value, for: result) : vectorResult(value, for: result)
        return (statements + [returned]).joined(separator: "\n")
    }
}

func demoteShiftAmount(of source: Element, _ shift: DemoteShift) -> ImmediateArgument {
    ImmediateArgument(
        name: "bits",
        label: shift.label,
        upperBound: .fixed(source.bits - 1),
        codegenAlternatives: [
            CodegenImmediate(name: "widthDifference", value: { source.bits - $0.bits })
        ],
        message: "Shift amount is negative or at least as many as a source lane has bits"
    )
}

func demoteShifted(
    _ operand: String,
    _ shift: DemoteShift,
    for source: Element,
    by amount: String = "bits"
) -> String {
    let function = cFunctionName(shift.operation, source)
    return "(\(source.cVector))\(function)((\(source.cRawVector))\(operand), \(amount))"
}

func demoteShiftedBody(
    _ shift: DemoteShift?,
    for source: Element,
    _ kernel: (_ first: String, _ second: String) -> String
) -> String {
    guard let shift else { return kernel("a", "b") }
    return """
        const \(source.cVector) shiftedA = \(demoteShifted("a", shift, for: source));
        const \(source.cVector) shiftedB = \(demoteShifted("b", shift, for: source));
        \(kernel("shiftedA", "shiftedB"))
        """
}

func demoteNarrowLanes(_ lane: String, from source: Element) -> String {
    vectorTypedef("narrow_lanes", lane: lane, bits: source.bits / 2, lanes: source.laneCount)
}

func demoteJoined(
    _ lower: String,
    _ upper: String,
    lane: String,
    from source: Element,
    to result: Element,
    isMask: Bool = false
) -> String {
    let indices = laneIndices(0..<result.laneCount)
    let joined = "__builtin_shufflevector(lower, upper, \(indices))"
    return """
        \(demoteNarrowLanes(lane, from: source))
        const narrow_lanes lower = \(lower);
        const narrow_lanes upper = \(upper);
        \(isMask ? maskResult(joined, for: result) : vectorResult(joined, for: result))
        """
}

func demoteSaturated(_ operand: String, from source: Element, to result: Element) -> String {
    var clamped = operand
    if source.category == .signedInteger {
        let lowest = splat(lowestValue(of: result), as: source.cVector, lanes: source.laneCount)
        clamped = "__builtin_elementwise_max(\(clamped), \(lowest))"
    }
    let highest = splat(highestValue(of: result), as: source.cVector, lanes: source.laneCount)
    return
        "__builtin_convertvector(__builtin_elementwise_min(\(clamped), \(highest)), narrow_lanes)"
}

func demotePortable(
    _ first: String,
    _ second: String,
    from source: Element,
    to result: Element
) -> String {
    demoteJoined(
        demoteSaturated(first, from: source, to: result),
        demoteSaturated(second, from: source, to: result),
        lane: result.cType,
        from: source,
        to: result
    )
}

func demoteTruncatedPortable(
    _ first: String,
    _ second: String,
    from source: Element,
    to result: Element
) -> String {
    demoteJoined(
        "__builtin_convertvector(\(first), narrow_lanes)",
        "__builtin_convertvector(\(second), narrow_lanes)",
        lane: result.cType,
        from: source,
        to: result
    )
}

func demoteMasksPortable(from source: Element, to result: Element) -> String {
    let signedSource = signedElement(of: source).at(width: source.width)
    let signedResult = signedElement(of: result).at(width: result.width)
    return demoteJoined(
        demoteSaturated("a", from: signedSource, to: signedResult),
        demoteSaturated("b", from: signedSource, to: signedResult),
        lane: result.cMaskLane,
        from: source,
        to: result,
        isMask: true
    )
}

func demoteEvenLanes(
    _ first: String,
    _ second: String,
    lane: String,
    from source: Element
) -> DemoteKernel {
    let narrow = vectorTypedef(
        "narrow_lanes",
        lane: lane,
        bits: source.bits / 2,
        lanes: 2 * source.laneCount
    )
    let indices = laneIndices(Array(stride(from: 0, to: 4 * source.laneCount, by: 2)))
    return DemoteKernel(
        statements: [narrow],
        value:
            "__builtin_shufflevector((narrow_lanes)\(first), (narrow_lanes)\(second), \(indices))"
    )
}

func demoteClampedToSigned(
    _ operand: String,
    from source: Element,
    to result: Element
) -> String {
    guard demoteUnsignedToSigned(from: source, to: result) else { return operand }
    let unsigned = unsignedElement(of: result).at(width: result.width)
    let highest = splat(highestValue(of: result), as: unsigned.cVector, lanes: unsigned.laneCount)
    return
        "(\(result.cVector))__builtin_elementwise_min((\(unsigned.cVector))\(operand), \(highest))"
}

func demoteNeonNarrowed(_ operand: String, from source: Element, to result: Element) -> String {
    let instruction = demoteSignedToUnsigned(from: source, to: result) ? "vqmovun_v" : "vqmovn_v"
    let code = neonTypeCode(of: result) - 32
    let halves = neonVector("i8x8")
    return "(\(halves))__builtin_neon_\(instruction)((\(neonVector("i8")))\(operand), \(code))"
}

func demoteNeonConcatenated(_ halves: [String], for result: Element) -> String {
    "__builtin_shufflevector(\(halves[0]), \(halves[1]), \(laneIndices(0..<16)))"
}

func demoteNeonKernel(
    _ first: String,
    _ second: String,
    from source: Element,
    to result: Element
) -> DemoteKernel {
    let narrowed = [first, second].map { demoteNeonNarrowed($0, from: source, to: result) }
    let combined = demoteNeonConcatenated(narrowed, for: result)
    return DemoteKernel(value: demoteClampedToSigned(combined, from: source, to: result))
}

func demoteNeonFused(
    _ bits: Int,
    _ shift: DemoteShift,
    from source: Element,
    to result: Element
) -> String {
    let rounding = shift == .rounding ? "r" : ""
    let suffix = demoteSignedToUnsigned(from: source, to: result) ? "un" : "n"
    let code = neonTypeCode(of: result) - 32
    let halves = neonVector("i8x8")
    let narrowed = ["a", "b"].map {
        "(\(halves))__builtin_neon_vq\(rounding)shr\(suffix)_n_v((\(neonVector("i8")))\($0), \(bits), \(code))"
    }
    return vectorResult(demoteNeonConcatenated(narrowed, for: result), for: result)
}

func demoteNeonBody(
    _ shift: DemoteShift?,
    from source: Element,
    to result: Element
) -> String {
    let unfused = demoteShiftedBody(shift, for: source) {
        demoteNeonKernel($0, $1, from: source, to: result).body(for: result)
    }
    guard let shift, !demoteUnsignedToSigned(from: source, to: result) else { return unfused }
    let cases = (1...result.bits).map {
        (amount: $0, body: demoteNeonFused($0, shift, from: source, to: result))
    }
    return "\(constantSwitch(on: "bits", cases))\n\(unfused)"
}

func demoteSveKernel(
    _ first: String,
    _ second: String,
    ordered: Bool,
    from source: Element,
    to result: Element
) -> DemoteKernel {
    let operands = [first, second]
    let combined: String
    if demoteUnsignedToSigned(from: source, to: result) {
        let narrowed = operands.map { operand in
            let arguments = [sveAllLanes(of: source), operand, highestValue(of: result)]
            let clamped = sveBuiltin("min_n", arguments, for: source, predication: "x")
            return sveReinterpreted(clamped, from: source, to: result)
        }
        combined = sveBuiltin(ordered ? "uzp1" : "trn1", narrowed, for: result)
    } else {
        let isSignedToUnsigned = demoteSignedToUnsigned(from: source, to: result)
        let (bottom, top) = isSignedToUnsigned ? ("qxtunb", "qxtunt") : ("qxtnb", "qxtnt")
        let narrowed = operands.map { sveBuiltin(bottom, [$0], for: source) }
        combined =
            ordered
            ? sveBuiltin("uzp1", narrowed, for: result)
            : sveBuiltin(top, [narrowed[0], operands[1]], for: source)
    }
    return DemoteKernel(value: sveResult(combined, for: result))
}

func demoteSveShifted(_ operand: String, _ shift: DemoteShift, for source: Element) -> String {
    let shifted = demoteShifted(sveResult(operand, for: source), shift, for: source)
    return "(\(sveVector(source.cSuffix)))\(shifted)"
}

func demoteSveBody(
    _ shift: DemoteShift?,
    ordered: Bool,
    from source: Element,
    to result: Element
) -> String {
    let operands = ["a", "b"].map { sveSplatOperand($0, for: source) }
    guard let shift else {
        return demoteSveKernel(operands[0], operands[1], ordered: ordered, from: source, to: result)
            .body(for: result)
    }
    let kernel = demoteSveKernel("shiftedA", "shiftedB", ordered: ordered, from: source, to: result)
    return DemoteKernel(
        statements: zip(["shiftedA", "shiftedB"], operands).map { name, operand in
            "const \(sveType(of: source)) \(name) = \(demoteSveShifted(operand, shift, for: source));"
        },
        value: kernel.value
    ).body(for: result)
}

func demoteSveTruncated(from source: Element, to result: Element) -> String {
    let operands = ["a", "b"].map {
        sveReinterpreted(sveSplatOperand($0, for: source), from: source, to: result)
    }
    return vectorResult(
        sveResult(sveBuiltin("uzp1", operands, for: result), for: result),
        for: result
    )
}

func demoteX86PackName(sourceBits: Int, unsigned: Bool) -> String {
    "pack\(unsigned ? "us" : "ss")\(sourceBits == 16 ? "wb" : "dw")"
}

func demoteX86Pack(
    _ first: String,
    _ second: String,
    sourceBits: Int,
    unsigned: Bool,
    width: Int
) -> String {
    x86Packing(
        demoteX86PackName(sourceBits: sourceBits, unsigned: unsigned),
        first,
        second,
        from: "i\(sourceBits)",
        to: "i\(sourceBits / 2)",
        width: width
    )
}

func demoteX86SignedMaximum(_ operand: String, level: X86Level, from source: Element) -> String {
    let limit = source.bits == 16 ? "0x7FFF" : "0x7FFFFFFF"
    let lanes = splat(limit, as: source.cVector, lanes: source.laneCount)
    guard level < .sse4 else { return "__builtin_elementwise_min(\(operand), \(lanes))" }
    let bytes = unsignedElement(bits: 8).at(width: source.width).cVector
    let minimum = "__builtin_elementwise_min((\(bytes))\(operand), (\(bytes))\(lanes))"
    return "(\(source.cVector))\(minimum)"
}

func demoteX86UnsignedWords(
    level: X86Level,
    _ first: String,
    _ second: String,
    from source: Element,
    to result: Element
) -> DemoteKernel {
    let signed = signedElement(of: source).at(width: source.width).cVector
    let unsigned = unsignedElement(of: source).at(width: source.width).cVector
    let words = unsignedElement(of: result).at(width: result.width).cVector
    let bits = x86Vector("i64")
    var statements = X86Statements()
    let operands = [(first, "First"), (second, "Second")].map { operand, name in
        let value = "(\(signed))\(operand)"
        let overflowed =
            source.category == .signedInteger
            ? "\(value) > 0xFFFF" : "(\(signed))((\(unsigned))\(operand) >> 16) > 0"
        let kept =
            source.category == .signedInteger
            ? "~(\(bits))(\(value) >> 31) & (\(bits))\(value)" : "(\(bits))\(operand)"
        return (
            kept: statements.define(bits, "kept\(name)", kept),
            overflowed: statements.define(bits, "overflowed\(name)", "(\(bits))(\(overflowed))")
        )
    }
    guard level == .sse2 else {
        let bytes = unsignedElement(bits: 8).at(width: source.width).cVector
        let clamped = operands.map { "(\(bytes))(\($0.kept) | \($0.overflowed))" }
        let indices: [Int] = (0..<16).map { index in
            16 * (index / 8) + 4 * (index % 8 / 2) + index % 2
        }
        let selected =
            "__builtin_shufflevector(\(clamped[0]), \(clamped[1]), \(laneIndices(indices)))"
        return DemoteKernel(statements: [statements.text], value: "(\(words))\(selected)")
    }
    let extended = operands.map {
        "(((\(signed))((\(unsigned))\($0.kept) << 16) >> 16) | (\(signed))\($0.overflowed))"
    }
    let packed = demoteX86Pack(
        extended[0],
        extended[1],
        sourceBits: 32,
        unsigned: false,
        width: source.width
    )
    return DemoteKernel(statements: [statements.text], value: "(\(words))\(packed)")
}

func demoteX86Packed(
    level: X86Level,
    _ first: String,
    _ second: String,
    from source: Element,
    to result: Element
) -> DemoteKernel {
    let toUnsigned = result.category == .unsignedInteger
    if toUnsigned && source.bits == 32 && level < .sse4 {
        return demoteX86UnsignedWords(level: level, first, second, from: source, to: result)
    }
    func pack(_ first: String, _ second: String) -> String {
        demoteX86Pack(
            first,
            second,
            sourceBits: source.bits,
            unsigned: toUnsigned,
            width: source.width
        )
    }
    switch (source.category, result.category) {
    case (.unsignedInteger, .unsignedInteger):
        let clamped = [first, second].map { demoteX86SignedMaximum($0, level: level, from: source) }
        let statements = [
            "const \(source.cVector) clampedFirst = \(clamped[0]);",
            "const \(source.cVector) clampedSecond = \(clamped[1]);",
        ]
        return DemoteKernel(statements: statements, value: pack("clampedFirst", "clampedSecond"))
    case (.unsignedInteger, _):
        let packed = pack(first, second)
        return DemoteKernel(value: demoteClampedToSigned(packed, from: source, to: result))
    default:
        return DemoteKernel(value: pack(first, second))
    }
}

func demoteX86Positive(
    _ operand: String,
    named name: String,
    level: X86Level,
    into statements: inout X86Statements,
    for source: Element,
    equalFirst: Bool = false
) -> String {
    let unsigned = unsignedElement(of: source).at(width: source.width).cVector
    let signed = signedElement(of: source).at(width: source.width).cVector
    guard level < .sse4 else {
        return statements.define(unsigned, name, "(\(unsigned))((\(signed))\(operand) > 0)")
    }
    let words = signedElement(of: unsignedElement(bits: 32)).at(width: source.width).cVector
    let greater = "(\(unsigned))((\(words))\(operand) > 0)"
    let equal = "((\(unsigned))((\(words))\(operand) == 0) & (0 - \(operand)))"
    let upper: String
    if equalFirst {
        let equalLanes = statements.define(
            unsigned,
            "\(name)Equal",
            "(\(unsigned))((\(words))\(operand) == 0)"
        )
        let greaterLanes = statements.define(unsigned, "\(name)Greater", greater)
        upper = statements.define(
            unsigned,
            "\(name)Upper",
            "(\(equalLanes) & (0 - \(operand))) | \(greaterLanes)"
        )
    } else {
        upper = statements.define(unsigned, "\(name)Upper", "\(greater) | \(equal)")
    }
    return statements.define(
        unsigned,
        name,
        "(\(unsigned))__builtin_shufflevector((\(words))\(upper), (\(words))\(upper), 1, 1, 3, 3)"
    )
}

func demoteX86Saturated64Lane(
    _ operand: String,
    named name: String,
    level: X86Level,
    into statements: inout X86Statements,
    from source: Element,
    to result: Element,
    equalFirst: Bool = false,
    shiftedTwice: String? = nil,
    deferringLimit: Bool = false
) -> String {
    let unsigned = unsignedElement(of: source).at(width: source.width).cVector
    let signed = signedElement(of: source).at(width: source.width).cVector
    let words = signedElement(of: unsignedElement(bits: 32)).at(width: source.width).cVector
    let isSignedResult = result.category == .signedInteger
    let highest = String((1 << (result.bits - 1)) - 1, radix: 16, uppercase: true)
    let limit = splat("0x\(highest)", as: unsigned, lanes: source.laneCount)
    var value = "(\(unsigned))\(operand)"
    var inverted = ""
    if source.category == .signedInteger {
        let sign =
            level < .sse4
            ? "(\(unsigned))__builtin_shufflevector((\(words))\(operand) >> 31, (\(words))\(operand) >> 31, 1, 1, 3, 3)"
            : "(\(unsigned))((\(signed))\(operand) < 0)"
        inverted = statements.define(unsigned, "inverted\(name)", sign)
        value = isSignedResult ? "\(inverted) ^ \(value)" : "\(value) & ~\(inverted)"
        value = statements.define(unsigned, "operand\(name)", value)
    }
    let shifted = statements.define(
        unsigned,
        "shifted\(name)",
        shiftedTwice ?? "\(value) >> \(result.bits - (isSignedResult ? 1 : 0))"
    )
    let big = demoteX86Positive(
        shifted,
        named: "big\(name)",
        level: level,
        into: &statements,
        for: source,
        equalFirst: equalFirst
    )
    var narrowed = "(\(value) | \(big))"
    if isSignedResult && !(deferringLimit && inverted.isEmpty) {
        narrowed = "(\(narrowed) & \(limit))"
    }
    if !inverted.isEmpty && isSignedResult { narrowed = "(\(inverted) ^ \(narrowed))" }
    return statements.define(unsigned, "saturated\(name)", narrowed)
}

func demoteX86Saturated64(
    level: X86Level,
    _ first: String,
    _ second: String,
    deferringLimit defersLimit: Bool = false,
    from source: Element,
    to result: Element
) -> DemoteKernel {
    var statements = X86Statements()
    let saturated = [(first, "First"), (second, "Second")].map { operand, name in
        demoteX86Saturated64Lane(
            operand,
            named: name,
            level: level,
            into: &statements,
            from: source,
            to: result,
            deferringLimit: defersLimit
        )
    }
    let selected = demoteX86Words(saturated[0], saturated[1], width: source.width)
    guard defersLimit else { return DemoteKernel(statements: [statements.text], value: selected) }
    let unsigned = unsignedElement(of: result).at(width: result.width)
    let highest = splat(highestValue(of: result), as: unsigned.cVector, lanes: unsigned.laneCount)
    return DemoteKernel(
        statements: [statements.text],
        value: "(\(unsigned.cVector))\(selected) & \(highest)"
    )
}

func demoteX86Avx3Narrowed64(
    _ first: String,
    _ second: String,
    from source: Element,
    to result: Element
) -> DemoteKernel {
    let quads = x86Vector("i64")
    let zero = compoundLiteral("narrow_vector", ["0"])
    let signedResult = result.category == .signedInteger
    let signedSource = source.category == .signedInteger
    let name = signedResult ? "pmovsqd512_mask" : "pmovusqd512_mask"
    let narrowed = [first, second].map { operand in
        var mask = "(unsigned char)-1"
        if signedSource && !signedResult {
            mask = "__builtin_ia32_knotqi(__builtin_ia32_cvtq2mask512((\(quads))\(operand)))"
        }
        let call = "__builtin_ia32_\(name)((\(quads))\(operand), \(zero), \(mask))"
        return "(narrow_vector)\(call)"
    }
    let combined =
        "__builtin_shufflevector(\(narrowed[0]), \(narrowed[1]), \(laneIndices(0..<16)))"
    return DemoteKernel(
        statements: ["typedef int32_t narrow_vector __attribute__((vector_size(32)));"],
        value: demoteClampedToSigned(combined, from: source, to: result)
    )
}

func demoteX86Words(_ first: String, _ second: String, width: Int) -> String {
    let floats = x86Vector("f32")
    let lanes = width / 4
    let indices = (0..<width / 16).flatMap { block in
        let start = 4 * block
        return [start, start + 2, lanes + start, lanes + start + 2]
    }
    return
        "__builtin_shufflevector((\(floats))\(first), (\(floats))\(second), \(laneIndices(indices)))"
}

func demoteX86OrderTableName(
    _ highwayName: String,
    from source: Element,
    to result: Element
) -> String {
    let name = snakeCased(lowercasedFirstWord(highwayName))
    return "cvectorization_ops_x86_\(name)_table_\(source.cSuffix)_to_\(result.cSuffix)"
}

func demoteX86OrderTable(
    _ highwayName: String,
    from source: Element,
    to result: Element
) -> String? {
    guard source.bits < 64 else { return nil }
    return cFunction(
        returns: "const long long*",
        name: demoteX86OrderTableName(highwayName, from: source, to: result),
        parameters: [],
        body: """
            static const long long table[8] __attribute__((aligned(64))) = {0, 2, 4, 6, 1, 3, 5, 7};
            return table;
            """,
        specifiers: "__attribute__((visibility(\"hidden\"))) CVECTORIZATION_OPS_INLINE"
    )
}

func demoteX86TruncationTable(from source: Element, to result: Element) -> String? {
    guard source.bits == 64 else { return nil }
    let indices = (0..<result.laneCount).map { String(2 * $0) }.joined(separator: ", ")
    return cFunction(
        returns: "const int32_t*",
        name: demoteX86OrderTableName("OrderedTruncate2To", from: source, to: result),
        parameters: [],
        body: """
            static const int32_t table[\(result.laneCount)] __attribute__((aligned(64))) = {\(indices)};
            return table;
            """,
        specifiers: "__attribute__((visibility(\"hidden\"))) CVECTORIZATION_OPS_INLINE"
    )
}

func demoteX86Ordered(
    _ kernel: DemoteKernel,
    level: X86Level,
    from source: Element,
    table: String? = nil
) -> DemoteKernel {
    let quads = x86Vector("i64")
    if level >= .avx3, source.bits < 64, let table {
        let permuted = x86Builtin(
            "permvardi512",
            ["reordered", "indices"],
            as: "i64",
            returning: quads
        )
        return DemoteKernel(
            statements: kernel.statements + [
                "const \(quads) reordered = (\(quads))(\(kernel.value));",
                "const \(quads) indices = *(const \(quads)*)\(table)();",
            ],
            value: permuted
        )
    }
    guard level == .avx2 else { return kernel }
    return DemoteKernel(
        statements: kernel.statements + ["const \(quads) reordered = (\(quads))(\(kernel.value));"],
        value: "__builtin_shufflevector(reordered, reordered, 0, 2, 1, 3)"
    )
}

func demoteX86Truncated(
    level: X86Level,
    from source: Element,
    to result: Element
) -> DemoteKernel? {
    switch (level, source.bits) {
    case (.sse2, 32):
        let signed = signedElement(of: source).at(width: source.width).cVector
        let unsigned = unsignedElement(of: source).at(width: source.width).cVector
        let words = unsignedElement(of: result).at(width: result.width).cVector
        let extended = ["a", "b"].map { "(\(signed))((\(unsigned))\($0) << 16) >> 16" }
        let packed = demoteX86Pack(
            extended[0],
            extended[1],
            sourceBits: 32,
            unsigned: false,
            width: source.width
        )
        return DemoteKernel(value: "(\(words))\(packed)")
    case (.avx3, 64):
        let table = demoteX86OrderTableName("OrderedTruncate2To", from: source, to: result)
        let indices = x86Vector("i32")
        return DemoteKernel(
            statements: ["const \(indices) indices = *(const \(indices)*)\(table)();"],
            value: x86TwoTableLookup("a", "indices", "b", for: result)
        )
    case (.avx2, 64):
        let words = demoteX86Words("a", "b", width: source.width)
        return demoteX86Ordered(DemoteKernel(value: words), level: level, from: source)
    case (.ssse3, 16), (.sse4, 16), (.avx2, _):
        let mask = splat(
            source.bits == 16 ? "0x00FF" : "0xFFFF",
            as: source.cVector,
            lanes: source.laneCount
        )
        let packed = demoteX86Pack(
            "(a & \(mask))",
            "(b & \(mask))",
            sourceBits: source.bits,
            unsigned: true,
            width: source.width
        )
        return demoteX86Ordered(DemoteKernel(value: packed), level: level, from: source)
    default:
        return nil
    }
}

func demoteX86Kernel(
    level: X86Level,
    table: String?,
    _ first: String,
    _ second: String,
    deferringLimit: Bool = false,
    from source: Element,
    to result: Element
) -> DemoteKernel {
    let reordered: DemoteKernel
    if source.bits < 64 {
        reordered = demoteX86Packed(level: level, first, second, from: source, to: result)
    } else if level >= .avx3 {
        reordered = demoteX86Avx3Narrowed64(first, second, from: source, to: result)
    } else {
        reordered = demoteX86Saturated64(
            level: level,
            first,
            second,
            deferringLimit: deferringLimit,
            from: source,
            to: result
        )
    }
    guard let table else { return reordered }
    return demoteX86Ordered(reordered, level: level, from: source, table: table)
}

func demoteX86MaskKernel(
    level: X86Level,
    from source: Element,
    to result: Element
) -> DemoteKernel {
    if level >= .avx3 {
        let narrow = vectorTypedef(
            "narrow_lanes",
            lane: result.cMaskLane,
            bits: result.bits,
            lanes: source.laneCount
        )
        let joined = laneIndices(0..<result.laneCount)
        return DemoteKernel(
            statements: [narrow],
            value:
                "__builtin_shufflevector(__builtin_convertvector(a, narrow_lanes), __builtin_convertvector(b, narrow_lanes), \(joined))"
        )
    }
    let signedSource = signedElement(of: source).at(width: source.width)
    let signedResult = signedElement(of: result).at(width: result.width)
    let saturated = demoteX86Kernel(
        level: level,
        table: nil,
        "a",
        "b",
        from: signedSource,
        to: signedResult
    )
    return demoteX86Ordered(saturated, level: level, from: source)
}

func demoteOrderTable(
    ordered: Bool,
    highwayName: String,
    from source: Element,
    to result: Element
) -> String? {
    ordered ? demoteX86OrderTableName(highwayName, from: source, to: result) : nil
}

func demoteTargets(
    shift: DemoteShift?,
    ordered: Bool,
    highwayName: String,
    from source: Element
) -> TargetBodies<Element> {
    func x86(_ level: X86Level) -> (Element) -> String {
        sourced(source) { source, result in
            let table = demoteOrderTable(
                ordered: ordered,
                highwayName: highwayName,
                from: source,
                to: result
            )
            let defersLimit =
                level == .sse4 && shift == .plain
                && demoteUnsignedToSigned(from: source, to: result)
            return demoteShiftedBody(shift, for: source) {
                demoteX86Kernel(
                    level: level,
                    table: table,
                    $0,
                    $1,
                    deferringLimit: defersLimit,
                    from: source,
                    to: result
                ).body(for: result)
            }
        }
    }
    return TargetBodies(
        neon: sourced(source) { source, result in
            demoteNeonBody(shift, from: source, to: result)
        },
        sve2_128: sourced(source) { source, result in
            demoteSveBody(shift, ordered: ordered, from: source, to: result)
        },
        avx3: x86(.avx3),
        avx2: x86(.avx2),
        sse4: x86(.sse4),
        ssse3: x86(.ssse3),
        sse2: x86(.sse2)
    )
}

func demoteHelpers(
    ordered: Bool,
    highwayName: String,
    from source: Element
) -> TargetBodies<Element> {
    guard ordered else { return TargetBodies() }
    return TargetBodies(
        avx3: { result in
            demoteX86OrderTable(highwayName, from: source.at(width: result.width), to: result)
        }
    )
}

func demoteTwoVectorOps(
    _ highwayName: String,
    label: String,
    ordered: Bool,
    shift: DemoteShift? = nil
) -> [Op] {
    let swiftName = "vector"
    let identifier = shift.map { swiftName + [label, $0.label].map(uppercasedFirst).joined() }
    return sourcedOps(accepting: demoteIntegers) { source, results in
        Op(
            swiftName,
            highwayName,
            [.tag, .sourceVector, .sourceVector] + (shift == nil ? [] : [.immediate]),
            .vector,
            results,
            section: .twoVectorDemotion,
            immediates: shift.map { [demoteShiftAmount(of: source, $0)] } ?? [],
            vectorLabels: [label, "_"],
            source: source,
            identifier: identifier,
            targets: demoteTargets(
                shift: shift,
                ordered: ordered,
                highwayName: highwayName,
                from: source
            ),
            helpers: demoteHelpers(ordered: ordered, highwayName: highwayName, from: source),
            portable: sourced(source) { source, result in
                demoteShiftedBody(shift, for: source) {
                    demotePortable($0, $1, from: source, to: result)
                }
            }
        )
    }
}

let demoteTruncatingOps = sourcedOps(accepting: demoteUnsignedIntegers) { source, results in
    func x86(_ level: X86Level) -> (Element) -> String {
        sourced(source) { source, result in
            let kernel = demoteX86Truncated(level: level, from: source, to: result)
            return (kernel ?? demoteEvenLanes("a", "b", lane: result.cType, from: source))
                .body(for: result)
        }
    }
    let shuffled = sourced(source) { source, result in
        demoteEvenLanes("a", "b", lane: result.cType, from: source).body(for: result)
    }
    return Op(
        "vector",
        "OrderedTruncate2To",
        [.tag, .sourceVector, .sourceVector],
        .vector,
        results,
        section: .twoVectorDemotion,
        vectorLabels: ["truncatingIfNeeded", "_"],
        source: source,
        targets: TargetBodies(
            neon: shuffled,
            sve2_128: sourced(source) { source, result in
                demoteSveTruncated(from: source, to: result)
            },
            avx3: x86(.avx3),
            avx2: x86(.avx2),
            sse4: x86(.sse4),
            ssse3: x86(.ssse3),
            sse2: x86(.sse2)
        ),
        helpers: TargetBodies(
            avx3: { result in
                demoteX86TruncationTable(from: source.at(width: result.width), to: result)
            }
        ),
        portable: sourced(source) { source, result in
            demoteTruncatedPortable("a", "b", from: source, to: result)
        }
    )
}

let demoteMasksOps = sourcedOps(
    accepting: includingFloat16(halvesOfWidth),
    includingHalfPrecision: true
) { source, results in
    let shuffled = sourced(source) { source, result in
        demoteEvenLanes("a", "b", lane: result.cMaskLane, from: source)
            .body(for: result, isMask: true)
    }
    let saturated = sourced(source) { source, result in
        demoteNeonKernel(
            "a",
            "b",
            from: signedElement(of: source).at(width: source.width),
            to: signedElement(of: result).at(width: result.width)
        ).body(for: result, isMask: true)
    }
    func x86(_ level: X86Level) -> (Element) -> String {
        sourced(source) { source, result in
            demoteX86MaskKernel(level: level, from: source, to: result)
                .body(for: result, isMask: true)
        }
    }
    return Op(
        "mask",
        "OrderedDemote2MasksTo",
        [.tag, .sourceTag, .sourceMask, .sourceMask],
        .mask,
        results,
        section: .convertMask,
        maskLabels: ["narrowing", "_"],
        source: source,
        targets: TargetBodies(
            neon: saturated,
            sve2_128: shuffled,
            avx3: x86(.avx3),
            avx2: x86(.avx2),
            sse4: x86(.sse4),
            sse2: x86(.sse2)
        ),
        acceptsNonCanonicalMasks: true,
        portable: sourced(source) { source, result in
            demoteMasksPortable(from: source, to: result)
        }
    )
}

let demoteOps: [Op] =
    demoteTwoVectorOps(
        "OrderedDemote2To",
        label: "clamping",
        ordered: true
    )
    + demoteTwoVectorOps(
        "ReorderDemote2To",
        label: "clampingInAnyOrder",
        ordered: false
    )
    + demoteTwoVectorOps(
        "OrderedShiftRightAndDemote2To",
        label: "clamping",
        ordered: true,
        shift: .plain
    )
    + demoteTwoVectorOps(
        "OrderedRoundingShiftRightAndDemote2To",
        label: "clamping",
        ordered: true,
        shift: .rounding
    )
    + demoteTwoVectorOps(
        "ReorderShiftRightAndDemote2To",
        label: "clampingInAnyOrder",
        ordered: false,
        shift: .plain
    )
    + demoteTwoVectorOps(
        "ReorderRoundingShiftRightAndDemote2To",
        label: "clampingInAnyOrder",
        ordered: false,
        shift: .rounding
    )
    + demoteTruncatingOps + demoteMasksOps

let conversionOps: [Op] =
    bitCastOps + convertFromIntegerOps + convertToIntegerOps + promoteLowerUpperOps
    + promoteEvenOddOps + zipOps + demoteOps

func sumsAccepts(bits: Set<Int>, factor: Int) -> (Element, Element) -> Bool {
    { source, result in
        source.category == result.category && bits.contains(source.bits)
            && result.bits == factor * source.bits
    }
}

func sumsPairs(
    of operand: String,
    from source: Element,
    to result: Element,
    converting: Bool = false
) -> String {
    guard source.category != .float && !converting else {
        let evenLanes = (0..<result.laneCount).map { 2 * $0 }
        let oddLanes = (0..<result.laneCount).map { 2 * $0 + 1 }
        let even = convertedLanes(operand, at: evenLanes, to: result.cVector)
        let odd = convertedLanes(operand, at: oddLanes, to: result.cVector)
        return "(\(even) + \(odd))"
    }
    let unsigned = unsignedElement(of: result).at(width: result.width).cVector
    let shift = source.bits
    guard source.category == .signedInteger else {
        let mask = splat(highestValue(of: source), as: unsigned, lanes: result.laneCount)
        return "(((\(unsigned))\(operand) & \(mask)) + ((\(unsigned))\(operand) >> \(shift)))"
    }
    let even = "(\(result.cVector))((\(unsigned))\(operand) << \(shift)) >> \(shift)"
    return "((\(even)) + ((\(result.cVector))\(operand) >> \(shift)))"
}

func sumsIsSigned32(_ element: Element) -> Bool {
    element.category == .signedInteger && element.bits == 32
}

func sumsChained(from source: Element, to result: Element, converting: Bool = false) -> String {
    var statements: [String] = []
    var operand = "a"
    var widened = source
    while widened.bits * 2 < result.bits {
        let middle = resizedElement(of: source, bits: widened.bits * 2).at(width: result.width)
        let name = "sums\(middle.bits)"
        let pairs = sumsPairs(
            of: operand,
            from: widened,
            to: middle,
            converting: converting && sumsIsSigned32(widened)
        )
        statements.append("const \(middle.cVector) \(name) = \(pairs);")
        operand = name
        widened = middle
    }
    let pairs = sumsPairs(
        of: operand,
        from: widened,
        to: result,
        converting: converting && sumsIsSigned32(widened)
    )
    statements.append(vectorResult(pairs, for: result))
    return statements.joined(separator: "\n")
}

func sumsOfEight(of operand: String, from source: Element, to result: Element) -> String {
    """
    \(result.cVector) result = \(compoundLiteral(result.cVector, ["0"]));
    #pragma clang loop unroll(full)
    for (size_t i = 0; i < \(source.laneCount); ++i) {
      result[i / 8] += \(operand)[i];
    }
    \(vectorResult("result", for: result))
    """
}

func sumsOfPortable(factor: Int, from source: Element, to result: Element) -> String {
    factor == 8
        ? sumsOfEight(of: "a", from: source, to: result)
        : sumsChained(from: source, to: result)
}

func sumsAbsoluteDifferences(of first: String, _ second: String, from source: Element) -> String {
    let bytes = unsignedElement(of: source).cVector
    let larger = "__builtin_elementwise_max(\(first), \(second))"
    let smaller = "__builtin_elementwise_min(\(first), \(second))"
    return "((\(bytes))\(larger) - (\(bytes))\(smaller))"
}

func sumsOfAbsoluteDifferencesPortable(from source: Element, to result: Element) -> String {
    let differences = sumsAbsoluteDifferences(of: "a", "b", from: source)
    return """
        const \(unsignedElement(of: source).cVector) differences = \(differences);
        \(sumsOfEight(of: "differences", from: source, to: result))
        """
}

func sumsAdjacentQuadPortable(from source: Element, to result: Element) -> String {
    """
    const int aStart = (aOffset & 1) * 4;
    const int bStart = (bOffset & 3) * 4;
    \(result.cVector) result;
    #pragma clang loop unroll(full)
    for (size_t i = 0; i < \(result.laneCount); ++i) {
      const size_t block = i / 8 * 16;
      int sum = 0;
      for (size_t j = 0; j < 4; ++j) {
        const int difference = (int)a[block + aStart + i % 8 + j] - (int)b[block + bStart + j];
        sum += difference < 0 ? -difference : difference;
      }
      result[i] = (\(result.cType))sum;
    }
    \(vectorResult("result", for: result))
    """
}

func sumsShuffledQuadPortable(from source: Element, to result: Element) -> String {
    """
    const size_t selections[4] = {(size_t)(i0 & 3), (size_t)(i1 & 3), (size_t)(i2 & 3), (size_t)(i3 & 3)};
    \(result.cVector) result;
    #pragma clang loop unroll(full)
    for (size_t i = 0; i < \(result.laneCount); ++i) {
      const size_t block = i / 8 * 16;
      const size_t aStart = i % 8 / 4 * 8 + i % 4;
      const size_t bStart = i % 8 / 2 * 4;
      int sum = 0;
      for (size_t j = 0; j < 4; ++j) {
        const size_t position = aStart + j;
        const int difference = (int)a[block + selections[position / 4] * 4 + position % 4] - (int)b[block + bStart + j];
        sum += difference < 0 ? -difference : difference;
      }
      result[i] = (\(result.cType))sum;
    }
    \(vectorResult("result", for: result))
    """
}

typealias SumsPairs = (_ operand: String, _ source: Element, _ result: Element) -> String

struct SumsOperands {
    let source: Element
    var element: Element
    var declarations = ""
    var first = "a"
    var second = "b"
}

func sumsOperands(for source: Element, biasing: Bool) -> SumsOperands {
    var operands = SumsOperands(source: source, element: source)
    guard biasing, source.category == .signedInteger else { return operands }
    let bytes = unsignedElement(of: source).at(width: source.width)
    operands.element = bytes
    operands.declarations = """
        const \(bytes.cVector) biasedA = (\(bytes.cVector))(a ^ \(sumsSigns(for: source)));
        const \(bytes.cVector) biasedB = (\(bytes.cVector))(b ^ \(sumsSigns(for: source)));
        """
    operands.first = "biasedA"
    operands.second = "biasedB"
    return operands
}

func sumsImmediatesBody(operands: SumsOperands, cases: String, runtime: String) -> String {
    [operands.declarations, cases, runtime].filter { !$0.isEmpty }.joined(separator: "\n")
}

func sumsAdjacentQuadTarget(
    from source: Element,
    biasing: Bool = false,
    _ body:
        @escaping (_ aOffset: Int, _ bOffset: Int, _ operands: SumsOperands, _ result: Element)
        -> String
) -> (Element) -> String {
    sourced(source) { source, result in
        let operands = sumsOperands(for: source, biasing: biasing)
        let cases = constantSwitch(
            on: "aOffset * 4 + bOffset",
            knowing: ["aOffset", "bOffset"],
            (0..<8).map { (amount: $0, body: body($0 / 4, $0 % 4, operands, result)) }
        )
        return sumsImmediatesBody(
            operands: operands,
            cases: cases,
            runtime: sumsAdjacentQuadPortable(from: source, to: result)
        )
    }
}

func sumsShuffledQuadTarget(
    from source: Element,
    biasing: Bool = false,
    _ body: @escaping (_ tuple: [Int], _ operands: SumsOperands, _ result: Element) -> String
) -> (Element) -> String {
    sourced(source) { source, result in
        let operands = sumsOperands(for: source, biasing: biasing)
        let cases = constantSwitch(
            on: "((i3 * 4u + i2) * 4u + i1) * 4u + i0",
            knowing: ["i3", "i2", "i1", "i0"],
            per4Tuples().map { (amount: per4Key($0), body: body($0, operands, result)) }
        )
        return sumsImmediatesBody(
            operands: operands,
            cases: cases,
            runtime: sumsShuffledQuadPortable(from: source, to: result)
        )
    }
}

func sumsAdjacentQuadVectors(
    aOffset: Int,
    bOffset: Int,
    operands: SumsOperands,
    pairs: SumsPairs,
    to result: Element
) -> String {
    let source = operands.element
    let blocks = source.width / 16
    let words = unsignedElement(bits: 16).at(width: source.width)
    let bytes = unsignedElement(of: source).at(width: source.width)
    let sums = unsignedElement(of: result).at(width: source.width)
    func combined(_ amount: Int) -> String {
        let indices = blockCombineIndices(bytes: amount, width: source.width)
        return "__builtin_shufflevector(lower, upper, \(laneIndices(indices)))"
    }
    func broadcast(_ lane: Int) -> String {
        let indices = broadcastIndices(lane: lane, for: words)
        let vector = "(\(words.cVector))\(operands.second)"
        return "__builtin_shufflevector(\(vector), \(vector), \(laneIndices(indices)))"
    }
    func sum(_ first: String, _ second: String) -> String {
        pairs(sumsAbsoluteDifferences(of: first, second, from: source), bytes, sums)
    }
    let lower = unpackIndices(lanes: 16, upper: false, blocks: blocks)
    let upper = unpackIndices(lanes: 16, upper: true, blocks: blocks)
    let interleave = "\(operands.first), \(operands.first)"
    return """
        {
          const \(source.cVector) lower = __builtin_shufflevector(\(interleave), \(laneIndices(lower)));
          const \(source.cVector) upper = __builtin_shufflevector(\(interleave), \(laneIndices(upper)));
          const \(source.cVector) a01 = \(combined(aOffset * 8 + 1));
          const \(source.cVector) a23 = \(combined(aOffset * 8 + 5));
          const \(source.cVector) b01 = (\(source.cVector))\(broadcast(bOffset * 2));
          const \(source.cVector) b23 = (\(source.cVector))\(broadcast(bOffset * 2 + 1));
          \(vectorResult("\(sum("a01", "b01")) + \(sum("a23", "b23"))", for: result))
        }
        """
}

func sumsShuffledQuadSumsName(from source: Element, to result: Element) -> String {
    "cvectorization_ops_sums_of_shuffled_quad_sums_\(source.cSuffix)_to_\(result.cSuffix)"
}

typealias SumsQuadSum = (_ differences: String, _ element: Element) -> String

func sumsNeonQuadSum(_ differences: String, _ element: Element) -> String {
    let quads = unsignedElement(bits: 32).at(width: element.width)
    return sumsNeonWidened(differences, as: unsignedElement(of: element), to: quads)
}

func sumsX86QuadSum(_ differences: String, _ element: Element) -> String {
    let words = unsignedElement(bits: 16).at(width: element.width)
    let quads = unsignedElement(bits: 32).at(width: element.width)
    let pairs = sumsPairs(of: differences, from: unsignedElement(of: element), to: words)
    return x86Builtin(
        "pmaddwd\(x86Bits(element.width))",
        [pairs, splat("1", as: x86Vector("i16"), lanes: words.laneCount)],
        as: "i16",
        returning: quads.cVector
    )
}

func sumsShuffledQuadSums(
    operands: SumsOperands,
    quadSum: SumsQuadSum,
    to result: Element
) -> String {
    let element = operands.element
    let quads = unsignedElement(bits: 32).at(width: element.width)
    func sum(_ name: String) -> String {
        quadSum(sumsAbsoluteDifferences(of: name, "b", from: element), element)
    }
    return cFunction(
        returns: result.cRawVector,
        name: sumsShuffledQuadSumsName(from: operands.source, to: result),
        parameters: [
            "\(element.cVector) first", "\(element.cVector) second", "\(element.cVector) b",
        ],
        body: """
            const \(quads.cVector) even = \(sum("first"));
            const \(quads.cVector) odd = \(sum("second"));
            \(vectorResult("even + (odd << 16)", for: result))
            """
    )
}

func sumsShuffledQuadVectors(tuple: [Int], operands: SumsOperands, to result: Element) -> String {
    let selections = Array(tuple.reversed())
    func shuffled(_ parity: Int) -> String {
        let indices = (0..<operands.source.width).map { position in
            let quad = position % 16 / 4
            let start = quad / 2 * 8 + quad % 2 * 2 + parity + position % 4
            return position / 16 * 16 + selections[start / 4] * 4 + start % 4
        }
        return
            "__builtin_shufflevector(\(operands.first), \(operands.first), \(laneIndices(indices)))"
    }
    let name = sumsShuffledQuadSumsName(from: operands.source, to: result)
    return "return \(name)(\(shuffled(0)), \(shuffled(1)), \(operands.second));"
}

func sumsNeonWidened(_ operand: String, as source: Element, to result: Element) -> String {
    var expression = operand
    var widened = source
    while widened.bits < result.bits {
        widened = resizedElement(of: source, bits: widened.bits * 2)
        expression = neonBuiltin(
            "vpaddlq_v",
            [expression],
            code: neonTypeCode(of: widened),
            for: widened
        )
    }
    return expression
}

func sumsNeonPairs(_ operand: String, _ source: Element, _ result: Element) -> String {
    sumsNeonWidened(operand, as: source, to: result)
}

func sumsNeonWidening(from source: Element, to result: Element) -> String? {
    guard source.category != .float else { return nil }
    return vectorResult(sumsNeonWidened("a", as: source, to: result), for: result)
}

func sumsNeonOfEightAbsoluteDifferences(from source: Element, to result: Element) -> String {
    let differences = neonBuiltin(
        "vabdq_v",
        ["a", "b"],
        code: neonTypeCode(of: source),
        for: source
    )
    return vectorResult(
        sumsNeonWidened(differences, as: unsignedElement(of: source), to: result),
        for: result
    )
}

func sumsSigns(for source: Element) -> String {
    splat("-128", as: source.cVector, lanes: source.laneCount)
}

func sumsX86Biased(_ operand: String, for source: Element) -> String {
    source.category == .signedInteger ? "(\(operand) ^ \(sumsSigns(for: source)))" : operand
}

func sumsX86Sad(_ first: String, _ second: String, to result: Element) -> String {
    x86Builtin(
        "psadbw\(x86Bits(result.width))",
        [first, second],
        as: "i8",
        returning: result.cVector
    )
}

func sumsX86OfEight(from source: Element, to result: Element) -> String {
    let zero = compoundLiteral(x86Vector("i8"), ["0"])
    let sums = sumsX86Sad(sumsX86Biased("a", for: source), zero, to: result)
    guard source.category == .signedInteger else { return vectorResult(sums, for: result) }
    let offset = splat("-1024", as: result.cVector, lanes: result.laneCount)
    return vectorResult("\(sums) + \(offset)", for: result)
}

func sumsX86OfEightAbsoluteDifferences(from source: Element, to result: Element) -> String {
    vectorResult(
        sumsX86Sad(sumsX86Biased("a", for: source), sumsX86Biased("b", for: source), to: result),
        for: result
    )
}

func sumsX86Avx3OfFour(from source: Element, to result: Element) -> String? {
    guard source.bits == 8 else { return nil }
    let words = unsignedElement(bits: 16).at(width: source.width)
    let zero = compoundLiteral(x86Vector("i8"), ["0"])
    let differences = x86Builtin(
        "dbpsadbw512",
        [
            (value: sumsX86Biased("a", for: source), type: x86Vector("i8")),
            (value: zero, type: x86Vector("i8")),
            (value: "0", type: "int"),
        ],
        returning: words.cVector
    )
    let sums = x86Avx3Select(
        "0x55555555",
        differences,
        splat("0", as: words.cVector, lanes: words.laneCount),
        for: words
    )
    guard source.category == .signedInteger else { return vectorResult(sums, for: result) }
    let offset = splat("-512", as: result.cVector, lanes: result.laneCount)
    return vectorResult("(\(result.cVector))\(sums) + \(offset)", for: result)
}

func sumsX86Avx3OfTwoFloats(from source: Element, to result: Element) -> String? {
    guard source.category == .float else { return nil }
    let words = unsignedElement(bits: 64).at(width: result.width).cVector
    let even = "__builtin_convertvector(even, \(result.cVector))"
    let odd = "__builtin_convertvector(odd, \(result.cVector))"
    return """
        \(vectorTypedef("narrow_vector", of: source, lanes: result.laneCount))
        \(vectorTypedef("narrow_lanes", of: unsignedElement(bits: 32), lanes: result.laneCount))
        const narrow_vector even = (narrow_vector)__builtin_convertvector((\(words))a, narrow_lanes);
        const narrow_vector odd = (narrow_vector)__builtin_convertvector((\(words))a >> 32, narrow_lanes);
        \(vectorResult("\(even) + \(odd)", for: result))
        """
}

func sumsX86Sse4Chained(from source: Element, to result: Element) -> String? {
    guard source.category == .signedInteger, result.bits == 64 else { return nil }
    return sumsChained(from: source, to: result, converting: true)
}

func sumsX86Mpsadbw(
    aOffset: Int,
    bOffset: Int,
    operands: SumsOperands,
    to result: Element
) -> String {
    let immediate =
        operands.source.width == 16
        ? (aOffset << 2) | bOffset
        : (aOffset << 5) | (bOffset << 3) | (aOffset << 2) | bOffset
    let sums = x86Builtin(
        "mpsadbw\(x86Bits(operands.source.width))",
        [
            (value: operands.first, type: x86Vector("i8")),
            (value: operands.second, type: x86Vector("i8")),
            (value: String(immediate), type: "int"),
        ],
        returning: result.cVector
    )
    return vectorResult(sums, for: result)
}

func sumsX86Dbsad(
    _ first: String,
    _ second: String,
    immediate: Int,
    to result: Element
) -> String {
    vectorResult(
        x86Builtin(
            "dbpsadbw512",
            [
                (value: first, type: x86Vector("i8")),
                (value: second, type: x86Vector("i8")),
                (value: String(immediate), type: "int"),
            ],
            returning: result.cVector
        ),
        for: result
    )
}

func sumsX86Avx3AdjacentQuad(
    aOffset: Int,
    bOffset: Int,
    operands: SumsOperands,
    to result: Element
) -> String {
    let source = operands.element
    let quads = unsignedElement(bits: 32).at(width: source.width)
    let indices = broadcastIndices(lane: bOffset, for: quads)
    let vector = "(\(quads.cVector))\(operands.second)"
    let broadcast =
        "(\(source.cVector))__builtin_shufflevector(\(vector), \(vector), \(laneIndices(indices)))"
    let immediate = ((aOffset + 2) << 6) | ((aOffset + 1) << 4) | ((aOffset + 1) << 2) | aOffset
    return sumsX86Dbsad(broadcast, operands.first, immediate: immediate, to: result)
}

func sumsX86Avx3ShuffledQuad(tuple: [Int], operands: SumsOperands, to result: Element) -> String {
    sumsX86Dbsad(operands.second, operands.first, immediate: per4Key(tuple), to: result)
}

func sumsBitwisePairs(_ operand: String, _ source: Element, _ result: Element) -> String {
    sumsPairs(of: operand, from: source, to: result)
}

func sumsOfTargets(factor: Int, from source: Element) -> TargetBodies<Element> {
    let widening = sourced(source) { source, result in sumsNeonWidening(from: source, to: result) }
    let sse4 = sourced(source) { source, result in sumsX86Sse4Chained(from: source, to: result) }
    guard factor == 8 else {
        let avx3 = sourced(source) { source, result -> String? in
            factor == 4
                ? sumsX86Avx3OfFour(from: source, to: result)
                : sumsX86Avx3OfTwoFloats(from: source, to: result)
        }
        return TargetBodies(sve2_128: widening, avx3: avx3, sse4: sse4)
    }
    let x86 = sourced(source) { source, result in sumsX86OfEight(from: source, to: result) }
    return TargetBodies(neon: widening, avx3: x86, avx2: x86, sse2: x86)
}

func sumsOfOps(_ swiftName: String, _ highwayName: String, bits: Set<Int>, factor: Int) -> [Op] {
    sourcedOps(accepting: sumsAccepts(bits: bits, factor: factor)) { source, results in
        Op(
            swiftName,
            highwayName,
            [.sourceVector],
            .vector,
            results,
            section: .arithmetic,
            unorderedNaNs: source.category == .float ? .adjacentLanes : nil,
            filtersUnorderedNaNs: source.category == .float,
            vectorLabels: ["_"],
            source: source,
            targets: sumsOfTargets(factor: factor, from: source),
            portable: sourced(source) { source, result in
                sumsOfPortable(factor: factor, from: source, to: result)
            }
        )
    }
}

let sumsOfAbsoluteDifferencesOps = sourcedOps(
    accepting: sumsAccepts(bits: [8], factor: 8)
) { source, results in
    let x86 = sourced(source) { source, result in
        sumsX86OfEightAbsoluteDifferences(from: source, to: result)
    }
    return Op(
        "sumsOf8AbsoluteDifferences",
        "SumsOf8AbsDiff",
        [.sourceVector, .sourceVector],
        .vector,
        results,
        section: .arithmetic,
        vectorLabels: ["_", "_"],
        source: source,
        targets: TargetBodies(
            neon: sourced(source) { source, result in
                sumsNeonOfEightAbsoluteDifferences(from: source, to: result)
            },
            avx3: x86,
            avx2: x86,
            sse2: x86
        ),
        portable: sourced(source) { source, result in
            sumsOfAbsoluteDifferencesPortable(from: source, to: result)
        }
    )
}

let sumsAdjacentQuadOffsets = [
    ImmediateArgument(
        name: "aOffset",
        label: "aOffset",
        upperBound: .fixed(1),
        message: "A offset is not between 0 and 1"
    ),
    ImmediateArgument(
        name: "bOffset",
        label: "bOffset",
        upperBound: .fixed(3),
        message: "B offset is not between 0 and 3"
    ),
]

let sumsAdjacentQuadOps = sourcedOps(accepting: sumsAccepts(bits: [8], factor: 2)) {
    source,
    results in
    func vectors(biasing: Bool, pairs: @escaping SumsPairs) -> (Element) -> String {
        sumsAdjacentQuadTarget(from: source, biasing: biasing) {
            aOffset,
            bOffset,
            operands,
            result in
            sumsAdjacentQuadVectors(
                aOffset: aOffset,
                bOffset: bOffset,
                operands: operands,
                pairs: pairs,
                to: result
            )
        }
    }
    let mpsadbw = sumsAdjacentQuadTarget(from: source, biasing: true) {
        aOffset,
        bOffset,
        operands,
        result in
        sumsX86Mpsadbw(aOffset: aOffset, bOffset: bOffset, operands: operands, to: result)
    }
    return Op(
        "sumsOfAdjacentQuadAbsoluteDifferences",
        "SumsOfAdjQuadAbsDiff",
        [.sourceVector, .sourceVector, .immediate, .immediate],
        .vector,
        results,
        section: .arithmetic,
        immediates: sumsAdjacentQuadOffsets,
        vectorLabels: ["_", "_"],
        source: source,
        targets: TargetBodies(
            neon: vectors(biasing: false, pairs: sumsNeonPairs),
            avx3: sumsAdjacentQuadTarget(from: source, biasing: true) {
                aOffset,
                bOffset,
                operands,
                result in
                sumsX86Avx3AdjacentQuad(
                    aOffset: aOffset,
                    bOffset: bOffset,
                    operands: operands,
                    to: result
                )
            },
            avx2: mpsadbw,
            sse4: mpsadbw,
            sse2: vectors(biasing: true, pairs: sumsBitwisePairs)
        ),
        portable: sourced(source) { source, result in
            sumsAdjacentQuadPortable(from: source, to: result)
        }
    )
}

let sumsShuffledQuadOps = sourcedOps(accepting: sumsAccepts(bits: [8], factor: 2)) {
    source,
    results in
    func vectors(biasing: Bool) -> (Element) -> String {
        sumsShuffledQuadTarget(from: source, biasing: biasing) { tuple, operands, result in
            sumsShuffledQuadVectors(tuple: tuple, operands: operands, to: result)
        }
    }
    func sums(biasing: Bool, quadSum: @escaping SumsQuadSum) -> (Element) -> String {
        sourced(source) { source, result in
            sumsShuffledQuadSums(
                operands: sumsOperands(for: source, biasing: biasing),
                quadSum: quadSum,
                to: result
            )
        }
    }
    return Op(
        "sumsOfShuffledQuadAbsoluteDifferences",
        "SumsOfShuffledQuadAbsDiff",
        [.sourceVector, .sourceVector, .immediate, .immediate, .immediate, .immediate],
        .vector,
        results,
        section: .arithmetic,
        immediates: per4LaneIndices,
        vectorLabels: ["_", "_"],
        source: source,
        targets: TargetBodies(
            neon: vectors(biasing: false),
            avx3: sumsShuffledQuadTarget(from: source, biasing: true) { tuple, operands, result in
                sumsX86Avx3ShuffledQuad(tuple: tuple, operands: operands, to: result)
            },
            avx2: vectors(biasing: false),
            sse4: vectors(biasing: false),
            sse2: vectors(biasing: true)
        ),
        helpers: TargetBodies(
            neon: sums(biasing: false, quadSum: sumsNeonQuadSum),
            avx2: sums(biasing: false, quadSum: sumsX86QuadSum),
            sse4: sums(biasing: false, quadSum: sumsX86QuadSum),
            sse2: sums(biasing: true, quadSum: sumsX86QuadSum)
        ),
        portable: sourced(source) { source, result in
            sumsShuffledQuadPortable(from: source, to: result)
        }
    )
}

let sumsOps: [Op] =
    sumsOfOps("sumsOf2", "SumsOf2", bits: [8, 16, 32], factor: 2)
    + sumsOfOps("sumsOf4", "SumsOf4", bits: [8, 16], factor: 4)
    + sumsOfOps("sumsOf8", "SumsOf8", bits: [8], factor: 8)
    + sumsOfAbsoluteDifferencesOps + sumsAdjacentQuadOps + sumsShuffledQuadOps

func mulBitsBiasedExponentAccepts(_ source: Element, _ result: Element) -> Bool {
    source.category == .float && result.category == .unsignedInteger && source.bits == result.bits
}

func mulBitsBiasedExponent(from source: Element, to result: Element) -> String {
    vectorResult(
        "(\(result.cVector))__builtin_elementwise_abs(a) >> \(mantissaBits(of: source))",
        for: result
    )
}

let mulBitsBiasedExponentOps = sourcedOps(accepting: mulBitsBiasedExponentAccepts) {
    source,
    results in
    Op(
        "biasedExponent",
        "GetBiasedExponent",
        [.sourceVector],
        .vector,
        results,
        section: .arithmetic,
        source: source,
        portable: sourced(source) { source, result in
            mulBitsBiasedExponent(from: source, to: result)
        }
    )
}

enum MulBitsExponentClamp {
    case lanes
    case selecting
    case halves
    case words

    var bits: Int? {
        switch self {
        case .lanes, .selecting: return nil
        case .halves: return 32
        case .words: return 16
        }
    }
}

func mulBitsPowerOf2Accepts(_ source: Element, _ result: Element) -> Bool {
    source.category == .signedInteger && result.category == .float && source.bits == result.bits
}

func mulBitsPowerOf2(_ clamp: MulBitsExponentClamp, to result: Element) -> String {
    let exponents = signedElement(of: result).at(width: result.width)
    let integer = exponents.cVector
    let bias = maxExponentField(of: result) >> 1
    let isHalf = result.category == .float16
    let arithmetic = isHalf ? "native_vector" : result.cVector
    func integers(_ value: Int) -> String {
        splat("\(value)", as: integer, lanes: result.laneCount)
    }
    func clamped(_ operand: String, _ lowest: Int, _ highest: Int, viewedAs bits: Int?) -> String {
        guard let bits, bits < exponents.bits else {
            let raised = "__builtin_elementwise_max(\(operand), \(integers(lowest)))"
            return "__builtin_elementwise_min(\(raised), \(integers(highest)))"
        }
        let view = resizedElement(of: exponents, bits: bits).cVector
        let raised = "__builtin_elementwise_max((\(view))\(operand), (\(view))\(integers(lowest)))"
        return "(\(integer))__builtin_elementwise_min(\(raised), (\(view))\(integers(highest)))"
    }
    func selected(_ mask: String, _ chosen: String, _ other: String) -> String {
        let words = x86Vector("i64")
        let (picked, kept) = ("(\(words))\(chosen)", "(\(words))\(other)")
        return "(\(integer))(((\(words))\(mask) & \(picked)) | (~(\(words))\(mask) & \(kept)))"
    }
    func neonSelected(_ operand: String, _ lowest: Int, _ highest: Int) -> String {
        let (low, high) = (integers(lowest), integers(highest))
        func choosing(_ mask: String, _ chosen: String, _ other: String) -> String {
            neonBuiltin(
                "vbslq_v",
                [mask, chosen, other],
                code: neonTypeCode(of: exponents),
                for: exponents
            )
        }
        let raised = choosing("(\(exponents.cMask))(\(low) > \(operand))", low, operand)
        return choosing("(\(exponents.cMask))(\(raised) > \(high))", high, raised)
    }
    func neonClamped(_ operand: String, _ lowest: Int, _ highest: Int) -> String {
        let code = neonTypeCode(of: exponents)
        let raised = neonBuiltin(
            "vmaxq_v",
            [operand, integers(lowest)],
            code: code,
            for: exponents
        )
        return neonBuiltin("vminq_v", [raised, integers(highest)], code: code, for: exponents)
    }
    func comparison(_ name: String, _ first: String, _ second: String) -> String {
        guard exponents.bits == 64 else {
            return "const \(exponents.cMask) \(name) = (\(exponents.cMask))(\(first) > \(second));"
        }
        return """
            \(exponents.cMask) \(name);
            {
            \(indented(x86Int64Greater(first, second, for: exponents)))
              \(name) = mask;
            }
            """
    }
    func bitwiseClamped(_ lowest: Int, _ highest: Int) -> String {
        let (low, high) = (integers(lowest), integers(highest))
        return """
            \(comparison("raisable", "b", low))
            const \(integer) raised = \(selected("raisable", "b", low));
            \(comparison("lowerable", "raised", high))
            const \(integer) exponent = \(selected("lowerable", high, "raised"));
            """
    }
    func factor(_ exponent: String) -> String {
        "(\(arithmetic))((\(exponent) + \(integers(bias))) << \(mantissaBits(of: result)))"
    }
    func clampedExponent(_ operand: String, _ lowest: Int, _ highest: Int, narrowly: Bool) -> String
    {
        switch clamp {
        case .selecting where exponents.bits == 64:
            return neonSelected(operand, lowest, highest)
        case .selecting:
            return neonClamped(operand, lowest, highest)
        default: return clamped(operand, lowest, highest, viewedAs: narrowly ? clamp.bits : nil)
        }
    }
    let widest =
        clamp == .words
        ? bitwiseClamped(3 - 3 * bias, 3 * bias)
        : "const \(integer) exponent = \(clampedExponent("b", 3 - 3 * bias, 3 * bias, narrowly: false));"
    let factors = [
        "const \(arithmetic) factor1 = \(factor("exponent1"));",
        "const \(arithmetic) factor2 = \(factor("exponent2"));",
        "const \(arithmetic) factor3 = \(factor("exponent3"));",
    ]
    let natives =
        isHalf
        ? "\(halfPrecisionNativeVector(for: result))\nconst native_vector nativeA = (native_vector)a;\n"
        : ""
    let product = "((\(isHalf ? "nativeA" : "a") * factor1) * factor2) * factor3"
    return """
        \(natives)\(widest)
        const \(integer) exponent3 = \(clampedExponent("exponent", 1 - bias, bias, narrowly: true));
        const \(integer) remaining = exponent - exponent3;
        const \(integer) exponent2 = \(clampedExponent("remaining", 1 - bias, bias, narrowly: true));
        const \(integer) exponent1 = remaining - exponent2;
        \(factors.joined(separator: "\n"))
        \(vectorResult(isHalf ? "(\(result.cVector))(\(product))" : product, for: result))
        """
}

func mulBitsPowerOf2Sve(from source: Element, to result: Element) -> String {
    let scaled = sveBuiltin(
        "scale",
        [
            sveAllLanes(of: result), sveSplatOperand("a", for: result),
            sveSplatOperand("b", for: source),
        ],
        for: result,
        predication: "x"
    )
    return vectorResult(sveResult(scaled, for: result), for: result)
}

func mulBitsPowerOf2X86Avx3(to result: Element) -> String {
    let floating = x86Vector(result.cSuffix)
    let arguments = [
        (value: "a", type: floating), (value: "scale", type: floating),
        (value: compoundLiteral(floating, ["0"]), type: floating),
        (value: "-1", type: x86MaskType(lanes: result.laneCount)),
        (value: "\(x86CurrentRounding)", type: "int"),
    ]
    let name = "scalef\(result.bits == 32 ? "ps" : "pd")\(x86Bits(result.width))_mask"
    return """
        const \(result.cVector) scale = __builtin_convertvector(b, \(result.cVector));
        \(vectorResult(x86Builtin(name, arguments, returning: result.cVector), for: result))
        """
}

let mulBitsPowerOf2Ops = sourcedOps(accepting: mulBitsPowerOf2Accepts) { source, results in
    Op(
        "multiplyingByPowerOf2",
        "MulByPow2",
        [.vector, .sourceVector],
        .vector,
        results,
        section: .multiply,
        source: source,
        targets: TargetBodies(
            neon: { result in mulBitsPowerOf2(.selecting, to: result) },
            sve2_128: sourced(source) { source, result in
                mulBitsPowerOf2Sve(from: source, to: result)
            },
            avx3: { result in mulBitsPowerOf2X86Avx3(to: result) },
            avx2: { result in mulBitsPowerOf2(.halves, to: result) },
            sse4: { result in mulBitsPowerOf2(.halves, to: result) },
            sse2: { result in mulBitsPowerOf2(.words, to: result) }
        ),
        portable: { result in mulBitsPowerOf2(.lanes, to: result) }
    )
}

func mulBitsSourceInputs(of op: Op, operand: Element, seed: String) -> String? {
    switch op.highwayName {
    case "MulByPow2": return "Inputs.exponents(\(operand.namespace).Vector.self, \(seed))"
    case "MultiRotateRight", "BitShuffle":
        return "Inputs.byteIndices(\(operand.namespace).Vector.self, \(seed))"
    default: return nil
    }
}

func mulBitsMultiplyingAccepts(_ source: Element, _ result: Element) -> Bool {
    source.category != .float && source.category == result.category
        && result.bits == 2 * source.bits
}

func mulBitsWidenedLanes(
    _ operand: String,
    odd: Bool,
    from source: Element,
    to result: Element
) -> String {
    let unsigned = unsignedElement(of: result).at(width: result.width)
    let shift = source.bits
    guard source.category != .signedInteger else {
        let lanes =
            odd
            ? "(\(result.cVector))\(operand)"
            : "(\(result.cVector))((\(unsigned.cVector))\(operand) << \(shift))"
        return "(\(lanes) >> \(shift))"
    }
    let lowMask = splat(highestValue(of: source), as: unsigned.cVector, lanes: result.laneCount)
    let lanes =
        odd
        ? "(\(unsigned.cVector))\(operand) >> \(shift)"
        : "(\(unsigned.cVector))\(operand) & \(lowMask)"
    return "(\(result.cVector))(\(lanes))"
}

func mulBitsMultiplying(odd: Bool, from source: Element, to result: Element) -> String {
    let (first, second) = (
        mulBitsWidenedLanes("a", odd: odd, from: source, to: result),
        mulBitsWidenedLanes("b", odd: odd, from: source, to: result)
    )
    return vectorResult("\(first) * \(second)", for: result)
}

func mulBitsMultiplyingEmulated(odd: Bool, from source: Element, to result: Element) -> String? {
    guard !odd && source.category == .signedInteger else { return nil }
    let (first, second) = (
        mulBitsConvertedEvenLanes("a", from: source, to: result),
        mulBitsConvertedEvenLanes("b", from: source, to: result)
    )
    return vectorResult("\(first) * \(second)", for: result)
}

func mulBitsConvertedEvenLanes(
    _ operand: String,
    from source: Element,
    to result: Element
) -> String {
    let kept = mulBitsKeptLanes(operand, odd: false, count: result.laneCount)
    return "__builtin_convertvector(\(kept), \(result.cVector))"
}

func mulBitsKeptLanes(_ operand: String, odd: Bool, count: Int) -> String {
    let kept = laneIndices((0..<count).map { 2 * $0 + (odd ? 1 : 0) })
    return "__builtin_shufflevector(\(operand), \(operand), \(kept))"
}

func mulBitsMultiplyingNeon(odd: Bool, from source: Element, to result: Element) -> String {
    let halves = neonVector("i8x8")
    let product = """
        (\(result.cVector))__builtin_neon_vmull_v((\(halves))first, (\(halves))second, \(neonTypeCode(of: result)))
        """
    return """
        \(vectorTypedef("narrow_vector", of: source, lanes: result.laneCount))
        const narrow_vector first = \(mulBitsKeptLanes("a", odd: odd, count: result.laneCount));
        const narrow_vector second = \(mulBitsKeptLanes("b", odd: odd, count: result.laneCount));
        \(vectorResult(product, for: result))
        """
}

func mulBitsMultiplyingSve(odd: Bool, from source: Element, to result: Element) -> String {
    let operands = ["a", "b"].map { sveSplatOperand($0, for: source) }
    let product = sveBuiltin(odd ? "mullt" : "mullb", operands, for: result)
    return vectorResult(sveResult(product, for: result), for: result)
}

func mulBitsMultiplyingX86Words(
    odd: Bool,
    level: X86Level,
    from source: Element,
    to result: Element
) -> String {
    let words = unsignedElement(of: source).at(width: source.width).cVector
    let wide = unsignedElement(of: result).at(width: result.width).cVector
    let name = "pmulh\(source.category == .signedInteger ? "w" : "uw")\(x86Bits(source.width))"
    let high = x86Builtin(name, ["a", "b"], as: "i16", returning: words)
    let lanes = source.laneCount
    let combined: String
    if level >= .avx2 {
        let blended = laneIndices((0..<lanes).map { $0 % 2 == 0 ? $0 : lanes + $0 })
        let (lowShifted, highShifted) = (
            odd ? "(\(words))((\(wide))low >> 16)" : "low",
            odd ? "high" : "(\(words))((\(wide))high << 16)"
        )
        combined = "__builtin_shufflevector(\(lowShifted), \(highShifted), \(blended))"
    } else {
        let (lowMask, highMask) = (
            splat("0xffff", as: wide, lanes: result.laneCount),
            splat("0xffff0000", as: wide, lanes: result.laneCount)
        )
        combined =
            odd
            ? "((\(wide))low >> 16) | ((\(wide))high & \(highMask))"
            : "((\(wide))low & \(lowMask)) | ((\(wide))high << 16)"
    }
    return """
        const \(words) low = (\(words))a * (\(words))b;
        const \(words) high = \(high);
        \(vectorResult(combined, for: result))
        """
}

func mulBitsMultiplyingX86Signed32(odd: Bool, from source: Element, to result: Element) -> String {
    let unsigned = unsignedElement(of: source).at(width: source.width).cVector
    let unsignedWide = unsignedElement(of: result).at(width: result.width).cVector
    let lanes = source.laneCount
    let duplicated = laneIndices((0..<lanes).map { $0 | (odd ? 1 : 0) })
    let operands =
        odd
        ? [
            "const \(source.cVector) first = __builtin_shufflevector(a, a, \(duplicated));",
            "const \(source.cVector) second = __builtin_shufflevector(b, b, \(duplicated));",
        ] : ["const \(source.cVector) first = a;", "const \(source.cVector) second = b;"]
    let low = x86Builtin("pmuludq128", ["first", "second"], as: "i32", returning: unsignedWide)
    return
        (operands + [
            "const \(unsigned) corrections = ((\(unsigned))(first >> 31) & (\(unsigned))second) + ((\(unsigned))(second >> 31) & (\(unsigned))first);",
            "const \(unsignedWide) low = \(low);",
            vectorResult("low - ((\(unsignedWide))corrections << 32)", for: result),
        ]).joined(separator: "\n")
}

func mulBitsMultiplyingX86Duplicated(from source: Element, to result: Element) -> String {
    let duplicated = laneIndices((0..<source.laneCount).map { $0 | 1 })
    let (first, second) = (
        mulBitsWidenedLanes("first", odd: false, from: source, to: result),
        mulBitsWidenedLanes("second", odd: false, from: source, to: result)
    )
    return """
        const \(source.cVector) first = __builtin_shufflevector(a, a, \(duplicated));
        const \(source.cVector) second = __builtin_shufflevector(b, b, \(duplicated));
        \(vectorResult("\(first) * \(second)", for: result))
        """
}

func mulBitsMultiplyingX86(
    odd: Bool,
    level: X86Level,
    from source: Element,
    to result: Element
) -> String? {
    switch (source.bits, source.category) {
    case (16, .signedInteger) where level < .sse4:
        return mulBitsMultiplyingX86Words(odd: odd, level: level, from: source, to: result)
    case (16, .unsignedInteger) where level < .sse4 || level == .avx2:
        return mulBitsMultiplyingX86Words(odd: odd, level: level, from: source, to: result)
    case (32, .signedInteger) where level < .sse4:
        return mulBitsMultiplyingX86Signed32(odd: odd, from: source, to: result)
    case (32, _) where odd:
        return mulBitsMultiplyingX86Duplicated(from: source, to: result)
    default:
        return nil
    }
}

func mulBitsMultiplyingOps(
    _ swiftName: String,
    _ highwayName: String,
    odd: Bool
) -> [Op] {
    sourcedOps(accepting: mulBitsMultiplyingAccepts) { source, results in
        func x86(_ level: X86Level) -> (Element) -> String? {
            sourced(source) { source, result in
                mulBitsMultiplyingX86(odd: odd, level: level, from: source, to: result)
                    ?? (level == .sse4
                        ? mulBitsMultiplying(odd: odd, from: source, to: result) : nil)
            }
        }
        return Op(
            swiftName,
            highwayName,
            [.sourceVector, .sourceVector],
            .vector,
            results,
            section: .multiply,
            source: source,
            targets: TargetBodies(
                neon: sourced(source) { source, result in
                    mulBitsMultiplyingNeon(odd: odd, from: source, to: result)
                },
                sve2_128: sourced(source) { source, result in
                    mulBitsMultiplyingSve(odd: odd, from: source, to: result)
                },
                avx3: x86(.avx3),
                avx2: x86(.avx2),
                sse4: x86(.sse4),
                sse2: x86(.sse2),
                emu128: sourced(source) { source, result in
                    mulBitsMultiplyingEmulated(odd: odd, from: source, to: result)
                }
            ),
            portable: sourced(source) { source, result in
                mulBitsMultiplying(odd: odd, from: source, to: result)
            }
        )
    }
}

func mulBitsWideProduct64(odd: Bool, for element: Element) -> String {
    let lane = element.cUnsignedLane
    let isSigned = element.category == .signedInteger
    let wide = isSigned ? "__int128" : "unsigned __int128"
    let half = element.bits / 2
    let corrections =
        isSigned
        ? " - ((\(lane))(first >> \(element.bits - 1)) & y) - ((\(lane))(second >> \(element.bits - 1)) & x)"
        : ""
    return """
        \(element.cVector) product;
        for (size_t i = 0; i < \(element.laneCount); i += 2) {
          const size_t index = i + \(odd ? 1 : 0);
          const \(element.cType) first = a[index];
          const \(element.cType) second = b[index];
        #if defined(__SIZEOF_INT128__)
          const \(wide) wide = (\(wide))\(odd ? "first" : "second") * (\(wide))\(odd ? "second" : "first");
          product[i] = (\(element.cType))wide;
          product[i + 1] = (\(element.cType))(wide >> \(element.bits));
        #else
          const \(lane) x = (\(lane))first;
          const \(lane) y = (\(lane))second;
          const \(lane) loLo = (x & 0xffffffff) * (y & 0xffffffff);
          const \(lane) hiLo = (x >> \(half)) * (y & 0xffffffff);
          const \(lane) loHi = (x & 0xffffffff) * (y >> \(half));
          const \(lane) hiHi = (x >> \(half)) * (y >> \(half));
          const \(lane) t = (loLo >> \(half)) + (hiLo & 0xffffffff) + loHi;
          product[i] = (\(element.cType))((t << \(half)) | (loLo & 0xffffffff));
          product[i + 1] = (\(element.cType))((hiLo >> \(half)) + (t >> \(half)) + hiHi\(corrections));
        #endif
        }
        \(vectorResult("product", for: element))
        """
}

func mulBitsWideProduct64Sve(odd: Bool, for element: Element) -> String {
    let operands = ["a", "b"].map { sveOperand($0, for: element, splat: true) }
    func product(_ name: String) -> String {
        let call = sveBuiltin(
            name,
            [sveAllLanes(of: element)] + operands,
            for: element,
            predication: "x"
        )
        return sveResult(call, for: element)
    }
    return """
        const \(element.cVector) high = \(product("mulh"));
        const \(element.cVector) low = \(product("mul"));
        \(sveShuffled(odd ? "trn2" : "trn1", "low", "high", for: element))
        """
}

func mulBitsWideProduct64X86(odd: Bool, for element: Element) -> String {
    let integers = x86Vector("i32")
    let unsigned = element.cUnsignedVector
    let lanes = element.laneCount * 2
    let swapped = laneIndices((0..<lanes).map { $0 ^ 1 })
    func product(_ first: String, _ second: String) -> String {
        x86Builtin(
            "pmuludq\(x86Bits(element.width))",
            [first, second],
            as: "i32",
            returning: unsigned
        )
    }
    let isSigned = element.category == .signedInteger
    let corrections =
        isSigned
        ? [
            "const \(element.cVector) aSigns = a >> 63;",
            "const \(element.cVector) bSigns = b >> 63;",
        ]
        : []
    let high =
        isSigned
        ? "(\(unsigned))unsignedHigh - (\(unsigned))(aSigns & b) - (\(unsigned))(a & bSigns)"
        : "unsignedHigh"
    let parity = odd ? 1 : 0
    let interleaved = laneIndices(
        (0..<element.laneCount / 2).flatMap {
            [2 * $0 + parity, element.laneCount + 2 * $0 + parity]
        }
    )
    return
        ([
            "const \(integers) a32 = (\(integers))a;",
            "const \(integers) b32 = (\(integers))b;",
            "const \(integers) aSwapped = __builtin_shufflevector(a32, a32, \(swapped));",
            "const \(integers) bSwapped = __builtin_shufflevector(b32, b32, \(swapped));",
            "const \(unsigned) lowMask = \(splat("0xffffffff", as: unsigned, lanes: element.laneCount));",
            "const \(unsigned) lowProducts = \(product("a32", "b32"));",
            "const \(unsigned) middle = \(product("aSwapped", "b32")) + (lowProducts >> 32);",
            "const \(unsigned) carried = \(product("a32", "bSwapped")) + (middle & lowMask);",
            "const \(unsigned) unsignedHigh = \(product("aSwapped", "bSwapped")) + (middle >> 32) + (carried >> 32);",
            "const \(unsigned) low = (carried << 32) + (lowProducts & lowMask);",
        ] + corrections + [
            "const \(unsigned) high = \(high);",
            vectorResult("__builtin_shufflevector(low, high, \(interleaved))", for: element),
        ]).joined(separator: "\n")
}

func mulBitsMultiplying64Op(
    _ swiftName: String,
    _ highwayName: String,
    odd: Bool
) -> Op {
    Op(
        swiftName,
        highwayName,
        [.vector, .vector],
        .vector,
        .integer(bits: [64]),
        section: .multiply,
        targets: TargetBodies(
            sve2_128: { element in mulBitsWideProduct64Sve(odd: odd, for: element) },
            avx3: { element in mulBitsWideProduct64X86(odd: odd, for: element) },
            avx2: { element in mulBitsWideProduct64X86(odd: odd, for: element) }
        )
    ) { element in
        mulBitsWideProduct64(odd: odd, for: element)
    }
}

let mulBitsMultiplyingEvenOps =
    mulBitsMultiplyingOps("multiplyingEven", "MulEven", odd: false)
    + [mulBitsMultiplying64Op("multiplyingEven", "MulEven", odd: false)]

let mulBitsMultiplyingOddOps =
    mulBitsMultiplyingOps("multiplyingOdd", "MulOdd", odd: true)
    + [mulBitsMultiplying64Op("multiplyingOdd", "MulOdd", odd: true)]

func mulBitsByteIndexedAccepts(_ source: Element, _ result: Element) -> Bool {
    source.bits == 8 && source.category != .float && result.bits == 64 && result.category != .float
}

func mulBitsMultiRotatedRight(for element: Element) -> String {
    let lane = element.cUnsignedLane
    let bytes = unsignedElement(bits: 8).at(width: element.width)
    return """
        \(bytes.cVector) rotated;
        for (size_t i = 0; i < \(element.laneCount); ++i) {
          const \(lane) value = (\(lane))a[i];
          for (size_t j = 0; j < 8; ++j) {
            const unsigned count = (unsigned)(uint8_t)b[i * 8 + j] & 63;
            rotated[i * 8 + j] = (uint8_t)((value >> count) | (value << ((64 - count) & 63)));
          }
        }
        \(vectorResult("rotated", for: element))
        """
}

func mulBitsBitShuffled(for element: Element) -> String {
    let lane = element.cUnsignedLane
    return """
        \(element.cVector) shuffled;
        for (size_t i = 0; i < \(element.laneCount); ++i) {
          const \(lane) value = (\(lane))a[i];
          \(lane) bits = 0;
          for (size_t j = 0; j < 8; ++j) {
            const unsigned count = (unsigned)(uint8_t)b[i * 8 + j] & 63;
            bits |= ((value >> count) & 1) << j;
          }
          shuffled[i] = (\(element.cType))bits;
        }
        \(vectorResult("shuffled", for: element))
        """
}

func mulBitsByteVectors(for element: Element) -> (bytes: Element, words: Element, lanes: Element) {
    (
        unsignedElement(bits: 8).at(width: element.width),
        unsignedElement(bits: 16).at(width: element.width),
        unsignedElement(of: element).at(width: element.width)
    )
}

enum MulBitsByteLookup {
    case neon
    case sve
    case x86

    func lookup(_ table: String, _ indices: String, for element: Element) -> String {
        let bytes = unsignedElement(bits: 8).at(width: element.width)
        switch self {
        case .neon: return neonTableLookup(table, indices, for: bytes)
        case .sve:
            let operands = [table, indices].map { sveOperand($0, for: bytes) }
            return sveResult(sveBuiltin("tbl", operands, for: bytes), for: bytes)
        case .x86: return x86TableLookup(table, indices, for: bytes)
        }
    }

    func sumsOfBytes(_ bytes: String, for element: Element) -> String {
        let lanes = unsignedElement(of: element).at(width: element.width)
        switch self {
        case .neon:
            var summed = bytes
            for bits in [16, 32, 64] {
                let widened = unsignedElement(bits: bits).at(width: element.width)
                summed = neonBuiltin(
                    "vpaddlq_v",
                    [summed],
                    code: neonTypeCode(of: widened),
                    for: widened
                )
            }
            return summed
        case .sve:
            let byteLanes = unsignedElement(bits: 8).at(width: element.width)
            let words = unsignedElement(bits: 32).at(width: element.width)
            let sums = sveBuiltin(
                "dot_n",
                [sveBuiltin("dup_n", ["0"], for: words), sveOperand(bytes, for: byteLanes), "1"],
                for: words
            )
            let accumulated = sveBuiltin(
                "adalp",
                [sveAllLanes(of: lanes), sveBuiltin("dup_n", ["0"], for: lanes), sums],
                for: lanes,
                predication: "x"
            )
            return sveResult(accumulated, for: lanes)
        case .x86:
            let signedBytes = x86Vector("i8")
            return x86Builtin(
                "psadbw\(x86Bits(element.width))",
                [
                    (value: bytes, type: signedBytes),
                    (value: compoundLiteral(signedBytes, ["0"]), type: signedBytes),
                ],
                returning: lanes.cVector
            )
        }
    }
}

func mulBitsMultiRotatedRightLookup(
    _ target: MulBitsByteLookup,
    scalingByPowers: Bool = false,
    for element: Element
) -> String {
    let (bytes, words, lanes) = mulBitsByteVectors(for: element)
    let size = element.width
    func bytesOf(_ value: Int) -> String {
        splat("\(value)", as: bytes.cVector, lanes: size)
    }
    func zipped(upper: Bool) -> String {
        laneIndices(
            (0..<size / 16).flatMap { block in
                (0..<8).flatMap { lane in
                    let first = 16 * block + lane + (upper ? 8 : 0)
                    return [first, size + first]
                }
            }
        )
    }
    let packed = laneIndices(
        (0..<size / 16).flatMap { block in
            (0..<8).map { 16 * block + 2 * $0 } + (0..<8).map { size + 16 * block + 2 * $0 }
        }
    )
    let duplicatedEven = laneIndices((0..<element.laneCount).map { $0 & ~1 })
    let duplicatedOdd = laneIndices((0..<element.laneCount).map { $0 | 1 })
    let powers = compoundLiteral(
        bytes.cVector,
        (0..<size).map { $0 % 16 < 8 ? String(128 >> ($0 % 16)) : "0" }
    )
    func segments(_ name: String, duplicated: String, upper: Bool) -> String {
        let extraction =
            scalingByPowers
            ? "((\(words.cVector))\(name)Segments * \(name)Counts) >> 7"
            : "(\(words.cVector))\(name)Segments >> \(name)Counts"
        return """
            const \(bytes.cVector) \(name)Source = (\(bytes.cVector))__builtin_shufflevector(values, values, \(duplicated));
            const \(bytes.cVector) \(name)Indices = __builtin_shufflevector(byteIndices, nextIndices, \(zipped(upper: upper)));
            const \(bytes.cVector) \(name)Segments = \(target.lookup("\(name)Source", "\(name)Indices", for: element));
            const \(words.cVector) \(name)Counts = (\(words.cVector))__builtin_shufflevector(\(scalingByPowers ? "powers" : "bitCounts"), \(bytesOf(0)), \(zipped(upper: upper)));
            const \(words.cVector) \(name)Extracted = \(extraction);
            """
    }
    let scaling =
        scalingByPowers
        ? """
        const \(bytes.cVector) powersTable = \(powers);
        const \(bytes.cVector) powers = \(target.lookup("powersTable", "bitCounts", for: element));

        """ : ""
    return """
        const \(bytes.cVector) indices = (\(bytes.cVector))b;
        const \(lanes.cVector) values = (\(lanes.cVector))a;
        const \(bytes.cVector) masked = indices & \(bytesOf(63));
        const \(bytes.cVector) byteIndices = masked >> 3;
        const \(bytes.cVector) nextIndices = byteIndices + \(bytesOf(1));
        const \(bytes.cVector) bitCounts = masked & \(bytesOf(7));
        \(scaling)\(segments("even", duplicated: duplicatedEven, upper: false))
        \(segments("odd", duplicated: duplicatedOdd, upper: true))
        \(vectorResult("__builtin_shufflevector((\(bytes.cVector))evenExtracted, (\(bytes.cVector))oddExtracted, \(packed))", for: element))
        """
}

func mulBitsBitShuffledLookup(
    _ target: MulBitsByteLookup,
    avx3: Bool = false,
    for element: Element
) -> String {
    let (bytes, words, lanes) = mulBitsByteVectors(for: element)
    let size = element.width
    func bytesOf(_ value: Int) -> String {
        splat("\(value)", as: bytes.cVector, lanes: size)
    }
    func wordsOf(_ value: String) -> String {
        splat(value, as: words.cVector, lanes: size / 2)
    }
    func interleaved(_ even: String, _ odd: String) -> String {
        let indices = laneIndices((0..<size).map { $0 % 2 == 0 ? $0 : size + $0 })
        return
            "__builtin_shufflevector((\(bytes.cVector))\(even), (\(bytes.cVector))\(odd), \(indices))"
    }
    let upperHalves = compoundLiteral(
        lanes.cVector,
        (0..<element.laneCount).map { $0 % 2 == 0 ? "0" : "0x0808080808080808ull" }
    )
    let indexMask = splat("0x0707070707070707ull", as: lanes.cVector, lanes: element.laneCount)
    let selectedBits = splat("0x8040201008040201ull", as: lanes.cVector, lanes: element.laneCount)
    let byteIndices =
        avx3
        ? x86Builtin(
            "pternlogq\(x86Bits(size))_mask",
            [
                (value: indexMask, type: x86Vector("i64")),
                (value: "((\(words.cVector))indices >> 3)", type: x86Vector("i64")),
                (value: upperHalves, type: x86Vector("i64")),
                (value: "0xca", type: "int"),
                (value: "-1", type: x86MaskType(lanes: element.laneCount)),
            ],
            returning: bytes.cVector
        )
        : "(\(bytes.cVector))(((\(lanes.cVector))(indices >> 3) & \(indexMask)) | \(upperHalves))"
    let rotation =
        avx3
        ? """
        const \(words.cVector) tableWords = (\(words.cVector))tableBytes;
        const \(words.cVector) leftCounts = (\(words.cVector))counts;
        const \(words.cVector) rightCounts = (\(words.cVector))(\(bytes.cVector))(-counts);
        const \(words.cVector) evenLeft = tableWords << (leftCounts & \(wordsOf("7")));
        const \(words.cVector) oddLeft = (tableWords & \(wordsOf("0xff00"))) << ((leftCounts >> 8) & \(wordsOf("7")));
        const \(words.cVector) evenRight = (tableWords & \(wordsOf("0x00ff"))) >> (rightCounts & \(wordsOf("7")));
        const \(words.cVector) oddRight = tableWords >> ((rightCounts >> 8) & \(wordsOf("7")));
        const \(bytes.cVector) rotated = \(interleaved("evenLeft", "oddLeft")) | \(interleaved("evenRight", "oddRight"));
        """
        : """
        const \(bytes.cVector) leftCounts = counts & \(bytesOf(7));
        const \(bytes.cVector) rightCounts = (\(bytes.cVector))(-counts) & \(bytesOf(7));
        const \(bytes.cVector) shiftedLeft = tableBytes << leftCounts;
        const \(bytes.cVector) shiftedRight = tableBytes >> rightCounts;
        const \(bytes.cVector) rotated = shiftedLeft | shiftedRight;
        """
    return """
        const \(bytes.cVector) indices = (\(bytes.cVector))b;
        const \(bytes.cVector) byteIndices = \(byteIndices);
        const \(bytes.cVector) counts = \(iota(as: bytes.cVector, lanes: size)) - indices;
        const \(bytes.cVector) looked = (\(bytes.cVector))a;
        const \(bytes.cVector) tableBytes = \(target.lookup("looked", "byteIndices", for: element));
        \(rotation)
        const \(lanes.cVector) extracted = (\(lanes.cVector))rotated & \(selectedBits);
        \(vectorResult(target.sumsOfBytes("extracted", for: element), for: element))
        """
}

func mulBitsMultiRotatedRightX86Multishift(for element: Element) -> String {
    let shifted = x86Builtin(
        "vpmultishiftqb\(x86Bits(element.width))",
        ["b", "a"],
        as: "i8",
        returning: element.cVector
    )
    return vectorResult(shifted, for: element)
}

func mulBitsBitShuffledX86Shuffling(for element: Element) -> String {
    let maskType = x86MaskType(lanes: element.width)
    let lanes = unsignedElement(of: element).at(width: element.width)
    let bits = x86Builtin(
        "vpshufbitqmb\(x86Bits(element.width))_mask",
        [
            (value: "a", type: x86Vector("i8")), (value: "b", type: x86Vector("i8")),
            (value: "-1", type: maskType),
        ],
        returning: maskType
    )
    return """
        \(vectorTypedef("mask_bytes", of: unsignedElement(bits: 8), lanes: element.laneCount))
        const \(maskType) bits = \(bits);
        \(vectorResult("__builtin_convertvector(__builtin_bit_cast(mask_bytes, bits), \(lanes.cVector))", for: element))
        """
}

func mulBitsByteIndexedOps(
    _ swiftName: String,
    _ highwayName: String,
    section: Section,
    targets: TargetBodies<Element>,
    portable: @escaping (Element) -> String
) -> [Op] {
    sourcedOps(accepting: mulBitsByteIndexedAccepts) { source, results in
        Op(
            swiftName,
            highwayName,
            [.vector, .sourceVector],
            .vector,
            results,
            section: section,
            vectorLabels: ["_", "by"],
            source: source,
            targets: targets,
            portable: sourced(source) { _, result in portable(result) }
        )
    }
}

let mulBitsMultiRotatedRightOps = mulBitsByteIndexedOps(
    "multiRotatedRight",
    "MultiRotateRight",
    section: .shifts,
    targets: TargetBodies(
        neon: { element in mulBitsMultiRotatedRightLookup(.neon, for: element) },
        sve2_128: { element in mulBitsMultiRotatedRightLookup(.sve, for: element) },
        avx3dl: { element in mulBitsMultiRotatedRightX86Multishift(for: element) },
        avx3: { element in mulBitsMultiRotatedRightLookup(.x86, for: element) },
        avx2: { element in mulBitsMultiRotatedRightLookup(.x86, for: element) },
        ssse3: { element in
            mulBitsMultiRotatedRightLookup(.x86, scalingByPowers: true, for: element)
        }
    ),
    portable: mulBitsMultiRotatedRight
)

let mulBitsBitShuffledOps = mulBitsByteIndexedOps(
    "bitShuffled",
    "BitShuffle",
    section: .blockwise,
    targets: TargetBodies(
        neon: { element in mulBitsBitShuffledLookup(.neon, for: element) },
        sve2_128: { element in mulBitsBitShuffledLookup(.sve, for: element) },
        avx3dl: { element in mulBitsBitShuffledX86Shuffling(for: element) },
        avx3: { element in mulBitsBitShuffledLookup(.x86, avx3: true, for: element) },
        avx2: { element in mulBitsBitShuffledLookup(.x86, for: element) },
        ssse3: { element in mulBitsBitShuffledLookup(.x86, for: element) }
    ),
    portable: mulBitsBitShuffled
)

let mulBitsOps: [Op] =
    mulBitsBiasedExponentOps + mulBitsPowerOf2Ops + mulBitsMultiplyingEvenOps
    + mulBitsMultiplyingOddOps + mulBitsMultiRotatedRightOps + mulBitsBitShuffledOps

typealias WidenMulKernel = (statements: String, value: String)

func widenMulBody(
    _ kernel: WidenMulKernel,
    masked: Bool = false,
    nativeMask: Bool = false,
    for result: Element
) -> String {
    let finished: String
    if !masked {
        finished = vectorResult(kernel.value, for: result)
    } else if nativeMask {
        finished = x86Avx3ZeroMasked(kernel.value, for: result)
    } else {
        finished = maskedSelecting(kernel.value, merging: false, for: result)
    }
    return [kernel.statements, finished].filter { !$0.isEmpty }.joined(separator: "\n")
}

func widenMulLanes(
    _ operand: String,
    stride: Int,
    offset: Int,
    to result: Element
) -> String {
    let kept = (0..<result.laneCount).map { stride * $0 + offset }
    return convertedLanes(operand, at: kept, to: result.cVector)
}

func widenMulSum(_ terms: [String], for result: Element) -> String {
    guard result.category == .signedInteger else { return "(\(terms.joined(separator: " + ")))" }
    let wrapped = terms.map { "(\(result.cUnsignedVector))\($0)" }
    return "(\(result.cVector))(\(wrapped.joined(separator: " + ")))"
}

func widenMulProducts(
    _ first: String,
    _ second: String,
    stride: Int,
    to result: Element
) -> [String] {
    (0..<stride).map { offset in
        let lanes = [first, second].map {
            widenMulLanes($0, stride: stride, offset: offset, to: result)
        }
        return "(\(lanes[0]) * \(lanes[1]))"
    }
}

func widenMulPairwiseAccepts(_ source: Element, _ result: Element) -> Bool {
    source.category != .float && source.category == result.category && source.bits == 16
        && result.bits == 32
}

func widenMulPairwisePortable(
    _ first: String,
    _ second: String,
    to result: Element
) -> String {
    widenMulSum(widenMulProducts(first, second, stride: 2, to: result), for: result)
}

func widenMulPairwiseNeon(
    _ first: String,
    _ second: String,
    to result: Element
) -> WidenMulKernel {
    let (halves, quads) = (neonVector("i8x8"), neonVector("i8"))
    let lanes = result.laneCount
    func product(_ range: Range<Int>) -> String {
        let operands = [first, second].map {
            "(\(halves))__builtin_shufflevector(\($0), \($0), \(laneIndices(range)))"
        }
        let code = neonTypeCode(of: result)
        return "__builtin_neon_vmull_v(\(operands[0]), \(operands[1]), \(code))"
    }
    let sums = "__builtin_neon_vpaddq_v(low, high, \(neonTypeCode(of: result)))"
    return (
        """
        const \(quads) high = \(product(lanes..<2 * lanes));
        const \(quads) low = \(product(0..<lanes));
        """,
        "(\(result.cVector))\(sums)"
    )
}

func widenMulPairwiseSveCall(
    _ first: String,
    _ second: String,
    from source: Element,
    to result: Element
) -> String {
    let operands = [first, second].map { sveSplatOperand($0, for: source) }
    let even = sveBuiltin("mullb", operands, for: result)
    return sveBuiltin("mlalt", [even] + operands, for: result)
}

func widenMulPairwiseSve(
    _ first: String,
    _ second: String,
    from source: Element,
    to result: Element
) -> String {
    sveResult(widenMulPairwiseSveCall(first, second, from: source, to: result), for: result)
}

func widenMulPairwiseX86(
    _ first: String,
    _ second: String,
    level: X86Level,
    from source: Element,
    to result: Element
) -> WidenMulKernel {
    let bits = x86Bits(result.width)
    guard result.category == .unsignedInteger else {
        let product = x86Builtin(
            "pmaddwd\(bits)",
            [first, second],
            as: "i16",
            returning: result.cVector
        )
        return ("", product)
    }
    let lanes = source.laneCount
    let high = x86Builtin("pmulhuw\(bits)", [first, second], as: "i16", returning: source.cVector)
    let oddEven = laneIndices((0..<lanes).map { $0 % 2 == 1 ? $0 : lanes + $0 })
    let blended =
        level >= .avx3
        ? "__builtin_shufflevector(highs, lows, \(oddEven))"
        : x86SelectedOddEven(odd: "highs", even: "lows", level: level, for: source)
    let crossed = "(((\(result.cVector))highs << 16) | ((\(result.cVector))lows >> 16))"
    return (
        """
        const \(source.cVector) lows = \(first) * \(second);
        const \(source.cVector) highs = \(high);
        """,
        "(((\(result.cVector))\(blended)) + \(crossed))"
    )
}

func widenMulPairwiseTargets(masked: Bool, from source: Element) -> TargetBodies<Element> {
    func body(
        nativeMask: Bool = false,
        _ kernel: @escaping (Element, Element) -> WidenMulKernel
    ) -> (Element) -> String? {
        sourced(source) { source, result in
            widenMulBody(
                kernel(source, result),
                masked: masked,
                nativeMask: nativeMask,
                for: result
            )
        }
    }
    func x86(_ level: X86Level, nativeMask: Bool = false) -> (Element) -> String? {
        body(nativeMask: nativeMask) { source, result in
            widenMulPairwiseX86("a", "b", level: level, from: source, to: result)
        }
    }
    return TargetBodies(
        neon: body { _, result in widenMulPairwiseNeon("a", "b", to: result) },
        sve2_128: body { source, result in
            ("", widenMulPairwiseSve("a", "b", from: source, to: result))
        },
        avx3: x86(.avx3, nativeMask: true),
        avx2: x86(.avx2),
        sse4: x86(.sse4),
        sse2: x86(.sse2)
    )
}

func widenMulPairwiseOps(masked: Bool) -> [Op] {
    sourcedOps(accepting: widenMulPairwiseAccepts) { source, results in
        Op(
            "multiplyPairwiseAdding",
            masked ? "MaskedWidenMulPairwiseAdd" : "WidenMulPairwiseAdd",
            [.tag] + (masked ? [.whereMask] : []) + [.sourceVector, .sourceVector],
            .vector,
            results,
            section: masked ? .zeroMaskedArithmetic : .multiply,
            source: source,
            targets: widenMulPairwiseTargets(masked: masked, from: source),
            portable: sourced(source) { _, result in
                widenMulBody(
                    ("", widenMulPairwisePortable("a", "b", to: result)),
                    masked: masked,
                    for: result
                )
            }
        )
    }
}

func widenMulSaturatingPairwiseAccepts(_ source: Element, _ result: Element) -> Bool {
    source.category == .unsignedInteger && source.bits == 8 && result.category == .signedInteger
        && result.bits == 16
}

func widenMulSaturatingPairwisePortable(to result: Element) -> WidenMulKernel {
    let (vector, unsigned) = (result.cVector, unsignedElement(of: result).cVector)
    let mask = splat("0x00FF", as: vector, lanes: result.laneCount)
    return (
        """
        const \(vector) a0 = (\(vector))a & \(mask);
        const \(vector) b0 = (\(vector))((\(unsigned))b << 8) >> 8;
        const \(vector) a1 = (\(vector))((\(unsigned))a >> 8);
        const \(vector) b1 = (\(vector))b >> 8;
        """,
        "__builtin_elementwise_add_sat(a0 * b0, a1 * b1)"
    )
}

func widenMulSaturatingPairwiseX86(to result: Element) -> String {
    let product = x86Builtin(
        "pmaddubsw\(x86Bits(result.width))",
        ["a", "b"],
        as: "i8",
        returning: result.cVector
    )
    return vectorResult(product, for: result)
}

let widenMulSaturatingPairwiseOps = sourcedOps(accepting: widenMulSaturatingPairwiseAccepts) {
    source,
    results in
    func x86() -> (Element) -> String? {
        sourced(source) { _, result in widenMulSaturatingPairwiseX86(to: result) }
    }
    return Op(
        "saturatingMultiplyPairwiseAdding",
        "SatWidenMulPairwiseAdd",
        [.tag, .sourceVector, .signedSourceVector],
        .vector,
        results,
        section: .multiply,
        source: source,
        targets: TargetBodies(avx3: x86(), avx2: x86(), ssse3: x86()),
        portable: sourced(source) { _, result in
            widenMulBody(widenMulSaturatingPairwisePortable(to: result), for: result)
        }
    )
}

func widenMulAccumulatingAccepts(_ source: Element, _ result: Element) -> Bool {
    source.category == .signedInteger && source.bits == 16 && result.category == .signedInteger
        && result.bits == 32
}

func widenMulAccumulatingTail(
    _ product: String,
    blending: Bool = false,
    for result: Element
) -> WidenMulKernel {
    let (vector, unsigned) = (result.cVector, result.cUnsignedVector)
    let lowest = splat(lowestValue(of: result), as: vector, lanes: result.laneCount)
    let highest = splat(highestValue(of: result), as: vector, lanes: result.laneCount)
    let shift = result.bits - 1
    var statements = [
        "const \(vector) product = \(product);",
        "const \(vector) overflow = (\(vector))(product == \(lowest));",
        "const \(vector) adjusted = (\(vector))((\(unsigned))c - (\(unsigned))((c >> \(shift)) & overflow));",
        "const \(vector) bumped = (\(vector))((\(unsigned))product + (\(unsigned))overflow);",
    ]
    guard blending else {
        let sum = "__builtin_elementwise_add_sat(adjusted, bumped)"
        return (statements.joined(separator: "\n"), sum)
    }
    let signs = x86Builtin(
        "psradi\(x86Bits(result.width))",
        [(value: "adjusted", type: x86Vector("i32")), (value: String(shift), type: "int")],
        returning: vector
    )
    let words = x86Vector("i64")
    statements += [
        "const \(vector) sum = (\(vector))((\(unsigned))adjusted + (\(unsigned))bumped);",
        "const \(words) overflows = ~((\(words))adjusted ^ (\(words))bumped) & ((\(words))adjusted ^ (\(words))sum);",
        "const \(words) limits = (\(words))\(signs) ^ (\(words))\(highest);",
    ]
    let selected = x86Builtin(
        "blendvps\(x86UnsuffixedBits(result.width))",
        ["sum", "limits", "overflows"],
        as: "f32",
        returning: vector
    )
    return (statements.joined(separator: "\n"), selected)
}

func widenMulAccumulatingSve(from source: Element, to result: Element) -> String {
    let (type, all) = (sveType(of: result), sveAllLanes(of: result))
    let lowest = sveBuiltin("dup_n", [lowestValue(of: result)], for: result)
    let overflowing = sveBuiltin("cmpeq", [all, "product", lowest], for: result)
    let ones = sveBuiltin("dup_n", ["-1"], for: result)
    let zeros = sveBuiltin("dup_n", ["0"], for: result)
    let signs = sveBuiltin(
        "asr_n",
        [all, "sum", String(result.bits - 1)],
        for: result,
        predication: "x"
    )
    func combined(_ name: String, _ first: String, _ second: String) -> String {
        sveBuiltin(name, [all, first, second], for: result, predication: "x")
    }
    let adjusted = combined("sub", "sum", combined("and", signs, "overflow"))
    let saturated = sveBuiltin(
        "qadd",
        [adjusted, combined("add", "product", "overflow")],
        for: result
    )
    return """
        const \(type) product = \(widenMulPairwiseSveCall("a", "b", from: source, to: result));
        const \(type) overflow = \(sveBuiltin("sel", [overflowing, ones, zeros], for: result));
        const \(type) sum = \(sveSplatOperand("c", for: result));
        \(vectorResult(sveResult(saturated, for: result), for: result))
        """
}

func widenMulAccumulatingX86Native(
    _ first: String,
    _ second: String,
    to result: Element
) -> String {
    let vector = x86Vector("i32")
    let accumulated = x86Builtin(
        "vpdpwssds\(x86Bits(result.width))",
        [(value: "c", type: vector), (value: first, type: vector), (value: second, type: vector)],
        returning: result.cVector
    )
    return vectorResult(accumulated, for: result)
}

let widenMulAccumulatingOps = sourcedOps(accepting: widenMulAccumulatingAccepts) {
    source,
    results in
    func x86(_ level: X86Level) -> (Element) -> String? {
        sourced(source) { source, result in
            if level >= .avx3dl { return widenMulAccumulatingX86Native("a", "b", to: result) }
            let product = widenMulPairwiseX86("a", "b", level: level, from: source, to: result)
            let tail = widenMulAccumulatingTail(
                product.value,
                blending: level == .sse4,
                for: result
            )
            return widenMulBody(
                (product.statements + "\n" + tail.statements, tail.value),
                for: result
            )
        }
    }
    return Op(
        "saturatingMultiplyPairwiseAccumulating",
        "SatWidenMulPairwiseAccumulate",
        [.tag, .sourceVector, .sourceVector, .vector],
        .vector,
        results,
        section: .multiply,
        source: source,
        targets: TargetBodies(
            neon: sourced(source) { _, result in
                let product = widenMulPairwiseNeon("a", "b", to: result)
                let tail = widenMulAccumulatingTail(product.value, for: result)
                return widenMulBody(
                    (product.statements + "\n" + tail.statements, tail.value),
                    for: result
                )
            },
            sve2_128: sourced(source) { source, result in
                widenMulAccumulatingSve(from: source, to: result)
            },
            avx3dl: x86(.avx3dl),
            avx3: x86(.avx3),
            avx2: x86(.avx2),
            sse4: x86(.sse4),
            sse2: x86(.sse2)
        ),
        portable: sourced(source) { _, result in
            widenMulBody(
                widenMulAccumulatingTail(
                    widenMulPairwisePortable("a", "b", to: result),
                    for: result
                ),
                for: result
            )
        }
    )
}

func widenMulQuadAccepts(_ source: Element, _ result: Element) -> Bool {
    source.category != .float && source.category == result.category
        && (source.bits == 8 || source.bits == 16) && result.bits == 4 * source.bits
}

func widenMulMixedQuadAccepts(_ source: Element, _ result: Element) -> Bool {
    source.category == .unsignedInteger && source.bits == 8 && result.category == .signedInteger
        && result.bits == 32
}

func widenMulQuadPortable(to result: Element) -> WidenMulKernel {
    guard result.bits == 64 else {
        let products = widenMulProducts("a", "b", stride: 4, to: result)
        return ("", widenMulSum(products + ["c"], for: result))
    }
    let (middle, vector) = (resizedElement(of: result, bits: 32).cVector, result.cVector)
    func products(part: Int) -> String {
        let lanes = ["a", "b"].map { convertedPart($0, part: part, lanes: 4, to: middle) }
        return "\(lanes[0]) * \(lanes[1])"
    }
    func pairs(_ operand: String) -> String {
        let sums = [[0, 2], [1, 3]].map { convertedLanes(operand, at: $0, to: vector) }
        return "\(sums[0]) + \(sums[1])"
    }
    let statements = """
        const \(middle) lows = \(products(part: 0));
        const \(middle) highs = \(products(part: 1));
        const \(vector) lowSums = \(pairs("lows"));
        const \(vector) highSums = \(pairs("highs"));
        const \(vector) sums = __builtin_shufflevector(lowSums, highSums, 0, 2) + __builtin_shufflevector(lowSums, highSums, 1, 3);
        """
    return (statements, widenMulSum(["c", "sums"], for: result))
}

func widenMulChoice(_ branches: [(condition: String, body: String)], otherwise: String) -> String {
    let chain = branches.enumerated().flatMap { index, branch in
        ["#\(index == 0 ? "if" : "elif") \(branch.condition)", branch.body]
    }
    return (chain + ["#else", otherwise, "#endif"]).joined(separator: "\n")
}

func widenMulWords() -> Element {
    signedElement(of: unsignedElement(bits: 16))
}

func widenMulNeonDot(
    _ sum: String,
    _ first: String,
    _ second: String,
    to result: Element
) -> String {
    let name = "vdotq_\(result.category == .signedInteger ? "s" : "u")32"
    return neonBuiltin(name, [sum, first, second], code: neonTypeCode(of: result), for: result)
}

func widenMulNeonPairs(_ product: (Int) -> String, to result: Element) -> String {
    let code = neonTypeCode(of: result)
    let paired = (0..<2).map { "__builtin_neon_vpaddlq_v(\(product($0)), \(code))" }
    let sums = "__builtin_neon_vpaddq_v(\(paired[0]), \(paired[1]), \(code))"
    return widenMulSum(["(\(result.cVector))\(sums)", "c"], for: result)
}

func widenMulNeonWidening(from source: Element, to result: Element, mixed: Bool) -> String {
    let (halves, quads) = (neonVector("i8x8"), neonVector("i8"))
    let half = source.laneCount / 2
    let kept = { (part: Int) in Array(part * half..<(part + 1) * half) }
    guard mixed else {
        let middle = resizedElement(of: result, bits: 2 * source.bits)
        return widenMulNeonPairs(
            { part in
                let operands = ["a", "b"].map {
                    "(\(halves))__builtin_shufflevector(\($0), \($0), \(laneIndices(kept(part))))"
                }
                let code = neonTypeCode(of: middle)
                return "__builtin_neon_vmull_v(\(operands[0]), \(operands[1]), \(code))"
            },
            to: result
        )
    }
    return widenMulNeonPairs(
        { part in
            let operands = ["a", "b"].map {
                convertedLanes($0, at: kept(part), to: widenMulWords().cVector)
            }
            return "(\(quads))(\(operands[0]) * \(operands[1]))"
        },
        to: result
    )
}

func widenMulSignCorrected(
    dot: (_ sum: String, _ first: String, _ second: String) -> String,
    for result: Element
) -> String {
    let bytes = unsignedElement(bits: 8).cVector
    let words = unsignedElement(of: result).cVector
    return """
        const \(bytes) unsignedB = (\(bytes))b;
        const \(words) unsignedC = (\(words))c;
        const \(words) first = \(dot("unsignedC", "a", "unsignedB"));
        const \(bytes) signs = unsignedB >> 7;
        const \(words) zero = (\(words)){0};
        const \(words) second = \(dot("zero", "a", "signs"));
        \(vectorResult("(\(result.cVector))(first - (second << 8))", for: result))
        """
}

func widenMulQuadNeon(from source: Element, to result: Element, mixed: Bool) -> String {
    let widening = vectorResult(
        widenMulNeonWidening(from: source, to: result, mixed: mixed),
        for: result
    )
    guard source.bits == 8 else { return widening }
    guard mixed else {
        let native = vectorResult(widenMulNeonDot("c", "a", "b", to: result), for: result)
        return widenMulChoice([("defined(__ARM_FEATURE_DOTPROD)", native)], otherwise: widening)
    }
    let unsigned = unsignedElement(of: result).at(width: result.width)
    let native = vectorResult(
        neonBuiltin("vusdotq_s32", ["c", "a", "b"], code: neonTypeCode(of: result), for: result),
        for: result
    )
    let corrected = widenMulSignCorrected(
        dot: { widenMulNeonDot($0, $1, $2, to: unsigned) },
        for: result
    )
    return widenMulChoice(
        [
            ("defined(__ARM_FEATURE_MATMUL_INT8)", native),
            ("defined(__ARM_FEATURE_DOTPROD)", corrected),
        ],
        otherwise: widening
    )
}

func widenMulSveDot(
    _ name: String,
    _ operands: (sum: String, first: String, second: String),
    elements: (first: Element, second: Element),
    to result: Element
) -> String {
    let arguments = [
        sveSplatOperand(operands.sum, for: result),
        sveSplatOperand(operands.first, for: elements.first),
        sveSplatOperand(operands.second, for: elements.second),
    ]
    return sveResult(sveBuiltin(name, arguments, for: result), for: result)
}

func widenMulQuadSve(from source: Element, to result: Element, mixed: Bool) -> String {
    let second = mixed ? signedElement(of: source).at(width: source.width) : source
    let dot = vectorResult(
        widenMulSveDot("dot", ("c", "a", "b"), elements: (source, second), to: result),
        for: result
    )
    guard mixed else { return dot }
    let native = vectorResult(
        widenMulSveDot("usdot", ("c", "a", "b"), elements: (source, second), to: result),
        for: result
    )
    let unsigned = unsignedElement(of: result).at(width: result.width)
    let corrected = widenMulSignCorrected(
        dot: { widenMulSveDot("dot", ($0, $1, $2), elements: (source, source), to: unsigned) },
        for: result
    )
    return widenMulChoice([("defined(__ARM_FEATURE_MATMUL_INT8)", native)], otherwise: corrected)
}

func widenMulQuadX86Bytes(from source: Element, to result: Element, mixed: Bool) -> String {
    let words = widenMulWords().cVector
    let unsignedWords = unsignedElement(bits: 16).cVector
    let wide = signedElement(of: result).at(width: result.width)
    let isFirstSigned = source.category == .signedInteger
    let isSecondSigned = isFirstSigned || mixed
    let mask = splat("0x00FF", as: words, lanes: result.laneCount * 2)
    func evens(_ name: String, isSigned: Bool) -> String {
        isSigned ? "(\(words))((\(unsignedWords))\(name) << 8) >> 8" : "(\(words))\(name) & \(mask)"
    }
    func odds(_ name: String, isSigned: Bool) -> String {
        isSigned ? "(\(words))\(name) >> 8" : "(\(words))((\(unsignedWords))\(name) >> 8)"
    }
    let products = ["0", "1"].map {
        widenMulPairwiseX86("a\($0)", "b\($0)", level: .sse2, from: source, to: wide).value
    }
    let total = widenMulSum(products.map { "(\(result.cVector))\($0)" }, for: result)
    return """
        const \(words) a0 = \(evens("a", isSigned: isFirstSigned));
        const \(words) b0 = \(evens("b", isSigned: isSecondSigned));
        const \(words) a1 = \(odds("a", isSigned: isFirstSigned));
        const \(words) b1 = \(odds("b", isSigned: isSecondSigned));
        \(vectorResult(widenMulSum(["c", total], for: result), for: result))
        """
}

func widenMulQuadX86Native(from source: Element, to result: Element, mixed: Bool) -> String {
    let vector = x86Vector("i32")
    func dot(_ sum: String, _ first: String, _ second: String) -> String {
        x86Builtin(
            "vpdpbusd\(x86Bits(result.width))",
            [
                (value: sum, type: vector), (value: first, type: vector),
                (value: second, type: vector),
            ],
            returning: result.cVector
        )
    }
    guard !mixed else { return vectorResult(dot("c", "a", "b"), for: result) }
    let bytes = signedElement(of: unsignedElement(bits: 8)).at(width: result.width)
    let signs = x86GaloisAffine("b", matrix: 0x8080_8080_8080_8080, for: bytes)
    let zero = compoundLiteral(vector, ["0"])
    let correction =
        source.category == .signedInteger
        ? dot(zero, "((\(unsignedElement(bits: 8).cVector))a >> 7)", "b") : dot(zero, "a", signs)
    let unsigned = result.cUnsignedVector
    return """
        const \(result.cVector) first = \(dot("c", "a", "b"));
        const \(result.cVector) second = \(correction);
        \(vectorResult("(\(result.cVector))((\(unsigned))first - ((\(unsigned))second << 8))", for: result))
        """
}

func widenMulQuadX86Words(level: X86Level, from source: Element, to result: Element) -> String {
    let (vector, unsigned) = (result.cVector, result.cUnsignedVector)
    let low = splat("0xFFFFFFFF", as: unsigned, lanes: result.laneCount)
    guard source.category == .signedInteger else {
        let lanes = source.laneCount
        let words = unsignedElement(bits: 32).cVector
        let oddEven = laneIndices((0..<lanes).map { $0 % 2 == 1 ? $0 : lanes + $0 })
        func blended(_ odd: String, _ even: String) -> String {
            level >= .avx3
                ? "__builtin_shufflevector(\(odd), \(even), \(oddEven))"
                : x86SelectedOddEven(odd: odd, even: even, level: level, for: source)
        }
        let shifted = [
            "(\(source.cVector))((\(words))highs << 16)",
            "(\(source.cVector))((\(words))lows >> 16)",
        ]
        let high = x86Builtin(
            "pmulhuw\(x86Bits(source.width))",
            ["a", "b"],
            as: "i16",
            returning: source.cVector
        )
        return """
            const \(source.cVector) lows = a * b;
            const \(source.cVector) highs = \(high);
            const \(unsigned) evens = (\(unsigned))(\(words))\(blended(shifted[0], "lows"));
            const \(unsigned) odds = (\(unsigned))(\(words))\(blended("highs", shifted[1]));
            \(vectorResult("(\(vector))((\(unsigned))c + (((evens & \(low)) + (odds & \(low))) + ((evens >> 32) + (odds >> 32))))", for: result))
            """
    }
    let wide = signedElement(of: unsignedElement(bits: 32)).at(width: result.width)
    let lowest = splat(lowestValue(of: wide), as: wide.cVector, lanes: wide.laneCount)
    let highMask = splat("0xFFFFFFFF00000000", as: unsigned, lanes: result.laneCount)
    let product = x86Builtin(
        "pmaddwd\(x86Bits(source.width))",
        ["a", "b"],
        as: "i16",
        returning: wide.cVector
    )
    let blend = laneIndices((0..<wide.laneCount).map { $0 % 2 == 0 ? $0 : wide.laneCount + $0 })
    let highSums =
        level >= .avx3
        ? "(\(unsigned))(((\(vector))sums) >> 32)"
        : "(\(unsigned))__builtin_shufflevector((\(wide.cVector))(sums >> 32), products >> 31, \(blend))"
    return """
        const \(wide.cVector) products = \(product);
        const \(wide.cVector) overflows = (\(wide.cVector))(products == \(lowest));
        const \(unsigned) sums = (\(unsigned))products;
        const \(unsigned) flags = (\(unsigned))overflows;
        const \(unsigned) lows = (\(unsigned))(((\(vector))(sums << 32)) >> 32) & ~(flags << 32);
        const \(unsigned) highs = \(highSums) & ~(flags & \(highMask));
        \(vectorResult("(\(vector))((\(unsigned))c + (lows + highs))", for: result))
        """
}

func widenMulQuadTargets(mixed: Bool, from source: Element) -> TargetBodies<Element> {
    func body(_ make: @escaping (Element, Element) -> String) -> (Element) -> String? {
        sourced(source) { source, result in make(source, result) }
    }
    func x86(_ level: X86Level) -> (Element) -> String? {
        body { source, result in
            guard source.bits == 8 else {
                return widenMulQuadX86Words(level: level, from: source, to: result)
            }
            return level >= .avx3dl
                ? widenMulQuadX86Native(from: source, to: result, mixed: mixed)
                : widenMulQuadX86Bytes(from: source, to: result, mixed: mixed)
        }
    }
    return TargetBodies(
        neon: body { widenMulQuadNeon(from: $0, to: $1, mixed: mixed) },
        sve2_128: body { widenMulQuadSve(from: $0, to: $1, mixed: mixed) },
        avx3dl: x86(.avx3dl),
        avx3: x86(.avx3),
        avx2: x86(.avx2),
        sse4: x86(.sse4),
        sse2: x86(.sse2)
    )
}

func widenMulQuadOps(mixed: Bool) -> [Op] {
    sourcedOps(accepting: mixed ? widenMulMixedQuadAccepts : widenMulQuadAccepts) {
        source,
        results in
        Op(
            "multiplyQuadAccumulating",
            "SumOfMulQuadAccumulate",
            [.tag, .sourceVector, mixed ? .signedSourceVector : .sourceVector, .vector],
            .vector,
            results,
            section: .multiply,
            source: source,
            targets: widenMulQuadTargets(mixed: mixed, from: source),
            portable: sourced(source) { _, result in
                widenMulBody(widenMulQuadPortable(to: result), for: result)
            }
        )
    }
}

let widenMulCornerIdentifiers: Set<String> = [
    "saturatingMultiplyPairwiseAccumulating", "multiplyQuadAccumulating",
    "saturatingMultiplyAccumulatingFixedPoint",
]

func widenMulCornerTests(of op: Op, for element: Element) -> [String] {
    guard widenMulCornerIdentifiers.contains(op.identifier) else { return [] }
    let test = "\(op.testIdentifier)Corners"
    let generated = referenceInputs(of: op, for: element, test: test, inContract: true)
    let inputs = zip(generated, op.operands).map { input, parameter in
        let operand = operandElement(of: parameter, for: element, source: op.source)
        let (inputsName, type) =
            parameter.isSourced
            ? ("widenMulOperands", "\(operand.namespace).Vector")
            : ("widenMulAccumulators", "H.Vector")
        let values = "Inputs.\(inputsName)(\(type).self)"
        return ReferenceInput(
            parameter: input.parameter,
            name: input.name,
            values: parameter.shape == .full
                ? values : "\(values).map { \(operand.namespace).lowerHalf($0) }"
        )
    }
    guard let accumulator = inputs.last else { return [] }
    let calls = referenceCalls(of: op, for: element, pointer: "")
    let description = referenceDescription(of: inputs)
    let statements = """
        for \(accumulator.name) in \(accumulator.name)Inputs {
        mismatches.check(\(calls.port), \(calls.reference), \(description))
        }
        """
    return [
        referenceTestFunction(
            test,
            label: test,
            for: element,
            inputs: Array(inputs.dropLast()),
            declarations: ["let \(accumulator.name)Inputs = \(accumulator.values)"],
            statements: statements
        )
    ]
}

let widenMulOps: [Op] =
    widenMulPairwiseOps(masked: false) + widenMulPairwiseOps(masked: true)
    + widenMulSaturatingPairwiseOps + widenMulAccumulatingOps + widenMulQuadOps(mixed: false)
    + widenMulQuadOps(mixed: true)

func reorderMulReorderAccepts(_ source: Element, _ result: Element) -> Bool {
    source.category != .float && source.category == result.category && source.bits == 16
        && result.bits == 32
}

func reorderMulWidenAccepts(_ source: Element, _ result: Element) -> Bool {
    source.category != .float && zipWidens(source, result)
}

func reorderMulLoadedOutVector(named name: String, for element: Element) -> String {
    """
    \(element.cVector) \(name);
    __builtin_memcpy(&\(name), v0, sizeof \(name));
    """
}

func reorderMulProduct(_ part: Int, to result: Element) -> String {
    let halves = neonVector("i8x8")
    let indices = Array(part * result.laneCount..<(part + 1) * result.laneCount)
    let operands = ["a", "b"].map {
        "(\(halves))__builtin_shufflevector(\($0), \($0), \(laneIndices(indices)))"
    }
    let product =
        "__builtin_neon_vmull_v(\(operands[0]), \(operands[1]), \(neonTypeCode(of: result)))"
    return "(\(result.cVector))\(product)"
}

func reorderMulNeonAccumulating(to result: Element) -> String {
    let high = arithmetic("+", "accumulated", reorderMulProduct(1, to: result), for: result)
    let low = arithmetic("+", "c", reorderMulProduct(0, to: result), for: result)
    return """
        \(reorderMulLoadedOutVector(named: "accumulated", for: result))
        \(outVectorStore(0, of: high, for: result))
        \(vectorResult(low, for: result))
        """
}

func reorderMulSveAccumulating(from source: Element, to result: Element) -> String {
    let (a, b) = (sveSplatOperand("a", for: source), sveSplatOperand("b", for: source))
    func accumulated(_ instruction: String, onto accumulator: String) -> String {
        let operands = [accumulator, a, b]
        return sveResult(sveBuiltin(instruction, operands, for: result), for: result)
    }
    let odd = accumulated("mlalt", onto: sveOperand("accumulated", for: result))
    let even = accumulated("mlalb", onto: sveSplatOperand("c", for: result))
    return """
        \(reorderMulLoadedOutVector(named: "accumulated", for: result))
        const \(result.cVector) odd = \(odd);
        const \(result.cVector) even = \(even);
        \(outVectorStore(0, from: "odd"))
        \(vectorResult("even", for: result))
        """
}

func reorderMulPromoted(
    _ operand: String,
    by highwayName: String,
    from source: Element,
    to result: Element
) -> String {
    let promotions = promoteLowerUpperOps + promoteEvenOddOps
    guard
        let promotion = promotions.first(where: {
            $0.highwayName == highwayName && $0.source?.suffix == source.suffix
        })
    else {
        fatalError("There is no \(highwayName) from \(source.swiftType)")
    }
    let name = cFunctionName(of: promotion, for: result)
    return "(\(result.cVector))\(name)((\(source.cRawVector))\(operand))"
}

func reorderMulMultiplyAdding(
    _ first: String,
    _ second: String,
    _ addend: String,
    for result: Element
) -> String {
    let raw = result.cRawVector
    let name = cFunctionName("multiplyAdding", result)
    return "(\(result.cVector))\(name)((\(raw))\(first), (\(raw))\(second), (\(raw))\(addend))"
}

func reorderMulComposedAccumulating(
    high: String,
    low: String,
    from source: Element,
    to result: Element
) -> String {
    func product(_ half: String, onto addend: String) -> String {
        let operands = ["a", "b"].map {
            reorderMulPromoted($0, by: half, from: source, to: result)
        }
        return reorderMulMultiplyAdding(operands[0], operands[1], addend, for: result)
    }
    return """
        \(reorderMulLoadedOutVector(named: "accumulated", for: result))
        \(outVectorStore(0, of: product(high, onto: "accumulated"), for: result))
        \(vectorResult(product(low, onto: "c"), for: result))
        """
}

func reorderMulX86Pairwise(
    from source: Element,
    to result: Element
) -> (declarations: String, expression: String) {
    let raw = source.cRawVector
    guard source.category == .unsignedInteger else {
        let madd = x86Builtin(
            "pmaddwd\(x86Bits(result.width))",
            ["a", "b"],
            as: "i16",
            returning: result.cVector
        )
        return ("", madd)
    }
    func product(_ name: String) -> String {
        "(\(source.cVector))\(cFunctionName(name, source))((\(raw))a, (\(raw))b)"
    }
    let oddEven = "\(cFunctionName("oddEven", source))((\(raw))high, (\(raw))low)"
    let declarations = """
        const \(source.cVector) low = \(product("multiplying"));
        const \(source.cVector) high = \(product("multiplyingHigh"));
        const \(result.cVector) highOddLowEven = (\(result.cVector))(\(source.cVector))\(oddEven);
        const \(result.cVector) highEvenLowOdd = ((\(result.cVector))high << 16) | ((\(result.cVector))low >> 16);
        """
    return (declarations, "highOddLowEven + highEvenLowOdd")
}

let reorderMulReorderingOps = sourcedOps(accepting: reorderMulReorderAccepts) { source, results in
    func x86(_ level: X86Level) -> (Element) -> String? {
        sourced(source) { source, result in
            if level == .avx3dl {
                guard result.category == .signedInteger else { return nil }
                let accumulated = x86Builtin(
                    "vpdpwssd\(x86Bits(result.width))",
                    ["c", "a", "b"],
                    as: "i32",
                    returning: result.cVector
                )
                return vectorResult(accumulated, for: result)
            }
            let pairwise = reorderMulX86Pairwise(from: source, to: result)
            let sum = arithmetic("+", "c", "(\(pairwise.expression))", for: result)
            return [pairwise.declarations, vectorResult(sum, for: result)]
                .filter { !$0.isEmpty }.joined(separator: "\n")
        }
    }
    return Op(
        "multiplyAccumulatingInAnyOrder",
        "ReorderWidenMulAccumulate",
        [.tag, .sourceVector, .sourceVector, .vector, .outVector],
        .vector,
        results,
        section: .multiply,
        accumulates: true,
        source: source,
        targets: TargetBodies(
            neon: sourced(source) { _, result in reorderMulNeonAccumulating(to: result) },
            sve2_128: sourced(source) { source, result in
                reorderMulSveAccumulating(from: source, to: result)
            },
            avx3dl: x86(.avx3dl),
            avx3: x86(.avx3),
            avx2: x86(.avx2),
            sse2: x86(.sse2)
        ),
        portable: sourced(source) { source, result in
            reorderMulComposedAccumulating(
                high: "PromoteOddTo",
                low: "PromoteEvenTo",
                from: source,
                to: result
            )
        }
    )
}

let reorderMulWideningOps = sourcedOps(accepting: reorderMulWidenAccepts) { source, results in
    Op(
        "multiplyAccumulating",
        "WidenMulAccumulate",
        [.tag, .sourceVector, .sourceVector, .vector, .outVector],
        .vector,
        results,
        section: .multiply,
        accumulates: true,
        source: source,
        targets: TargetBodies(
            neon: sourced(source) { _, result in reorderMulNeonAccumulating(to: result) }
        ),
        portable: sourced(source) { source, result in
            reorderMulComposedAccumulating(
                high: "PromoteUpperTo",
                low: "PromoteLowerTo",
                from: source,
                to: result
            )
        }
    )
}

func reorderMulPairwiseLanes(parity: Int, for element: Element) -> String {
    let indices = Array(stride(from: parity, to: 2 * element.laneCount, by: 2))
    return "__builtin_shufflevector(a, b, \(laneIndices(indices)))"
}

let reorderMulNeonKeepsFirstCondition =
    "HWY_STATIC_TARGET == HWY_NEON_BF16 || (defined(__ARM_FEATURE_BF16_VECTOR_ARITHMETIC) && (HWY_COMPILER_GCC_ACTUAL >= 1000 || HWY_COMPILER_CLANG >= 1100))"

let reorderMulSveKeepsFirstCondition =
    "HWY_COMPILER_CLANG >= 1700 || HWY_COMPILER_GCC_ACTUAL >= 1400"

let reorderMulAvx3KeepsFirstCondition =
    "(HWY_STATIC_TARGET & (HWY_AVX3_SPR | HWY_AVX3_ZEN4)) && !defined(HWY_AVX3_DISABLE_AVX512BF16) && !HWY_COMPILER_CLANGCL"

func reorderMulFloatRearranging(keepingFirstIf condition: String, for element: Element) -> String {
    """
    #if \(condition)
    \(vectorResult("a", for: element))
    #else
    \(binaryArithmetic("+", for: element))
    #endif
    """
}

func reorderMulX86Rearranging(for element: Element) -> String {
    element.category == .float
        ? binaryArithmetic("+", for: element) : vectorResult("a", for: element)
}

let reorderMulRearrangingOp = Op(
    "rearrangedToOddPlusEven",
    "RearrangeToOddPlusEven",
    [.vector, .vector],
    .vector,
    .all(bits: [32]),
    section: .multiply,
    unorderedNaNs: .perLane,
    targets: TargetBodies(
        neon: { element in
            if element.category == .float {
                return reorderMulFloatRearranging(
                    keepingFirstIf: reorderMulNeonKeepsFirstCondition,
                    for: element
                )
            }
            let sum = arithmetic("+", "evens", "odds", for: element)
            return """
                const \(element.cVector) evens = \(reorderMulPairwiseLanes(parity: 0, for: element));
                const \(element.cVector) odds = \(reorderMulPairwiseLanes(parity: 1, for: element));
                \(vectorResult(sum, for: element))
                """
        },
        sve2_128: { element in
            guard element.category != .float else {
                return reorderMulFloatRearranging(
                    keepingFirstIf: reorderMulSveKeepsFirstCondition,
                    for: element
                )
            }
            return [
                sveSplatBinary("add", .arithmetic, for: element),
                binaryArithmetic("+", for: element),
            ].compactMap { $0 }.joined(separator: "\n")
        },
        avx3dl: { element in
            element.category == .float
                ? reorderMulFloatRearranging(
                    keepingFirstIf: reorderMulAvx3KeepsFirstCondition,
                    for: element
                ) : nil
        },
        avx3: { element in reorderMulX86Rearranging(for: element) },
        avx2: { element in reorderMulX86Rearranging(for: element) },
        sse2: { element in reorderMulX86Rearranging(for: element) }
    )
) { element in
    binaryArithmetic("+", for: element)
}

func reorderMulPairingMembers(of element: Element) -> [SectionMember] {
    let tests = reorderMulReorderingOps.filter { $0.applies.matches(element) }.compactMap { op in
        op.source.map { reorderMulPairingTest(of: op, from: $0, to: element) }
    }
    return tests.isEmpty ? [] : [SectionMember(section: .multiply, inside: tests)]
}

func reorderMulPairingTest(of reorder: Op, from source: Element, to element: Element) -> String {
    let rearrange = reorderMulRearrangingOp
    let test = "\(reorder.swiftName)\(uppercasedFirst(rearrange.swiftName))From\(source.swiftType)"
    let seeds = ["0", "1"].map { "seed: \(referenceTestSeed(element, test, $0))" }
    let operands = (0..<2).map {
        "Inputs.conversions(\(source.namespace).Vector.self, \(seeds[$0]))"
    }
    let reorderReference = referenceCall(
        referenceFunctionName(of: reorder, for: element),
        ["a.raw", "b.raw", "referenceSum0.raw", "&referenceSum1.raw"]
    )
    let rearrangeReference = referenceCall(
        referenceFunctionName(of: rearrange, for: element),
        ["referenceSum0.raw", "referenceSum1.raw"]
    )
    let declarations = [
        "let aInputs = \(operands[0])",
        "let bInputs = \(operands[1])",
        "let pairs = everyPair(aInputs, bInputs)",
    ]
    let statements = """
        for index in pairs.indices {
        let steps = [index, (index * 7 + 1) % pairs.count, (index * 13 + 5) % pairs.count]
        .map { pairs[$0] }
        var portSum0 = H.zero()
        var portSum1 = H.zero()
        var referenceSum0 = H.zero()
        var referenceSum1 = H.zero()
        var products = [H.Lane](repeating: 0, count: H.laneCount)
        for (a, b) in steps {
        portSum0 = H.\(reorder.swiftName)(a, b, portSum0, &portSum1)
        referenceSum0 = H.Vector(raw: \(reorderReference))
        for lane in products.indices {
        let even = H.Lane(truncatingIfNeeded: a.simd[2 * lane]) &* H.Lane(truncatingIfNeeded: b.simd[2 * lane])
        let odd = H.Lane(truncatingIfNeeded: a.simd[2 * lane + 1]) &* H.Lane(truncatingIfNeeded: b.simd[2 * lane + 1])
        products[lane] = products[lane] &+ even &+ odd
        }
        }
        let described = { steps.map { "\\(describe($0.0)) * \\(describe($0.1))" }.joined(separator: ", ") }
        let rearranged = H.\(rearrange.swiftName)(portSum0, portSum1)
        let referenceRearranged = H.Vector(raw: \(rearrangeReference))
        mismatches.check(portSum0, referenceSum0, "steps: \\(described()), sum0")
        mismatches.check(portSum1, referenceSum1, "steps: \\(described()), sum1")
        mismatches.check(rearranged, referenceRearranged, "steps: \\(described()), rearranged")
        mismatches.check(rearranged, H.Vector(H.Vector.Simd(products)), "steps: \\(described()), products")
        }
        """
    return referenceTestFunction(
        test,
        label: test,
        for: element,
        inputs: [],
        declarations: declarations,
        statements: statements
    )
}

let reorderMulOps: [Op] =
    reorderMulReorderingOps + [reorderMulRearrangingOp] + reorderMulWideningOps

let widenArithmeticOps: [Op] = sumsOps + mulBitsOps + widenMulOps + reorderMulOps

func narrowLoadedVector(_ shape: Shape, for element: Element) -> String {
    """
    \(element.cRawVector(of: shape)) v;
    __builtin_memcpy(&v, from, \(element.bytes(of: shape)));
    return v;
    """
}

func narrowStoredVector(_ shape: Shape, for element: Element) -> String {
    "__builtin_memcpy(to, &a, \(element.bytes(of: shape)));"
}

func emulatedNarrowStoredVector(_ shape: Shape, for element: Element) -> String? {
    let bytes = element.bytes(of: shape)
    guard shape != .block, bytes < 8 else { return nil }
    let unit = unsignedElement(bits: 8 * bytes)
    let register = partialRegisterBytes(of: shape, for: element, arm: false)
    return """
        \(vectorTypedef("unit_vector", of: unit, lanes: register / bytes))
        const \(unit.cType) bits = ((unit_vector)a)[0];
        __builtin_memcpy(to, &bits, \(bytes));
        """
}

func neonNarrowStoredVector(_ shape: Shape, for element: Element) -> String {
    shape == .block
        ? narrowStoredVector(shape, for: element)
        : neonPartialStore(bytes: element.bytes(of: shape), of: "a", for: element)
}

let narrowMemoryOps: [Op] = Shape.allCases.filter { $0 != .full }.flatMap { shape in
    [
        Op(
            "load\(shape.prefix)",
            "LoadU",
            [.narrowTag(shape), .constLanePointer],
            .narrowVector(shape),
            shape.applies,
            section: .load,
            span: shape.spanExtent
        ) { element in
            narrowLoadedVector(shape, for: element)
        },
        Op(
            "store",
            "StoreU",
            [.narrowVector(shape), .narrowTag(shape), .lanePointer],
            .void,
            shape.applies,
            section: .store,
            span: shape.spanExtent,
            identifier: "store\(shape.prefix)",
            targets: TargetBodies(
                neon: { neonNarrowStoredVector(shape, for: $0) },
                emu128: { emulatedNarrowStoredVector(shape, for: $0) }
            )
        ) { element in
            narrowStoredVector(shape, for: element)
        },
    ]
}

func partialRegisterBytes(of shape: Shape, for element: Element, arm: Bool) -> Int {
    if shape == .block { return 16 }
    return arm ? 8 : max(16, element.bytes(of: shape))
}

func partialRegisterLanes(of shape: Shape, for element: Element, arm: Bool) -> Int {
    partialRegisterBytes(of: shape, for: element, arm: arm) / (element.bits / 8)
}

func narrowResult(
    _ expression: String,
    _ shape: Shape,
    for element: Element,
    isMask: Bool = false
) -> String {
    isMask
        ? narrowMaskResult(expression, shape, for: element)
        : "return (\(element.cRawVector(of: shape)))(\(expression));"
}

func halfPadding(arm: Bool, for element: Element) -> [Int] {
    let lanes = partialRegisterLanes(of: .half, for: element, arm: arm)
    return Array(repeating: -1, count: lanes - element.laneCount(of: .half))
}

func halfIndices(upper: Bool, arm: Bool, for element: Element) -> String {
    let half = element.laneCount(of: .half)
    let lanes = upper ? Array(half..<2 * half) : Array(0..<half)
    return laneIndices(lanes + halfPadding(arm: arm, for: element))
}

func halfOfVector(upper: Bool, arm: Bool, for element: Element) -> String {
    let indices = halfIndices(upper: upper, arm: arm, for: element)
    return narrowResult("__builtin_shufflevector(a, a, \(indices))", .half, for: element)
}

func combinedHalvesIndices(arm: Bool, for element: Element) -> String {
    let half = element.laneCount(of: .half)
    let register = partialRegisterLanes(of: .half, for: element, arm: arm)
    return laneIndices(0..<half, register..<register + half)
}

func combinedHalves(zeroing: Bool, arm: Bool, for element: Element) -> String {
    let indices = combinedHalvesIndices(arm: arm, for: element)
    let upper = zeroing ? compoundLiteral(element.cRawVector(of: .half), ["0"]) : "a"
    let lower = zeroing ? "a" : "b"
    return vectorResult("__builtin_shufflevector(\(lower), \(upper), \(indices))", for: element)
}

func emulatedZeroExtendedHalf(for element: Element) -> String {
    let lanes = unsignedElement(bits: 64).at(width: element.width)
    return """
        \(vectorTypedef("half_lanes", of: lanes, lanes: 2))
        \(vectorResult("__builtin_shufflevector((half_lanes)a, (half_lanes){0}, 0, 2)", for: element))
        """
}

func combinedHalvesSve(for element: Element) -> String {
    let lanes = unsignedElement(bits: 64).at(width: element.width)
    let widened = [("low", "b"), ("high", "a")].map { name, operand in
        """
        const \(lanes.cVector) \(name) = \
        __builtin_shufflevector((half_lanes)\(operand), (half_lanes)\(operand), 0, -1);
        """
    }
    let operands = [sveOperand("low", for: lanes), sveOperand("high", for: lanes)]
    let zipped = sveBuiltin("zip1", operands, for: lanes)
    return """
        \(vectorTypedef("half_lanes", of: lanes, lanes: 1))
        \(widened.joined(separator: "\n"))
        \(vectorResult("(\(element.cVector))\(sveResult(zipped, for: lanes))", for: element))
        """
}

let narrowHalfOps: [Op] = [
    Op(
        "lowerHalf",
        "LowerHalf",
        [.narrowTag(.half), .vector],
        .narrowVector(.half),
        .all,
        section: .combine,
        targets: TargetBodies(neon: { halfOfVector(upper: false, arm: true, for: $0) })
    ) { element in
        halfOfVector(upper: false, arm: false, for: element)
    },
    Op(
        "upperHalf",
        "UpperHalf",
        [.narrowTag(.half), .vector],
        .narrowVector(.half),
        .all,
        section: .combine,
        targets: TargetBodies(neon: { halfOfVector(upper: true, arm: true, for: $0) })
    ) { element in
        halfOfVector(upper: true, arm: false, for: element)
    },
    Op(
        "combining",
        "Combine",
        [.tag, .narrowVector(.half), .narrowVector(.half)],
        .vector,
        .all,
        section: .combine,
        targets: TargetBodies(
            neon: { combinedHalves(zeroing: false, arm: true, for: $0) },
            sve2_128: { combinedHalvesSve(for: $0) }
        )
    ) { element in
        combinedHalves(zeroing: false, arm: false, for: element)
    },
    Op(
        "zeroExtending",
        "ZeroExtendVector",
        [.tag, .narrowVector(.half)],
        .vector,
        .all,
        section: .combine,
        targets: TargetBodies(
            neon: { combinedHalves(zeroing: true, arm: true, for: $0) },
            emu128: { emulatedZeroExtendedHalf(for: $0) }
        )
    ) { element in
        combinedHalves(zeroing: true, arm: false, for: element)
    },
]

func promotedLanes(to result: Element) -> [Int] {
    Array(0..<result.laneCount)
}

func promoteNarrowSve(from source: Element, shape: Shape, to result: Element) -> String? {
    guard source.category != .float, result.category != .float else { return nil }
    let lanes = partialRegisterLanes(of: shape, for: source, arm: true)
    let padding = Array(repeating: -1, count: source.laneCount - lanes)
    var call = "(\(sveType(of: source)))\(sveOperand("widened", for: source))"
    var unpacked = source
    while unpacked.bits < result.bits {
        let unsigned = unsignedElement(bits: 2 * unpacked.bits)
        unpacked = source.category == .signedInteger ? signedElement(of: unsigned) : unsigned
        call = sveBuiltin("unpklo", [call], for: unpacked)
    }
    let reinterpreted = sveReinterpreted(call, from: unpacked, to: result)
    return """
        const \(source.cVector) widened = __builtin_shufflevector(a, a, \(laneIndices(Array(0..<lanes) + padding)));
        \(vectorResult(sveResult(reinterpreted, for: result), for: result))
        """
}

func promoteNarrowZeroed(from source: Element, shape: Shape) -> String {
    let register = partialRegisterLanes(of: shape, for: source, arm: false)
    let kept = source.laneCount(of: shape)
    guard kept < register else { return "a" }
    let zero = compoundLiteral(source.cRawVector(of: shape), ["0"])
    let indices = laneIndices(Array(0..<kept) + Array(repeating: register, count: register - kept))
    return "__builtin_shufflevector(a, \(zero), \(indices))"
}

func promoteNarrowAccepts(_ shape: Shape, inRange: Bool) -> (Element, Element) -> Bool {
    { source, result in
        promotes(source, to: result) && source.laneCount(of: shape) == result.laneCount
            && (!inRange || convertsFloatToInteger(from: source, to: result))
    }
}

func promoteNarrowFamily(_ shape: Shape, inRange: Bool) -> [Op] {
    let range = inRange ? "InRange" : ""
    return sourcedOps(accepting: promoteNarrowAccepts(shape, inRange: inRange)) {
        source,
        results in
        let x86 = sourced(source) { source, result in
            promoteX86(
                of: promoteNarrowZeroed(from: source, shape: shape),
                inRange: inRange,
                from: source,
                to: result
            )
        }
        return Op(
            "vector",
            "Promote\(range)To",
            [.tag, .sourceNarrowVector(shape)],
            .vector,
            results,
            section: .singleVectorPromotion,
            vectorLabels: ["widening\(range)"],
            source: source,
            targets: TargetBodies(
                neon: sourced(source) { source, result in
                    promoteNeon(of: promotedLanes(to: result), from: source, to: result)
                },
                sve2_128: sourced(source) { source, result in
                    promoteNarrowSve(from: source, shape: shape, to: result)
                },
                avx3: sourced(source) { source, result in
                    promoteAvx3(
                        of: promotedLanes(to: result),
                        inRange: inRange,
                        from: source,
                        to: result
                    )
                },
                avx2: x86,
                sse2: x86
            ),
            portable: sourced(source) { source, result in
                promotePortable(
                    of: promotedLanes(to: result),
                    inRange: inRange,
                    from: source,
                    to: result
                )
            }
        )
    }
}

let promoteNarrowOps: [Op] =
    [Shape.half, .quarter, .eighth].flatMap { promoteNarrowFamily($0, inRange: false) }
    + promoteNarrowFamily(.half, inRange: true)

func fixedPointDuplicates(from source: Element, to result: Element) -> String {
    let indices = laneIndices((0..<result.laneCount).flatMap { [$0, $0] })
    return ["a", "b"].map {
        "const \(source.cVector) dup\(uppercasedFirst($0)) = __builtin_shufflevector(\($0), \($0), \(indices));"
    }
    .joined(separator: "\n")
}

func fixedPointProduct(to result: Element) -> String {
    let lanes = promotedLanes(to: result)
    let product = ["a", "b"].map { convertedLanes($0, at: lanes, to: result.cVector) }
    let widened = "(\(product[0]) * \(product[1]))"
    return widenMulSum([widened, widened], for: result)
}

func fixedPointNeon(to result: Element) -> String {
    let (halves, quads) = (neonVector("i8x8"), neonVector("i8"))
    let code = neonTypeCode(of: result)
    let accumulated = "__builtin_neon_vqdmlal_v((\(quads))c, (\(halves))a, (\(halves))b, \(code))"
    return vectorResult("(\(result.cVector))\(accumulated)", for: result)
}

let fixedPointMultiplyOps = sourcedOps(accepting: widenMulAccumulatingAccepts) { source, results in
    func x86(_ level: X86Level) -> (Element) -> String? {
        sourced(source) { source, result in
            let duplicates = fixedPointDuplicates(from: source, to: result)
            if level >= .avx3dl {
                let native = widenMulAccumulatingX86Native("dupA", "dupB", to: result)
                return "\(duplicates)\n\(native)"
            }
            let product = widenMulPairwiseX86(
                "dupA",
                "dupB",
                level: level,
                from: source,
                to: result
            )
            let tail = widenMulAccumulatingTail(
                product.value,
                blending: level == .sse4,
                for: result
            )
            let statements = [duplicates, product.statements, tail.statements]
            return widenMulBody(
                (statements.filter { !$0.isEmpty }.joined(separator: "\n"), tail.value),
                for: result
            )
        }
    }
    return Op(
        "saturatingMultiplyAccumulatingFixedPoint",
        "SatWidenMulAccumFixedPoint",
        [.tag, .sourceNarrowVector(.half), .sourceNarrowVector(.half), .vector],
        .vector,
        results,
        section: .multiply,
        source: source,
        targets: TargetBodies(
            neon: sourced(source) { _, result in fixedPointNeon(to: result) },
            avx3dl: x86(.avx3dl),
            avx3: x86(.avx3),
            avx2: x86(.avx2),
            sse4: x86(.sse4),
            sse2: x86(.sse2)
        ),
        portable: sourced(source) { _, result in
            widenMulBody(
                widenMulAccumulatingTail(fixedPointProduct(to: result), for: result),
                for: result
            )
        }
    )
}

func demoteSingleAccepts(_ shape: Shape) -> (Element, Element) -> Bool {
    { source, result in
        guard let fraction = shape.fraction else { return false }
        return source.category != .float && result.category != .float
            && source.bits == fraction * result.bits
    }
}

func demoteSingleShiftedBody(
    _ shift: DemoteShift?,
    for source: Element,
    _ kernel: (_ operand: String) -> String
) -> String {
    guard let shift else { return kernel("a") }
    return """
        const \(source.cVector) shifted = \(demoteShifted("a", shift, for: source));
        \(kernel("shifted"))
        """
}

func demoteSingleRoute(from source: Element, to result: Element) -> [Element] {
    var route = [source]
    while let last = route.last, last.bits > result.bits {
        route.append(resizedElement(of: result, bits: last.bits / 2))
    }
    return route
}

func demoteSingleRegisterLanes(_ shape: Shape, to result: Element, arm: Bool) -> [Int] {
    let own = result.laneCount(of: shape)
    let padding = partialRegisterLanes(of: shape, for: result, arm: arm) - own
    return Array(0..<own) + Array(repeating: -1, count: padding)
}

func demoteSinglePortable(
    _ operand: String,
    _ shape: Shape,
    from source: Element,
    to result: Element,
    isMask: Bool = false
) -> String {
    let lanes = result.laneCount(of: shape)
    let indices = laneIndices(demoteSingleRegisterLanes(shape, to: result, arm: false))
    return """
        \(vectorTypedef("narrow_lanes", lane: result.cType, bits: result.bits, lanes: lanes))
        const narrow_lanes narrowed = \(demoteSaturated(operand, from: source, to: result));
        \(narrowResult("__builtin_shufflevector(narrowed, narrowed, \(indices))", shape, for: result, isMask: isMask))
        """
}

func demoteSingleNeon(
    _ operand: String,
    _ shape: Shape,
    from source: Element,
    to result: Element
) -> String {
    let route = demoteSingleRoute(from: source, to: result)
    let halves = neonVector("i8x8")
    var statements: [String] = []
    var previous = operand
    for (index, step) in zip(route, route.dropFirst()).enumerated() {
        var input = previous
        if index > 0 {
            let lanes = 8 / (step.0.bits / 8)
            let name = "lanes\(index)"
            statements.append(vectorTypedef(name, of: step.0, lanes: lanes))
            let indices = laneIndices(0..<lanes, 0..<lanes)
            input =
                "__builtin_shufflevector((\(name))\(previous), (\(name))\(previous), \(indices))"
        }
        let narrowed = demoteNeonNarrowed(input, from: step.0, to: step.1)
        statements.append("const \(halves) narrowed\(index) = \(narrowed);")
        previous = "narrowed\(index)"
    }
    let lanes = 8 / (result.bits / 8)
    statements.append(vectorTypedef("result_lanes", of: result, lanes: lanes))
    var value = "(result_lanes)\(previous)"
    if demoteUnsignedToSigned(from: source, to: result) {
        statements.append(
            vectorTypedef("narrow_lanes", of: unsignedElement(of: result), lanes: lanes)
        )
        let highest = splat(highestValue(of: result), as: "narrow_lanes", lanes: lanes)
        value = "(result_lanes)__builtin_elementwise_min((narrow_lanes)\(previous), \(highest))"
    }
    statements.append("const result_lanes narrowed = \(value);")
    let indices = laneIndices(demoteSingleRegisterLanes(shape, to: result, arm: true))
    let shuffled = "__builtin_shufflevector(narrowed, narrowed, \(indices))"
    return (statements + [narrowResult(shuffled, shape, for: result)]).joined(separator: "\n")
}

func demoteSingleNeonFused(
    _ bits: Int,
    _ shift: DemoteShift,
    _ shape: Shape,
    from source: Element,
    to result: Element
) -> String {
    let rounding = shift == .rounding ? "r" : ""
    let suffix = demoteSignedToUnsigned(from: source, to: result) ? "un" : "n"
    let code = neonTypeCode(of: result) - 32
    let narrowed =
        "(\(neonVector("i8x8")))__builtin_neon_vq\(rounding)shr\(suffix)_n_v((\(neonVector("i8")))a, \(bits), \(code))"
    return narrowResult(narrowed, shape, for: result)
}

func demoteSingleNeonBody(
    _ shift: DemoteShift?,
    _ shape: Shape,
    from source: Element,
    to result: Element
) -> String {
    let unfused = demoteSingleShiftedBody(shift, for: source) {
        demoteSingleNeon($0, shape, from: source, to: result)
    }
    guard let shift, shape == .half, !demoteUnsignedToSigned(from: source, to: result) else {
        return unfused
    }
    let cases = (1...result.bits).map {
        (amount: $0, body: demoteSingleNeonFused($0, shift, shape, from: source, to: result))
    }
    return "\(constantSwitch(on: "bits", cases))\n\(unfused)"
}

func demoteSingleSveClamps(from source: Element, to result: Element) -> Bool {
    guard source.category == .signedInteger else {
        return result.category == .signedInteger || (result.bits == 8 && source.bits >= 32)
    }
    return result.bits == 8 && source.bits == 64
}

func demoteSingleSveClamped(
    _ operand: String,
    from source: Element,
    to result: Element
) -> (value: String, element: Element) {
    let highest = highestValue(of: result)
    guard source.category == .signedInteger else {
        let arguments = [sveAllLanes(of: source), operand, highest]
        return (sveBuiltin("min_n", arguments, for: source, predication: "x"), source)
    }
    let raised = sveBuiltin(
        "max_n",
        [sveAllLanes(of: source), operand, lowestValue(of: result)],
        for: source,
        predication: "x"
    )
    guard result.category == .unsignedInteger else {
        let arguments = [sveAllLanes(of: source), raised, highest]
        return (sveBuiltin("min_n", arguments, for: source, predication: "x"), source)
    }
    let unsigned = unsignedElement(of: source).at(width: source.width)
    let arguments = [
        sveAllLanes(of: unsigned), sveReinterpreted(raised, from: source, to: unsigned), highest,
    ]
    return (sveBuiltin("min_n", arguments, for: unsigned, predication: "x"), unsigned)
}

func demoteSingleSveWidths(from source: Element, to result: Element) -> [Int] {
    if source.bits == 32 && result.bits == 8 && !demoteUnsignedToSigned(from: source, to: result) {
        return [16, 8]
    }
    return Array(
        repeating: result.bits,
        count: (source.bits / result.bits).trailingZeroBitCount
    )
}

func demoteSingleSve(
    _ operand: String,
    _ shape: Shape,
    from source: Element,
    to result: Element
) -> String {
    var narrowed = operand
    var element = source
    if demoteSingleSveClamps(from: source, to: result) {
        (narrowed, element) = demoteSingleSveClamped(operand, from: source, to: result)
    } else {
        let route = demoteSingleRoute(from: source, to: result)
        for step in zip(route, route.dropFirst()) {
            let isSignedToUnsigned = demoteSignedToUnsigned(from: step.0, to: step.1)
            narrowed = sveBuiltin(isSignedToUnsigned ? "qxtunb" : "qxtnb", [narrowed], for: step.0)
        }
        element = route[route.count - 1]
    }
    var statements = ["const \(sveType(of: element)) narrowed = \(narrowed);"]
    var previous = "narrowed"
    for (index, width) in demoteSingleSveWidths(from: source, to: result).enumerated() {
        let target = resizedElement(of: result, bits: width)
        let reinterpreted = sveReinterpreted(previous, from: element, to: target)
        let compacted = sveBuiltin("uzp1", [reinterpreted, reinterpreted], for: target)
        statements.append("const \(sveType(of: target)) compacted\(index) = \(compacted);")
        previous = "compacted\(index)"
        element = target
    }
    let converted = sveResult(previous, for: result)
    let indices = laneIndices(demoteSingleRegisterLanes(shape, to: result, arm: true))
    let shuffled = "__builtin_shufflevector(\(converted), \(converted), \(indices))"
    return (statements + [narrowResult(shuffled, shape, for: result)]).joined(separator: "\n")
}

func demoteSingleSveBody(
    _ shift: DemoteShift?,
    _ shape: Shape,
    from source: Element,
    to result: Element
) -> String {
    let operand = sveSplatOperand("a", for: source)
    guard let shift else { return demoteSingleSve(operand, shape, from: source, to: result) }
    let shifted = demoteSveShifted(operand, shift, for: source)
    return """
        const \(sveType(of: source)) shifted = \(shifted);
        \(demoteSingleSve("shifted", shape, from: source, to: result))
        """
}

func demoteSingleX86TableName(
    _ highwayName: String,
    from source: Element,
    to result: Element
) -> String {
    let name = snakeCased(lowercasedFirstWord(highwayName))
    return "cvectorization_ops_x86_\(name)_table_\(source.cSuffix)_to_\(result.cSuffix)"
}

func demoteSingleX86Indices(
    level: X86Level,
    from source: Element,
    to result: Element
) -> (bits: Int, values: [Int])? {
    let values = [0, 2, 4, 6, 0, 2, 4, 6]
    switch level {
    case .avx3, .avx3dl:
        return source.bits < 64 && source.bits == 2 * result.bits ? (64, values) : nil
    case .avx2:
        return source.bits == 64 && result.bits == 32 ? (32, values) : nil
    default:
        return nil
    }
}

func demoteSingleX86Table(
    _ highwayName: String,
    level: X86Level,
    from source: Element,
    to result: Element
) -> String? {
    guard let indices = demoteSingleX86Indices(level: level, from: source, to: result) else {
        return nil
    }
    let lane = indices.bits == 64 ? "long long" : "int32_t"
    let values = indices.values.map(String.init).joined(separator: ", ")
    return cFunction(
        returns: "const \(lane)*",
        name: demoteSingleX86TableName(highwayName, from: source, to: result),
        parameters: [],
        body: """
            static const \(lane) table[\(indices.values.count)] __attribute__((aligned(64))) = {\(values)};
            return table;
            """,
        specifiers: "__attribute__((visibility(\"hidden\"))) CVECTORIZATION_OPS_INLINE"
    )
}

func demoteSingleX86LoadedIndices(
    _ table: String,
    level: X86Level,
    from source: Element,
    to result: Element
) -> String {
    let bits = demoteSingleX86Indices(level: level, from: source, to: result)?.bits
    return "*(const \(x86Vector(bits == 64 ? "i64" : "i32"))*)\(table)()"
}

func demoteSingleX86Finish(
    _ statements: [String],
    _ value: String,
    _ shape: Shape,
    to result: Element,
    isMask: Bool = false
) -> String {
    (statements.filter { !$0.isEmpty } + [narrowResult(value, shape, for: result, isMask: isMask)])
        .joined(separator: "\n")
}

func demoteSingleX86Clamped(
    _ value: String,
    _ shape: Shape,
    from source: Element,
    to result: Element
) -> (declarations: [String], value: String) {
    guard demoteUnsignedToSigned(from: source, to: result) else { return ([], value) }
    let lanes = partialRegisterLanes(of: shape, for: result, arm: false)
    let unsigned = unsignedElement(of: result)
    let highest = splat(highestValue(of: result), as: "unsigned_vector", lanes: lanes)
    return (
        [vectorTypedef("unsigned_vector", of: unsigned, lanes: lanes)],
        "__builtin_elementwise_min((unsigned_vector)\(value), \(highest))"
    )
}

func demoteSingleX86Unpacked(
    _ operand: String,
    _ shape: Shape,
    to result: Element
) -> String {
    let view = unsignedElement(of: result).at(width: 16).cVector
    let quads = x86Vector("i64")
    let upper = "__builtin_shufflevector((\(quads))\(operand), (\(quads))\(operand), 1, 1)"
    let lanes = partialRegisterLanes(of: shape, for: result, arm: false)
    let indices = (0..<lanes / 2).flatMap { [$0, lanes + $0] }
    return
        "__builtin_shufflevector((\(view))\(operand), (\(view))\(upper), \(laneIndices(indices)))"
}

func demoteSingleX86Strided(
    _ operand: String,
    _ shape: Shape,
    from source: Element,
    to result: Element
) -> String {
    let view = unsignedElement(of: result).at(width: source.width).cVector
    let ratio = source.bits / result.bits
    let own = (0..<source.laneCount).map { $0 * ratio }
    let registerLanes = partialRegisterLanes(of: shape, for: result, arm: false)
    let indices = (0..<registerLanes).map { own[$0 % own.count] }
    return
        "__builtin_shufflevector((\(view))\(operand), (\(view))\(operand), \(laneIndices(indices)))"
}

func demoteX86BlockPack(_ operand: String, sourceBits: Int, unsigned: Bool) -> String {
    let name = demoteX86PackName(sourceBits: sourceBits, unsigned: unsigned)
    let input = "(\(x86Block("i\(sourceBits)")))\(operand)"
    return "(\(x86Block("i\(sourceBits / 2)")))__builtin_ia32_\(name)128(\(input), \(input))"
}

func demoteSingleX86Limited(
    _ value: String,
    _ shape: Shape,
    from source: Element,
    to target: Element
) -> (declarations: [String], value: String) {
    guard demoteUnsignedToSigned(from: source, to: target) else { return ([], value) }
    let lanes = partialRegisterLanes(of: shape, for: target, arm: false)
    let highest = splat(highestValue(of: target), as: "limit_lanes", lanes: lanes)
    return (
        [vectorTypedef("limit_lanes", of: unsignedElement(of: target), lanes: lanes)],
        "(limit_lanes)(\(value)) & \(highest)"
    )
}

func demoteSingleX86ShiftedTwice(
    _ shift: DemoteShift?,
    level: X86Level,
    from source: Element,
    to target: Element
) -> String? {
    guard shift == .plain, level == .sse4, target.bits > 8,
        demoteUnsignedToSigned(from: source, to: target)
    else { return nil }
    return demoteShifted("a", .plain, for: source, by: "bits + \(target.bits - 1)")
}

func demoteSingleX86Sse(
    level: X86Level,
    shift: DemoteShift?,
    _ operand: String,
    _ shape: Shape,
    from source: Element,
    to result: Element,
    isMask: Bool = false
) -> String {
    let toUnsigned = result.category == .unsignedInteger
    var statements = X86Statements()
    func packed(_ value: String, from bits: Int) -> String {
        var value = value
        var bits = bits
        while bits > result.bits {
            bits /= 2
            let unsigned = toUnsigned && bits == result.bits
            value = demoteX86Pack(
                value,
                value,
                sourceBits: 2 * bits,
                unsigned: unsigned,
                width: level.width
            )
        }
        return value
    }
    if source.bits == 64 {
        let viaWords =
            level == .sse2 && demoteUnsignedToSigned(from: source, to: result) && result.bits < 32
        let target = viaWords ? resizedElement(of: result, bits: 32) : result
        let saturated = demoteX86Saturated64Lane(
            operand,
            named: "Lane",
            level: level,
            into: &statements,
            from: source,
            to: target,
            equalFirst: true,
            shiftedTwice: demoteSingleX86ShiftedTwice(
                shift,
                level: level,
                from: source,
                to: target
            ),
            deferringLimit: level == .sse4 && target.bits == 8
        )
        let truncated =
            level == .sse2 && target.bits < 32
            ? demoteSingleX86Unpacked(saturated, shape, to: target)
            : demoteSingleX86Strided(saturated, shape, from: source, to: target)
        let limited =
            level == .sse4 && target.bits == 8
            ? demoteSingleX86Limited(truncated, shape, from: source, to: target)
            : (declarations: [], value: truncated)
        let value = viaWords ? packed(limited.value, from: 32) : limited.value
        return demoteSingleX86Finish(
            limited.declarations + [statements.text],
            value,
            shape,
            to: result,
            isMask: isMask
        )
    }
    if source.bits == 32 && result.bits == 16 && toUnsigned && level < .sse4 {
        let kernel = demoteX86UnsignedWords(
            level: level,
            operand,
            operand,
            from: source,
            to: result
        )
        return demoteSingleX86Finish(
            kernel.statements,
            kernel.value,
            shape,
            to: result,
            isMask: isMask
        )
    }
    var value = operand
    if source.category == .unsignedInteger && toUnsigned {
        let clamped = demoteX86SignedMaximum(operand, level: level, from: source)
        value = statements.define(source.cVector, "clamped", clamped)
    }
    let clamped = demoteSingleX86Clamped(
        packed(value, from: source.bits),
        shape,
        from: source,
        to: result
    )
    return demoteSingleX86Finish(
        clamped.declarations + [statements.text],
        clamped.value,
        shape,
        to: result,
        isMask: isMask
    )
}

func demoteSingleX86Avx2Truncated(
    _ operand: String,
    table: String,
    _ statements: inout X86Statements,
    from source: Element,
    to result: Element
) -> String {
    let quads = x86Vector("i64")
    let bytes = x86Vector("i8")
    func shuffled(_ lanes: [UInt32], bits: Int) -> String {
        let shifted = lanes.flatMap { lane in
            (0..<bits / 8).map { (lane >> (8 * UInt32($0))) & 0xFF }
        }
        let table = shifted.map { String(Int8(truncatingIfNeeded: $0)) }
        return
            "(\(bytes))__builtin_ia32_pshufb256((\(bytes))\(operand), \(compoundLiteral(bytes, table)))"
    }
    switch result.bits {
    case 32:
        let words = x86Vector("i32")
        let indices = demoteSingleX86LoadedIndices(table, level: .avx2, from: source, to: result)
        let permuted = statements.define(
            words,
            "permuted",
            "(\(words))__builtin_ia32_permvarsi256((\(words))\(operand), \(indices))"
        )
        return "__builtin_shufflevector(\(permuted), \(permuted), 0, 1, 2, 3)"
    case 16:
        let kept: [UInt32] = [0x0100, 0xFFFF, 0x0908, 0xFFFF]
        let lanes = kept + Array(repeating: 0xFFFF, count: 8) + kept
        let quad = statements.define(bytes, "looked", shuffled(lanes, bits: 16))
        let half = statements.define(
            x86Block("i64"),
            "half",
            "__builtin_shufflevector((\(quads))\(quad), (\(quads))\(quad), 0, 3)"
        )
        let block = x86Block("i32")
        return
            "(\(x86Block("i16")))__builtin_ia32_packusdw128((\(block))\(half), (\(block))\(half))"
    default:
        let table: [UInt32] = [0xFFFF_0800, ~0, ~0, ~0, 0x0800_FFFF, ~0, ~0, ~0]
        let quad = statements.define(bytes, "looked", shuffled(table, bits: 32))
        let lower = "__builtin_shufflevector((\(quads))\(quad), (\(quads))\(quad), 0, 1)"
        let upper = "__builtin_shufflevector((\(quads))\(quad), (\(quads))\(quad), 2, 3)"
        return "\(lower) | \(upper)"
    }
}

func demoteSingleX86Avx2(
    _ operand: String,
    table: String,
    _ shape: Shape,
    from source: Element,
    to result: Element,
    isMask: Bool = false
) -> String {
    let toUnsigned = result.category == .unsignedInteger
    var statements = X86Statements()
    if source.bits == 64 {
        let saturated = demoteX86Saturated64Lane(
            operand,
            named: "Lane",
            level: .avx2,
            into: &statements,
            from: source,
            to: result,
            equalFirst: true
        )
        let truncated = demoteSingleX86Avx2Truncated(
            saturated,
            table: table,
            &statements,
            from: source,
            to: result
        )
        return demoteSingleX86Finish(
            [statements.text],
            truncated,
            shape,
            to: result,
            isMask: isMask
        )
    }
    var value = operand
    if source.category == .unsignedInteger && toUnsigned {
        let clamped = demoteX86SignedMaximum(operand, level: .avx2, from: source)
        value = statements.define(source.cVector, "clamped", clamped)
    }
    let isHalf = source.bits == 2 * result.bits
    let packed = demoteX86Pack(
        value,
        value,
        sourceBits: source.bits,
        unsigned: toUnsigned && isHalf,
        width: X86Level.avx2.width
    )
    let quads = x86Vector("i64")
    let gathered = "__builtin_shufflevector((\(quads))\(packed), (\(quads))\(packed), 0, 2)"
    if !isHalf {
        let blocks = statements.define(x86Block("i64"), "blocks", gathered)
        value = demoteX86BlockPack(blocks, sourceBits: source.bits / 2, unsigned: toUnsigned)
    } else {
        value = gathered
    }
    let clamped = demoteSingleX86Clamped(value, shape, from: source, to: result)
    return demoteSingleX86Finish(
        clamped.declarations + [statements.text],
        clamped.value,
        shape,
        to: result,
        isMask: isMask
    )
}

func demoteSingleX86Avx3(
    _ operand: String,
    table: String,
    _ shape: Shape,
    from source: Element,
    to result: Element,
    isMask: Bool = false
) -> String {
    let toUnsigned = result.category == .unsignedInteger
    let quads = x86Vector("i64")
    var statements = X86Statements()
    if source.bits == 64
        || (source.bits == 32 && result.bits == 8
            && demoteUnsignedToUnsigned(from: source, to: result))
    {
        let letter = x86LaneLetter(bits: result.bits)
        let name =
            "pmov\(toUnsigned ? "us" : "s")\(x86LaneLetter(bits: source.bits))\(letter)512_mask"
        let lanes = partialRegisterLanes(of: shape, for: result, arm: false)
        let narrow = signedElement(of: result)
        let zero = compoundLiteral("narrow_vector", ["0"])
        var mask = source.bits == 64 ? "(unsigned char)-1" : "(unsigned short)-1"
        if source.category == .signedInteger && toUnsigned {
            mask = "__builtin_ia32_knotqi(__builtin_ia32_cvtq2mask512((\(quads))\(operand)))"
        }
        let input = "(\(x86Vector("i\(source.bits)")))\(operand)"
        var value = "(narrow_vector)__builtin_ia32_\(name)(\(input), \(zero), \(mask))"
        var declarations = [vectorTypedef("narrow_vector", of: narrow, lanes: lanes)]
        if demoteUnsignedToSigned(from: source, to: result) {
            let unsigned = unsignedElement(of: result)
            declarations.append(vectorTypedef("unsigned_vector", of: unsigned, lanes: lanes))
            let highest = splat(highestValue(of: result), as: "unsigned_vector", lanes: lanes)
            value = "__builtin_elementwise_min((unsigned_vector)\(value), \(highest))"
        }
        return demoteSingleX86Finish(declarations, value, shape, to: result, isMask: isMask)
    }
    var value = operand
    if source.category == .unsignedInteger && toUnsigned {
        let clamped = demoteX86SignedMaximum(operand, level: .avx3, from: source)
        value = statements.define(source.cVector, "clamped", clamped)
    }
    let isHalf = source.bits == 2 * result.bits
    let packed = demoteX86Pack(
        value,
        value,
        sourceBits: source.bits,
        unsigned: toUnsigned && isHalf,
        width: X86Level.avx3.width
    )
    if isHalf {
        let indices = statements.define(
            quads,
            "indices",
            demoteSingleX86LoadedIndices(table, level: .avx3, from: source, to: result)
        )
        let permuted = x86Builtin("permvardi512", [packed, indices], as: "i64", returning: quads)
        value = "__builtin_shufflevector(\(permuted), \(permuted), 0, 1, 2, 3)"
    } else {
        let bytes = demoteX86Pack(
            packed,
            packed,
            sourceBits: source.bits / 2,
            unsigned: toUnsigned,
            width: X86Level.avx3.width
        )
        let words = x86Vector("i32")
        let indices = compoundLiteral(words, (0..<4).flatMap { _ in ["0", "4", "8", "12"] })
        let permuted = x86Builtin("permvarsi512", [bytes, indices], as: "i32", returning: words)
        value = "__builtin_shufflevector(\(permuted), \(permuted), 0, 1, 2, 3)"
    }
    let clamped = demoteSingleX86Clamped(value, shape, from: source, to: result)
    return demoteSingleX86Finish(
        clamped.declarations + [statements.text],
        clamped.value,
        shape,
        to: result,
        isMask: isMask
    )
}

func demoteSingleX86Body(
    level: X86Level,
    table: String,
    _ shift: DemoteShift?,
    _ shape: Shape,
    from source: Element,
    to result: Element,
    isMask: Bool = false
) -> String {
    demoteSingleShiftedBody(shift, for: source) { operand in
        switch level {
        case .avx3, .avx3dl:
            return demoteSingleX86Avx3(
                operand,
                table: table,
                shape,
                from: source,
                to: result,
                isMask: isMask
            )
        case .avx2:
            return demoteSingleX86Avx2(
                operand,
                table: table,
                shape,
                from: source,
                to: result,
                isMask: isMask
            )
        case .sse4, .ssse3, .sse2:
            return demoteSingleX86Sse(
                level: level,
                shift: shift,
                operand,
                shape,
                from: source,
                to: result,
                isMask: isMask
            )
        }
    }
}

func demoteSingleTargets(
    _ highwayName: String,
    _ shift: DemoteShift?,
    _ shape: Shape,
    from source: Element
) -> TargetBodies<Element> {
    func x86(_ level: X86Level) -> (Element) -> String {
        sourced(source) { source, result in
            demoteSingleX86Body(
                level: level,
                table: demoteSingleX86TableName(highwayName, from: source, to: result),
                shift,
                shape,
                from: source,
                to: result
            )
        }
    }
    return TargetBodies(
        neon: sourced(source) { source, result in
            demoteSingleNeonBody(shift, shape, from: source, to: result)
        },
        sve2_128: sourced(source) { source, result in
            demoteSingleSveBody(shift, shape, from: source, to: result)
        },
        avx3: x86(.avx3),
        avx2: x86(.avx2),
        sse4: x86(.sse4),
        ssse3: x86(.ssse3),
        sse2: x86(.sse2)
    )
}

func demoteSingleHelpers(
    _ highwayName: String,
    from source: Element
) -> TargetBodies<Element> {
    func table(_ level: X86Level) -> (Element) -> String? {
        { result in
            demoteSingleX86Table(
                highwayName,
                level: level,
                from: source.at(width: result.width),
                to: result
            )
        }
    }
    return TargetBodies(avx3: table(.avx3), avx2: table(.avx2))
}

func integerDemotionSourceInputs(
    of op: Op,
    operand: Element,
    result: Element,
    seed: String
) -> String? {
    guard op.section == .singleVectorDemotion, operand.category != .float,
        result.category != .float
    else { return nil }
    return "Inputs.integerDemotions(\(operand.namespace).Vector.self, to: H.Lane.self, \(seed))"
}

func demoteSingleOps(_ shape: Shape, _ highwayName: String, shift: DemoteShift? = nil) -> [Op] {
    let swiftName = shape.conversion("vector")
    let identifier = shift.map { swiftName + ["clamping", $0.label].map(uppercasedFirst).joined() }
    return sourcedOps(accepting: demoteSingleAccepts(shape)) { source, results in
        Op(
            swiftName,
            highwayName,
            [.narrowTag(shape), .sourceVector] + (shift == nil ? [] : [.immediate]),
            .narrowVector(shape),
            results,
            section: .singleVectorDemotion,
            immediates: shift.map { [demoteShiftAmount(of: source, $0)] } ?? [],
            vectorLabels: ["clamping"],
            source: source,
            identifier: identifier,
            targets: demoteSingleTargets(highwayName, shift, shape, from: source),
            helpers: demoteSingleHelpers(highwayName, from: source),
            portable: sourced(source) { source, result in
                demoteSingleShiftedBody(shift, for: source) {
                    demoteSinglePortable($0, shape, from: source, to: result)
                }
            }
        )
    }
}

let demoteIntegerOps: [Op] = [Shape.half, .quarter, .eighth].flatMap { shape in
    demoteSingleOps(shape, "DemoteTo")
        + demoteSingleOps(shape, "ShiftRightAndDemoteTo", shift: .plain)
        + demoteSingleOps(shape, "RoundingShiftRightAndDemoteTo", shift: .rounding)
}

func demoteFloatConverts(_ source: Element, _ result: Element) -> Bool {
    source.bits == 64 && result.bits == 32
        && (source.category == .float || result.category == .float)
}

func float16DemotionSourceInputs(
    of op: Op,
    operand: Element,
    for element: Element,
    seed: String
) -> String? {
    guard op.highwayName == "DemoteTo", operand.category == .float, element.category == .float16
    else { return nil }
    return "Inputs.float16Demotions(\(operand.namespace).Vector.self, \(seed))"
}

func floatDemotionSourceInputs(
    of op: Op,
    operand: Element,
    for element: Element,
    seed: String
) -> String? {
    let demotions = ["DemoteTo", "DemoteInRangeTo", "DemoteToNearestInt"]
    guard demotions.contains(op.highwayName), demoteFloatConverts(operand, element) else {
        return nil
    }
    return "Inputs.floatDemotions(\(operand.namespace).Vector.self, \(seed))"
}

func narrowedLanes(
    _ operand: String,
    _ shape: Shape,
    arm: Bool,
    for element: Element
) -> String {
    let lanes = element.laneCount(of: shape)
    let padding = partialRegisterLanes(of: shape, for: element, arm: arm) - lanes
    let indices = laneIndices(Array(0..<lanes) + Array(repeating: -1, count: padding))
    return narrowResult(
        "__builtin_shufflevector(\(operand), \(operand), \(indices))",
        shape,
        for: element
    )
}

func narrowedResult(
    _ operand: String,
    _ shape: Shape,
    arm: Bool,
    for element: Element
) -> String {
    guard partialRegisterLanes(of: shape, for: element, arm: arm) > element.laneCount(of: shape)
    else { return narrowResult(operand, shape, for: element) }
    return narrowedLanes(operand, shape, arm: arm, for: element)
}

func narrowedBlock(_ expression: String, _ shape: Shape, for result: Element) -> String {
    """
    const \(result.cBlock) block = (\(result.cBlock))\(expression);
    \(narrowedResult("block", shape, arm: false, for: result))
    """
}

func demoteFloatNearestLane(from source: Element, to result: Element) -> String {
    let (lowest, highest) = (lowestValue(of: result), highestValue(of: result))
    let absolute = scalarAbsolute(of: source)
    return """
        const bool negative = __builtin_signbit(value);
        if (!(\(absolute)(value) < 2147483648.0)) {
          converted[i] = negative ? \(lowest) : \(highest);
          continue;
        }
        const double clamped = value < 2147483647.0 ? value : 2147483647.0;
        const double bias = value < 0.0 ? -0.5 : 0.5;
        const int32_t rounded = (int32_t)(clamped + bias);
        const double distance = \(absolute)((double)rounded - clamped);
        converted[i] = (rounded & 1) && distance == 0.5 ? rounded - (negative ? -1 : 1) : rounded;
        """
}

func demoteFloatPortable(
    _ conversion: FloatToIntConversion,
    from source: Element,
    to result: Element
) -> String {
    let narrow = result.cVector(of: .half)
    guard convertsFloatToInteger(from: source, to: result) else {
        return """
            const \(narrow) converted = __builtin_convertvector(a, \(narrow));
            \(narrowedResult("converted", .half, arm: false, for: result))
            """
    }
    let lane: String
    switch conversion {
    case .nearestEven:
        lane = demoteFloatNearestLane(from: source, to: result)
    default:
        let truncated = floatToIntTruncatedLane(
            inRangeOnly: conversion == .inRange,
            from: source,
            to: result
        )
        lane = "converted[i] = \(truncated);"
    }
    return """
        \(narrow) converted;
        for (size_t i = 0; i < \(source.laneCount); ++i) {
          const \(source.cType) value = a[i];
        \(indented(lane))
        }
        \(narrowedResult("converted", .half, arm: false, for: result))
        """
}

func demoteFloatNeon(
    _ conversion: FloatToIntConversion,
    from source: Element,
    to result: Element
) -> String {
    let narrow = result.cVector(of: .half)
    guard convertsFloatToInteger(from: source, to: result) else {
        return """
            const \(narrow) converted = __builtin_convertvector(a, \(narrow));
            \(narrowedResult("converted", .half, arm: true, for: result))
            """
    }
    let wide = resizedElement(of: result, bits: 64)
    return """
        \(floatToIntNeon(conversion, to: wide))
        \(narrowResult(demoteNeonNarrowed("converted", from: wide, to: result), .half, for: result))
        """
}

func demoteFloatX86Converting(
    _ operand: String,
    rounding: Bool,
    unsigned: Bool = false,
    to result: Element
) -> String {
    let name = "cvt\(rounding ? "" : "t")pd2\(unsigned ? "u" : "")dq"
    let float = x86Vector("f64")
    guard result.width == 64 else {
        return "__builtin_ia32_\(name)\(x86UnsuffixedBits(result.width))((\(float))\(operand))"
    }
    let zero = compoundLiteral("signed_words", ["0"])
    let arguments = ["(\(float))\(operand)", zero, "(unsigned char)-1", "\(x86CurrentRounding)"]
    return "__builtin_ia32_\(name)512_mask(\(arguments.joined(separator: ", ")))"
}

func demoteFloatX86NonNegative(level: X86Level, from source: Element) -> [String] {
    guard level == .avx2 else { return floatToIntX86NonNegative(level: level, from: source) }
    let zeroed = x86Builtin(
        "blendvpd256",
        ["a", compoundLiteral("float_vector", ["0"]), "a"],
        as: "f64",
        returning: "float_vector"
    )
    return ["const float_vector nonNegative = \(zeroed);"]
}

func demoteFloatX86Statements(
    _ conversion: FloatToIntConversion,
    level: X86Level,
    from source: Element,
    to result: Element
) -> [String] {
    let lanes = source.laneCount
    let rounding = conversion == .nearestEven
    func returning(_ operand: String) -> String {
        narrowResult(
            demoteFloatX86Converting(operand, rounding: rounding, to: result),
            .half,
            for: result
        )
    }
    func clamped(_ operand: String, to limit: String) -> String {
        let maximum = splat(limit, as: "float_vector", lanes: lanes)
        return "const float_vector clamped = \(x86Extremum("min", operand, maximum, for: source));"
    }
    guard result.category == .unsignedInteger else {
        guard conversion != .inRange else { return [returning("a")] }
        return [clamped("a", to: "2147483647.0"), returning("clamped")]
    }
    let saturating = conversion == .saturating
    let nonNegative = saturating ? demoteFloatX86NonNegative(level: level, from: source) : []
    guard level < .avx3 else {
        let converted = demoteFloatX86Converting(
            saturating ? "nonNegative" : "a",
            rounding: false,
            unsigned: true,
            to: result
        )
        return nonNegative + [narrowResult(converted, .half, for: result)]
    }
    let operand = saturating ? "clamped" : "a"
    let evens = Array(stride(from: 0, to: 2 * lanes, by: 2))
    let padding = Array(
        repeating: -1,
        count: partialRegisterLanes(of: .half, for: result, arm: false) - lanes
    )
    let upper = "__builtin_shufflevector(words, words, \(laneIndices(evens + padding)))"
    let raw = result.cRawVector(of: .half)
    return nonNegative + (saturating ? [clamped("nonNegative", to: "4294967295.0")] : []) + [
        "const float_vector limit = \(splat("2147483648.0", as: "float_vector", lanes: lanes));",
        "const signed_vector high = (signed_vector)(\(operand) >= limit);",
        "const float_vector adjusted = \(operand) - (float_vector)((unsigned_vector)high & (unsigned_vector)limit);",
        "const unsigned_words words = (unsigned_words)high;",
        "const \(raw) lower = (\(raw))\(demoteFloatX86Converting("adjusted", rounding: false, to: result));",
        "const \(raw) upper = (\(raw))\(upper) << 31;",
        narrowResult("lower | upper", .half, for: result),
    ]
}

func demoteFloatX86UnsignedToSingle(from source: Element, to result: Element) -> String {
    let lanes = source.laneCount
    let offset = splat("18446744073709551616.0", as: "float_vector", lanes: lanes)
    let wordLanes = max(16, source.width / 2) / 4
    let evens = laneIndices((0..<wordLanes).map { $0 % lanes * 2 })
    let converted =
        wordLanes == lanes
        ? "masked" : "__builtin_shufflevector(masked, masked, \(laneIndices(0..<lanes)))"
    return """
        typedef double float_vector __attribute__((vector_size(\(source.width))));
        typedef uint64_t unsigned_vector __attribute__((vector_size(\(source.width))));
        typedef int32_t words_vector __attribute__((vector_size(\(source.width))));
        typedef int32_t low_words __attribute__((vector_size(\(max(16, source.width / 2)))));
        const float_vector offset = \(offset);
        const float_vector high = (float_vector)((a >> 12) | (unsigned_vector)offset) - offset;
        const low_words truncated = __builtin_shufflevector((words_vector)a, (words_vector)a, \(evens));
        const low_words masked = truncated & 0xFFF;
        const float_vector low = __builtin_convertvector(\(converted), float_vector);
        const float_vector sum = high + low;
        const float_vector carry = (high - sum) + low;
        const unsigned_vector inexact = (unsigned_vector)(carry != (float_vector){0}) >> 63;
        const unsigned_vector decrement = (unsigned_vector)carry >> 63;
        const float_vector adjusted = (float_vector)(((unsigned_vector)sum - decrement) | inexact);
        \(demoteFloatX86Narrowed("adjusted", to: result))
        """
}

func demoteFloatX86Narrowed(_ operand: String, to result: Element) -> String {
    let doubles = "(\(x86Vector("f64")))\(operand)"
    guard result.width == 64 else {
        let call = "__builtin_ia32_cvtpd2ps\(x86UnsuffixedBits(result.width))(\(doubles))"
        return narrowResult(call, .half, for: result)
    }
    let zero = compoundLiteral(result.cVector(of: .half), ["0"])
    let arguments = [doubles, zero, "(unsigned char)-1", "\(x86CurrentRounding)"]
    return narrowResult(
        "__builtin_ia32_cvtpd2ps512_mask(\(arguments.joined(separator: ", ")))",
        .half,
        for: result
    )
}

func demoteFloatX86(
    _ conversion: FloatToIntConversion,
    level: X86Level,
    from source: Element,
    to result: Element
) -> String? {
    guard convertsFloatToInteger(from: source, to: result) else {
        if source.category == .float { return demoteFloatX86Narrowed("a", to: result) }
        guard source.category == .unsignedInteger, level < .avx3 else { return nil }
        return demoteFloatX86UnsignedToSingle(from: source, to: result)
    }
    let body = demoteFloatX86Statements(conversion, level: level, from: source, to: result)
        .joined(separator: "\n")
    let lanes = source.laneCount
    let types = [
        ("float_vector", "double", 64, lanes), ("unsigned_vector", "uint64_t", 64, lanes),
        ("signed_vector", "int64_t", 64, lanes), ("words_vector", "int32_t", 32, 2 * lanes),
        ("unsigned_words", "uint32_t", 32, 2 * lanes), ("signed_words", "int32_t", 32, lanes),
    ]
    let declarations = types.filter {
        body.range(of: "\\b\($0.0)\\b", options: .regularExpression) != nil
    }
    .map { vectorTypedef($0.0, lane: $0.1, bits: $0.2, lanes: $0.3) }
    return (declarations + [body]).joined(separator: "\n")
}

func demoteFloatOp(
    _ highwayName: String,
    label: String,
    conversion: FloatToIntConversion,
    section: Section,
    accepting: @escaping (Element, Element) -> Bool
) -> [Op] {
    sourcedOps(accepting: accepting) { source, results in
        func x86(_ level: X86Level) -> (Element) -> String? {
            sourced(source) { source, result in
                demoteFloatX86(conversion, level: level, from: source, to: result)
            }
        }
        return Op(
            "halfVector",
            highwayName,
            [.narrowTag(.half), .sourceVector],
            .narrowVector(.half),
            results,
            section: section,
            vectorLabels: [label],
            source: source,
            targets: TargetBodies(
                neon: sourced(source) { source, result in
                    demoteFloatNeon(conversion, from: source, to: result)
                },
                sve2_128: sourced(source) { source, result in
                    source.category == .float ? nil : demoteSveConverting(from: source, to: result)
                },
                avx3: x86(.avx3),
                avx2: x86(.avx2),
                sse4: x86(.sse4),
                sse2: x86(.sse2)
            ),
            portable: sourced(source) { source, result in
                demoteFloatPortable(conversion, from: source, to: result)
            }
        )
    }
}

func demoteFloatToInteger(_ source: Element, _ result: Element) -> Bool {
    demoteFloatConverts(source, result) && convertsFloatToInteger(from: source, to: result)
}

func demoteFloatToSigned(_ source: Element, _ result: Element) -> Bool {
    demoteFloatToInteger(source, result) && result.category == .signedInteger
}

func truncatesLanes(from source: Element, to result: Element, into shape: Shape) -> Bool {
    source.category == .unsignedInteger && result.category == .unsignedInteger
        && result.bits < source.bits && source.bits == result.bits * (shape.fraction ?? 0)
}

func demoteTruncated(_ shape: Shape, arm: Bool, for result: Element) -> String {
    let narrow = result.cVector(of: shape)
    return """
        const \(narrow) converted = __builtin_convertvector(a, \(narrow));
        \(narrowedResult("converted", shape, arm: arm, for: result))
        """
}

enum DemoteGathering {
    case halves
    case quarters
    case merged
}

func demoteX86Avx2Gathered(
    _ lookup: [String],
    laneBits: Int,
    _ gathering: DemoteGathering,
    shape: Shape,
    for result: Element
) -> String {
    let quads = x86Vector("i64")
    let lookupType = vectorTypedef(
        "lookup_vector",
        lane: "uint\(laneBits)_t",
        bits: laneBits,
        lanes: lookup.count
    )
    let lookups = """
        \(lookupType)
        const lookup_vector lookup = \(compoundLiteral("lookup_vector", lookup));
        const \(quads) quads = (\(quads))__builtin_ia32_pshufb256((\(x86Vector("i8")))a, (\(x86Vector("i8")))lookup);
        """
    let block = x86Block("i64")
    switch gathering {
    case .halves:
        return """
            \(lookups)
            \(narrowResult("__builtin_shufflevector(quads, quads, 0, 3)", shape, for: result))
            """
    case .quarters:
        let words = x86Block("i32")
        let packed =
            "__builtin_ia32_packusdw128((\(words))mixed, (\(words))mixed)"
        return """
            \(lookups)
            const \(block) mixed = __builtin_shufflevector(quads, quads, 0, 3);
            \(narrowedBlock(packed, shape, for: result))
            """
    case .merged:
        return """
            \(lookups)
            const \(block) lower = __builtin_shufflevector(quads, quads, 0, 1);
            const \(block) upper = __builtin_shufflevector(quads, quads, 2, 3);
            \(narrowedBlock("lower | upper", shape, for: result))
            """
    }
}

func demoteTruncatedAvx2(from source: Element, to result: Element, shape: Shape) -> String? {
    func halves(_ low: String, _ high: String) -> String {
        let none = "~0u"
        let lookup = [low, high, none, none, none, none, low, high]
        return demoteX86Avx2Gathered(lookup, laneBits: 32, .halves, shape: shape, for: result)
    }
    func quarters(_ low: String, _ high: String) -> String {
        let none = "0xFFFF"
        let lookup =
            [low, none, high] + Array(repeating: none, count: 9) + [low, none, high, none]
        return demoteX86Avx2Gathered(lookup, laneBits: 16, .quarters, shape: shape, for: result)
    }
    switch (source.bits, result.bits) {
    case (16, 8): return halves("0x06040200u", "0x0E0C0A08u")
    case (32, 16): return halves("0x05040100u", "0x0D0C0908u")
    case (32, 8): return quarters("0x400", "0xC08")
    case (64, 16): return quarters("0x100", "0x908")
    case (64, 8):
        let lookup = ["0xFFFF0800u", "~0u", "~0u", "~0u", "0x0800FFFFu", "~0u", "~0u", "~0u"]
        return demoteX86Avx2Gathered(lookup, laneBits: 32, .merged, shape: shape, for: result)
    default: return nil
    }
}

func demoteTruncatedSse2(from source: Element, to result: Element, shape: Shape) -> String? {
    let signed = x86Vector("i\(source.bits)")
    let words = x86Vector("i16")
    switch (source.bits, result.bits) {
    case (64, 8), (64, 16):
        let lanes = x86Vector("i\(result.bits)")
        let high = "(\(lanes))__builtin_shufflevector(a, a, 1, 3)"
        let interleaved = laneIndices(
            (0..<8 / (result.bits / 8)).flatMap { [$0, 16 / (result.bits / 8) + $0] }
        )
        return narrowedBlock(
            "__builtin_shufflevector((\(lanes))a, \(high), \(interleaved))",
            shape,
            for: result
        )
    case (32, 16), (16, 8):
        let amount = result.bits
        let packing = source.bits == 32 ? "packssdw" : "packsswb"
        let packed = "__builtin_ia32_\(packing)128(shifted, shifted)"
        return """
            const \(signed) shifted = (\(signed))(a << \(amount)) >> \(amount);
            \(narrowedBlock(packed, shape, for: result))
            """
    case (32, 8):
        let packed = x86Packing("packuswb", "words", "words", from: "i16", to: "i8", width: 16)
        return """
            const \(signed) masked = (\(signed))((a << 24) >> 24);
            const \(words) words = \(x86Packing("packssdw", "masked", "masked", from: "i32", to: "i16", width: 16));
            \(narrowedBlock(packed, shape, for: result))
            """
    default:
        return nil
    }
}

func demoteTruncatedNeon(from source: Element, to result: Element, shape: Shape) -> String {
    let lanes = 16 / (result.bits / 8)
    let evens = Array(stride(from: 0, to: lanes, by: 2))
    let steps = (source.bits / result.bits).trailingZeroBitCount
    let narrowings = (1...steps).map { step in
        let previous = "narrowed\(step - 1)"
        return
            "const even_vector narrowed\(step) = __builtin_shufflevector(\(previous), \(previous), \(laneIndices(evens + evens)));"
    }
    return """
        \(vectorTypedef("even_vector", lane: result.cType, bits: result.bits, lanes: lanes))
        const even_vector narrowed0 = (even_vector)a;
        \(narrowings.joined(separator: "\n"))
        \(narrowedLanes("narrowed\(steps)", shape, arm: true, for: result))
        """
}

func demoteSveUnzipped(
    through stages: [Element],
    shape: Shape,
    from source: Element,
    to result: Element
) -> String {
    var statements = [
        "const \(sveType(of: source)) unzipped0 = \(sveSplatOperand("a", for: source));"
    ]
    for (index, (previous, stage)) in zip([source] + stages, stages).enumerated() {
        let operand = sveReinterpreted("unzipped\(index)", from: previous, to: stage)
        let unzipped = sveBuiltin("uzp1", [operand, operand], for: stage)
        statements.append("const \(sveType(of: stage)) unzipped\(index + 1) = \(unzipped);")
    }
    statements.append(
        "const \(result.cVector) narrowed = \(sveResult("unzipped\(stages.count)", for: result));"
    )
    statements.append(narrowedLanes("narrowed", shape, arm: true, for: result))
    return statements.joined(separator: "\n")
}

func demoteSveConverting(from source: Element, to result: Element) -> String {
    let converted = sveBuiltin(
        "cvt_f32",
        [sveAllLanes(of: result), sveSplatOperand("a", for: source)],
        for: source,
        predication: "x"
    )
    let unzipped = sveBuiltin("uzp1", ["converted", "converted"], for: result)
    return """
        const \(sveType(of: result)) converted = \(converted);
        const \(result.cVector) narrowed = \(sveResult(unzipped, for: result));
        \(narrowedLanes("narrowed", .half, arm: true, for: result))
        """
}

let demoteFloatTruncatingOps = [Shape.half, .quarter, .eighth].flatMap { shape in
    sourcedOps(accepting: { truncatesLanes(from: $0, to: $1, into: shape) }) { source, results in
        func x86(
            _ gathering: @escaping (Element, Element, Shape) -> String?
        ) -> (Element) -> String? {
            sourced(source) { source, result in gathering(source, result, shape) }
        }
        return Op(
            shape.conversion("vector"),
            "TruncateTo",
            [.narrowTag(shape), .sourceVector],
            .narrowVector(shape),
            results,
            section: .singleVectorDemotion,
            vectorLabels: ["truncatingIfNeeded"],
            source: source,
            targets: TargetBodies(
                neon: sourced(source) { source, result in
                    demoteTruncatedNeon(from: source, to: result, shape: shape)
                },
                sve2_128: sourced(source) { source, result in
                    demoteSveUnzipped(
                        through: Array(
                            repeating: result,
                            count: (source.bits / result.bits).trailingZeroBitCount
                        ),
                        shape: shape,
                        from: source,
                        to: result
                    )
                },
                avx2: x86(demoteTruncatedAvx2),
                ssse3: { result in demoteTruncated(shape, arm: false, for: result) },
                sse2: x86(demoteTruncatedSse2)
            ),
            portable: { result in demoteTruncated(shape, arm: false, for: result) }
        )
    }
}

func demoteU8FromU32(saturating: Bool, arm: Bool, for result: Element) -> String {
    let narrow = result.cVector(of: .quarter)
    let source = unsignedElement(bits: 32).at(width: result.width)
    let highest = splat("UINT8_MAX", as: source.cVector, lanes: source.laneCount)
    let operand = saturating ? "__builtin_elementwise_min(a, \(highest))" : "a"
    return """
        const \(narrow) converted = __builtin_convertvector(\(operand), \(narrow));
        \(narrowedResult("converted", .quarter, arm: arm, for: result))
        """
}

func demoteU8FromU32Packed(for result: Element) -> String {
    let words = x86Packing("packssdw", "a", "a", from: "i32", to: "i16", width: 16)
    let bytes = x86Packing("packuswb", "words", "words", from: "i16", to: "i8", width: 16)
    return """
        const \(x86Vector("i16")) words = \(words);
        \(narrowedBlock(bytes, .quarter, for: result))
        """
}

func convertsU8FromU32(_ source: Element, _ result: Element) -> Bool {
    source.suffix == "U32" && result.suffix == "U8"
}

let demoteFloatU8FromU32Ops = sourcedOps(accepting: convertsU8FromU32) { source, results in
    func truncating(arm: Bool) -> (Element) -> String {
        { result in demoteU8FromU32(saturating: false, arm: arm, for: result) }
    }
    let neon = sourced(source) { source, result in
        demoteTruncatedNeon(from: source, to: result, shape: .quarter)
    }
    return Op(
        "quarterVector",
        "U8FromU32",
        [.sourceVector],
        .narrowVector(.quarter),
        results,
        section: .typeConversion,
        vectorLabels: ["convertingInRange"],
        source: source,
        targets: TargetBodies(
            neon: neon,
            sve2_128: sourced(source) { source, result in
                demoteSveUnzipped(
                    through: [unsignedElement(bits: 16).at(width: result.width), result],
                    shape: .quarter,
                    from: source,
                    to: result
                )
            },
            avx3: truncating(arm: false),
            avx2: { result in
                let lookup = [
                    "0x0C080400u", "~0u", "~0u", "~0u", "~0u", "0x0C080400u", "~0u", "~0u",
                ]
                return demoteX86Avx2Gathered(
                    lookup,
                    laneBits: 32,
                    .merged,
                    shape: .quarter,
                    for: result
                )
            },
            ssse3: truncating(arm: false),
            sse2: { result in demoteU8FromU32Packed(for: result) }
        ),
        portable: { result in demoteU8FromU32(saturating: true, arm: false, for: result) }
    )
}

let demoteFloatOps: [Op] =
    demoteFloatOp(
        "DemoteTo",
        label: "converting",
        conversion: .saturating,
        section: .singleVectorDemotion,
        accepting: demoteFloatConverts
    )
    + demoteFloatOp(
        "DemoteInRangeTo",
        label: "convertingInRange",
        conversion: .inRange,
        section: .singleVectorDemotion,
        accepting: demoteFloatToInteger
    )
    + demoteFloatOp(
        "DemoteToNearestInt",
        label: "roundingToNearestOrEven",
        conversion: .nearestEven,
        section: .typeConversion,
        accepting: demoteFloatToSigned
    )
    + demoteFloatTruncatingOps + demoteFloatU8FromU32Ops

func narrowMaskResult(_ expression: String, _ shape: Shape, for element: Element) -> String {
    "return (\(element.cRawMask(of: shape)))(\(expression));"
}

func halfOfMask(upper: Bool, arm: Bool, for element: Element) -> String {
    let indices = halfIndices(upper: upper, arm: arm, for: element)
    return narrowMaskResult("__builtin_shufflevector(mask, mask, \(indices))", .half, for: element)
}

func combinedHalfMasks(arm: Bool, for element: Element) -> String {
    let indices = combinedHalvesIndices(arm: arm, for: element)
    return maskResult("__builtin_shufflevector(b, a, \(indices))", for: element)
}

func promotedMask(from source: Element, to result: Element, shape: Shape, arm: Bool) -> String {
    let lanes = source.laneCount(of: shape)
    let register = partialRegisterLanes(of: shape, for: source, arm: arm)
    let operand =
        lanes < register
        ? "__builtin_shufflevector(mask, mask, \(laneIndices(0..<lanes)))" : "mask"
    return maskResult("__builtin_convertvector(\(operand), \(result.cMask))", for: result)
}

func ssse3PromotedMask(from source: Element, to result: Element) -> String? {
    guard result.bits == 64, source.bits <= 16 else { return nil }
    let bytes = source.bits / 8
    let zeroByte = 16
    let spread = (0..<2).flatMap { lane in
        Array(repeating: zeroByte, count: 4 - bytes) + (0..<bytes).map { lane * bytes + $0 }
    }
    let zeroes = splat("0", as: x86Block("i8"), lanes: 16)
    let shuffled =
        "__builtin_shufflevector((\(x86Block("i8")))mask, \(zeroes), \(laneIndices(spread + Array(repeating: zeroByte, count: 8))))"
    let high = "(\(x86Block("i16")))extended"
    return """
        const \(x86Block("i32")) extended = (\(x86Block("i32")))\(shuffled) >> \(32 - source.bits);
        const \(x86Block("i16")) signs = __builtin_shufflevector(\(high), \(high), 1, 1, 3, 3, 4, 5, 6, 7);
        \(maskResult("(\(x86Block("i64")))__builtin_shufflevector(extended, (\(x86Block("i32")))signs, 0, 4, 1, 5)", for: result))
        """
}

func demotedMask(from source: Element, to result: Element, shape: Shape) -> String {
    let lanes = result.laneCount(of: shape)
    let register = partialRegisterLanes(of: shape, for: result, arm: false)
    let narrowed = "__builtin_convertvector(mask, \(result.cMask(of: shape)))"
    guard lanes < register else { return narrowMaskResult(narrowed, shape, for: result) }
    let padding = Array(repeating: -1, count: register - lanes)
    let indices = laneIndices(Array(0..<lanes) + padding)
    return """
        const \(result.cMask(of: shape)) narrowed = \(narrowed);
        \(narrowMaskResult("__builtin_shufflevector(narrowed, narrowed, \(indices))", shape, for: result))
        """
}

func neonDemotedMask(from source: Element, to result: Element, shape: Shape) -> String {
    let signed = signedElement(of: source)
    let padding = laneIndices(Array(0..<8) + Array(repeating: -1, count: 8))
    var statements: [String] = []
    var operand = "mask"
    var bits = source.bits
    while bits > result.bits {
        let step = (
            from: resizedElement(of: signed, bits: bits),
            to: resizedElement(of: signed, bits: bits / 2)
        )
        let name = "narrowed\(statements.count + 1)"
        let narrowed = demoteNeonNarrowed(operand, from: step.from, to: step.to)
        statements.append("const \(neonVector("i8x8")) \(name) = \(narrowed);")
        operand = "__builtin_shufflevector(\(name), \(name), \(padding))"
        bits /= 2
    }
    let last = "narrowed\(statements.count)"
    return (statements + [narrowMaskResult(last, shape, for: result)]).joined(separator: "\n")
}

func x86PackedMask(from source: Element, to result: Element, shape: Shape) -> String? {
    guard source.bits <= 32 else { return nil }
    func pack(_ bits: Int, _ operands: [String]) -> String {
        x86Builtin(
            "\(demoteX86PackName(sourceBits: bits, unsigned: false))128",
            operands.map { (value: $0, type: x86Block("i\(bits)")) },
            returning: x86Block("i\(bits / 2)")
        )
    }
    let lanes = source.laneCount
    let operands =
        source.width == 16
        ? ["mask", "mask"]
        : [0..<lanes / 2, lanes / 2..<lanes].map {
            "__builtin_shufflevector(mask, mask, \(laneIndices($0)))"
        }
    let packed = pack(source.bits, operands)
    guard source.bits / result.bits > 2 else { return narrowMaskResult(packed, shape, for: result) }
    return """
        const \(x86Block("i\(source.bits / 2)")) packed = \(packed);
        \(narrowMaskResult(pack(source.bits / 2, ["packed", "packed"]), shape, for: result))
        """
}

func saturatedMaskDemotion(
    _ demotion: (_ source: Element, _ result: Element) -> String,
    from source: Element,
    to result: Element
) -> String {
    let signedSource = signedElement(of: source).at(width: source.width)
    let signedResult = signedElement(of: result).at(width: result.width)
    return """
        const \(signedSource.cVector) a = (\(signedSource.cVector))mask;
        \(demotion(signedSource, signedResult))
        """
}

func x86DemotedMask(
    level: X86Level,
    from source: Element,
    to result: Element,
    shape: Shape
) -> String {
    if let packed = x86PackedMask(from: source, to: result, shape: shape) { return packed }
    let table = demoteSingleX86TableName("DemoteMaskTo", from: source, to: result)
    return saturatedMaskDemotion(
        {
            demoteSingleX86Body(
                level: level,
                table: table,
                nil,
                shape,
                from: $0,
                to: $1,
                isMask: true
            )
        },
        from: source,
        to: result
    )
}

func portableDemotedMask(from source: Element, to result: Element, shape: Shape) -> String {
    saturatedMaskDemotion(
        { demoteSinglePortable("a", shape, from: $0, to: $1, isMask: true) },
        from: source,
        to: result
    )
}

let narrowMaskHalfOps: [Op] = [
    Op(
        "lowerHalf",
        "LowerHalfOfMask",
        [.narrowTag(.half), .mask],
        .narrowMask(.half),
        .all,
        section: .combineMask,
        identifier: "lowerHalfOfMask",
        targets: TargetBodies(neon: { halfOfMask(upper: false, arm: true, for: $0) }),
        acceptsNonCanonicalMasks: true
    ) { element in
        halfOfMask(upper: false, arm: false, for: element)
    },
    Op(
        "upperHalf",
        "UpperHalfOfMask",
        [.narrowTag(.half), .mask],
        .narrowMask(.half),
        .all,
        section: .combineMask,
        identifier: "upperHalfOfMask",
        targets: TargetBodies(neon: { halfOfMask(upper: true, arm: true, for: $0) }),
        acceptsNonCanonicalMasks: true
    ) { element in
        halfOfMask(upper: true, arm: false, for: element)
    },
    Op(
        "combining",
        "CombineMasks",
        [.tag, .narrowMask(.half), .narrowMask(.half)],
        .mask,
        .all,
        section: .combineMask,
        identifier: "combiningMasks",
        targets: TargetBodies(neon: { combinedHalfMasks(arm: true, for: $0) }),
        acceptsNonCanonicalMasks: true
    ) { element in
        combinedHalfMasks(arm: false, for: element)
    },
]

let narrowMaskPromotionOps: [Op] = Shape.allCases.filter { $0 != .full && $0.hasMask }.flatMap {
    shape in
    sourcedOps(
        accepting: includingFloat16 { source, result in
            source.supports(shape) && result.bits == source.bits * (shape.fraction ?? 1)
        },
        includingHalfPrecision: true
    ) { source, results in
        Op(
            "mask",
            "PromoteMaskTo",
            [.tag, .sourceNarrowTag(shape), .sourceNarrowMask(shape)],
            .mask,
            results,
            section: .convertMask,
            maskLabels: ["widening"],
            source: source,
            targets: TargetBodies(
                neon: sourced(source) { source, result in
                    promotedMask(from: source, to: result, shape: shape, arm: true)
                },
                sse4: sourced(source) { source, result in
                    promotedMask(from: source, to: result, shape: shape, arm: false)
                },
                ssse3: sourced(source) { source, result in
                    ssse3PromotedMask(from: source, to: result)
                        ?? promotedMask(from: source, to: result, shape: shape, arm: false)
                }
            ),
            acceptsNonCanonicalMasks: true,
            portable: sourced(source) { source, result in
                promotedMask(from: source, to: result, shape: shape, arm: false)
            }
        )
    }
}

let narrowMaskDemotionOps: [Op] = Shape.allCases.filter { $0 != .full && $0.hasMask }.flatMap {
    shape in
    sourcedOps(
        accepting: includingFloat16 { source, result in
            result.supports(shape) && source.bits == result.bits * (shape.fraction ?? 1)
        },
        includingHalfPrecision: true
    ) { source, results in
        func x86Demoted(_ level: X86Level) -> (Element) -> String {
            sourced(source) { source, result in
                x86DemotedMask(level: level, from: source, to: result, shape: shape)
            }
        }
        return Op(
            "\(shape.prefix.lowercased())Mask",
            "DemoteMaskTo",
            [.narrowTag(shape), .sourceTag, .sourceMask],
            .narrowMask(shape),
            results,
            section: .convertMask,
            maskLabels: ["narrowing"],
            source: source,
            targets: TargetBodies(
                neon: sourced(source) { source, result in
                    neonDemotedMask(from: source, to: result, shape: shape)
                },
                avx3: sourced(source) { source, result in
                    demotedMask(from: source, to: result, shape: shape)
                },
                avx2: x86Demoted(.avx2),
                sse4: x86Demoted(.sse4),
                ssse3: x86Demoted(.ssse3),
                sse2: x86Demoted(.sse2)
            ),
            helpers: TargetBodies(
                avx2: { result in
                    demoteSingleX86Table(
                        "DemoteMaskTo",
                        level: .avx2,
                        from: source.at(width: result.width),
                        to: result
                    )
                }
            ),
            acceptsNonCanonicalMasks: true,
            portable: sourced(source) { source, result in
                portableDemotedMask(from: source, to: result, shape: shape)
            }
        )
    }
}

let narrowMaskOps: [Op] = narrowMaskHalfOps + narrowMaskPromotionOps + narrowMaskDemotionOps

let resizeShapes = Shape.allCases.filter { $0 != .block }

func registerBytes(of shape: Shape, for element: Element, arm: Bool) -> Int {
    shape == .full ? element.width : partialRegisterBytes(of: shape, for: element, arm: arm)
}

func registerType(of shape: Shape) -> String {
    "cvectorization_ops_register_\(shape.cName)"
}

func registerTypedef(of shape: Shape) -> String {
    let vector = "CVECTORIZATION_OPS_VECTOR_BYTES"
    let size =
        shape == .full
        ? vector : "CVECTORIZATION_OPS_PARTIAL_REGISTER_BYTES(\(vector) / \(shape.fraction ?? 1))"
    return "typedef uint8_t \(registerType(of: shape)) __attribute__((vector_size(\(size))));"
}

func resizedRegisterName(from source: Shape, to result: Shape, zeroExtending: Bool) -> String {
    let kind = zeroExtending ? "zero_extend_resize" : "resize"
    return "cvectorization_ops_\(kind)_\(source.cName)_to_\(result.cName)"
}

func resizedRegister(
    from source: Shape,
    to result: Shape,
    zeroing: Bool,
    arm: Bool,
    for element: Element
) -> String {
    let from = registerBytes(of: source, for: element, arm: arm)
    let to = registerBytes(of: result, for: element, arm: arm)
    guard from != to else { return "return a;" }
    let padding = (0..<max(to - from, 0)).map { zeroing ? from + $0 % from : -1 }
    let indices = laneIndices(Array(0..<min(from, to)) + padding)
    let second = zeroing ? compoundLiteral(registerType(of: source), ["0"]) : "a"
    return "return __builtin_shufflevector(a, \(second), \(indices));"
}

func zeroExtendedRegister(
    from source: Shape,
    to result: Shape,
    arm: Bool,
    zeroingRegister: Bool = true,
    wideLanes: Bool = false,
    passingTail: Bool = false,
    for element: Element
) -> String {
    let (kept, grown) = (element.bytes(of: source), element.bytes(of: result))
    guard grown > kept else {
        return resizedRegister(from: source, to: result, zeroing: false, arm: arm, for: element)
    }
    let from = registerBytes(of: source, for: element, arm: arm)
    let to = registerBytes(of: result, for: element, arm: arm)
    let doubles = grown == 2 * kept
    let insertsLanes = (arm || wideLanes) && (doubles || to > 8)
    let lane = insertsLanes ? min(8, 1 << kept.trailingZeroBitCount) : 1
    let zeroed = arm ? (doubles ? grown : to) : (zeroingRegister ? to : grown)
    let zeros = (0..<(zeroed - kept) / lane).map { from / lane + $0 % (from / lane) }
    if passingTail && zeros.count > 1 && grown <= 8 {
        return """
            typedef uint64_t lanes __attribute__((vector_size(\(from))));
            lanes widened = (lanes)a;
            widened[0] = (uint\(kept * 8)_t)widened[0];
            return (\(registerType(of: result)))widened;
            """
    }
    let remaining = (zeroed / lane..<to / lane).map { passingTail && $0 < from / lane ? $0 : -1 }
    let indices = laneIndices(Array(0..<kept / lane) + zeros + remaining)
    let shuffle = { (type: String) in
        "return (\(registerType(of: result)))"
            + "__builtin_shufflevector((\(type))a, \(compoundLiteral(type, ["0"])), \(indices));"
    }
    guard lane > 1 else { return shuffle(registerType(of: source)) }
    return """
        typedef uint\(lane * 8)_t lanes __attribute__((vector_size(\(from))));
        \(shuffle("lanes"))
        """
}

func sveZeroExtendedRegister(
    from source: Shape,
    to result: Shape,
    for element: Element
) -> String? {
    let kept = element.bytes(of: source)
    guard element.bytes(of: result) > 2 * kept else { return nil }
    let bytes = unsignedElement(bits: 8)
    let (from, to) = (
        registerBytes(of: source, for: element, arm: true),
        registerBytes(of: result, for: element, arm: true)
    )
    let padding = Array(repeating: -1, count: element.width - from)
    let widened =
        from == element.width
        ? "a" : "__builtin_shufflevector(a, a, \(laneIndices(Array(0..<from) + padding)))"
    let selected = sveBuiltin(
        "sel",
        [
            sveActiveLanes(String(kept), for: bytes),
            "(\(sveVector(bytes.cSuffix)))\(widened)",
            sveBuiltin("dup_n", ["0"], for: bytes),
        ],
        for: bytes
    )
    let narrowed =
        to == element.width
        ? "zeroed" : "__builtin_shufflevector(zeroed, zeroed, \(laneIndices(Array(0..<to))))"
    return """
        const \(registerType(of: .full)) zeroed = (\(registerType(of: .full)))(\(sveVector(bytes.cSuffix)))\(selected);
        return (\(registerType(of: result)))\(narrowed);
        """
}

func resizeHelperTargets(
    from source: Shape,
    to result: Shape,
    zeroExtending: Bool
) -> (targets: TargetBodies<Element>, portable: (Element) -> String) {
    func body(
        _ element: Element,
        zeroing: Bool,
        arm: Bool,
        zeroingRegister: Bool = true
    ) -> String {
        zeroExtending
            ? zeroExtendedRegister(
                from: source,
                to: result,
                arm: arm,
                zeroingRegister: zeroingRegister,
                for: element
            )
            : resizedRegister(from: source, to: result, zeroing: zeroing, arm: arm, for: element)
    }
    let leavingRegister = { (element: Element) in
        body(element, zeroing: false, arm: false, zeroingRegister: false)
    }
    let zeroedGrowth = { (element: Element) in
        func growth(zeroingRegister: Bool, passingTail: Bool) -> String {
            zeroExtendedRegister(
                from: source,
                to: result,
                arm: false,
                zeroingRegister: zeroingRegister,
                wideLanes: true,
                passingTail: passingTail,
                for: element
            )
        }
        return """
            #if defined(__aarch64__)
            \(growth(zeroingRegister: false, passingTail: true))
            #else
            \(growth(zeroingRegister: zeroExtending, passingTail: false))
            #endif
            """
    }
    let targets = TargetBodies<Element>(
        neon: { body($0, zeroing: true, arm: true) },
        sve2_128: { element in
            if zeroExtending {
                return sveZeroExtendedRegister(from: source, to: result, for: element)
            }
            let grows =
                registerBytes(of: result, for: element, arm: true)
                > registerBytes(of: source, for: element, arm: true)
            return grows ? body(element, zeroing: false, arm: true) : nil
        },
        avx3: leavingRegister,
        avx2: leavingRegister,
        sse4: leavingRegister,
        emu128: zeroedGrowth
    )
    return (targets, { body($0, zeroing: false, arm: false) })
}

func resizeHelpers() -> String {
    let typedefs = resizeShapes.map(registerTypedef(of:))
    let functions = [false, true].flatMap { zeroExtending in
        resizeShapes.flatMap { source in
            resizeShapes.filter { $0 != source }.map { result in
                let (targets, portable) = resizeHelperTargets(
                    from: source,
                    to: result,
                    zeroExtending: zeroExtending
                )
                return cFunction(
                    returns: registerType(of: result),
                    name: resizedRegisterName(
                        from: source,
                        to: result,
                        zeroExtending: zeroExtending
                    ),
                    parameters: ["\(registerType(of: source)) a"],
                    body: cBody(targets, for: unsignedElement(bits: 8), portable: portable)
                )
            }
        }
    }
    return (typedefs.map { "\($0)\n" } + functions).joined()
}

func resizeOp(
    from source: Element,
    in sourceShape: Shape,
    to resultShape: Shape,
    zeroExtending: Bool
) -> Op? {
    let results = elements.filter {
        $0.supports(resultShape) && !($0.suffix == source.suffix && resultShape == sourceShape)
    }
    guard !results.isEmpty else { return nil }
    let resultTag: Parameter = resultShape == .full ? .tag : .narrowTag(resultShape)
    let sourceTag: Parameter = sourceShape == .full ? .sourceTag : .sourceNarrowTag(sourceShape)
    let operand: Parameter =
        sourceShape == .full ? .sourceVector : .sourceNarrowVector(sourceShape)
    let resized = resizedRegisterName(
        from: sourceShape,
        to: resultShape,
        zeroExtending: zeroExtending
    )
    let expression =
        sourceShape == resultShape ? "a" : "\(resized)((\(registerType(of: sourceShape)))a)"
    func resultOf(_ expression: String, for result: Element) -> String {
        resultShape == .full
            ? vectorResult(expression, for: result)
            : narrowResult(expression, resultShape, for: result)
    }
    func narrowedRegister(arm: Bool) -> (Element) -> String? {
        { result in
            guard resultShape == .quarter || resultShape == .eighth else { return nil }
            let register = sourceShape == resultShape ? "a" : expression
            let lanes = partialRegisterLanes(of: resultShape, for: result, arm: arm)
            let unspecified = lanes - result.laneCount(of: resultShape)
            let indices = laneIndices(
                Array(0..<lanes - unspecified) + Array(repeating: -1, count: unspecified)
            )
            let operand = "(\(result.cRawVector(of: resultShape)))\(register)"
            return narrowResult(
                "__builtin_shufflevector(\(operand), \(operand), \(indices))",
                resultShape,
                for: result
            )
        }
    }
    return Op(
        resultShape.conversion("vector"),
        zeroExtending ? "ZeroExtendResizeBitCast" : "ResizeBitCast",
        [resultTag] + (zeroExtending ? [sourceTag] : []) + [operand],
        resultShape == .full ? .vector : .narrowVector(resultShape),
        .results(results),
        section: .typeConversion,
        growth: zeroExtending ? .zeroed : .unspecified,
        vectorLabels: [zeroExtending ? "zeroExtendingResizing" : "resizing"],
        source: source,
        targets: TargetBodies(
            neon: narrowedRegister(arm: true),
            sve2_128: sourced(source) { source, result in
                guard sourceShape == .full, isInteger64(source) else { return nil }
                let splat = sveSplatOperand("a", for: source)
                guard resultShape != .full else {
                    let reinterpreted = sveReinterpretedSplat("a", from: source, to: result)
                    return vectorResult(sveResult(reinterpreted, for: result), for: result)
                }
                let register = "(\(registerType(of: .full)))\(sveResult(splat, for: source))"
                return resultOf("\(resized)(\(register))", for: result)
            },
            emu128: narrowedRegister(arm: false)
        ),
        outOfLineOnSVE: source.isHalfPrecision
            ? .results(results.filter { differentHalfPrecisions(source, $0) }) : nil,
        referenceCall: { result, arguments in
            let name = zeroExtending ? "ZeroExtendResizeBitCast" : "ResizeBitCast"
            let direct = "hn::\(name)(\(arguments.joined(separator: ", ")))"
            guard differentHalfPrecisions(source, result) else { return direct }
            let sourceTag = "\(source.tag(of: sourceShape))()"
            let unsignedSource = unsignedElement(of: source)
            let unsignedTag = "hn::RebindToUnsigned<\(source.tag(of: sourceShape))>()"
            let conversion =
                !zeroExtending && sourceShape.isPartial ? "registerFromPort" : "fromPort"
            let unsignedOperand = referenceConversion(
                sourceShape.conversion(conversion),
                "(\(unsignedSource.cRawVector(of: sourceShape)))a",
                for: unsignedSource
            )
            let tags = arguments.dropLast().map { $0 == sourceTag ? unsignedTag : $0 }
            let viaUnsigned = "hn::\(name)(\((tags + [unsignedOperand]).joined(separator: ", ")))"
            return "\n#if HWY_TARGET == HWY_SVE2_128\n\(viaUnsigned)\n#else\n\(direct)\n#endif\n"
        },
        portable: { result in
            resultOf(expression, for: result)
        }
    )
}

let resizeOps: [Op] = [false, true].flatMap { zeroExtending in
    elements.flatMap { source in
        resizeShapes.filter(source.supports).flatMap { sourceShape in
            resizeShapes.compactMap { resultShape in
                resizeOp(
                    from: source,
                    in: sourceShape,
                    to: resultShape,
                    zeroExtending: zeroExtending
                )
            }
        }
    }
}

let blockIndex = ImmediateArgument(
    name: "index",
    label: "at",
    upperBound: .blocks(offset: -1),
    codegenValue: 0,
    message: "Block is negative or not in the vector"
)

func extractedBlockCases(for element: Element) -> [(amount: Int, body: String)] {
    let lanes = element.blockLaneCount
    return (0..<element.laneCount / lanes).map { block in
        let indices = laneIndices(block * lanes..<(block + 1) * lanes)
        let shuffle = "__builtin_shufflevector(a, a, \(indices))"
        return (amount: block, body: narrowResult(shuffle, .block, for: element))
    }
}

func portableExtractedBlock(for element: Element) -> String {
    let lanes = element.blockLaneCount
    return """
        \(constantSwitch(on: "index", extractedBlockCases(for: element)))
        \(element.cBlock) result;
        #pragma clang loop unroll(full)
        for (size_t i = 0; i < \(lanes); ++i) {
          result[i] = a[index * \(lanes) + i];
        }
        \(narrowResult("result", .block, for: element))
        """
}

func insertedBlockCases(for element: Element) -> [(amount: Int, body: String)] {
    let (lanes, total) = (element.blockLaneCount, element.laneCount)
    let padding = Array(repeating: -1, count: total - lanes)
    let widened = "__builtin_shufflevector(b, b, \(laneIndices(Array(0..<lanes) + padding)))"
    return (0..<total / lanes).map { block in
        guard total > lanes else { return (amount: block, body: vectorResult("b", for: element)) }
        let indices = (0..<total).map { $0 / lanes == block ? total + $0 % lanes : $0 }
        let shuffle = "__builtin_shufflevector(a, \(widened), \(laneIndices(indices)))"
        return (amount: block, body: vectorResult(shuffle, for: element))
    }
}

func portableInsertedBlock(for element: Element) -> String {
    let lanes = element.blockLaneCount
    return """
        \(constantSwitch(on: "index", insertedBlockCases(for: element)))
        \(element.cVector) result = a;
        #pragma clang loop unroll(full)
        for (size_t i = 0; i < \(lanes); ++i) {
          result[index * \(lanes) + i] = b[i];
        }
        \(vectorResult("result", for: element))
        """
}

let blockOps: [Op] = [
    Op(
        "block",
        "ExtractBlock",
        [.vector, .immediate],
        .narrowVector(.block),
        .all,
        section: .gettingSettingBlocks,
        immediates: [blockIndex],
        identifier: "extractingBlock"
    ) { element in
        portableExtractedBlock(for: element)
    },
    Op(
        "replacingBlock",
        "InsertBlock",
        [.vector, .immediate, .narrowVector(.block)],
        .vector,
        .all,
        section: .gettingSettingBlocks,
        immediates: [blockIndex],
        vectorLabels: ["_", "with"]
    ) { element in
        portableInsertedBlock(for: element)
    },
]

