func halfPrecisionNativeVector(for element: Element) -> String {
    vectorTypedef("native_vector", lane: "_Float16", bits: element.bits, lanes: element.laneCount)
}

func halfPrecisionMasked(_ symbol: String, with mask: UInt16, for element: Element) -> String {
    let word = String(mask, radix: 16)
    guard element.category == .float16, element.width == X86Level.avx3.width else {
        let lanes = splat("0x\(word)", as: element.cUnsignedVector, lanes: element.laneCount)
        return "\(unsignedBits("a", of: element)) \(symbol) \(lanes)"
    }
    let wide = signedElement(of: unsignedElement(bits: 64))
    let lanes = splat(
        "(\(wide.cType))0x\(String(repeating: word, count: 4))ULL",
        as: wide.cVector,
        lanes: element.width / 8
    )
    return "(\(wide.cVector))a \(symbol) \(lanes)"
}

func halfPrecisionCopyingSign(for element: Element) -> String {
    guard element.category == .float16, element.width == X86Level.avx3.width else {
        return portableCopyingSign(toMagnitude: false, for: element)
    }
    let wide = unsignedElement(bits: 64).at(width: element.width)
    let signs = splat("0x8000800080008000ULL", as: wide.cVector, lanes: wide.laneCount)
    return vectorResult(
        "((\(wide.cVector))b & \(signs)) | ((\(wide.cVector))a & ~\(signs))",
        for: element
    )
}

func halfPrecisionCopyingSignToMagnitude(for element: Element) -> String {
    let bytes = unsignedElement(bits: 8).at(width: element.width).cVector
    let magnitude = "(\(bytes))\(unsignedBits("a", of: element))"
    let signs =
        "(\(bytes))\(unsignedBits("b", of: element)) & (\(bytes))\(signBitMask(for: element))"
    return """
        #if \(sve2_128Condition)
        \(sveCopyingSign(for: element))
        #else
        \(vectorResult("\(magnitude) | (\(signs))", for: element))
        #endif
        """
}

func halfPrecisionSignBody(
    native: (String) -> String,
    bits: String,
    for element: Element
) -> String {
    """
    #if \(neonHasFloat16Condition)
    \(halfPrecisionNativeVector(for: element))
    \(vectorResult("(\(element.cVector))(\(native("(native_vector)a")))", for: element))
    #else
    \(vectorResult(fromUnsignedBits(bits, of: element), for: element))
    #endif
    """
}

func float16ConcatenatedEvenPacked(for element: Element) -> String {
    let lanes = element.laneCount / 2
    let mask = splat("0xFFFF", as: "wide_vector", lanes: lanes)
    let packed = x86Builtin(
        "packusdw128",
        ["((wide_vector)b & \(mask))", "((wide_vector)a & \(mask))"],
        as: "i32",
        returning: element.cVector
    )
    return """
        \(vectorTypedef("wide_vector", of: unsignedElement(bits: 32), lanes: lanes))
        \(vectorResult(packed, for: element))
        """
}

func float16ConcatenatedDelegation(parity: Int, for element: Element) -> String {
    let unsigned = unsignedElement(of: element).at(width: element.width)
    let name = cFunctionName(parity == 1 ? "concatenatingOdd" : "concatenatingEven", unsigned)
    return vectorResult(
        "\(name)((\(unsigned.cRawVector))rawA, (\(unsigned.cRawVector))rawB)",
        for: element
    )
}

let halfPrecisionTargetBodies: [String: TargetBodies<Element>] = [
    "maskFromVector": TargetBodies(
        sve2_128: { element in
            """
            \(halfPrecisionNativeVector(for: element))
            \(maskResult("(\(element.cMask))((native_vector)a != (native_vector){0})", for: element))
            """
        }
    ),
    "concatenatingOdd": TargetBodies(
        sse2: { x86ConcatenatedParity(parity: 1, level: .sse2, for: $0) }
    ),
    "concatenatingEven": TargetBodies(sse4: { float16ConcatenatedEvenPacked(for: $0) }),
    "storeInterleaved4": TargetBodies(
        avx3: { element in
            element.category == .float16
                ? x86Avx3StoreInterleaved4(pointer: "((uint16_t*)to)", for: element) : nil
        }
    ),
    "storeWhere": TargetBodies(
        avx2: { element in
            guard element.category == .float16 else { return nil }
            let block = x86Block("i16")
            let halves = [("lower", 0), ("upper", 8)].map { name, start in
                "const \(block) \(name) = (\(block))__builtin_shufflevector(a, a, \(laneIndices(start..<start + 8)));"
            }
            return x86Avx2HoistedMaskedStore(for: element, declaring: halves) {
                "((uint16_t*)to)[\($0)] = \($0 < 8 ? "lower" : "upper")[\($0 % 8)];"
            }
        }
    ),
]

let halfPrecisionBodies: [String: (Element) -> String] = [
    "repeating": { element in
        vectorResult(
            splat("value", as: unsignedElement(of: element).cVector, lanes: element.laneCount),
            for: element
        )
    },
    "negated": { element in
        halfPrecisionSignBody(
            native: { "-\($0)" },
            bits: halfPrecisionMasked("^", with: 0x8000, for: element),
            for: element
        )
    },
    "magnitude": { element in
        halfPrecisionSignBody(
            native: { "__builtin_elementwise_abs(\($0))" },
            bits: halfPrecisionMasked("&", with: 0x7fff, for: element),
            for: element
        )
    },
    "concatenatingOdd": { element in float16ConcatenatedDelegation(parity: 1, for: element) },
    "concatenatingEven": { element in float16ConcatenatedDelegation(parity: 0, for: element) },
    "copyingSign": { element in halfPrecisionCopyingSign(for: element) },
    "copyingSignToMagnitude": { element in halfPrecisionCopyingSignToMagnitude(for: element) },
    "negatingIfNegative": { element in portableNegatingIfNegative(for: element) },
    "lane": { element in
        let unsigned = unsignedElement(of: element).at(width: element.width)
        let delegated =
            "\(cFunctionName("lane", unsigned))((\(unsigned.cRawVector))rawA, index)"
        let lane = sveBuiltin(
            "lasta",
            [sveActiveLanes("index", for: element), sveSplatOperand("a", for: element)],
            for: element
        )
        return """
            #if \(sve2_128Condition)
            if (__builtin_constant_p(index)) {
              return \(delegated);
            }
            return __builtin_bit_cast(uint16_t, \(lane));
            #else
            return \(delegated);
            #endif
            """
    },
    "maskFromVector": { element in
        let unsigned = unsignedElement(of: element).at(width: element.width)
        return
            "return (\(element.cRawMask))\(cFunctionName("maskFromVector", unsigned))((\(unsigned.cRawVector))rawA);"
    },
    "storeInterleaved4": { element in
        let unsigned = unsignedElement(of: element).at(width: element.width)
        let operands = ["rawA", "rawB", "rawC", "rawD"].map { "(\(unsigned.cRawVector))\($0)" }
        return
            "\(cFunctionName("storeInterleaved4", unsigned))(\(operands.joined(separator: ", ")), (\(unsigned.cType)*)to);"
    },
    "storeWhere": { element in
        let unsigned = unsignedElement(of: element).at(width: element.width)
        return
            "\(cFunctionName("storeWhere", unsigned))((\(unsigned.cRawVector))rawA, (\(unsigned.cRawMask))rawMask, (\(unsigned.cType)*)to);"
    },
    "storeFirst": { element in
        let unsigned = unsignedElement(of: element).at(width: element.width)
        let delegated =
            "\(cFunctionName("storeFirst", unsigned))((\(unsigned.cRawVector))rawA, (\(unsigned.cType)*)to, count);"
        guard element.category == .float16, element.width == 16 else { return delegated }
        return """
            #if \(neonCondition) == \(ArmLevel.neon.rawValue) && (\(neonHasFloat16Condition))
            \(neonStoreFirst(for: element))
            #else
            \(delegated)
            #endif
            """
    },
    "allBitsClear": { element in
        let unsigned = unsignedElement(of: element).at(width: element.width)
        let zero = compoundLiteral(element.cVector, ["0"])
        let allTrue = cFunctionName("allTrue", element)
        func allEqualToZero(_ operand: String, _ zero: String) -> String {
            "return \(allTrue)((\(element.cRawMask))(\(element.cMask))(\(operand) == \(zero)));"
        }
        return """
            #if CVECTORIZATION_OPS_X86 || (\(neonCondition) == \(ArmLevel.neon.rawValue) && !(\(neonHasFloat16Condition)))
            return \(cFunctionName("allBitsClear", unsigned))((\(unsigned.cRawVector))rawA);
            #elif \(neonHasFloat16Condition)
            \(halfPrecisionNativeVector(for: element))
            \(allEqualToZero("(native_vector)a", "(native_vector){0}"))
            #else
            \(allEqualToZero("a", zero))
            #endif
            """
    },
]

let float16ComposedOps: Set<String> = [
    "allBitsClear",
    "duplicatingEven",
    "duplicatingOdd",
    "indices",
    "interleavingEven",
    "interleavingOdd",
    "interleavingUpper",
    "interleavingWholeUpper",
    "lane",
    "loadIndices",
    "lookup16",
    "lookup8",
    "magnitude",
    "oddEven",
    "shuffledPer4Lanes",
    "slide1Down",
    "slideDownLanes",
    "slideDownLanesFillingWith",
    "slideMaskDownLanes",
    "slideMaskUpLanes",
    "slideUpLanes",
    "slideUpLanesFillingWith",
