]

let nativeFloat16Condition = "(HWY_HAVE_FLOAT16 && HWY_ARCH_ARM) || HWY_TARGET == HWY_EMU128"

let float16ReferenceCompositions: [String: ([String]) -> String] = [
    "magnitude": { arguments in
        let unsigned = unsignedElement(bits: 16)
        let bits = "hn::BitCast(\(unsigned.tag)(), \(arguments[0]))"
        let cleared = "hn::AndNot(hn::SignBit(\(unsigned.tag)()), \(bits))"
        return
            "return \(referenceConversion("toPort", "hn::BitCast(\(float16.tag)(), \(cleared))", for: float16));"
    }
]

func extendedToHalfPrecision(_ op: Op) -> Op {
    guard op.source == nil, let extra = bitwiseHalfPrecisionOps[op.identifier] else { return op }
    var extended = op
    extended.applies = op.applies.including(extra)
    return extended
}

enum Float16Promotion {
    case narrow(Shape)
    case lower
    case upper
    case even
    case odd

    var highwayName: String {
        switch self {
        case .narrow: return "PromoteTo"
        case .lower: return "PromoteLowerTo"
        case .upper: return "PromoteUpperTo"
        case .even: return "PromoteEvenTo"
        case .odd: return "PromoteOddTo"
        }
    }

    var label: String {
        switch self {
        case .narrow: return "widening"
        case .lower: return "wideningLower"
        case .upper: return "wideningUpper"
        case .even: return "wideningEven"
        case .odd: return "wideningOdd"
        }
    }

    var parameters: [Parameter] {
        guard case .narrow(let shape) = self else { return [.tag, .sourceVector] }
        return [.tag, .sourceNarrowVector(shape)]
    }

    var parity: Int? {
        switch self {
        case .even: return 0
        case .odd: return 1
        default: return nil
        }
    }

    func accepts(_ source: Element, _ result: Element) -> Bool {
        guard source.category == .float16, result.category == .float else { return false }
        guard case .narrow(let shape) = self else { return result.bits == 2 * source.bits }
        return source.laneCount(of: shape) == result.laneCount
    }

    func lanes(to result: Element) -> [Int] {
        let count = result.laneCount
        switch self {
        case .narrow, .lower: return Array(0..<count)
        case .upper: return Array(count..<2 * count)
        case .even: return (0..<count).map { 2 * $0 }
        case .odd: return (0..<count).map { 2 * $0 + 1 }
        }
    }
}

let float16SprCondition = staticTargetCondition(of: ["AVX3_SPR"])

func float16Singles(_ lanes: Int) -> String {
    vectorTypedef("single_vector", lane: "float", bits: 32, lanes: lanes)
}

func float16PromotedHardware(_ promotion: Float16Promotion, to result: Element) -> String {
    let lanes = promotion.lanes(to: result)
    let singles = lanes.count
    var statements = [
        vectorTypedef("narrow_bits", lane: "short", bits: 16, lanes: max(8, singles)),
        float16Singles(singles),
    ]
    var narrow = result.bits == 64 ? "a" : "__builtin_shufflevector(a, a, \(laneIndices(lanes)))"
    if let parity = promotion.parity, result.width == 32 {
        let bytes = x86Vector("i8")
        let quads = x86Vector("i64")
        let table: [Int] = [0, 4, 8, 12].flatMap { [$0 + 2 * parity, $0 + 2 * parity + 1] }
        let half = table.map(String.init) + Array(repeating: "-1", count: 8)
        let shuffled = x86Builtin(
            "pshufb256",
            [(value: "a", type: bytes), (value: compoundLiteral(bytes, half + half), type: bytes)],
            returning: bytes
        )
        let gathered = x86Builtin(
            "permdi256",
            [(value: "shuffled", type: quads), (value: "232", type: "int")],
            returning: quads
        )
        statements += [
            "const \(bytes) shuffled = \(shuffled);",
            "const \(quads) gathered = \(gathered);",
        ]
        narrow = "__builtin_shufflevector(gathered, gathered, 0, 1)"
    }
    let floats = x86Vector("f32")
    let converted =
        singles == 16
        ? x86Builtin(
            "vcvtph2ps512_mask",
            [
                (value: narrow, type: "narrow_bits"),
                (value: compoundLiteral(floats, ["0"]), type: floats),
                (value: "-1", type: x86MaskType(lanes: 16)),
                (value: String(x86CurrentRounding), type: "int"),
            ],
            returning: "single_vector"
        )
        : x86Builtin(
            singles == 8 ? "vcvtph2ps256" : "vcvtph2ps",
            [(value: narrow, type: "narrow_bits")],
            returning: "single_vector"
        )
    statements.append("const single_vector single = \(converted);")
    statements.append(
        vectorResult(
            result.bits == 64 ? "__builtin_convertvector(single, \(result.cVector))" : "single",
            for: result
        )
    )
    return statements.joined(separator: "\n")
}

func float16SoftwareTypedefs(lanes: Int) -> [String] {
    [
        vectorTypedef("words", lane: "uint32_t", bits: 32, lanes: lanes),
        vectorTypedef("signed_words", lane: "int32_t", bits: 32, lanes: lanes),
        float16Singles(lanes),
    ]
}

func float16PromotedSoftware(_ promotion: Float16Promotion, to result: Element) -> String {
    let lanes = promotion.lanes(to: result)
    var statements = float16SoftwareTypedefs(lanes: lanes.count)
    switch promotion.parity {
    case 0: statements.append("const words bits = (words)a & 0xFFFF;")
    case 1: statements.append("const words bits = (words)a >> 16;")
    default:
        let narrow = "(narrow_bits)__builtin_shufflevector(a, a, \(laneIndices(lanes)))"
        statements += [
            vectorTypedef("narrow_bits", lane: "uint16_t", bits: 16, lanes: lanes.count),
            "const words bits = __builtin_convertvector(\(narrow), words);",
        ]
    }
    statements += [
        "const words magnitude = bits & 0x7FFF;",
        "const words special = (words)(magnitude > 0x7BFF);",
        "const words zero = (words)(magnitude < 0x400);",
        "const words subnormal = (words)(__builtin_convertvector((signed_words)(bits & 0x3FF), single_vector) * 0x1p-24f);",
        "const words normal = ((magnitude << 13) + 0x38000000) | (special & 0x7F800000);",
        "const words combined = (zero & subnormal) | (~zero & normal);",
        "const single_vector single = (single_vector)(((bits & 0x8000) << 16) | combined);",
        vectorResult(
            result.bits == 64 ? "__builtin_convertvector(single, \(result.cVector))" : "single",
            for: result
        ),
    ]
    return statements.joined(separator: "\n")
}

func float16PromotedNeon(
    _ promotion: Float16Promotion,
    from source: Element,
    to result: Element
) -> String {
    guard result.bits == 32 else {
        return promoteNeon(of: promotion.lanes(to: result), from: source, to: result)
    }
    let narrowing = promoteNarrowing(of: promotion.lanes(to: result), from: source, to: result)
    let narrow = "(\(neonVector("i8x8")))v"
    let code = neonTypeCode(of: source) - 32
    return """
        \(narrowing)
        \(vectorResult("(\(result.cVector))__builtin_neon_vcvt_f32_f16(\(narrow), \(code))", for: result))
        """
}

func float16PromotionOps(_ promotion: Float16Promotion) -> [Op] {
    sourcedOps(accepting: promotion.accepts, includingHalfPrecision: true) { source, results in
        let software = sourced(source) { _, result in
            float16PromotedSoftware(promotion, to: result)
        }
        let hardware = sourced(source) { _, result in
            float16PromotedHardware(promotion, to: result)
        }
        return Op(
            "vector",
            promotion.highwayName,
            promotion.parameters,
            .vector,
            results,
            section: .singleVectorPromotion,
            vectorLabels: [promotion.label],
            source: source,
            targets: TargetBodies(
                neon: sourced(source) { source, result in
                    float16PromotedNeon(promotion, from: source, to: result)
                },
                avx3: hardware,
                avx2: hardware,
                sse2: software
            ),
            portable: software
        )
    }
}

enum Float16Demotion {
    case single
    case double

    var shape: Shape { self == .single ? .half : .quarter }

    func accepts(_ source: Element, _ result: Element) -> Bool {
        source.category == .float && result.category == .float16
            && source.bits == (self == .single ? 32 : 64)
            && source.laneCount == result.laneCount(of: shape)
    }
}

func float16RoundedToOdd(from source: Element) -> [String] {
    let quads = unsignedElement(bits: 64).at(width: source.width).cVector
    return [
        "const \(quads) quads = (\(quads))a;",
        "const \(quads) rounded = (quads & 0xFFFFFFFFE0000000u) | ((quads + 0x1FFFFFFF) & 0x20000000);",
    ]
}

func float16DemotedNeon(_ demotion: Float16Demotion, to result: Element) -> String {
    let narrow = result.cVector(of: demotion.shape)
    return """
        const \(narrow) converted = __builtin_convertvector(a, \(narrow));
        \(narrowedResult("converted", demotion.shape, arm: true, for: result))
        """
}

func float16DemotedSpr(from source: Element, to result: Element) -> String {
    let converted = x86Builtin(
        "vcvtpd2ph512_mask",
        [
            (value: "a", type: x86Vector("f64")),
            (value: compoundLiteral("spr_halves", ["0"]), type: "spr_halves"),
            (value: "-1", type: x86MaskType(lanes: source.laneCount)),
            (value: String(x86CurrentRounding), type: "int"),
        ],
        returning: "spr_halves"
    )
    return """
        \(vectorTypedef("spr_halves", lane: "_Float16", bits: 16, lanes: 8))
        \(narrowResult(converted, .quarter, for: result))
        """
}

func float16DemotedHardware(
    _ demotion: Float16Demotion,
    from source: Element,
    to result: Element
) -> String {
    let lanes = source.laneCount
    let doubles = x86Vector("f64")
    var statements = [
        vectorTypedef("narrow_bits", lane: "short", bits: 16, lanes: max(8, lanes)),
        float16Singles(lanes),
    ]
    switch demotion {
    case .single:
        statements.append("const single_vector single = (single_vector)a;")
    case .double:
        let narrowed =
            lanes == 8
            ? x86Builtin(
                "cvtpd2ps512_mask",
                [
                    (value: "odd", type: doubles),
                    (value: compoundLiteral("single_vector", ["0"]), type: "single_vector"),
                    (value: "-1", type: x86MaskType(lanes: lanes)),
                    (value: String(x86CurrentRounding), type: "int"),
                ],
                returning: "single_vector"
            )
            : x86Builtin("cvtpd2ps256", [(value: "odd", type: doubles)], returning: "single_vector")
        statements += float16RoundedToOdd(from: source)
        statements.append("const \(source.cVector) odd = (\(source.cVector))rounded;")
        statements.append("const single_vector single = \(narrowed);")
    }
    let converted =
        lanes == 16
        ? x86Builtin(
            "vcvtps2ph512_mask",
            [
                (value: "single", type: "single_vector"),
                (value: "8", type: "int"),
                (value: compoundLiteral("narrow_bits", ["0"]), type: "narrow_bits"),
                (value: "-1", type: x86MaskType(lanes: 16)),
            ],
            returning: "narrow_bits"
        )
        : x86Builtin(
            lanes == 8 ? "vcvtps2ph256" : "vcvtps2ph",
            [(value: "single", type: "single_vector"), (value: "8", type: "int")],
            returning: "narrow_bits"
        )
    statements.append(narrowResult(converted, demotion.shape, for: result))
    return statements.joined(separator: "\n")
}

func float16DemotedSoftware(
    _ demotion: Float16Demotion,
    x86: Bool,
    from source: Element,
    to result: Element
) -> String {
    let lanes = x86 ? 4 : source.laneCount
    var statements = float16SoftwareTypedefs(lanes: lanes)
    if x86 { statements.append(vectorTypedef("bytes", lane: "uint8_t", bits: 8, lanes: 16)) }
    if demotion == .double {
        let odd = "(\(source.cVector))rounded"
        let narrowed =
            x86
            ? "(single_vector)__builtin_ia32_cvtpd2ps((\(x86Vector("f64")))\(odd))"
            : "__builtin_convertvector(\(odd), single_vector)"
        statements += float16RoundedToOdd(from: source)
        statements.append("const single_vector single = \(narrowed);")
    } else {
        statements.append("const single_vector single = (single_vector)a;")
    }
    let clamped =
        x86
        ? "(words)__builtin_elementwise_min((single_vector)magnitude, \(splat("65536.0f", as: "single_vector", lanes: lanes)))"
        : "__builtin_elementwise_min(magnitude, \(splat("0x47800000u", as: "words", lanes: lanes)))"
    let limit = splat("126", as: "words", lanes: lanes)
    let increment =
        x86
        ? "(words)__builtin_elementwise_max((bytes)((clamped >> 23) + 13), (bytes)\(limit))"
        : "__builtin_elementwise_max((clamped >> 23) + 13, \(limit))"
    statements += [
        "const words magnitude = (words)single & 0x7FFFFFFF;",
        "const words clamped = \(clamped);",
        "const words increment = \(increment);",
        "const words rounded_single = (words)((single_vector)clamped + (single_vector)(increment << 23));",
        "const words fields = (rounded_single >> 13) + (rounded_single & 0xFFF) - 0x1F800;",
        "const words nan = (words)(single != single);",
        "const words bits = fields | (nan & 0x7FFF) | ((words)((signed_words)single >> 16) & 0xFFFF8000u);",
    ]
    if x86 {
        statements.append(
            narrowedBlock(
                "__builtin_ia32_packssdw128((signed_words)bits, (signed_words)bits)",
                demotion.shape,
                for: result
            )
        )
    } else {
        statements += [
            vectorTypedef("narrow_bits", lane: "int16_t", bits: 16, lanes: lanes),
            "const narrow_bits narrowed = __builtin_convertvector((signed_words)bits, narrow_bits);",
            narrowedResult("narrowed", demotion.shape, arm: false, for: result),
        ]
    }
    return statements.joined(separator: "\n")
}

func float16DemoteOps(_ demotion: Float16Demotion) -> [Op] {
    sourcedOps(accepting: demotion.accepts, includingHalfPrecision: true) { source, results in
        let hardware = sourced(source) { source, result in
            float16DemotedHardware(demotion, from: source, to: result)
        }
        let avx3 = sourced(source) { source, result in
            demotion == .double
                ? "#if \(float16SprCondition)\n\(float16DemotedSpr(from: source, to: result))\n#else\n\(float16DemotedHardware(demotion, from: source, to: result))\n#endif"
                : float16DemotedHardware(demotion, from: source, to: result)
        }
        return Op(
            demotion.shape.conversion("vector"),
            "DemoteTo",
            [.narrowTag(demotion.shape), .sourceVector],
            .narrowVector(demotion.shape),
            results,
            section: .singleVectorDemotion,
            vectorLabels: ["converting"],
            source: source,
            targets: TargetBodies(
                neon: sourced(source) { _, result in
                    float16DemotedNeon(demotion, to: result)
                },
                avx3: avx3,
                avx2: hardware,
                sse2: sourced(source) { source, result in
                    float16DemotedSoftware(demotion, x86: true, from: source, to: result)
                }
            ),
            portable: sourced(source) { source, result in
                float16DemotedSoftware(demotion, x86: false, from: source, to: result)
            }
        )
    }
}

let float16PromotionOpList: [Op] =
    ([Float16Promotion.narrow(.half), .narrow(.quarter), .lower, .upper, .even, .odd])
    .flatMap(float16PromotionOps)

let float16DemotionOpList: [Op] = [Float16Demotion.single, .double].flatMap(float16DemoteOps)

let float16Conversions:
    [(conversion: FloatToIntConversion, highwayName: String, label: String, tagged: Bool)] = [
        (.saturating, "ConvertTo", "converting", true),
        (.inRange, "ConvertInRangeTo", "convertingInRange", true),
        (.nearestEven, "NearestInt", "roundingToNearestOrEven", false),
        (.up, "CeilInt", "roundingUp", false),
        (.down, "FloorInt", "roundingDown", false),
    ]

let float16NativeCondition =
    "defined(__ARM_FEATURE_FP16_VECTOR_ARITHMETIC) || HWY_STATIC_TARGET == HWY_NEON_BF16"

func float16ToIntegerAccepts(signedOnly: Bool) -> (Element, Element) -> Bool {
    { source, result in
        source.category == .float16 && result.bits == 16
            && (result.category == .signedInteger
                || (!signedOnly && result.category == .unsignedInteger))
    }
}

func float16FromIntegerAccepts(_ source: Element, _ result: Element) -> Bool {
    (source.category == .unsignedInteger || source.category == .signedInteger)
        && source.bits == 16 && result.category == .float16
}

func float16ComposedCall(
    _ ops: [Op],
    _ highwayName: String,
    from source: Element,
    to result: Element,
    _ arguments: [String]
) -> String {
    guard
        let op = ops.first(where: {
            $0.highwayName == highwayName && $0.source?.suffix == source.suffix
                && $0.applies.matches(result) && $0.sourceShape == .full
        })
    else {
        fatalError("There is no \(highwayName) from \(source.swiftType) to \(result.swiftType)")
    }
    return "\(cFunctionName(of: op, for: result))(\(arguments.joined(separator: ", ")))"
}

func float16ConversionReturning(masked: Bool, for result: Element) -> String {
    guard masked else { return vectorResult("converted", for: result) }
    guard result.category == .float16 else {
        return floatToIntReturning(masked: true, for: result)
    }
    let unsigned = unsignedElement(bits: 16).at(width: result.width)
    let selecting = cFunctionName("selectingOrZero", unsigned)
    let operands = ["(\(unsigned.cRawMask))mask", "(\(unsigned.cRawVector))converted"]
    return "return (\(result.cRawVector))\(selecting)(\(operands.joined(separator: ", ")));"
}

func float16X86Rounded(_ operand: String, towardPositive: Bool, width: Int) -> String {
    float16X86Rounded(operand, immediate: towardPositive ? 10 : 9, width: width)
}

func float16X86Rounded(_ operand: String, immediate: Int, width: Int) -> String {
    let floats = x86Vector("f32")
    let immediate = String(immediate)
    guard width == 64 else {
        let name = width == 32 ? "roundps256" : "roundps"
        return x86Builtin(
            name,
            [(value: operand, type: floats), (value: immediate, type: "int")],
            returning: floats
        )
    }
    return x86Builtin(
        "rndscaleps_mask",
        [
            (value: operand, type: floats), (value: immediate, type: "int"),
            (value: compoundLiteral(floats, ["0"]), type: floats),
            (value: "-1", type: x86MaskType(lanes: 16)),
            (value: String(x86CurrentRounding), type: "int"),
        ],
        returning: floats
    )
}

func float16ToIntegerEmulated(
    _ conversion: FloatToIntConversion,
    roundingOnX86 roundsOnX86: Bool = false,
    from source: Element,
    to result: Element
) -> String {
    let wide = resizedElement(of: result, bits: 32)
    let single = floatElement(bits: 32).at(width: result.width)
    let name = float16Conversions.first { $0.conversion == conversion }!.highwayName
    func halves(_ promotion: Float16Promotion) -> String {
        let promoted = float16ComposedCall(
            float16PromotionOpList,
            promotion.highwayName,
            from: source,
            to: single,
            ["(\(source.cRawVector))a"]
        )
        guard roundsOnX86 else {
            return float16ComposedCall(
                convertToIntegerOps,
                name,
                from: single,
                to: wide,
                [promoted]
            )
        }
        let rounded = float16X86Rounded(
            promoted,
            towardPositive: conversion == .up,
            width: result.width
        )
        return float16ComposedCall(
            convertToIntegerOps,
            "ConvertTo",
            from: single,
            to: wide,
            ["(\(single.cRawVector))\(rounded)"]
        )
    }
    let narrowed = float16ComposedCall(
        demoteOps,
        "OrderedDemote2To",
        from: wide,
        to: result,
        [halves(.lower), halves(.upper)]
    )
    return "const \(result.cRawVector) converted = \(narrowed);"
}

func float16FromIntegerEmulated(from source: Element, to result: Element) -> String {
    let wide = resizedElement(of: source, bits: 32)
    let single = floatElement(bits: 32).at(width: result.width)
    let unsigned = unsignedElement(bits: 16).at(width: result.width)
    func narrowed(_ half: PromoteLowerUpperHalf) -> String {
        let widened = float16ComposedCall(
            promoteLowerUpperOps,
            "Promote\(uppercasedFirst(half.rawValue))To",
            from: source,
            to: wide,
            ["(\(source.cRawVector))a"]
        )
        let converted = float16ComposedCall(
            convertFromIntegerOps,
            "ConvertTo",
            from: wide,
            to: single,
            [widened]
        )
        let demoted = float16ComposedCall(
            float16DemotionOpList,
            "DemoteTo",
            from: single,
            to: result,
            [converted]
        )
        return "(\(unsigned.cRawVector(of: .half)))\(demoted)"
    }
    let combined =
        "\(cFunctionName("combining", unsigned))(\(narrowed(.upper)), \(narrowed(.lower)))"
    return "const \(result.cRawVector) converted = (\(result.cRawVector))\(combined);"
}

func float16ToIntegerNeon(_ conversion: FloatToIntConversion, to result: Element) -> String {
    let sign = result.category == .signedInteger ? "s" : "u"
    let builtin = "__builtin_neon_vcvt\(conversion.neonRounding)q_\(sign)16_f16"
    let operand = "(\(neonVector("i8")))a"
    let code = neonTypeCode(of: result)
    return
        "const \(result.cVector) converted = (\(result.cVector))\(builtin)(\(operand), \(code));"
}

func float16ToIntegerReference(
    _ conversion: FloatToIntConversion,
    masked: Bool,
    to result: Element,
    _ arguments: [String]
) -> String {
    let name = float16Conversions.first { $0.conversion == conversion }!.highwayName
    let vector = arguments[arguments.count - 1]
    let rebinding = result.category == .signedInteger ? "RebindToSigned" : "RebindToUnsigned"
    let single = "hn::Repartition<float, \(float16.tag)>()"
    let wide = "hn::\(rebinding)<hn::Repartition<float, \(float16.tag)>>()"
    func converted(_ promotion: String) -> String {
        let promoted = "hn::\(promotion)(\(single), \(vector))"
        switch conversion {
        case .saturating: return "hn::ConvertTo(\(wide), \(promoted))"
        case .inRange: return "hn::ConvertInRangeTo(\(wide), \(promoted))"
        default: return "hn::\(name)(\(promoted))"
        }
    }
    let emulated =
        "hn::OrderedDemote2To(\(result.tag)(), \(converted("PromoteLowerTo")), \(converted("PromoteUpperTo")))"
    let direct = "hn::\(name)(\(arguments.joined(separator: ", ")))"
    guard masked else { return "\n#if HWY_HAVE_FLOAT16\n\(direct)\n#else\n\(emulated)\n#endif\n" }
    let unmasked = "hn::ConvertTo(\(arguments[1]), \(vector))"
    return """

        #if HWY_TARGET_IS_SVE
        hn::MaskedConvertTo(\(arguments.joined(separator: ", ")))
        #elif HWY_HAVE_FLOAT16
        hn::IfThenElseZero(\(arguments[0]), \(unmasked))
        #else
        hn::IfThenElseZero(\(arguments[0]), \(emulated))
        #endif

        """
}

func float16FromIntegerReference(
    masked: Bool,
    from source: Element,
    to result: Element,
    _ arguments: [String]
) -> String {
    let vector = arguments[arguments.count - 1]
    let rebinding = source.category == .signedInteger ? "RebindToSigned" : "RebindToUnsigned"
    let single = "hn::Repartition<float, \(result.tag)>()"
    let wide = "hn::\(rebinding)<hn::Repartition<float, \(result.tag)>>()"
    func converted(_ promotion: String) -> String {
        let promoted = "hn::\(promotion)(\(wide), \(vector))"
        return "hn::DemoteTo(\(result.tag(of: .half))(), hn::ConvertTo(\(single), \(promoted)))"
    }
    let emulated =
        "hn::Combine(\(result.tag)(), \(converted("PromoteUpperTo")), \(converted("PromoteLowerTo")))"
    let direct = "hn::ConvertTo(\(arguments[arguments.count - 2]), \(vector))"
    guard masked else { return "\n#if HWY_HAVE_FLOAT16\n\(direct)\n#else\n\(emulated)\n#endif\n" }
    return """

        #if HWY_TARGET_IS_SVE
        hn::MaskedConvertTo(\(arguments.joined(separator: ", ")))
        #elif HWY_HAVE_FLOAT16
        hn::IfThenElseZero(\(arguments[0]), \(direct))
        #else
        hn::IfThenElseZero(\(arguments[0]), \(emulated))
        #endif

        """
}

func float16ToIntegerOps(
    _ conversion: FloatToIntConversion,
    _ highwayName: String,
    label: String,
    masked: Bool = false,
    tagged: Bool = true
) -> [Op] {
    sourcedOps(
        accepting: float16ToIntegerAccepts(signedOnly: !tagged),
        includingHalfPrecision: true
    ) { source, results in
        let emulated = { (source: Element, result: Element) in
            float16ToIntegerEmulated(conversion, from: source, to: result)
        }
        let rounded = sourced(source) { source, result in
            "\(float16ToIntegerEmulated(conversion, roundingOnX86: true, from: source, to: result))\n\(float16ConversionReturning(masked: masked, for: result))"
        }
        let roundsOnX86 = conversion == .up || conversion == .down
        return Op(
            "vector",
            highwayName,
            (masked ? [.whereMask] : []) + (tagged ? [.tag] : []) + [.sourceVector],
            .vector,
            results,
            section: .typeConversion,
            vectorLabels: [label],
            source: source,
            targets: TargetBodies(
                neon: sourced(source) { source, result in
                    """
                    #if \(float16NativeCondition)
                    \(float16ToIntegerNeon(conversion, to: result))
                    #else
                    \(emulated(source, result))
                    #endif
                    \(float16ConversionReturning(masked: masked, for: result))
                    """
                },
                avx3: roundsOnX86 ? rounded : nil,
                avx2: roundsOnX86 ? rounded : nil,
                sse4: roundsOnX86 ? rounded : nil
            ),
            referenceCall: { result, arguments in
                float16ToIntegerReference(conversion, masked: masked, to: result, arguments)
            },
            portable: sourced(source) { source, result in
                "\(emulated(source, result))\n\(float16ConversionReturning(masked: masked, for: result))"
            }
        )
    }
}

func float16FromIntegerOps(masked: Bool) -> [Op] {
    sourcedOps(accepting: float16FromIntegerAccepts, includingHalfPrecision: true) {
        source,
        results in
        Op(
            "vector",
            masked ? "MaskedConvertTo" : "ConvertTo",
            (masked ? [.whereMask] : []) + [.tag, .sourceVector],
            .vector,
            results,
            section: .typeConversion,
            vectorLabels: ["converting"],
            source: source,
            targets: TargetBodies(
                neon: sourced(source) { source, result in
                    """
                    #if \(float16NativeCondition)
                    const \(result.cVector) converted = __builtin_convertvector(a, \(result.cVector));
                    #else
                    \(float16FromIntegerEmulated(from: source, to: result))
                    #endif
                    \(float16ConversionReturning(masked: masked, for: result))
                    """
                }
            ),
            referenceCall: { result, arguments in
                float16FromIntegerReference(
                    masked: masked,
                    from: source,
                    to: result,
                    arguments
                )
            },
            portable: sourced(source) { source, result in
                """
                \(float16FromIntegerEmulated(from: source, to: result))
                \(float16ConversionReturning(masked: masked, for: result))
                """
            }
        )
    }
}

let float16IntegerOps: [Op] =
    float16Conversions.flatMap {
        float16ToIntegerOps($0.conversion, $0.highwayName, label: $0.label, tagged: $0.tagged)
    }
    + float16ToIntegerOps(.saturating, "MaskedConvertTo", label: "converting", masked: true)
    + float16FromIntegerOps(masked: false) + float16FromIntegerOps(masked: true)

func float16SumsOf2(from source: Element, to result: Element) -> String {
    let promoted = [Float16Promotion.even, .odd].map { promotion in
        float16ComposedCall(
            float16PromotionOpList,
            promotion.highwayName,
            from: source,
            to: result,
            [rawName("a")]
        )
    }
    return "return \(cFunctionName("adding", result))(\(promoted.joined(separator: ", ")));"
}

let float16SumsOf2Ops = sourcedOps(
    accepting: Float16Promotion.even.accepts,
    includingHalfPrecision: true
) { source, results in
    Op(
        "sumsOf2",
        "SumsOf2",
        [.sourceVector],
        .vector,
        results,
        section: .arithmetic,
        unorderedNaNs: .adjacentLanes,
        filtersUnorderedNaNs: true,
        vectorLabels: ["_"],
        source: source,
        portable: sourced(source) { source, result in float16SumsOf2(from: source, to: result) }
    )
}

func float16BiasedExponentAccepts(_ source: Element, _ result: Element) -> Bool {
    source.category == .float16 && result.category == .unsignedInteger
        && source.bits == result.bits
}

func float16BiasedExponent(native: Bool, from source: Element, to result: Element) -> String {
    let magnitude =
        native
        ? "__builtin_elementwise_abs((native_vector)a)"
        : halfPrecisionMasked("&", with: 0x7fff, for: source)
    let shifted = "(\(result.cVector))(\(magnitude)) >> \(mantissaBits(of: source))"
    guard native else { return vectorResult(shifted, for: result) }
    return "\(halfPrecisionNativeVector(for: source))\n\(vectorResult(shifted, for: result))"
}

func float16BiasedExponentReference(from source: Element, _ arguments: [String]) -> String {
    let unsigned = "hn::RebindToUnsigned<\(source.tag)>()"
    let magnitude =
        "hn::And(hn::BitCast(\(unsigned), \(arguments[0])), hn::Set(\(unsigned), 0x7FFF))"
    let emulated = "hn::ShiftRight<\(mantissaBits(of: source))>(\(magnitude))"
    let direct = "hn::GetBiasedExponent(\(arguments[0]))"
    return "\n#if HWY_HAVE_FLOAT16\n\(direct)\n#else\n\(emulated)\n#endif\n"
}

let float16BiasedExponentOps = sourcedOps(
    accepting: float16BiasedExponentAccepts,
    includingHalfPrecision: true
) { source, results in
    Op(
        "biasedExponent",
        "GetBiasedExponent",
        [.sourceVector],
        .vector,
        results,
        section: .arithmetic,
        source: source,
        targets: TargetBodies(
            neon: sourced(source) { source, result in
                """
                #if \(neonHasFloat16Condition)
                \(float16BiasedExponent(native: true, from: source, to: result))
                #else
                \(float16BiasedExponent(native: false, from: source, to: result))
                #endif
                """
            }
        ),
        referenceCall: { _, arguments in float16BiasedExponentReference(from: source, arguments) },
        portable: sourced(source) { source, result in
            float16BiasedExponent(native: false, from: source, to: result)
        }
    )
}

func float16PowerOf2Accepts(_ source: Element, _ result: Element) -> Bool {
    source.category == .signedInteger && result.category == .float16 && source.bits == result.bits
}

func float16PowerOf2Emulated(from source: Element, to result: Element) -> String {
    let single = float16Single(for: result)
    let integer = signedElement(of: single).at(width: result.width)
    func scaled(_ half: PromoteLowerUpperHalf) -> String {
        let promotion = "Promote\(uppercasedFirst(half.rawValue))To"
        let operand = float16ComposedCall(
            float16PromotionOpList,
            promotion,
            from: result,
            to: single,
            [rawName("a")]
        )
        let exponents = float16ComposedCall(
            conversionOps,
            promotion,
            from: source,
            to: integer,
            [rawName("b")]
        )
        return float16ComposedCall(
            mulBitsPowerOf2Ops,
            "MulByPow2",
            from: integer,
            to: single,
            [operand, exponents]
        )
    }
    return "return (\(result.cRawVector))\(float16Combined(for: result, halfResult: scaled));"
}

func float16PowerOf2Reference(to result: Element, _ arguments: [String]) -> String {
    let single = "hn::Repartition<float, \(result.tag)>()"
    let wide = "hn::RebindToSigned<hn::Repartition<float, \(result.tag)>>()"
    func scaled(_ promotion: String) -> String {
        let operands = [
            "hn::\(promotion)(\(single), \(arguments[0]))",
            "hn::\(promotion)(\(wide), \(arguments[1]))",
        ]
        let product = "hn::MulByPow2(\(operands.joined(separator: ", ")))"
        return "hn::DemoteTo(\(result.tag(of: .half))(), \(product))"
    }
    let emulated =
        "hn::Combine(\(result.tag)(), \(scaled("PromoteUpperTo")), \(scaled("PromoteLowerTo")))"
    let direct = "hn::MulByPow2(\(arguments.joined(separator: ", ")))"
    return "\n#if HWY_HAVE_FLOAT16\n\(direct)\n#else\n\(emulated)\n#endif\n"
}

let float16PowerOf2Ops = sourcedOps(
    accepting: float16PowerOf2Accepts,
    includingHalfPrecision: true
) { source, results in
    Op(
        "multiplyingByPowerOf2",
        "MulByPow2",
        [.vector, .sourceVector],
        .vector,
        results,
        section: .multiply,
        source: source,
        targets: TargetBodies(
            neon: sourced(source) { source, result in
                """
                #if \(neonHasFloat16Condition)
                \(mulBitsPowerOf2(.selecting, to: result))
                #else
                \(float16PowerOf2Emulated(from: source, to: result))
                #endif
                """
            },
            sve2_128: sourced(source) { source, result in
                mulBitsPowerOf2Sve(from: source, to: result)
            }
        ),
        referenceCall: { result, arguments in float16PowerOf2Reference(to: result, arguments) },
        portable: sourced(source) { source, result in
            float16PowerOf2Emulated(from: source, to: result)
        }
    )
}

let float16WidenArithmeticOps: [Op] =
    float16SumsOf2Ops + float16BiasedExponentOps + float16PowerOf2Ops

let convertFloat16Ops: [Op] =
    float16PromotionOpList + float16DemotionOpList + float16IntegerOps + float16WidenArithmeticOps

func bfloat16PromotesToFloat(_ source: Element, _ result: Element) -> Bool {
    source.category == .bfloat16 && result.category == .float && result.bits == 32
}

func bfloat16PromoteWords(for result: Element) -> Element {
    unsignedElement(of: result).at(width: result.width)
}

func bfloat16PromotePortable(of lanes: [Int], from source: Element, to result: Element) -> String {
    let words = bfloat16PromoteWords(for: result).cVector
    return """
        \(promoteNarrowing(of: lanes, from: source, to: result))
        \(vectorResult("(\(words))__builtin_convertvector(v, \(words)) << 16", for: result))
        """
}

func bfloat16PromoteEvenOddPortable(parity: Int, for result: Element) -> String {
    let words = bfloat16PromoteWords(for: result)
    let lanes =
        parity == 0
        ? "(\(words.cVector))a << 16"
        : "(\(words.cVector))a & \(splat("0xFFFF0000u", as: words.cVector, lanes: result.laneCount))"
    return vectorResult(lanes, for: result)
}

func bfloat16PromoteEvenOddSve(parity: Int, for result: Element) -> String {
    let words = unsignedElement(of: result)
    let operand = sveReinterpreted(
        sveSplatOperand("a", for: unsignedElement(bits: 16)),
        from: unsignedElement(bits: 16),
        to: words
    )
    let arguments =
        parity == 0
        ? [sveAllLanes(of: words), operand, "16"]
        : [sveAllLanes(of: words), operand, "0xFFFF0000u"]
    let promoted = sveBuiltin(
        parity == 0 ? "lsl_n" : "and_n",
        arguments,
        for: words,
        predication: "x"
    )
    return vectorResult(
        sveResult(sveReinterpreted(promoted, from: words, to: result), for: result),
        for: result
    )
}

let bfloat16PromoteOps: [Op] =
    sourcedOps(accepting: bfloat16PromotesToFloat, includingHalfPrecision: true) {
        source,
        results in
        Op(
            "vector",
            "PromoteTo",
            [.tag, .sourceNarrowVector(.half)],
            .vector,
            results,
            section: .singleVectorPromotion,
            vectorLabels: ["widening"],
            source: source,
            portable: sourced(source) { source, result in
                bfloat16PromotePortable(of: promotedLanes(to: result), from: source, to: result)
            }
        )
    }
    + [PromoteLowerUpperHalf.lower, .upper].flatMap { half in
        sourcedOps(accepting: bfloat16PromotesToFloat, includingHalfPrecision: true) {
            source,
            results in
            Op(
                "vector",
                "Promote\(uppercasedFirst(half.rawValue))To",
                [.tag, .sourceVector],
                .vector,
                results,
                section: .singleVectorPromotion,
                vectorLabels: ["widening\(uppercasedFirst(half.rawValue))"],
                source: source,
                portable: sourced(source) { source, result in
                    bfloat16PromotePortable(
                        of: promoteLowerUpperIndices(half, of: source),
                        from: source,
                        to: result
                    )
                }
            )
        }
    }
    + [("PromoteEvenTo", "wideningEven", 0), ("PromoteOddTo", "wideningOdd", 1)].flatMap {
        highwayName,
        label,
        parity in
        sourcedOps(accepting: bfloat16PromotesToFloat, includingHalfPrecision: true) {
            source,
            results in
            Op(
                "vector",
                highwayName,
                [.tag, .sourceVector],
                .vector,
                results,
                section: .singleVectorPromotion,
                vectorLabels: [label],
                source: source,
                targets: TargetBodies(
                    sve2_128: sourced(source) { _, result in
                        bfloat16PromoteEvenOddSve(parity: parity, for: result)
                    }
                ),
                portable: sourced(source) { _, result in
                    bfloat16PromoteEvenOddPortable(parity: parity, for: result)
                }
            )
        }
    }

let bfloat16NeonNativeCondition = reorderMulNeonKeepsFirstCondition

let bfloat16SveFeatureCondition = reorderMulSveKeepsFirstCondition

let bfloat16SveConvertCondition =
    "defined(__ARM_FEATURE_SVE_BF16) && (HWY_COMPILER_CLANG >= 1200 || HWY_COMPILER_GCC_ACTUAL >= 1000)"

let bfloat16Avx3Condition = reorderMulAvx3KeepsFirstCondition

func bfloat16DemotesFromFloat(_ source: Element, _ result: Element) -> Bool {
    source.category == .float && source.bits == 32 && result.category == .bfloat16
}

func bfloat16DemotionSourceInputs(
    operand: Element,
    for element: Element,
    seed: String
) -> String? {
    guard bfloat16DemotesFromFloat(operand, element) else { return nil }
    return "Inputs.bfloat16Demotions(\(operand.namespace).Vector.self, \(seed))"
}

enum Bfloat16Rounding {
    case masked
    case statements
    case classified
}

func bfloat16DemoteRounded(
    _ operand: String,
    from source: Element,
    using rounding: Bfloat16Rounding = .statements
) -> String {
    let words = bfloat16PromoteWords(for: source)
    let (bits, ordered) = ("\(operand)Bits", "\(operand)Ordered")
    let declaration = "const \(words.cVector) \(bits) = (\(words.cVector))\(operand);"
    switch rounding {
    case .masked:
        return """
            \(declaration)
            const \(words.cVector) \(operand)NaNs = (\(words.cVector))(\(operand) != \(operand));
            const \(words.cVector) \(operand)Rounded = ((\(bits) + (((\(bits) >> 16) & 1) + 0x7FFF)) & ~\(operand)NaNs) | ((\(bits) | 0x400000) & \(operand)NaNs);
            """
    case .statements:
        return """
            \(declaration)
            const \(words.cVector) \(ordered) = (\(words.cVector))(\(operand) == \(operand));
            const \(words.cVector) \(operand)Biased = \(bits) + 0x7FFF;
            const \(words.cVector) \(operand)Quieted = \(bits) | 0x400000;
            const \(words.cVector) \(operand)Rounded = ((\(operand)Biased + ((\(bits) >> 16) & 1)) & \(ordered)) | (\(operand)Quieted & ~\(ordered));
            """
    case .classified:
        let bitsType = x86MaskType(lanes: source.laneCount)
        let nans = x86Builtin(
            "fpclassps512_mask",
            [
                (value: operand, type: x86Vector("f32")), (value: "0x81", type: "int"),
                (value: "-1", type: bitsType),
            ],
            returning: bitsType
        )
        let rounded = x86Avx3Select(
            "\(operand)NaNs",
            "\(operand)Quieted",
            "\(operand)Biased + ((\(bits) >> 16) & 1)",
            for: words
        )
        return """
            \(declaration)
            const \(bitsType) \(operand)NaNs = \(nans);
            const \(words.cVector) \(operand)Biased = \(bits) + 0x7FFF;
            const \(words.cVector) \(operand)Quieted = \(bits) | 0x400000;
            const \(words.cVector) \(operand)Rounded = \(rounded);
            """
    }
}

func bfloat16DemoteHalf(
    arm: Bool,
    using rounding: Bfloat16Rounding = .statements,
    from source: Element,
    to result: Element
) -> String {
    let narrow = result.cVector(of: .half)
    return """
        \(bfloat16DemoteRounded("a", from: source, using: rounding))
        const \(narrow) converted = __builtin_convertvector(aRounded >> 16, \(narrow));
        \(narrowedResult("converted", .half, arm: arm, for: result))
        """
}

func bfloat16DemoteLanes(from source: Element, to result: Element) -> String {
    vectorTypedef("narrow_lanes", lane: result.cType, bits: result.bits, lanes: result.laneCount)
}

func bfloat16DemoteOrdered(
    using rounding: Bfloat16Rounding = .statements,
    from source: Element,
    to result: Element
) -> String {
    let odds = laneIndices(Array(stride(from: 1, to: 4 * source.laneCount, by: 2)))
    return """
        \(bfloat16DemoteLanes(from: source, to: result))
        \(bfloat16DemoteRounded("a", from: source, using: rounding))
        \(bfloat16DemoteRounded("b", from: source, using: rounding))
        \(vectorResult("__builtin_shufflevector((narrow_lanes)aRounded, (narrow_lanes)bRounded, \(odds))", for: result))
        """
}

func bfloat16DemoteReordered(
    using rounding: Bfloat16Rounding = .statements,
    from source: Element,
    to result: Element
) -> String {
    let words = bfloat16PromoteWords(for: source).cVector
    return """
        \(bfloat16DemoteLanes(from: source, to: result))
        \(bfloat16DemoteRounded("a", from: source, using: rounding))
        \(bfloat16DemoteRounded("b", from: source, using: rounding))
        \(vectorResult("(narrow_lanes)((aRounded & \(splat("0xFFFF0000u", as: words, lanes: source.laneCount))) | (bRounded >> 16))", for: result))
        """
}

func bfloat16DemoteTruncated(from source: Element, to result: Element) -> String {
    let words = bfloat16PromoteWords(for: source).cVector
    let upper = splat("0xFFFF0000u", as: words, lanes: source.laneCount)
    return vectorResult("((\(words))a & \(upper)) | ((\(words))b >> 16)", for: result)
}

func bfloat16DemoteAvx3Half(from source: Element, to result: Element) -> String {
    let typedef = vectorTypedef("bfloat_lanes", lane: "__bf16", bits: 16, lanes: source.laneCount)
    let operands = [
        (value: "a", type: x86Vector("f32")),
        (value: compoundLiteral("bfloat_lanes", ["0"]), type: "bfloat_lanes"),
        (value: "-1", type: "unsigned short"),
    ]
    let converted = x86Builtin("cvtneps2bf16_512_mask", operands, returning: "bfloat_lanes")
    return widenMulChoice(
        [(bfloat16Avx3Condition, "\(typedef)\n\(narrowResult(converted, .half, for: result))")],
        otherwise: bfloat16DemoteHalf(arm: false, using: .classified, from: source, to: result)
    )
}

func bfloat16DemoteAvx3TwoVectors(
    ordered: Bool,
    from source: Element,
    to result: Element
) -> String {
    let typedef = vectorTypedef(
        "bfloat_lanes",
        lane: "__bf16",
        bits: 16,
        lanes: 2 * source.laneCount
    )
    let operands = ["b", "a"].map { (value: $0, type: x86Vector("f32")) }
    let converted = x86Builtin("cvtne2ps2bf16_512", operands, returning: "bfloat_lanes")
    return widenMulChoice(
        [(bfloat16Avx3Condition, "\(typedef)\n\(vectorResult(converted, for: result))")],
        otherwise: ordered
            ? bfloat16DemoteOrdered(using: .classified, from: source, to: result)
            : bfloat16DemoteReordered(using: .classified, from: source, to: result)
    )
}

func bfloat16DemoteX86Reordered(
    using rounding: Bfloat16Rounding = .statements,
    from source: Element,
    to result: Element
) -> String {
    let words = bfloat16PromoteWords(for: source).cVector
    let lanes = result.laneCount
    let blended = laneIndices((0..<lanes).map { $0 % 2 == 0 ? $0 : lanes + $0 })
    return """
        \(bfloat16DemoteLanes(from: source, to: result))
        \(bfloat16DemoteRounded("a", from: source, using: rounding))
        \(bfloat16DemoteRounded("b", from: source, using: rounding))
        const \(words) bShifted = bRounded >> 16;
        \(vectorResult("__builtin_shufflevector((narrow_lanes)bShifted, (narrow_lanes)aRounded, \(blended))", for: result))
        """
}

func bfloat16DemoteX86Ordered(
    using rounding: Bfloat16Rounding = .statements,
    from source: Element,
    to result: Element
) -> String {
    let rounded = ["a", "b"].map { bfloat16DemoteRounded($0, from: source, using: rounding) }
    guard source.width == 16 else {
        let packed = x86Packing(
            "packusdw",
            "aShifted",
            "bShifted",
            from: "i32",
            to: "i16",
            width: 32
        )
        let words = bfloat16PromoteWords(for: source).cVector
        return """
            \(rounded.joined(separator: "\n"))
            const \(words) aShifted = aRounded >> 16;
            const \(words) bShifted = bRounded >> 16;
            const \(x86Vector("i64")) packed = (\(x86Vector("i64")))\(packed);
            \(vectorResult("__builtin_shufflevector(packed, packed, 0, 2, 1, 3)", for: result))
            """
    }
    let signed = x86Vector("i32")
    return """
        \(rounded.joined(separator: "\n"))
        const \(signed) aShifted = (\(signed))aRounded >> 16;
        const \(signed) bShifted = (\(signed))bRounded >> 16;
        \(vectorResult(x86Packing("packssdw", "aShifted", "bShifted", from: "i32", to: "i16", width: 16), for: result))
        """
}

func bfloat16DemoteX86Half(
    using rounding: Bfloat16Rounding = .statements,
    from source: Element,
    to result: Element
) -> String {
    let rounded = bfloat16DemoteRounded("a", from: source, using: rounding)
    guard source.width == 16 else {
        let words = bfloat16PromoteWords(for: source).cVector
        let packed = x86Packing("packusdw", "shifted", "shifted", from: "i32", to: "i16", width: 32)
        let quads = x86Vector("i64")
        return """
            \(rounded)
            const \(words) shifted = aRounded >> 16;
            const \(quads) packed = (\(quads))\(packed);
            \(narrowedBlock("__builtin_shufflevector(packed, packed, 0, 2)", .half, for: result))
            """
    }
    let signed = x86Vector("i32")
    let packed = x86Packing("packssdw", "shifted", "shifted", from: "i32", to: "i16", width: 16)
    return """
        \(rounded)
        const \(signed) shifted = (\(signed))aRounded >> 16;
        \(narrowedBlock(packed, .half, for: result))
        """
}

func bfloat16DemoteNeonHalf(from source: Element, to result: Element) -> String {
    let narrowed = "__builtin_neon_vcvt_bf16_f32((\(neonVector("i8")))a, 11)"
    return widenMulChoice(
        [(bfloat16NeonNativeCondition, narrowResult(narrowed, .half, for: result))],
        otherwise: bfloat16DemoteHalf(arm: true, from: source, to: result)
    )
}

func bfloat16DemoteNeonTwoVectors(
    ordered: Bool,
    from source: Element,
    to result: Element
) -> String {
    let quads = neonVector("i8")
    let lower = "__builtin_neon_vcvtq_low_bf16_f32((\(quads))a, 43)"
    let combined = "__builtin_neon_vcvtq_high_bf16_f32((\(quads))\(lower), (\(quads))b, 43)"
    return widenMulChoice(
        [(bfloat16NeonNativeCondition, vectorResult(combined, for: result))],
        otherwise: ordered
            ? bfloat16DemoteOrdered(from: source, to: result)
            : bfloat16DemoteReordered(from: source, to: result)
    )
}

func bfloat16DemoteSveConverted(
    _ operand: String,
    from source: Element,
    to result: Element
) -> String {
    sveBuiltin(
        "cvt_bf16",
        [sveAllLanes(of: result), sveSplatOperand(operand, for: source)],
        for: source,
        predication: "x"
    )
}

func bfloat16DemoteSveHalf(from source: Element, to result: Element) -> String {
    let unzipped = sveBuiltin("uzp1", ["converted", "converted"], for: result)
    let native = """
        const \(sveType(of: result)) converted = \(bfloat16DemoteSveConverted("a", from: source, to: result));
        const \(result.cVector) narrowed = \(sveResult(unzipped, for: result));
        \(narrowedLanes("narrowed", .half, arm: true, for: result))
        """
    return widenMulChoice(
        [(bfloat16SveConvertCondition, native)],
        otherwise: bfloat16DemoteHalf(arm: true, from: source, to: result)
    )
}

func bfloat16DemoteSveTwoVectors(
    ordered: Bool,
    from source: Element,
    to result: Element
) -> String {
    let converted = [("a", "aConverted"), ("b", "bConverted")].map { operand, name in
        "const \(sveType(of: result)) \(name) = \(bfloat16DemoteSveConverted(operand, from: source, to: result));"
    }
    let combined =
        ordered
        ? sveBuiltin("uzp1", ["aConverted", "bConverted"], for: result)
        : sveBuiltin(
            "cvtnt_bf16",
            ["bConverted", sveAllLanes(of: result), sveSplatOperand("a", for: source)],
            for: source,
            predication: "m"
        )
    let native = """
        \(converted.joined(separator: "\n"))
        \(vectorResult(sveResult(combined, for: result), for: result))
        """
    return widenMulChoice(
        [(bfloat16SveConvertCondition, native)],
        otherwise: ordered
            ? bfloat16DemoteOrdered(from: source, to: result)
            : bfloat16DemoteReordered(from: source, to: result)
    )
}

let bfloat16DemoteOps: [Op] =
    sourcedOps(accepting: bfloat16DemotesFromFloat, includingHalfPrecision: true) {
        source,
        results in
        Op(
            "halfVector",
            "DemoteTo",
            [.narrowTag(.half), .sourceVector],
            .narrowVector(.half),
            results,
            section: .singleVectorDemotion,
            vectorLabels: ["converting"],
            source: source,
            targets: TargetBodies(
                neon: sourced(source) { source, result in
                    bfloat16DemoteNeonHalf(from: source, to: result)
                },
                sve2_128: sourced(source) { source, result in
                    bfloat16DemoteSveHalf(from: source, to: result)
                },
                avx3dl: sourced(source) { source, result in
                    bfloat16DemoteAvx3Half(from: source, to: result)
                },
                avx3: sourced(source) { source, result in
                    bfloat16DemoteHalf(arm: false, using: .classified, from: source, to: result)
                },
                avx2: sourced(source) { source, result in
                    bfloat16DemoteX86Half(from: source, to: result)
                },
                sse4: sourced(source) { source, result in
                    bfloat16DemoteX86Half(from: source, to: result)
                },
                sse2: sourced(source) { source, result in
                    bfloat16DemoteX86Half(using: .masked, from: source, to: result)
                }
            ),
            portable: sourced(source) { source, result in
                bfloat16DemoteHalf(arm: false, from: source, to: result)
            }
        )
    }
    + [
        ("OrderedDemote2To", "converting", true),
        ("ReorderDemote2To", "convertingInAnyOrder", false),
    ]
    .flatMap { highwayName, label, ordered in
        sourcedOps(accepting: bfloat16DemotesFromFloat, includingHalfPrecision: true) {
            source,
            results in
            Op(
                "vector",
                highwayName,
                [.tag, .sourceVector, .sourceVector],
                .vector,
                results,
                section: .twoVectorDemotion,
                vectorLabels: [label, "_"],
                source: source,
                targets: TargetBodies(
                    neon: sourced(source) { source, result in
                        bfloat16DemoteNeonTwoVectors(ordered: ordered, from: source, to: result)
                    },
                    sve2_128: sourced(source) { source, result in
                        bfloat16DemoteSveTwoVectors(ordered: ordered, from: source, to: result)
                    },
                    avx3dl: sourced(source) { source, result in
                        bfloat16DemoteAvx3TwoVectors(ordered: ordered, from: source, to: result)
                    },
                    avx3: sourced(source) { source, result in
                        ordered
                            ? bfloat16DemoteOrdered(using: .classified, from: source, to: result)
                            : bfloat16DemoteReordered(using: .classified, from: source, to: result)
                    },
                    avx2: sourced(source) { source, result in
                        ordered
                            ? bfloat16DemoteX86Ordered(from: source, to: result)
                            : bfloat16DemoteX86Reordered(from: source, to: result)
                    },
                    sse4: sourced(source) { source, result in
                        ordered
                            ? bfloat16DemoteX86Ordered(from: source, to: result)
                            : bfloat16DemoteX86Reordered(from: source, to: result)
                    },
                    sse2: sourced(source) { source, result in
                        ordered
                            ? bfloat16DemoteX86Ordered(using: .masked, from: source, to: result)
                            : bfloat16DemoteReordered(using: .masked, from: source, to: result)
                    },
                    emu128: ordered
                        ? nil
                        : sourced(source) { source, result in
                            bfloat16DemoteTruncated(from: source, to: result)
                        }
                ),
                portable: sourced(source) { source, result in
                    ordered
                        ? bfloat16DemoteOrdered(from: source, to: result)
                        : bfloat16DemoteReordered(from: source, to: result)
                }
            )
        }
    }

func bfloat16Promoted(_ operand: String, by highwayName: String, to result: Element) -> String {
    guard let promotion = bfloat16PromoteOps.first(where: { $0.highwayName == highwayName }) else {
        fatalError("There is no \(highwayName) from BFloat16")
    }
    let name = cFunctionName(of: promotion, for: result)
    return "(\(result.cVector))\(name)((\(bfloat16.cRawVector))\(operand))"
}

func bfloat16ParityName(_ parity: Int) -> String {
    parity == 0 ? "PromoteEvenTo" : "PromoteOddTo"
}

func bfloat16Products(of parity: Int, for result: Element) -> String {
    let name = bfloat16ParityName(parity)
    let raw = result.cRawVector
    let operands = ["a", "b"].map { "(\(raw))\(bfloat16Promoted($0, by: name, to: result))" }
    return
        "(\(result.cVector))\(cFunctionName("multiplying", result))(\(operands.joined(separator: ", ")))"
}

func bfloat16FusedProducts(of parity: Int, onto addend: String, for result: Element) -> String {
    let name = bfloat16ParityName(parity)
    return reorderMulMultiplyAdding(
        bfloat16Promoted("a", by: name, to: result),
        bfloat16Promoted("b", by: name, to: result),
        addend,
        for: result
    )
}

func bfloat16PairwiseGeneric(fusing parity: Int, for result: Element) -> String {
    bfloat16FusedProducts(
        of: parity,
        onto: bfloat16Products(of: 1 - parity, for: result),
        for: result
    )
}

func bfloat16Zero(for result: Element) -> String {
    compoundLiteral(result.cVector, ["0"])
}

func bfloat16NeonCall(_ name: String, _ accumulator: String, for result: Element) -> String {
    neonBuiltin("\(name)_f32", [accumulator, "a", "b"], code: 41, for: result)
}

func bfloat16SveCall(_ name: String, _ accumulator: String, for result: Element) -> String {
    let words = unsignedElement(bits: 16)
    let operands = ["a", "b"].map {
        sveReinterpreted(sveSplatOperand($0, for: words), from: words, to: bfloat16)
    }
    return sveBuiltin(name, [accumulator] + operands, for: result)
}

func bfloat16SveZero(for result: Element) -> String {
    sveBuiltin("dup_n", ["0"], for: result)
}

func bfloat16Avx3Call(_ accumulator: String, for result: Element) -> WidenMulKernel {
    let typedef = vectorTypedef(
        "bfloat_lanes",
        lane: "__bf16",
        bits: 16,
        lanes: 2 * result.laneCount
    )
    let operands = [
        (value: accumulator, type: x86Vector("f32")), (value: "a", type: "bfloat_lanes"),
        (value: "b", type: "bfloat_lanes"),
    ]
    return (
        typedef,
        x86Builtin("dpbf16ps_\(x86Bits(result.width))", operands, returning: result.cVector)
    )
}

func bfloat16Natively(
    if condition: String,
    _ native: WidenMulKernel,
    otherwise generic: WidenMulKernel,
    finishing finish: (WidenMulKernel) -> String
) -> String {
    widenMulChoice([(condition, finish(native))], otherwise: finish(generic))
}

func bfloat16PairwiseOps(masked: Bool) -> [Op] {
    sourcedOps(accepting: bfloat16PromotesToFloat, includingHalfPrecision: true) {
        source,
        results in
        func body(
            _ result: Element,
            fusing parity: Int,
            nativeMask: Bool = false,
            native: (condition: String, kernel: WidenMulKernel)? = nil
        ) -> String {
            func finished(_ kernel: WidenMulKernel) -> String {
                widenMulBody(kernel, masked: masked, nativeMask: nativeMask, for: result)
            }
            let generic = finished(("", bfloat16PairwiseGeneric(fusing: parity, for: result)))
            guard let native else { return generic }
            return widenMulChoice([(native.condition, finished(native.kernel))], otherwise: generic)
        }
        return Op(
            "multiplyPairwiseAdding",
            masked ? "MaskedWidenMulPairwiseAdd" : "WidenMulPairwiseAdd",
            [.tag] + (masked ? [.whereMask] : []) + [.sourceVector, .sourceVector],
            .vector,
            results,
            section: masked ? .zeroMaskedArithmetic : .multiply,
            unorderedNaNs: .widenedPairs,
            filtersUnorderedNaNs: true,
            source: source,
            targets: TargetBodies(
                neon: sourced(source) { _, result in
                    let dot = bfloat16NeonCall("vbfdotq", bfloat16Zero(for: result), for: result)
                    return body(result, fusing: 0, native: (bfloat16NeonNativeCondition, ("", dot)))
                },
                sve2_128: sourced(source) { _, result in
                    let even = bfloat16SveCall("bfmlalb", bfloat16SveZero(for: result), for: result)
                    let odd = bfloat16SveCall("bfmlalt", even, for: result)
                    return body(
                        result,
                        fusing: 1,
                        native: (bfloat16SveFeatureCondition, ("", sveResult(odd, for: result)))
                    )
                },
                avx3dl: sourced(source) { _, result in
                    let dot = bfloat16Avx3Call(bfloat16Zero(for: result), for: result)
                    return body(
                        result,
                        fusing: 0,
                        nativeMask: true,
                        native: (bfloat16Avx3Condition, dot)
                    )
                },
                avx3: sourced(source) { _, result in
                    body(result, fusing: 0, nativeMask: true)
                }
            ),
            portable: sourced(source) { _, result in body(result, fusing: 0) }
        )
    }
}

func bfloat16ReorderGeneric(for result: Element) -> String {
    """
    \(reorderMulLoadedOutVector(named: "accumulated", for: result))
    \(outVectorStore(0, of: bfloat16FusedProducts(of: 1, onto: "accumulated", for: result), for: result))
    \(vectorResult(bfloat16FusedProducts(of: 0, onto: "c", for: result), for: result))
    """
}

let bfloat16ReorderOps = sourcedOps(
    accepting: bfloat16PromotesToFloat,
    includingHalfPrecision: true
) {
    source,
    results in
    func body(
        _ result: Element,
        native: (condition: String, kernel: WidenMulKernel)? = nil
    ) -> String {
        let generic = bfloat16ReorderGeneric(for: result)
        guard let native else { return generic }
        return widenMulChoice(
            [(native.condition, widenMulBody(native.kernel, for: result))],
            otherwise: generic
        )
    }
    return Op(
        "multiplyAccumulatingInAnyOrder",
        "ReorderWidenMulAccumulate",
        [.tag, .sourceVector, .sourceVector, .vector, .outVector],
        .vector,
        results,
        section: .multiply,
        unorderedNaNs: .widenedAccumulating,
        filtersUnorderedNaNs: true,
        accumulates: true,
        source: source,
        targets: TargetBodies(
            neon: sourced(source) { _, result in
                let dot = bfloat16NeonCall("vbfdotq", "c", for: result)
                return body(result, native: (bfloat16NeonNativeCondition, ("", dot)))
            },
            sve2_128: sourced(source) { _, result in
                let dot = sveResult(
                    bfloat16SveCall("bfdot", sveSplatOperand("c", for: result), for: result),
                    for: result
                )
                return body(result, native: (bfloat16SveFeatureCondition, ("", dot)))
            },
            avx3dl: sourced(source) { _, result in
                body(result, native: (bfloat16Avx3Condition, bfloat16Avx3Call("c", for: result)))
            }
        ),
        portable: sourced(source) { _, result in body(result) }
    )
}

let bfloat16MulAddOps = [
    ("multiplyAddingEven", "MulEvenAdd", 0), ("multiplyAddingOdd", "MulOddAdd", 1),
]
.flatMap { swiftName, highwayName, parity in
    sourcedOps(accepting: bfloat16PromotesToFloat, includingHalfPrecision: true) {
        source,
        results in
        func body(_ result: Element, native: (condition: String, kernel: WidenMulKernel)?) -> String
        {
            let generic = widenMulBody(
                ("", bfloat16FusedProducts(of: parity, onto: "c", for: result)),
                for: result
            )
            guard let native else { return generic }
            return widenMulChoice(
                [(native.condition, widenMulBody(native.kernel, for: result))],
                otherwise: generic
            )
        }
        return Op(
            swiftName,
            highwayName,
            [.tag, .sourceVector, .sourceVector, .vector],
            .vector,
            results,
            section: .fusedMultiplyAdd,
            unorderedNaNs: parity == 0 ? .widenedEven : .widenedOdd,
            filtersUnorderedNaNs: true,
            source: source,
            targets: TargetBodies(
                neon: sourced(source) { _, result in
                    let name = parity == 0 ? "vbfmlalbq" : "vbfmlaltq"
                    let call = bfloat16NeonCall(name, "c", for: result)
                    return body(result, native: (bfloat16NeonNativeCondition, ("", call)))
                },
                sve2_128: sourced(source) { _, result in
                    let name = parity == 0 ? "bfmlalb" : "bfmlalt"
                    let call = sveResult(
                        bfloat16SveCall(name, sveSplatOperand("c", for: result), for: result),
                        for: result
                    )
                    return body(result, native: (bfloat16SveFeatureCondition, ("", call)))
                }
            ),
            portable: sourced(source) { _, result in body(result, native: nil) }
        )
    }
}

let bfloat16MultiplyOps: [Op] =
    bfloat16PairwiseOps(masked: false) + bfloat16PairwiseOps(masked: true) + bfloat16ReorderOps
    + bfloat16MulAddOps

let bfloat16ConvertOps: [Op] = bfloat16PromoteOps + bfloat16DemoteOps + bfloat16MultiplyOps

let float16ArithmeticIdentifiers: [String] = [
    "adding",
    "subtracting",
    "multiplying",
    "dividing",
    "squareRoot",
    "absoluteDifference",
    "addingSubtracting",
    "clamped",
    "minimum",
    "maximum",
    "minimumNumber",
    "maximumNumber",
    "equalTo",
    "notEqualTo",
    "lessThan",
    "greaterThan",
    "lessThanOrEqualTo",
    "greaterThanOrEqualTo",
    "isNaN",
    "isEitherNaN",
    "isInfinite",
    "isFinite",
    "minimumMagnitude",
    "maximumMagnitude",
    "roundedToNearestOrEven",
    "roundedTowardZero",
    "roundedUp",
    "roundedDown",
    "multiplyAdding",
    "negatedMultiplyAdding",
    "multiplySubtracting",
    "negatedMultiplySubtracting",
    "multiplyAddingSubtracting",
