let float16FusedIdentifiers: Set<String> = [
    "multiplyAdding",
    "negatedMultiplyAdding",
    "multiplySubtracting",
    "negatedMultiplySubtracting",
    "multiplyAddingSubtracting",
    "multiplySubtractingAdding",
    "multiplyingComplex",
    "multiplyingComplexConjugate",
    "multiplyAddingComplex",
    "multiplyAddingComplexConjugate",
]

func float16Single(for element: Element) -> Element {
    floatElement(bits: 32).at(width: element.width)
}

func float16SourcedFunction(
    _ ops: [Op],
    _ identifier: String,
    from source: Element,
    to result: Element
) -> String {
    guard
        let op = ops.first(where: {
            $0.identifier == identifier && $0.source?.suffix == source.suffix
                && $0.applies.matches(result)
        })
    else {
        fatalError("There is no \(identifier) from \(source.swiftType) to \(result.swiftType)")
    }
    return cFunctionName(of: op, for: result)
}

func float16Operands(of op: Op) -> [String] {
    precondition(op.operands.allSatisfy { $0 == .vector }, "\(op.identifier) takes only vectors")
    return Array(["a", "b", "c"].prefix(op.operands.count))
}

enum Float16Reduction {
    case sum
    case smallest
    case largest

    var lanewise: String {
        switch self {
        case .sum: return "adding"
        case .smallest: return "minimum"
        case .largest: return "maximum"
        }
    }

    var identifier: String {
        switch self {
        case .sum: return "sum"
        case .smallest: return "smallest"
        case .largest: return "largest"
        }
    }

    var identity: String {
        self == .smallest ? "0x7C00" : "0xFC00"
    }
}

let float16Reductions: [String: (reduction: Float16Reduction, repeating: Bool, orNaN: Bool)] = [
    "sum": (.sum, false, false),
    "smallest": (.smallest, false, false),
    "largest": (.largest, false, false),
    "smallestOrNaN": (.smallest, false, true),
    "largestOrNaN": (.largest, false, true),
    "repeatingSum": (.sum, true, false),
    "repeatingSmallest": (.smallest, true, false),
    "repeatingLargest": (.largest, true, false),
]

func float16BaseIdentifier(ofMasked identifier: String) -> String? {
    for suffix in ["WhereOtherwise", "Where"] where identifier.hasSuffix(suffix) {
        return String(identifier.dropLast(suffix.count))
    }
    return nil
}

func float16PairwiseBody(subtracting: Bool, for element: Element) -> String {
    let evens = float16Call("interleavingEven", ["rawA", "rawB"], for: element)
    let odds = float16Call("interleavingOdd", ["rawA", "rawB"], for: element)
    guard subtracting else { return float16Composed("adding", [evens, odds], for: element) }
    return float16Composed("subtracting", [odds, evens], for: element)
}

func float16Call(_ identifier: String, _ arguments: [String], for element: Element) -> String {
    "\(cFunctionName(identifier, element))(\(arguments.joined(separator: ", ")))"
}

func float16TreeReduction(_ reduction: Float16Reduction, for element: Element) -> String {
    let unsigned = unsignedElement(bits: 16).at(width: element.width)
    let pairs = [
        float16Call("concatenatingEven", ["reduced", "reduced"], for: element),
        float16Call("concatenatingOdd", ["reduced", "reduced"], for: element),
    ]
    return """
        \(element.cRawVector) reduced = rawA;
        #pragma clang loop unroll(disable)
        for (size_t lanes = \(element.laneCount); lanes > 1; lanes /= 2) {
          reduced = \(float16Call(reduction.lanewise, pairs, for: element));
        }
        return \(cFunctionName("lane", unsigned))((\(unsigned.cRawVector))reduced, 0);
        """
}

func float16SingleReduction(_ reduction: Float16Reduction, for element: Element) -> String {
    let single = float16Single(for: element)
    let unsigned = unsignedElement(bits: 16).at(width: element.width)
    let lanes = single.laneCount
    let widening = float16PromotionOpList.first {
        $0.highwayName == "PromoteTo" && $0.source?.suffix == element.suffix
            && $0.applies.matches(single) && $0.sourceShape == .half
    }!
    func rounded(_ vector: String) -> String {
        let narrow = float16ComposedCall(
            float16DemotionOpList,
            "DemoteTo",
            from: single,
            to: element,
            ["(\(single.cRawVector))\(vector)"]
        )
        return "\(cFunctionName(of: widening, for: single))(\(narrow))"
    }
    func promoted(_ half: PromoteLowerUpperHalf) -> String {
        float16ComposedCall(
            float16PromotionOpList,
            "Promote\(uppercasedFirst(half.rawValue))To",
            from: element,
            to: single,
            ["(\(element.cRawVector))rawA"]
        )
    }
    func combined(_ evens: String, _ odds: String) -> String {
        let operands = [evens, odds].map { "(\(single.cRawVector))\($0)" }
        return "\(cFunctionName(reduction.lanewise, single))(\(operands.joined(separator: ", ")))"
    }
    let vector = single.cVector
    var statements = [
        "const \(vector) lower = (\(vector))\(promoted(.lower));",
        "const \(vector) upper = (\(vector))\(promoted(.upper));",
        "const \(vector) evens0 = __builtin_shufflevector(lower, upper, \(laneIndices((0..<lanes).map { 2 * $0 })));",
        "const \(vector) odds0 = __builtin_shufflevector(lower, upper, \(laneIndices((0..<lanes).map { 2 * $0 + 1 })));",
    ]
    var level = 0
    var total = "level0"
    var remaining = element.laneCount
    while true {
        let sum = combined("evens\(level)", "odds\(level)")
        remaining /= 2
        guard remaining > 1 else {
            statements.append("const \(vector) \(total) = (\(vector))\(sum);")
            break
        }
        let step = reduction == .sum ? rounded(sum) : sum
        statements.append("const \(vector) \(total) = (\(vector))\(step);")
        level += 1
        let evens = laneIndices((0..<lanes).map { (2 * $0) % lanes })
        let odds = laneIndices((0..<lanes).map { (2 * $0 + 1) % lanes })
        statements += [
            "const \(vector) evens\(level) = __builtin_shufflevector(\(total), \(total), \(evens));",
            "const \(vector) odds\(level) = __builtin_shufflevector(\(total), \(total), \(odds));",
        ]
        total = "level\(level)"
    }
    let narrow = float16ComposedCall(
        float16DemotionOpList,
        "DemoteTo",
        from: single,
        to: element,
        ["(\(single.cRawVector))\(total)"]
    )
    let half = "(\(unsigned.cRawVector(of: .half)))\(narrow)"
    let pair = "\(cFunctionName("combining", unsigned))(\(half), \(half))"
    statements.append("return \(cFunctionName("lane", unsigned))(\(pair), 0);")
    return statements.joined(separator: "\n")
}

func float16Reduced(_ op: Op, for element: Element) -> String? {
    guard let description = float16Reductions[op.identifier] else { return nil }
    let (reduction, repeating, orNaN) = description
    guard repeating || orNaN else { return float16SingleReduction(reduction, for: element) }
    let reduced = float16Call(reduction.identifier, ["rawA"], for: element)
    if repeating { return "return \(float16Call("repeating", [reduced], for: element));" }
    let nan = float16Call("isNaN", ["rawA"], for: element)
    return "return \(cFunctionName("allFalse", element))(\(nan)) ? \(reduced) : 0x7FFF;"
}

func float16Masked(_ op: Op, base: String, for element: Element) -> String {
    let names = bindings(of: op, for: element)
        .map(\.cDeclaration)
        .filter { !$0.isEmpty }
        .map { String($0.split(separator: " ").last ?? "") }
    var operands = names.filter { $0 != "rawMask" && $0 != "rawOtherwise" }
    if base == "dividing" && op.parameters.contains(.otherwiseVector) {
        let ones = float16Call("repeating", ["0x3C00"], for: element)
        operands[1] = float16Call("selecting", ["rawMask", operands[1], ones], for: element)
    }
    if op.returns == .lane {
        let masked: String
        switch base {
        case "sum": masked = float16Call("selectingOrZero", ["rawMask", "rawA"], for: element)
        default:
            let identity = float16Call(
                "repeating",
                [(base == "smallest" ? Float16Reduction.smallest : .largest).identity],
                for: element
            )
            masked = float16Call("selecting", ["rawMask", "rawA", identity], for: element)
        }
        return "return \(float16Call(base, [masked], for: element));"
    }
    let result = float16Call(base, operands, for: element)
    if op.returns == .mask {
        return "return \(float16Call("bitwiseAndMask", ["rawMask", result], for: element));"
    }
    if op.parameters.contains(.otherwiseVector) {
        return
            "return \(float16Call("selecting", ["rawMask", result, "rawOtherwise"], for: element));"
    }
    return "return \(float16Call("selectingOrZero", ["rawMask", result], for: element));"
}

func float16Fallback(_ op: Op, for element: Element, truncatingMasks: Bool = false) -> String {
    float16PortableBodies[op.identifier]?(element)
        ?? float16Emulated(op, for: element, truncatingMasks: truncatingMasks)
}

let float16X86RoundingImmediates: [String: Int] = [
    "roundedToNearestOrEven": 8,
    "roundedTowardZero": 11,
    "roundedUp": 10,
    "roundedDown": 9,
]

func float16Emulated(_ op: Op, for element: Element, truncatingMasks: Bool) -> String {
    guard let immediate = float16X86RoundingImmediates[op.identifier] else {
        return float16Lanewise(op, for: element, x86Rounding: nil, truncatingMasks: truncatingMasks)
    }
    return """
        #if CVECTORIZATION_OPS_X86 >= 3
        \(float16Lanewise(op, for: element, x86Rounding: immediate, truncatingMasks: false))
        #else
        \(float16Lanewise(op, for: element, x86Rounding: nil, truncatingMasks: truncatingMasks))
        #endif
        """
}

func float16Lanewise(
    _ op: Op,
    for element: Element,
    x86Rounding: Int?,
    truncatingMasks: Bool
) -> String {
    if let reduced = float16Reduced(op, for: element) { return reduced }
    if let base = float16BaseIdentifier(ofMasked: op.identifier) {
        return float16Masked(op, base: base, for: element)
    }
    if float16FusedIdentifiers.contains(op.identifier) {
        return float16FusedEmulated(op, for: element)
    }
    let single = float16Single(for: element)
    func halfResult(_ half: PromoteLowerUpperHalf) -> String {
        let arguments = float16Operands(of: op).map { operand in
            float16ComposedCall(
                float16PromotionOpList,
                "Promote\(uppercasedFirst(half.rawValue))To",
                from: element,
                to: single,
                ["(\(element.cRawVector))\(operand)"]
            )
        }
        guard let x86Rounding else {
            return "\(cFunctionName(of: op, for: single))(\(arguments.joined(separator: ", ")))"
        }
        let rounded = float16X86Rounded(arguments[0], immediate: x86Rounding, width: element.width)
        return "(\(single.cRawVector))\(rounded)"
    }
    if op.returns == .mask {
        if element.width == X86Level.avx3.width {
            let bits = [PromoteLowerUpperHalf.lower, .upper].map {
                x86Builtin(
                    "cvtd2mask512",
                    [(value: halfResult($0), type: x86Vector("i32"))],
                    returning: x86MaskType(lanes: single.laneCount)
                )
            }
            return maskResult(
                x86Avx3MaskVector("\(bits[0]) | ((unsigned int)\(bits[1]) << 16)", for: element),
                for: element
            )
        }
        if truncatingMasks {
            let masks = [PromoteLowerUpperHalf.lower, .upper].map {
                "__builtin_convertvector((\(single.cMask))\(halfResult($0)), \(element.cMask(of: .half)))"
            }
            let indices = laneIndices(0..<element.laneCount)
            return "return __builtin_shufflevector(\(masks[0]), \(masks[1]), \(indices));"
        }
        func narrowed(_ half: PromoteLowerUpperHalf) -> String {
            let narrowing = float16SourcedFunction(
                narrowMaskDemotionOps,
                "halfMaskNarrowing",
                from: single,
                to: element
            )
            return "\(narrowing)(\(halfResult(half)))"
        }
        return
            "return \(cFunctionName("combiningMasks", element))(\(narrowed(.upper)), \(narrowed(.lower)));"
    }
    return "return (\(element.cRawVector))\(float16Combined(for: element, halfResult: halfResult));"
}

func float16Combined(
    for element: Element,
    halfResult: (PromoteLowerUpperHalf) -> String
) -> String {
    let single = float16Single(for: element)
    let unsigned = unsignedElement(bits: 16).at(width: element.width)
    func narrowed(_ half: PromoteLowerUpperHalf) -> String {
        let demoted = float16ComposedCall(
            float16DemotionOpList,
            "DemoteTo",
            from: single,
            to: element,
            [halfResult(half)]
        )
        return "(\(unsigned.cRawVector(of: .half)))\(demoted)"
    }
    return "\(cFunctionName("combining", unsigned))(\(narrowed(.upper)), \(narrowed(.lower)))"
}

func float16FloorPowerOf2Emulated(for element: Element, roundsOnX86: Bool = false) -> String {
    let single = float16Single(for: element)
    let integer = signedElement(of: single).at(width: element.width)
    let (unsigned, mask, lanes) = (element.cUnsignedVector, element.cMask, element.laneCount)
    func scaled(_ half: PromoteLowerUpperHalf) -> String {
        func promoted(_ operand: String) -> String {
            float16ComposedCall(
                float16PromotionOpList,
                "Promote\(uppercasedFirst(half.rawValue))To",
                from: element,
                to: single,
                ["(\(element.cRawVector))\(operand)"]
            )
        }
        let exponents =
            roundsOnX86
            ? float16ComposedCall(
                convertToIntegerOps,
                "ConvertTo",
                from: single,
                to: integer,
                [
                    "(\(single.cRawVector))\(float16X86Rounded(promoted("b"), immediate: 9, width: element.width))"
                ]
            )
            : float16ComposedCall(
                conversionOps,
                "FloorInt",
                from: single,
                to: integer,
                [promoted("b")]
            )
        return float16ComposedCall(
            mulBitsPowerOf2Ops,
            "MulByPow2",
            from: integer,
            to: single,
            [promoted("a"), exponents]
        )
    }
    let exponentMask = splat("0x7C00", as: unsigned, lanes: lanes)
    let magnitudeMask = splat("0x7FFF", as: unsigned, lanes: lanes)
    let nan = splat(scalarNaN(of: element), as: element.cVector, lanes: lanes)
    return """
        const \(element.cVector) scaled = (\(element.cVector))\(float16Combined(for: element, halfResult: scaled));
        const \(mask) negative = (\(mask))\(unsignedBits("b", of: element)) < 0;
        const \(unsigned) target = \(exponentMask) & (\(unsigned))negative;
        const \(unsigned) magnitude = \(unsignedBits("b", of: element)) & \(magnitudeMask);
        const \(mask) infinite = (\(mask))(magnitude == \(exponentMask));
        const \(mask) special = (\(mask))(magnitude > \(exponentMask)) | (infinite & (\(mask))((\(unsignedBits("a", of: element)) & \(magnitudeMask)) == target));
        \(vectorResult(bitSelect("special", nan, "scaled", of: element), for: element))
        """
}

let float16FusedDecompositions: [String: (base: String, negating: Set<Int>)] = [
    "multiplySubtractingAdding": ("multiplyAddingSubtracting", [2])
]

func float16FusedDecomposition(
    of op: Op,
    for element: Element
) -> (base: String, negating: Set<Int>) {
    guard element.width > X86Level.sse4.width else { return (op.identifier, []) }
    return float16FusedDecompositions[op.identifier] ?? (op.identifier, [])
}

func float16FusedEmulated(_ op: Op, for element: Element) -> String {
    let single = float16Single(for: element)
    let double = floatElement(bits: 64).at(width: element.width)
    let words = unsignedElement(bits: 64).at(width: element.width)
    let unsigned = unsignedElement(bits: 16).at(width: element.width)
    let demotesQuarters = element.width == X86Level.avx3.width
    let (base, negating) = float16FusedDecomposition(of: op, for: element)
    let signs = splat("0x8000000000000000ULL", as: words.cVector, lanes: words.laneCount)
    let halving = float16SourcedFunction(
        demoteFloatOps,
        "halfVectorConverting",
        from: double,
        to: single
    )
    var statements: [String] = []
    var halves: [String] = []
    for half in [PromoteLowerUpperHalf.lower, .upper] {
        var quarters: [String] = []
        for part in [PromoteLowerUpperHalf.lower, .upper] {
            let name = "\(half.rawValue)\(uppercasedFirst(part.rawValue))"
            let arguments = float16Operands(of: op).map { operand -> String in
                let widened = float16ComposedCall(
                    float16PromotionOpList,
                    "Promote\(uppercasedFirst(half.rawValue))To",
                    from: element,
                    to: single,
                    ["(\(element.cRawVector))\(operand)"]
                )
                return float16ComposedCall(
                    promoteLowerUpperOps,
                    "Promote\(uppercasedFirst(part.rawValue))To",
                    from: single,
                    to: double,
                    [widened]
                )
            }
            let operands = arguments.enumerated().map { index, argument in
                negating.contains(index)
                    ? "(\(double.cRawVector))((\(words.cVector))\(argument) ^ \(signs))" : argument
            }
            let fused = "\(cFunctionName(base, double))(\(operands.joined(separator: ", ")))"
            guard demotesQuarters else {
                statements += [
                    "const \(words.cVector) \(name)Bits = (\(words.cVector))\(fused);",
                    "const \(words.cVector) \(name)Odd = (\(name)Bits & 0xFFFFFFFFE0000000u) | ((\(name)Bits + 0x1FFFFFFF) & 0x20000000);",
                ]
                quarters.append("\(halving)((\(double.cRawVector))\(name)Odd)")
                continue
            }
            let demoted = float16ComposedCall(
                float16DemotionOpList,
                "DemoteTo",
                from: double,
                to: element,
                [fused]
            )
            quarters.append("(\(unsigned.cRawVector(of: .quarter)))\(demoted)")
        }
        guard !demotesQuarters else {
            let indices = laneIndices(0..<element.laneCount / 2)
            halves.append("__builtin_shufflevector(\(quarters[0]), \(quarters[1]), \(indices))")
            continue
        }
        let combined = "\(cFunctionName("combining", single))(\(quarters[1]), \(quarters[0]))"
        let demoted = float16ComposedCall(
            float16DemotionOpList,
            "DemoteTo",
            from: single,
            to: element,
            [combined]
        )
        halves.append("(\(unsigned.cRawVector(of: .half)))\(demoted)")
    }
    let combined = "\(cFunctionName("combining", unsigned))(\(halves[1]), \(halves[0]))"
    return (statements + ["return (\(element.cRawVector))\(combined);"]).joined(separator: "\n")
}

func float16NativeOperands(_ expression: String) -> String {
    expression.replacingOccurrences(
        of: "\\b([abc])\\b",
        with: "(native_vector)$1",
        options: .regularExpression
    )
}

func float16NativeVectorOperation(_ expression: String, for element: Element) -> String {
    """
    \(halfPrecisionNativeVector(for: element))
    \(vectorResult("(\(element.cVector))(\(float16NativeOperands(expression)))", for: element))
    """
}

func float16NativeClamped(for element: Element) -> String {
    let code = neonTypeCode(of: element)
    let raised = neonBuiltin("vmaxnmq_f16", ["b", "a"], code: code, for: element)
    let clamped = neonBuiltin("vminnmq_f16", ["raised", "c"], code: code, for: element)
    return """
        const \(element.cVector) raised = \(raised);
        \(vectorResult(clamped, for: element))
        """
}

func float16NativeAlternating(negatingAll: Bool, for element: Element) -> String {
    var statements = [halfPrecisionNativeVector(for: element)]
    var odd = "(native_vector)c"
    if negatingAll {
        statements.append("const native_vector flipped = -\(odd);")
        odd = "flipped"
    }
    statements += [
        "const native_vector negated = -\(odd);",
        "const native_vector addend = \(alternatingLanes("negated", odd, for: element));",
        vectorResult(
            "(\(element.cVector))__builtin_elementwise_fma((native_vector)a, (native_vector)b, addend)",
            for: element
        ),
    ]
    return statements.joined(separator: "\n")
}

func float16NativeAddingSubtracting(for element: Element) -> String {
    """
    \(halfPrecisionNativeVector(for: element))
    const native_vector negated = -(native_vector)b;
    const native_vector addend = \(alternatingLanes("negated", "(native_vector)b", for: element));
    \(vectorResult("(\(element.cVector))((native_vector)a + addend)", for: element))
    """
}

func float16NativeComplex(conjugating: Bool, adding: Bool, for element: Element) -> String {
    let (fusedFirst, fusedSecond) = conjugating ? ("u", "x") : ("u", "y")
    let (productFirst, productSecond) = conjugating ? ("v", "y") : ("v", "x")
    let (differenceFirst, differenceSecond) =
        conjugating ? (("v", "x"), ("u", "y")) : (("u", "x"), ("v", "y"))
    let fused =
        "__builtin_elementwise_fma(n\(fusedFirst), n\(fusedSecond), n\(productFirst) * n\(productSecond))"
    let difference =
        "n\(differenceFirst.0) * n\(differenceFirst.1) - n\(differenceSecond.0) * n\(differenceSecond.1)"
    let (evens, odds) = conjugating ? (fused, difference) : (difference, fused)
    let vector = element.cVector
    let alternated = alternatingLanes("evens", "odds", for: element)
    let result = adding ? "(native_vector)multiplied + (native_vector)c" : "multiplied"
    let body = """
        \(complexDuplicates(for: element))
        \(halfPrecisionNativeVector(for: element))
        const native_vector nu = (native_vector)u;
        const native_vector nv = (native_vector)v;
        const native_vector nx = (native_vector)x;
        const native_vector ny = (native_vector)y;
        const native_vector odds = \(odds);
        const native_vector evens = \(evens);
        const \(vector) multiplied = (\(vector))\(alternated);
        \(vectorResult("(\(vector))(\(result))", for: element))
        """
    return withoutContraction(body)
}

func float16NativeReduction(_ builtin: String, for element: Element) -> String {
    """
    const _Float16 reduced = __builtin_neon_\(builtin)((\(neonVector("i8")))a);
    return __builtin_bit_cast(uint16_t, reduced);
    """
}

func float16NativeSum(for element: Element) -> String {
    let code = neonTypeCode(of: element)
    let half = neonVector("i8x8")
    let words = "uint16_t __attribute__((vector_size(8)))"
    return """
        const \(neonVector("i8")) pairs = __builtin_neon_vpaddq_f16((\(neonVector("i8")))a, (\(neonVector("i8")))a, \(code));
        const \(half) lower = __builtin_shufflevector(pairs, pairs, 0, 1, 2, 3, 4, 5, 6, 7);
        const \(half) quads = __builtin_neon_vpadd_f16(lower, lower, \(code - 32));
        const \(half) total = __builtin_neon_vpadd_f16(quads, quads, \(code - 32));
        return ((\(words))total)[0];
        """
}

func float16NativeMask(_ expression: String, for element: Element) -> String {
    """
    \(halfPrecisionNativeVector(for: element))
    \(maskResult("(\(element.cMask))(\(float16NativeOperands(expression)))", for: element))
    """
}

func float16NativeRounded(_ rounding: FloatRounding, for element: Element) -> String {
    float16NativeVectorOperation(
        "__builtin_elementwise_\(rounding.builtin)(a)",
        for: element
    )
}

func float16NativeExtremum(
    _ name: String,
    of operands: [String] = ["a", "b"],
    for element: Element
) -> String {
    let call = neonBuiltin(
        "v\(name)nmq_f16",
        operands,
        code: neonTypeCode(of: element),
        for: element
    )
    return vectorResult(call, for: element)
}

