func float16SveSum(for element: Element) -> String {
    let reduced = sveBuiltin(
        "addv",
        [sveAllLanes(of: element), sveOperand("a", for: element)],
        for: element
    )
    return "return __builtin_bit_cast(uint16_t, \(reduced));"
}

func float16SvePairwiseBlocks(subtracting: Bool, for element: Element) -> String {
    let name = cFunctionName(subtracting ? "pairwiseSubtracting" : "pairwiseAdding", element)
    let words = unsignedElement(bits: 64).at(width: element.width)
    let operand = sveOperand("pairwise", for: element)
    func concatenated(_ builtin: String) -> String {
        let call = sveBuiltin(builtin, [operand, operand], for: element)
        return sveReinterpreted(call, from: element, to: words)
    }
    let interleaved = sveBuiltin("zip1", [concatenated("uzp1"), concatenated("uzp2")], for: words)
    let result = sveResult(sveReinterpreted(interleaved, from: words, to: element), for: element)
    return """
        const \(element.cVector) pairwise = (\(element.cVector))\(name)(\(rawName("a")), \(rawName("b")));
        \(vectorResult(result, for: element))
        """
}

