func float16Composed(
    _ identifier: String,
    _ arguments: [String],
    for element: Element
) -> String {
    "return \(float16Call(identifier, arguments, for: element));"
}

func float16Exponent(for element: Element) -> String {
    let unsigned = element.cUnsignedVector
    let signed = signedElement(of: element).at(width: element.width)
    let converted = float16ComposedCall(
        float16IntegerOps,
        "ConvertTo",
        from: signed,
        to: element,
        ["(\(signed.cRawVector))exponent"]
    )
    return """
        const \(unsigned) bits = (\(unsigned))a;
        const \(signed.cVector) exponent = (\(signed.cVector))((bits & 0x7FFF) >> 10) - 15;
        return \(converted);
        """
}

func float16Iota(emulated: Bool, for element: Element) -> String {
    let lanes = element.laneCount
    guard emulated else {
        let first = splat(
            "__builtin_bit_cast(_Float16, value)",
            as: "native_vector",
            lanes: lanes
        )
        return """
            \(halfPrecisionNativeVector(for: element))
            \(vectorResult("(\(element.cVector))(\(first) + \(iota(as: "native_vector", lanes: lanes)))", for: element))
            """
    }
    let single = float16Single(for: element)
    let unsigned = unsignedElement(bits: 16).at(width: element.width)
    func narrowed(_ half: PromoteLowerUpperHalf) -> String {
        let start = half == .lower ? 0 : single.laneCount
        let offsets = compoundLiteral(
            single.cVector,
            (0..<single.laneCount).map { "\(start + $0).0f" }
        )
        let promoted = float16ComposedCall(
            float16PromotionOpList,
            "Promote\(uppercasedFirst(half.rawValue))To",
            from: element,
            to: single,
            [float16Call("repeating", ["value"], for: element)]
        )
        let sum =
            "\(cFunctionName("adding", single))(\(promoted), (\(single.cRawVector))\(offsets))"
        let demoted = float16ComposedCall(
            float16DemotionOpList,
            "DemoteTo",
            from: single,
            to: element,
            [sum]
        )
        return "(\(unsigned.cRawVector(of: .half)))\(demoted)"
    }
    let combined =
        "\(cFunctionName("combining", unsigned))(\(narrowed(.upper)), \(narrowed(.lower)))"
    return "return (\(element.cRawVector))\(combined);"
}

let float16PortableBodies: [String: (Element) -> String] = [
    "multiplyingRounded": {
        let product = float16Call("multiplying", ["rawA", "rawB"], for: $0)
        return float16Composed("roundedToNearestOrEven", [product], for: $0)
    },
    "pairwiseAdding": { float16PairwiseBody(subtracting: false, for: $0) },
    "pairwiseSubtracting": { float16PairwiseBody(subtracting: true, for: $0) },
    "pairwiseAddingBlocks": { x86PairwiseBlocks(subtracting: false, level: .ssse3, for: $0) },
    "pairwiseSubtractingBlocks": { x86PairwiseBlocks(subtracting: true, level: .ssse3, for: $0) },
    "exponent": { float16Exponent(for: $0) },
    "iota": { float16Iota(emulated: true, for: $0) },
    "complexConjugate": { element in
        let signs = (0..<element.laneCount).map { $0.isMultiple(of: 2) ? "0" : "0x8000" }
        let mask = compoundLiteral(element.cUnsignedVector, signs)
        return vectorResult(
            fromUnsignedBits("\(unsignedBits("a", of: element)) ^ \(mask)", of: element),
            for: element
        )
    },
    "isInfinite": { portableIsInfinite(for: $0) },
    "isFinite": { portableIsFinite(for: $0) },
]

func float16FusedReferenceComposition(
    of op: Op,
    for element: Element,
    _ arguments: [String]
) -> String {
    let single = "hn::Repartition<float, \(element.tag)>()"
    let double = "hn::Repartition<double, \(element.tag)>()"
    func quarter(_ half: String, _ part: String) -> String {
        let promoted = arguments.map {
            "hn::Promote\(part)To(\(double), hn::Promote\(half)To(\(single), \($0)))"
        }
        let fused = "hn::\(op.highwayName)(\(promoted.joined(separator: ", ")))"
        return "hn::DemoteTo(\(element.tag(of: .quarter))(), \(fused))"
    }
    func half(_ half: String) -> String {
        "hn::Combine(\(element.tag(of: .half))(), \(quarter(half, "Upper")), \(quarter(half, "Lower")))"
    }
    return "hn::Combine(\(element.tag)(), \(half("Upper")), \(half("Lower")))"
}

func float16CompositeReference(of op: Op, for element: Element, _ arguments: [String]) -> String? {
    let single = "hn::Repartition<float, \(element.tag)>()"
    let halfTag = "\(element.tag(of: .half))()"
    switch op.identifier {
    case "multiplyingRounded":
        let product = float16ReferenceComposition(
            of: float16Source(named: "multiplying"),
            for: element,
            arguments
        )
        return float16ReferenceComposition(
            of: float16Source(named: "roundedToNearestOrEven"),
            for: element,
            [product]
        )
    case "pairwiseAdding", "pairwiseSubtracting", "pairwiseAddingBlocks",
        "pairwiseSubtractingBlocks":
        let name = op.identifier.hasPrefix("pairwiseAdding") ? "PairwiseAdd" : "PairwiseSub"
        func half(_ promotion: String) -> String {
            let promoted = arguments[1...2].map { "hn::\(promotion)(\(single), \($0))" }
            return
                "hn::DemoteTo(\(halfTag), hn::\(name)(\(single), \(promoted.joined(separator: ", "))))"
        }
        let pairwise =
            "hn::Combine(\(element.tag)(), \(half("PromoteUpperTo")), \(half("PromoteLowerTo")))"
        guard op.identifier.hasSuffix("Blocks") else { return pairwise }
        return "hn::detail::BlockwiseConcatOddEven(\(element.tag)(), \(pairwise))"
    case "complexConjugate":
        let unsigned = "hn::RebindToUnsigned<\(element.tag)>()"
        let bits = "hn::BitCast(\(unsigned), \(arguments[0]))"
        let flipped = "hn::Xor(\(bits), hn::SignBit(\(unsigned)))"
        return "hn::BitCast(\(element.tag)(), hn::OddEven(\(flipped), \(bits)))"
    case "exponent":
        let unsigned = "hn::RebindToUnsigned<\(element.tag)>()"
        let signed = "hn::RebindToSigned<\(element.tag)>()"
        let bits =
            "hn::And(hn::BitCast(\(unsigned), \(arguments[0])), hn::Set(\(unsigned), 0x7FFF))"
        let biased = "hn::BitCast(\(signed), hn::ShiftRight<10>(\(bits)))"
        return float16FromIntegerReference(
            masked: false,
            from: signedElement(of: unsignedElement(bits: 16)),
            to: element,
            ["\(element.tag)()", "hn::Sub(\(biased), hn::Set(\(signed), 15))"]
        )
    case "iota":
        let first = "hn::Set(\(element.tag)(), \(arguments[1]))"
        func half(_ promotion: String, _ start: String) -> String {
            let sum =
                "hn::Add(hn::\(promotion)(\(single), \(first)), hn::Iota(\(single), \(start)))"
            return "hn::DemoteTo(\(halfTag), \(sum))"
        }
        let lanes = "static_cast<float>(hn::Lanes(\(single)))"
        return
            "hn::Combine(\(element.tag)(), \(half("PromoteUpperTo", lanes)), \(half("PromoteLowerTo", "0.0f")))"
    default: return nil
    }
}

func float16Source(named identifier: String) -> Op {
    guard
        let op = float16ArithmeticSources.first(where: {
            $0.identifier == identifier && $0.applies.matches(floatElement(bits: 32))
        })
    else { fatalError("There is no \(identifier) op on Float") }
    return op
}

func float16ReductionReferenceComposition(
    _ description: (reduction: Float16Reduction, repeating: Bool, orNaN: Bool),
    for element: Element,
    _ arguments: [String]
) -> String {
    let (tag, vector) = (arguments[0], arguments[1])
    let lanewise = float16Source(named: description.reduction.lanewise)
    let step = float16ReferenceComposition(of: lanewise, for: element, ["x", "y"])
    let reduced =
        """
        [&]() { const \(element.tag) d; auto v = \(vector); \
        const auto step = [&](auto x, auto y) { return \(step); }; \
        for (size_t lanes = hn::Lanes(d); lanes > 1; lanes /= 2) { \
        v = step(hn::ConcatEven(d, v, v), hn::ConcatOdd(d, v, v)); } return hn::GetLane(v); }()
        """
    if description.repeating { return "hn::Set(\(tag), \(reduced))" }
    guard description.orNaN else { return reduced }
    let nan = float16ReferenceComposition(of: float16Source(named: "isNaN"), for: element, [vector])
    return "(hn::AllFalse(\(tag), \(nan)) ? \(reduced) : hwy::ScalarNaN<hwy::float16_t>())"
}

func float16MaskedReferenceComposition(
    of op: Op,
    base: Op,
    for element: Element,
    _ arguments: [String]
) -> String {
    let labeled = Array(zip(op.parameters, arguments))
    let mask = labeled.first { $0.0 == .whereMask }!.1
    let otherwise = labeled.first { $0.0 == .otherwiseVector }?.1
    let vectors = labeled.filter { $0.0 == .vector }.map(\.1)
    if op.returns == .lane {
        let tag = labeled.first { $0.0 == .tag }!.1
        let masked =
            switch base.identifier {
            case "sum": "hn::IfThenElseZero(\(mask), \(vectors[0]))"
            case "smallest":
                "hn::IfThenElse(\(mask), \(vectors[0]), hn::Set(\(tag), hwy::PositiveInfOrHighestValue<hwy::float16_t>()))"
            default:
                "hn::IfThenElse(\(mask), \(vectors[0]), hn::Set(\(tag), hwy::NegativeInfOrLowestValue<hwy::float16_t>()))"
            }
        return float16ReferenceComposition(of: base, for: element, [tag, masked])
    }
    var divisors = vectors
    if base.identifier == "dividing" && otherwise != nil {
        let ones =
            "hn::Set(\(element.tag)(), \(element.hwyScalar("static_cast<uint16_t>(0x3C00)")))"
        divisors[1] = "hn::IfThenElse(\(mask), \(vectors[1]), \(ones))"
    }
    let composed = float16ReferenceComposition(of: base, for: element, divisors)
    if op.returns == .mask { return "hn::And(\(mask), \(composed))" }
    if let otherwise { return "hn::IfThenElse(\(mask), \(composed), \(otherwise))" }
    return "hn::IfThenElseZero(\(mask), \(composed))"
}

func float16ReferenceComposition(
    of op: Op,
    for element: Element,
    _ arguments: [String]
) -> String {
    if let description = float16Reductions[op.identifier] {
        return float16ReductionReferenceComposition(description, for: element, arguments)
    }
    if let composition = float16CompositeReference(of: op, for: element, arguments) {
        return composition
    }
    if let base = float16BaseIdentifier(ofMasked: op.identifier) {
        return float16MaskedReferenceComposition(
            of: op,
            base: float16Source(named: base),
            for: element,
            arguments
        )
    }
    if float16FusedIdentifiers.contains(op.identifier) {
        return float16FusedReferenceComposition(of: op, for: element, arguments)
    }
    let single = "hn::Repartition<float, \(element.tag)>()"
    let operands = zip(op.parameters, arguments).filter { !$0.0.isTag }.map(\.1)
    func half(_ promotion: String) -> String {
        let promoted = operands.map { "hn::\(promotion)(\(single), \($0))" }
        return "hn::\(op.highwayName)(\(promoted.joined(separator: ", ")))"
    }
    let halfTag = "\(element.tag(of: .half))()"
    if op.returns == .mask {
        func narrowed(_ promotion: String) -> String {
            "hn::DemoteMaskTo(\(halfTag), \(single), \(half(promotion)))"
        }
        return
            "hn::CombineMasks(\(element.tag)(), \(narrowed("PromoteUpperTo")), \(narrowed("PromoteLowerTo")))"
    }
    func narrowed(_ promotion: String) -> String {
        "hn::DemoteTo(\(halfTag), \(half(promotion)))"
    }
    return
        "hn::Combine(\(element.tag)(), \(narrowed("PromoteUpperTo")), \(narrowed("PromoteLowerTo")))"
}

func float16ReferenceCall(of op: Op) -> (Element, [String]) -> String {
    { element, arguments in
        let direct = "hn::\(op.highwayName)(\(arguments.joined(separator: ", ")))"
        let composition = float16ReferenceComposition(of: op, for: element, arguments)
        return "\n#if HWY_HAVE_FLOAT16\n\(direct)\n#else\n\(composition)\n#endif\n"
    }
}

func float16ArithmeticVariant(of op: Op) -> Op {
    let native = float16NativeBodies[op.identifier]
    let halves: ((Element) -> String)? =
        float16HalvesIdentifiers.contains(op.identifier)
        ? { float16Lanewise(op, for: $0, x86Rounding: nil, truncatingMasks: false) } : nil
    let truncatedMasks: ((Element) -> String)? =
        op.returns == .mask && float16PortableBodies[op.identifier] == nil
        ? { float16Lanewise(op, for: $0, x86Rounding: nil, truncatingMasks: true) } : nil
    let nativeMasks: ((Element) -> String)? =
        op.returns == .mask
        ? native.map { native in
            { element in
                """
                #if \(float16SprCondition)
                \(native(element))
                #else
                \(float16Lanewise(op, for: element, x86Rounding: nil, truncatingMasks: false))
                #endif
                """
            }
        } : nil
    return Op(
        op.swiftName,
        op.highwayName,
        op.parameters,
        op.returns,
        .results([float16]),
        section: op.section,
        unorderedNaNs: op.unorderedNaNs,
        filtersUnorderedNaNs: op.filtersUnorderedNaNs,
        vectorLabels: op.vectorLabels,
        maskLabels: op.maskLabels,
        identifier: op.explicitIdentifier,
        targets: TargetBodies(
            neon: native.map { native in
                { element in
                    """
                    #if \(neonHasFloat16Condition)
                    \(native(element))
                    #else
                    \(float16NeonFallbackBodies[op.identifier]?(element) ?? float16Fallback(op, for: element, truncatingMasks: true))
                    #endif
                    """
                }
            },
            sve2_128: float16SveBodies[op.identifier] ?? float16SveMaskedArithmetic(of: op),
            sve2_128Splat: float16SveSplatBodies[op.identifier],
            avx3: halves ?? nativeMasks,
            avx2: halves ?? truncatedMasks ?? float16Avx2Bodies[op.identifier],
            ssse3: float16SsseBodies[op.identifier],
            sse2: float16SseBodies[op.identifier] ?? halves
        ),
        helpers: TargetBodies(sve2_128: float16SveHelpers[op.identifier]),
        outOfLineOnSVE: op.outOfLineOnSVE?.including([float16]),
        referenceCall: float16ReferenceCall(of: op),
        portable: { float16Fallback(op, for: $0) }
    )
}

let float16ArithmeticSources =
    basicOps + signAndComparisonOps + maskOps + swizzleOps + compressOps + maskedOps

func followsConversions(_ op: Op, for element: Element) -> Bool {
    element.category == .float16 && float16ArithmeticIdentifiers.contains(op.identifier)
}

let float16ArithmeticOps: [Op] = float16ArithmeticIdentifiers.map { identifier in
    guard
        let source = float16ArithmeticSources.first(where: {
            $0.identifier == identifier && $0.applies.matches(floatElement(bits: 32))
        })
    else { fatalError("There is no \(identifier) op on Float") }
    return float16ArithmeticVariant(of: source)
}

let ops =
    (basicOps + signAndComparisonOps + cryptoOps + maskOps + swizzleOps + compressOps
    + lookupSizes.map(lookupOp) + maskedOps + immediateOps + memoryOps + conversionOps
    + widenArithmeticOps + narrowOps + convertFloat16Ops + bfloat16ConvertOps + float16ArithmeticOps)
    .map(
        extendedToHalfPrecision
    )

// A widening load reads lanes of a narrower element type and promotes each of them to the
// element type of the vector it returns. It is two Highway ops rather than one, and its pointer
// is not a `Lane` pointer, so it does not fit `Op` and is generated on its own below.
struct WideningOp {
    let swiftName: String
    let highwayName: String
    let section: Section
    let takesCount: Bool
    var targets = TargetBodies<WideningElements>()

    var span: SpanExtent { takesCount ? .first : .vectors(1) }
}

let wideningOps: [WideningOp] = [
    WideningOp(
        swiftName: "loadWidening",
        highwayName: "LoadU",
        section: .load,
        takesCount: false,
        targets: TargetBodies(
            neon: { pair in neonWidening(from: pair.narrow, to: pair.wide) },
            avx3: { pair in x86Avx3Widening(from: pair.narrow, to: pair.wide) },
            avx2: { pair in x86Widening(takesCount: false, from: pair.narrow, to: pair.wide) },
            sse2: { pair in x86Widening(takesCount: false, from: pair.narrow, to: pair.wide) }
        )
    ),
    WideningOp(
        swiftName: "loadFirstWidening",
        highwayName: "LoadN",
        section: .load,
        takesCount: true,
        targets: TargetBodies(
            neon: { pair in neonLoadFirstWidening(from: pair.narrow, to: pair.wide) },
            sve2_128: { pair in sveLoadFirstWidening(from: pair.narrow, to: pair.wide) },
            avx3: { pair in x86Avx3LoadFirstWidening(from: pair.narrow, to: pair.wide) },
            avx2: { pair in x86Widening(takesCount: true, from: pair.narrow, to: pair.wide) },
            sse2: { pair in x86Widening(takesCount: true, from: pair.narrow, to: pair.wide) }
        )
    ),
]

/// Whether Highway promotes `narrow` lanes to `wide` ones: every narrower element of the same
/// category, an unsigned integer to a wider signed one, and a 32-bit float to a 64-bit integer or
/// a 32-bit integer to a 64-bit float.
func promotes(_ narrow: Element, to wide: Element) -> Bool {
    guard narrow.bits < wide.bits, !narrow.isHalfPrecision, !wide.isHalfPrecision else {
        return false
    }
    if narrow.category == wide.category { return true }
    switch (narrow.category, wide.category) {
    case (.unsignedInteger, .signedInteger): return true
    case (.signedInteger, .unsignedInteger): return false
    default: return narrow.bits == 32 && wide.bits == 64
    }
}

func convertsFloatToInteger(from narrow: Element, to wide: Element) -> Bool {
    narrow.category == .float
        && (wide.category == .unsignedInteger || wide.category == .signedInteger)
}

/// The element types `element` can be widened from.
func wideningSources(of element: Element) -> [Element] {
    elements.filter { promotes($0, to: element) }
}

/// The widenings the header defines in the section of `element`: those whose other element type
/// comes earlier in `elements`, so that the widening can use what both sections define.
func wideningPairs(definedIn element: Element) -> [(narrow: Element, wide: Element)] {
    let position = elements.firstIndex { $0.cSuffix == element.cSuffix } ?? 0
    func isDeclared(_ other: Element) -> Bool {
        (elements.firstIndex { $0.cSuffix == other.cSuffix } ?? 0) < position
    }
    let narrows = wideningSources(of: element).filter(isDeclared)
    let wides = elements.filter { isDeclared($0) && promotes(element, to: $0) }
    return narrows.map { (narrow: $0, wide: element) } + wides.map { (narrow: element, wide: $0) }
}

func wideningFunctionName(_ op: WideningOp, from narrow: Element, to wide: Element) -> String {
    "\(op.swiftName)\(narrow.suffix)To\(wide.suffix)"
}

func snakeCased(_ name: String) -> String {
    name.replacingOccurrences(of: "NaN", with: "Nan")
        .replacingOccurrences(of: "BFloat", with: "Bfloat")
        .map { $0.isUppercase ? "_\($0.lowercased())" : String($0) }.joined()
}

func cFunctionName(_ swiftName: String, _ element: Element) -> String {
    "cvectorization_ops_\(snakeCased(swiftName))_\(element.cSuffix)"
}

func referenceFunctionName(_ name: String, _ element: Element) -> String {
    "\(name)\(element.suffix)"
}

func cWideningFunctionName(_ op: WideningOp, from narrow: Element, to wide: Element) -> String {
    "cvectorization_ops_\(snakeCased(op.swiftName))_\(narrow.cSuffix)_to_\(wide.cSuffix)"
}

func cFunctionName(of op: Op, for element: Element) -> String {
    guard let source = op.source else { return cFunctionName(op.identifier, element) }
    let shape = op.sourceShape == .full ? "" : "\(op.sourceShape.cName)_"
    return
        "cvectorization_ops_\(snakeCased(op.identifier))_\(shape)\(source.cSuffix)_to_\(element.cSuffix)"
}

func referenceFunctionName(of op: Op, for element: Element) -> String {
    guard let source = op.source else { return referenceFunctionName(op.identifier, element) }
    return "\(op.identifier)\(op.sourceShape.prefix)\(source.suffix)To\(element.suffix)"
}

// A rebinding reinterprets a mask as the mask of another element type of the same size. It has
// a source and a target element type, so it does not fit `Op` and is generated on its own below.
struct RebindingOp {
    let swiftName: String
    let label: String
    let highwayName: String
    let section: Section
}

let rebindingOps: [RebindingOp] = [
    RebindingOp(
        swiftName: "mask",
        label: "rebinding",
        highwayName: "RebindMask",
        section: .convertMask
    )
]

/// The element types whose masks `element` can rebind.
func rebindingSources(of element: Element) -> [Element] {
    elements.filter { $0.bits == element.bits && $0.suffix != element.suffix }
}

/// The rebindings the header defines in the section of `element`: those between it and the
/// element types of its size that come earlier in `elements`, so that they can use what both
/// sections define.
func rebindingPairs(definedIn element: Element) -> [(source: Element, target: Element)] {
    let position = elements.firstIndex { $0.cSuffix == element.cSuffix } ?? 0
    let earlier = rebindingSources(of: element).filter { other in
        (elements.firstIndex { $0.cSuffix == other.cSuffix } ?? 0) < position
    }
    return earlier.flatMap { [(source: $0, target: element), (source: element, target: $0)] }
}

func rebindingFunctionName(
    _ op: RebindingOp,
    from source: Element,
    to target: Element
) -> String {
    "\(op.swiftName)\(uppercasedFirst(op.label))\(source.suffix)To\(target.suffix)"
}

func cRebindingFunctionName(
    _ op: RebindingOp,
    from source: Element,
    to target: Element
) -> String {
    let name = "\(snakeCased(op.swiftName))_\(snakeCased(op.label))"
    return "cvectorization_ops_\(name)_\(source.cSuffix)_to_\(target.cSuffix)"
}

let repeatingBlockName = "repeatingBlock"

/// The parameters of `repeatingBlock`, one per lane of a 128-bit block.
func repeatingBlockLanes(of element: Element) -> [String] {
    (0..<element.blockLaneCount).map { "v\($0)" }
}

struct Binding {
    let declaration: String
    let cDeclaration: String
    let argument: String
    let swiftLabel: String?
    let swiftName: String
    let swiftType: String
    let isInOut: Bool
}

func bindings(
    of op: Op,
    for element: Element,
    scope: String = "",
    checked: Bool = true
) -> [Binding] {
    var vectorNames = ["a", "b", "c", "d"].makeIterator()
    var swiftLabels = SwiftLabels(of: op)
    let maskCount = op.parameters.filter(\.isMask).count
    var maskNames = (maskCount > 1 ? ["a", "b"] : ["mask"]).makeIterator()
    var immediates = op.immediates.makeIterator()
    var outVectorIndex = 0
    var result: [Binding] = []

    for parameter in op.parameters {
        switch parameter {
        case .tag, .sourceTag, .narrowTag, .sourceNarrowTag:
            let operand = operandElement(of: parameter, for: element, source: op.source)
            result.append(
                Binding(
                    declaration: "",
                    cDeclaration: "",
                    argument: "\(operand.tag(of: parameter.shape))()",
                    swiftLabel: nil,
                    swiftName: "",
                    swiftType: "",
                    isInOut: false
                )
            )
        case .vector, .shiftCounts, .sourceVector, .signedSourceVector, .narrowVector,
            .sourceNarrowVector:
            let operand = operandElement(of: parameter, for: element, source: op.source)
            let shape = parameter.shape
            let name = vectorNames.next() ?? "v"
            let conversion =
                op.growth == .unspecified && shape.isPartial ? "registerFromPort" : "fromPort"
            result.append(
                Binding(
                    declaration: "\(operand.cRawVector(of: shape)) \(name)",
                    cDeclaration: "\(operand.cRawVector(of: shape)) \(rawName(name))",
                    argument: referenceConversion(shape.conversion(conversion), name, for: operand),
                    swiftLabel: swiftLabels.next(for: parameter) ?? "_",
                    swiftName: name,
                    swiftType: parameter.isSourced
                        ? "\(operand.namespace).\(shape.swiftVector)"
                        : "\(scope)\(shape.swiftVector)",
                    isInOut: false
                )
            )
        case .indices:
            result.append(
                Binding(
                    declaration: "\(element.cRawVector) indices",
                    cDeclaration: "\(element.cRawVector) \(rawName("indices"))",
                    argument: referenceConversion("fromPort", "indices", for: element),
                    swiftLabel: checkedLabel("at", checked: checked),
                    swiftName: "indices",
                    swiftType: "\(scope)Vector",
                    isInOut: false
                )
            )
        case .laneIndices:
            let indexElement = laneIndexElement(of: element)
            let vector = referenceConversion("fromPort", "indices", for: indexElement)
            result.append(
                Binding(
                    declaration: "\(indexElement.cRawVector) indices",
                    cDeclaration: "\(indexElement.cRawVector) \(rawName("indices"))",
                    argument: "hn::IndicesFromVec(\(element.tag)(), \(vector))",
                    swiftLabel: checkedLabel("at", checked: checked),
                    swiftName: "indices",
                    swiftType: "\(scope)Indices",
                    isInOut: false
                )
            )
        case .lookupIndices:
            let indexElement = laneIndexElement(of: element)
            result.append(
                Binding(
                    declaration: "\(indexElement.cRawVector) indices",
                    cDeclaration: "\(indexElement.cRawVector) \(rawName("indices"))",
                    argument: referenceConversion("fromPort", "indices", for: indexElement),
                    swiftLabel: "at",
                    swiftName: "indices",
                    swiftType: "\(scope)Indices",
                    isInOut: false
                )
            )
        case .mask, .whereMask, .sourceMask, .narrowMask, .sourceNarrowMask:
            let operand = operandElement(of: parameter, for: element, source: op.source)
            let shape = parameter.shape
            let name = parameter == .whereMask ? "mask" : maskNames.next() ?? "mask"
            result.append(
                Binding(
                    declaration: "\(operand.cRawMask(of: shape)) \(name)",
                    cDeclaration: "\(operand.cRawMask(of: shape)) \(rawName(name))",
                    argument: referenceConversion(
                        shape.conversion("maskFromPort"),
                        name,
                        for: operand
                    ),
                    swiftLabel: swiftLabels.next(for: parameter) ?? "_",
                    swiftName: name,
                    swiftType: parameter.isSourced
                        ? "\(operand.namespace).\(shape.swiftMask)" : "\(scope)\(shape.swiftMask)",
                    isInOut: false
                )
            )
        case .indexVector:
            let indexElement = laneIndexElement(of: element)
            result.append(
                Binding(
                    declaration: "\(indexElement.cRawVector) vector",
                    cDeclaration: "\(indexElement.cRawVector) \(rawName("vector"))",
                    argument: referenceConversion("fromPort", "vector", for: indexElement),
                    swiftLabel: checkedLabel("from", checked: checked),
                    swiftName: "vector",
                    swiftType: "\(scope)Indices",
                    isInOut: false
                )
            )
        case .lane:
            result.append(
                Binding(
                    declaration: "\(element.cScalar) value",
                    cDeclaration: "\(element.cScalar) value",
                    argument: element.hwyScalar("value"),
                    swiftLabel: "_",
                    swiftName: "value",
                    swiftType: "\(scope)Lane",
                    isInOut: false
                )
            )
        case .insertedLane:
            result.append(
                Binding(
                    declaration: "\(element.cScalar) value",
                    cDeclaration: "\(element.cScalar) value",
                    argument: element.hwyScalar("value"),
                    swiftLabel: "with",
                    swiftName: "value",
                    swiftType: "\(scope)Lane",
                    isInOut: false
                )
            )
        case .laneIndex:
            result.append(
                Binding(
                    declaration: "size_t index",
                    cDeclaration: "size_t index",
                    argument: "index",
                    swiftLabel: checkedLabel("at", checked: checked),
                    swiftName: "index",
                    swiftType: "Int",
                    isInOut: false
                )
            )
        case .tuple(let count):
            let members = (0..<count).map {
                referenceConversion("fromPort", "tuple.v\($0)", for: element)
            }
            result.append(
                Binding(
                    declaration: "\(element.cTuple(count)) tuple",
                    cDeclaration: "\(element.cTuple(count)) tuple",
                    argument:
                        "hn::Create\(count)(\(element.tag)(), \(members.joined(separator: ", ")))",
                    swiftLabel: "_",
                    swiftName: "tuple",
                    swiftType: tupleType("\(scope)Vector", count: count),
                    isInOut: false
                )
            )
        case .tupleIndex:
            result.append(
                Binding(
                    declaration: "size_t index",
                    cDeclaration: "size_t index",
                    argument: "",
                    swiftLabel: checkedLabel("at", checked: checked),
                    swiftName: "index",
                    swiftType: "Int",
                    isInOut: false
                )
            )
        case .constLanePointer:
            result.append(
                Binding(
                    declaration: "const \(element.cPointee)* from",
                    cDeclaration: "const \(element.cPointee)* from",
                    argument: element.hwyPointer("from", isConst: true),
                    swiftLabel: "from",
                    swiftName: "from",
                    swiftType: "UnsafePointer<\(scope)Lane>",
                    isInOut: false
                )
            )
        case .lanePointer:
            result.append(
                Binding(
                    declaration: "\(element.cPointee)* to",
                    cDeclaration: "\(element.cPointee)* to",
                    argument: element.hwyPointer("to", isConst: false),
                    swiftLabel: "to",
                    swiftName: "to",
                    swiftType: "UnsafeMutablePointer<\(scope)Lane>",
                    isInOut: false
                )
            )
        case .constBytePointer:
            result.append(
                Binding(
                    declaration: "const uint8_t* from",
                    cDeclaration: "const uint8_t* from",
                    argument: "from",
                    swiftLabel: "from",
                    swiftName: "from",
                    swiftType: "UnsafePointer<UInt8>",
                    isInOut: false
                )
            )
        case .bytePointer:
            result.append(
                Binding(
                    declaration: "uint8_t* to",
                    cDeclaration: "uint8_t* to",
                    argument: "to",
                    swiftLabel: "to",
                    swiftName: "to",
                    swiftType: "UnsafeMutablePointer<UInt8>",
                    isInOut: false
                )
            )
        case .flag:
            result.append(
                Binding(
                    declaration: "bool value",
                    cDeclaration: "bool value",
                    argument: "value",
                    swiftLabel: "_",
                    swiftName: "value",
                    swiftType: "Bool",
                    isInOut: false
                )
            )
        case .maskBits:
            result.append(
                Binding(
                    declaration: "uintptr_t bits",
                    cDeclaration: "uintptr_t bits",
                    argument: "static_cast<unsigned>(bits)",
                    swiftLabel: "bits",
                    swiftName: "bits",
                    swiftType: "UInt",
                    isInOut: false
                )
            )
        case .count:
            result.append(
                Binding(
                    declaration: "size_t count",
                    cDeclaration: "size_t count",
                    argument: "count",
                    swiftLabel: "count",
                    swiftName: "count",
                    swiftType: "Int",
                    isInOut: false
                )
            )
        case .shiftAmount:
            result.append(
                Binding(
                    declaration: "int bits",
                    cDeclaration: "int bits",
                    argument: "bits",
                    swiftLabel: "by",
                    swiftName: "bits",
                    swiftType: "Int",
                    isInOut: false
                )
            )
        case .laneAmount:
            result.append(
                Binding(
                    declaration: "size_t lanes",
                    cDeclaration: "size_t lanes",
                    argument: "lanes",
                    swiftLabel: checkedLabel("by", checked: checked),
                    swiftName: "lanes",
                    swiftType: "Int",
                    isInOut: false
                )
            )
        case .outVector:
            let name = "v\(outVectorIndex)"
            outVectorIndex += 1
            result.append(
                Binding(
                    declaration: "\(element.outVector)& \(name)",
                    cDeclaration: "void* \(rawName(name))",
                    argument: "inPlace<\(element.vector)>(\(name))",
                    swiftLabel: "_",
                    swiftName: name,
                    swiftType: "\(scope)Vector",
                    isInOut: true
                )
            )
        case .fillVector:
            result.append(
                Binding(
                    declaration: "\(element.cRawVector) fill",
                    cDeclaration: "\(element.cRawVector) \(rawName("fill"))",
                    argument: referenceConversion("fromPort", "fill", for: element),
                    swiftLabel: parameter.overloading?.label,
                    swiftName: "fill",
                    swiftType: "\(scope)Vector",
                    isInOut: false
                )
            )
        case .fillLane:
            result.append(
                Binding(
                    declaration: "\(element.cScalar) fill",
                    cDeclaration: "\(element.cScalar) fill",
                    argument: element.hwyScalar("fill"),
                    swiftLabel: parameter.overloading?.label,
                    swiftName: "fill",
                    swiftType: "\(scope)Lane",
                    isInOut: false
                )
            )
        case .otherwiseVector:
            result.append(
                Binding(
                    declaration: "\(element.cRawVector) otherwise",
                    cDeclaration: "\(element.cRawVector) \(rawName("otherwise"))",
                    argument: referenceConversion("fromPort", "otherwise", for: element),
                    swiftLabel: parameter.overloading?.label,
                    swiftName: "otherwise",
                    swiftType: "\(scope)Vector",
                    isInOut: false
                )
            )
        case .roundConstant:
            result.append(
                Binding(
                    declaration: "uint8_t roundConstant",
                    cDeclaration: "uint8_t roundConstant",
                    argument: "roundConstant",
                    swiftLabel: "roundConstant",
                    swiftName: "roundConstant",
                    swiftType: "UInt8",
                    isInOut: false
                )
            )
        case .immediate:
            guard let immediate = immediates.next() else {
                fatalError("\(op.identifier) has more immediate parameters than immediates")
            }
            result.append(
                Binding(
                    declaration: "int \(immediate.name)",
                    cDeclaration: "int \(immediate.name)",
                    argument: immediate.name,
                    swiftLabel: immediate.swiftLabel(checked: checked),
                    swiftName: immediate.name,
                    swiftType: "Int",
                    isInOut: false
                )
            )
        case .narrowLanePointer:
            guard let narrow = op.narrowElement else {
                fatalError("\(op.swiftName) takes a narrow pointer but has no narrow element")
            }
            result.append(
                Binding(
                    declaration: "\(narrow.cType)* to",
                    cDeclaration: "\(narrow.cType)* to",
                    argument: "to",
                    swiftLabel: "to",
                    swiftName: "to",
                    swiftType: "UnsafeMutablePointer<\(narrow.swiftType)>",
                    isInOut: false
                )
            )
        case .constBitsPointer:
            result.append(
                Binding(
                    declaration: "const uint8_t* bits",
                    cDeclaration: "const uint8_t* bits",
                    argument: "bits",
                    swiftLabel: "bits",
                    swiftName: "bits",
                    swiftType: "UnsafePointer<UInt8>",
                    isInOut: false
                )
            )
        case .constIndexPointer:
            let indexElement = laneIndexElement(of: element)
            result.append(
                Binding(
                    declaration: "const \(indexElement.cType)* from",
                    cDeclaration: "const \(indexElement.cType)* from",
                    argument: "from",
                    swiftLabel: "from",
                    swiftName: "from",
                    swiftType: "UnsafePointer<\(indexElement.swiftType)>",
                    isInOut: false
                )
            )
        case .pointerIndices, .pointerOffsets:
            let indexElement = signedElement(of: element)
            let name = parameter == .pointerIndices ? "indices" : "byteOffsets"
            result.append(
                Binding(
                    declaration: "\(indexElement.cRawVector) \(name)",
                    cDeclaration: "\(indexElement.cRawVector) \(rawName(name))",
                    argument: referenceConversion("fromPort", name, for: indexElement),
                    swiftLabel: name,
                    swiftName: name,
                    swiftType: "\(indexElement.namespace).Vector",
                    isInOut: false
                )
            )
        }
    }
    return result
}

func referenceConversion(
    _ conversion: String,
    _ expression: String,
    for element: Element
) -> String {
    "\(referenceFunctionName(conversion, element))(\(expression))"
}

func referenceIndicesRoundTrip(_ indices: String, for element: Element) -> String {
    let indexElement = laneIndexElement(of: element)
    let tables = [0, 1].map { table in
        let first = table == 0 ? "0" : "hn::Lanes(\(indexElement.tag)())"
        let iota = "hn::Iota(\(indexElement.tag)(), static_cast<\(indexElement.cType)>(\(first)))"
        return "hn::BitCast(\(element.tag)(), \(iota))"
    }
    let lookup =
        "hn::TwoTablesLookupLanes(\(element.tag)(), \(tables[0]), \(tables[1]), \(indices))"
    return "hn::BitCast(\(indexElement.tag)(), \(lookup))"
}

func referenceToPort(
    _ call: String,
    returning returns: ReturnType,
    for element: Element
) -> String {
    switch returns {
    case .vector: return referenceConversion("toPort", call, for: element)
    case .narrowVector(let shape):
        return referenceConversion(shape.conversion("toPort"), call, for: element)
    case .laneIndices:
        return referenceConversion("toPort", call, for: laneIndexElement(of: element))
    case .mask: return referenceConversion("maskToPort", call, for: element)
    case .narrowMask(let shape):
        return referenceConversion(shape.conversion("maskToPort"), call, for: element)
    case .indices:
        let indexElement = laneIndexElement(of: element)
        let converted = referenceIndicesRoundTrip(call, for: element)
        return referenceConversion("toPort", converted, for: indexElement)
    case .lane: return element.isHalfPrecision ? "hwy::BitCastScalar<uint16_t>(\(call))" : call
    default: return call
    }
}

func referenceBody(
    calling call: String,
    returning returns: ReturnType,
    for element: Element
) -> String {
    guard returns != .void else { return "\(call);" }
    if case .tuple(let count) = returns {
        let members = (0..<count).map {
            referenceConversion("toPort", "hn::Get\(count)<\($0)>(result)", for: element)
        }
        return "const auto result = \(call);\nreturn {\(members.joined(separator: ", "))};"
    }
    if returns == .laneIndices {
        let indexElement = laneIndexElement(of: element)
        let iota = "hn::BitCast(\(element.tag)(), hn::Iota(\(indexElement.tag)(), 0))"
        let indices = "hn::BitCast(\(indexElement.tag)(), hn::TableLookupLanes(\(iota), \(call)))"
        return "return \(referenceConversion("toPort", indices, for: indexElement));"
    }
    return "return \(referenceToPort(call, returning: returns, for: element));"
}

func referenceRoundConstantBody(
    of op: Op,
    bindings parameterBindings: [Binding],
    for element: Element
) -> String {
    let arguments = zip(parameterBindings, op.parameters)
        .filter { $0.1 != .roundConstant }
        .map(\.0.argument)
        .joined(separator: ", ")
    func call(_ constant: Int) -> String {
        let highway = "hn::\(op.highwayName)<\(constant)>(\(arguments))"
        return "return \(referenceToPort(highway, returning: op.returns, for: element));"
    }
    let cases = (0..<255).map { "  case \($0): \(call($0))" }
    return (["  switch (roundConstant) {"] + cases + ["  default: \(call(255))", "  }"])
        .joined(separator: "\n")
}

func tupleCount(of op: Op) -> Int {
    for case .tuple(let count) in op.parameters {
        return count
    }
    fatalError("\(op.swiftName) takes no tuple")
}

func referenceIndexedBody(
    of op: Op,
    for element: Element,
    arguments: [String],
    count: Int
) -> String {
    let cases = (0..<count).map { index in
        let call = "hn::\(op.highwayName)<\(index)>(\(arguments.joined(separator: ", ")))"
        let label = index == count - 1 ? "default" : "case \(index)"
        let body = referenceBody(calling: call, returning: op.returns, for: element)
        return "\(label): {\n\(body)\n}"
    }
    return "switch (index) {\n\(cases.joined(separator: "\n"))\n}"
}

func templateReferenceName(of op: Op, for element: Element) -> String {
    referenceFunctionName("\(op.identifier)Template", element)
}

struct ReferenceCase {
    let value: Int
    let bytes: Int
    let call: String
}

func referenceSwitchBody(
    on key: String,
    cases: [ReferenceCase],
    otherwise: String,
    returning returns: ReturnType,
    for element: Element
) -> String {
    func result(_ call: String) -> String {
        "return \(referenceToPort(call, returning: returns, for: element));"
    }
    var lines = ["  switch (\(key)) {"]
    for reference in cases {
        let isGuarded = reference.bytes > 16
        if isGuarded { lines.append("#if HWY_MAX_BYTES >= \(reference.bytes)") }
        lines.append("  case \(reference.value): \(result(reference.call))")
        if isGuarded { lines.append("#endif") }
    }
    lines += ["  default: \(result(otherwise))", "  }"]
    return lines.joined(separator: "\n")
}

func referenceTemplateBody(
    of op: Op,
    bindings parameterBindings: [Binding],
    for element: Element
) -> String {
    guard let template = op.template else { fatalError("\(op.identifier) has no template") }
    let operands = zip(parameterBindings, op.parameters)
    let arguments = operands.filter { $0.1 != .shiftAmount }.map(\.0.argument)
    let amount = operands.first { $0.1 == .shiftAmount }?.0.argument ?? "bits"
    let fallback =
        template.fallback.map { $0(parameterBindings.map(\.argument)) }
        ?? "hn::\(op.highwayName)(\(parameterBindings.map(\.argument).joined(separator: ", ")))"
    let cases = template.range(element).map { amount in
        ReferenceCase(
            value: amount,
            bytes: 16,
            call: "hn::\(template.name)<\(amount)>(\(arguments.joined(separator: ", ")))"
        )
    }
    return referenceSwitchBody(
        on: amount,
        cases: cases,
        otherwise: fallback,
        returning: op.returns,
        for: element
    )
}

func referenceImmediatesBody(
    of op: Op,
    bindings parameterBindings: [Binding],
    for element: Element
) -> String {
    let widest = element.at(width: X86Level.avx3.width)
    let arguments = zip(parameterBindings, op.parameters)
        .filter { $0.1 != .immediate }
        .map(\.0.argument)
    var tuples: [[Int]] = [[]]
    for immediate in op.immediates {
        tuples = tuples.flatMap { tuple in immediate.values(for: widest).map { tuple + [$0] } }
    }
    let radixes = op.immediates.map { $0.values(for: widest).upperBound + 1 }
    let names = op.immediates.map(\.name)
    let key = zip(names, radixes).dropFirst().reduce(names[0]) { "(\($0)) * \($1.1) + \($1.0)" }
    let cases = tuples.map { tuple in
        let bytes = zip(op.immediates, tuple).map {
            $0.upperBound.width(reaching: $1, for: element)
        }
        let value = zip(tuple, radixes).dropFirst().reduce(tuple[0]) { $0 * $1.1 + $1.0 }
        let template = tuple.map(String.init).joined(separator: ", ")
        return ReferenceCase(
            value: value,
            bytes: bytes.max() ?? 16,
            call: "hn::\(op.highwayName)<\(template)>(\(arguments.joined(separator: ", ")))"
        )
    }
    return referenceSwitchBody(
        on: key,
        cases: cases,
        otherwise: cases[0].call,
        returning: op.returns,
        for: element
    )
}

func referenceOutVectorBody(
    of op: Op,
    for element: Element,
    bindings parameterBindings: [Binding]
) -> String {
    var temporaryArguments: [String] = []
    var temporaries: [String] = []
    var bridgedStores: [String] = []
    var memoryStores: [String] = []
    for binding in parameterBindings {
        guard binding.isInOut else {
            temporaryArguments.append(binding.argument)
            continue
        }
        let temporary = "h\(temporaries.count)"
        let pointer = "reinterpret_cast<\(element.hwyType)*>(&\(binding.swiftName))"
        let initial = referenceConversion("fromPort", binding.swiftName, for: element)
        temporaryArguments.append(temporary)
        temporaries.append(op.accumulates ? "\(temporary) = \(initial)" : temporary)
        let converted = referenceConversion("toPort", temporary, for: element)
        bridgedStores.append("\(binding.swiftName) = \(converted);")
        memoryStores.append("hn::StoreU(\(temporary), \(element.tag)(), \(pointer));")
    }
    let inPlaceArguments = parameterBindings.map(\.argument).joined(separator: ", ")
    let declaration = "\(element.vector) \(temporaries.joined(separator: ", "));"
    let hasResult = op.returns != .void
    let call =
        "\(hasResult ? "const auto result = " : "")"
        + "hn::\(op.highwayName)(\(temporaryArguments.joined(separator: ", ")));"
    let returned =
        hasResult ? [referenceBody(calling: "result", returning: op.returns, for: element)] : []
    func outOfPlace(_ stores: [String]) -> String {
        ([declaration, call] + stores + returned).map { "  \($0)" }.joined(separator: "\n")
    }
    let inPlace = referenceBody(
        calling: "hn::\(op.highwayName)(\(inPlaceArguments))",
        returning: op.returns,
        for: element
    )
    let isWide =
        op.accumulates ? "HWY_MAX_BYTES > 16 || HWY_TARGET == HWY_EMU128" : "HWY_MAX_BYTES > 16"
    return """
        #if HWY_TARGET_IS_SVE
        \(outOfPlace(bridgedStores))
        #elif \(isWide)
        \(outOfPlace(memoryStores))
        #else
          \(inPlace)
        #endif
        """
}

func cReturnType(_ returns: ReturnType, _ element: Element) -> String {
    switch returns {
    case .vector: return element.cRawVector
    case .laneIndices: return laneIndexElement(of: element).cRawVector
    case .mask: return element.cRawMask
    case .lane: return element.cScalar
    case .count: return "size_t"
    case .index: return "intptr_t"
    case .bits: return "uint64_t"
    case .boolean: return "bool"
    case .void: return "void"
    case .indices: return laneIndexElement(of: element).cRawVector
    case .tuple(let count): return element.cTuple(count)
    case .narrowVector(let shape): return element.cRawVector(of: shape)
    case .narrowMask(let shape): return element.cRawMask(of: shape)
    }
}

func tupleType(_ vector: String, count: Int) -> String {
    "(\(Array(repeating: vector, count: count).joined(separator: ", ")))"
}

func swiftReturnType(_ returns: ReturnType, scope: String = "") -> String {
    switch returns {
    case .vector: return "\(scope)Vector"
    case .laneIndices: return "\(scope)Indices"
    case .mask: return "\(scope)Mask"
    case .lane: return "\(scope)Lane"
    case .count, .index: return "Int"
    case .bits: return "UInt64"
    case .boolean: return "Bool"
    case .void: return "Void"
    case .indices: return "\(scope)Indices"
    case .tuple(let count): return tupleType("\(scope)Vector", count: count)
    case .narrowVector(let shape): return "\(scope)\(shape.swiftVector)"
    case .narrowMask(let shape): return "\(scope)\(shape.swiftMask)"
    }
}

func importedReturnType(_ returns: ReturnType, _ element: Element) -> String {
    switch returns {
    case .vector: return "\(element.namespace).Vector"
    case .laneIndices: return "\(laneIndexElement(of: element).namespace).Vector"
    case .mask: return "\(element.namespace).Mask"
    case .lane: return element.swiftType
    case .count, .index: return "Int"
    case .bits: return "UInt64"
    case .boolean: return "Bool"
    case .void: return "Void"
    case .indices: return "\(laneIndexElement(of: element).namespace).Vector"
    case .tuple(let count): return tupleType("\(element.namespace).Vector", count: count)
    case .narrowVector(let shape): return "\(element.namespace).\(shape.swiftVector)"
    case .narrowMask(let shape): return "\(element.namespace).\(shape.swiftMask)"
    }
}

let generationNotice = """
    // Generated by utils/GenerateVectorizationOps.swift. Do not edit.
    """

func unavailableSendableConformance(of type: String) -> String {
    """
    @available(*, unavailable)
    extension \(type): Sendable {}
    """
}

func neonBridgeType(of element: Element) -> String {
    let name =
        switch element.category {
        case .unsignedInteger: "uint"
        case .signedInteger: "int"
        case .float, .float16: "float"
        case .bfloat16: "bfloat"
        }
    return "\(name)\(element.bits)x\(element.blockLaneCount)_t"
}

func neonBridgeToSve(_ expression: String, of element: Element) -> String {
    let suffix = sveSuffix(of: element)
    return
        "svset_neonq_\(suffix)(svundef_\(suffix)(), (\(neonBridgeType(of: element)))\(expression))"
}

func neonBridgeFromSve(_ expression: String, of element: Element, as type: String) -> String {
    "(\(type))svget_neonq_\(sveSuffix(of: element))(\(expression))"
}

func referenceMask(fromSigned vector: String, tag: String, of element: Element) -> String {
    element.isHalfPrecision
        ? "hn::RebindMask(\(tag)(), hn::MaskFromVec(\(vector)))"
        : "hn::MaskFromVec(hn::BitCast(\(tag)(), \(vector)))"
}

func referenceSignedVector(fromMask mask: String, tag: String, of element: Element) -> String {
    element.isHalfPrecision
        ? "hn::VecFromMask(di, hn::RebindMask(di, \(mask)))"
        : "hn::BitCast(di, hn::VecFromMask(\(tag)(), \(mask)))"
}

func bridgedPortConversions(of element: Element) -> String {
    let signed = signedElement(of: element)
    let signedTag = "const hn::RebindToSigned<\(element.tag)> di;"
    var output = ""
    output += "HWY_INLINE \(element.vector) \(referenceFunctionName("fromPort", element))"
    output +=
        "(\(element.cRawVector) v) { return \(neonBridgeToSve("v", of: element)); }\n"
    output += "HWY_INLINE \(element.cRawVector) \(referenceFunctionName("toPort", element))"
    output += "(\(element.vector) v) { return "
    output += "\(neonBridgeFromSve("v", of: element, as: element.cRawVector)); }\n"
    output += "HWY_INLINE \(element.mask) \(referenceFunctionName("maskFromPort", element))"
    output += "(\(element.cRawMask) m) { return "
    output += referenceMask(
        fromSigned: neonBridgeToSve("m", of: signed),
        tag: element.tag,
        of: element
    )
    output += "; }\n"
    output += "HWY_INLINE \(element.cRawMask) \(referenceFunctionName("maskToPort", element))"
    output += "(\(element.mask) m) { \(signedTag) return "
    output += neonBridgeFromSve(
        referenceSignedVector(fromMask: "m", tag: element.tag, of: element),
        of: signed,
        as: element.cRawMask
    )
    output += "; }\n"
    return output
}

func memoryPortConversions(of element: Element) -> String {
    let signedTag = "const hn::RebindToSigned<\(element.tag)> di;"
    var output = ""
    output += "HWY_INLINE \(element.vector) \(referenceFunctionName("fromPort", element))"
    output +=
        "(\(element.cRawVector) v) { return hn::LoadU(\(element.tag)(), "
    output += "reinterpret_cast<const \(element.hwyType)*>(&v)); }\n"
    output += "HWY_INLINE \(element.cRawVector) \(referenceFunctionName("toPort", element))"
    output +=
        "(\(element.vector) v) { \(element.cRawVector) port; "
    output += "hn::StoreU(v, \(element.tag)(), reinterpret_cast<\(element.hwyType)*>(&port)); "
    output += "return port; }\n"
    output += "HWY_INLINE \(element.mask) \(referenceFunctionName("maskFromPort", element))"
    output += "(\(element.cRawMask) m) { \(signedTag) return "
    output += referenceMask(
        fromSigned: "hn::LoadU(di, reinterpret_cast<const \(element.cMaskLane)*>(&m))",
        tag: element.tag,
        of: element
    )
    output += "; }\n"
    output += "HWY_INLINE \(element.cRawMask) \(referenceFunctionName("maskToPort", element))"
    output +=
        "(\(element.mask) m) { \(signedTag) \(element.cRawMask) port; "
    output +=
        "hn::StoreU(\(referenceSignedVector(fromMask: "m", tag: element.tag, of: element)), di, "
    output += "reinterpret_cast<\(element.cMaskLane)*>(&port)); return port; }\n"
    return output
}

func narrowReferenceTag(of element: Element, shape: Shape) -> String {
    switch shape {
    case .full: return element.tag
    case .half: return "hn::Half<\(element.tag)>"
    case .quarter: return "hn::Half<\(element.tag(of: .half))>"
    case .eighth: return "hn::Half<\(element.tag(of: .quarter))>"
    case .block: return "hn::BlockDFromD<\(element.tag)>"
    }
}

func bridgedNarrowPortConversions(of element: Element, shape: Shape) -> String {
    let (raw, vector) = (element.cRawVector(of: shape), element.vector(of: shape))
    let rawLanes = (shape == .block ? 16 : 8) / (element.bits / 8)
    let padding = Array(repeating: -1, count: element.blockLaneCount - rawLanes)
    let block = element.cVector(of: .block)
    let widened =
        shape == .block
        ? "(\(neonBridgeType(of: element)))v"
        : "(\(neonBridgeType(of: element)))__builtin_shufflevector(v, v, "
            + "\(laneIndices(Array(0..<rawLanes) + padding)))"
    let narrowed =
        shape == .block
        ? neonBridgeFromSve("v", of: element, as: raw)
        : "__builtin_shufflevector(\(neonBridgeFromSve("v", of: element, as: block)), "
            + "\(neonBridgeFromSve("v", of: element, as: block)), \(laneIndices(0..<rawLanes)))"
    let suffix = sveSuffix(of: element)
    var output = ""
    output += "HWY_INLINE \(vector) \(referenceFunctionName(shape.conversion("fromPort"), element))"
    output += "(\(raw) v) { return svset_neonq_\(suffix)(svundef_\(suffix)(), \(widened)); }\n"
    if shape.isPartial {
        output += "HWY_INLINE \(vector) "
        output += "\(referenceFunctionName(shape.conversion("registerFromPort"), element))"
        output += "(\(raw) v) { return "
        output += "\(referenceFunctionName(shape.conversion("fromPort"), element))(v); }\n"
    }
    output += "HWY_INLINE \(raw) \(referenceFunctionName(shape.conversion("toPort"), element))"
    output += "(\(vector) v) { return \(narrowed); }\n"
    return output
        + (shape.hasMask ? bridgedNarrowMaskPortConversions(of: element, shape: shape) : "")
}

func bridgedNarrowMaskPortConversions(of element: Element, shape: Shape) -> String {
    let (raw, mask, tag) = (
        element.cRawMask(of: shape), element.mask(of: shape), element.tag(of: shape)
    )
    let signed = signedElement(of: element)
    let rawLanes = 8 / (element.bits / 8)
    let padding = Array(repeating: -1, count: element.blockLaneCount - rawLanes)
    let widened =
        "(\(neonBridgeType(of: signed)))__builtin_shufflevector(m, m, "
        + "\(laneIndices(Array(0..<rawLanes) + padding)))"
    let block = signed.cVector(of: .block)
    let suffix = sveSuffix(of: signed)
    var output = ""
    output +=
        "HWY_INLINE \(mask) \(referenceFunctionName(shape.conversion("maskFromPort"), element))"
    output += "(\(raw) m) { return "
    output += referenceMask(
        fromSigned: "svset_neonq_\(suffix)(svundef_\(suffix)(), \(widened))",
        tag: tag,
        of: element
    )
    output += "; }\n"
    output += "HWY_INLINE \(raw) \(referenceFunctionName(shape.conversion("maskToPort"), element))"
    output += "(\(mask) m) { const hn::RebindToSigned<\(tag)> di; "
    output += "const auto v = \(referenceSignedVector(fromMask: "m", tag: tag, of: element)); "
    output += "return __builtin_shufflevector((\(block))svget_neonq_\(suffix)(v), "
    output += "(\(block))svget_neonq_\(suffix)(v), \(laneIndices(0..<rawLanes))); }\n"
    return output
}

func memoryNarrowPortConversions(of element: Element, shape: Shape) -> String {
    let (raw, vector, tag) = (
        element.cRawVector(of: shape), element.vector(of: shape), element.tag(of: shape)
    )
    var output = ""
    output += "HWY_INLINE \(vector) \(referenceFunctionName(shape.conversion("fromPort"), element))"
    output += "(\(raw) v) { return hn::LoadU(\(tag)(), "
    output += "reinterpret_cast<const \(element.hwyType)*>(&v)); }\n"
    if shape.isPartial {
        output += "HWY_INLINE \(vector) "
        output += "\(referenceFunctionName(shape.conversion("registerFromPort"), element))"
        output += "(\(raw) v) { return hn::ResizeBitCast(\(tag)(), hn::LoadU("
        output += "hn::FixedTag<uint8_t, sizeof(\(raw))>(), "
        output += "reinterpret_cast<const uint8_t*>(&v))); }\n"
    }
    output += "HWY_INLINE \(raw) \(referenceFunctionName(shape.conversion("toPort"), element))"
    output += "(\(vector) v) { \(raw) port; "
    output += "hn::StoreU(v, \(tag)(), reinterpret_cast<\(element.hwyType)*>(&port)); "
    output += "return port; }\n"
    return output
        + (shape.hasMask ? memoryNarrowMaskPortConversions(of: element, shape: shape) : "")
}

func memoryNarrowMaskPortConversions(of element: Element, shape: Shape) -> String {
    let (raw, mask, tag) = (
        element.cRawMask(of: shape), element.mask(of: shape), element.tag(of: shape)
    )
    let signedTag = "const hn::RebindToSigned<\(tag)> di;"
    var output = ""
    output +=
        "HWY_INLINE \(mask) \(referenceFunctionName(shape.conversion("maskFromPort"), element))"
    output += "(\(raw) m) { \(signedTag) return "
    output += referenceMask(
        fromSigned: "hn::LoadU(di, reinterpret_cast<const \(element.cMaskLane)*>(&m))",
        tag: tag,
        of: element
    )
    output += "; }\n"
    output += "HWY_INLINE \(raw) \(referenceFunctionName(shape.conversion("maskToPort"), element))"
    output += "(\(mask) m) { \(signedTag) \(raw) port; "
    output += "hn::StoreU(\(referenceSignedVector(fromMask: "m", tag: tag, of: element)), di, "
    output += "reinterpret_cast<\(element.cMaskLane)*>(&port)); return port; }\n"
    return output
}

func narrowReferenceDeclarations(of element: Element) -> String {
    narrowShapes(of: element).map { shape in
        let mask =
            shape.hasMask
            ? "using \(element.mask(of: shape)) = hn::MFromD<\(element.tag(of: shape))>;\n" : ""
        return """
            using \(element.tag(of: shape)) = \(narrowReferenceTag(of: element, shape: shape));
            using \(element.vector(of: shape)) = hn::VFromD<\(element.tag(of: shape))>;
            \(mask)#if HWY_TARGET_IS_SVE
            \(bridgedNarrowPortConversions(of: element, shape: shape))#else
            \(memoryNarrowPortConversions(of: element, shape: shape))#endif

            """
    }.joined()
}

func portConversions(of element: Element) -> String {
    """
    #if HWY_TARGET_IS_SVE
    \(bridgedPortConversions(of: element))#else
    \(memoryPortConversions(of: element))#endif

    """
}

typealias ReferenceFunctions = (functions: String, nothrow: String)

func referenceOpFunctions(of op: Op, for element: Element) -> ReferenceFunctions {
    var functions = ""
    var nothrow = ""
    let parameterBindings = bindings(of: op, for: element)
    let declarations =
        parameterBindings
        .filter { !$0.declaration.isEmpty }
        .map(\.declaration)
        .joined(separator: ", ")
    let argumentList = parameterBindings.map(\.argument).filter { !$0.isEmpty }
    let arguments = argumentList.joined(separator: ", ")
    let body =
        op.parameters.contains(.tupleIndex)
        ? referenceIndexedBody(
            of: op,
            for: element,
            arguments: argumentList,
            count: tupleCount(of: op)
        )
        : referenceBody(
            calling: op.template?.fallback.map { $0(argumentList) }
                ?? op.referenceCall.map { $0(element, argumentList) }
                ?? "hn::\(op.highwayName)(\(arguments))",
            returning: op.returns,
            for: element
        )
    let specifier =
        op.outOfLineOnSVE?.matches(element) == true
        ? "SWIFT_HIGHWAY_REFERENCE_OPERAND_ORDERED" : "HWY_INLINE"
    functions += "\(specifier) \(cReturnType(op.returns, element)) "
    functions +=
        "\(referenceFunctionName(of: op, for: element))(\(declarations))"
    if parameterBindings.contains(where: \.isInOut) {
        let outVectorBody = referenceOutVectorBody(
            of: op,
            for: element,
            bindings: parameterBindings
        )
        functions += " {\n\(outVectorBody)\n}\n"
    } else if op.parameters.contains(.roundConstant) {
        let roundConstantBody = referenceRoundConstantBody(
            of: op,
            bindings: parameterBindings,
            for: element
        )
        functions += " {\n\(roundConstantBody)\n}\n"
    } else if !op.immediates.isEmpty {
        let immediatesBody = referenceImmediatesBody(
            of: op,
            bindings: parameterBindings,
            for: element
        )
        functions += " {\n\(immediatesBody)\n}\n"
    } else {
        functions += " { \(body) }\n"
    }
    nothrow += referenceNothrowWrapper(
        returning: cReturnType(op.returns, element),
        named: referenceFunctionName(of: op, for: element),
        declarations: declarations
    )
    if op.template != nil {
        let templateBody = referenceTemplateBody(
            of: op,
            bindings: parameterBindings,
            for: element
        )
        functions += "HWY_INLINE \(cReturnType(op.returns, element)) "
        functions += "\(templateReferenceName(of: op, for: element))(\(declarations))"
        functions += " {\n\(templateBody)\n}\n"
        nothrow += referenceNothrowWrapper(
            returning: cReturnType(op.returns, element),
            named: templateReferenceName(of: op, for: element),
            declarations: declarations
        )
    }
    if element.category == .float16 && float16ComposedOps.contains(op.identifier) {
        let composition = halfPrecisionComposition(of: op, for: element, declarations: declarations)
        functions = "#if \(nativeFloat16Condition)\n\(functions)#else\n\(composition)#endif\n"
    }
    return (functions, nothrow)
}

func generateReferenceHeader() -> String {
    var output = """
        \(generationNotice)

        #ifndef SWIFT_HIGHWAY_REFERENCE_H
        #define SWIFT_HIGHWAY_REFERENCE_H

        #include <stddef.h>
        #include <stdint.h>
        #include <new>
        #include "CVectorizationOps.h"

        #include "hwy/cache_control.h"
        #include "hwy/highway.h"
        #if HWY_TARGET_IS_SVE
        #include <arm_neon_sve_bridge.h>
        #endif

        namespace hwy {
        namespace HWY_NAMESPACE {
        struct ReferenceTarget {};
        }  // namespace HWY_NAMESPACE
        }  // namespace hwy

        namespace HighwayReference {
        namespace hn = hwy::HWY_NAMESPACE;

        /// Names the static target in the mangled name of a Swift function that takes it, which
        /// scripts/compare-codegen.sh reads the target from.
        using Target = hn::ReferenceTarget;

        /// Lets Highway write an out-parameter in place, so that its stores happen where the
        /// port's do, rather than all at once as a copy of a local would have them.
        template <typename Highway, typename Port>
        HWY_INLINE Highway& inPlace(Port& port) {
          static_assert(sizeof(Highway) == sizeof(Port), "the port's vector has Highway's size");
          static_assert(alignof(Highway) <= 16, "Swift aligns the port's vector to at most 16 bytes");
          return *new (&port) Highway;
        }

        /// The count a span form hands to an op that takes one. Highway's SVE2_128 ops truncate a
        /// count to 32 bits, so they get at most `lanes`, while the other targets take any.
        HWY_INLINE size_t spanCount(size_t count, size_t lanes) {
          return HWY_TARGET == HWY_SVE2_128 && count > lanes ? lanes : count;
        }

        /// Whether the static target only emulates vectors, in which case a caller is better off
        /// with its own scalar code.
        HWY_INLINE bool isEmulated() {
          return HWY_TARGET == HWY_SCALAR || HWY_TARGET == HWY_EMU128;
        }

        /// The name of the target the ops below were compiled for.
        HWY_INLINE const char* targetName() { return hwy::TargetName(HWY_TARGET); }

        HWY_INLINE const char* targetNameOf(int64_t target) { return hwy::TargetName(target); }

        HWY_INLINE int64_t staticTarget() { return HWY_STATIC_TARGET; }

        HWY_INLINE int64_t supportedTargets() { return hwy::SupportedTargets(); }

        \(targetSetReferenceFunctions())

        /// Whether highway's debug assertions are on, which abort on indices that its lookups
        /// do not accept.
        HWY_INLINE bool hasDebugAssertions() { return HWY_IS_DEBUG_BUILD; }

        \(targetCapabilityReferenceFunctions())

        /// Whether the lanes that Highway's Compress ops return after the selected ones are the
        /// same on every run. They are not where an op goes through a local array that it only
        /// partly writes, as it does for 8-bit lanes before AVX3_DL and for 16-bit lanes on AVX3.
        template <typename T>
        HWY_INLINE bool compressTailIsDeterministic() {
        #if HWY_TARGET == HWY_EMU128 || HWY_ARCH_ARM || HWY_TARGET <= HWY_AVX3_DL
          return true;
        #elif HWY_TARGET <= HWY_AVX3
          return sizeof(T) >= 4;
        #else
          return hn::CompressIsPartition<T>::value != 0;
        #endif
        }

        /// How many of the bytes after the first `kept` of a resized vector Highway gives
        /// deterministically when it grows them to `grown` bytes out of a register of
        /// `sourceRegister` bytes. EMU128 zeroes every new byte. NEON carries the register and
        /// zeroes the rest of a 16-byte result. x86 carries the register and leaves the bytes
        /// beyond it undefined, and SVE leaves them all undefined, as its registers are wider than
        /// the port's.
        HWY_INLINE size_t resizedBytesDefined(size_t kept, size_t grown, size_t sourceRegister) {
          if (grown <= kept) return 0;
        #if HWY_TARGET == HWY_EMU128 || HWY_TARGET_IS_NEON
          return grown - kept;
        #elif HWY_TARGET_IS_SVE
          return 0;
        #else
          return (grown < sourceRegister ? grown : sourceRegister) - kept;
        #endif
        }

        \(cacheControlReferenceFunctions())
        /// Highway's SVE ops overwrite one operand, so the compiler may swap a commutative op's
        /// operands to save a move, which decides whose NaN comes out when both are NaN. Out of
        /// line, the first operand is already in the register the op overwrites, which is the
        /// order Highway's call has.
        #if HWY_TARGET_IS_SVE
        #define SWIFT_HIGHWAY_REFERENCE_OPERAND_ORDERED inline HWY_NOINLINE
        #else
        #define SWIFT_HIGHWAY_REFERENCE_OPERAND_ORDERED HWY_INLINE
        #endif


        """

    var nothrow = ""
    for element in elements {
        output += "using \(element.tag) = hn::ScalableTag<\(element.hwyType)>;\n"
        output += "using \(element.vector) = hn::VFromD<\(element.tag)>;\n"
        output += "using \(element.mask) = hn::MFromD<\(element.tag)>;\n"
        output += "typedef \(element.cRawVector) \(element.outVector) "
        output += "__attribute__((aligned(16)));\n"
        output += "HWY_INLINE size_t \(referenceFunctionName("laneCount", element))()"
        output += " { return hn::Lanes(\(element.tag)()); }\n"
        nothrow += referenceNothrowWrapper(
            returning: "size_t",
            named: referenceFunctionName("laneCount", element),
            declarations: ""
        )
        output += "HWY_INLINE size_t \(referenceFunctionName("blockCount", element))()"
        output += " { return hn::Blocks(\(element.tag)()); }\n"
        let tailIsDeterministic = referenceFunctionName("compressTailIsDeterministic", element)
        output += "HWY_INLINE bool \(tailIsDeterministic)()"
        output += " { return compressTailIsDeterministic<\(element.hwyType)>(); }\n"
        for capability in laneCapabilities where capability.applies.matches(element) {
            output += "HWY_INLINE bool \(referenceFunctionName(capability.name, element))()"
            output += " { return \(capability.reference(for: element)); }\n"
        }
        output += portConversions(of: element)
        output += narrowReferenceDeclarations(of: element)
    }

    for element in elements {
        for op in ops where op.source == nil && op.applies.matches(element) {
            let (functions, wrappers) = referenceOpFunctions(of: op, for: element)
            output += functions
            nothrow += wrappers
        }

        for op in wideningOps {
            for narrow in wideningSources(of: element) {
                let countDeclaration = op.takesCount ? ", size_t count" : ""
                let countArgument = op.takesCount ? ", count" : ""
                let narrowTag = "hn::Rebind<\(narrow.cType), \(element.tag)>()"
                let load = "hn::\(op.highwayName)(\(narrowTag), from\(countArgument))"
                let body = referenceBody(
                    calling: "hn::PromoteTo(\(element.tag)(), \(load))",
                    returning: .vector,
                    for: element
                )
                output += "HWY_INLINE \(cReturnType(.vector, element)) "
                output += "\(wideningFunctionName(op, from: narrow, to: element))"
                output +=
                    "(const \(narrow.cType)* from\(countDeclaration))"
                output += " { \(body) }\n"
                nothrow += referenceNothrowWrapper(
                    returning: cReturnType(.vector, element),
                    named: wideningFunctionName(op, from: narrow, to: element),
                    declarations: "const \(narrow.cType)* from\(countDeclaration)"
                )
            }
        }

        for op in rebindingOps {
            for pair in rebindingPairs(definedIn: element) {
                let name = rebindingFunctionName(op, from: pair.source, to: pair.target)
                let mask = referenceConversion("maskFromPort", "mask", for: pair.source)
                let body = referenceBody(
                    calling: "hn::\(op.highwayName)(\(pair.target.tag)(), \(mask))",
                    returning: .mask,
                    for: pair.target
                )
                let declaration = "\(pair.source.cRawMask) mask"
                output += "HWY_INLINE \(cReturnType(.mask, pair.target)) "
                output += "\(name)(\(declaration)) { \(body) }\n"
                nothrow += referenceNothrowWrapper(
                    returning: cReturnType(.mask, pair.target),
                    named: name,
                    declarations: declaration
                )
            }
        }

        for composition in firstTrueCompositions(for: element) {
            output += maskCompositionReferenceFunction(composition, for: element)
        }

        let blockLanes = repeatingBlockLanes(of: element)
        let blockArguments = blockLanes.map(element.hwyScalar).joined(separator: ", ")
        let blockBody = referenceBody(
            calling: "hn::Dup128VecFromValues(\(element.tag)(), \(blockArguments))",
            returning: .vector,
            for: element
        )
        output += "HWY_INLINE \(cReturnType(.vector, element)) "
        output += "\(referenceFunctionName(repeatingBlockName, element))("
        output += blockLanes.map { "\(element.cScalar) \($0)" }.joined(separator: ", ")
        output += ") { \(blockBody) }\n"
        nothrow += referenceNothrowWrapper(
            returning: cReturnType(.vector, element),
            named: referenceFunctionName(repeatingBlockName, element),
            declarations: blockLanes.map { "\(element.cScalar) \($0)" }.joined(separator: ", ")
        )
        output += "\n"
    }

    for op in ops where op.source != nil {
        for element in elements where op.applies.matches(element) {
            let (functions, wrappers) = referenceOpFunctions(of: op, for: element)
            output += functions
            nothrow += wrappers
        }
    }

    output += """
        /// Swift calls a C++ function that might throw as an `invoke` with a landing pad, which makes
        /// LLVM schedule the code around the call differently from the code around the port's C
        /// functions. The codegen comparison calls these `noexcept` forwarders instead, which the
        /// tests do not: with them LLVM would no longer inline the ops into the tests' code.
        namespace Nothrow {
        HWY_INLINE size_t spanCount(size_t count, size_t lanes) noexcept {
          return ::HighwayReference::spanCount(count, lanes);
        }
        \(cacheControlNothrowFunctions())\(nothrow)}  // namespace Nothrow

        }  // namespace HighwayReference

        #endif

        """
    return output
}

func wideningLoad(takesCount: Bool, from narrow: Element, to wide: Element) -> String {
    let lanes = wide.laneCount
    let bytes = lanes * narrow.bits / 8
    let declaration = takesCount ? zeroedVector(of: "narrow_vector") : "narrow_vector v;"
    let size =
        takesCount
        ? "\(clampedCount(to: lanes)) * sizeof(\(narrow.cType))"
        : "sizeof v"
    return """
        typedef \(narrow.cType) narrow_vector __attribute__((vector_size(\(bytes))));
        \(declaration)
        __builtin_memcpy(&v, from, \(size));
        """
}

func portableSaturatingConversion(from narrow: Element, to integer: Element) -> String {
    let isSigned = integer.category == .signedInteger
    let outOfRangeExponent = 127 + integer.bits - (isSigned ? 1 : 0)
    let compared = isSigned ? "__builtin_fabsf(value)" : "value"
    let lane = narrow.cUnsignedLane
    let (lowest, highest) = (lowestValue(of: integer), highestValue(of: integer))
    let saturated = "(bits & 0x80000000) != 0 ? \(lowest) : \(highest)"
    return """
        \(integer.cVector) result;
        for (size_t i = 0; i < \(integer.laneCount); ++i) {
          const \(narrow.cType) value = v[i];
          const \(lane) bits = __builtin_bit_cast(\(lane), value);
          const \(lane) exponent = __builtin_bit_cast(\(lane), \(compared)) >> 23;
          result[i] = exponent < \(outOfRangeExponent) ? (\(integer.cType))value : \(saturated);
        }
        \(vectorResult("result", for: integer))
        """
}

func wideningBody(takesCount: Bool, from narrow: Element, to wide: Element) -> String {
    let load = wideningLoad(takesCount: takesCount, from: narrow, to: wide)
    guard !convertsFloatToInteger(from: narrow, to: wide) else {
        return "\(load)\n\(portableSaturatingConversion(from: narrow, to: wide))"
    }
    return """
        \(load)
        \(wide.cVector) result;
        for (size_t i = 0; i < \(wide.laneCount); ++i) {
          result[i] = v[i];
        }
        \(vectorResult("result", for: wide))
        """
}

func halfPrecisionRepeatingBlock(for element: Element) -> String {
    let unsigned = unsignedElement(bits: element.bits).at(width: element.width)
    let call =
        "\(cFunctionName(repeatingBlockName, unsigned))(\(repeatingBlockLanes(of: element).joined(separator: ", ")))"
    return "return (\(element.cRawVector))\(call);"
}

func repeatingBlockBody(of element: Element) -> String {
    let blocks = Array(repeating: repeatingBlockLanes(of: element), count: element.width / 16)
    return vectorResult(compoundLiteral(element.cVector, blocks.flatMap { $0 }), for: element)
}

typealias TargetBranch = (condition: String, body: String)

let neonCondition = "CVECTORIZATION_OPS_NEON"
let sve2_128Condition = "\(neonCondition) == \(ArmLevel.sve2_128.rawValue)"
let emu128Condition = "!\(neonCondition) && !CVECTORIZATION_OPS_X86"

func x86Condition(from first: X86Level, through last: X86Level) -> String {
    guard first != last else { return "CVECTORIZATION_OPS_X86 == \(first.rawValue)" }
    return
        "CVECTORIZATION_OPS_X86 >= \(first.rawValue) && CVECTORIZATION_OPS_X86 <= \(last.rawValue)"
}

func mergingIdenticalBodies(_ branches: [TargetBranch]) -> [TargetBranch] {
    var merged = branches
    guard let neon = merged.first, neon.condition == neonCondition,
        let index = merged.lastIndex(where: {
            $0.body == neon.body && $0.condition != neonCondition
        })
    else { return merged }
    merged[index].condition = "\(neonCondition) || (\(merged[index].condition))"
    merged.removeFirst()
    return merged
}

func x86Branches<Input: WidthScaled>(
    _ targets: TargetBodies<Input>,
    for input: Input,
    portable: ((Input) -> String)?
) -> [TargetBranch] {
    var ranges: [(first: X86Level, last: X86Level, body: String)] = []
    for level in supportedX86Levels {
        let scaled = input.at(width: level.width)
        let inherited = level.inherited.lazy.compactMap { targets.body(at: $0)?(scaled) }.first
        let widened = level.width > 16 ? portable?(scaled) : nil
        guard let body = inherited ?? widened else { continue }
        if let previous = ranges.last, previous.body == body,
            previous.last.rawValue + 1 == level.rawValue
        {
            ranges[ranges.count - 1].last = level
        } else {
            ranges.append((level, level, body))
        }
    }
    return ranges.reversed().map { range in
        (condition: x86Condition(from: range.first, through: range.last), body: range.body)
    }
}

func cBody<Input: WidthScaled>(
    _ targets: TargetBodies<Input>,
    for input: Input,
    portable: ((Input) -> String)?
) -> String {
    let fallback = portable?(input)
    let neonBody = targets.neon?(input)
    let splatBody = targets.sve2_128Splat?(input).map {
        [$0, neonBody ?? fallback].compactMap { $0 }.joined(separator: "\n")
    }
    let sve2 = (targets.sve2_128?(input) ?? splatBody).map {
        (condition: sve2_128Condition, body: $0)
    }
    let neon = neonBody.map { (condition: neonCondition, body: $0) }
    let emu128 = targets.emu128?(input).map { (condition: emu128Condition, body: $0) }
    let specific = (neon.map { [$0] } ?? []) + x86Branches(targets, for: input, portable: portable)
    let branches =
        (sve2.map { [$0] } ?? []) + mergingIdenticalBodies(specific.filter { $0.body != fallback })
        + (emu128.map { [$0] } ?? [])
    guard !branches.isEmpty else { return fallback ?? "" }
    let chain = branches.enumerated().flatMap { index, branch in
        ["#\(index == 0 ? "if" : "elif") \(branch.condition)", branch.body]
            .filter { !$0.isEmpty }
    }
    let otherwise = fallback.map { ["#else", $0] } ?? []
    return (chain + otherwise + ["#endif"]).joined(separator: "\n")
}

func neonHelperName(of op: Op, for element: Element) -> String {
    cFunctionName("neon" + uppercasedFirst(op.identifier), element)
}

func constantArgumentOf(_ op: Op, for element: Element) -> ConstantArgument? {
    guard let constant = op.constantArgument, constant.applies(element),
        op.targets.sve2_128?(element) != nil
    else { return nil }
    return constant
}

func cBody(of op: Op, for element: Element) -> String {
    var targets = op.targets
    if let constant = constantArgumentOf(op, for: element), let sve = targets.sve2_128 {
        let arguments = bindings(of: op, for: element)
            .filter { !$0.cDeclaration.isEmpty }
            .map { String($0.cDeclaration.split(separator: " ").last ?? "") }
            .map { $0 == constant.name ? "\(constant.cast)\($0)" : $0 }
        let call = "\(neonHelperName(of: op, for: element))(\(arguments.joined(separator: ", ")))"
        let delegation = op.returns == .void ? "\(call);\n  return;" : "return \(call);"
        let known =
            constant.vector
            ? "\(cFunctionName("sveConstant", element))(\(constant.name))"
            : "__builtin_constant_p(\(constant.name))"
        let conditions = [known] + (constant.holds.map { [$0(element)] } ?? [])
        targets.sve2_128 = { element in
            sve(element).map { body in
                """
                if (\(conditions.joined(separator: " && "))) {
                  \(delegation)
                }
                \(body)
                """
            }
        }
    }
    guard let template = op.template else {
        return cBody(targets, for: element, portable: op.portable)
    }
    let call = templatedCall(of: op, for: element)
    let declaration = "const \(element.cRawVector) result = \(call);"
    func deferring(_ path: ((Element) -> String?)?) -> ((Element) -> String?)? {
        path.map { path in
            { element in path(element).map { "\(declaration)\n\($0)\nreturn result;" } }
        }
    }
    let paths = template.paths
    let deferred = TargetBodies(
        neon: deferring(paths.neon),
        sve2_128: deferring(paths.sve2_128),
        avx3dl: deferring(paths.avx3dl),
        avx3: deferring(paths.avx3),
        avx2: deferring(paths.avx2),
        sse4: deferring(paths.sse4),
        ssse3: deferring(paths.ssse3),
        sse2: deferring(paths.sse2)
    )
    return cBody(deferred, for: element, portable: { _ in "return \(call);" })
}

func templatedHelperName(of op: Op, for element: Element) -> String {
    cFunctionName(op.identifier + "WithoutTemplate", element)
}

func templatedCall(of op: Op, for element: Element) -> String {
    let arguments = bindings(of: op, for: element)
        .filter { !$0.cDeclaration.isEmpty }
        .map { String($0.cDeclaration.split(separator: " ").last ?? "") }
    return "\(templatedHelperName(of: op, for: element))(\(arguments.joined(separator: ", ")))"
}

func cHelpers(of op: Op, for element: Element) -> String {
    var helpers = cBody(op.helpers, for: element, portable: nil)
    if op.template != nil {
        let parameters = bindings(of: op, for: element)
            .filter { !$0.cDeclaration.isEmpty }
            .map(\.cDeclaration)
        helpers += cOpFunction(
            returns: op.returns,
            name: templatedHelperName(of: op, for: element),
            parameters: parameters,
            prologue: cPrologue(of: op, for: element),
            body: cBody(op.targets, for: element, portable: op.portable),
            for: element
        )
    }
    if constantArgumentOf(op, for: element) != nil {
        let parameters = bindings(of: op, for: element)
            .filter { !$0.cDeclaration.isEmpty }
            .map(\.cDeclaration)
        let function = cOpFunction(
            returns: op.returns,
            name: neonHelperName(of: op, for: element),
            parameters: parameters,
            prologue: cPrologue(of: op, for: element),
            body: op.targets.neon?(element) ?? op.portable(element),
            for: element
        )
        helpers += "\(helpers.isEmpty ? "" : "\n")#if \(sve2_128Condition)\n\(function)#endif"
    }
    return helpers.isEmpty ? "" : "\(helpers)\n"
}

func cBody(of op: WideningOp, from narrow: Element, to wide: Element) -> String {
    cBody(
        op.targets,
        for: WideningElements(narrow: narrow, wide: wide),
        portable: { pair in
            wideningBody(takesCount: op.takesCount, from: pair.narrow, to: pair.wide)
        }
    )
}

func x86Helpers() -> String {
    let i64 = x86Vector("i64")
    let asFloats = [32, 64].map { bits in
        let float = x86Vector("f\(bits)")
        return cFunction(
            returns: float,
            name: x86AsFloatName(bits: bits),
            parameters: ["\(i64) v"],
            body: "return (\(float))v;"
        )
    }
    let selecting = cFunction(
        returns: i64,
        name: x86IfThenElseName,
        parameters: ["\(i64) mask", "\(i64) yes", "\(i64) no"],
        body: "return (mask & yes) | (~mask & no);"
    )
    let comparisons = [8, 32, 64].map { bits in
        let signed = x86Vector("i\(bits)")
        return cFunction(
            returns: i64,
            name: x86GreaterThanName(bits: bits),
            parameters: ["\(i64) a", "\(i64) b"],
            body: "return (\(i64))((\(signed))a > (\(signed))b);"
        )
    }
    let helpers =
        asFloats + [selecting] + comparisons + x86PartialLoadHelpers() + x86InterleaveLowerHelpers()
        + x86PartialStoreHelpers() + x86UpperHalfHelpers()
    let negatives = x86NegativeLanesHelpers().joined()
    let negativesCondition = x86Condition(from: .sse2, through: .ssse3)
    return """
        #if CVECTORIZATION_OPS_X86
        \(helpers.joined())#endif
        #if \(negativesCondition)
        \(negatives)#endif
        """
}

func neonTable(
    named name: String,
    _ bytes: [Int],
    alignment: Int = 16,
    isInternal: Bool = false,
    isHidden: Bool = false
) -> String {
    cFunction(
        returns: "const uint8_t*",
        name: name,
        parameters: [],
        body: """
            static const uint8_t table[\(bytes.count)] __attribute__((aligned(\(alignment)))) = {\(bytes.map(String.init).joined(separator: ", "))};
            return table;
            """,
        specifiers: isInternal
            ? "__attribute__((internal_linkage)) CVECTORIZATION_OPS_INLINE"
            : isHidden
                ? "__attribute__((visibility(\"hidden\"))) CVECTORIZATION_OPS_INLINE"
                : "CVECTORIZATION_OPS_INLINE"
    )
}

func neonHelpers() -> String {
    let zeroing = Array(repeating: 255, count: 16)
    let slideTable = neonTable(named: neonSlideTableName, zeroing + Array(0..<16) + zeroing)
    let slideFillingTables = [SlideDirection.up, .down].map { direction in
        neonTable(
            named: neonSlideFillingTableName(direction),
            neonSlideFillingTable(direction)
        )
    }
    let tables = [slideTable] + slideFillingTables
    return "#if CVECTORIZATION_OPS_NEON\n\(tables.joined())#endif"
}

func byteElement(of element: Element) -> Element {
    unsignedElement(bits: 8).at(width: element.width)
}

func indicesWithinBody(for element: Element) -> String {
    let unsigned = element.cUnsignedVector
    let first = splat("first", as: unsigned, lanes: element.laneCount)
    let limit = splat("limit", as: unsigned, lanes: element.laneCount)
    let exceedsLane = element.bits < 64 ? "count > UINT\(element.bits)_MAX || " : ""
    return """
        const \(element.cUnsignedLane) first = (\(element.cUnsignedLane))offset;
        const \(element.cUnsignedLane) limit = (\(element.cUnsignedLane))count;
        const \(unsigned) shifted = (\(unsigned))indices - \(first);
        return \(exceedsLane)__builtin_reduce_and(shifted < \(limit)) != 0;
        """
}

func indicesWithinName(perByte: Bool, for element: Element) -> String {
    perByte && element.bits > 8 ? "indicesWithinBytes" : "indicesWithin"
}

func indicesWithinFunction(perByte: Bool, for element: Element) -> String {
    cOpFunction(
        returns: .boolean,
        name: cFunctionName(indicesWithinName(perByte: perByte, for: element), element),
        parameters: ["\(element.cRawVector) rawIndices", "size_t offset", "size_t count"],
        prologue: ["const \(element.cVector) indices = (\(element.cVector))rawIndices;"],
        body: cBody(
            TargetBodies(),
            for: element,
            portable: { indicesWithinBody(for: perByte ? byteElement(of: $0) : $0) }
        ),
        for: element
    )
}

func indicesWithinWhereBody(signBits: Bool, for element: Element) -> String {
    let indices = signedElement(of: element).at(width: element.width)
    let unsigned = indices.cUnsignedVector
    let limit = splat("limit", as: unsigned, lanes: element.laneCount)
    let exceedsLane = element.bits < 64 ? "count > UINT\(element.bits)_MAX || " : ""
    let used = signBits ? "(mask < 0)" : "mask"
    return """
        const \(indices.cUnsignedLane) limit = (\(indices.cUnsignedLane))count;
        const \(indices.cMask) within = (\(indices.cMask))((\(unsigned))indices < \(limit));
        return \(exceedsLane)__builtin_reduce_or(\(used) & ~within) == 0;
        """
}

func indicesWithinWhereName(gathering: Bool) -> String {
    gathering ? "gatherIndicesWithinWhere" : "indicesWithinWhere"
}

/// What a masked gather or scatter checks: the indices of the lanes it uses, those with any bit of
/// the mask set, except that the gathers of AVX2 and AVX-512 and the scatters of AVX-512 only use
/// those with the sign bit set.
func indicesWithinWhereFunction(gathering: Bool, for element: Element) -> String {
    let indices = signedElement(of: element).at(width: element.width)
    let signBits: (Element) -> String? = { indicesWithinWhereBody(signBits: true, for: $0) }
    return cOpFunction(
        returns: .boolean,
        name: cFunctionName(indicesWithinWhereName(gathering: gathering), element),
        parameters: [
            "\(indices.cRawVector) rawIndices", "size_t count", "\(element.cRawMask) rawMask",
        ],
        prologue: [
            "const \(indices.cVector) indices = (\(indices.cVector))rawIndices;",
            "const \(indices.cMask) mask = (\(indices.cMask))(\(element.cMask))rawMask;",
        ],
        body: cBody(
            TargetBodies(avx3: signBits, avx2: gathering ? signBits : nil),
            for: element,
            portable: { indicesWithinWhereBody(signBits: false, for: $0) }
        ),
        for: element
    )
}

func rawVectorDeclarations() -> String {
    let groups = [
        (neonCondition, neonVectors),
        (sve2_128Condition, sveVectors),
        ("CVECTORIZATION_OPS_X86", x86Vectors),
    ]
    return groups.map { condition, vectors in
        let typedefs = vectors.map {
            "typedef \($0.type) \($0.name) __attribute__((\($0.attribute)));"
        }
        return (["#if \(condition)"] + typedefs + ["#endif"]).joined(separator: "\n")
    }
    .joined(separator: "\n\n")
}

func cFunction(
    returns: String,
    name: String,
    parameters: [String],
    body: String,
    specifiers: String = "CVECTORIZATION_OPS_INLINE"
) -> String {
    let signature = parameters.isEmpty ? "void" : parameters.joined(separator: ", ")
    let declaration = [specifiers, returns, "\(name)(\(signature))"].filter { !$0.isEmpty }
    let lines = body.split(separator: "\n", omittingEmptySubsequences: false).map {
        $0.hasPrefix("#") ? String($0) : "  \($0)"
    }
    return """
        \(declaration.joined(separator: " ")) {
        \(lines.joined(separator: "\n"))
        }

        """
}

func rawName(_ name: String) -> String {
    prefixed("raw", name)
}

func cPrologue(of op: Op, for element: Element) -> [String] {
    zip(bindings(of: op, for: element), op.parameters).compactMap { binding, parameter in
        let name = binding.swiftName
        let raw = rawName(name)
        switch parameter {
        case .vector, .shiftCounts, .indices, .laneIndices, .lookupIndices, .indexVector,
            .fillVector, .otherwiseVector, .pointerIndices, .pointerOffsets, .sourceVector,
            .signedSourceVector:
            let operand = operandElement(of: parameter, for: element, source: op.source)
            return "const \(operand.cVector) \(name) = (\(operand.cVector))\(raw);"
        case .narrowVector, .sourceNarrowVector:
            let operand = operandElement(of: parameter, for: element, source: op.source)
            return "const \(operand.cRawVector(of: parameter.shape)) \(name) = \(raw);"
        case .mask, .whereMask, .sourceMask:
            let operand = operandElement(of: parameter, for: element, source: op.source)
            return "const \(operand.cMask) \(name) = (\(operand.cMask))\(raw);"
        case .narrowMask, .sourceNarrowMask:
            let operand = operandElement(of: parameter, for: element, source: op.source)
            return "const \(operand.cRawMask(of: parameter.shape)) \(name) = \(raw);"
        case .outVector:
            return "\(element.cBlock)* const \(name) = (\(element.cBlock)*)\(raw);"
        default:
            return nil
        }
    }
}

func cOpFunction(
    returns: ReturnType,
    name: String,
    parameters: [String],
    prologue: [String] = [],
    body: String,
    for element: Element
) -> String {
    cFunction(
        returns: cReturnType(returns, element),
        name: name,
        parameters: parameters,
        body: (prologue + [body]).joined(separator: "\n")
    )
}

func cRawConversions(of element: Element) -> String {
    let vectors = [
        (element.cToRawVector, element.cRawVector, element.cVector),
        (element.cFromRawVector, element.cVector, element.cRawVector),
    ]
    let masks = [
        (element.cToRawMask, element.cRawMask, element.cMask),
        (element.cFromRawMask, element.cMask, element.cRawMask),
    ]
    let conversions = element.hasOpaqueVector ? vectors + masks : masks
    return conversions.map { name, result, source in
        cFunction(
            returns: result,
            name: name,
            parameters: ["\(source) v"],
            body: "return (\(result))v;"
        )
    }.joined()
}

enum StaticTargetSupport {
    case arm(ArmLevel)
    case x86(X86Level)
    case portable
    case unsupported(String)

    var isSupported: Bool {
        switch self {
        case .arm, .x86, .portable: return true
        case .unsupported: return false
        }
    }

    var selection: [String] {
        switch self {
        case .arm(let level): return bodySelection(neon: level.rawValue, x86: 0, bytes: 16)
        case .x86(let level): return bodySelection(neon: 0, x86: level.rawValue, bytes: level.width)
        case .portable: return bodySelection(neon: 0, x86: 0, bytes: 16)
        case .unsupported(let message): return ["#error \"\(message)\""]
        }
    }
}

struct StaticTargetRule {
    let names: [String]
    var condition: String?
    let support: StaticTargetSupport
}

let armNeonTargets = ["NEON_BF16", "NEON", "NEON_WITHOUT_AES"]
let sveRemedy = "use SVE2 with -msve-vector-bits=128 or \(disablingFlag("HWY_ALL_SVE"))"

let staticTargetRules: [StaticTargetRule] = [
    StaticTargetRule(names: armNeonTargets, condition: "HWY_ARCH_ARM_A64", support: .arm(.neon)),
    StaticTargetRule(
        names: ["SVE2_128"],
        condition: "(!defined(__ARM_FEATURE_SVE_BF16) || !defined(__ARM_FEATURE_SVE_MATMUL_INT8))",
        support: .unsupported(
            "highway's SVE2_128 target needs BF16 and I8MM: add +bf16+i8mm to -march, "
                + "as in -march=armv9-a+bf16+i8mm"
        )
    ),
    StaticTargetRule(names: ["SVE2_128"], support: .arm(.sve2_128)),
    StaticTargetRule(names: ["AVX3"], support: .x86(.avx3)),
    StaticTargetRule(names: ["AVX3_DL", "AVX3_ZEN4", "AVX3_SPR"], support: .x86(.avx3dl)),
    StaticTargetRule(names: ["AVX2"], support: .x86(.avx2)),
    StaticTargetRule(names: ["SSE4"], support: .x86(.sse4)),
    StaticTargetRule(names: ["SSSE3"], support: .x86(.ssse3)),
    StaticTargetRule(names: ["SSE2"], support: .x86(.sse2)),
    StaticTargetRule(names: armNeonTargets, condition: "!HWY_ARCH_ARM_A64", support: .portable),
    StaticTargetRule(
        names: ["PPC8", "PPC9", "PPC10", "Z14", "Z15", "WASM", "LSX", "EMU128"],
        support: .portable
    ),
    StaticTargetRule(
        names: ["AVX10_2"],
        support: .unsupported("the port does not support highway's AVX10_2 target yet")
    ),
    StaticTargetRule(
        names: ["SVE", "SVE2"],
        condition: "!defined(__ARM_FEATURE_SVE_BITS)",
        support: .unsupported("highway sizes SVE vectors at run time: \(sveRemedy)")
    ),
    StaticTargetRule(
        names: ["SVE", "SVE2", "SVE_256"],
        condition: "defined(__ARM_FEATURE_SVE_BITS)",
        support: .unsupported(
            "the port does not support highway's fixed-size SVE targets yet: \(sveRemedy)"
        )
    ),
    StaticTargetRule(
        names: ["RVV"],
        support: .unsupported(
            "highway sizes RVV vectors at run time: use \(disablingFlag("HWY_RVV"))"
        )
