let x86GroupTargets = ["AVX3_SPR", "AVX3_DL", "AVX3", "AVX2", "SSE4", "SSSE3"]

let x86Xcr0Bits = [("XMM", 1), ("YMM", 2), ("OPMASK", 5), ("ZMM_HI", 6), ("REGS32", 7)]

let x86CpuidName = "cvectorization_ops_x86_cpuid"
let x86IsBitSetName = "cvectorization_ops_x86_is_bit_set"
let x86IsAmdName = "cvectorization_ops_x86_is_amd"
let x86ReadXcr0Name = "cvectorization_ops_x86_read_xcr0"
let x86FlagsFromCpuidName = "cvectorization_ops_x86_flags_from_cpuid"
let x86DetectTargetsName = "cvectorization_ops_x86_detect_targets_impl"
let armGetAuxValName = "cvectorization_ops_getauxval"
let armDetectAdditionalSveTargetsName = "cvectorization_ops_arm_detect_additional_sve_targets"
let armDetectTargetsName = "cvectorization_ops_arm_detect_targets_impl"
let hasCpuFeatureName = "cvectorization_ops_has_cpu_feature"
let parseU32Name = "cvectorization_ops_parse_u32"
let isMacOs12_2OrLaterName = "cvectorization_ops_is_mac_os_12_2_or_later"

func x86FeatureMacro(_ feature: String) -> String {
    "CVECTORIZATION_OPS_X86_\(feature)"
}

func x86GroupMacro(_ group: String) -> String {
    "CVECTORIZATION_OPS_X86_GROUP_\(group)"
}

func x86Xcr0Macro(_ bit: String) -> String {
    "CVECTORIZATION_OPS_X86_XCR0_\(bit)"
}

func x86HasXcr0Name(_ registers: String) -> String {
    "cvectorization_ops_x86_has_\(registers)"
}

func x86Xcr0Function(named name: String, mask: String, requiring bits: [String]) -> String {
    let required = bits.map(x86Xcr0Macro).joined(separator: " | ")
    return cFunction(
        returns: "bool",
        name: x86HasXcr0Name(name),
        parameters: ["uint32_t xcr0"],
        body: """
            const uint32_t \(mask) = \(required);
            return (xcr0 & \(mask)) == \(mask);
            """,
        specifiers: "static"
    )
}

func x86FeatureDefinitions() -> String {
    let features = x86CpuFeatures.enumerated().map { index, feature in
        "#define \(x86FeatureMacro(feature)) (1ull << \(index))"
    }
    let groups = x86FeatureGroups.map { group in
        func definition(dropping dropped: [String]) -> String {
            let terms =
                group.features.filter { !dropped.contains($0) }.map(x86FeatureMacro)
                + group.groups.map(x86GroupMacro)
            let value = terms.isEmpty ? "0" : "(\(terms.joined(separator: " | ")))"
            return "#define \(x86GroupMacro(group.name)) \(value)"
        }
        guard let conditional = group.conditional else { return definition(dropping: []) }
        return [
            "#if \(conditional.condition)", definition(dropping: []), "#else",
            definition(dropping: conditional.features), "#endif",
        ].joined(separator: "\n")
    }
    return (features + groups).joined(separator: "\n")
}

func x86FlagsFromCpuidFunction() -> String {
    func reads(_ leaf: X86CpuidLeaf) -> [String] {
        ["\(x86CpuidName)(\(leaf.leaf), \(leaf.subleaf), abcd);"]
            + leaf.flags.map { register, bit, feature in
                "flags |= \(x86IsBitSetName)(abcd[\(register)], \(bit)) ? \(x86FeatureMacro(feature)) : 0;"
            }
    }
    let standard = x86CpuidLeaves.filter { !$0.needsLevel7 }.flatMap(reads)
    let extended = x86CpuidLeaves.filter(\.needsLevel7).flatMap(reads).map { "  \($0)" }
    let body =
        [
            "uint64_t flags = 0;", "uint32_t abcd[4];", "\(x86CpuidName)(0, 0, abcd);",
            "const uint32_t max_level = abcd[0];",
        ] + standard + ["if (max_level >= 7) {"] + extended + ["}", "return flags;"]
    return cFunction(
        returns: "uint64_t",
        name: x86FlagsFromCpuidName,
        parameters: [],
        body: body.joined(separator: "\n"),
        specifiers: "static"
    )
}

func x86DetectTargetsFunction() -> String {
    func groupCheck(_ group: String) -> String {
        "if ((flags & \(x86GroupMacro(group))) == \(x86GroupMacro(group))) {"
    }
    let groupTargets = x86GroupTargets.map { target in
        "\(groupCheck(target))\n  bits |= HWY_\(target);\n}"
    }
    return cFunction(
        returns: "int64_t",
        name: x86DetectTargetsName,
        parameters: [],
        body: """
            int64_t bits = 0;
            if (HWY_ARCH_X86_64) {
              bits |= HWY_SSE2;
            }
            const uint64_t flags = \(x86FlagsFromCpuidName)();
            \(groupTargets.joined(separator: "\n"))
            if (HWY_ARCH_X86_32) {
              \(groupCheck("SSE2"))
                bits |= HWY_SSE2;
              }
            }
            uint32_t abcd[4];
            \(groupCheck("AVX10"))
              \(x86CpuidName)(0x24, 0, abcd);
              const uint32_t avx10_ver = abcd[1] & 0xFFu;
              const bool has_avx10_with_512bit_vectors = (avx10_ver >= 1) && \(x86IsBitSetName)(abcd[1], 18);
              if (has_avx10_with_512bit_vectors) {
                bits |= (HWY_AVX3_SPR | HWY_AVX3_DL | HWY_AVX3);
                if (avx10_ver >= 2) {
                  bits |= HWY_AVX10_2;
                }
              }
            }
            \(x86CpuidName)(1, 0, abcd);
            const bool has_xsave = \(x86IsBitSetName)(abcd[2], 26);
            const bool has_osxsave = \(x86IsBitSetName)(abcd[2], 27);
            const int64_t min_avx2 = HWY_AVX2 | (HWY_AVX2 - 1);
            if (has_xsave && has_osxsave) {
            #if HWY_OS_APPLE
              const bool have_avx3_xsave_support = \(isMacOs12_2OrLaterName)() && \(hasCpuFeatureName)("hw.optional.avx512f");
            #endif
              const uint32_t xcr0 = \(x86ReadXcr0Name)();
              const int64_t min_avx3 = HWY_AVX3 | (HWY_AVX3 - 1);
              if (!\(x86HasXcr0Name("ymm"))(xcr0)) {
                bits &= ~min_avx2;
              }
            #if !HWY_OS_APPLE
              const bool have_avx3_xsave_support = \(x86HasXcr0Name("zmm"))(xcr0);
            #endif
              if (!have_avx3_xsave_support) {
                bits &= ~min_avx3;
              }
            } else {
              bits &= ~min_avx2;
            }
            if ((bits & HWY_AVX3_DL) && (flags & \(x86GroupMacro("AVX3_ZEN4"))) == \(x86GroupMacro("AVX3_ZEN4")) && \(x86IsAmdName)()) {
              bits |= HWY_AVX3_ZEN4;
            }
            return bits;
            """,
        specifiers: "static"
    )
}

func x86TargetDetection() -> String {
    let cpuid = cFunction(
        returns: "void",
        name: x86CpuidName,
        parameters: ["const uint32_t level", "const uint32_t count", "uint32_t* restrict abcd"],
        body: """
            #if HWY_COMPILER_MSVC || HWY_COMPILER_CLANGCL
            int regs[4];
            __cpuidex(regs, (int)level, (int)count);
            for (int i = 0; i < 4; ++i) {
              abcd[i] = (uint32_t)regs[i];
            }
            #else
            uint32_t a;
            uint32_t b;
            uint32_t c;
            uint32_t d;
            __cpuid_count(level, count, a, b, c, d);
            abcd[0] = a;
            abcd[1] = b;
            abcd[2] = c;
            abcd[3] = d;
            #endif
            """,
        specifiers: "static"
    )
    let isBitSet = cFunction(
        returns: "bool",
        name: x86IsBitSetName,
        parameters: ["const uint32_t reg", "const int index"],
        body: "return (reg & (1U << index)) != 0;",
        specifiers: "static"
    )
    let isAmd = cFunction(
        returns: "bool",
        name: x86IsAmdName,
        parameters: [],
        body: """
            uint32_t abcd[4];
            \(x86CpuidName)(0, 0, abcd);
            const uint32_t max_level = abcd[0];
            return max_level >= 1 && abcd[1] == 0x68747541 && abcd[2] == 0x444d4163 && abcd[3] == 0x69746e65;
            """,
        specifiers: "static"
    )
    let parseU32 = cFunction(
        returns: "bool",
        name: parseU32Name,
        parameters: ["const char** ptr", "uint32_t* parsed_val"],
        body: """
            uint64_t parsed_u64 = 0;
            const char* start_ptr = *ptr;
            for (char ch; (ch = (**ptr)) != '\\0'; ++*ptr) {
              unsigned digit = (unsigned)(unsigned char)ch - (unsigned)(unsigned char)'0';
              if (digit > 9u) {
                break;
              }
              parsed_u64 = (parsed_u64 * 10u) + digit;
              if (parsed_u64 > 0xFFFFFFFFu) {
                return false;
              }
            }
            *parsed_val = (uint32_t)parsed_u64;
            return (*ptr != start_ptr);
            """,
        specifiers: "static"
    )
    let isMacOs12_2OrLater = cFunction(
        returns: "bool",
        name: isMacOs12_2OrLaterName,
        parameters: [],
        body: """
            struct utsname uname_buf = {0};
            if (uname(&uname_buf) != 0) {
              return false;
            }
            const char* ptr = uname_buf.release;
            if (!ptr) {
              return false;
            }
            uint32_t major;
            uint32_t minor;
            if (!\(parseU32Name)(&ptr, &major)) {
              return false;
            }
            if (*ptr != '.') {
              return false;
            }
            ++ptr;
            if (!\(parseU32Name)(&ptr, &minor)) {
              return false;
            }
            return (major > 21 || (major == 21 && minor >= 3));
            """,
        specifiers: "static"
    )
    let xcr0Bits = x86Xcr0Bits.map { name, bit in "#define \(x86Xcr0Macro(name)) (1u << \(bit))" }
    let readXcr0 = cFunction(
        returns: "uint32_t",
        name: x86ReadXcr0Name,
        parameters: [],
        body: """
            #if HWY_COMPILER_MSVC
            return (uint32_t)_xgetbv(0);
            #else
            uint32_t xcr0, xcr0_high;
            const uint32_t index = 0;
            __asm__ volatile(".byte 0x0F, 0x01, 0xD0" : "=a"(xcr0), "=d"(xcr0_high) : "c"(index));
            return xcr0;
            #endif
            """,
        specifiers: "static"
    )
    return """
        #if HWY_ARCH_X86 && HWY_HAVE_RUNTIME_DISPATCH
        \(cpuid)\(isBitSet)\(isAmd)#if HWY_OS_APPLE
        \(parseU32)\(isMacOs12_2OrLater)#endif
        \(xcr0Bits.joined(separator: "\n"))
        \(readXcr0)\(x86Xcr0Function(named: "ymm", mask: "xmm_ymm", requiring: ["XMM", "YMM"]))#if !HWY_OS_APPLE
        \(x86Xcr0Function(named: "zmm", mask: "zmm", requiring: ["OPMASK", "ZMM_HI", "REGS32"]))#endif
        \(x86FeatureDefinitions())
        \(x86FlagsFromCpuidFunction())\(x86DetectTargetsFunction())#endif
        """
}

let armHwcap2Fallbacks = [("SVE2", 1), ("SVEAES", 2), ("SVEI8MM", 9), ("SVEBF16", 12)]

let armSveDetectionCondition =
    "(HWY_COMPILER_GCC || HWY_COMPILER_CLANG) && ((HWY_TARGETS & HWY_ALL_SVE) != 0)"

func armTargetDetection() -> String {
    let getAuxVal = cFunction(
        returns: "unsigned long",
        name: armGetAuxValName,
        parameters: ["unsigned long type"],
        body: """
            #if HWY_OS_FREEBSD || HWY_OS_OPENBSD
            unsigned long hwcap = 0;
            switch (type) {
            case AT_HWCAP:
            case AT_HWCAP2:
              if (elf_aux_info((int)type, &hwcap, sizeof(hwcap)) != 0) hwcap = 0;
              return hwcap;
            default:
              return 0;
            }
            #else
            return getauxval(type);
            #endif
            """,
        specifiers: "static"
    )
    let additionalSveTargets = cFunction(
        returns: "int64_t",
        name: armDetectAdditionalSveTargetsName,
        parameters: ["int64_t detected_targets"],
        body: """
            uint64_t sve_vec_len;
            __asm__("cntb %0" : "=r"(sve_vec_len)::);
            return ((sve_vec_len == 32) ? HWY_SVE_256 : (((detected_targets & HWY_SVE2) != 0 && sve_vec_len == 16) ? HWY_SVE2_128 : 0));
            """,
        specifiers: "static __attribute__((target(\"+sve\")))"
    )
    let hwcap2Fallbacks = armHwcap2Fallbacks.map { name, bit in
        "#ifndef HWCAP2_\(name)\n#define HWCAP2_\(name) (1 << \(bit))\n#endif"
    }
    let detectTargets = cFunction(
        returns: "int64_t",
        name: armDetectTargetsName,
        parameters: [],
        body: """
            int64_t bits = 0;
            #if defined(AT_HWCAP) && !HWY_OS_APPLE
            const unsigned long hw = \(armGetAuxValName)(AT_HWCAP);
            #else
            const unsigned long hw = 0UL;
            #endif
            (void)hw;
            #if HWY_ARCH_ARM_A64
            bits |= HWY_NEON_WITHOUT_AES;
            #if HWY_OS_APPLE
            if (\(hasCpuFeatureName)("hw.optional.arm.FEAT_AES")) {
              bits |= HWY_NEON;
              if ((\(hasCpuFeatureName)("hw.optional.AdvSIMD_HPFPCvt") || \(hasCpuFeatureName)("hw.optional.arm.AdvSIMD_HPFPCvt")) && \(hasCpuFeatureName)("hw.optional.arm.FEAT_DotProd") && \(hasCpuFeatureName)("hw.optional.arm.FEAT_BF16") && \(hasCpuFeatureName)("hw.optional.arm.FEAT_I8MM")) {
                bits |= HWY_NEON_BF16;
              }
            }
            #else
            #if defined(HWCAP_AES)
            if (hw & HWCAP_AES) {
              bits |= HWY_NEON;
            #if defined(AT_HWCAP2) && defined(HWCAP_ASIMDHP) && defined(HWCAP_ASIMDDP) && defined(HWCAP2_BF16)
              const unsigned long hw2 = \(armGetAuxValName)(AT_HWCAP2);
              const unsigned long group_f16_dot = HWCAP_ASIMDHP | HWCAP_ASIMDDP;
              const unsigned long group_bf16 = HWCAP2_BF16;
              if ((hw & group_f16_dot) == group_f16_dot && (hw2 & group_bf16) == group_bf16) {
                bits |= HWY_NEON_BF16;
              }
            #endif
            }
            #endif
            #if defined(HWCAP_SVE)
            if (hw & HWCAP_SVE) {
              bits |= HWY_SVE;
            }
            #endif
            \(hwcap2Fallbacks.joined(separator: "\n"))
            const unsigned long group_sve2 = HWCAP2_SVE2 | HWCAP2_SVEAES;
            #if defined(AT_HWCAP2)
            const unsigned long hw2 = \(armGetAuxValName)(AT_HWCAP2);
            #else
            const unsigned long hw2 = 0UL;
            #endif
            if ((hw2 & group_sve2) == group_sve2) {
              bits |= HWY_SVE2;
            }
            #if \(armSveDetectionCondition)
            if ((bits & HWY_ALL_SVE) != 0) {
              bits |= \(armDetectAdditionalSveTargetsName)(bits);
              const unsigned long group_sve2_128 = HWCAP2_SVEI8MM | HWCAP2_SVEBF16;
              if ((hw2 & group_sve2_128) != group_sve2_128) {
                bits &= ~HWY_SVE2_128;
              }
            }
            #endif
            #endif
            #else
            #if defined(HWCAP_NEON) && defined(HWCAP_VFPv4)
            if ((hw & HWCAP_NEON) && (hw & HWCAP_VFPv4)) {
              bits |= HWY_NEON_WITHOUT_AES;
            }
            #endif
            #endif
            return bits;
            """,
        specifiers: "static"
    )
    return """
        #if HWY_ARCH_ARM && HWY_HAVE_RUNTIME_DISPATCH
        #if !HWY_OS_APPLE
        \(getAuxVal)#endif
        #if HWY_ARCH_ARM_A64 && !HWY_OS_APPLE && \(armSveDetectionCondition)
        \(additionalSveTargets)#endif
        \(detectTargets)#endif
        """
}

func generateSupportedTargetsSource() -> String {
    let hasCpuFeature = cFunction(
        returns: "bool",
        name: hasCpuFeatureName,
        parameters: ["const char* feature_name"],
        body: """
            int result = 0;
            size_t len = sizeof(int);
            return (sysctlbyname(feature_name, &result, &len, NULL, 0) == 0 && result != 0);
            """,
        specifiers: "static"
    )
    let supportedTargets = cFunction(
        returns: "int64_t",
        name: supportedTargetsFunctionName,
        parameters: [],
        body: """
            int64_t bits = HWY_SCALAR | HWY_EMU128;
            #if HWY_ARCH_X86 && HWY_HAVE_RUNTIME_DISPATCH
            bits |= \(x86DetectTargetsName)();
            #elif HWY_ARCH_ARM && HWY_HAVE_RUNTIME_DISPATCH
            bits |= \(armDetectTargetsName)();
            #else
            bits |= HWY_ENABLED_BASELINE;
            #endif
            return bits;
            """,
        specifiers: ""
    )
    return """
        \(generationNotice)

        #include "include/CVectorizationOps.h"

        #if HWY_ARCH_X86 && HWY_HAVE_RUNTIME_DISPATCH
        #if HWY_COMPILER_MSVC || HWY_COMPILER_CLANGCL
        #include <intrin.h>
        #else
        #include <cpuid.h>
        #endif
        #endif

        #if HWY_ARCH_ARM && HWY_OS_LINUX
        #if HWY_HAVE_ASM_HWCAP
        #include <asm/hwcap.h>
        #endif
        #if HWY_HAVE_AUXV
        #include <sys/auxv.h>
        #endif
        #elif HWY_ARCH_ARM && (HWY_OS_FREEBSD || HWY_OS_OPENBSD)
        #if HWY_HAVE_ELF_AUX_INFO
        #include <sys/auxv.h>
        #endif
        #endif

        #if HWY_OS_APPLE
        #include <sys/sysctl.h>
        #include <sys/utsname.h>
        #endif

        \(targetSetAssertions())

        #if HWY_OS_APPLE && HWY_HAVE_RUNTIME_DISPATCH && (HWY_ARCH_X86 || HWY_ARCH_ARM_A64)
        \(hasCpuFeature)#endif

        \(x86TargetDetection())

        \(armTargetDetection())

        \(supportedTargets)
        """
}

func tupleTypedefs(of element: Element) -> String {
    let member = element.cTupleVector
    let structs = (2...4).map { count in
        let members = (0..<count).map { "\(member) v\($0);" }
        return "typedef struct { \(members.joined(separator: " ")) } \(element.cTuple(count));"
    }
    let alignment = "typedef \(element.cRawVector) \(member) __attribute__((aligned(16)));"
    return ([alignment] + structs).joined(separator: "\n")
}

func narrowShapes(of element: Element) -> [Shape] {
    Shape.allCases.filter { $0 != .full && element.supports($0) }
}

func narrowTypedefs(of element: Element) -> String {
    narrowShapes(of: element).map { shape in
        guard let fraction = shape.fraction else {
            return "typedef \(element.cBlock) \(element.cRawVector(of: shape));"
        }
        let bytes = "CVECTORIZATION_OPS_VECTOR_BYTES / \(fraction)"
        let register = "CVECTORIZATION_OPS_PARTIAL_REGISTER_BYTES(\(bytes))"
        return """
            typedef \(element.cType) \(element.cVector(of: shape)) __attribute__((vector_size(\(bytes))));
            typedef \(element.cType) \(element.cRawVector(of: shape)) __attribute__((vector_size(\(register))));
            typedef \(element.cMaskLane) \(element.cMask(of: shape)) __attribute__((vector_size(\(bytes))));
            typedef \(element.cMaskLane) \(element.cRawMask(of: shape)) __attribute__((vector_size(\(register))));
            """
    }.joined(separator: "\n")
}

func cNarrowRawConversion(
    simd: String,
    raw: String,
    toRaw: String,
    fromRaw: String
) -> String {
    cFunction(
        returns: raw,
        name: toRaw,
        parameters: ["\(simd) v"],
        body: "\(raw) result;\n__builtin_memcpy(&result, &v, sizeof v);\nreturn result;"
    )
        + cFunction(
            returns: simd,
            name: fromRaw,
            parameters: ["\(raw) v"],
            body: "\(simd) result;\n__builtin_memcpy(&result, &v, sizeof result);\nreturn result;"
        )
}

func cNarrowRawConversions(of element: Element) -> String {
    narrowShapes(of: element).map { shape in
        cNarrowRawConversion(
            simd: element.cVector(of: shape),
            raw: element.cRawVector(of: shape),
            toRaw: element.cToRawVector(of: shape),
            fromRaw: element.cFromRawVector(of: shape)
        )
            + (shape.hasMask
                ? cNarrowRawConversion(
                    simd: element.cMask(of: shape),
                    raw: element.cRawMask(of: shape),
                    toRaw: element.cToRawMask(of: shape),
                    fromRaw: element.cFromRawMask(of: shape)
                ) : "")
    }.joined()
}

func halfPrecisionTuple(_ name: String, count: Int, to element: Element) -> String {
    let members = (0..<count).map { "(\(element.cTupleVector))\(name).v\($0)" }
    return "(\(element.cTuple(count))){\(members.joined(separator: ", "))}"
}

func halfPrecisionDelegate(of op: Op, for element: Element) -> Element {
    let delegate =
        signedHalfPrecisionDelegations.contains(op.identifier)
        ? signedElement(of: element) : unsignedElement(of: element)
    return delegate.at(width: element.width)
}

func halfPrecisionCall(
    of op: Op,
    for element: Element,
    callee: (Element) -> String,
    declaration: (Binding) -> String
) -> String {
    let delegate = halfPrecisionDelegate(of: op, for: element)
    let arguments = zip(
        zip(bindings(of: op, for: element), bindings(of: op, for: delegate)),
        op.parameters
    ).compactMap { bindingPair, parameter -> String? in
        let (binding, delegated) = bindingPair
        let text = declaration(binding)
        guard !text.isEmpty else { return nil }
        let name = text.split(separator: " ").last.map(String.init) ?? ""
        if case .tuple(let count) = parameter {
            return halfPrecisionTuple(name, count: count, to: delegate)
        }
        let type = String(text.dropLast(name.count + 1))
        let delegatedType = String(declaration(delegated).dropLast(name.count + 1))
        return type == delegatedType ? name : "(\(delegatedType))\(name)"
    }
    let call = "\(callee(delegate))(\(arguments.joined(separator: ", ")))"
    let returnType = cReturnType(op.returns, element)
    switch op.returns {
    case .void: return "\(call);"
    case .tuple(let count):
        return """
            const \(cReturnType(op.returns, delegate)) result = \(call);
            return \(halfPrecisionTuple("result", count: count, to: element));
            """
    default:
        return returnType == cReturnType(op.returns, delegate)
            ? "return \(call);" : "return (\(returnType))\(call);"
    }
}

func halfPrecisionComposition(of op: Op, for element: Element, declarations: String) -> String {
    let specifier =
        op.outOfLineOnSVE?.matches(element) == true
        ? "SWIFT_HIGHWAY_REFERENCE_OPERAND_ORDERED" : "HWY_INLINE"
    func definition(named name: (Element) -> String) -> String {
        let body =
            float16ReferenceCompositions[op.identifier]?(
                bindings(of: op, for: element).map(\.argument).filter { !$0.isEmpty }
            )
            ?? halfPrecisionCall(
                of: op,
                for: element,
                callee: name,
                declaration: \.declaration
            )
        return "\(specifier) \(cReturnType(op.returns, element)) "
            + "\(name(element))(\(declarations)) { \(body) }\n"
    }
    let template = op.template == nil ? "" : definition { templateReferenceName(of: op, for: $0) }
    return definition { referenceFunctionName(of: op, for: $0) } + template
}

func halfPrecisionBody(of op: Op, for element: Element) -> String? {
    guard element.isHalfPrecision, let body = halfPrecisionBodies[op.identifier] else { return nil }
    return cBody(
        halfPrecisionTargetBodies[op.identifier] ?? TargetBodies(),
        for: element,
        portable: body
    )
}

func halfPrecisionDelegation(
    of op: Op,
    for element: Element,
    spanned: Bool = false
) -> String? {
    guard
        element.isHalfPrecision, bitwiseHalfPrecisionOps[op.identifier] != nil,
        halfPrecisionBodies[op.identifier] == nil
    else { return nil }
    return halfPrecisionCall(
        of: op,
        for: element,
        callee: {
            spanned ? cFunctionName(op.identifier + "Span", $0) : cFunctionName(of: op, for: $0)
        },
        declaration: \.cDeclaration
    )
}

func cOpFunctions(of op: Op, for element: Element) -> String {
    var output = ""
    let parameters =
        bindings(of: op, for: element)
        .filter { !$0.cDeclaration.isEmpty }
        .map(\.cDeclaration)
    let delegation = halfPrecisionDelegation(of: op, for: element)
    if delegation == nil {
        output += cHelpers(of: op, for: element)
    }
    output += cOpFunction(
        returns: op.returns,
        name: cFunctionName(of: op, for: element),
        parameters: parameters,
        prologue: delegation == nil ? cPrologue(of: op, for: element) : [],
        body: delegation ?? halfPrecisionBody(of: op, for: element)
            ?? cBody(of: op, for: element),
        for: element
    )
    if !op.spanTargets.isEmpty {
        let arguments = parameters.map { String($0.split(separator: " ").last ?? "") }
        let call =
            "\(cFunctionName(of: op, for: element))(\(arguments.joined(separator: ", ")))"
        output += cOpFunction(
            returns: op.returns,
            name: cFunctionName(op.identifier + "Span", element),
            parameters: parameters,
            prologue: delegation == nil ? cPrologue(of: op, for: element) : [],
            body: halfPrecisionDelegation(of: op, for: element, spanned: true)
                ?? cBody(op.spanTargets, for: element, portable: { _ in "return \(call);" }),
            for: element
        )
    }
    return output
}

func generateHeader() -> String {
    var output = """
        \(generationNotice)

        #ifndef SWIFT_VECTORIZATION_OPS_H
        #define SWIFT_VECTORIZATION_OPS_H

        #include <stdbool.h>
        #include <stddef.h>
        #include <stdint.h>
        #include "../vendor/detect_targets.h"

        #ifdef __cplusplus
        extern "C" {
        #endif

        #if defined(CVECTORIZATION_OPS_EXTERNAL_DEFINITIONS)
        #define CVECTORIZATION_OPS_INLINE extern inline __attribute__((always_inline)) CVECTORIZATION_OPS_VECTOR_WIDTH
        #define CVECTORIZATION_OPS_FUNCTION extern inline
        #else
        #define CVECTORIZATION_OPS_INLINE inline __attribute__((always_inline)) CVECTORIZATION_OPS_VECTOR_WIDTH
        #define CVECTORIZATION_OPS_FUNCTION inline
        #endif

        \(staticTargetSelection())

        #if CVECTORIZATION_OPS_VECTOR_BYTES == \(X86Level.avx3.width)
        #define CVECTORIZATION_OPS_VECTOR_WIDTH __attribute__((min_vector_width(\(X86Level.avx3.width * 8))))
        #else
        #define CVECTORIZATION_OPS_VECTOR_WIDTH
        #endif

        #if CVECTORIZATION_OPS_NEON
        #define CVECTORIZATION_OPS_PARTIAL_REGISTER_BYTES(bytes) 8
        #else
        #define CVECTORIZATION_OPS_PARTIAL_REGISTER_BYTES(bytes) ((bytes) < 16 ? 16 : (bytes))
        #endif

        \(rawVectorDeclarations())

        \(x86Helpers())

        \(neonHelpers())

        \(resizeHelpers())

        /// Whether the target only emulates vectors, in which case a caller is better off
        /// with its own scalar code.
        \(emulatedFunction())
        /// The name of the target the ops below were compiled for.
        \(targetNameFunction())
        \(targetFunction())
        \(supportedTargetsDeclaration())
        \(targetCapabilityFunctions())
        \(setMaskFunction())
        \(cacheControlFunctions())
        """

    for element in elements {
        output += """
            \(vectorTypedef(of: element))
            typedef \(element.cMaskLane) \(element.cMask) __attribute__((vector_size(CVECTORIZATION_OPS_VECTOR_BYTES)));
            typedef \(element.cType) \(element.cBlock) __attribute__((vector_size(16)));
            #if CVECTORIZATION_OPS_X86
            typedef \(x86RawType(of: element)) \(element.cRawVector);
            typedef \(x86RawType(of: element)) \(element.cRawMask);
            #else
            typedef \(element.cVector) \(element.cRawVector);
            typedef \(element.cMask) \(element.cRawMask);
            #endif
            \(tupleTypedefs(of: element))
            \(narrowTypedefs(of: element))

            """
    }

    for element in elements {
        output += cFunction(
            returns: "size_t",
            name: cFunctionName("laneCount", element),
            parameters: [],
            body: "return sizeof(\(element.cVector)) / sizeof(\(element.cType));"
        )
        output += cFunction(
            returns: "size_t",
            name: cFunctionName("blockCount", element),
            parameters: [],
            body: "return sizeof(\(element.cVector)) / 16;"
        )
        output += cRawConversions(of: element)
        output += cNarrowRawConversions(of: element)
        for capability in laneCapabilities where capability.applies.matches(element) {
            output += cFunction(
                returns: "bool",
                name: cFunctionName(capability.name, element),
                parameters: [],
                body: capability.body(for: element)
            )
        }
        if element.category != .float {
            output += indicesWithinFunction(perByte: false, for: element)
            if element.bits > 8 {
                output += indicesWithinFunction(perByte: true, for: element)
            }
        }
        if element.bits >= 32 {
            output += indicesWithinWhereFunction(gathering: true, for: element)
            output += indicesWithinWhereFunction(gathering: false, for: element)
        }
        output += sveConstantFunction(for: element)
        if element.category == .float || element.category == .float16 {
            output += constantNaNFunction(for: element)
            output += sveConstantNumbersFunction(for: element)
            output += constantLaneFunction(for: element)
        }
        output += sveSplatFunction(for: element)

        for op in ops
        where op.source == nil && op.applies.matches(element)
            && !followsConversions(op, for: element)
        {
            output += cOpFunctions(of: op, for: element)
        }

        let pairs = wideningPairs(definedIn: element)
        for pair in pairs {
            let promotion = cBody(
                x86PromotionHelpers(from: pair.narrow),
                for: pair.wide,
                portable: nil
            )
            output += "\(promotion)\n"
        }

        for op in wideningOps {
            for pair in pairs {
                let countParameters = op.takesCount ? ["size_t count"] : []
                output += cOpFunction(
                    returns: .vector,
                    name: cWideningFunctionName(op, from: pair.narrow, to: pair.wide),
                    parameters: ["const \(pair.narrow.cType)* from"] + countParameters,
                    body: cBody(of: op, from: pair.narrow, to: pair.wide),
                    for: pair.wide
                )
            }
        }

        for op in rebindingOps {
            for pair in rebindingPairs(definedIn: element) {
                output += cFunction(
                    returns: pair.target.cRawMask,
                    name: cRebindingFunctionName(op, from: pair.source, to: pair.target),
                    parameters: ["\(pair.source.cRawMask) mask"],
                    body: "return (\(pair.target.cRawMask))mask;"
                )
            }
        }

        output += cOpFunction(
            returns: .vector,
            name: cFunctionName(repeatingBlockName, element),
            parameters: repeatingBlockLanes(of: element).map { "\(element.cScalar) \($0)" },
            body: element.isHalfPrecision
                ? halfPrecisionRepeatingBlock(for: element)
                : cBody(TargetBodies(), for: element, portable: repeatingBlockBody),
            for: element
        )
        output += "\n"
    }

    for op in ops where op.source != nil {
        for element in elements where op.applies.matches(element) {
            output += cOpFunctions(of: op, for: element)
        }
    }

    for op in ops where op.source == nil && op.applies.matches(float16) {
        if followsConversions(op, for: float16) {
            output += cOpFunctions(of: op, for: float16)
        }
    }

    output += """
        #ifdef __cplusplus
        }
        #endif

        #endif

        """
    return output
}

func swiftArgument(
    _ binding: Binding,
    _ parameter: Parameter,
    for element: Element,
    source: Element? = nil
) -> String {
    switch parameter {
    case .tag, .sourceTag, .narrowTag, .sourceNarrowTag: return ""
    case .shiftAmount, .immediate: return "Int32(truncatingIfNeeded: \(binding.swiftName))"
    default: return rawArgument(binding.swiftName, parameter, for: element, source: source)
    }
}

func rawArgument(
    _ name: String,
    _ parameter: Parameter,
    for element: Element,
    source: Element? = nil
) -> String {
    switch parameter {
    case .vector, .shiftCounts, .indices, .laneIndices, .lookupIndices, .indexVector, .fillVector,
        .otherwiseVector, .pointerIndices, .pointerOffsets, .sourceVector, .signedSourceVector:
        let operand = operandElement(of: parameter, for: element, source: source)
        return operand.hasOpaqueVector ? "\(name).raw" : name
    case .mask, .whereMask, .sourceMask, .narrowVector, .sourceNarrowVector, .narrowMask,
        .sourceNarrowMask:
        return "\(name).raw"
    case .lane, .insertedLane, .fillLane: return element.swiftScalarArgument(name)
    case .outVector: return element.hasOpaqueVector ? "&\(name).raw" : "&\(name)"
    case .tuple(let count):
        let members = (0..<count).map { member in
            "v\(member): \(element.hasOpaqueVector ? "\(name).\(member).raw" : "\(name).\(member)")"
        }
        return "\(element.cTuple(count))(\(members.joined(separator: ", ")))"
    default: return name
    }
}

func vectorFromRaw(_ call: String, of element: Element) -> String {
    element.hasOpaqueVector ? "Vector(raw: \(call))" : call
}

func importedType(
    of parameter: Parameter,
    for element: Element,
    narrow: Element? = nil,
    source: Element? = nil
) -> String {
    switch parameter {
    case .narrowLanePointer: return "UnsafeMutablePointer<\(narrow?.swiftType ?? "")>"
    case .tag, .sourceTag, .narrowTag, .sourceNarrowTag: return ""
    case .narrowVector, .sourceNarrowVector:
        let operand = operandElement(of: parameter, for: element, source: source)
        return "\(operand.namespace).\(parameter.shape.swiftVector)"
    case .vector, .shiftCounts, .indices, .laneIndices, .lookupIndices, .indexVector, .outVector,
        .fillVector, .otherwiseVector, .pointerIndices, .pointerOffsets, .sourceVector,
        .signedSourceVector:
        let operand = operandElement(of: parameter, for: element, source: source)
        return "\(operand.namespace).Vector"
    case .mask, .whereMask, .sourceMask:
        let operand = operandElement(of: parameter, for: element, source: source)
        return "\(operand.namespace).Mask"
    case .narrowMask, .sourceNarrowMask:
        let operand = operandElement(of: parameter, for: element, source: source)
        return "\(operand.namespace).\(parameter.shape.swiftMask)"
    case .lane, .fillLane, .insertedLane: return element.swiftType
    case .tuple(let count): return tupleType("\(element.namespace).Vector", count: count)
    case .constLanePointer: return "UnsafePointer<\(element.swiftType)>"
    case .lanePointer: return "UnsafeMutablePointer<\(element.swiftType)>"
    case .constBytePointer, .constBitsPointer: return "UnsafePointer<UInt8>"
    case .constIndexPointer: return "UnsafePointer<\(laneIndexElement(of: element).swiftType)>"
    case .bytePointer: return "UnsafeMutablePointer<UInt8>"
    case .flag: return "Bool"
    case .maskBits: return "UInt"
    case .count, .laneAmount, .laneIndex, .tupleIndex: return "Int"
    case .shiftAmount, .immediate: return "Int32"
    case .roundConstant: return "UInt8"
    }
}

func swiftDeclaration(_ binding: Binding, as type: String? = nil) -> String {
    let label = binding.swiftLabel ?? binding.swiftName
    let inoutKeyword = binding.isInOut ? "inout " : ""
    let naming =
        label == binding.swiftName
        ? binding.swiftName
        : "\(label) \(binding.swiftName)"
    return "\(naming): \(inoutKeyword)\(type ?? binding.swiftType)"
}

/// How a Swift call passes `binding`, or `expression` in its place, on to a function that has the
/// same parameter.
func swiftCallArgument(_ binding: Binding, passing expression: String? = nil) -> String {
    let label = binding.swiftLabel ?? binding.swiftName
    let operand = expression ?? binding.swiftName
    let value = binding.isInOut ? "&\(operand)" : operand
    return label == "_" ? value : "\(label): \(value)"
}

func swiftSignature(
    of op: Op,
    for element: Element,
    checked: Bool = true
) -> (parameters: String, arguments: String) {
    let parameterBindings = bindings(of: op, for: element, checked: checked)
    var declarations: [String] = []
    var arguments: [String] = []

    for (binding, parameter) in zip(parameterBindings, op.parameters) {
        if parameter.isTag { continue }
        declarations.append(swiftDeclaration(binding))
        arguments.append(swiftArgument(binding, parameter, for: element, source: op.source))
    }

    return (
        op.swiftOrdered(declarations).joined(separator: ", "), arguments.joined(separator: ", ")
    )
}

/// An op that takes a pointer is the only kind whose call is an unsafe construct, so only those
/// acknowledge it, rather than the package turning the diagnostic down for every op.
func isUnsafe(_ op: Op) -> Bool {
    op.parameters.contains(where: \.isPointer)
}

func swiftBody(of op: Op, for element: Element, arguments: String, spanned: Bool = false) -> String
{
    let keyword = isUnsafe(op) || op.parameters.contains(.outVector) ? "unsafe " : ""
    let function =
        spanned && !op.spanTargets.isEmpty
        ? cFunctionName(op.identifier + "Span", element) : cFunctionName(of: op, for: element)
    let call = "\(keyword)\(function)(\(arguments))"
    switch op.returns {
    case .count, .index: return "Int(\(call))"
    case .vector: return vectorFromRaw(call, of: element)
    case .laneIndices: return "Indices(raw: \(call))"
    case .mask: return "Mask(raw: \(call))"
    case .lane: return element.swiftScalarResult(call)
    case .indices: return "Indices(raw: \(call))"
    case .tuple(let count):
        let members = (0..<count).map { vectorFromRaw("tuple.v\($0)", of: element) }
        return "{ tuple in (\(members.joined(separator: ", "))) }(\(call))"
    case .narrowVector(let shape): return "\(shape.swiftVector)(raw: \(call))"
    case .narrowMask(let shape): return "\(shape.swiftMask)(raw: \(call))"
    default: return call
    }
}

// `Span` needs newer OSes than the macOS 10.13 and iOS 12.0 SwiftPM 6.3 builds for by default.
let spanAvailability = "@available(SwiftStdlib 5.1, *)"

// A span that a span form takes where an op takes a pointer. Its label differs between the forms
// of an op. An op with several pointers names each span after its label.
struct SpanArgument {
    let label: String
    var name = "span"
    let element: String
    let isMutable: Bool
    let extent: SpanExtent
}

// A Swift parameter of a span form.
enum SpanParameter {
    case span(SpanArgument)
    case other(declaration: String, argument: String)
}

// A pointer op as its span forms see it, so that an `Op` and a `WideningOp` get the same ones.
// `bridgeCall` calls the bridge with the given pointers, one per span, and the given count if it
// takes one. `count` makes that count of the buffers of the spans, named as the given strings.
struct SpanForms {
    let name: String
    let parameters: [SpanParameter]
    let returns: ReturnType
    var count: (_ buffers: [String]) -> String = { "\($0[0]).count" }
    var checks: [Check] = []
    var appendsToOutput = true
    var bridgeCall: (_ pointers: [String], _ count: String) -> String

    var spans: [SpanArgument] {
        parameters.compactMap { parameter in
            if case .span(let span) = parameter { span } else { nil }
        }
    }

    var isMutable: Bool {
        spans.contains(where: \.isMutable)
    }

    var extent: SpanExtent {
        spans[0].extent
    }

    var element: String {
        spans[0].element
    }

    var takesCountFromSpans: Bool {
        spans.allSatisfy { if case .first = $0.extent { true } else { false } }
    }
}

func spanElement(of parameter: Parameter, for element: Element, narrow: Element? = nil) -> String {
    if parameter == .narrowLanePointer, let narrow { return narrow.swiftType }
    if parameter.isBytePointer { return "UInt8" }
    if parameter == .constIndexPointer { return laneIndexElement(of: element).swiftType }
    return "Lane"
}

func spanForms(of op: Op, for element: Element) -> SpanForms? {
    guard let extent = op.span else { return nil }
    let parameterBindings = bindings(of: op, for: element)
    let takesCountFromSpan = if case .first = extent { true } else { false }
    let hasSeveralSpans = op.parameters.filter(\.isPointer).count > 1

    var parameters: [SpanParameter?] = []
    for (binding, parameter) in zip(parameterBindings, op.parameters) {
        switch parameter {
        case .tag, .sourceTag, .narrowTag, .sourceNarrowTag:
            continue
        case .count where takesCountFromSpan:
            parameters.append(nil)
        case _ where parameter.isPointer:
            let label = binding.swiftLabel ?? binding.swiftName
            parameters.append(
                .span(
                    SpanArgument(
                        label: label,
                        name: hasSeveralSpans ? label : "span",
                        element: spanElement(of: parameter, for: element, narrow: op.narrowElement),
                        isMutable: parameter.isMutablePointer,
                        extent: parameter.isBytePointer ? .maskBytes : extent
                    )
                )
            )
        default:
            parameters.append(
                .other(declaration: swiftDeclaration(binding), argument: swiftCallArgument(binding))
            )
        }
    }

    var forms = SpanForms(
        name: op.swiftName,
        parameters: op.swiftOrdered(parameters).compactMap { $0 },
        returns: op.returns,
        checks: spanOpChecks(of: op, for: element),
        appendsToOutput: op.appendsToOutputSpan,
        bridgeCall: { pointers, count in
            var remaining = pointers.makeIterator()
            var arguments: [String] = []
            for (binding, parameter) in zip(parameterBindings, op.parameters) {
                switch parameter {
                case .tag, .sourceTag, .narrowTag, .sourceNarrowTag:
                    continue
                case .count where takesCountFromSpan:
                    arguments.append(count)
                case _ where parameter.isPointer:
                    arguments.append(remaining.next() ?? "")
                default:
                    arguments.append(swiftArgument(binding, parameter, for: element))
                }
            }
            return swiftBody(
                of: op,
                for: element,
                arguments: arguments.joined(separator: ", "),
                spanned: true
            )
        }
    )
    if op.clampsSpanCount || (hasSeveralSpans && takesCountFromSpan) {
        forms.count = { buffers in
            let counts = buffers.map { "\($0).count" } + (op.clampsSpanCount ? ["laneCount"] : [])
            return counts.count == 1 ? counts[0] : "Swift.min(\(counts.joined(separator: ", ")))"
        }
    }
    return forms
}

func spanForms(of op: WideningOp, from narrow: Element, to wide: Element) -> SpanForms {
    let function = cWideningFunctionName(op, from: narrow, to: wide)
    return SpanForms(
        name: op.swiftName,
        parameters: [
            .span(
                SpanArgument(
                    label: "from",
                    element: narrow.swiftType,
                    isMutable: false,
                    extent: op.span
                )
            )
        ],
        returns: .vector,
        bridgeCall: { pointers, count in
            let countArgument = op.takesCount ? ", \(count)" : ""
            return vectorFromRaw("unsafe \(function)(\(pointers[0])\(countArgument))", of: wide)
        }
    )
}

func checkedLabel(_ label: String, checked: Bool) -> String {
    checked ? label : "\(label)Unchecked"
}

func spanDeclaration(_ span: SpanArgument, checked: Bool) -> (declaration: String, argument: String)
{
    let label = checkedLabel(span.label, checked: checked)
    let naming = label == span.name ? label : "\(label) \(span.name)"
    let type = span.isMutable ? "inout MutableSpan<\(span.element)>" : "Span<\(span.element)>"
    return ("\(naming): \(type)", "\(label): \(span.isMutable ? "&" : "")\(span.name)")
}

func spanSignature(_ forms: SpanForms, checked: Bool) -> (parameters: String, arguments: String) {
    var declarations: [String] = []
    var arguments: [String] = []
    for parameter in forms.parameters {
        switch parameter {
        case .span(let span):
            let spanDeclaration = spanDeclaration(span, checked: checked)
            declarations.append(spanDeclaration.declaration)
            arguments.append(spanDeclaration.argument)
        case .other(let declaration, let argument):
            declarations.append(declaration)
            arguments.append(argument)
        }
    }
    return (declarations.joined(separator: ", "), arguments.joined(separator: ", "))
}

typealias Check = (condition: String, message: String)

/// What a span form checks before it touches `count` vectors' worth of lanes, each as a Swift
/// condition and the message for when it fails.
func spanChecks(vectors count: Int, aligned: Bool, of span: String = "span") -> [Check] {
    var checks = [
        count > 1
            ? (
                "\(span).count >= \(count) * laneCount",
                "Span has fewer elements than \(count) vectors have lanes"
            )
            : ("\(span).count >= laneCount", "Span has fewer elements than a vector has lanes")
    ]
    if aligned {
        checks.append(
            (
                "\(span).withUnsafeBufferPointer { UInt(bitPattern: $0.baseAddress) "
                    + "% UInt(laneCount * MemoryLayout<Lane>.stride) == 0 }",
                "Span does not start at an address aligned to the vector size"
            )
        )
    }
    return checks
}

/// What a span form checks before it touches the `lanes` of a table, each as a Swift condition and
/// the message for when it fails. The span must start at an address aligned to the table's size.
func spanChecks(table lanes: Int, of span: String = "span") -> [Check] {
    [
        ("\(span).count >= \(lanes)", "Span has fewer elements than the table has lanes"),
        (
            "\(span).withUnsafeBufferPointer { UInt(bitPattern: $0.baseAddress) "
                + "% UInt(\(lanes) * MemoryLayout<Lane>.stride) == 0 }",
            "Span does not start at an address aligned to the table size"
        ),
    ]
}

/// What a span form checks before it touches the bytes of a mask's bits, each as a Swift condition
/// and the message for when it fails.
func spanChecks(maskBytes: Void, of span: String = "span") -> [Check] {
    [("\(span).count >= (laneCount + 7) / 8", "Span has fewer bytes than a mask has bits")]
}

/// A checked member that traps when any of `checks` fails, and the `@unsafe` unchecked member it
/// calls, which only asserts them, like `Span`'s `subscript(_:)` and `subscript(unchecked:)`.
func checkedMembers(
    _ name: String,
    availability: String? = nil,
    checked: String,
    unchecked: (parameters: String, arguments: String),
    returnClause: String,
    checks: [Check],
    uncheckedBody: String
) -> String {
    let returnKeyword = returnClause.isEmpty ? "" : "return "
    let attributes = availability.map { "\($0)\n" } ?? ""
    let preconditions = checks.map { "precondition(\($0.condition), \"\($0.message)\")" }
    let assertions = checks.map { "assert(\($0.condition), \"\($0.message)\")" }
    return """
            \(attributes)@export(implementation) @inline(always)
            public static func \(name)(\(checked))\(returnClause) {
                \(preconditions.joined(separator: "\n"))
                \(returnKeyword)unsafe \(name)(\(unchecked.arguments))
            }

            \(attributes)@unsafe @export(implementation) @inline(always)
            public static func \(name)(\(unchecked.parameters))\(returnClause) {
                \(assertions.joined(separator: "\n"))
                \(uncheckedBody)
            }


        """
}

func partialExtentLanes(_ extent: SpanExtent?, prefix: String = "") -> String {
    switch extent {
    case .halfVector?: return "\(prefix)laneCount / 2"
    case .quarterVector?: return "\(prefix)laneCount / 4"
    case .eighthVector?: return "\(prefix)laneCount / 8"
    default: fatalError("\(String(describing: extent)) is not a part of a vector")
    }
}

func partialExtentName(_ extent: SpanExtent) -> String {
    switch extent {
    case .halfVector: return "half a vector"
    case .quarterVector: return "a quarter of a vector"
    case .eighthVector: return "an eighth of a vector"
    default: fatalError("\(extent) is not a part of a vector")
    }
}

func spanChecks(of span: SpanArgument) -> [Check] {
    switch span.extent {
    case .first:
        return []
    case .vectors(let count, let aligned):
        return spanChecks(vectors: count, aligned: aligned, of: span.name)
    case .table(let lanes):
        return spanChecks(table: lanes, of: span.name)
    case .maskBytes:
        return spanChecks(maskBytes: (), of: span.name)
    case .block:
        return [
            (
                "\(span.name).count >= 16 / MemoryLayout<Lane>.stride",
                "Span has fewer elements than a block has lanes"
            )
        ]
    case .halfVector:
        return [
            (
                "\(span.name).count >= laneCount / 2",
                "Span has fewer elements than half a vector has lanes"
            )
        ]
    case .quarterVector:
        return [
            (
                "\(span.name).count >= laneCount / 4",
                "Span has fewer elements than a quarter of a vector has lanes"
            )
        ]
    case .eighthVector:
        return [
            (
                "\(span.name).count >= laneCount / 8",
                "Span has fewer elements than an eighth of a vector has lanes"
            )
        ]
    case .gathered:
        return []
    }
}

func bufferAccessor(of span: SpanArgument) -> String {
    span.isMutable ? "withUnsafeMutableBufferPointer" : "withUnsafeBufferPointer"
}

/// `body` inside the closures that give it the buffers of `spans`: `$0` for a single span, and
/// otherwise one named after each span, nested in the order of the spans.
func bufferClosures(_ spans: [SpanArgument], body: (_ buffers: [String]) -> String) -> String {
    if spans.count == 1 {
        return "\(spans[0].name).\(bufferAccessor(of: spans[0])) {\n\(body(["$0"]))\n}"
    }
    let buffers = spans.map { "\($0.name)Buffer" }
    var closures = body(buffers)
    for (span, buffer) in zip(spans, buffers).reversed() {
        closures = "\(span.name).\(bufferAccessor(of: span)) { \(buffer) in\n\(closures)\n}"
    }
    return closures
}

/// The members that take a span where `forms`' op takes a pointer. A `first` op never touches
/// more than the spans have, so it has one form. The others have a checked form that traps when
/// a span is too short or misaligned, and an `@unsafe` unchecked one that only asserts it.
func spanMembers(_ forms: SpanForms) -> String {
    let returnClause = forms.returns == .void ? "" : " -> \(swiftReturnType(forms.returns))"
    let returnKeyword = forms.returns == .void ? "" : "return "
    let checked = spanSignature(forms, checked: true)

    guard !forms.takesCountFromSpans else {
        let body = bufferClosures(forms.spans) { buffers in
            forms.bridgeCall(buffers.map { "\($0).baseAddress" }, forms.count(buffers))
        }
        return """
                \(spanAvailability)
                @export(implementation) @inline(always)
                public static func \(forms.name)(\(checked.parameters))\(returnClause) {
                    \(body)
                }


            """
    }

    let unchecked = spanSignature(forms, checked: false)
    let isNonEmpty = forms.spans.allSatisfy {
        if case .gathered = $0.extent { false } else { true }
    }
    let body = bufferClosures(forms.spans) { buffers in
        let pointers = buffers.map { "\($0).baseAddress\(isNonEmpty ? ".unsafelyUnwrapped" : "")" }
        return forms.bridgeCall(pointers, forms.count(buffers))
    }
    return checkedMembers(
        forms.name,
        availability: spanAvailability,
        checked: checked.parameters,
        unchecked: unchecked,
        returnClause: returnClause,
        checks: forms.spans.flatMap(spanChecks(of:)) + forms.checks,
        uncheckedBody: "\(returnKeyword)\(body)"
    )
}

func takesLaneAmount(_ op: Op) -> Bool {
    op.parameters.contains(.laneAmount)
}

func takesIndices(_ op: Op) -> Bool {
    op.parameters.contains { $0 == .indices || $0 == .laneIndices || $0 == .indexVector }
}

func takesLaneIndex(_ op: Op) -> Bool {
    op.parameters.contains(.laneIndex) || op.parameters.contains(.tupleIndex)
}

func takesLookupIndices(_ op: Op) -> Bool {
    op.parameters.contains(.lookupIndices)
}

func hasCheckedForms(_ op: Op) -> Bool {
    takesLaneAmount(op) || takesIndices(op) || takesLaneIndex(op) || !op.immediates.isEmpty
}

/// What a lane amount form checks before it hands the amount on, as a Swift condition and the
/// message for when it fails. Highway's NEON slides read their index tables out of bounds above
/// `laneCount`.
func laneAmountChecks() -> [Check] {
    [
        (
            "lanes >= 0 && lanes <= laneCount",
            "Lane amount is negative or more than a vector has lanes"
        )
    ]
}

/// What a lookup form checks before it hands the indices on, as a Swift condition and the message
/// for when it fails: one unsigned comparison of every index and one reduction of the results.
func indexChecks(of op: Op, for element: Element) -> [Check] {
    guard let contract = op.indexContract,
        let parameter = op.parameters.first(where: { $0 == .indices || $0.isLaneIndices })
    else { return [] }
    let indexElement = operandElement(of: parameter, for: element)
    let function = cFunctionName(
        indicesWithinName(perByte: contract.isPerByte, for: indexElement),
        indexElement
    )
    let name = parameter == .indexVector ? "vector" : "indices"
    let count = contract.count.expression(laneCount: "laneCount")
    return [("\(function)(\(name).raw, \(contract.offset), \(count))", contract.message)]
}

func laneIndexChecks() -> [Check] {
    [
        (
            "index >= 0 && index < laneCount",
            "Lane index is negative or at least as many as a vector has lanes"
        )
    ]
}

func tupleIndexChecks(count: Int) -> [Check] {
    [("index >= 0 && index < \(count)", "Tuple index is negative or at least \(count)")]
}

func uncheckedFormChecks(of op: Op, for element: Element) -> [Check] {
    if !op.immediates.isEmpty {
        return op.immediates.map { $0.check(for: element) }
    }
    if takesIndices(op) { return indexChecks(of: op, for: element) }
    if op.parameters.contains(.laneIndex) { return laneIndexChecks() }
    if op.parameters.contains(.tupleIndex) { return tupleIndexChecks(count: tupleCount(of: op)) }
    return laneAmountChecks()
}

/// The members of an op that takes a lane amount or indices: a checked form that traps on those
/// outside the range its checks accept, and an `@unsafe` unchecked one that only asserts it.
func checkedFormMembers(of op: Op, for element: Element) -> String {
    let returnClause = op.returns == .void ? "" : " -> \(swiftReturnType(op.returns))"
    let returnKeyword = op.returns == .void ? "" : "return "
    let checked = swiftSignature(of: op, for: element)
    let unchecked = swiftSignature(of: op, for: element, checked: false)
    var uncheckedArguments: [String] = []
    for (binding, parameter) in zip(bindings(of: op, for: element, checked: false), op.parameters) {
        if parameter.isTag { continue }
        uncheckedArguments.append(swiftCallArgument(binding))
    }
    let body = swiftBody(of: op, for: element, arguments: unchecked.arguments)
    return checkedMembers(
        op.swiftName,
        checked: checked.parameters,
        unchecked: (
            unchecked.parameters, op.swiftOrdered(uncheckedArguments).joined(separator: ", ")
        ),
        returnClause: returnClause,
        checks: uncheckedFormChecks(of: op, for: element),
        uncheckedBody: "\(returnKeyword)\(body)"
    )
}

func checkedFormRequirements(of op: Op, indent: String) -> String {
    let returnClause = op.returns == .void ? "" : " -> \(swiftReturnType(op.returns))"
    let unchecked = swiftSignature(of: op, for: elements[0], checked: false)
    return "\(indent)@unsafe static func \(op.swiftName)(\(unchecked.parameters))\(returnClause)\n"
}

func spanRequirements(_ forms: SpanForms, indent: String) -> String {
    let returnClause = forms.returns == .void ? "" : " -> \(swiftReturnType(forms.returns))"
    let checked = spanSignature(forms, checked: true)
    var output = "\(indent)\(spanAvailability)\n"
    output += "\(indent)static func \(forms.name)(\(checked.parameters))\(returnClause)\n"
    if forms.takesCountFromSpans { return output }
    let unchecked = spanSignature(forms, checked: false)
    output += "\(indent)\(spanAvailability)\n"
    output += "\(indent)@unsafe static func \(forms.name)(\(unchecked.parameters))\(returnClause)\n"
    return output
}

/// The name of the form of a store op that appends to an `OutputSpan`, after `UniqueArray`'s
/// `append`s. A `first` op appends as many lanes as it is told to, so it is
/// `append(_:addingCount:to:)`.
func outputSpanName(_ forms: SpanForms) -> String {
    if case .first = forms.extent { return "append" }
    return "append\(forms.name.dropFirst("store".count))"
}

func outputSpanSignature(
    _ forms: SpanForms,
    checked: Bool
) -> (parameters: String, arguments: String) {
    let label = checkedLabel("to", checked: checked)
    let takesCount = if case .first = forms.extent { true } else { false }
    var declarations: [String] = []
    var arguments: [String] = []
    for parameter in forms.parameters {
        switch parameter {
        case .span:
            if takesCount {
                declarations.append("addingCount: Int")
                arguments.append("addingCount: addingCount")
            }
            declarations.append("\(label) output: inout OutputSpan<\(forms.element)>")
            arguments.append("\(label): &output")
        case .other(let declaration, let argument):
            declarations.append(declaration)
            arguments.append(argument)
        }
    }
    return (declarations.joined(separator: ", "), arguments.joined(separator: ", "))
}

/// What an output span form checks before it appends, each as a Swift condition and the message
/// for when it fails. An `aligned` op also needs the lanes it appends to start at an address
/// aligned to the vector size.
func outputSpanChecks(_ extent: SpanExtent) -> [Check] {
    if case .maskBytes = extent {
        return [
            (
                "output.freeCapacity >= (laneCount + 7) / 8",
                "OutputSpan has less free capacity than a mask has bytes"
            )
        ]
    }
    switch extent {
    case .block:
        return [
            (
                "output.freeCapacity >= 16 / MemoryLayout<Lane>.stride",
                "OutputSpan has less free capacity than a block has lanes"
            )
        ]
    case .halfVector, .quarterVector, .eighthVector:
        return [
            (
                "output.freeCapacity >= \(partialExtentLanes(extent))",
                "OutputSpan has less free capacity than \(partialExtentName(extent)) has lanes"
            )
        ]
    default: break
    }
    guard case .vectors(let count, let aligned) = extent else {
        return [
            ("addingCount >= 0 && addingCount <= laneCount", "Count out of bounds"),
            (
                "addingCount <= output.freeCapacity",
                "OutputSpan has less free capacity than the count"
            ),
        ]
    }
    var checks = [
        count > 1
            ? (
                "output.freeCapacity >= \(count) * laneCount",
                "OutputSpan has less free capacity than \(count) vectors have lanes"
            )
            : (
                "output.freeCapacity >= laneCount",
                "OutputSpan has less free capacity than a vector has lanes"
            )
    ]
    if aligned {
        checks.append(
            (
                "output.span.withUnsafeBufferPointer { (UInt(bitPattern: $0.baseAddress) "
                    + "&+ UInt($0.count &* MemoryLayout<Lane>.stride)) "
                    + "% UInt(laneCount * MemoryLayout<Lane>.stride) == 0 }",
                "OutputSpan does not continue at an address aligned to the vector size"
            )
        )
    }
    return checks
}

/// The members that append to an `OutputSpan` where `forms`' store op takes a pointer. Like the
/// span forms, a checked form traps when the output span has too little free capacity, the count
/// is out of bounds, or the lanes would be misaligned, and an `@unsafe` unchecked one only
/// asserts it. An empty `OutputSpan` can have no buffer at all, which only a `first` op can be
/// given, to append no lanes to.
func outputSpanMembers(_ forms: SpanForms) -> String {
    let name = outputSpanName(forms)
    let checked = outputSpanSignature(forms, checked: true)
    let unchecked = outputSpanSignature(forms, checked: false)
    let (pointer, appendedCount) =
        switch forms.extent {
        case .first:
            ("buffer.baseAddress?.advanced(by: initializedCount)", "addingCount")
        case .vectors(let count, _):
            (
                "buffer.baseAddress.unsafelyUnwrapped + initializedCount",
                count > 1 ? "\(count) * laneCount" : "laneCount"
            )
        case .block:
            (
                "buffer.baseAddress.unsafelyUnwrapped + initializedCount",
                "16 / MemoryLayout<Lane>.stride"
            )
        case .halfVector, .quarterVector, .eighthVector:
            (
                "buffer.baseAddress.unsafelyUnwrapped + initializedCount",
                partialExtentLanes(forms.extent)
            )
        case .table, .gathered:
            fatalError("\(forms.extent) is not an output")
        case .maskBytes:
            ("buffer.baseAddress.unsafelyUnwrapped + initializedCount", "(laneCount + 7) / 8")
        }
    let discarding = forms.returns == .void ? "" : "_ = "
    return checkedMembers(
        name,
        availability: spanAvailability,
        checked: checked.parameters,
        unchecked: unchecked,
        returnClause: "",
        checks: outputSpanChecks(forms.extent),
        uncheckedBody: """
            unsafe output.withUnsafeMutableBufferPointer { buffer, initializedCount in
                \(discarding)\(forms.bridgeCall([pointer], "addingCount"))
                initializedCount &+= \(appendedCount)
            }
            """
    )
}

func outputSpanRequirements(_ forms: SpanForms, indent: String) -> String {
    let name = outputSpanName(forms)
    let checked = outputSpanSignature(forms, checked: true)
    let unchecked = outputSpanSignature(forms, checked: false)
    var output = "\(indent)\(spanAvailability)\n"
    output += "\(indent)static func \(name)(\(checked.parameters))\n"
    output += "\(indent)\(spanAvailability)\n"
    output += "\(indent)@unsafe static func \(name)(\(unchecked.parameters))\n"
    return output
}

let integerElements = classicElements.filter { $0.category != .float }
let floatElements = classicElements.filter { $0.category == .float }

func opsApplyingToAll(_ candidates: [Element]) -> [Op] {
    ops.filter { op in op.source == nil && candidates.allSatisfy(op.applies.matches) }
}

let universalOps = opsApplyingToAll(classicElements)
let integerOnlyOps = opsApplyingToAll(integerElements)
    .filter { op in !universalOps.contains { $0.identifier == op.identifier } }
let floatOnlyOps = opsApplyingToAll(floatElements)
    .filter { op in !universalOps.contains { $0.identifier == op.identifier } }

func protocolRequirements(_ requirementOps: [Op], indent: String) -> String {
    var output = ""
    for op in requirementOps where !isOutsideProtocols(op) {
        let signature = swiftSignature(of: op, for: elements[0])
        let returnClause = op.returns == .void ? "" : " -> \(swiftReturnType(op.returns))"
        output += "\(indent)static func \(op.swiftName)(\(signature.parameters))\(returnClause)\n"
        if hasCheckedForms(op) {
            output += checkedFormRequirements(of: op, indent: indent)
        }
        if let forms = spanForms(of: op, for: elements[0]) {
            output += spanRequirements(forms, indent: indent)
            if forms.isMutable && forms.appendsToOutput {
                output += outputSpanRequirements(forms, indent: indent)
            }
        }
    }
    return output
}

func generateProtocols() -> String {
    let declarations = """
        /// An element type that vectors can hold, and the ops every such type has.
        ///
        /// Conformances are the `SIMD…` enumerations, so that a kernel can be written once and
        /// used for any element type: `func sum<E: SIMDElement>(_ type: E.Type, …)`.
        public protocol SIMDElement {
            associatedtype Lane
            associatedtype Vector
            associatedtype Mask
            associatedtype Indices

            /// How many lanes of `Lane` a `Vector` holds on the target this was compiled for.
            static var laneCount: Int { get }

            /// How many 16-byte blocks a `Vector` holds on the target this was compiled for.
            static var blockCount: Int { get }

        \(laneCapabilityRequirements(indent: "    "))\(protocolRequirements(universalOps, indent: "    "))}

        /// The ops that only the integer element types have.
        public protocol SIMDIntegerElement: SIMDElement {
        \(protocolRequirements(integerOnlyOps, indent: "    "))}

        /// The ops that only the floating point element types have.
        public protocol SIMDFloatElement: SIMDElement {
        \(protocolRequirements(floatOnlyOps, indent: "    "))}
        """

    return "\(generationNotice)\n\n\(declarations)\n"
}

func vectorDeclaration(of element: Element) -> String {
    """
    public struct Vector: Sendable {
        /// The SIMD type a `Vector` converts to and from, whose width is the target's.
        public typealias SIMDType = \(element.cVector)

        public var raw: \(element.cRawVector)

        @export(implementation) @inline(always)
        public init(raw: \(element.cRawVector)) {
            self.raw = raw
        }

        @export(implementation) @inline(always)
        public init(_ simd: SIMDType) {
            raw = \(element.cToRawVector)(simd)
        }

        @export(implementation) @inline(always)
        public var simd: SIMDType { \(element.cFromRawVector)(raw) }
    }
    """
}

func maskDeclaration(of element: Element) -> String {
    """
    public struct Mask: Sendable {
        /// The SIMD mask type a `Mask` converts to and from, whose width is the target's.
        public typealias SIMDType = SIMDMask<\(element.cMask)>

        public var raw: \(element.cRawMask)

        @export(implementation) @inline(always)
        public init(raw: \(element.cRawMask)) {
            self.raw = raw
        }

        @export(implementation) @inline(always)
        public init(_ simd: SIMDType) {
            raw = \(element.cToRawMask)(simd._storage)
        }

        @export(implementation) @inline(always)
        public var simd: SIMDType {
            SIMDType(\(element.cFromRawMask)(raw))
        }
    }
    """
}

func indicesDeclaration(of element: Element) -> String {
    "public typealias Indices = \(laneIndexElement(of: element).namespace).Vector"
}

func narrowDeclaration(
    named name: String,
    shape: Shape,
    simd: String,
    raw: String,
    toRaw: String,
    fromRaw: String
) -> String {
    let width =
        switch shape {
        case .full: "the target's width"
        case .half: "half the target's width"
        case .quarter: "a quarter of the target's width"
        case .eighth: "an eighth of the target's width"
        case .block: "128 bits wide"
        }
    return """
        public struct \(name): Sendable {
            /// The SIMD type that `\(name)` converts to and from, \(width).
            public typealias SIMDType = \(simd)

            public var raw: \(raw)

            @export(implementation) @inline(always)
            public init(raw: \(raw)) {
                self.raw = raw
            }

            @export(implementation) @inline(always)
            public init(_ simd: SIMDType) {
                raw = \(toRaw)(simd)
            }

            @export(implementation) @inline(always)
            public var simd: SIMDType { \(fromRaw)(raw) }
        }
        """
}

func narrowVectorDeclaration(of element: Element, shape: Shape) -> String {
    narrowDeclaration(
        named: shape.swiftVector,
        shape: shape,
        simd: element.cVector(of: shape),
        raw: element.cRawVector(of: shape),
        toRaw: element.cToRawVector(of: shape),
        fromRaw: element.cFromRawVector(of: shape)
    )
}

func narrowMaskDeclaration(of element: Element, shape: Shape) -> String {
    narrowDeclaration(
        named: shape.swiftMask,
        shape: shape,
        simd: element.cMask(of: shape),
        raw: element.cRawMask(of: shape),
        toRaw: element.cToRawMask(of: shape),
        fromRaw: element.cFromRawMask(of: shape)
    )
}

func typeDeclarations(of element: Element) -> String {
    let lane = "public typealias Lane = \(element.swiftType)"
    let mask = maskDeclaration(of: element)
    let indices = indicesDeclaration(of: element)
    let narrow = narrowShapes(of: element).map {
        let masks = $0.hasMask ? "\n\n\(narrowMaskDeclaration(of: element, shape: $0))" : ""
        return "\n\n\(narrowVectorDeclaration(of: element, shape: $0))\(masks)"
    }
    .joined()
    guard element.hasOpaqueVector else {
        return
            "\(lane)\npublic typealias Vector = \(element.cVector)\n\n\(mask)\n\n\(indices)\(narrow)"
    }
    return "\(lane)\n\n\(vectorDeclaration(of: element))\n\n\(mask)\n\n\(indices)\(narrow)"
}

func opMembers(of op: Op, for element: Element) -> String {
    if hasCheckedForms(op) {
        return checkedFormMembers(of: op, for: element)
    }
    var output = ""
    let signature = swiftSignature(of: op, for: element)
    let returnClause = op.returns == .void ? "" : " -> \(swiftReturnType(op.returns))"
    let body = swiftBody(of: op, for: element, arguments: signature.arguments)
    output += "    @export(implementation) @inline(always)\n"
    output +=
        "    public static func \(op.swiftName)(\(signature.parameters))\(returnClause) {\n"
    let checks = laneCapabilityStatements(of: op, for: element)
    output += checks
    output += "        \(checks.isEmpty ? "" : "return ")\(body)\n"
    output += "    }\n\n"
    if let forms = spanForms(of: op, for: element) {
        output += spanMembers(forms)
        if forms.isMutable && forms.appendsToOutput {
            output += outputSpanMembers(forms)
        }
    }
    return output
}

func wideningMembers(_ op: WideningOp, for element: Element) -> String {
    var output = ""
    for narrow in wideningSources(of: element) {
        let countParameter = op.takesCount ? ", count: Int" : ""
        let countArgument = op.takesCount ? ", count" : ""
        let function = cWideningFunctionName(op, from: narrow, to: element)
        output += "    @export(implementation) @inline(always)\n"
        output += "    public static func \(op.swiftName)("
        output += "from: UnsafePointer<\(narrow.swiftType)>\(countParameter)"
        output += ") -> Vector {\n"
        let call = "unsafe \(function)(from\(countArgument))"
        output += "        \(vectorFromRaw(call, of: element))\n"
        output += "    }\n\n"
        output += spanMembers(spanForms(of: op, from: narrow, to: element))
    }
    return output
}

func guarded(
    _ text: String,
    rebinding source: Element,
    to element: Element,
    testing: Bool
) -> String {
    guarded(
        text,
        involving: element.compilationCondition == nil ? [source] : [],
        testing: testing
    )
}

func rebindingMembers(_ op: RebindingOp, for element: Element) -> String {
    var output = ""
    for source in rebindingSources(of: element) {
        let function = cRebindingFunctionName(op, from: source, to: element)
        var member = "    @export(implementation) @inline(always)\n"
        member += "    public static func \(op.swiftName)"
        member += "(\(op.label) mask: \(source.namespace).Mask) -> Mask {\n"
        member += "        Mask(raw: \(function)(mask.raw))\n"
        member += "    }\n"
        output += guarded(member, rebinding: source, to: element, testing: false) + "\n\n"
    }
    return output
}

func repeatingBlockMembers(for element: Element) -> String {
    var output = ""
    let blockLanes = repeatingBlockLanes(of: element)
    output += "    @export(implementation) @inline(always)\n"
    output += "    public static func \(repeatingBlockName)("
    output += blockLanes.map { "_ \($0): Lane" }.joined(separator: ", ")
    output += ") -> Vector {\n"
    let blockFunction = cFunctionName(repeatingBlockName, element)
    let blockCall =
        "\(blockFunction)(\(blockLanes.map(element.swiftScalarArgument).joined(separator: ", ")))"
    output += "        \(vectorFromRaw(blockCall, of: element))\n"
    output += "    }\n\n"
    return output
}

func availabilityInserted(_ attribute: String, into text: String) -> String {
    var previousIsAttribute = false
    var lines: [String] = []
    for line in text.split(separator: "\n", omittingEmptySubsequences: false) {
        let trimmed = line.trimmingCharacters(in: .whitespaces)
        if trimmed.hasPrefix("@"), !previousIsAttribute {
            lines.append("\(line.prefix { $0 == " " })\(attribute)")
        }
        previousIsAttribute = trimmed.hasPrefix("@")
        lines.append(String(line))
    }
    return lines.joined(separator: "\n")
}

/// The element types that are compiled out where `element` is not, and that `op` takes or returns.
func compiledOutOperands(of op: Op, in element: Element) -> [Element] {
    guard element.compilationCondition == nil, let source = op.source,
        source.compilationCondition != nil
    else { return [] }
    return [source]
}

func guarded(_ text: String, involving involved: [Element], testing: Bool) -> String {
    guard let element = involved.first(where: { $0.compilationCondition != nil }),
        let condition = element.compilationCondition, !text.isEmpty
    else { return text }
    let attributed =
        testing
        ? text : availabilityInserted(element.swiftAvailability ?? "", into: text)
    return "#if \(condition)\n\(attributed)\n#endif"
}

func guarded(_ texts: [String], op: Op, in element: Element, testing: Bool) -> [String] {
    let involved = compiledOutOperands(of: op, in: element)
    return texts.map { guarded($0, involving: involved, testing: testing) }
}

func generateElementMembers(_ element: Element) -> [SectionMember] {
    var members = ops.filter { $0.applies.matches(element) }.map {
        SectionMember(
            section: $0.section,
            inside: guarded(
                [opMembers(of: $0, for: element)],
                op: $0,
                in: element,
                testing: false
            )
        )
    }
    members += wideningOps.map {
        SectionMember(section: $0.section, inside: [wideningMembers($0, for: element)])
    }
    members += rebindingOps.map {
        SectionMember(section: $0.section, inside: [rebindingMembers($0, for: element)])
    }
    members.append(
        SectionMember(section: .initialization, inside: [repeatingBlockMembers(for: element)])
    )
    return members
}

let elementImports = "public import CVectorizationOps"

func hasAll(_ requirements: [Op], for element: Element) -> Bool {
    requirements.allSatisfy { op in
        isOutsideProtocols(op)
            || ops.contains { $0.identifier == op.identifier && $0.applies.matches(element) }
    }
}

func protocolConformances(of element: Element) -> [String] {
    switch element.category {
    case .float: return ["SIMDElement", "SIMDFloatElement"]
    case .unsignedInteger, .signedInteger: return ["SIMDElement", "SIMDIntegerElement"]
    case .float16, .bfloat16:
        guard hasAll(universalOps, for: element) else { return [] }
        return ["SIMDElement"] + (hasAll(floatOnlyOps, for: element) ? ["SIMDFloatElement"] : [])
    }
}

func generateElement(_ element: Element) -> String {
    let conformances = protocolConformances(of: element) + ["SendableMetatype"]

    var output = """
        \(generationNotice)

        \(elementImports)

        /// Vectors of `\(element.swiftType)`, and the ops over them.
        \(element.swiftAvailability.map { "\($0)\n" } ?? "")public enum \(element.namespace): \(conformances.joined(separator: ", ")) {
            \(typeDeclarations(of: element))

            @export(implementation) @inline(always)
            public static var laneCount: Int { Int(\(cFunctionName("laneCount", element))()) }

            @export(implementation) @inline(always)
            public static var blockCount: Int { Int(\(cFunctionName("blockCount", element))()) }


        """
    output += laneCapabilityMembers(for: element)
    output += indexLimitMembers(for: element)
    output += "}\n\n\(unavailableSendableConformance(of: element.namespace))\n"

    return output
}

func fnv1a(_ text: String) -> UInt64 {
    text.utf8.reduce(0xCBF2_9CE4_8422_2325) { ($0 ^ UInt64($1)) &* 0x100_0000_01B3 }
}

func referenceTestSeed(_ element: Element, _ test: String, _ input: String) -> String {
    String(format: "0x%016llX", fnv1a("\(element.suffix)/\(test)/\(input)"))
}

struct ReferenceInput {
    let parameter: Parameter
    let name: String
    let values: String

    var description: String {
        switch parameter {
        case .lane, .fillLane, .insertedLane: return "hex(\(name))"
        case .count, .shiftAmount, .laneAmount, .roundConstant, .immediate, .flag, .maskBits,
            .laneIndex, .tupleIndex:
            return name
        case .tuple(let count):
            let members = (0..<count).map { "describe(\(name).\($0))" }
            return "[\(members.joined(separator: ", "))].joined(separator: \", \")"
        default: return "describe(\(name))"
        }
    }
}

func hasOutOfContractInputs(_ op: Op) -> Bool {
    guard !op.requiresTrueLane else { return true }
    return op.parameters.contains { parameter in
        switch parameter {
        case .shiftAmount, .shiftCounts, .laneAmount, .indices, .laneIndices, .lookupIndices:
            return true
        default: return false
        }
    }
}

func isAligned(_ op: Op) -> Bool {
    switch op.span {
    case .vectors(_, let aligned)?: return aligned
    case .table?: return true
    case .first?, .maskBytes?, .block?, .halfVector?, .quarterVector?, .eighthVector?, .gathered?,
        nil:
        return false
    }
}

/// The lanes whose size a pointer op's address must be aligned to.
func alignmentLanes(of op: Op) -> String {
    if case .table(let lanes)? = op.span { return String(lanes) }
    return "H.laneCount"
}

func pointerLanes(of op: Op, guarded: Bool = false) -> String {
    switch op.span {
    case .vectors(let count, _)?: return count == 1 ? "H.laneCount" : "\(count) * H.laneCount"
    case .first?: return op.clampsSpanCount && !guarded ? "2 * H.laneCount" : "H.laneCount"
    case .table(let lanes)?: return String(lanes)
    case .maskBytes?: return "(H.laneCount + 7) / 8"
    case .block?: return "16 / MemoryLayout<H.Lane>.size"
    case .halfVector?, .quarterVector?, .eighthVector?:
        return partialExtentLanes(op.span, prefix: "H.")
    case .gathered?: return "H.laneCount"
    case nil: fatalError("\(op.swiftName) takes a pointer but has no span extent")
    }
}

func pointeeType(of op: Op, for element: Element) -> String {
    if let narrow = op.narrowElement { return narrow.swiftType }
    if op.parameters.contains(.constIndexPointer) { return laneIndexElement(of: element).swiftType }
    if case .maskBytes? = op.span { return "UInt8" }
    return "H.Lane"
}

func pointerExpression(_ closureParameter: String, aligned: Bool) -> String {
    aligned ? closureParameter : "\(closureParameter).baseAddress!"
}

/// The lanes of `buffer` that a pointer op with `extent` may touch, which a guarded test puts right
/// before an inaccessible page.
func guardedLanes(of buffer: String, extent: SpanExtent?, count: String = "count") -> String {
    guard case .first? = extent else { return buffer }
    return "Array(\(buffer).prefix(\(count)))"
}

func indexInputs(
    of op: Op,
    _ parameter: Parameter,
    seed: String,
    inContract: Bool
) -> String {
    guard let contract = op.indexContract else {
        fatalError("\(op.swiftName) takes indices but has no index contract")
    }
    let type = parameter.isLaneIndices ? "H.Indices" : "H.Vector"
    let offset = contract.offset == 0 ? "" : "offset: \(contract.offset), "
    let perByte = contract.isPerByte ? "perByte: true, " : ""
    let count = contract.count.expression(laneCount: "H.laneCount")
    let arguments =
        "\(type).self, \(offset)\(perByte)count: \(count), \(seed), inContract: \(inContract)"
    return "Inputs.tableIndices(\(arguments))"
}

func divisorInputs(_ vectors: String, spreadSeed: String, for element: Element) -> String {
    let negatives =
        element.category == .signedInteger ? " + [H.Vector(H.Vector.Simd(repeating: -1))]" : ""
    let shifted =
        "H.Vector(vector.simd &>> H.Vector.Simd(repeating: H.Lane(truncatingIfNeeded: index)))"
    let spread =
        "Inputs.vectors(H.Vector.self, \(spreadSeed)).enumerated().map { index, vector in \(shifted) }"
    return "\(vectors)\(negatives) + \(spread)"
}

func byteSweepInputs(_ vectors: String) -> String {
    let lanes = "(0..<H.laneCount).map { H.Lane(truncatingIfNeeded: start + $0) }"
    return "\(vectors) + (0..<256).map { start in H.Vector(H.Vector.Simd(\(lanes))) }"
}

func immediate(named name: String, of op: Op) -> ImmediateArgument {
    guard let immediate = op.immediates.first(where: { $0.name == name }) else {
        fatalError("\(op.identifier) has no immediate named \(name)")
    }
    return immediate
}

func nonCanonicalMaskInputs(
    of element: Element,
    seed: String,
    mapping transform: (_ mask: String) -> String = { $0 }
) -> String {
    let vectors = "Inputs.vectors(\(element.namespace).Vector.self, \(seed))"
    guard ops.contains(where: { $0.identifier == "maskFromVector" && $0.applies.matches(element) })
    else {
        let unsigned = unsignedElement(of: element)
        let bits = "\(unsigned.namespace).vector(bitPattern: $0)"
        let mask = "\(element.namespace).mask(rebinding: \(unsigned.namespace).mask(from: \(bits)))"
        return "\(vectors).map { \(transform(mask)) }"
    }
    return "\(vectors).map { \(transform("\(element.namespace).mask(from: $0)")) }"
}

func nonCanonicalHalfMaskInputs(of element: Element, seed: String) -> String {
    nonCanonicalMaskInputs(of: element, seed: seed) { "\(element.namespace).lowerHalf(\($0))" }
}

func nonCanonicalNarrowedMaskInputs(
    of element: Element,
    narrowing shape: Shape,
    from wide: Element,
    seed: String
) -> String {
    nonCanonicalMaskInputs(of: wide, seed: seed) {
        "\(element.namespace).\(shape.prefix.lowercased())Mask(narrowing: \($0))"
    }
}

func referenceInputs(
    of op: Op,
    for element: Element,
    test: String,
    inContract: Bool,
    guarded: Bool = false,
    nonCanonical: Bool = false
) -> [ReferenceInput] {
    var inputs: [ReferenceInput] = []
    for (binding, parameter) in zip(bindings(of: op, for: element), op.parameters) {
        let seed = "seed: \(referenceTestSeed(element, test, String(inputs.count)))"
        let operand = operandElement(of: parameter, for: element, source: op.source)
        var values: String
        switch parameter {
        case .tag, .sourceTag, .narrowTag, .sourceNarrowTag, .lanePointer, .bytePointer,
            .narrowLanePointer:
            continue
        case .outVector where !op.accumulates:
            continue
        case .sourceVector, .signedSourceVector:
            values =
                mulBitsSourceInputs(of: op, operand: operand, seed: seed)
                ?? integerDemotionSourceInputs(
                    of: op,
                    operand: operand,
                    result: element,
                    seed: seed
                )
                ?? floatDemotionSourceInputs(of: op, operand: operand, for: element, seed: seed)
                ?? float16DemotionSourceInputs(of: op, operand: operand, for: element, seed: seed)
                ?? bfloat16DemotionSourceInputs(operand: operand, for: element, seed: seed)
                ?? "Inputs.conversions(\(operand.namespace).Vector.self, \(seed))"
        case .narrowVector(let shape):
            values = "Inputs.vectors(H.\(shape.swiftVector).self, \(seed)).map(poisoningUpperBytes)"
        case .sourceNarrowVector(let shape):
            values = "Inputs.conversions(\(operand.namespace).\(shape.swiftVector).self, \(seed))"
            values += ".map(poisoningUpperBytes)"
        case .sourceMask:
            values =
                nonCanonical
                ? nonCanonicalMaskInputs(of: operand, seed: seed)
                : "Inputs.masks(\(operand.namespace).Mask.self, \(seed))"
        case .narrowMask(let shape):
            values =
                nonCanonical && shape == .half
                ? nonCanonicalHalfMaskInputs(of: element, seed: seed)
                : "Inputs.masks(H.\(shape.swiftMask).self, \(seed))"
        case .sourceNarrowMask(let shape):
            values =
                nonCanonical
                ? nonCanonicalNarrowedMaskInputs(
                    of: operand,
                    narrowing: shape,
                    from: element,
                    seed: seed
                )
                : "Inputs.masks(\(operand.namespace).\(shape.swiftMask).self, \(seed))"
        case .vector, .fillVector, .otherwiseVector, .outVector:
            let generator = op.accumulates ? "accumulators" : "vectors"
            values = "Inputs.\(generator)(H.Vector.self, \(seed))"
            if op.divides && element.category != .float && parameter == .vector
                && inputs.contains(where: { $0.parameter == .vector })
            {
                let spreadSeed =
                    "seed: \(referenceTestSeed(element, test, "\(inputs.count)Spread"))"
                values = divisorInputs(values, spreadSeed: spreadSeed, for: element)
            }
            if op.section == .crypto && element.bits == 8 && inputs.isEmpty {
                values = byteSweepInputs(values)
            }
        case .indices, .laneIndices, .lookupIndices, .indexVector:
            values = indexInputs(of: op, parameter, seed: seed, inContract: inContract)
        case .mask, .whereMask:
            values =
                nonCanonical
                ? nonCanonicalMaskInputs(of: element, seed: seed)
                : "Inputs.masks(H.Mask.self, \(seed))"
            if op.requiresTrueLane {
                values += ".filter { \(inContract ? "" : "!")any($0.simd) }"
            }
        case .lane, .fillLane, .insertedLane:
            values = "Inputs.lanes(H.Lane.self, \(seed))"
        case .flag:
            values = "[false, true]"
        case .maskBits:
            values = "Inputs.maskBits(lanes: 16 / MemoryLayout<H.Lane>.size, \(seed))"
        case .laneIndex:
            values = "Inputs.laneIndices(lanes: H.laneCount)"
        case .tuple(let count):
            values = "Inputs.tuples\(count)(of: Inputs.vectors(H.Vector.self, \(seed)))"
        case .tupleIndex:
            values = "Inputs.tupleIndices(count: \(tupleCount(of: op)))"
        case .count where op.clampsSpanCount:
            values = "Inputs.counts(through: \(guarded ? "H.laneCount" : "2 * H.laneCount"))"
        case .count where op.span != nil:
            values = "Inputs.bufferCounts(lanes: H.laneCount)"
        case .count:
            values = "Inputs.maskCounts(lanes: H.laneCount, lane: \(element.swiftMaskLane).self)"
        case .shiftAmount:
            values = "Inputs.shiftAmounts(bits: \(element.bits), inContract: \(inContract))"
        case .shiftCounts:
            values = "Inputs.shiftCounts(H.Vector.self, \(seed), inContract: \(inContract))"
        case .laneAmount:
            values = "Inputs.laneAmounts(lanes: H.laneCount, inContract: \(inContract))"
        case .roundConstant:
            values = "Array<UInt8>(0...255)"
        case .immediate:
            let immediate = immediate(named: binding.swiftName, of: op)
            let upper = immediate.upperBound.expression(for: element, laneCount: "H.laneCount")
            values = "Array(\(immediate.lowerBound)...\(upper))"
        case .constIndexPointer:
            let lanes = pointerLanes(of: op)
            let pointee = pointeeType(of: op, for: element)
            values = "Inputs.indexBuffers(\(pointee).self, lanes: \(lanes), \(seed))"
        case .constLanePointer, .constBytePointer, .constBitsPointer:
            let isBytes = parameter.isBytePointer
            let lanes = isBytes ? "(H.laneCount + 7) / 8" : pointerLanes(of: op, guarded: guarded)
            let pointee = isBytes ? "UInt8" : pointeeType(of: op, for: element)
            values = "Inputs.buffers(\(pointee).self, count: \(lanes), \(seed))"
        case .pointerIndices, .pointerOffsets:
            let vector = "\(signedElement(of: element).namespace).Vector"
            let lanes = pointerLanes(of: op)
            let count =
                parameter == .pointerOffsets
                ? "(\(lanes) - 1) * MemoryLayout<H.Lane>.stride + 1" : lanes
            values =
                "Inputs.tableIndices(\(vector).self, count: \(count), \(seed), inContract: true)"
        }
        inputs.append(ReferenceInput(parameter: parameter, name: binding.swiftName, values: values))
    }
    return inputs
}

let referenceCombinators = [
    2: "everyPair", 3: "mixedTriples", 4: "mixedQuadruples", 5: "mixedQuintuples",
    6: "mixedSextuples",
]

func referenceLoop(
    over inputs: [ReferenceInput],
    for element: Element,
    test: String,
    where condition: String? = nil
) -> String? {
    guard let first = inputs.first else { return nil }
    let filter = condition.map { " where \($0)" } ?? ""
    guard inputs.count > 1 else { return "for \(first.name) in \(first.name)Inputs\(filter)" }
    guard let combinator = referenceCombinators[inputs.count] else {
        fatalError("\(test) has \(inputs.count) inputs, which nothing combines")
    }
    var arguments = inputs.map { "\($0.name)Inputs" }
    if inputs.count > 2 {
        arguments.append("seed: \(referenceTestSeed(element, test, "combinations"))")
    }
    let names = inputs.map(\.name).joined(separator: ", ")
    return "for (\(names)) in \(combinator)(\(arguments.joined(separator: ", ")))\(filter)"
}

func referenceDescription(of inputs: [ReferenceInput], suffix: String = "") -> String {
    let fields = inputs.map { "\($0.name): \\(\($0.description))" }
    return "\"\(fields.joined(separator: ", "))\(suffix)\""
}

func portCall(_ name: String, _ arguments: [String], on type: String = "H") -> String {
    "\(type).\(name)(\(arguments.joined(separator: ", ")))"
}

let referenceNothrowNamespace = "HighwayReference.Nothrow"

func referenceCall(
    _ name: String,
    _ arguments: [String],
    in namespace: String = "HighwayReference"
) -> String {
    "\(namespace).\(name)(\(arguments.joined(separator: ", ")))"
}

func referenceNothrowWrapper(
    returning type: String,
    named name: String,
    declarations: String
) -> String {
    let arguments = declarations.split(separator: ",").compactMap {
        $0.split(whereSeparator: { " &*".contains($0) }).last
    }
    let call = "::HighwayReference::\(name)(\(arguments.joined(separator: ", ")))"
    return
        "HWY_INLINE \(type) \(name)(\(declarations)) noexcept { \(type == "void" ? "" : "return ")\(call); }\n"
}

func referenceResult(
    _ call: String,
    returning returns: ReturnType,
    for element: Element,
    on type: String = "H"
) -> String {
    switch returns {
    case .vector: return opaqueVector(call, of: element, on: type)
    case .narrowVector(let shape): return "\(type).\(shape.swiftVector)(raw: \(call))"
    case .narrowMask(let shape): return "\(type).\(shape.swiftMask)(raw: \(call))"
    case .laneIndices: return "\(type).Indices(raw: \(call))"
    case .mask: return "\(type).Mask(raw: \(call))"
    case .indices: return "\(type).Indices(raw: \(call))"
    case .tuple(let count):
        let members = (0..<count).map { opaqueVector("tuple.v\($0)", of: element, on: type) }
        return "{ tuple in (\(members.joined(separator: ", "))) }(\(call))"
    case .lane:
        return element.isHalfPrecision ? "\(element.swiftType)(bitPattern: \(call))" : call
    default: return call
    }
}

func referenceCalls(
    of op: Op,
    for element: Element,
    pointer: String,
    referencePointer: String? = nil,
    destination: String? = nil,
    checked: Bool = true,
    referenceName: String? = nil,
    constants: [String: (port: String, reference: String)] = [:]
) -> (port: String, reference: String) {
    var portArguments: [String] = []
    var referenceArguments: [String] = []
    var outVectorIndex = 0

    for (binding, parameter) in zip(bindings(of: op, for: element, checked: checked), op.parameters)
    {
        if let constant = constants[binding.swiftName] {
            portArguments.append(swiftCallArgument(binding, passing: constant.port))
            referenceArguments.append(
                rawArgument(constant.reference, parameter, for: element, source: op.source)
            )
            continue
        }
        switch parameter {
        case .tag, .sourceTag, .narrowTag, .sourceNarrowTag:
            continue
        case .vector, .shiftCounts, .indices, .laneIndices, .lookupIndices, .indexVector, .mask,
            .fillVector, .whereMask, .otherwiseVector, .lane, .insertedLane, .fillLane, .count,
            .shiftAmount, .laneAmount, .roundConstant, .immediate, .flag, .maskBits, .laneIndex,
            .tuple, .tupleIndex, .pointerIndices, .pointerOffsets, .sourceVector,
            .signedSourceVector, .sourceMask, .narrowVector, .sourceNarrowVector, .narrowMask,
            .sourceNarrowMask:
            portArguments.append(swiftCallArgument(binding))
            referenceArguments.append(
                swiftArgument(binding, parameter, for: element, source: op.source)
            )
        case .constLanePointer, .lanePointer, .constBytePointer, .bytePointer, .constBitsPointer,
            .constIndexPointer, .narrowLanePointer:
            let operand = parameter.isMutablePointer ? destination ?? pointer : pointer
            portArguments.append(swiftCallArgument(binding, passing: operand))
            referenceArguments.append(
                parameter.isMutablePointer ? operand : referencePointer ?? operand
            )
        case .outVector:
            portArguments.append(swiftCallArgument(binding, passing: "p\(outVectorIndex)"))
            referenceArguments.append(
                rawArgument("r\(outVectorIndex)", parameter, for: element)
            )
            outVectorIndex += 1
        }
    }

    let keyword = isUnsafe(op) ? "unsafe " : ""
    let portKeyword = isUnsafe(op) || !checked ? "unsafe " : ""
    let call = referenceCall(
        referenceName ?? referenceFunctionName(of: op, for: element),
        referenceArguments
    )
    let reference = referenceResult(call, returning: op.returns, for: element)
    let port = portCall(op.swiftName, op.swiftOrdered(portArguments))
    return ("\(portKeyword)\(port)", "\(keyword)\(reference)")
}

typealias Disabling = (condition: String, reason: String)

func emulationDisabling(_ reason: String) -> Disabling {
    ("SIMDTarget.targetName == \"EMU128\"", reason)
}

let assertionsDisabling: Disabling = (
    "assertionsAreEnabled", "Assertions abort the test run on these indices"
)

func outOfContractDisabling(of op: Op) -> [Disabling] {
    if op.requiresTrueLane {
        return [assertionsDisabling]
    }
    if op.parameters.contains(.shiftAmount) || op.parameters.contains(.shiftCounts) {
        return [emulationDisabling("EMU128 has no defined result for these shift counts")]
    }
    guard let contract = op.indexContract else { return [] }
    return [assertionsDisabling]
        + (contract.isDefinedOnEmulation
            ? [] : [emulationDisabling("EMU128 reads outside the vector for these indices")])
}

func laneCapabilityDisabling(of op: Op, for element: Element) -> [Disabling] {
    guard let capability = op.laneCapability, capability.isChecked(for: element) else { return [] }
    return [capability.disabling]
}

func testAttribute(disabling: [Disabling]) -> String {
    let traits = disabling.map { ".disabled(if: \($0.condition), \"\($0.reason)\")" }
    return "@Test(\(traits.joined(separator: ", ")))"
}

func referenceTestFunction(
    _ test: String,
    label: String,
    for element: Element,
    inputs: [ReferenceInput],
    declarations: [String] = [],
    disabling: [Disabling] = [],
    signature: String? = nil,
    loopCondition: String? = nil,
    recording: String = "mismatches.record()",
    statements: String
) -> String {
    let header =
        signature
        ?? (disabling.isEmpty
            ? "@Test func \(test)() {"
            : "\(testAttribute(disabling: disabling))\nfunc \(test)() {")
    var lines = ["let mismatches = Mismatches(\"\(label)\")"]
    lines += inputs.map { "let \($0.name)Inputs = \($0.values)" }
    lines += declarations
    if let loop = referenceLoop(
        over: inputs,
        for: element,
        test: test,
        where: loopCondition
    ) {
        lines.append("\(loop) {\n\(statements)\n}")
    } else {
        lines.append(statements)
    }
    lines.append(recording)
    return """
        \(header)
        \(lines.joined(separator: "\n"))
        }
        """
}

func alignedLanes(_ lanes: String, to laneCount: String = "H.laneCount") -> String {
    "withAlignedLanes(\(lanes), laneCount: \(laneCount))"
}

func referenceLoadStatements(
    of source: String,
    aligned: Bool,
    alignedTo laneCount: String = "H.laneCount",
    guardedLanes: String?,
    comparison: String? = nil,
    port: String,
    reference: String,
    description: String
) -> String {
    let results = "(\(port), \(reference))"
    let scope =
        if let guardedLanes {
            "unsafe withGuardedLanes(\(guardedLanes)) { source in \(results) }.result"
        } else if aligned {
            "unsafe \(alignedLanes(source, to: laneCount)) { source in \(results) }.result"
        } else {
            "\(source).withUnsafeBufferPointer { source in \(results) }"
        }
    let check = comparison ?? "mismatches.check(portResult, referenceResult, \(description))"
    return """
        let (portResult, referenceResult) = \(scope)
        \(check)
        """
}

func compressedPrefixComparison(
    of source: String,
    for element: Element,
    description: String
) -> String {
    let isDeterministic = referenceCall(
        referenceFunctionName("compressTailIsDeterministic", element),
        []
    )
    let lanes = ["portResult", "referenceResult"].map { result in
        "(0..<checkedLanes).map { \(simdVector(result, of: element))[$0] }"
    }
    return """
        let checkedLanes = compressedLaneCount(bits: \(source), lanes: H.laneCount, tailIsDeterministic: \(isDeterministic))
        mismatches.check(\(lanes[0]), \(lanes[1]), \(description))
        """
}

func referenceOutVectorStatements(
    of source: String,
    count: Int,
    for element: Element,
    guardedLanes: String?,
    port: String,
    reference: String,
    inputs: [ReferenceInput]
) -> String {
    let zero = referenceResult(
        referenceCall(referenceFunctionName("zero", element), []),
        returning: .vector,
        for: element
    )
    var statements = (0..<count).map { "var p\($0) = \(portCall("zero", []))" }
    statements += (0..<count).map { "var r\($0) = \(zero)" }
    let calls = "{ source in\n\(port)\n\(reference)\n}"
    if let guardedLanes {
        statements.append("_ = unsafe withGuardedLanes(\(guardedLanes)) \(calls)")
    } else {
        statements.append("\(source).withUnsafeBufferPointer \(calls)")
    }
    for index in 0..<count {
        let description = referenceDescription(of: inputs, suffix: ", v\(index)")
        statements.append("mismatches.check(p\(index), r\(index), \(description))")
    }
    return statements.joined(separator: "\n")
}

func referenceStoreStatements(
    aligned: Bool,
    guardedLanes: String?,
    returnsResult: Bool,
    port: String,
    reference: String,
    description: String
) -> String {
    let stores = ["port", "reference"].map { side in
        let (lanes, result) = ("\(side)Lanes", returnsResult ? "\(side)Result" : "_")
        let call = side == "port" ? port : reference
        let closure = "{ destination in \(call) }"
        if let guardedLanes {
            return "let (\(result), \(lanes)) = unsafe withGuardedLanes(\(guardedLanes)) \(closure)"
        }
        if aligned {
            return "let (\(result), \(lanes)) = unsafe \(alignedLanes("sentinel")) \(closure)"
        }
        let binding = returnsResult ? "let \(result) = " : ""
        return
            "var \(lanes) = sentinel\n\(binding)\(lanes).withUnsafeMutableBufferPointer \(closure)"
    }
    var comparisons = ["mismatches.check(portLanes, referenceLanes, \(description))"]
    if returnsResult {
        comparisons.append("mismatches.check(portResult, referenceResult, \(description))")
    }
    return (stores + comparisons).joined(separator: "\n")
}

func referenceCopyStatements(
    of source: String,
    sourceLanes: String?,
    destinationLanes: String?,
    returnsResult: Bool,
    port: String,
    reference: String,
    description: String
) -> String {
    var comparisons = ["mismatches.check(portLanes, referenceLanes, \(description))"]
    if returnsResult {
        comparisons.append("mismatches.check(portResult, referenceResult, \(description))")
    }
    guard let sourceLanes, let destinationLanes else {
        let calls = [("portLanes", port), ("referenceLanes", reference)].map { lanes, call in
            "\(lanes).withUnsafeMutableBufferPointer { destination in \(call) }"
        }
        let scope =
            returnsResult
            ? "let (portResult, referenceResult) = \(source).withUnsafeBufferPointer { source in\n"
                + "(\(calls.joined(separator: ", ")))\n}"
            : "\(source).withUnsafeBufferPointer { source in\n\(calls.joined(separator: "\n"))\n}"
        return (["var portLanes = sentinel", "var referenceLanes = sentinel", scope] + comparisons)
            .joined(separator: "\n")
    }
    let copies = ["port", "reference"].map { side in
        let call = side == "port" ? port : reference
        let result = returnsResult ? "\(side)Result" : "_"
        return """
            let (\(result), \(side)Lanes) = unsafe withGuardedLanes(\(destinationLanes)) { destination in
            unsafe withGuardedLanes(\(sourceLanes)) { source in \(call) }.result
            }
            """
    }
    return (copies + comparisons).joined(separator: "\n")
}

/// Highway's mask loads promise to read at least 8 bytes, which some targets do, so it is given a
/// copy that has them. The port is given the bytes it needs, to see that it reads no more.
func readsMaskBits(_ op: Op) -> Bool {
    if op.parameters.contains(.constBitsPointer) { return true }
    guard case .maskBytes? = op.span else { return false }
    return op.parameters.contains(.constBytePointer)
}

func paddedPointer(of op: Op) -> String? {
    readsMaskBits(op) ? "padded.baseAddress!" : nil
}

func paddedReferenceCall(_ call: String, of op: Op, source: String) -> String {
    guard paddedPointer(of: op) != nil else { return call }
    let padding = "[UInt8](repeating: 0, count: 8)"
    return "(\(source) + \(padding)).withUnsafeBufferPointer { padded in \(call) }"
}

func hasCopiedLanes(_ op: Op) -> Bool {
    op.parameters.contains(where: \.isConstPointer)
        && op.parameters.contains(where: \.isMutablePointer)
}

func referencePointer(of op: Op, guarded: Bool) -> String {
    let isStore = op.parameters.contains(where: \.isMutablePointer) && !hasCopiedLanes(op)
    return pointerExpression(isStore ? "destination" : "source", aligned: isAligned(op) || guarded)
}

func referenceDestination(of op: Op, guarded: Bool) -> String? {
    hasCopiedLanes(op)
        ? pointerExpression("destination", aligned: isAligned(op) || guarded) : nil
}

/// Indices of the lanes that an op does not use are made to point just past its lanes, so that a
/// test before a guard page faults when the op loads or stores through them.
func poisonedIndexStatements(of op: Op, inputs: [ReferenceInput]) -> String {
    guard let operand = inputs.first(where: { $0.parameter.isPointerIndices }) else { return "" }
    let pastEnd =
        operand.parameter == .pointerOffsets
        ? "H.laneCount * MemoryLayout<H.Lane>.stride" : "H.laneCount"
    let unused: String
    if inputs.contains(where: { $0.parameter == .whereMask }) {
        unused = "where: mask"
    } else if op.parameters.contains(.count), inputs.contains(where: { $0.parameter == .count }) {
        unused = "firstLanes: count"
    } else {
        return ""
    }
    return "let \(operand.name) = poisoned(\(operand.name), \(unused), with: \(pastEnd))\n"
}

func referenceStatements(
    of op: Op,
    for element: Element,
    inputs: [ReferenceInput],
    guarded: Bool,
    count: String = "count",
    calls: (port: String, reference: String)
) -> (declarations: [String], statements: String) {
    let description = referenceDescription(of: inputs)
    let aligned = isAligned(op)
    let isStore = op.parameters.contains(where: \.isMutablePointer)
    var declarations: [String] = []
    let statements: String

    if hasCopiedLanes(op), let source = inputs.first(where: { $0.parameter.isConstPointer })?.name {
        let lanes = pointerLanes(of: op, guarded: guarded)
        declarations.append(
            "let sentinel = Inputs.sentinel(\(pointeeType(of: op, for: element)).self, count: \(guarded ? lanes : "\(lanes) + 4"))"
        )
        statements = referenceCopyStatements(
            of: source,
            sourceLanes: guarded ? guardedLanes(of: source, extent: op.span, count: count) : nil,
            destinationLanes: guarded
                ? guardedLanes(of: "sentinel", extent: op.span, count: count) : nil,
            returnsResult: op.returns != .void,
            port: calls.port,
            reference: paddedReferenceCall(calls.reference, of: op, source: source),
            description: description
        )
    } else if let source = inputs.first(where: { $0.parameter.isConstPointer })?.name {
        let outVectors = op.parameters.filter { $0 == .outVector }.count
        let reference = paddedReferenceCall(calls.reference, of: op, source: source)
        statements =
            outVectors == 0
            ? referenceLoadStatements(
                of: source,
                aligned: aligned,
                alignedTo: alignmentLanes(of: op),
                guardedLanes: guarded
                    ? guardedLanes(of: source, extent: op.span, count: count) : nil,
                comparison: op.leavesLanesUnspecified
                    ? compressedPrefixComparison(of: source, for: element, description: description)
                    : nil,
                port: calls.port,
                reference: reference,
                description: description
            )
            : referenceOutVectorStatements(
                of: source,
                count: outVectors,
                for: element,
                guardedLanes: guarded
                    ? guardedLanes(of: source, extent: op.span, count: count) : nil,
                port: calls.port,
                reference: calls.reference,
                inputs: inputs
            )
    } else if isStore {
        let lanes = pointerLanes(of: op, guarded: guarded)
        let sentinelCount = guarded ? lanes : "\(lanes) + 4"
        declarations.append(
            "let sentinel = Inputs.sentinel(\(pointeeType(of: op, for: element)).self, count: \(sentinelCount))"
        )
        statements = referenceStoreStatements(
            aligned: aligned,
            guardedLanes: guarded
                ? guardedLanes(of: "sentinel", extent: op.span, count: count) : nil,
            returnsResult: op.returns != .void,
            port: calls.port,
            reference: calls.reference,
            description: description
        )
    } else if op.accumulates {
        let outVectors = (0..<op.parameters.filter { $0 == .outVector }.count)
        let initials = outVectors.flatMap { ["var p\($0) = v\($0)", "var r\($0) = v\($0)"] }
        let checks = outVectors.map { index in
            let described = referenceDescription(of: inputs, suffix: ", final v\(index)")
            return "mismatches.check(p\(index), r\(index), \(described))"
        }
        statements = """
            \(initials.joined(separator: "\n"))
            let port = \(calls.port)
            let reference = \(calls.reference)
            mismatches.check(port, reference, \(description))
            \(checks.joined(separator: "\n"))
            """
    } else if op.unspecifiedResult {
        statements = "_ = \(calls.port)\n_ = \(calls.reference)"
    } else if let defined = op.definedLanes {
        let isDeterministic = referenceCall(
            referenceFunctionName("compressTailIsDeterministic", element),
            []
        )
        let trueCount =
            ops.contains { $0.identifier == "trueCount" && $0.applies.matches(element) }
            ? portCall("trueCount", ["mask"])
            : "\(portCall("bits", ["of: mask"])).nonzeroBitCount"
        let lanes = defined == .trueLanes ? trueCount : "H.laneCount - \(trueCount)"
        let results = ["port", "reference"].map { result in
            let simd = simdVector(result, of: element)
            return "(0..<checkedLanes).map { \(simd)[$0] }"
        }
        statements = """
            let port = \(calls.port)
            let reference = \(calls.reference)
            let checkedLanes = \(isDeterministic) ? H.laneCount : \(lanes)
            mismatches.check(\(results[0]), \(results[1]), \(description))
            """
    } else if op.growth == .unspecified {
        let source = op.source ?? element
        let shape = op.sourceShape
        let type = "\(source.namespace)\(shape == .full ? "" : ".\(shape.swiftVector)")"
        let results = ["port", "reference"].map { "Array(bytes(of: \($0)).prefix(definedBytes))" }
        let resultType: String
        switch op.returns {
        case .narrowVector(let shape): resultType = "H.\(shape.swiftVector)"
        default: resultType = "H"
        }
        let grown = ["port", "reference"].map {
            "Array(registerBytes(of: \($0)).dropFirst(definedBytes).prefix(newBytes))"
        }
        let register = shape == .full ? "definedBytes" : "MemoryLayout<\(type).Raw>.size"
        statements = """
            let port = \(calls.port)
            let reference = \(calls.reference)
            let definedBytes = \(type).laneCount * MemoryLayout<\(source.namespace).Lane>.stride
            let grownBytes = \(resultType).laneCount * MemoryLayout<H.Lane>.stride
            let newBytes = HighwayReference.resizedBytesDefined(definedBytes, grownBytes, \(register))
            mismatches.check(\(results[0]), \(results[1]), \(description))
            mismatches.check(\(grown[0]), \(grown[1]), \(description))
            """
    } else if case .tuple(let count) = op.returns {
        let checks = (0..<count).map {
            "mismatches.check(port.\($0), reference.\($0), \(description))"
        }
        statements = """
            let port = \(calls.port)
            let reference = \(calls.reference)
            \(checks.joined(separator: "\n"))
            """
    } else {
        statements = "mismatches.check(\(calls.port), \(calls.reference), \(description))"
    }

    return (declarations, poisonedIndexStatements(of: op, inputs: inputs) + statements)
}

func referenceTest(
    of op: Op,
    for element: Element,
    inContract: Bool,
    checked: Bool = true,
    guarded: Bool = false,
    nonCanonical: Bool = false
) -> String {
    let (test, label) =
        if guarded {
            ("\(op.testIdentifier)BeforeGuardPage", "\(op.testIdentifier) before a guard page")
        } else if nonCanonical {
            (
                "\(op.testIdentifier)NonCanonical",
                "\(op.testIdentifier) with masks from arbitrary vectors"
            )
        } else if !inContract {
            ("\(op.testIdentifier)OutOfContract", "\(op.testIdentifier) out of contract")
        } else if checked {
            (op.testIdentifier, op.testIdentifier)
        } else {
            ("\(op.testIdentifier)Unchecked", "\(op.testIdentifier) unchecked")
        }
    let inputs = referenceInputs(
        of: op,
        for: element,
        test: test,
        inContract: inContract,
        guarded: guarded,
        nonCanonical: nonCanonical
    )
    let calls = referenceCalls(
        of: op,
        for: element,
        pointer: referencePointer(of: op, guarded: guarded),
        referencePointer: paddedPointer(of: op),
        destination: referenceDestination(of: op, guarded: guarded),
        checked: checked
    )
    let (declarations, statements) = referenceStatements(
        of: op,
        for: element,
        inputs: inputs,
        guarded: guarded,
        calls: calls
    )

    return referenceTestFunction(
        test,
        label: label,
        for: element,
        inputs: inputs,
        declarations: declarations,
        disabling: laneCapabilityDisabling(of: op, for: element)
            + (inContract ? [] : outOfContractDisabling(of: op)),
        loopCondition: referenceLoopCondition(of: op, for: element, inputs: inputs),
        statements: statements
    )
}

func wideningReferenceTest(
    _ op: WideningOp,
    from narrow: Element,
    to wide: Element,
    guarded: Bool = false,
    constantCount: Bool = false
) -> String {
    let name = "\(op.swiftName)From\(narrow.swiftType)"
    let guardedName = guarded ? "\(name)BeforeGuardPage" : name
    let test = constantCount ? "check\(uppercasedFirst(guardedName))ConstantCount" : guardedName
    let seed = "seed: \(referenceTestSeed(wide, test, "0"))"
    var inputs = [
        ReferenceInput(
            parameter: .constLanePointer,
            name: "from",
            values: "Inputs.buffers(\(narrow.swiftType).self, count: H.laneCount, \(seed))"
        )
    ]
    let pointer = pointerExpression("source", aligned: guarded)
    var portArguments = ["from: \(pointer)"]
    var referenceArguments = [pointer]
    if op.takesCount {
        if !constantCount {
            inputs.append(
                ReferenceInput(
                    parameter: .count,
                    name: "count",
                    values: "Inputs.bufferCounts(lanes: H.laneCount)"
                )
            )
        }
        portArguments.append("count: count")
        referenceArguments.append(guarded ? "min(count, H.laneCount)" : "count")
    }

    let function = wideningFunctionName(op, from: narrow, to: wide)
    let reference = referenceResult(
        referenceCall(function, referenceArguments),
        returning: .vector,
        for: wide
    )
    let suffix = guarded ? " before a guard page" : ""
    let countLabel = constantCount ? " with count \\(count)" : ""
    return referenceTestFunction(
        test,
        label: "\(op.swiftName) from \(narrow.swiftType)\(countLabel)\(suffix)",
        for: wide,
        inputs: inputs,
        signature: constantCount ? constantHelperSignature(test, ["count"], "Int") : nil,
        statements: referenceLoadStatements(
            of: "from",
            aligned: false,
            guardedLanes: guarded ? guardedLanes(of: "from", extent: op.span) : nil,
            port: "unsafe \(portCall(op.swiftName, portArguments))",
            reference: "unsafe \(reference)",
            description: referenceDescription(of: inputs)
        )
    )
}

func rebindingReferenceTest(
    _ op: RebindingOp,
    from source: Element,
    to target: Element,
    nonCanonical: Bool = false
) -> String {
    let test =
        "\(op.swiftName)\(uppercasedFirst(op.label))From\(source.swiftType)\(nonCanonical ? "NonCanonical" : "")"
    let seed = "seed: \(referenceTestSeed(target, test, "0"))"
    let inputs = [
        ReferenceInput(
            parameter: .mask,
            name: "mask",
            values: nonCanonical
                ? nonCanonicalMaskInputs(of: source, seed: seed)
                : "Inputs.masks(\(source.namespace).Mask.self, \(seed))"
        )
    ]
    let port = portCall(op.swiftName, ["\(op.label): mask"])
    let reference = referenceResult(
        referenceCall(rebindingFunctionName(op, from: source, to: target), ["mask.raw"]),
        returning: .mask,
        for: target
    )
    return referenceTestFunction(
        test,
        label:
            "\(op.swiftName) \(op.label) from \(source.swiftType)\(nonCanonical ? " with masks from arbitrary vectors" : "")",
        for: target,
        inputs: inputs,
        statements:
            "mismatches.check(\(port), \(reference), \(referenceDescription(of: inputs)))"
    )
}

func repeatingBlockReferenceTest(for element: Element) -> String {
    let seed = "seed: \(referenceTestSeed(element, repeatingBlockName, "0"))"
    let vectors = ReferenceInput(
        parameter: .vector,
        name: "vector",
        values: "Inputs.vectors(H.Vector.self, \(seed))"
    )
    let lanes = repeatingBlockLanes(of: element).indices.map {
        element.swiftLane(fromSimd: "\(simdVector("vector", of: element))[\($0)]")
    }
    let function = referenceFunctionName(repeatingBlockName, element)
    let port = portCall(repeatingBlockName, lanes)
    let reference = referenceResult(
        referenceCall(function, lanes.map(element.swiftScalarArgument)),
        returning: .vector,
        for: element
    )
    let description = "\"lanes: \\(describe(vector))\""
    return referenceTestFunction(
        repeatingBlockName,
        label: repeatingBlockName,
        for: element,
        inputs: [vectors],
        statements: "mismatches.check(\(port), \(reference), \(description))"
    )
}

func laneCapabilityReferenceTest(_ capability: LaneCapability, for element: Element) -> String {
    let name = capability.name
    let call = referenceCall(referenceFunctionName(name, element), [])
    return referenceTestFunction(
        name,
        label: name,
        for: element,
        inputs: [],
        statements: "mismatches.check(H.\(name), \(call), \"\")"
    )
}

func blockCountReferenceTest(for element: Element) -> String {
    let call = referenceCall(referenceFunctionName("blockCount", element), [])
    return referenceTestFunction(
        "blockCount",
        label: "blockCount",
        for: element,
        inputs: [],
        statements: "mismatches.check(H.blockCount, \(call), \"\")"
    )
}

func laneCountReferenceTest(for element: Element) -> String {
    let call = referenceCall(referenceFunctionName("laneCount", element), [])
    return referenceTestFunction(
        "laneCount",
        label: "laneCount",
        for: element,
        inputs: [],
        statements: "mismatches.check(H.laneCount, \(call), \"\")"
    )
}

func simdVector(_ expression: String, of element: Element) -> String {
    element.hasOpaqueVector ? "\(expression).simd" : expression
}

func opaqueVector(_ expression: String, of element: Element, on type: String = "H") -> String {
    element.hasOpaqueVector ? "\(type).Vector(raw: \(expression))" : expression
}

func narrowReferenceConformance(of element: Element, shape: Shape) -> String {
    let lanes =
        shape == .block
        ? "16 / MemoryLayout<\(element.swiftType)>.stride"
        : "\(element.namespace).laneCount / \(shape.fraction ?? 1)"
    return """
        extension \(element.namespace).\(shape.swiftVector): ReferenceNarrowVector {
            package static var laneCount: Int { \(lanes) }

            package init(lanes: [\(element.swiftType)]) {
                self = lanes.withUnsafeBufferPointer { buffer in
                    unsafe \(element.namespace).load\(shape.prefix)(from: buffer.baseAddress!)
                }
            }

            package var lanes: [\(element.swiftType)] {
                var lanes = [\(element.swiftType)](repeating: \(element.swiftZeroLane), count: Self.laneCount)
                lanes.withUnsafeMutableBufferPointer { buffer in
                    unsafe \(element.namespace).store(self, to: buffer.baseAddress!)
                }
                return lanes
            }
        }
        """
}

func narrowMaskReferenceConformance(of element: Element, shape: Shape) -> String {
    """
    extension \(element.namespace).\(shape.swiftMask): ReferenceNarrowMask {
        package typealias Lane = \(element.swiftMaskLane)

        package static var laneCount: Int { \(element.namespace).laneCount / \(shape.fraction ?? 1) }
    }
    """
}

func referenceConformances(of element: Element) -> String {
    var blocks: [String] = []
    if element.hasOpaqueVector {
        let body =
            element.isHalfPrecision
            ? "{\n    package typealias InputLane = \(element.swiftType)\n\n"
                + "    package static func simdLane(_ lane: InputLane) -> UInt16 { lane.bitPattern }\n}"
            : "{}"
        blocks.append("extension \(element.namespace).Vector: ReferenceVector \(body)")
    }
    blocks.append("extension \(element.namespace).Mask: ReferenceMask {}")
    for shape in narrowShapes(of: element) {
        blocks.append(narrowReferenceConformance(of: element, shape: shape))
        if shape.hasMask {
            blocks.append(narrowMaskReferenceConformance(of: element, shape: shape))
        }
    }
    let attribute = element.swiftAvailability.map { "\($0)\n" } ?? ""
    let conformances = blocks.map { "\(attribute)\($0)" }.joined(separator: "\n\n")
    guard let condition = element.compilationCondition else { return conformances }
    return "#if \(condition)\n\(conformances)\n#endif"
}

func referenceTests(of op: Op, for element: Element) -> [String] {
    var tests = [referenceTest(of: op, for: element, inContract: true)]
    if takesIndices(op) || takesLaneIndex(op) || !op.immediates.isEmpty {
        tests.append(referenceTest(of: op, for: element, inContract: true, checked: false))
    }
    if hasOutOfContractInputs(op) {
        tests.append(
            referenceTest(of: op, for: element, inContract: false, checked: !takesIndices(op))
        )
    }
    if op.span != nil {
        tests.append(referenceTest(of: op, for: element, inContract: true, guarded: true))
    }
    if op.acceptsNonCanonicalMasks {
        tests.append(referenceTest(of: op, for: element, inContract: true, nonCanonical: true))
    }
    return tests + uncheckedSpanTests(of: op, for: element)
        + widenMulCornerTests(of: op, for: element)
}

func uncheckedSpanTests(of op: Op, for element: Element) -> [String] {
    guard !takesLookupIndices(op), let forms = spanForms(of: op, for: element) else { return [] }
    var tests: [String] = []
    if !forms.takesCountFromSpans {
        tests.append(uncheckedSpanTest(of: op, forms: forms, for: element))
    }
    if forms.isMutable && forms.appendsToOutput {
        tests.append(uncheckedOutputSpanTest(of: op, forms: forms, for: element))
    }
    return tests
}

func uncheckedSpanBinding(_ span: SpanArgument, of op: Op) -> String {
    let (pointer, buffer, constructor) =
        span.isMutable
        ? ("destination", "UnsafeMutableBufferPointer", "var \(span.name) = unsafe MutableSpan")
        : ("source", "UnsafeBufferPointer", "let \(span.name) = unsafe Span")
    let lanes =
        if case .maskBytes = span.extent { "(H.laneCount + 7) / 8" } else { pointerLanes(of: op) }
    let elements = isAligned(op) ? "\(buffer)(start: \(pointer), count: \(lanes))" : pointer
    return "\(constructor)(_unsafeElements: \(elements))"
}

func uncheckedSpanCall(
    of op: Op,
    forms: SpanForms,
    for element: Element,
    checked: Bool
) -> String {
    var arguments = spanSignature(forms, checked: checked).arguments
    let outVectors = zip(bindings(of: op, for: element), op.parameters)
        .filter { $0.1 == .outVector }
        .map(\.0.swiftName)
    for (index, name) in outVectors.enumerated() {
        arguments = arguments.replacingOccurrences(
            of: "&\(name)",
            with: "&\(checked ? "r" : "p")\(index)"
        )
    }
    let bindings = forms.spans.map { uncheckedSpanBinding($0, of: op) }
    let call = portCall(forms.name, [arguments])
    return """
        ({
        \(bindings.joined(separator: "\n"))
        return \(checked ? "" : "unsafe ")\(call)
        })()
        """
}

func uncheckedSpanTest(of op: Op, forms: SpanForms, for element: Element) -> String {
    let test = "\(op.testIdentifier)UncheckedSpan"
    let inputs = referenceInputs(of: op, for: element, test: test, inContract: true)
    let (declarations, statements) = referenceStatements(
        of: op,
        for: element,
        inputs: inputs,
        guarded: false,
        calls: (
            port: uncheckedSpanCall(of: op, forms: forms, for: element, checked: false),
            reference: uncheckedSpanCall(of: op, forms: forms, for: element, checked: true)
        )
    )
    return referenceTestFunction(
        test,
        label: "\(op.testIdentifier) unchecked span",
        for: element,
        inputs: inputs,
        declarations: declarations,
        statements: statements
    )
}

func uncheckedOutputSpanTest(of op: Op, forms: SpanForms, for element: Element) -> String {
    let test = "\(op.testIdentifier)UncheckedOutputSpan"
    let inputs = referenceInputs(of: op, for: element, test: test, inContract: true).map {
        $0.parameter == .count
            ? ReferenceInput(
                parameter: .count,
                name: $0.name,
                values: "Inputs.counts(through: H.laneCount)"
            ) : $0
    }
    let description = referenceDescription(of: inputs)
    let capacity =
        switch forms.extent {
        case .first: "count"
        case .maskBytes: "(H.laneCount + 7) / 8"
        default: pointerLanes(of: op)
        }
    let alignment =
        isAligned(op)
        ? ", alignment: H.laneCount * MemoryLayout<\(pointeeType(of: op, for: element))>.stride"
        : ""
    let stores = [("port", false), ("reference", true)].map { side, checked in
        let arguments = outputSpanSignature(forms, checked: checked).arguments
            .replacingOccurrences(of: "addingCount: addingCount", with: "addingCount: count")
        let call = "\(checked ? "" : "unsafe ")\(portCall(outputSpanName(forms), [arguments]))"
        return """
            let (_, \(side)Lanes) = withOutputSpan(capacity: \(capacity)\(alignment)) { output in
            \(call)
            }
            """
    }
    let comparison = "mismatches.check(portLanes, referenceLanes, \(description))"
    return referenceTestFunction(
        test,
        label: "\(op.testIdentifier) unchecked output span",
        for: element,
        inputs: inputs,
        statements: (stores + [comparison]).joined(separator: "\n")
    )
}

func codegenKeysOfOps(for element: Element) -> [[String]] {
    var keys = ops.filter { $0.applies.matches(element) }.map { codegenKeys(of: $0, for: element) }
    keys += wideningOps.flatMap { op in
        wideningSources(of: element).map { codegenKeys(of: op, from: $0, to: element) }
    }
    keys += rebindingOps.flatMap { op in
        rebindingSources(of: element).map { codegenKeys(of: op, from: $0, to: element) }
    }
    keys.append(repeatingBlockCodegenKeys(for: element))
    keys += codegenKernels.filter { $0.applies.matches(element) }.map {
        codegenKeys(of: $0, for: element)
    }
    return keys
}

func isTested(_ opKeys: [String], by keys: Set<String>?) -> Bool {
    guard let keys else { return true }
    return !keys.isDisjoint(with: opKeys)
}

func testedOps(for element: Element, by keys: Set<String>?) -> [Op] {
    ops.filter {
        $0.applies.matches(element) && isTested(codegenKeys(of: $0, for: element), by: keys)
    }
}

func testedWideningSources(
    of op: WideningOp,
    for element: Element,
    by keys: Set<String>?
) -> [Element] {
    wideningSources(of: element).filter {
        isTested(codegenKeys(of: op, from: $0, to: element), by: keys)
    }
}

func testedRebindingSources(
    of op: RebindingOp,
    for element: Element,
    by keys: Set<String>?
) -> [Element] {
    rebindingSources(of: element).filter {
        isTested(codegenKeys(of: op, from: $0, to: element), by: keys)
    }
}

func testedKernels(for element: Element, by keys: Set<String>?) -> [CodegenKernel] {
    codegenKernels.filter {
        $0.applies.matches(element) && isTested(codegenKeys(of: $0, for: element), by: keys)
    }
}

func generateReferenceTestMembers(_ element: Element, by keys: Set<String>?) -> [SectionMember] {
    var members = testedOps(for: element, by: keys).map {
        SectionMember(
            section: $0.section,
            inside: markingKnownGaps(
                guarded(
                    referenceTests(of: $0, for: element),
                    op: $0,
                    in: element,
                    testing: true
                ),
                suite: "\(element.namespace)Reference"
            )
        )
    }
    members += wideningOps.map { op in
        let tests = testedWideningSources(of: op, for: element, by: keys).flatMap { narrow in
            [
                wideningReferenceTest(op, from: narrow, to: element),
                wideningReferenceTest(op, from: narrow, to: element, guarded: true),
            ]
        }
        return SectionMember(section: op.section, inside: tests)
    }
    members += rebindingOps.map { op in
        let tests = testedRebindingSources(of: op, for: element, by: keys).flatMap { source in
            [false, true].map { nonCanonical in
                guarded(
                    rebindingReferenceTest(
                        op,
                        from: source,
                        to: element,
                        nonCanonical: nonCanonical
                    ),
                    rebinding: source,
                    to: element,
                    testing: true
                )
            }
        }
        return SectionMember(section: op.section, inside: tests)
    }
    if isTested(repeatingBlockCodegenKeys(for: element), by: keys) {
        members.append(
            SectionMember(
                section: .initialization,
                inside: [repeatingBlockReferenceTest(for: element)]
            )
        )
    }
    members += reorderMulPairingMembers(of: element)
    members += firstTrueCompositionMembers(of: element, by: keys)
    return members
}

let referenceTestImports = """
    import CHighwayReference
    import HighwayReferenceTestSupport
    import Testing
    import Vectorization
    """

func generateReferenceTests(_ element: Element) -> String {
    var tests = [laneCountReferenceTest(for: element), blockCountReferenceTest(for: element)]
    for capability in laneCapabilities where capability.applies.matches(element) {
        tests.append(laneCapabilityReferenceTest(capability, for: element))
    }

    return """
        \(generationNotice)

        \(referenceTestImports)

        @Suite("\(element.namespace) against Highway")
        struct \(element.namespace)ReferenceTests {
            typealias H = \(element.namespace)

        \(tests.joined(separator: "\n\n"))
        }

        """
}

func generateReferenceConformances(of conformingElements: [Element], importing: String) -> String {
    """
    \(generationNotice)

    \(importing)

    \(conformingElements.map(referenceConformances(of:)).joined(separator: "\n\n"))

    """
}

let targetReferenceChecks: [(test: String, port: String, reference: String)] =
    [
        (
            "targetName",
            "SIMDTarget.targetName",
            "unsafe String(cString: \(referenceCall("targetName", [])))"
        ),
        ("isEmulated", "SIMDTarget.isEmulated", referenceCall("isEmulated", [])),
    ]
    + targetCapabilities.map {
        ($0.swiftName, "SIMDTarget.\($0.swiftName)", referenceCall($0.swiftName, []))
    } + [
        ("target", "SIMDTarget.target.rawValue", referenceCall("staticTarget", [])),
        (
            "supportedTargets",
            "SIMDTarget.supportedTargets.rawValue",
            referenceCall("supportedTargets", [])
        ),
    ]

func generateReferenceTargetTests() -> String {
    let tests =
        targetReferenceChecks.map { test, port, reference in
            """
            @Test func \(test)() {
            let mismatches = Mismatches("\(test)")
            mismatches.check(\(port), \(reference), "")
            mismatches.record()
            }
            """
        } + targetSetReferenceTests() + cacheControlRunTests()

    return """
        \(generationNotice)

        import CHighwayReference
        import HighwayReferenceTestSupport
        import Vectorization
        import Testing

        @Suite("HighwayTarget against Highway")
        struct HighwayTargetReferenceTests {
        \(tests.joined(separator: "\n\n"))
        }

        """
}

func uppercasedFirst(_ text: String) -> String {
    "\(text.prefix(1).uppercased())\(text.dropFirst())"
}

func codegenConstantSuffix(_ constantParameter: String?) -> String {
    constantParameter.map { "Constant\(uppercasedFirst($0))" } ?? ""
}

func codegenKey(_ referenceName: String, constantParameter: String? = nil) -> String {
    "\(uppercasedFirst(referenceName))\(codegenConstantSuffix(constantParameter))"
}

func codegenFunctionName(
    _ side: String,
    _ referenceName: String,
    constantParameter: String? = nil
) -> String {
    "\(side)\(codegenKey(referenceName, constantParameter: constantParameter))"
}

func codegenFunction(
    _ name: String,
    parameters: [String],
    returnClause: String,
    call: String
) -> String {
    """
    @inline(never)
    public func \(name)(\(parameters.joined(separator: ", ")))\(returnClause) {
        \(call)
    }
    """
}

func codegenFunctions(
    _ swiftName: String,
    referenceName: String,
    for element: Element,
    returns: ReturnType,
    isUnsafe: (port: Bool, reference: Bool),
    constantParameter: String? = nil,
    calling highwayName: String? = nil,
    port: (parameters: [String], arguments: [String]),
    reference: (parameters: [String], arguments: [String])
) -> String {
    let portKeyword = isUnsafe.port ? "unsafe " : ""
    let referenceKeyword = isUnsafe.reference ? "unsafe " : ""
    let hasReturn = returns != .void
    let portReturn = swiftReturnType(returns, scope: "\(element.namespace).")
    let referenceReturn = importedReturnType(returns, element)
    let functions = [
        codegenFunction(
            codegenFunctionName("port", referenceName, constantParameter: constantParameter),
            parameters: port.parameters,
            returnClause: hasReturn ? " -> \(portReturn)" : "",
            call: portKeyword + portCall(swiftName, port.arguments, on: element.namespace)
        ),
        codegenFunction(
            codegenFunctionName("highway", referenceName, constantParameter: constantParameter),
            parameters: reference.parameters,
            returnClause: hasReturn ? " -> \(referenceReturn)" : "",
            call: referenceKeyword
                + referenceResult(
                    referenceCall(
                        highwayName ?? referenceName,
                        reference.arguments,
                        in: referenceNothrowNamespace
                    ),
                    returning: returns,
                    for: element,
                    on: element.namespace
                )
        ),
    ]
    return functions.joined(separator: "\n\n")
}

struct CodegenParameter {
    let binding: Binding
    let kind: Parameter
    let referenceType: String
    var immediate: ImmediateArgument?
    var source: Element?
}

func codegenBinding(label: String, name: String, type: String) -> Binding {
    Binding(
        declaration: "",
        cDeclaration: "",
        argument: name,
        swiftLabel: label,
        swiftName: name,
        swiftType: type,
        isInOut: false
    )
}

struct CodegenSide {
    enum Kind: String {
        case port
        case highway
    }

    let kind: Kind
    let element: Element

    var vector: String { returnType(.vector) }
    var lane: String { returnType(.lane) }
    var pointer: String { "UnsafePointer<\(lane)>" }

    var namespace: String {
        switch kind {
        case .port: return element.namespace
        case .highway: return referenceNamespace(of: element)
        }
    }

    var laneCount: String { "\(namespace).laneCount" }

    func returnType(_ returns: ReturnType) -> String {
        switch kind {
        case .port: return swiftReturnType(returns, scope: "\(element.namespace).")
        case .highway: return importedReturnType(returns, element)
        }
    }

    func call(_ identifier: String, _ arguments: [String]) -> String {
        let op = codegenOp(identifier, for: element)
        let operandBindings = bindings(of: op, for: element, checked: !takesIndices(op))
        let callBindings = zip(operandBindings, op.parameters)
            .filter { _, parameter in !parameter.isTag }
            .map(\.0)
        guard callBindings.count == arguments.count else {
            fatalError(
                "\(identifier) takes \(callBindings.count) arguments, not \(arguments.count)"
            )
        }
        let keyword = isUnsafe(op) ? "unsafe " : ""
        switch kind {
        case .port:
            let labelled = zip(op.swiftOrdered(callBindings), arguments).map {
                swiftCallArgument($0, passing: $1)
            }
            let portKeyword = isUnsafe(op) || takesIndices(op) ? "unsafe " : ""
            return portKeyword + portCall(op.swiftName, labelled, on: element.namespace)
        case .highway:
            let converted = zip(op.swiftOrdered(op.operands), arguments).map {
                rawArgument($1, $0, for: element)
            }
            let reference = referenceFunctionName(of: op, for: element)
            let call = referenceCall(
                reference,
                op.highwayOrdered(converted),
                in: referenceNothrowNamespace
            )
            return keyword
                + referenceResult(call, returning: op.returns, for: element, on: element.namespace)
        }
    }

    func repeating(_ value: String) -> String {
        call("repeating", [value])
    }

    func repeatingBlock(_ lanes: [String]) -> String {
        switch kind {
        case .port:
            return portCall(repeatingBlockName, lanes, on: element.namespace)
        case .highway:
            let call = referenceCall(
                referenceFunctionName(repeatingBlockName, element),
                lanes,
                in: referenceNothrowNamespace
            )
            return referenceResult(call, returning: .vector, for: element, on: element.namespace)
        }
    }
}

func codegenOp(_ identifier: String, for element: Element) -> Op {
    guard let op = ops.first(where: { $0.identifier == identifier && $0.applies.matches(element) })
    else {
        fatalError("\(identifier) is not an op of \(element.swiftType)")
    }
    return op
}

func codegenConstant(
    of parameter: Parameter,
    immediate: ImmediateArgument? = nil,
    alternative: CodegenImmediate? = nil,
    source: Element? = nil,
    for element: Element
) -> (port: String, reference: String)? {
    let operand = operandElement(of: parameter, for: element, source: source)
    let port = CodegenSide(kind: .port, element: operand)
    let highway = CodegenSide(kind: .highway, element: operand)
    let lane =
        switch operand.category {
        case .float: "1.5"
        case .float16, .bfloat16: "\(operand.swiftType)(bitPattern: 26)"
        case .unsignedInteger, .signedInteger: "26"
        }
    switch parameter {
    case .vector, .fillVector, .otherwiseVector, .sourceVector, .signedSourceVector:
        return (port.repeating(lane), highway.repeating(lane))
    case .shiftCounts: return (port.repeating("3"), highway.repeating("3"))
    case .indices: return (port.repeating("3"), highway.repeating("3"))
    case .laneIndices, .lookupIndices, .indexVector, .pointerIndices, .pointerOffsets:
        let indices = operandElement(of: parameter, for: element)
        return (
            CodegenSide(kind: .port, element: indices).repeating("1"),
            CodegenSide(kind: .highway, element: indices).repeating("1")
        )
    case .lane, .fillLane, .insertedLane: return (lane, lane)
    case .shiftAmount: return ("3", "3")
    case .laneAmount, .count, .roundConstant, .laneIndex, .tupleIndex: return ("1", "1")
    case .immediate:
        let value = String(alternative?.value(element) ?? immediate?.codegenValue ?? 1)
        return (value, value)
    case .flag: return ("false", "false")
    case .maskBits: return ("5", "5")
    case .tag, .sourceTag, .narrowTag, .sourceNarrowTag, .mask, .whereMask, .sourceMask,
        .narrowVector, .sourceNarrowVector, .narrowMask, .sourceNarrowMask, .constLanePointer,
        .lanePointer, .constBytePointer, .bytePointer, .constBitsPointer, .constIndexPointer,
        .narrowLanePointer, .outVector, .tuple:
        return nil
    }
}

struct CodegenVariant {
    var constant: Int?
    var alternative: CodegenImmediate?
}

func codegenVariants(of parameters: [CodegenParameter], for element: Element) -> [CodegenVariant] {
    let constants = parameters.indices.filter {
        codegenConstant(
            of: parameters[$0].kind,
            immediate: parameters[$0].immediate,
            source: parameters[$0].source,
            for: element
        ) != nil
    }
    let firstImmediate = parameters.firstIndex { $0.kind == .immediate }
    let variants = constants.filter { parameters[$0].kind != .immediate || $0 == firstImmediate }
    let alternatives =
        firstImmediate.flatMap { parameters[$0].immediate?.codegenAlternatives } ?? []
    return ((firstImmediate == nil ? [nil] : []) + variants).map { CodegenVariant(constant: $0) }
        + alternatives.map { CodegenVariant(constant: firstImmediate, alternative: $0) }
}

func codegenConstantName(
    of parameters: [CodegenParameter],
    constant: Int?,
    alternative: CodegenImmediate? = nil
) -> String? {
    constant.map { parameters[$0].binding.swiftName + uppercasedFirst(alternative?.name ?? "") }
}

func codegenConstantIndices(of parameters: [CodegenParameter], variant: Int?) -> Set<Int> {
    guard let variant else { return [] }
    let immediates = parameters.indices.filter { parameters[$0].kind == .immediate }
    return Set(immediates + [variant])
}

func codegenFunctions(
    _ swiftName: String,
    referenceName: String,
    for element: Element,
    returns: ReturnType,
    isUnsafe: (port: Bool, reference: Bool),
    parameters: [CodegenParameter],
    templateName: String? = nil,
    highwayOrdered: ([String]) -> [String] = { $0 }
) -> String {
    var functions: [String] = []

    for variant in codegenVariants(of: parameters, for: element) {
        var portParameters: [String] = []
        var referenceParameters: [String] = []
        var portArguments: [String] = []
        var referenceArguments: [String] = []

        let constantIndices = codegenConstantIndices(of: parameters, variant: variant.constant)
        for (index, parameter) in parameters.enumerated() {
            let binding = parameter.binding
            if constantIndices.contains(index),
                let constant = codegenConstant(
                    of: parameter.kind,
                    immediate: parameter.immediate,
                    alternative: index == variant.constant ? variant.alternative : nil,
                    source: parameter.source,
                    for: element
                )
            {
                portArguments.append(swiftCallArgument(binding, passing: constant.port))
                referenceArguments.append(
                    rawArgument(
                        constant.reference,
                        parameter.kind,
                        for: element,
                        source: parameter.source
                    )
                )
                continue
            }
            let isShiftAmount = parameter.kind == .shiftAmount
            portParameters.append(swiftDeclaration(binding, as: isShiftAmount ? "Int32" : nil))
            referenceParameters.append(swiftDeclaration(binding, as: parameter.referenceType))
            portArguments.append(
                swiftCallArgument(
                    binding,
                    passing: isShiftAmount ? "Int(\(binding.swiftName))" : nil
                )
            )
            referenceArguments.append(
                rawArgument(
                    binding.swiftName,
                    parameter.kind,
                    for: element,
                    source: parameter.source
                )
            )
        }

        functions.append(
            codegenFunctions(
                swiftName,
                referenceName: referenceName,
                for: element,
                returns: returns,
                isUnsafe: isUnsafe,
                constantParameter: codegenConstantName(
                    of: parameters,
                    constant: variant.constant,
                    alternative: variant.alternative
                ),
                calling: variant.constant.flatMap {
                    parameters[$0].kind == .shiftAmount ? templateName : nil
                },
                port: (portParameters, portArguments),
                reference: (referenceParameters, highwayOrdered(referenceArguments))
            )
        )
    }

    return functions.joined(separator: "\n\n")
}

func codegenKeys(
    _ referenceName: String,
    parameters: [CodegenParameter],
    for element: Element
) -> [String] {
    codegenVariants(of: parameters, for: element).map {
        codegenKey(
            referenceName,
            constantParameter: codegenConstantName(
                of: parameters,
                constant: $0.constant,
                alternative: $0.alternative
            )
        )
    }
}

func codegenParameters(of op: Op, for element: Element) -> [CodegenParameter] {
    var parameters: [CodegenParameter] = []

    let parameterBindings = bindings(
        of: op,
        for: element,
        scope: "\(element.namespace).",
        checked: false
    )
    for (binding, parameter) in zip(parameterBindings, op.parameters) {
        if parameter.isTag { continue }
        parameters.append(
            CodegenParameter(
                binding: binding,
                kind: parameter,
                referenceType: importedType(
                    of: parameter,
                    for: element,
                    narrow: op.narrowElement,
                    source: op.source
                ),
                immediate: parameter == .immediate
                    ? immediate(named: binding.swiftName, of: op) : nil,
                source: op.source
            )
        )
    }

    return op.swiftOrdered(parameters)
}

func codegenFunctions(of op: Op, for element: Element) -> String {
    codegenFunctions(
        op.swiftName,
        referenceName: referenceFunctionName(of: op, for: element),
        for: element,
        returns: op.returns,
        isUnsafe: (port: isUnsafe(op) || hasCheckedForms(op), reference: isUnsafe(op)),
        parameters: codegenParameters(of: op, for: element),
        templateName: op.template == nil ? nil : templateReferenceName(of: op, for: element),
        highwayOrdered: op.highwayOrdered
    )
}

func codegenKeys(of op: Op, for element: Element) -> [String] {
    codegenKeys(
        referenceFunctionName(of: op, for: element),
        parameters: codegenParameters(of: op, for: element),
        for: element
    )
}

func codegenParameters(of op: WideningOp, from narrow: Element) -> [CodegenParameter] {
    let pointerType = importedType(of: .constLanePointer, for: narrow)
    var parameters = [
        CodegenParameter(
            binding: codegenBinding(label: "from", name: "from", type: pointerType),
            kind: .constLanePointer,
            referenceType: pointerType
        )
    ]
    if op.takesCount {
        let countType = importedType(of: .count, for: narrow)
        parameters.append(
            CodegenParameter(
                binding: codegenBinding(label: "count", name: "count", type: countType),
                kind: .count,
                referenceType: countType
            )
        )
    }
    return parameters
}

func codegenFunctions(_ op: WideningOp, from narrow: Element, to wide: Element) -> String {
    codegenFunctions(
        op.swiftName,
        referenceName: wideningFunctionName(op, from: narrow, to: wide),
        for: wide,
        returns: .vector,
        isUnsafe: (port: true, reference: true),
        parameters: codegenParameters(of: op, from: narrow)
    )
}

func codegenKeys(of op: WideningOp, from narrow: Element, to wide: Element) -> [String] {
    codegenKeys(
        wideningFunctionName(op, from: narrow, to: wide),
        parameters: codegenParameters(of: op, from: narrow),
        for: wide
    )
}

func codegenParameters(of op: RebindingOp, from source: Element) -> [CodegenParameter] {
    let type = importedType(of: .mask, for: source)
    return [
        CodegenParameter(
            binding: codegenBinding(label: op.label, name: "mask", type: type),
            kind: .mask,
            referenceType: type
        )
    ]
}

func codegenFunctions(_ op: RebindingOp, from source: Element, to target: Element) -> String {
    codegenFunctions(
        op.swiftName,
        referenceName: rebindingFunctionName(op, from: source, to: target),
        for: target,
        returns: .mask,
        isUnsafe: (port: false, reference: false),
        parameters: codegenParameters(of: op, from: source)
    )
}

func codegenKeys(of op: RebindingOp, from source: Element, to target: Element) -> [String] {
    codegenKeys(
        rebindingFunctionName(op, from: source, to: target),
        parameters: codegenParameters(of: op, from: source),
        for: target
    )
}

func repeatingBlockCodegenFunctions(for element: Element) -> String {
    let lanes = repeatingBlockLanes(of: element)
    return codegenFunctions(
        repeatingBlockName,
        referenceName: referenceFunctionName(repeatingBlockName, element),
        for: element,
        returns: .vector,
        isUnsafe: (port: false, reference: false),
        port: (lanes.map { "_ \($0): \(element.namespace).Lane" }, lanes),
        reference: (
            lanes.map { "_ \($0): \(element.swiftType)" },
            lanes.map(element.swiftScalarArgument)
        )
    )
}

func repeatingBlockCodegenKeys(for element: Element) -> [String] {
    [codegenKey(referenceFunctionName(repeatingBlockName, element))]
}

func referenceNamespace(of element: Element) -> String {
    "HighwayReference\(element.swiftType)"
}

func referenceSpanForms(of op: Op, for element: Element) -> SpanForms? {
    guard var forms = spanForms(of: op, for: element) else { return nil }
    if !op.clampsSpanCount {
        forms.count = { "\(referenceNothrowNamespace).spanCount(\($0[0]).count, laneCount)" }
    }
    let parameterBindings = bindings(of: op, for: element)
    let takesCountFromSpan = if case .first = op.span { true } else { false }
    forms.bridgeCall = { pointers, count in
        var remaining = pointers.makeIterator()
        var arguments: [String] = []
        for (binding, parameter) in zip(parameterBindings, op.parameters) {
            switch parameter {
            case .tag, .sourceTag, .narrowTag, .sourceNarrowTag:
                continue
            case .count where takesCountFromSpan:
                arguments.append(count)
            case _ where parameter.isPointer:
                arguments.append(remaining.next() ?? "")
            default:
                arguments.append(rawArgument(binding.swiftName, parameter, for: element))
            }
        }
        let call = referenceCall(
            referenceFunctionName(of: op, for: element),
            arguments,
            in: referenceNothrowNamespace
        )
        let result = referenceResult(
            call,
            returning: op.returns,
            for: element,
            on: element.namespace
        )
        return "unsafe \(result)"
    }
    return forms
}

func referenceSpanForms(of op: WideningOp, from narrow: Element, to wide: Element) -> SpanForms {
    var forms = spanForms(of: op, from: narrow, to: wide)
    forms.count = { "\(referenceNothrowNamespace).spanCount(\($0[0]).count, laneCount)" }
    let function = wideningFunctionName(op, from: narrow, to: wide)
    forms.bridgeCall = { pointers, count in
        let call = referenceCall(
            function,
            op.takesCount ? [pointers[0], count] : [pointers[0]],
            in: referenceNothrowNamespace
        )
        return "unsafe \(referenceResult(call, returning: .vector, for: wide, on: wide.namespace))"
    }
    return forms
}

/// Highway's ops behind the same span members as the port's, so that kernels take spans on both
/// sides.
func referenceSpanNamespace(of element: Element) -> String {
    """
    \(element.swiftAvailability.map { "\($0)\n" } ?? "")public enum \(referenceNamespace(of: element)) {
        public typealias Lane = \(element.swiftType)
        public typealias Vector = \(element.namespace).Vector
        public typealias Mask = \(element.namespace).Mask

        @export(implementation) @inline(always)
        public static var laneCount: Int {
            Int(\(referenceCall(referenceFunctionName("laneCount", element), [], in: referenceNothrowNamespace)))
        }
    }
    """
}

func referenceSpanMembers(of op: Op, for element: Element) -> [String] {
    guard !takesLookupIndices(op), !isOutsideProtocols(op),
        let forms = referenceSpanForms(of: op, for: element)
    else { return [] }
    var members = [spanMembers(forms)]
    if forms.isMutable && forms.appendsToOutput {
        members.append(outputSpanMembers(forms))
    }
    return members
}

struct KernelParameter {
    enum Kind {
        case vector
        case lane
        case pointer
        case count
        case span
        case byteSpan
        case outputSpan
    }

    let label: String
    let name: String
    let kind: Kind

    func type(on side: CodegenSide) -> String {
        switch kind {
        case .vector: return side.vector
        case .lane: return side.lane
        case .pointer: return side.pointer
        case .count: return "Int"
        case .span: return "Span<\(side.lane)>"
        case .byteSpan: return "Span<UInt8>"
        case .outputSpan: return "inout OutputSpan<\(side.lane)>"
        }
    }

    func declaration(on side: CodegenSide) -> String {
        let naming = label == name ? name : "\(label) \(name)"
        return "\(naming): \(type(on: side))"
    }

    func argument(passing expression: String) -> String {
        label == "_" ? expression : "\(label): \(expression)"
    }
}

struct CodegenKernel {
    let name: String
    let applies: Applies
    let returns: ReturnType
    let parameters: [KernelParameter]
    let body: (CodegenSide) -> String
    var usesSpans = false
}

func codegenBlockLoop(on side: CodegenSide, block: [String], remainder: [String]) -> String {
    """
    let laneCount = \(side.laneCount)
    var from = unsafe from
    var count = count
    while count >= laneCount {
    \(block.joined(separator: "\n"))
    unsafe from += laneCount
    count -= laneCount
    }
    if count > 0 {
    \(remainder.joined(separator: "\n"))
    }
    """
}

func codegenDigitValues(
    of vector: String,
    on side: CodegenSide
) -> (statements: [String], result: String) {
    let lettersExpression = side.call("subtracting", [vector, side.repeating("0x61")])
    let fromZero = side.call("subtracting", [vector, side.repeating("0x30")])
    let clamped = side.call("minimum", [fromZero, side.repeating("36")])
    let numbersExpression = side.call("adding", [clamped, side.repeating("26")])
    let isLetter = side.call("lessThan", ["letters", side.repeating("26")])
    return (
        ["let letters = \(lettersExpression)", "let numbers = \(numbersExpression)"],
        side.call("selecting", [isLetter, "letters", "numbers"])
    )
}

let utf8LookupTables: [(name: String, lanes: [Int])] = [
    ("byte1High", [2, 2, 2, 2, 2, 2, 2, 2, 128, 128, 128, 128, 33, 1, 21, 73]),
    ("byte1Low", [231, 163, 131, 131, 139, 203, 203, 203, 203, 203, 203, 203, 203, 219, 203, 203]),
    ("byte2High", [1, 1, 1, 1, 1, 1, 1, 1, 230, 174, 186, 186, 1, 1, 1, 1]),
]

func codegenSpanAdvance(_ span: String, by count: String, range: String) -> String {
    """
    let \(range) = unsafe Range<Int>(uncheckedBounds: (\(count), \(span).count))
    \(span) = unsafe \(span).extracting(unchecked: \(range))
    """
}

func codegenUTF8LookupErrors(on side: CodegenSide) -> (statements: [String], result: String) {
    let byte1High = side.call(
        "tableLookupBytes",
        ["byte1High", side.call("shiftedRight", ["prev1", "4"])]
    )
    let byte1Low = side.call(
        "tableLookupBytes",
        ["byte1Low", side.call("bitwiseAnd", ["prev1", side.repeating("0x0F")])]
    )
    let byte2High = side.call(
        "tableLookupBytes",
        ["byte2High", side.call("shiftedRight", ["input", "4"])]
    )
    let specialCases = side.call(
        "bitwiseAnd",
        [side.call("bitwiseAnd", [byte1High, byte1Low]), byte2High]
    )
    let continuations = side.call(
        "bitwiseOr",
        [
            side.call("saturatingSubtracting", ["prev2", side.repeating("0xE0 &- 0x80")]),
            side.call("saturatingSubtracting", ["prev3", side.repeating("0xF0 &- 0x80")]),
        ]
    )
    let mustBe23Continuation = side.call("bitwiseAnd", [continuations, side.repeating("0x80")])
    return (
        [
            "let specialCases = \(specialCases)",
            "let mustBe23Continuation = \(mustBe23Continuation)",
        ],
        side.call("bitwiseXor", ["mustBe23Continuation", "specialCases"])
    )
}

func codegenUTF8LookupWindow(
    of span: String,
    loading name: String,
    label: String,
    on side: CodegenSide
) -> [String] {
    var statements = ["let windowCount = \(span).count"]
    for (vector, offset) in [("input", 3), ("prev1", 2), ("prev2", 1)] {
        let window =
            "\(span).extracting(unchecked: Range(uncheckedBounds: (\(offset), windowCount)))"
        statements.append("let \(vector) = unsafe \(side.namespace).\(name)(\(label): \(window))")
    }
    let keyword = label == "fromUnchecked" ? "unsafe " : ""
    statements.append("let prev3 = \(keyword)\(side.namespace).\(name)(\(label): \(span))")
    return statements
}

let codegenKernels: [CodegenKernel] = [
    CodegenKernel(
        name: "MaskedLowercase",
        applies: .integer(bits: [8]),
        returns: .vector,
        parameters: [KernelParameter(label: "_", name: "v", kind: .vector)],
        body: { side in
            let offset = side.call("subtracting", ["v", side.repeating("0x41")])
            let isUppercase = side.call("lessThan", [offset, side.repeating("26")])
            let lowercaseBit = side.call("selectingOrZero", [isUppercase, side.repeating("0x20")])
            return "return \(side.call("bitwiseOr", ["v", lowercaseBit]))"
        }
    ),
    CodegenKernel(
        name: "DigitValues",
        applies: .unsigned(bits: [8]),
        returns: .vector,
        parameters: [KernelParameter(label: "_", name: "v", kind: .vector)],
        body: { side in
            let digits = codegenDigitValues(of: "v", on: side)
            return (digits.statements + ["return \(digits.result)"]).joined(separator: "\n")
        }
    ),
    CodegenKernel(
        name: "NoneAbove",
        applies: .integer,
        returns: .boolean,
        parameters: [KernelParameter(label: "_", name: "v", kind: .vector)],
        body: { side in
            let above = side.call("greaterThan", ["v", side.repeating("26")])
            return "return \(side.call("allFalse", [above]))"
        }
    ),
    CodegenKernel(
        name: "SmallestAtLeast",
        applies: .unsigned(bits: [32]),
        returns: .lane,
        parameters: [
            KernelParameter(label: "from", name: "from", kind: .pointer),
            KernelParameter(label: "count", name: "count", kind: .count),
            KernelParameter(label: "atLeast", name: "n", kind: .lane),
        ],
        body: { side in
            let candidates = side.call(
                "selecting",
                [side.call("lessThan", ["loaded", "threshold"]), "identity", "loaded"]
            )
            let accumulate = "accumulator = \(side.call("minimum", ["accumulator", candidates]))"
            let blockLoad = "let loaded = \(side.call("load", ["from"]))"
            let remainderLoad = "let loaded = \(side.call("loadFirst", ["from", "count"]))"
            let loop = codegenBlockLoop(
                on: side,
                block: [blockLoad, accumulate],
                remainder: [remainderLoad, accumulate]
            )
            return """
                let identity = \(side.repeating(".max"))
                let threshold = \(side.repeating("n"))
                var accumulator = identity
                \(loop)
                return \(side.call("smallest", ["accumulator"]))
                """
        }
    ),
    CodegenKernel(
        name: "LargestDigit",
        applies: .unsigned(bits: [8]),
        returns: .boolean,
        parameters: [
            KernelParameter(label: "from", name: "from", kind: .pointer),
            KernelParameter(label: "count", name: "count", kind: .count),
        ],
        body: { side in
            let digits = codegenDigitValues(of: "loaded", on: side)
            let blockLoad = "let loaded = \(side.call("load", ["from"]))"
            let blockMaximum = "largest = \(side.call("maximum", ["largest", digits.result]))"
            let remainderLoad = "let loaded = \(side.call("loadFirst", ["from", "count"]))"
            let remainderDigits = side.call(
                "selectingOrZero",
                [side.call("firstLanes", ["count"]), digits.result]
            )
            let remainderMaximum = "largest = \(side.call("maximum", ["largest", remainderDigits]))"
            let loop = codegenBlockLoop(
                on: side,
                block: [blockLoad] + digits.statements + [blockMaximum],
                remainder: [remainderLoad] + digits.statements + [remainderMaximum]
            )
            let aboveDigits = side.call("greaterThan", ["largest", side.repeating("35")])
            return """
                var largest = \(side.call("zero", []))
                \(loop)
                return \(side.call("allFalse", [aboveDigits]))
                """
        }
    ),
    CodegenKernel(
        name: "UTF8LookupStep",
        applies: .unsigned(bits: [8]),
        returns: .vector,
        parameters: [KernelParameter(label: "_", name: "input", kind: .vector)],
        body: { side in
            let tables = utf8LookupTables.map { table in
                "let \(table.name) = \(side.repeatingBlock(table.lanes.map(String.init)))"
            }
            let slides = [
                "let prev1 = \(side.call("slide1Up", ["input"]))",
                "let prev2 = \(side.call("slideUpLanes", ["input", "2"]))",
                "let prev3 = \(side.call("slideUpLanes", ["input", "3"]))",
            ]
            let prev1High = side.call(
                "tableLookupBytes",
                ["byte1High", side.call("shiftedRight", ["prev1", "4"])]
            )
            let prev1Low = side.call(
                "tableLookupBytes",
                ["byte1Low", side.call("bitwiseAnd", ["prev1", side.repeating("0x0F")])]
            )
            let inputHigh = side.call(
                "tableLookupBytes",
                ["byte2High", side.call("shiftedRight", ["input", "4"])]
            )
            let special = side.call(
                "bitwiseAnd",
                [side.call("bitwiseAnd", [prev1High, prev1Low]), inputHigh]
            )
            let continuations = side.call(
                "bitwiseOr",
                [
                    side.call("saturatingSubtracting", ["prev2", side.repeating("0x60")]),
                    side.call("saturatingSubtracting", ["prev3", side.repeating("0x70")]),
                ]
            )
            let result = side.call("bitwiseXor", [special, continuations])
            return (tables + slides + ["return \(result)"]).joined(separator: "\n")
        }
    ),
    CodegenKernel(
        name: "SmallestAtLeastSpan",
        applies: .unsigned(bits: [32]),
        returns: .lane,
        parameters: [
            KernelParameter(label: "atLeast", name: "n", kind: .lane),
            KernelParameter(label: "in", name: "values", kind: .span),
        ],
        body: { side in
            let isBelow = "let isBelow = \(side.call("lessThan", ["loaded", "threshold"]))"
            let candidates = side.call("selecting", ["isBelow", "identity", "loaded"])
            let accumulate = "accumulator = \(side.call("minimum", ["accumulator", candidates]))"
            let advance = codegenSpanAdvance(
                "remainingValuesSpan",
                by: "laneCount",
                range: "remainingValuesRange"
            )
            return """
                let laneCount = \(side.laneCount)
                let identity = \(side.repeating(".max"))
                let threshold = \(side.repeating("n"))
                var accumulator = identity

                var remainingValuesSpan = values
                while remainingValuesSpan.count >= laneCount {
                let loaded = \(side.namespace).load(from: remainingValuesSpan)
                \(isBelow)
                \(accumulate)
                \(advance)
                }
                if !remainingValuesSpan.isEmpty {
                let loaded = \(side.namespace).loadFirst(from: remainingValuesSpan)
                \(isBelow)
                \(accumulate)
                }
                return \(side.call("smallest", ["accumulator"]))
                """
        },
        usesSpans: true
    ),
    CodegenKernel(
        name: "LargestDigitSpan",
        applies: .unsigned(bits: [8]),
        returns: .boolean,
        parameters: [KernelParameter(label: "_", name: "inputBytesSpan", kind: .span)],
        body: { side in
            let digits = codegenDigitValues(of: "loaded", on: side)
            let firstDigits = side.call(
                "selectingOrZero",
                [side.call("firstLanes", ["remaining"]), digits.result]
            )
            let advance = codegenSpanAdvance(
                "remainingBytesSpan",
                by: "laneCount",
                range: "remainingBytesRange"
            )
            let aboveDigits = side.call("greaterThan", ["largestDigit", side.repeating("35")])
            return """
                let count = inputBytesSpan.count
                guard count > 0 else {
                return true
                }

                let laneCount = \(side.laneCount)
                var remainingBytesSpan = inputBytesSpan
                var largestDigit = \(side.call("zero", []))
                while remainingBytesSpan.count >= laneCount {
                let loaded = \(side.namespace).load(from: remainingBytesSpan)
                \(digits.statements.joined(separator: "\n"))
                largestDigit = \(side.call("maximum", ["largestDigit", digits.result]))
                \(advance)
                }
                if !remainingBytesSpan.isEmpty {
                let remaining = remainingBytesSpan.count
                let loaded = \(side.namespace).loadFirst(from: remainingBytesSpan)
                \(digits.statements.joined(separator: "\n"))
                largestDigit = \(side.call("maximum", ["largestDigit", firstDigits]))
                }
                return \(side.call("allFalse", [aboveDigits]))
                """
        },
        usesSpans: true
    ),
    CodegenKernel(
        name: "MaskedLowercaseSpan",
        applies: .unsigned(bits: [8]),
        returns: .count,
        parameters: [
            KernelParameter(label: "span", name: "span", kind: .span),
            KernelParameter(label: "into", name: "output", kind: .outputSpan),
        ],
        body: { side in
            let isASCII = side.call(
                "allFalse",
                [side.call("greaterThan", ["window", side.repeating("0x7F")])]
            )
            let isUppercasedLetter = side.call(
                "lessThan",
                [
                    side.call("subtracting", ["window", side.repeating("0x41")]),
                    side.repeating("26"),
                ]
            )
            let lowercaseBit = side.call(
                "selectingOrZero",
                ["isUppercasedLetter", side.repeating("0b0010_0000")]
            )
            let advance = codegenSpanAdvance(
                "remainingBytesSpan",
                by: "windowLength",
                range: "remainingBytesRange"
            )
            return """
                let laneCount = \(side.laneCount)
                var remainingBytesSpan = span
                while !remainingBytesSpan.isEmpty {
                let windowLength = min(laneCount, remainingBytesSpan.count)
                let window =
                if windowLength == laneCount {
                \(side.namespace).load(from: remainingBytesSpan)
                } else {
                \(side.namespace).loadFirst(from: remainingBytesSpan)
                }
                if \(isASCII) {
                let isUppercasedLetter = \(isUppercasedLetter)
                let lowercased = \(side.call("bitwiseOr", ["window", lowercaseBit]))
                if windowLength == laneCount {
                unsafe \(side.namespace).append(lowercased, toUnchecked: &output)
                } else {
                unsafe \(side.namespace).append(
                lowercased,
                addingCount: windowLength,
                toUnchecked: &output
                )
                }
                \(advance)
                continue
                }
                break
                }
                return remainingBytesSpan.count
                """
        },
        usesSpans: true
    ),
    CodegenKernel(
        name: "UTF8LookupSpan",
        applies: .unsigned(bits: [8]),
        returns: .boolean,
        parameters: [KernelParameter(label: "_", name: "bytes", kind: .span)],
        body: { side in
            let tables = utf8LookupTables.map { table in
                "let \(table.name) = \(side.repeatingBlock(table.lanes.map(String.init)))"
            }
            let errors = codegenUTF8LookupErrors(on: side)
            let head = [
                "let input = headBytes",
                "let prev1 = \(side.call("slide1Up", ["headBytes"]))",
                "let prev2 = \(side.call("slideUpLanes", ["headBytes", "2"]))",
                "let prev3 = \(side.call("slideUpLanes", ["headBytes", "3"]))",
            ]
            let window = codegenUTF8LookupWindow(
                of: "remainingBytesSpan",
                loading: "load",
                label: "fromUnchecked",
                on: side
            )
            let lastWindow = codegenUTF8LookupWindow(
                of: "remainingBytesSpan",
                loading: "loadFirst",
                label: "from",
                on: side
            )
            let accumulate = "errors = \(side.call("bitwiseOr", ["errors", errors.result]))"
            let advance = codegenSpanAdvance(
                "remainingBytesSpan",
                by: "laneCount",
                range: "remainingBytesRange"
            )
            let hasErrors = side.call("notEqualTo", ["errors", side.call("zero", [])])
            return """
                let count = bytes.count
                guard count > 0 else {
                return true
                }

                let laneCount = \(side.laneCount)
                guard _fastPath(laneCount >= 16) else {
                return false
                }

                \(tables.joined(separator: "\n"))
                let headBytes = \(side.namespace).loadFirst(from: bytes)
                \((head + errors.statements).joined(separator: "\n"))
                var errors = \(errors.result)

                if count > laneCount {
                var remainingBytesSpan = unsafe bytes.extracting(
                unchecked: Range<Int>(uncheckedBounds: (laneCount &- 3, count))
                )
                while remainingBytesSpan.count >= laneCount &+ 3 {
                \((window + errors.statements).joined(separator: "\n"))
                \(accumulate)
                \(advance)
                }
                if remainingBytesSpan.count > 3 {
                \((lastWindow + errors.statements).joined(separator: "\n"))
                \(accumulate)
                }
                }

                if count >= 3 {
                let last = unsafe bytes[unchecked: count &- 1]
                let secondToLast = unsafe bytes[unchecked: count &- 2]
                let thirdToLast = unsafe bytes[unchecked: count &- 3]
                if last >= 0xC0 || secondToLast >= 0xE0 || thirdToLast >= 0xF0 {
                return false
                }
                }

                return \(side.call("allFalse", [hasErrors]))
                """
        },
        usesSpans: true
    ),
    CodegenKernel(
        name: "SumWideningSpan",
        applies: .unsigned(bits: [32]),
        returns: .lane,
        parameters: [KernelParameter(label: "_", name: "bytes", kind: .byteSpan)],
        body: { side in
            let advance = codegenSpanAdvance(
                "remainingBytesSpan",
                by: "laneCount",
                range: "remainingBytesRange"
            )
            let widened = "\(side.namespace).loadWidening(from: remainingBytesSpan)"
            let firstWidened = "\(side.namespace).loadFirstWidening(from: remainingBytesSpan)"
            return """
                let laneCount = \(side.laneCount)
                var total = \(side.call("zero", []))
                var remainingBytesSpan = bytes
                while remainingBytesSpan.count >= laneCount {
                total = \(side.call("adding", ["total", widened]))
                \(advance)
                }
                if !remainingBytesSpan.isEmpty {
                total = \(side.call("adding", ["total", firstWidened]))
                }
                return \(side.call("sum", ["total"]))
                """
        },
        usesSpans: true
    ),
]

func codegenKernelFunctions(_ kernel: CodegenKernel, for element: Element) -> String {
    let referenceName = referenceFunctionName(kernel.name, element)
    let functions = [CodegenSide.Kind.port, .highway].map { kind in
        let side = CodegenSide(kind: kind, element: element)
        let function = codegenFunction(
            codegenFunctionName(kind.rawValue, referenceName),
            parameters: kernel.parameters.map { $0.declaration(on: side) },
            returnClause: " -> \(side.returnType(kernel.returns))",
            call: kernel.body(side)
        )
        return kernel.usesSpans ? "\(spanAvailability)\n\(function)" : function
    }
    return functions.joined(separator: "\n\n")
}

func codegenKeys(of kernel: CodegenKernel, for element: Element) -> [String] {
    [codegenKey(referenceFunctionName(kernel.name, element))]
}

func codegenCalls(
    of parameters: [CodegenParameter],
    for element: Element,
    referenceName: String,
    constant: Int?,
    alternative: CodegenImmediate? = nil,
    keyword: String,
    pointer: String,
    referencePointer: String? = nil,
    destination: String? = nil,
    highwayCount: String? = nil
) -> (port: String, reference: String) {
    var portArguments: [String] = []
    var referenceArguments: [String] = []
    var outVectorIndex = 0

    let constantIndices = codegenConstantIndices(of: parameters, variant: constant)
    for (index, parameter) in parameters.enumerated() where !constantIndices.contains(index) {
        let binding = parameter.binding
        switch parameter.kind {
        case .tag, .sourceTag, .narrowTag, .sourceNarrowTag:
            continue
        case .vector, .shiftCounts, .indices, .laneIndices, .lookupIndices, .indexVector, .mask,
            .fillVector, .whereMask, .otherwiseVector, .lane, .insertedLane, .fillLane,
            .laneAmount, .roundConstant, .immediate, .flag, .maskBits, .laneIndex, .tuple,
            .tupleIndex, .pointerIndices, .pointerOffsets, .sourceVector, .signedSourceVector,
            .sourceMask, .narrowVector, .sourceNarrowVector, .narrowMask, .sourceNarrowMask:
            portArguments.append(swiftCallArgument(binding))
            referenceArguments.append(swiftCallArgument(binding))
        case .count:
            portArguments.append(swiftCallArgument(binding))
            referenceArguments.append(swiftCallArgument(binding, passing: highwayCount))
        case .shiftAmount:
            let amount = swiftArgument(binding, parameter.kind, for: element)
            portArguments.append(swiftCallArgument(binding, passing: amount))
            referenceArguments.append(swiftCallArgument(binding, passing: amount))
        case .constLanePointer, .lanePointer, .constBytePointer, .bytePointer, .constBitsPointer,
            .constIndexPointer, .narrowLanePointer:
            let operand = parameter.kind.isMutablePointer ? destination ?? pointer : pointer
            portArguments.append(swiftCallArgument(binding, passing: operand))
            referenceArguments.append(
                swiftCallArgument(
                    binding,
                    passing: parameter.kind.isMutablePointer ? operand : referencePointer ?? operand
                )
            )
        case .outVector:
            portArguments.append(swiftCallArgument(binding, passing: "p\(outVectorIndex)"))
            referenceArguments.append(swiftCallArgument(binding, passing: "r\(outVectorIndex)"))
            outVectorIndex += 1
        }
    }

    let constantName = codegenConstantName(
        of: parameters,
        constant: constant,
        alternative: alternative
    )
    func call(_ side: String, _ arguments: [String]) -> String {
        let name = codegenFunctionName(side, referenceName, constantParameter: constantName)
        return "\(keyword)\(name)(\(arguments.joined(separator: ", ")))"
    }
    return (call("port", portArguments), call("highway", referenceArguments))
}

func codegenGuardedCount(
    of parameters: [CodegenParameter],
    for element: Element,
    constant: Int?
) -> String {
    guard let constant, parameters[constant].kind == .count,
        let value = codegenConstant(of: .count, for: element)
    else { return "count" }
    return value.port
}

func referenceLoopCondition(
    of op: Op,
    for element: Element,
    inputs: [ReferenceInput]
) -> String? {
    let condition = unorderedNaNsCondition(of: op, for: element, inputs: inputs)
    guard !op.filtersUnorderedNaNs else { return condition }
    guard element.category == .float16 else { return nil }
    return condition.map { "HighwayReference.hasNativeFloat16Arithmetic() || \($0)" }
}

func unorderedNaNsCondition(
    of op: Op,
    for element: Element,
    inputs: [ReferenceInput]
) -> String? {
    unorderedNaNsCondition(
        of: op,
        for: element,
        vectors: inputs.filter {
            [.vector, .sourceVector].contains($0.parameter)
                || (op.unorderedNaNs?.isWidened == true && $0.parameter == .outVector)
        }.map(\.name),
        sources: inputs.filter { $0.parameter == .sourceVector }.map(\.name)
    )
}

func codegenUnorderedNaNsCondition(
    of op: Op,
    for element: Element,
    parameters: [CodegenParameter],
    constants: Set<Int>,
    inputs: [ReferenceInput]
) -> String? {
    guard op.unorderedNaNs?.isWidened == true else {
        return unorderedNaNsCondition(of: op, for: element, inputs: inputs)
    }
    let operands = parameters.indices.compactMap { index -> (name: String, kind: Parameter)? in
        let parameter = parameters[index]
        guard [.vector, .sourceVector, .outVector].contains(parameter.kind) else { return nil }
        let constant =
            constants.contains(index)
            ? codegenConstant(of: parameter.kind, source: parameter.source, for: element)?.port
            : nil
        return (constant ?? parameter.binding.swiftName, parameter.kind)
    }
    return unorderedNaNsCondition(
        of: op,
        for: element,
        vectors: operands.map(\.name),
        sources: operands.filter { $0.kind == .sourceVector }.map(\.name)
    )
}

func unorderedNaNsCondition(
    of op: Op,
    for element: Element,
    vectors: [String],
    sources: [String]
) -> String? {
    guard element.category == .float || element.category == .float16,
        let unorderedNaNs = op.unorderedNaNs
    else { return nil }
    let multiplicands = vectors.filter { $0 != "c" }.joined(separator: ", ")
    let hasAddend = vectors.contains("c")
    let accumulators = vectors.filter { !sources.contains($0) }
    switch (unorderedNaNs, vectors.count) {
    case (.perLane, 2), (.perLane, 3), (.multiplyAdd, 2):
        return "!hasUnorderedNaNs(\(vectors.joined(separator: ", ")))"
    case (.negatedAddend, 2) where hasAddend:
        return "!hasUnorderedNaNs(\(multiplicands), negatedLanes(of: c))"
    case (.alternatingAddend, 2) where hasAddend:
        return "!hasUnorderedNaNs(alternatingNegation: \(multiplicands), c)"
    case (.alternatingNegatedAddend, 2) where hasAddend:
        return "!hasUnorderedNaNs(alternatingNegation: \(multiplicands), negatedLanes(of: c))"
    case (.negatedAddend, 2), (.alternatingAddend, 2), (.alternatingNegatedAddend, 2):
        return "!hasUnorderedNaNs(\(vectors.joined(separator: ", ")))"
    case (.adjacentLanes, _):
        return "!hasUnorderedNaNs(adjacentLanesOf: \(vectors.joined(separator: ", ")))"
    case (.alternatingNegation, 2):
        return "!hasUnorderedNaNs(alternatingNegation: \(vectors.joined(separator: ", ")))"
    case (.alternatingNegation, 1):
        return nil
    case (.multiplyAdd, 3), (.negatedAddend, 3), (.alternatingAddend, 3),
        (.alternatingNegatedAddend, 3):
        return "!hasUnorderedNaNs(multiplying: \(vectors[0]), \(vectors[1]), adding: \(vectors[2]))"
    case (.negatedMultiplicand, 3):
        return "!hasUnorderedNaNs(negating: \(vectors[0]), \(vectors[1]), adding: \(vectors[2]))"
    case (.negatedMultiplicand, 2):
        return "!hasNaNs(in: \(vectors.filter { $0 != "c" }.joined(separator: ", ")))"
    case (.acrossLanes, 1):
        return "!hasUnorderedNaNs(lanesOf: \(vectors[0]))"
    case (.complexLanes, _):
        return "!hasUnorderedNaNs(complexLanesOf: \(vectors.joined(separator: ", ")))"
    case (.widenedPairs, _) where sources.count == 2:
        return "!hasUnorderedNaNs(widening: \(sources[0]), \(sources[1]))"
    case (.widenedEven, _) where sources.count == 2 && accumulators.count == 1,
        (.widenedOdd, _) where sources.count == 2 && accumulators.count == 1:
        let parity = unorderedNaNs == .widenedEven ? 0 : 1
        return
            "!hasUnorderedNaNs(widening: \(sources[0]), \(sources[1]), parity: \(parity), adding: \(accumulators[0]))"
    case (.widenedAccumulating, _) where sources.count == 2 && accumulators.count == 2:
        return
            "!hasUnorderedNaNs(widening: \(sources[0]), \(sources[1]), accumulating: \(accumulators[0]), \(accumulators[1]))"
    default:
        return nil
    }
}

func codegenTest(
    of op: Op,
    for element: Element,
    constant: Int?,
    alternative: CodegenImmediate? = nil,
    guarded: Bool = false
) -> String {
    let parameters = codegenParameters(of: op, for: element)
    let constantName = codegenConstantName(
        of: parameters,
        constant: constant,
        alternative: alternative
    )
    let name = "\(op.testIdentifier)\(codegenConstantSuffix(constantName))"
    let test = guarded ? "\(name)BeforeGuardPage" : name
    let referenceName = referenceFunctionName(of: op, for: element)
    let function = codegenFunctionName("port", referenceName, constantParameter: constantName)
    let constants = codegenConstantIndices(of: parameters, variant: constant)
    let constantNames = constants.map { parameters[$0].binding.swiftName }
    let inputs = referenceInputs(
        of: op,
        for: element,
        test: test,
        inContract: true,
        guarded: guarded
    )
    .filter { !constantNames.contains($0.name) }
    let calls = codegenCalls(
        of: parameters,
        for: element,
        referenceName: referenceName,
        constant: constant,
        alternative: alternative,
        keyword: isUnsafe(op) ? "unsafe " : "",
        pointer: referencePointer(of: op, guarded: guarded),
        referencePointer: paddedPointer(of: op),
        destination: referenceDestination(of: op, guarded: guarded)
    )
    let (declarations, statements) = referenceStatements(
        of: op,
        for: element,
        inputs: inputs,
        guarded: guarded,
        count: codegenGuardedCount(of: parameters, for: element, constant: constant),
        calls: calls
    )

    return referenceTestFunction(
        test,
        label: guarded ? "\(function) before a guard page" : function,
        for: element,
        inputs: inputs,
        declarations: declarations,
        disabling: laneCapabilityDisabling(of: op, for: element),
        loopCondition: codegenUnorderedNaNsCondition(
            of: op,
            for: element,
            parameters: parameters,
            constants: constants,
            inputs: inputs
        ),
        statements: statements
    )
}

func codegenWideningTest(
    _ op: WideningOp,
    from narrow: Element,
    to wide: Element,
    constant: Int?,
    guarded: Bool = false
) -> String {
    let parameters = codegenParameters(of: op, from: narrow)
    let constantName = constant.map { parameters[$0].binding.swiftName }
    let name = "\(op.swiftName)From\(narrow.swiftType)\(codegenConstantSuffix(constantName))"
    let test = guarded ? "\(name)BeforeGuardPage" : name
    let referenceName = wideningFunctionName(op, from: narrow, to: wide)
    let function = codegenFunctionName("port", referenceName, constantParameter: constantName)
    let seed = "seed: \(referenceTestSeed(wide, test, "0"))"
    var inputs = [
        ReferenceInput(
            parameter: .constLanePointer,
            name: "from",
            values: "Inputs.buffers(\(narrow.swiftType).self, count: H.laneCount, \(seed))"
        )
    ]
    if op.takesCount && constant == nil {
        inputs.append(
            ReferenceInput(
                parameter: .count,
                name: "count",
                values: "Inputs.bufferCounts(lanes: H.laneCount)"
            )
        )
    }
    let calls = codegenCalls(
        of: parameters,
        for: wide,
        referenceName: referenceName,
        constant: constant,
        keyword: "unsafe ",
        pointer: pointerExpression("source", aligned: guarded),
        highwayCount: guarded ? "min(count, H.laneCount)" : nil
    )
    let count = codegenGuardedCount(of: parameters, for: wide, constant: constant)

    return referenceTestFunction(
        test,
        label: guarded ? "\(function) before a guard page" : function,
        for: wide,
        inputs: inputs,
        statements: referenceLoadStatements(
            of: "from",
            aligned: false,
            guardedLanes: guarded ? guardedLanes(of: "from", extent: op.span, count: count) : nil,
            port: calls.port,
            reference: calls.reference,
            description: referenceDescription(of: inputs)
        )
    )
}

func codegenRebindingTest(
    _ op: RebindingOp,
    from source: Element,
    to target: Element
) -> String {
    let test = "\(op.swiftName)\(uppercasedFirst(op.label))From\(source.swiftType)"
    let referenceName = rebindingFunctionName(op, from: source, to: target)
    let function = codegenFunctionName("port", referenceName)
    let seed = "seed: \(referenceTestSeed(target, test, "0"))"
    let inputs = [
        ReferenceInput(
            parameter: .mask,
            name: "mask",
            values: "Inputs.masks(\(source.namespace).Mask.self, \(seed))"
        )
    ]
    let calls = codegenCalls(
        of: codegenParameters(of: op, from: source),
        for: target,
        referenceName: referenceName,
        constant: nil,
        keyword: "",
        pointer: ""
    )
    return referenceTestFunction(
        test,
        label: function,
        for: target,
        inputs: inputs,
        statements:
            "mismatches.check(\(calls.port), \(calls.reference), \(referenceDescription(of: inputs)))"
    )
}

func codegenRepeatingBlockTest(for element: Element) -> String {
    let seed = "seed: \(referenceTestSeed(element, repeatingBlockName, "0"))"
    let vectors = ReferenceInput(
        parameter: .vector,
        name: "vector",
        values: "Inputs.vectors(H.Vector.self, \(seed))"
    )
    let lanes = repeatingBlockLanes(of: element).indices
        .map { element.swiftLane(fromSimd: "\(simdVector("vector", of: element))[\($0)]") }
        .joined(separator: ", ")
    let referenceName = referenceFunctionName(repeatingBlockName, element)
    let function = codegenFunctionName("port", referenceName)
    let port = "\(function)(\(lanes))"
    let reference = "\(codegenFunctionName("highway", referenceName))(\(lanes))"
    let description = "\"lanes: \\(describe(vector))\""
    return referenceTestFunction(
        repeatingBlockName,
        label: function,
        for: element,
        inputs: [vectors],
        statements: "mismatches.check(\(port), \(reference), \(description))"
    )
}

let codegenKernelLength = "3 * H.laneCount + 1"

func lowercasedFirstWord(_ name: String) -> String {
    let uppercase = name.prefix { $0.isUppercase }
    let followedByLowercase = name.dropFirst(uppercase.count).first?.isLowercase == true
    let count = max(uppercase.count - (followedByLowercase ? 1 : 0), 1)
    return name.prefix(count).lowercased() + name.dropFirst(count)
}

func codegenKernelInputs(
    of kernel: CodegenKernel,
    for element: Element,
    test: String
) -> [ReferenceInput] {
    var inputs: [ReferenceInput] = []
    let counts = "Inputs.counts(through: \(codegenKernelLength))"
    for parameter in kernel.parameters {
        let seed = "seed: \(referenceTestSeed(element, test, String(inputs.count)))"
        switch parameter.kind {
        case .vector:
            let values = "Inputs.vectors(H.Vector.self, \(seed))"
            inputs.append(ReferenceInput(parameter: .vector, name: parameter.name, values: values))
        case .lane:
            let values = "Inputs.lanes(H.Lane.self, \(seed))"
            inputs.append(ReferenceInput(parameter: .lane, name: parameter.name, values: values))
        case .pointer, .span, .byteSpan:
            let isBytes = element.bits == 8 || parameter.kind == .byteSpan
            let values =
                isBytes
                ? "Inputs.byteBuffers(count: \(codegenKernelLength), \(seed))"
                : "Inputs.buffers(H.Lane.self, count: \(codegenKernelLength), \(seed))"
            inputs.append(
                ReferenceInput(parameter: .constLanePointer, name: parameter.name, values: values)
            )
            if parameter.kind != .pointer {
                inputs.append(
                    ReferenceInput(
                        parameter: .count,
                        name: "\(parameter.name)Count",
                        values: counts
                    )
                )
            }
        case .count:
            inputs.append(ReferenceInput(parameter: .count, name: parameter.name, values: counts))
        case .outputSpan:
            continue
        }
    }
    return inputs.filter { $0.parameter != .lane } + inputs.filter { $0.parameter == .lane }
}

func codegenKernelTest(
    _ kernel: CodegenKernel,
    for element: Element,
    guarded: Bool = false
) -> String {
    let name = lowercasedFirstWord(kernel.name)
    let test = guarded ? "\(name)BeforeGuardPage" : name
    let referenceName = referenceFunctionName(kernel.name, element)
    let function = codegenFunctionName("port", referenceName)
    let inputs = codegenKernelInputs(of: kernel, for: element, test: test)
    let description = referenceDescription(of: inputs)
    let spans = kernel.parameters.filter { $0.kind == .span || $0.kind == .byteSpan }
    let pointer = kernel.parameters.first { $0.kind == .pointer }
    let arguments = kernel.parameters.map { parameter in
        switch parameter.kind {
        case .vector, .lane, .count: return parameter.argument(passing: parameter.name)
        case .pointer:
            return parameter.argument(passing: pointerExpression("source", aligned: guarded))
        case .span, .byteSpan: return parameter.argument(passing: "\(parameter.name)Prefix.span")
        case .outputSpan: return parameter.argument(passing: "&output")
        }
    }
    let keyword = pointer == nil ? "" : "unsafe "
    let calls = ["port", "highway"].map {
        "\(keyword)\(codegenFunctionName($0, referenceName))(\(arguments.joined(separator: ", ")))"
    }

    var statements = spans.map {
        "let \($0.name)Prefix = ContiguousArray(\($0.name).prefix(\($0.name)Count))"
    }
    if let pointer {
        statements.append(
            referenceLoadStatements(
                of: pointer.name,
                aligned: false,
                guardedLanes: guarded ? guardedLanes(of: pointer.name, extent: .first) : nil,
                port: calls[0],
                reference: calls[1],
                description: description
            )
        )
    } else if kernel.parameters.contains(where: { $0.kind == .outputSpan }) {
        let capacity = "\(spans[0].name)Prefix.count"
        statements += [("port", calls[0]), ("reference", calls[1])].map { side, call in
            """
            let (\(side)Result, \(side)Lanes) = withOutputSpan(capacity: \(capacity)) { output in
            \(call)
            }
            """
        }
        statements.append("mismatches.check(portResult, referenceResult, \(description))")
        statements.append("mismatches.check(portLanes, referenceLanes, \(description))")
    } else {
        statements.append("mismatches.check(\(calls[0]), \(calls[1]), \(description))")
    }

    return referenceTestFunction(
        test,
        label: guarded ? "\(function) before a guard page" : function,
        for: element,
        inputs: inputs,
        statements: statements.joined(separator: "\n")
    )
}

func codegenTests(of op: Op, for element: Element) -> [String] {
    var tests: [String] = []
    let parameters = codegenParameters(of: op, for: element)
    for variant in codegenVariants(of: parameters, for: element) {
        tests.append(
            codegenTest(
                of: op,
                for: element,
                constant: variant.constant,
                alternative: variant.alternative
            )
        )
        if op.span != nil {
            tests.append(
                codegenTest(
                    of: op,
                    for: element,
                    constant: variant.constant,
                    alternative: variant.alternative,
                    guarded: true
                )
            )
        }
    }
    return tests
}

func codegenWideningTests(_ op: WideningOp, from narrow: Element, to wide: Element) -> [String] {
    var tests: [String] = []
    let parameters = codegenParameters(of: op, from: narrow)
    for variant in codegenVariants(of: parameters, for: wide) {
        for guarded in [false, true] {
            tests.append(
                codegenWideningTest(
                    op,
                    from: narrow,
                    to: wide,
                    constant: variant.constant,
                    guarded: guarded
                )
            )
        }
    }
    return tests
}

func codegenKernelTests(_ kernel: CodegenKernel, for element: Element) -> [String] {
    var tests = [codegenKernelTest(kernel, for: element)]
    if kernel.parameters.contains(where: { $0.kind == .pointer }) {
        tests.append(codegenKernelTest(kernel, for: element, guarded: true))
    }
    return tests
}

func generateCodegenTestMembers(_ element: Element, by keys: Set<String>?) -> [SectionMember] {
    var members = testedOps(for: element, by: keys).map {
        SectionMember(
            section: $0.section,
            inside: markingKnownGaps(
                guarded(codegenTests(of: $0, for: element), op: $0, in: element, testing: true),
                suite: "\(element.namespace)Codegen"
            )
        )
    }
    members += wideningOps.map { op in
        let tests = testedWideningSources(of: op, for: element, by: keys).flatMap {
            codegenWideningTests(op, from: $0, to: element)
        }
        return SectionMember(section: op.section, inside: tests)
    }
    members += rebindingOps.map { op in
        let tests = testedRebindingSources(of: op, for: element, by: keys).map {
            guarded(
                codegenRebindingTest(op, from: $0, to: element),
                rebinding: $0,
                to: element,
                testing: true
            )
        }
        return SectionMember(section: op.section, inside: tests)
    }
    if isTested(repeatingBlockCodegenKeys(for: element), by: keys) {
        members.append(
            SectionMember(
                section: .initialization,
                inside: [codegenRepeatingBlockTest(for: element)]
            )
        )
    }
    members += testedKernels(for: element, by: keys).map {
        SectionMember(section: .kernels, inside: codegenKernelTests($0, for: element))
    }
    return members
}

let codegenTestImports = """
    import CHighwayReference
    import HighwayReferenceCodegen
    import HighwayReferenceTestSupport
    import Testing
    import Vectorization
    """

func generateCodegenTests(_ element: Element) -> String {
    """
    \(generationNotice)

    \(codegenTestImports)

    @Suite("\(element.namespace) codegen against Highway")
    struct \(element.namespace)CodegenTests {
        typealias H = \(element.namespace)
    }

    """
}

struct ConstantValue {
    let name: String
    let literal: String
}

let constantMarkers = [
    "__builtin_constant_p(",
    "cvectorization_ops_sve_splat_",
    "cvectorization_ops_sve_constant_",
    "cvectorization_ops_constant_nan_",
    "cvectorization_ops_constant_lane_",
]

func headerFunctions(of header: String) -> [String: String] {
    var functions: [String: String] = [:]
    var current: String?
    for line in header.split(separator: "\n", omittingEmptySubsequences: false) {
        if current == nil {
            guard
                line.hasPrefix("CVECTORIZATION_OPS_INLINE")
                    || line.hasPrefix("CVECTORIZATION_OPS_FUNCTION"),
                let open = line.firstIndex(of: "("),
                let name = line[..<open].split(separator: " ").last
            else { continue }
            current = String(name)
        }
        if let name = current {
            functions[name, default: ""] += "\(line)\n"
            if line == "}" {
                current = nil
            }
        }
    }
    return functions
}

func parenthesizedArgument(in text: Substring) -> (argument: Substring, rest: Substring)? {
    var depth = 1
    for index in text.indices {
        switch text[index] {
        case "(":
            depth += 1
        case ")":
            depth -= 1
            if depth == 0 {
                return (text[..<index], text[text.index(after: index)...])
            }
        default:
            break
        }
    }
    return nil
}

func constantIdentifiers(in source: String) -> Set<String> {
    var identifiers: Set<String> = []
    for marker in constantMarkers {
        var remainder = source[...]
        while let range = remainder.range(of: marker) {
            remainder = remainder[range.upperBound...]
            if !marker.hasSuffix("(") {
                guard let open = remainder.firstIndex(of: "(") else { break }
                remainder = remainder[remainder.index(after: open)...]
            }
            guard let (argument, rest) = parenthesizedArgument(in: remainder) else { break }
            identifiers.formUnion(
                argument.split { !($0.isLetter || $0.isNumber || $0 == "_") }.map(String.init)
            )
            remainder = rest
        }
    }
    return identifiers
}

func constantSource(ofFunctionNamed name: String) -> String {
    let prefix = "cvectorization_ops_"
    guard name.hasPrefix(prefix) else { fatalError("\(name) is not a function of the header") }
    return ["", "neon_", "x86_"].compactMap { helper in
        generatedFunctions["\(prefix)\(helper)\(name.dropFirst(prefix.count))"]
    }.joined()
}

func constantParameters(of op: Op, for element: Element) -> [Int] {
    let functions =
        [cFunctionName(of: op, for: element)]
        + (op.template == nil ? [] : [templatedHelperName(of: op, for: element)])
    let identifiers = constantIdentifiers(
        in: functions.map(constantSource(ofFunctionNamed:)).joined()
    )
    return zip(bindings(of: op, for: element), op.parameters).enumerated().compactMap {
        index,
        pair in
        let operand = operandElement(of: pair.1, for: element, source: op.source)
        let isFloatOperand =
            (operand.category == .float || operand.isHalfPrecision) && isConstantVector(pair.1)
            && !pair.1.isPointerIndices
        let isTemplated = op.template != nil && pair.1 == .shiftAmount
        return isFloatOperand || isTemplated
            || (!pair.1.isTag && identifiers.contains(pair.0.swiftName))
            ? index : nil
    }
}

func constantCounts(spanned: Bool, for element: Element) -> [Int] {
    let laneCounts = [16, 32, 64].map { element.at(width: $0).laneCount }
    let beyond32Bits = laneCounts.flatMap { [1 << 32, (1 << 32) + 1, (1 << 32) + $0] }
    let through = Array(0...(laneCounts.max()! + 1))
    let limit = element.bits >= Int.bitWidth ? Int.max : (1 << (element.bits - 1)) - 1
    let counts =
        spanned
        ? through + laneCounts.map { 2 * $0 } + [1000] + beyond32Bits
        : through + [limit] + beyond32Bits.filter { $0 <= limit }
    return counts.reduce(into: []) { unique, count in
        if !unique.contains(count) {
            unique.append(count)
        }
    }
}

func integerConstantName(_ value: Int) -> String {
    value < 0 ? "Minus\(-value)" : "\(value)"
}

func integerConstants(_ values: [Int]) -> [ConstantValue] {
    values.map { ConstantValue(name: integerConstantName($0), literal: "\($0)") }
}

func integerSplats(for element: Element) -> [ConstantValue] {
    let signed = element.category == .signedInteger
    let upper = element.bits == 64 ? Int.max : (1 << (element.bits - (signed ? 1 : 0))) - 1
    let lower = signed ? (element.bits == 64 ? Int.min : -(1 << (element.bits - 1))) : 0
    let candidates =
        [0, 1, 15, 16, 26, 127, 128, 255, 256, 257, 65280, 65281]
        + (signed ? [-1, -16, -17, -128, -129] : [])
    let fitting = candidates.filter { (lower...upper).contains($0) }
    let extremes = [("Max", "H.Lane.max", upper), ("Min", "H.Lane.min", lower)]
        .filter { _, _, value in signed || value == upper }
        .filter { _, _, value in !fitting.contains(value) }
    return integerConstants(fitting)
        + extremes.map { ConstantValue(name: $0.0, literal: $0.1) }
}

let floatSplats = [
    ConstantValue(name: "Zero", literal: "0.0"),
    ConstantValue(name: "NegativeZero", literal: "-0.0"),
    ConstantValue(name: "One", literal: "1.0"),
    ConstantValue(name: "MinusOne", literal: "-1.0"),
    ConstantValue(name: "Two", literal: "2.0"),
    ConstantValue(name: "Half", literal: "0.5"),
    ConstantValue(name: "Four", literal: "4.0"),
    ConstantValue(name: "Quarter", literal: "0.25"),
    ConstantValue(name: "OnePointFive", literal: "1.5"),
    ConstantValue(name: "MinusTwoPointFive", literal: "-2.5"),
    ConstantValue(name: "Infinity", literal: ".infinity"),
    ConstantValue(name: "MinusInfinity", literal: "-.infinity"),
    ConstantValue(name: "NaN", literal: ".nan"),
    ConstantValue(name: "MinusNaN", literal: "-.nan"),
    ConstantValue(name: "PayloadNaN", literal: "H.Lane(nan: 1, signaling: false)"),
    ConstantValue(name: "SignalingNaN", literal: ".signalingNaN"),
    ConstantValue(name: "MinusSignalingNaN", literal: "-.signalingNaN"),
    ConstantValue(name: "LeastNonzero", literal: ".leastNonzeroMagnitude"),
    ConstantValue(name: "Greatest", literal: ".greatestFiniteMagnitude"),
]

let bfloatSplats = [
    ("Zero", 0x0000), ("NegativeZero", 0x8000), ("One", 0x3F80), ("MinusOne", 0xBF80),
    ("Two", 0x4000), ("Half", 0x3F00), ("Four", 0x4080), ("Quarter", 0x3E80),
    ("OnePointFive", 0x3FC0), ("MinusTwoPointFive", 0xC020), ("Infinity", 0x7F80),
    ("MinusInfinity", 0xFF80), ("NaN", 0x7FC0), ("MinusNaN", 0xFFC0), ("PayloadNaN", 0x7FC1),
    ("SignalingNaN", 0x7F81), ("MinusSignalingNaN", 0xFF81), ("LeastNonzero", 0x0001),
    ("Greatest", 0x7F7F),
].map { name, bits in
    ConstantValue(
        name: name,
        literal: "H.Lane(bitPattern: 0x\(String(format: "%04X", bits)))"
    )
}

func constantSplats(for element: Element) -> [ConstantValue] {
    switch element.category {
    case .float, .float16: return floatSplats
    case .bfloat16: return bfloatSplats
    case .unsignedInteger, .signedInteger: return integerSplats(for: element)
    }
}

/// The ops that combine adjacent lanes of one operand, whose constant operand has lanes that fold
/// to a different result than the same lanes do at runtime, which only a vector of different
/// lanes shows, with the issue the port has with it.
let adjacentLaneArithmeticOps: [String: KnownIssue] = [
    "pairwiseAddingBlocks": KnownIssue(
        comment:
            "The port adds a constant +inf and -inf pair in a vector, which the hardware does with the opposite NaN sign to Highway's folded scalar lanes",
        condition: "isAmd64 && SIMDTarget.targetName == \"EMU128\" && !assertionsAreEnabled"
    )
]

let foldedExponentOps: [String: KnownIssue] = [
    "multiplyingByPowerOf2": KnownIssue(
        comment:
            "Highway's emulated Set is opaque to the optimizer on Darwin, so it keeps its multiplications by the factors of a zero exponent, which quiet a signaling NaN that the port's folded ones return as it is",
        condition:
            "isDarwin && SIMDTarget.targetName == \"EMU128\" && !assertionsAreEnabled && value == 0"
    )
]

