func sveFirstTrueSettingIssue(_ result: String) -> KnownIssue {
    KnownIssue(
        comment:
            "Highway's SVE Not and ExclusiveNeither also set the predicate bits of the upper bytes of a lane wider than 8 bits, which SVE ignores, and its \(result), while the port builds a canonical predicate in each op and returns the documented result",
        condition: "SIMDTarget.targetName.hasPrefix(\"SVE\")"
    )
}

func firstTrueCompositionTests(of identifier: String) -> [String: [String]] {
    Dictionary(
        uniqueKeysWithValues: elements.filter { $0.bits > 8 }.map { element in
            let compositions = firstTrueCompositions(for: element).filter {
                $0.outer.identifier == identifier
            }
            return ("\(element.namespace)Reference", compositions.map(\.name))
        }
    )
}

let sveFirstTrueSettingGaps = [
    (
        "onlyFirstTrue",
        "SetOnlyFirst breaks after the first true byte, so it returns no true lane where the first true lane is not lane 0"
    ),
    (
        "beforeFirstTrue",
        "SetBeforeFirst breaks before the first true byte, so it returns only lane 0 where the first true lane is above lane 1 or no lane is true"
    ),
    (
        "atOrBeforeFirstTrue",
        "SetAtOrBeforeFirst breaks after the first true byte, so it returns only lane 0 where the first true lane is not lane 0 or no lane is true"
    ),
    (
        "atOrAfterFirstTrue",
        "SetAtOrAfterFirst negates SetBeforeFirst, which breaks before the first true byte, so it returns every lane but lane 0 where the first true lane is above lane 1 or no lane is true"
    ),
].map { identifier, result in
    (issue: sveFirstTrueSettingIssue(result), tests: firstTrueCompositionTests(of: identifier))
}

let knownGaps: [(issue: KnownIssue, tests: [String: [String]])] =
    [
        (linuxAvx2AndAvx512NaNSign, knownGapTests),
        (linuxAvx2AndAvx512IntermittentNaNSign, intermittentNaNSignTests),
        (linuxAvx512MaskedZeroSign, maskedZeroSignTests),
        (linuxAvx3SprFloat16OrderedComparison, float16OrderedComparisonTests),
        (darwinEmu128Folding, emu128FoldedConstantTests),
    ] + sveFirstTrueSettingGaps

func markingKnownGaps(_ tests: [String], suite: String) -> [String] {
    knownGaps.reduce(tests) { tests, gap in
        guard let names = gap.tests[suite] else { return tests }
        return tests.map { test in
            guard let name = names.first(where: { test.contains("func \($0)() {") }),
                let header = test.range(of: "func \(name)() {\n"), test.hasSuffix("\n}")
            else { return test }
            let body = test[header.upperBound...].dropLast(2)
            let options = gap.issue.isIntermittent.map { ",\nisIntermittent: \($0)" } ?? ""
            return """
                \(test[..<header.upperBound])withKnownIssue(
                "\(gap.issue.comment)"\(options)
                ) {
                \(body)
                } when: {
                \(gap.issue.condition)
                }
                }
                """
        }
    }
}

struct AlternatingConstant {
    let name: String
    let even: String
    let odd: String
}

let alternatingFloatConstants = [
    AlternatingConstant(name: "InfinityMinusInfinity", even: ".infinity", odd: "-.infinity"),
    AlternatingConstant(name: "MinusInfinityInfinity", even: "-.infinity", odd: ".infinity"),
]

func alternatingConstants(of op: Op, for element: Element) -> [AlternatingConstant] {
    element.category == .float && adjacentLaneArithmeticOps[op.identifier] != nil
        ? alternatingFloatConstants : []
}

func constantHelperName(
    of op: Op,
    parameter binding: Binding,
    guarded: Bool
) -> String {
    let name =
        "check\(uppercasedFirst(op.testIdentifier))Constant\(uppercasedFirst(binding.swiftName))"
    return guarded ? "\(name)BeforeGuardPage" : name
}

func constantHelperSignature(_ name: String, _ parameters: [String], _ type: String) -> String {
    let declarations = parameters.map { "_ \($0): \(type)" }.joined(separator: ", ")
    return "@inline(__always)\nprivate func \(name)(\(declarations)) {"
}

func isConstantVector(_ parameter: Parameter) -> Bool {
    switch parameter {
    case .vector, .shiftCounts, .fillVector, .otherwiseVector, .sourceVector, .signedSourceVector:
        return true
    default: return parameter.isPointerIndices
    }
}

func constantNamespace(of operand: Element, for element: Element) -> String {
    operand.suffix == element.suffix ? "H" : operand.namespace
}

func constantLane(of operand: Element, for element: Element) -> String {
    "\(constantNamespace(of: operand, for: element)).Lane"
}

func constantType(
    of parameter: Parameter,
    for element: Element,
    lane: String = "H.Lane"
)
    -> String
{
    switch parameter {
    case .flag: return "Bool"
    case .roundConstant: return "UInt8"
    case _ where parameter.isPointerIndices: return signedElement(of: element).swiftType
    case _ where isConstantVector(parameter): return lane
    default: return "Int"
    }
}

let indexSplats = integerConstants([0, 1])

func constantHelper(
    of op: Op,
    for element: Element,
    parameter index: Int,
    guarded: Bool,
    alternating: Bool = false
) -> String {
    let parameterBindings = bindings(of: op, for: element)
    let binding = parameterBindings[index]
    let isSplat = isConstantVector(op.parameters[index])
    let operand = operandElement(of: op.parameters[index], for: element, source: op.source)
    let name =
        constantHelperName(of: op, parameter: binding, guarded: guarded)
        + (alternating ? "Alternating" : "")
    let value = isSplat ? "value" : binding.swiftName
    let values = alternating ? ["even", "odd"] : [value]
    let blockLanes = (0..<operand.blockLaneCount).map { values[$0 % values.count] }
    let splat =
        op.parameters[index].isPointerIndices
        ? portCall("repeating", [value], on: operand.namespace)
        : alternating
            ? portCall(repeatingBlockName, blockLanes)
            : portCall("repeating", [value], on: constantNamespace(of: operand, for: element))
    let inputs = referenceInputs(
        of: op,
        for: element,
        test: name,
        inContract: true,
        guarded: guarded
    )
    .filter { $0.name != binding.swiftName }
    let calls = referenceCalls(
        of: op,
        for: element,
        pointer: referencePointer(of: op, guarded: guarded),
        destination: referenceDestination(of: op, guarded: guarded),
        referenceName: op.template != nil && op.parameters[index] == .shiftAmount
            ? templateReferenceName(of: op, for: element) : nil,
        constants: isSplat ? [binding.swiftName: (port: splat, reference: splat)] : [:]
    )
    let (declarations, statements) = referenceStatements(
        of: op,
        for: element,
        inputs: inputs,
        guarded: guarded,
        calls: calls
    )
    let highwaySplat = referenceResult(
        referenceCall(
            referenceFunctionName(alternating ? repeatingBlockName : "repeating", operand),
            (alternating ? blockLanes : [value]).map(operand.swiftScalarArgument)
        ),
        returning: .vector,
        for: operand,
        on: constantNamespace(of: operand, for: element)
    )
    let splatDeclarations =
        isSplat && !op.parameters[index].isPointerIndices
        ? [
            "mismatches.check(\(splat), \(highwaySplat), \"\(alternating ? repeatingBlockName : "repeating")\")"
        ] : []
    func operandName(_ operand: Binding) -> String {
        operand.swiftName == binding.swiftName && isSplat ? splat : operand.swiftName
    }
    let vectors = zip(parameterBindings, op.parameters)
        .filter {
            [.vector, .sourceVector].contains($0.1)
                || (op.unorderedNaNs?.isWidened == true && $0.1 == .outVector)
        }
        .map { operandName($0.0) }
    let sources = zip(parameterBindings, op.parameters)
        .filter { $0.1 == .sourceVector }
        .map { operandName($0.0) }
    let foldedParity =
        switch op.unorderedNaNs {
        case .widenedEven: ", parity: 0"
        case .widenedOdd: ", parity: 1"
        default: ""
        }
    let foldedNaNs =
        isSplat && op.parameters[index] == .sourceVector && op.unorderedNaNs?.isWidened == true
        ? sources.first { $0 != splat }.map {
            "!hasFoldedNaNs(multiplier: value, \($0)\(foldedParity))"
        } : nil
    let loopConditions = [
        unorderedNaNsCondition(of: op, for: element, vectors: vectors, sources: sources),
        foldedNaNs,
    ].compactMap { $0 }
    let describedValue =
        alternating
        ? "alternating \\(hex(even)), \\(hex(odd))"
        : isSplat ? "repeating \\(hex(value))" : "\\(\(value))"
    let suffix = guarded ? " before a guard page" : ""
    let knownIssue =
        alternating
        ? adjacentLaneArithmeticOps[op.identifier]
        : op.parameters[index] == .sourceVector && element.category == .float
            ? foldedExponentOps[op.identifier] : nil
    return referenceTestFunction(
        name,
        label: "\(op.testIdentifier) with \(binding.swiftName) \(describedValue)\(suffix)",
        for: element,
        inputs: inputs,
        declarations: splatDeclarations + declarations,
        signature: constantHelperSignature(
            name,
            values,
            constantType(
                of: op.parameters[index],
                for: element,
                lane: constantLane(of: operand, for: element)
            )
        ),
        loopCondition: loopConditions.isEmpty ? nil : loopConditions.joined(separator: " && "),
        recording: knownIssue.map {
            "mismatches.record(knownIssue: \"\($0.comment)\", when: \($0.condition))"
        } ?? "mismatches.record()",
        statements: statements
    )
}

func constantTest(
    _ name: String,
    enabledIf condition: String? = nil,
    disabling: [Disabling] = [],
    calls: [String]
) -> String {
    let attribute =
        disabling.isEmpty
        ? condition.map { "@Test(.enabled(if: \($0)))" } ?? "@Test"
        : testAttribute(disabling: disabling)
    return """
        \(attribute) func \(name)() {
        \(calls.joined(separator: "\n"))
        }
        """
}

func isOutOfContractSplat(_ value: ConstantValue, of op: Op, for element: Element) -> Bool {
    guard op.parameters.contains(.shiftCounts) else { return false }
    guard let count = Int(value.literal) else { return true }
    return !(0..<element.bits).contains(count)
}

func immediateConstantName(of op: Op) -> String {
    op.immediates.count == 1 ? uppercasedFirst(op.immediates[0].name) : "Immediates"
}

/// A helper that takes all immediates of an op, which only fold into the constant path of the op
/// when all of them are literals, and the tests that call it with every combination of literals.
func immediateConstantTests(
    of op: Op,
    for element: Element,
    checked: Bool = true
) -> [String] {
    let widest = element.at(width: X86Level.avx3.width)
    let form = checked ? "" : "Unchecked"
    let name =
        "check\(uppercasedFirst(op.testIdentifier))\(form)Constant\(immediateConstantName(of: op))"
    let parameterBindings = bindings(of: op, for: element)
    let names = op.immediates.map(\.name)
    let inputs = referenceInputs(of: op, for: element, test: name, inContract: true)
        .filter { !names.contains($0.name) }
    let calls = referenceCalls(
        of: op,
        for: element,
        pointer: referencePointer(of: op, guarded: false),
        checked: checked
    )
    let (declarations, statements) = referenceStatements(
        of: op,
        for: element,
        inputs: inputs,
        guarded: false,
        calls: calls
    )
    let parameters = zip(parameterBindings, op.parameters)
        .filter { $0.1 == .immediate }
        .map { "_ \($0.0.swiftName): Int" }
    let signature =
        "@inline(__always)\nprivate func \(name)(\(parameters.joined(separator: ", "))) {"
    let labels = op.immediates.map { "\($0.name) \\(\($0.name))" }
    var members = [
        referenceTestFunction(
            name,
            label:
                "\(op.testIdentifier)\(checked ? "" : " unchecked") with \(labels.joined(separator: ", "))",
            for: element,
            inputs: inputs,
            declarations: declarations,
            signature: signature,
            loopCondition: nil,
            statements: statements
        )
    ]
    var tuples: [[Int]] = [[]]
    for immediate in op.immediates {
        tuples = tuples.flatMap { tuple in immediate.values(for: widest).map { tuple + [$0] } }
    }
    for tuple in tuples {
        let suffix = tuple.map(String.init).joined()
        let conditions = zip(op.immediates, tuple).compactMap { immediate, value -> String? in
            if case .fixed = immediate.upperBound { return nil }
            let upper = immediate.upperBound.expression(for: element, laneCount: "H.laneCount")
            return "\(value) <= \(upper)"
        }
        members.append(
            constantTest(
                "\(op.testIdentifier)\(form)Constant\(immediateConstantName(of: op))\(suffix)",
                enabledIf: conditions.isEmpty ? nil : conditions.joined(separator: " && "),
                calls: ["\(name)(\(tuple.map(String.init).joined(separator: ", ")))"]
            )
        )
    }
    return members
}

func constantTests(of op: Op, for element: Element) -> [String] {
    let indices = constantParameters(of: op, for: element)
    let parameterBindings = bindings(of: op, for: element)
    var members: [String] = []

    for index in indices
    where !isConstantVector(op.parameters[index]) && op.parameters[index] != .immediate {
        let binding = parameterBindings[index]
        let values: [ConstantValue]
        switch op.parameters[index] {
        case .count:
            values = integerConstants(constantCounts(spanned: op.span != nil, for: element))
        case .laneAmount, .laneIndex:
            values = integerConstants(Array(0..<element.at(width: 64).laneCount))
        case .tupleIndex:
            values = integerConstants(Array(0..<tupleCount(of: op)))
        case .shiftAmount:
            values = integerConstants(Array(0..<element.bits))
        case .roundConstant:
            values = integerConstants(Array(0...255))
        case .flag:
            values = [
                ConstantValue(name: "False", literal: "false"),
                ConstantValue(name: "True", literal: "true"),
            ]
        default:
            fatalError("\(op.identifier) branches on \(binding.swiftName), which nothing covers")
        }
        for guarded in op.span == nil ? [false] : [false, true] {
            let helper = constantHelperName(of: op, parameter: binding, guarded: guarded)
            members.append(constantHelper(of: op, for: element, parameter: index, guarded: guarded))
            for value in values {
                let test = "\(op.testIdentifier)Constant\(uppercasedFirst(binding.swiftName))"
                let guardedTest = "\(test)\(value.name)\(guarded ? "BeforeGuardPage" : "")"
                members.append(
                    constantTest(
                        guardedTest,
                        enabledIf: op.parameters[index] == .laneAmount
                            || op.parameters[index] == .laneIndex
                            ? "\(value.literal) < H.laneCount" : nil,
                        calls: ["\(helper)(\(value.literal))"]
                    )
                )
            }
        }
    }

    if indices.contains(where: { op.parameters[$0] == .immediate }) {
        members += immediateConstantTests(of: op, for: element)
        members += immediateConstantTests(of: op, for: element, checked: false)
    }

    let splats = indices.filter {
        isConstantVector(op.parameters[$0]) && !op.parameters[$0].isPointerIndices
    }
    members += splats.map {
        constantHelper(of: op, for: element, parameter: $0, guarded: false)
    }
    func splatOperand(at index: Int) -> Element {
        operandElement(of: op.parameters[index], for: element, source: op.source)
    }
    var operands: [Element] = []
    for index in splats
    where !operands.contains(where: { $0.suffix == splatOperand(at: index).suffix }) {
        operands.append(splatOperand(at: index))
    }
    for (position, operand) in operands.enumerated() {
        let helpers = splats.filter { splatOperand(at: $0).suffix == operand.suffix }.map {
            constantHelperName(of: op, parameter: parameterBindings[$0], guarded: false)
        }
        let lane = constantLane(of: operand, for: element)
        let infix = position == 0 ? "" : operand.namespace
        for value in constantSplats(for: operand) {
            let literal = value.literal.replacingOccurrences(of: "H.Lane", with: lane)
            members.append(
                constantTest(
                    "\(op.testIdentifier)Constant\(infix)Splat\(value.name)",
                    disabling: laneCapabilityDisabling(of: op, for: element)
                        + (isOutOfContractSplat(value, of: op, for: element)
                            ? outOfContractDisabling(of: op) : []),
                    calls: helpers.map { "\($0)(\(literal))" }
                )
            )
        }
    }
    for index in splats {
        let alternating = alternatingConstants(of: op, for: element)
        guard !alternating.isEmpty else { break }
        let binding = parameterBindings[index]
        let helper = constantHelperName(of: op, parameter: binding, guarded: false) + "Alternating"
        let test = "\(op.identifier)Constant\(uppercasedFirst(binding.swiftName))Alternating"
        members.append(
            constantHelper(
                of: op,
                for: element,
                parameter: index,
                guarded: false,
                alternating: true
            )
        )
        for value in alternating {
            members.append(
                constantTest(
                    "\(test)\(value.name)",
                    calls: ["\(helper)(\(value.even), \(value.odd))"]
                )
            )
        }
    }
    for index in indices where op.parameters[index].isPointerIndices {
        let binding = parameterBindings[index]
        let helper = constantHelperName(of: op, parameter: binding, guarded: false)
        members.append(constantHelper(of: op, for: element, parameter: index, guarded: false))
        for value in indexSplats {
            members.append(
                constantTest(
                    "\(op.identifier)Constant\(uppercasedFirst(binding.swiftName))Splat\(value.name)",
                    calls: ["\(helper)(\(value.literal))"]
                )
            )
        }
    }
    return members
}

func wideningConstantTests(
    _ op: WideningOp,
    from narrow: Element,
    to wide: Element
) -> [String] {
    let identifiers = constantIdentifiers(
        in: constantSource(ofFunctionNamed: cWideningFunctionName(op, from: narrow, to: wide))
    )
    guard op.takesCount, identifiers.contains("count") else { return [] }
    var members: [String] = []
    for guarded in [false, true] {
        let name = "\(op.swiftName)From\(narrow.swiftType)\(guarded ? "BeforeGuardPage" : "")"
        let helper = "check\(uppercasedFirst(name))ConstantCount"
        members.append(
            wideningReferenceTest(op, from: narrow, to: wide, guarded: guarded, constantCount: true)
        )
        for value in integerConstants(constantCounts(spanned: true, for: wide)) {
            members.append(
                constantTest(
                    "\(name)ConstantCount\(value.name)",
                    calls: ["\(helper)(\(value.literal))"]
                )
            )
        }
    }
    return members
}

func generateConstantTestMembers(_ element: Element, by keys: Set<String>?) -> [SectionMember] {
    var members = testedOps(for: element, by: keys).map {
        SectionMember(
            section: $0.section,
            inside: markingKnownGaps(
                guarded(constantTests(of: $0, for: element), op: $0, in: element, testing: true),
                suite: "\(element.namespace)Constant"
            )
        )
    }
    members += wideningOps.map { op in
        let tests = testedWideningSources(of: op, for: element, by: keys).flatMap {
            wideningConstantTests(op, from: $0, to: element)
        }
        return SectionMember(section: op.section, inside: tests)
    }
    return members
}

