func write(_ contents: String, to path: String) throws {
    let url = URL(fileURLWithPath: path)
    try FileManager.default.createDirectory(
        at: url.deletingLastPathComponent(),
        withIntermediateDirectories: true
    )
    try contents.write(to: url, atomically: true, encoding: .utf8)
    FileHandle.standardError.write(Data("** Wrote \(path)\n".utf8))
}

struct SectionMember {
    let section: Section
    var inside: [String] = []
    var outside: [String] = []

    var lineCount: Int {
        (inside + outside).reduce(0) { $0 + $1.components(separatedBy: "\n").count + 1 }
    }

    var characterCount: Int {
        (inside + outside).reduce(0) { $0 + $1.utf8.count }
    }
}

let maximumUnformattedFileLines = 1000

let maximumUnformattedMembersFileLines = 2000

func balanced(_ members: [SectionMember]) -> [[SectionMember]] {
    let lines = members.reduce(0) { $0 + $1.lineCount }
    let count = max(
        1,
        (lines + maximumUnformattedMembersFileLines - 1) / maximumUnformattedMembersFileLines
    )
    let total = members.reduce(0) { $0 + $1.characterCount }
    var parts = [[SectionMember]](repeating: [], count: count)
    var before = 0
    for member in members {
        parts[(2 * before + member.characterCount) * count / (2 * total)].append(member)
        before += member.characterCount
    }
    return parts.filter { !$0.isEmpty }
}

func partitioned(_ members: [SectionMember]) -> [[SectionMember]] {
    var parts: [[SectionMember]] = [[]]
    var lines = 0
    for member in members {
        if lines + member.lineCount > maximumUnformattedFileLines, !parts[parts.count - 1].isEmpty {
            parts.append([])
            lines = 0
        }
        parts[parts.count - 1].append(member)
        lines += member.lineCount
    }
    return parts
}

func conditioned(_ source: String, on condition: String?) -> String {
    guard let condition else { return source }
    let notice = "\(generationNotice)\n\n"
    guard source.hasPrefix(notice) else { fatalError("A generated file lacks its notice") }
    return "\(notice)#if \(condition)\n\(source.dropFirst(notice.count))#endif\n"
}

func conditioned(_ source: String, for element: Element?) -> String {
    conditioned(source, on: element?.compilationCondition)
}

func entirelyGuardedCondition(of members: [SectionMember]) -> String? {
    let texts = members.flatMap { $0.inside + $0.outside }.filter { !$0.isEmpty }
    guard let condition = float16.compilationCondition, !texts.isEmpty,
        texts.allSatisfy({ $0.hasPrefix("#if \(condition)\n") })
    else { return nil }
    return condition
}

func sectionFile(
    _ members: [SectionMember],
    imports: String,
    extending type: String,
    for element: Element? = nil,
    testing: Bool = false
) -> String {
    var output = "\(generationNotice)\n\n\(imports)\n"
    let attribute = testing ? nil : element?.swiftAvailability
    let availability = attribute.map { "\($0)\n" } ?? ""
    var inside = members.flatMap(\.inside)
    if element?.swiftAvailability != nil {
        inside = inside.map { member in
            member.split(separator: "\n", omittingEmptySubsequences: false)
                .filter { $0.trimmingCharacters(in: .whitespaces) != spanAvailability }
                .joined(separator: "\n")
        }
    }
    if !inside.isEmpty {
        output +=
            "\n\(availability)extension \(type) {\n\(inside.joined(separator: "\n\n"))\n}\n"
    }
    let outside = members.flatMap(\.outside)
    if !outside.isEmpty {
        output += "\n\(outside.joined(separator: "\n\n"))\n"
    }
    return conditioned(
        output,
        on: element?.compilationCondition ?? entirelyGuardedCondition(of: members)
    )
}

func writeSections(
    _ members: [SectionMember],
    named name: String,
    in directory: String,
    imports: String,
    extending type: String,
    for element: Element? = nil,
    testing: Bool = false,
    balancing: Bool = false
) throws {
    func populated(_ section: Section) -> [SectionMember] {
        members.filter {
            $0.section == section && !($0.inside + $0.outside).allSatisfy(\.isEmpty)
        }
    }
    if balancing {
        let sectionMembers = Section.allCases.flatMap(populated)
        guard !sectionMembers.isEmpty else { return }
        for (index, part) in balanced(sectionMembers).enumerated() {
            try write(
                sectionFile(
                    part,
                    imports: imports,
                    extending: type,
                    for: element,
                    testing: testing
                ),
                to: "\(directory)/\(name)+Members\(index + 1).swift"
            )
        }
        return
    }
    for section in Section.allCases {
        let sectionMembers = populated(section)
        guard !sectionMembers.isEmpty else { continue }
        let parts = partitioned(sectionMembers)
        for (index, part) in parts.enumerated() {
            let number = parts.count == 1 ? "" : String(index + 1)
            try write(
                sectionFile(
                    part,
                    imports: imports,
                    extending: type,
                    for: element,
                    testing: testing
                ),
                to: "\(directory)/\(name)+\(section.rawValue)\(number).swift"
            )
        }
    }
}

struct TestSelection {
    let keptTests: Int
    let tests: Int
    let keptOps: Int
    let ops: Int
    let unattributableTests: Int

    var summary: String {
        "kept \(keptTests)/\(tests) tests (\(unattributableTests) unattributable) and "
            + "\(keptOps)/\(ops) ops"
    }
}

func testCount(of element: Element, by keys: Set<String>?) -> Int {
    let members =
        generateReferenceTestMembers(element, by: keys)
        + generateCodegenTestMembers(element, by: keys)
        + generateConstantTestMembers(element, by: keys)
    let suites = [
        generateReferenceTests(element), generateCodegenTests(element),
        generateConstantTests(element),
    ]
    return (suites + members.flatMap(\.inside)).reduce(0) {
        $0 + $1.components(separatedBy: "@Test").count - 1
    }
}

func testSelection(of element: Element, by keys: Set<String>) -> TestSelection {
    let keysOfOps = codegenKeysOfOps(for: element)
    return TestSelection(
        keptTests: testCount(of: element, by: keys),
        tests: testCount(of: element, by: nil),
        keptOps: keysOfOps.filter { isTested($0, by: keys) }.count,
        ops: keysOfOps.count,
        unattributableTests: testCount(of: element, by: [])
    )
}

